INSERT INTO `mbti_personality` VALUES ('ENFJ', '教育家', '热忱、易感应及负责任的--具能鼓励他人的领导风格。对别人所想或希求会表达真正关切且切实用心去处理。能怡然且技巧性地带领团体讨论或演示文稿提案。爱交际、受欢迎及富同情心。对称许及批评很在意。喜欢带引别人且能使别人或团体发挥潜能。', '广告客户管理,杂志编辑,公司培训师,电视制片人,市场专员,作家,社会工作者,人力资源管理');
INSERT INTO `mbti_personality` VALUES ('ENFP', '竞选者', '充满热忱、活力充沛、聪明的、富想象力的，视生命充满机会但期能得自他人肯定与支持。几乎能达成所有有兴趣的事。对难题很快就有对策并能对有困难的人施予援手。依赖能改善的能力而无须预作规划准备。为达目的常能找出强制自己为之的理由。即兴执行者。', '广告客户管理,管理咨询顾问,演员,平面设计师,艺术指导,公司团队培训师,心理学家,人力资源管理');
INSERT INTO `mbti_personality` VALUES ('ENTJ', '指挥官', '坦诚、具决策力的活动领导者。长于发展与实施广泛的系统以解决组织的问题。专精于具内涵与智能的谈话如对公众演讲。乐于经常吸收新知且能广开信息管道。易生过度自信，会强于表达自已创见。喜于长程策划及目标设定', '公司首席执行官,管理咨询顾问,政治家,房产开发商,教育咨询顾问,投资顾问,法官');
INSERT INTO `mbti_personality` VALUES ('ENTP', '辩论家', '反应快、聪明、长于多样事务。具激励伙伴、敏捷及直言讳专长。会为了有趣对问题的两面加予争辩。对解决新及挑战性的问题富有策略，但会轻忽或厌烦经常的任务与细节。兴趣多元，易倾向于转移至新生的兴趣。对所想要的会有技巧地找出逻辑的理由。长于看清础他人，有智能去解决新或有挑战的问题', '企业家,投资银行家,广告创意总监,市场管理咨询顾问,文案,广播/电视主持人,演员,大学校长');
INSERT INTO `mbti_personality` VALUES ('ESFJ', '执政官', '诚挚、爱说话、合作性高、受欢迎、光明正大的—天生的合作者及活跃的组织成员。重和谐且长于创造和谐。常作对他人有益事务。给予鼓励及称许会有更佳工作成效。最有兴趣于会直接及有形影响人们生活的事务。喜欢与他人共事去精确且准时地完成工作。', '房地产经纪人,零售商,护士,理货员/采购,按摩师,运动教练,饮食业管理,旅游管理');
INSERT INTO `mbti_personality` VALUES ('ESFP', '表演者', '外向、和善、接受性、乐于分享喜乐予他人。喜欢与他人一起行动且促成事件发生，在学习时亦然。知晓事件未来的发展并会热列参与。最擅长于人际相处能力及具备完备常识，很有弹性能立即适应他人与环境。对生命、人、物质享受的热爱者。', '幼教老师,公关专员,职业策划咨询师,旅游管理/导游,促销员,演员,海洋生物学家,销售');
INSERT INTO `mbti_personality` VALUES ('ESTJ', '总经理', '务实、真实、事实倾向，具企业或技术天份。不喜欢抽象理论；最喜欢学习可立即运用事理。喜好组织与管理活动且专注以最有效率方式行事以达致成效。具决断力、关注细节且很快作出决策—优秀行政者。会忽略他人感受。喜作领导者或企业主管。', '公司首席执行官,军官,预算分析师,药剂师,房地产经纪人,保险经纪人,教师（贸易/工商类）,物业管理');
INSERT INTO `mbti_personality` VALUES ('ESTP', '企业家', '擅长现场实时解决问题—解决问题者。喜欢办事并乐于其中及过程。倾向于喜好技术事务及运动，交结同好友人。具适应性、容忍度、务实性；投注心力于会很快具成效工作。不喜欢冗长概念的解释及理论。最专精于可操作、处理、分解或组合的真实事务。', '企业家,经纪人,保险经纪人,土木工程师,旅游管理,职业运动员/教练,电子游戏开发员,房产开发商');
INSERT INTO `mbti_personality` VALUES ('INFJ', '提倡者', '因为坚忍、创意及必须达成的意图而能成功。会在工作中投注最大的努力。默默强力的、诚挚的及用心的关切他人。因坚守原则而受敬重。提出造福大众利益的明确远景而为人所尊敬与追随。追求创见、关系及物质财物的意义及关联。想了解什么能激励别人及对他人具洞察力。光明正大且坚信其价值观。有组织且果断地履行其愿景。', '特殊教育教师,建筑设计师,培训经理/培训师,职业策划咨询顾问,心理咨询师,网站编辑,作家,仲裁人');
INSERT INTO `mbti_personality` VALUES ('INFP', '调停者', '安静观察者，具理想性与对其价值观及重要之人具忠诚心。希外在生活形态与内在价值观相吻合。具好奇心且很快能看出机会所在。常担负开发创意的触媒者。除非价值观受侵犯，行事会具弹性、适应力高且承受力强。具想了解及发展他人潜能的企图。想作太多且作事全神贯注。对所处境遇及拥有不太在意。具适应力、有弹性除非价值观受到威胁。', '心理学家,人力资源管理,翻译,大学教师（人文学科）,社会工作者,图书管理员,服装设计师,编辑/网站设计师');
INSERT INTO `mbti_personality` VALUES ('INTJ', '建筑师', '具强大动力与本意来达成目的与创意—固执顽固者。有宏大的愿景且能快速在众多外界事件中找出有意义的模范。对所承负职务，具良好能力于策划工作并完成。具怀疑心、挑剔性、独立性、果决，对专业水准及绩效要求高。', '首席财政执行官,知识产权律师,设计工程师,精神分析师,心脏病专家,媒体策划,网络管理员,建筑师');
INSERT INTO `mbti_personality` VALUES ('INTP', '逻辑学家', '安静、自持、弹性及具适应力。特别喜爱追求理论与科学事理。习于以逻辑及分析来解决问题—问题解决者。最有兴趣于创意事务及特定工作，对聚会与闲聊无大兴趣。追求可发挥个人强烈兴趣的生涯。追求发展对有兴趣事务的逻辑解释。', '软件设计师,风险投资家,法律仲裁人,金融分析师,大学教师（经济学）,音乐家,知识产权律师,网站设计师');
INSERT INTO `mbti_personality` VALUES ('ISFJ', '守卫者', '安静、和善、负责任且有良心。行事尽责投入。安定性高，常居项目工作或团体之安定力量。愿投入、吃苦及力求精确。兴趣通常不在于科技方面。对细节事务有耐心。忠诚、考虑周到、知性且会关切他人感受。致力于创构有序及和谐的工作与家庭环境。', '内科医生,营养师,图书/档案管理员,室内装潢设计师,客户服务专员,记账员,特殊教育教师,酒店管理');
INSERT INTO `mbti_personality` VALUES ('ISFP', '探险家', '羞怯的、安宁和善地、敏感的、亲切的、且行事谦虚。喜于避开争论，不对他人强加已见或价值观。无意于领导却常是忠诚的追随者。办事不急躁，安于现状无意于以过度的急切或努力破坏现况，且非成果导向。喜欢有自有的空间及照自订的时程办事。', '室内装潢设计师,按摩师,客户服务专员,服装设计师,厨师,护士,牙医,旅游管理');
INSERT INTO `mbti_personality` VALUES ('ISTJ', '物流师', '严肃、安静、藉由集中心志与全力投入、及可被信赖获致成功。行事务实、有序、实际、逻辑、真实及可信赖。十分留意且乐于任何事（工作、居家、生活均有良好组织及有序）。负责任。照设定成效来作出决策且不畏阻挠与闲言会坚定为之。重视传统与忠诚。传统性的思考者或经理。', '首席信息系统执行官,天文学家,数据库管理,会计,房地产经纪人,侦探,行政管理,信用分析师');
INSERT INTO `mbti_personality` VALUES ('ISTP', '鉴赏家', '冷静旁观者—安静、预留余地、弹性及会以无偏见的好奇心与未预期原始的幽默观察与分析。有兴趣于探索原因及效果，技术事件是为何及如何运作且使用逻辑的原理组构事实、重视效能。擅长于掌握问题核心及找出解决方式。分析成事的缘由且能实时由大量资料中找出实际问题的核心。', '信息服务业经理,计算机程序员,警官,软件开发员,律师助理,消防员,私人侦探,药剂师');
