INSERT INTO `t_2025_multi_area_job_info` VALUES (101, '软件测试', '重庆科满福人力资源服务有限公司', '6月28日', '7000-10000元', '重庆-南岸区', '企业服务', '20-99人', NULL, 'CCL1487604860J40925666204', '【岗位职责】：<br>1、软件测试岗位职责 <br>2、接受测试任务，进行需求分析<br>3、按照测试计划搭建测试环境，并保证测试环境的可靠性<br>4、按照测试计划编亏测试用例，保证测试用例合理有效<br>5、按照测试用例执行测试，及时发现缺陷，并使用工具进行管理缺陷<br>6、编写和提交测试报告，保证测试进度按计划完成<br>7、参与审核其他测试工程师的测试用例和报告<br>8、学习公司已有方案和推广使用新的测试技术和工具<br>', NULL, 'https://www.zhaopin.com/jobdetail/CCL1487604860J40925666204.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (102, '实施工程师', '永洪科技', '7月29日', '5000-10000元', '上海-普陀区', '计算机软件,IT服务,运营商/增值服务,互联网', '300-499人', 'D轮及以上', 'CC466596620J40936808904', '1、了解并参与项目整个建设周期工作(包括产品部署及培训，项目需求调研、方案汇报、开发、测试上线、验收等)；<br>2、与客户进行技术交流并编写技术方案，了解客户业务分析场景，并提供相应的解决方案和技术建议；<br>3、收集客户提出的关于产品改造、优化的需求，并反馈给产品部和研发部一起评审，跟进并把控开发进度；<br>4、配合项目经理做好项目文档编写，处理项目执行过程中各环节遇到的问题，确保项目顺利交付；<br>任职要求：<br>1、具备一定数学基础，逻辑思维能力突出，使用过Oracle、SqlServer等数据库进行数据收集、建模、分析相关完整方法者优先；<br>2、了解java编程语言，能够看懂代码，有java开发经验优先；<br>3、使用过linux环境，了解常用的linux命令的经验优先；<br>4、不错的沟通能力，富有责任感、执行力强，有较强的学习能力，具备一定的抗压能力；<br>5、统招本科及以上学历，计算机或应用数学相关专业，一本院校毕业优先。', '北京永洪商智科技有限公司（简称永洪科技），是一家致力于打造全球数据技术厂商，依托自主知识产权的一站式大数据平台形成完善的产品及服务体系，具备从数据应用方案咨询、数据治理、数据可视化分析、数字孪生、AIGC智能分析、数据深度应用到数据平台实施运维服务的端到端大数据价值服务能力，连续六届获得中国BI商业智能领域首名，也是专精特新“小巨人”企业。永洪科技的管理团队拥有世界百强企业或世界大数据企业10年以上从业经历，曾多次获得国际大奖，包括Java One大奖、软件界的奥斯卡大奖JDJ读者奖等。永洪科技的BI拥有分布式计算、分布式存储、分布式通信、云计算、数据处理、数据展现等多项技术专利。产品足以比肩国际同类产品，并在高性能、易用性、AI深度分析等方面形成独特优势。2022年，为了满足业务用户商业分析时代的数据应用需求，构建了更为全面的产品体系，即以永洪社区为基础，“免费全家桶”产品组合为支柱，“付费全家桶”产品组合为核心的模式，服务不同规模、类型、需求的客户。对于缺乏预算的小企业或者是大部门、以及有数据分析需求的个人，可以使用“免费全家桶”产品组合，即vividime Desktop Basic、X+Viewer、永洪云，完成数据分析，业务洞察。当企业逐步发展、有一定预算后，则可以升级为vividime Desktop Professional、永洪云独享版，延伸出更多数据应用场景，进一步提升效率和专业度。同时企业也可部署企业级BI平台vividime X-Suite/Z-Suite，实现更为丰富的企业级数据管理。2012年成立至今，已完成腾讯领投的2亿元C轮融资，业绩保持300%~500%的年增长率，拥有来自国内外一流大学与技术公司的研发队伍。除北京总部外，在上海、深圳、成都、大连等地设有分公司，并于2018年成功进军海外市场。秉承“以卓越的数据技术和客户服务为客户创造价值，长期与客户共同成长”的使命，凭借产品技术的创新及坚实的服务，永洪科技得到了广泛认可，获得了包括中国BI大数据领域首位企业奖、中国优质BI方案提供商、中国明日之星等大数据与人工智能领域的众多荣誉。永洪科技拥有1000+家合作伙伴，包括腾讯、华为、用友等战略合作伙伴；10000+家企业客户，包括中国银行、招商银行、华泰证券、国家电网、中国移动、家乐福、美的、格力、北京汽车、科技部、海关总署、中国人民警察大学等，涵盖了金融、制造、零售、能源、政府、教育等近20个中国支柱产业及新经济产业，并在金融、制造领域的市场占有率首位。', 'https://www.zhaopin.com/jobdetail/CC466596620J40936808904.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (103, '软件测试', '安徽雅云晖智能科技有限公司', '6月15日', '4000-6000元', '合肥-庐阳区', '计算机软件', '20-99人', NULL, 'CCL1483063630J40591243907', '职位描述', NULL, 'https://www.zhaopin.com/jobdetail/CCL1483063630J40591243907.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (104, '技术支持工程师', '突破电气', '7月25日', '1-2万', '天津-东丽区', '通信/网络设备,通信/网络设备', '100-299人', '未融资', 'CC120064580J40418252316', '国际技术支持工程师（工作地点：天津）<br>1.负责海外市场业务的售前、售中和售后技术支持工作，包括提供技术咨询、方案编写、产品演示、围绕客户与渠道合作伙伴进行技术培训等。<br>2.组织或配合线上、线下技术展示、宣传，负责技术讲解等；<br>3.负责订单编制与审核相关工作；<br>4.提供交付技术培训、交付现场指导、产品调试等；<br>5.提供故障维修等售后技术支持，配合处理客户投诉，并及时解决问题；<br>6.收集竞品产品和技术信息，提供改进意见。<br>任职要求：<br>1.本科及以上学历，机械电子、机电一体化、电气自动化等相关专业；英语口语可作为工作语言。<br>2.经验不限，优秀的应届毕业生也可以。有海外留学经历优先；有工业产品海外技术支持经验优先；<br>3.了解CAD、solidworks等绘图及设计软件。<br>4.沟通协调能力、抗压能力强，能适应短期国外出差。<br> <br>★ International FAE (Tianjin)<br>1. Responsible for the pre-sale, sale and after-sales technical support of overseas market business, including providing technical consultation, program writing, product demonstration, technical training around customers and channel partners, etc.<br>2. Organize or cooperate with online and offline technology display and publicity, and be responsible for technical explanation;<br>3. Responsible for order preparation and review;<br>4. Provide delivery technical training, delivery field guidance, product debugging, etc.;<br>5. Provide after-sales technical support such as fault maintenance, cooperate with customers to deal with complaints, and solve problems in time;<br>6. Collect product and technical information of competitors and provide suggestions for improvement.<br>Job Requirements:<br>1. Bachelor degree or above, major in mechatronics, mechatronics, electrical automation or related; Foreign preferred, Native English ;<br>2.3 years of industrial products overseas technical support experience;<br>3. Proficient in CAD, solidworks and other drawing and design software;<br>4. Communication and coordination skills, strong ability to work under pressure, can adapt to short-term business trips.', '突破电气—25年国际领先的工业级智能弹性配电产品制造商与服务商，国家高新技术企业。智能终端行业国家与行业标准制定者、行业领军企业。可移动式快速部署智能数据中心、数据中心智能母线系统、智能电源终端、智能PDU、特种连接器的研发、制造、销售和服务提供商。华为、百度、阿里、腾讯、艾默生、伊顿、施耐德、ABB等客户和合作伙伴。研发、生产基地坐落天津滨海高新区，紧临京津高速公路、天津机场和天津港。公司网址：wwww.toppdu.com', 'https://www.zhaopin.com/jobdetail/CC120064580J40418252316.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (105, '技术支持工程师', '汉恒生物科技(上海)有限公司', '7月7日', '9000-12000元', '上海-浦东新区', '医药制造,学术/科研', '100-299人', '未融资', 'CC596124220J40790626712', '岗位职责：<br>1、熟练掌握公司产品技术和应用要点，协助公司业务部门提供售前/售中/售后技术咨询；<br>2、协助销售人员和客户进行各个层面（业务、技术实现、产品）的技术交流和解答；<br>3、通过邮件、电话等处理客户产品方面咨询、投诉、疑难解答，解决客户常见的相关技术问题；<br>4、配合销售人员对客户进行现场技术指导；<br>5、参与市场推广活动，协助主持技术讲座、展会的技术咨询等；<br>6、与用户交流，收集、分析用户需求信息，整理相关技术信息为用户提供最优技术方案，协助销售渠道建设和维护；<br>7、负责公司内部产品技术相关培训；<br>8、收集产品信息和用户的反馈，及时反馈公司内部，协助整理和编写公司有关数据资料；<br>9、完成上级领导交办的其他事项。<br>任职要求：<br>1、分子生物学、遗传学、细胞生物学、免疫学等相关专业，硕士及以上学历；相关行业经验优异本科生也可考虑；<br>2、实验技能经验丰富， 做过动物实验（尤其神经领域），有1年以上相关工作经验，有过病毒包装经验及技术背景者优先；<br>3、具备较好的沟通表达能力，较强的学习能力、独立分析问题和解决问题的能力；<br>4、具备较强的责任感、团队协作精神及抗压能力；<br>5、英语读写能力良好，能熟练查阅专业文献、产品技术资料等；<br>6、熟悉office等办公软件及其他生物专业软件。', '以“汉恒”之名，扬帆起航，驰骋生命科学领域！汉恒之名取自汉文帝刘恒。文景之治，中国之兴。文帝性情宽厚，顺天应人，与人民休养，为苍生立命。汉恒人不忘文帝之精神，立志耕耘于中国之生命科学与医学领域。汉恒努力推动基因治疗技术的发展和临床转化。汉恒人，愿以绵薄力，化作脊梁身!汉恒生物创办于2010年，是一家专注于基因技术研发与应用转化的高新技术企业，坐落于张江高科技园区。汉恒一直致力于基因载体的研发与生产，我们的核心优势产品有慢病毒、腺病毒和腺相关病毒；同时聚焦热点专题，服务内容包括自噬流研究工具、基于病毒载体的crispr基因编辑工具、非编码RNA以及荧光素酶实验等。其中我们自主研发的自噬LC3双标腺病毒是自噬领域的金牌研究工具。目前为止病毒产品累计发刊6000+篇，近50%期刊IF＞5；其中汉恒生物自噬病毒产品累计发表学术期刊超1000篇，平均IF>6.3，包括Cell、Cancer Cell、nature medicine、Autophagy、Circulation等期刊。未来我们将以核心基因技术为基础，更加注重技术应用于临床转化。汉恒生物，更好的基因科技。', 'https://www.zhaopin.com/jobdetail/CC596124220J40790626712.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (106, '前端开发', '株式会社トップクラウド', '11月29日', '2-3万', '成都-武侯区', '计算机软件,IT服务,互联网', '20-99人', '未融资', 'CZ830846060J00257044205', '技能要求:  <br>日本语能力2级，半年以上软件开发经验，赴日工作<br>', '株式会社トップクラウド是一家以软件开发业务为主的日本企业，总部位于日本的神奈川县横滨市（横滨市有被称为日本乃至东亚最大的中华街）。以软件开发、软件委托开发和互连网服务为主要业务的高科技企业，在金融领域保险、证券、银行、物流等领域，拥有经验丰富团队，与日本各地区的多家企业达成了友好合作关系。本公司提倡以人为本的经营理念，尊重人，培养人、努力创造相互信赖相互团结的职场氛围。现诚招有识之士加盟我们，我们愿为您提供优厚的待遇和施展才华的空间。※重要事项：本公司是日本驻地企业，直接招聘，可为您免费办理赴日签证手续。株式会社トップクラウド期待您的加盟,共同发展！人事邮箱：soumu@topcloud-japan.com公司电话：（81）045- 298-3590欢迎垂询。公司网站：http://www.topcloud-japan.com', 'https://www.zhaopin.com/jobdetail/CZ830846060J00257044205.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (107, '软件测试', '集镁科技集团有限公司', '7月17日', '5000-7000元', '沈阳-浑南区', '计算机软件,云计算/大数据,IT服务,计算机软件', '100-299人', '未融资', 'CC204062710J40771580614', '1.编写测试用例、测试计划、编写自动化测试脚本（CAP/python/shell/java等）、执行测试活动、输出测试报告；<br>2.利用成熟工具搭建本公司自动化测试平台；  3.掌握至少一种测试工具，如loadRunner\\\\postman\\\\自动化测试框架selenium等  <br>4.全面负责性能测试、压力测试、功能测试、兼容性测试、安全测试、负载测试、容量测试等；  <br>5.产品手册编写、产品说明书编写、产品演示等工作；  <br>6.有git/CI/jenkins/docker/K8SNUE/django/echart等工具经验优先；  <br>7.加分项：等保安全评估、安全设计经验；  <br>', '集镁科技集团是国内资产和信息管理领域的领军企业。公司自成立以来，始终秉承“守正创新、行稳致远”的企业精神和“您的信任，我们的责任”的客户服务理念，透过档案信息管理、数据资产管理、安全存储与递送、数字化与数字转型、信息销毁与IT资产处置、生态与创新业务等产品和服务，为机构和个人提供全生命周期物理和数字资产管理解决方案，帮助客户保护关键和敏感信息和重要资产，识别和发现信息的商业与文化价值，推动信息合规治理，加快产业和生活数字化转型，构建起面向未来的信息竞争优势和智能互联的数字化生态。集团是中国档案学会理事单位、国家高新技术企业、瞪羚企业、吉林大学国家重点实验室共建单位、辽宁省研究生联合培养基地和辽宁省产业技术研究院数字转型产业技术联合创新中心依托单位等。集团拥有自有知识产权的MINDrive®DBP数字业务平台、通过安全和保密认证的工作流程、博士专家领衔的科研团队以及位于沈阳、长春、哈尔滨等连锁运营的信息科学园（基地）产业发展载体。服务客户涵盖金融保险、医疗健康、公共服务、房地产、工程建设、能源矿产、制药与生命科学等多个行业，长期合作的客户中既有位列财富500强的跨国公司，也有本地中小型企业，有政府行政部门，也有医疗和专业服务机构……集镁科技已成为众多机构与个人长期信赖的合作伙伴。面向未来，集团坚持开源和集约理念，依托集政产学研用为一体的集镁信息科学园，扎实推进企业稳健可持续发展，培育科研、生产与研发有机融合的特色产业集群，带动信息管理领域的学术研究、技术创新和产业生态协同发展，为产业链和产业生态发展贡献集镁解决方案。同时，集团积极履行环境社会治理责任，从理念到行动践行企业公民责任，让公司和人、社区与环境实现和谐共生、可持续发展。', 'https://www.zhaopin.com/jobdetail/CC204062710J40771580614.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (108, '科研人员', '重庆大学溧阳智慧城市研究院', '1月25日', '1.6-2.5万', '常州-溧阳市', '学术/科研', '20-99人', '不需要融资', 'CCL1372062360J40544269914', '智慧环保中心以重庆大学溧阳智慧城市研究院副院长、重庆市首批创新领军人才翟俊教授为中心负责人，国家级人才耿金菊教授为首席科学家，拥有一批国内外高水平人才和先进的科研仪器装备及产业化平台，孵化的公司已经获评国家高新技术企业。现根据发展需要，现公开招聘全职科研人员，公告如下：', '重庆大学溧阳智慧城市研究院（简称“研究院”）是由重庆大学和溧阳市人民政府联合举办的事业单位，于2021年3月正式注册成立。研究院以人才高地、科研重地、产业集群策源地为使命，不断整合优质创新要素，不断促进“政、产、学、研、用”深度融合，推动智慧城市产业链经济的全面发展。在智慧城市、土木建筑、环境与生态、城市规划、管理科学与工程、智慧能源、现代物理及与智慧城市相关的学科方向，建设成为“学术研究的热土，人才培养的高地，产业孵化的基地，国内外合作的平台”，产出国际一流的成果。研究院采用“校、院、企”三位一体的创新机制，促进产学研无缝衔接，将科技创新与经济社会发展密切融合，破解高校科技成果产业化难题，也为地方经济发展提供创新驱动引擎，更为科研人员践行“科学技术是第一生产力”，实现科技创新价值提供优秀平台。研究院的建设得到重庆大学、常州市、溧阳市的高度重视和全力支持，形成校地各方力量相向而行，多种资源共振叠加的良好发展态势，实现当年签约，当年即规模化运营。研究院组建了由周绪红、杨永斌、田村幸雄、王翔宇4名院士领衔的专兼职高水平人才团队，现有专兼职骨干专家37人，包括国家级人才15人、省部级人才10人，全职博士28人；已入驻博硕士研究生近100人。研究院建院元年（2021年）即承接包括省部级重点科技项目在内的各类科研、工程设计、咨询服务项目共计15项，合同金额2500余万元。研究院也与“上上电缆”、“宁德时代（江苏公司）”等知名企业一起获得溧阳市最高奖“特别贡献奖（2021年）”。研究院已经建成了“香山路”过渡院区，现有建筑面积1.37万平方米。院区共有九栋大楼，包含行政楼、研究中心大楼、学生宿舍、餐厅及活动中心。建设了较为完备的后勤保障体系和学生活动设施，为教职员工和研究生工作学习和生活提供了舒适优美的环境。研究院正式院区正在建设中，总体规划用地面积1000亩，一期建设用地300亩，建筑面积20万平米，拥有完备优越且环境优美的科研和人才培养场地、设施和生活保障条件。正式院区（一期）预计2023年建成并投入使用。现拥有平台基地：国家级博士后科研工作站、江苏省博士后创新实践基地。拥有国家级平台：输配电装备及系统安全与新技术国家重点实验室溧阳分中心和科技部低碳绿色建筑国际联合中心溧阳分中心。', 'https://www.zhaopin.com/jobdetail/CCL1372062360J40544269914.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (109, '科研人员', '大湾区大学(筹)', '1月12日', '3-3.5万·13薪', '东莞-None', '学校/学历教育,学校/学历教育', '20-99人', '不需要融资', 'CCL1368679040J40693232207', '【诚聘博后】电磁成像与感知、电磁兼容、电磁无损检测方向 | 大湾区大学（筹）高原课题组与中国科学技术大学刘发林教授联合招收博士后<br>课题组介绍<br>高原，大湾区大学（筹）信息科学技术学院助理教授，独立PI。博士期间研究微波与毫米波技术在工业无损检测及医学诊断方面的应用，在IEEE权威期刊及会议发表论文十余篇，获得IEEE奖学金（仪器与测量学会）一项，会议论文奖（IEEE I2MTC，IEEE APS）多项。博士毕业后加入Apple从事电磁设计工作，对电磁技术的研究及产业落地有深入理解。此外，曾两次获得IEEE Transactions on Instrumentation and Measurement杰出审稿人奖（Outstanding Reviewer Award）,受邀担任该期刊Associate Editor, 并获Outstanding Associate Editor（2021）奖项。<br>联合招收导师介绍<br>刘发林, 中国科学技术大学信息科学技术学院电子工程与信息科学系和微电子学院教授，博士生导师。1985年获清华大学无线电系工学学士学位，后又分别于1988年和2004年获中国科学技术大学电磁场与微波技术硕士和博士学位。1988年留在中国科大任教至今。主持或参加包括国家自然科学基金、863计划、973计划、国家科技重大专项、中科院知识创新工程等项目近20项，涉及毫米波雷达前端、毫米波仪器频率扩展、卫星组网通信、微波毫米波器件、计算电磁学、射频功放数字预失真技术等。曾获得1992年国家科技进步二等奖、1998年中国科学院科技进步一等奖等多项奖励。2001年入选教育部优秀青年教师资助计划。发表学术刊物论文100余篇，会议论文80余篇。其中SCIE、EI索引100余篇。已培养博士后9名，博士毕业生18名，硕士毕业生50余名。目前的研究兴趣集中在射频功放DPD技术和SAR雷达成像算法。现为中国电子学会微波分会副主任委员，《微波学报》副主编。<br>招聘方向<br>电磁成像与感知、电磁兼容、电磁无损检测<br>招聘岗位<br>博士后2名<br>岗位职责<br>1. 根据PI指导开展电磁成像与感知、微波无损检测、电磁兼容、及AI驱动的应用电磁技术等方向相关研究；<br>2. 独立或协助PI完成相关科研项目的申报、实施与结题等工作，输出高质量论文等成果；<br>3. 协助PI完成实验室建设、设备采购维护、研究生培养等实验室管理相关工作。<br>应聘条件<br>1. 具有或即将获得电气电子信息类专业博士学位，有以下经验优先考虑：电磁成像，微波工程与天线设计，与AI结合的应用电磁技术；<br>2. 具备良好的独立科研能力和创新能力，已有较好的科研学术成果；<br>3. 年龄一般不超过35周岁且获得博士学位不超过3年，身体健康状况良好，能够适应科研工作要求；<br>4. 具备良好的学术道德和职业操守，追求上进，自驱力强，具有高度责任心、良好沟通能力和团队合作精神。<br>薪酬待遇<br>1. 聘期2年。A类博士后综合年薪不低于45万元（含地方政府资助，下同），B类博士后综合年薪不低于40万元。入选广东省海外博士后人才支持项目，综合年薪不低于60万元。根据科研工作业绩表现，课题组提供相应的科研绩效奖励。2. 除综合年薪外，学校高标准缴纳社会保险和住房公积金，发放租房补贴。<br>3. 提供工作开展所需科研条件及国内外学术交流机会。<br>4. 支持博士后作为负责人申请国家自然科学基金、中国博士后科学基金以及省、市各级科研项目；获得中国博士后科学基金资助项目或省级以上重点博士后资助项目，地方政府按1∶1给予配套资助。<br>5. 出站后留莞工作的，东莞市给予50万元生活补助。入选广东省海外博士后人才支持项目，出站后留粤工作的，广东省给予40万元住房补贴。<br>6. 支持博士后申报东莞市特色人才，享受购房补贴、租房补贴、生活补助、科技成果转化贡献奖励、医疗保障、创业扶持、境外人才个人所得税优惠、优才卡服务等。<br>7. 工作地点松山湖科学城，享受带薪年假、健康体检和校内餐厅等福利待遇，学校按属地政策协助解决子女入园入学。<br>8. 对于优秀的出站博士后积极推荐申请校内相关岗位。<br>9. 博士后出站后颁发中国科学技术大学博士后证书。', '大湾区大学是由广东省人民政府管理、东莞市政府投入保障为主的公办普通高等学校，办学经费由东莞市财政全额供给。大湾区大学定位为以理工科为主的高水平新型研究型大学，重点聚焦物质科学、先进工程、生命科学、新一代信息技术、理学、金融管理等6个方向开展学科建设、人才培养和科学研究，拟开展本科生、硕士及博士研究生全日制学历教育，预计到2030年在校生将达1万人左右，本科生与研究生规模比例约1:1。大湾区大学按照“一校两区”建设，校园建设投资约100亿元，总占地面积约2356亩，总建筑面积约100万平方米。松山湖校区选址于松山湖高新区，已于今年1月工程设计招标，并于11月正式动工；滨海湾校区选址于东莞市滨海湾新区威远岛板块，滨海湾校区预计年底前启动校园规划和一期校园工程设计招标。', 'https://www.zhaopin.com/jobdetail/CCL1368679040J40693232207.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (110, '硬件测试', '拓保软件', '7月28日', '1-2万', '广州-海珠区', '计算机软件,互联网,IT服务,计算机软件', '1000-9999人', '未融资', 'CC157088920J40736722816', '职位亮点 ：<br>1.深度参与产品物料选型与成本优化！<br>2.专注电子元器件替代验证，保障产品质量！  3.技术驱动，实践电源/电路知识！  <br>4. 接触前沿电源技术/知名客户项目/完善培训体系！  <br>职位职责：  <br>1.替代料需求分析与评估： 深入分析替代料测试需求，评估物料替代对电路性能、可靠性的潜在影响。  <br>2.测试方案与计划制定： 基于需求设计详尽的测试用例，制定科学严谨的测试方案与计划，确保测试覆盖率全面。  <br>3.执行测试与问题定位： 独立执行替代料测试，熟练操作示波器、万用表、电源、电子负载、信号发生器、频谱仪等测试设备，准确搭建测试环境，具备良好的焊接技能。精准记录测试数据，分析测试结果，定位并解决测试过程中遇到的问题。  <br>4.报告输出与跟踪： 编写清晰专业的测试报告，输出准确的测试结论。跟踪替代料小批量试产结果，协助推动BOM变更流程。  <br>5.沟通协作： 与研发、采购、质量、生产等部门紧密协作，确保替代料验证流程顺畅。  <br>职位要求 ：  <br>1.专业基础： 电子工程、微电子、电气自动化、电子信息工程等相关专业背景。  <br>  <br>', '深圳市拓保软件有限公司创立于2007年，是一家以软件技术服务和信息化产品及解决方案服务为核心的国家高新技术企业。现已成为中国领先的软件与信息综合服务商。拓保软件拥有5000多名研发人员，在全国包含北京、上海、广州、成都、南京等多个城市及日本东京设有近20个分支机构，为全国范围内多家标杆企业、集团公司等组织提供专业的数字化技术服务，并与平安集团、BAT系、顺丰等百强企业建立长期的合作伙伴关系。拓保软件今天的成绩都源于公司每位专业人才的努力和拼搏，未来，全国各地的拓保人也将继续努力为中国企业及公共组织的数字化升级而奋斗，为商业和社会发展进步贡献力量！现在，你是否愿意加入我们？与全国5千多名专业人才共同成长共同奋进，成为专业技能超群的拓保人。在拓保软件，你将结识许多业界大牛，与他成为良师益友，帮助自己职业生涯的可持续发展；在拓保软件，你将获得的不仅是薪酬福利，更能获得贴心且精致的隐藏福利；在拓保软件，你将身处年轻活力的办公空间，与一群有趣且充满朝气的人儿共成长，一同解锁更多职业专业技能成立至今，拓保软件始终坚持“吸引和培养高素质人才，推动企业可持续高速发展”的人才战略，把人才的培养和职业发展放在企业发展重要位置，通过不断升级迭代人才发展体系，积极提高人才的职业素养，挖掘人才的个人潜力。加入我们，解锁新技能，开启一段新的人生征途！了解更多拓保软件最新资讯，请关注“拓保软件”微信公众号。总部电话：0755-25846644官网：http://www.tobosoft.com.cn', 'https://www.zhaopin.com/jobdetail/CC157088920J40736722816.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (111, '前端开发', '北京国信鸿思科技有限公司', '5月27日', '150-200元/天', '北京-海淀区', '计算机软件,云计算/大数据,IT服务,计算机软件', '20-99人', '不需要融资', 'CC689773120J40757680813', '职位描述<br>1.根据开发进度和任务分配，完成相应模块软件的开发、编程任务；<br>2.负责编写高质量、符合开发规范要求的前端代码；<br>3.进行程序单元、功能的测试，查出软件存在的缺陷并保证其质量；<br>4.进行编制项目文档和质量保证的工作。<br>职位要求<br>1.本科及以上学历，有良好的代码编写习惯；<br>2.有良好的沟通表达能力，独立分析、解决问题的能力；<br>3.工作主动，能承受一定的工作压力，具有良好的团队合作意识；', '北京国信鸿思科技有限公司创立于2014年，是一家以产学研一体化为核心的高科技公司。公司入驻于北京市海淀区学清路甲18号中关村东升科技园-学院园，充分融合产业、高校、科研机构的独特优势，形成了强大的集研究、开发、生产一体化团队。公司主营应用软件与平台的开发，核心业务领域包括大数据分析、人工智能、文本挖掘、仿真模拟、知识图谱、数字孪生等技术的研发及工程应用能力。', 'https://www.zhaopin.com/jobdetail/CC689773120J40757680813.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (112, 'Java', '外企德科数字技术有限公司', '2025-07-27 00:23:22', '1.6-3万·14薪', '东莞-None', '专业技术服务', '10000人以上', NULL, 'CCL1480117890J40599610805', '华为社招OD<br>【招聘岗位】<br>开发、测试、前端、算法、数开、运维工程师岗位~~~欢迎投递！<br>注：机考通过后、根据候选人意向岗位/城市与需求部门做匹配--先业务方向沟通，候选人OK了再安排后续面试--入职（多部门/多城市可选)；<br>【岗位要求】<br>1. 统全本科，可接受应届、考研断档、 0 经验；<br>2. 掌握任意一种 或多种 编程语言：Java/C/C++/C#/Python/Go/JavaScript等；能通过机考；<br>【福利待遇】<br>1、5天8小时，双休制，偶尔加班（根据项目进度来定）；<br>2、全额五险一金++周末加班2倍工资（周末加班不强制，看个人意愿）+年终奖(由部门/个人绩效定）；<br>3、大厂待遇，项目稳定，个人瓶颈期可申请挑战新项目，晋升空间广，办公环境高大上;<br>4、节日福利++生日会++年度免费体检++公司内部健康驿站++带薪年假<br>5、每年一次调薪调职机会；<br>【入职城市】可选：<br>深圳、东莞、成都、西安、上海，杭州、苏州、南京、武汉、长沙、北京等<br>【业务领域】可选：<br>消费者终端、智能汽车、芯片设计、前沿技术预研、通信、云计算、AI/人工智能、政企服务等', '外企德科数字技术有限公司是一家2023年新成立的中外合资企业。成立于2023年11月24日，公司定位：专注于为信息技术企业提供人才及数字技术外包解决方案的中外合资企业。它是由中国人力资源服务行业的FESCO（北京国际人力资本集团）与全球人力资源服务领导者The Adecco Group（德科集团）合资成立的。公司主要提供网络技术服务、软件外包服务、计算机系统服务、技术进出口、软件开发等信息技术相关服务。专注于为信息技术企业提供信息技术类人才及数字技术外包解决方案。', 'https://www.zhaopin.com/jobdetail/CCL1480117890J40599610805.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (113, '实施工程师', '安徽锐能科技有限公司', '7月10日', '4000-8000元', '合肥-瑶海区', '新能源汽车,新能源汽车,汽车零部件', '500-999人', '未融资', 'CC280805330J40792636005', '1.现场产品安装、调试及测试；<br>2. 负责对售后问题进行反馈及追踪，直至问题解决；<br>3.负责配合部门负责人进行内部和外部培训工作；<br>4.不断完善售后问题库。<br>任职要求：<br>1.电气相关专业专科及以上学历；<br>2.简单的电路分析；<br>3.具备汽车电子售后技术支持工作者优先；<br>4.具备相关相近工作经验1年以及上者。<br>能够接受长期出差', '安徽锐能科技有限公司，是由一群来自于中国科学技术大学、合肥工业大学、南京航天航空大学等国内一流高校的顶尖专家、青年才俊组建，一直专注于新能源控制技术、动力系统集成技术的研发与产业化，核心经营团队均来自世界500强企业以及国内上市公司。公司研发团队已承接国家科技支撑计划，安徽省、广东省、江苏省科技计划等十余项重大项目，获得授权专利二十余项。新能源汽车是国家重点支持的产业发展方向。我们紧跟新能源汽车发展的浪潮，建立了完整先进的汽车电子开发平台，为整车企业、动力电池企业提供最优质的动力控制系统产品与服务，涵盖大功率动力电池管理系统，电动汽车整车控制系统，电动汽车动力系统总成解决方案，电动汽车整车电气网络架构解决方案等。我们业已成为上海汽车、北京汽车、苏州金龙汽车、国轩高科等著名企业的核心供应商，我们开发的大功率动力电池管理产品与技术已达到国内顶尖水平。人类可持续前行将由新能源电力推动。我们致力于成为全球顶尖的新能源控制技术提供商，以精益求精的工匠精神，为客户提供最具价值的解决方案，推动新能源汽车产业的持续进步。', 'https://www.zhaopin.com/jobdetail/CC280805330J40792636005.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (114, 'Java', '外企德科数字技术有限公司', '2025-07-27 00:25:37', '1.5-3万', '东莞-None', '专业技术服务', '10000人以上', NULL, 'CCL1480117890J40788061105', '工作内容:<br>1.负责研发领域IT系统技术方案的设计，开发等工作;<br>2.负责项目开发过程中的技术攻关及解决运行中出现的技术问题;<br>3.负责产品核心模块的代码编写和测试;<br>4.负责产品疑难问题的分析和定位。<br>岗位要求:<br>1.统招学历学位证，毕业证，学信网可查;<br>2.热爱编程，基础扎实，熟悉掌握但不限于JAVA/Python/JS/HTML/GO/C/C++/C#等编程语言中的一种或数种，有良好的编程<br>习惯;<br>3.具备独立工作能力和解决问题的能力、善于沟通、乐于合作、热衷新技术、善于总结分享，喜欢动手实践', '外企德科数字技术有限公司是一家2023年新成立的中外合资企业。成立于2023年11月24日，公司定位：专注于为信息技术企业提供人才及数字技术外包解决方案的中外合资企业。它是由中国人力资源服务行业的FESCO（北京国际人力资本集团）与全球人力资源服务领导者The Adecco Group（德科集团）合资成立的。公司主要提供网络技术服务、软件外包服务、计算机系统服务、技术进出口、软件开发等信息技术相关服务。专注于为信息技术企业提供信息技术类人才及数字技术外包解决方案。', 'https://www.zhaopin.com/jobdetail/CCL1480117890J40788061105.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (115, '实施工程师', '外企德科数字技术有限公司', '2025-07-27 00:26:06', '8000-12000元·15薪', '苏州-工业园区', '专业技术服务', '10000人以上', NULL, 'CCL1480117890J40795412105', '1、负责V5级别大客户企业级支持计划交付，包含服务月报书写、云服务可用性优化等；<br>2、支撑客户重保期间相关技术问题支持，如技术交流、故障定位定界、演练方案输出及其他保障技术工作；<br>3、及时向客户支持专家、产品研发等升级大客户使用问题，参与审核产品研发工程师提供的解决方案，确保方案的可实施性；独立支撑及时、有效地与客户沟通，接收、处理客户问题，及时提供解决方案，并对解决方案的有效性独立支撑；<br>4、分析收集客户声音及问题，推动后端改进产品；<br>5、及时总结常见的技术问题，沉淀优秀经典案例，有必要时及时提供《根因分析报告》。', '外企德科数字技术有限公司是一家2023年新成立的中外合资企业。成立于2023年11月24日，公司定位：专注于为信息技术企业提供人才及数字技术外包解决方案的中外合资企业。它是由中国人力资源服务行业的FESCO（北京国际人力资本集团）与全球人力资源服务领导者The Adecco Group（德科集团）合资成立的。公司主要提供网络技术服务、软件外包服务、计算机系统服务、技术进出口、软件开发等信息技术相关服务。专注于为信息技术企业提供信息技术类人才及数字技术外包解决方案。', 'https://www.zhaopin.com/jobdetail/CCL1480117890J40795412105.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (116, '硬件测试', '重庆科满福人力资源服务有限公司', '7月15日', '8000-10000元', '郑州-管城回族区', '企业服务', '20-99人', NULL, 'CCL1487604860J40932176204', '【岗位职责】 ：<br>1、进行新产品研发阶段的测试工作<br>2、完成新产品的功能测试、可靠性测试、环境测<br>试、安全测试等技术工作<br>3、制定测试计划，设计测试用例，分析测试数<br>据，编制测试报告<br>4、为其他部门提供技术支持，与其他部门的产品<br>联合测试工作<br>【薪资待遇】：<br>试用期：（试用期5350-转正6500）元/月＋300全勤+（300-800）元/岗位补贴+（1000-1500）元/月绩效+加班费=-6000-9000左右', NULL, 'https://www.zhaopin.com/jobdetail/CCL1487604860J40932176204.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (117, '技术支持工程师', '超年实业(上海)有限公司', '7月18日', '6000-8000元', '上海-松江区', '人工智能,电子/半导体/集成电路,人工智能', '20-99人', '未融资', 'CCL1303113110J40754025309', '公司从产品知识、沟通技巧等各方面培养市场部和售后技术支持部门的储备人才。', '超年实业（上海）有限公司及旗下康睦成立于2014年，最初是由某德国知名智能家居企业的3位资深研发工程师共同组建的产品研发创业团队，致力于智能安全和物联网的自主设计与开发，经过数年的不懈努力，在指纹识别控制与应用、小系统节能应用、远距离加密传输、远程视频对讲与控制等方面的应用和整合取得了丰富的沉淀和积累，未来将在人脸识别、AI算法、NFC、NB iot、语音识别等层面进行探索与开发，加大底层应用技术的设计、研究与积累。目前公司已经取得数项创新专利。截至2022年，旗下康睦（kmuun.com）品牌已逐步形成了高端门禁D系列、嵌入式系统T系列、智能单品P系列以及高端智能定制服务为核心的4大类产品系列，目前正逐步发展为集设计研发、组织生产与品牌运营为一体的高科技公司。在嵌入式智能锁、后装指纹锁产品领域已建立起独树一格的品牌形象，力图在未来3年内时间内打造成为中国高端智能锁领域的第一品牌。公司秉承严谨、长远、负责的设计、研发理念，坚持以高品质的产品创新为基础，以为客户提供高品质产品和服务为中心，坚持品牌理想、屏蔽繁杂诱惑；耐住寂寞踏实工作、勤奋努力、不懈奋斗，在现代中国崛起的大背景下，结合系统效用的开发与管理方式，以开放的心态欢迎各界有识之士以各种方式加入我们，共同探索、共同创造、一起成长，为中国的高品质实体产业和产品品牌崛起尽一份绵薄之力。', 'https://www.zhaopin.com/jobdetail/CCL1303113110J40754025309.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (118, '软件测试', '天阳科技', '7月17日', '5000-7000元', '南宁-青秀区', '计算机软件,计算机软件', '1000-9999人', '已上市', 'CC120408370J40369078508', '1.全国项目驻场测试，主要负责功能、数据或接口等相关测试工作； <br>2.统招本科学历及以上（学信网可查）；毕业满2年；计算机专业优先； <br>3.热爱软件测试行业、有强力的自驱力，能够在测试岗位深入学习研究； <br>4.有无经验均可，服从公司安排，接受公司培养，可接受异地工作优先； <br>福利待遇： <br>上市公司，公司可以提供住宿，提供五险一金； <br>欢迎符合要求的小伙伴们投递~', '天阳科技(股票代码：300872)，是全球金融创新服务的重要贡献者，持续赋能中国金融行业数字化转型，为客户提供咨询、金融科技产品、金融IT服务、云计算及运营服务。公司成立于2003年，服务超过300家金融行业客户，覆盖中央银行、政策性银行、国有银行、股份制银行、地方性商业银行、非银行金融机构等，员工人数近7000人，成为激活金融领域创新活力、推动金融科技迈入世界领先水平的重要力量。作为金融行业客户可信赖的合作伙伴，天阳科技凭借丰富的行业经验和端到端的专业服务，在信创、数字化金融、信贷、交易银行、信用卡、零售、营销、风险管理、征信监管等众多领域具备核心竞争力。据赛迪和IDC报告显示，近年来公司在中国银行业IT解决方案市场排名强势崛起，2019年收入及市场占有率综合排名分别位列第四位和第五位，并保持高速增长。同时，前瞻商业和科技趋势，入选2021年度未来银行科技服务商TOP100。天阳科技始终聚焦金融科技领域，加大自主创新力度，在超过100个城市建立本地化、专业化的研发和服务团队，拥有CMMI5级认证、软件测试成熟度模型集成（TMMi）3级认证、ISO9001质量管理体系认证、ISO20000信息技术服务管理体系认证、IS027001信息安全管理体系认证。通过部署人工智能、云计算、大数据、移动互联网、分布式计算和区块链等先进金融科技，公司致力于构建安全可控、普惠民生、开放共赢格局，在关键技术领域服务现代化金融发展大局，更好地为各利益相关方创造更大价值，为大中企业、小微企业以及每个个体提供优质金融服务。', 'https://www.zhaopin.com/jobdetail/CC120408370J40369078508.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (119, '测试工程师', '科锐尔人力资源服务(苏州)有限公司', '6月6日', '7000-10000元', '武汉-蔡甸区', '咨询服务', '1000-9999人', '已上市', 'CC453635220J40797757203', '工作内容：<br>1）按照测试任务完成试验设置和测试切换工作。<br>2）掌握温度箱设置及操作、高速相机设置和操作、数据采集系统设置和操作，工装夹具的设置和操作，等主要测试技能。<br>3）参与实验室APS，5S、TPM等相关工作<br>4）完成实验室主管及经理布置的其它任务。<br>学历要求：统招大专<br>专业能力： word，excel基本操作', '科锐国际人力资源有限公司成立于1996年，总部位于北京。作为亚洲领先的整体人才解决方案服务商，科锐国际在中国大陆、香港、印度、新加坡等亚洲地区拥有超过79家分支机构，1,500余名专业招聘顾问，在超过18个行业及领域为客户提供中高端猎头、招聘流程外包、灵活用工、营销外包、校园招聘、培训、招聘咨询等解决方案。截至目前，科锐已与2,000余家跨国集团、国内上市公司、快速成长性企业及非盈利组织建立长期合作关系。其中70%为外资500强企业。', 'https://www.zhaopin.com/jobdetail/CC453635220J40797757203.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (120, '硬件测试', '重庆科满福人力资源服务有限公司', '6月30日', '7000-10000元', '苏州-工业园区', '企业服务', '20-99人', NULL, 'CCL1487604860J40922132104', '岗位职责】 ：<br>1、进行新产品研发阶段的测试工作<br>2、完成新产品的功能测试、可靠性测试、环境测<br>试、安全测试等技术工作<br>3、制定测试计划，设计测试用例，分析测试数<br>据，编制测试报告<br>4、为其他部门提供技术支持，与其他部门的产品<br>联合测试工作<br>', NULL, 'https://www.zhaopin.com/jobdetail/CCL1487604860J40922132104.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (121, '测试工程师', '河南歌络影视传媒有限公司', '7月24日', '8000-9000元·13薪', '开封-龙亭区', '新媒体', '20人以下', NULL, 'CCL1495955890J40793592303', '1、专科及以上学历，计算机，软件工程、物联网，大数据、通信工程、电子信息、新能源汽车等相关理工科专业; 2、理解测试流程，并写出测试用例;', NULL, 'https://www.zhaopin.com/jobdetail/CCL1495955890J40793592303.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (122, '科研人员', '三角轮胎', '7月21日', '1.5-2万', '威海-环翠区', '化学纤维制造业,化学原料/化学制品', '1000-9999人', '已上市', 'CC135621210J40270525805', '一、博士后科研工作站招聘计划<br> <br>（一）招聘方向<br> <br>1、橡胶及轮胎技术研究<br>先进测试设备的研发（1人），开展先进测试设备设计和制造研究（尤其是摩擦和六分力测试）。<br>先进仿真技术的研究（1-2人），包括制造过程和性能预测。<br>高分子材料研究（2-3人），突出新型功能材料的研究，以多孔材料、密封材料、自修复材料、3D打印材料、高性能聚氨酯弹性体材料为重点方向，达到或突破国外同等材料的性能指标；注重新型环保绿色材料，以可回收利用、绿色低能耗为主要关注点，性能与可替代的传统材料的性能相当；开展新型高性能材料的研究，以提升轮胎的磨耗、抓地和能耗等性能为目标。<br>车辆工程研究（1-2人），开展智能轮胎的研究，以算法、传感器、数据采集、与车辆互联等方向为内容，预测轮胎的力和力矩、磨损磨耗、耐久寿命等性能。<br>2、其他技术研究<br>橡胶和轮胎加工工艺与装备研究（1人）<br> <br>（二）招聘要求<br> <br>1.在国内获得或即将获得博士学位。<br>2.年龄在35岁及以下；品学兼优、身体健康。<br>3.具有较强科研能力和创新能力；具备敬业、团队精神。<br>4.全职在本站从事博士后研究工作人员优先。<br>5.所学专业、主要研究方向和研究特长适合本站课题研究需要并能够集中精力从事博士后研究工作。<br>6.有国外相关工作经验者优先。<br> <br> 二、在站博士后待遇标准<br> <br>（一）公司待遇<br> <br>1、全职在站人员年薪标准为税前月薪1.5—3万元，具体协商（根据专业及课题分三档：1.5万元/月、2万元/月、3万元/月）。<br> <br>2、兼职在站根据课题、在岗时间等确定，具体协商。<br> <br>3、全职在站和兼职在站人员的薪酬待遇也可按照课题、以及为企业带来的效益贡献情况双方协商确定。<br> <br>4、对在项目研究中取得专利，并获得相应科研成果转化效益等情况，公司将给予一定奖励。<br> <br>5、享受公司员工福利；社会保险可承担，具体协商。<br> <br>6、公司协助办理山东省及威海市博士学历人员资助。<br> <br>（二）威海市待遇<br> <br>1、生活津贴：在站的博士后人员，享受由市级财政和区级财政提供的全职在威工作的博士研究生待遇，每人每月给予5000元生活津贴。发放时间以博士后人员实际在站时间为准，最多不超过两年。出站留威且符合万名大学生聚集计划的，可继续领取最长1年的生活津贴。<br> 2、安家补贴：博士后人员出站后6个月内留威工作并落户、缴纳社会保险的，由市财政给予20万元安家补贴。', '三角轮胎创始于1976年，总部位于山东省威海市，2016年沪市A股上市,总资产161.39亿元，市值120亿元,员工近7000人，是中国轮胎产业科技创新的引领者，行业低碳绿色发展的首倡者和先行者。四十多年来，三角始终专注于轮胎科技创新，产品覆盖商用车轮胎、乘用车轮胎、斜交工程胎、子午工程胎和巨胎、特种轮胎等五个系列，是行业内品种最齐全的企业之一。营销网络遍及全球180多个国家和地区，获得了来自全球60个国家或经济体官方产品认证,在北美、欧洲、中南美、澳洲、东南亚、中东非、俄罗斯、印度等地设有营销分支机构，与众多国际知名工程机械制造商和汽车制造企业建立了全球合作。三角轮胎是国家高新技术企业、中国轮胎产业技术创新战略联盟主体单位，建有国家认定企业技术中心、国家工程实验室、国家级工业设计中心三个创新平台和一个海外研发机构——美国阿克隆研发中心，是国家标准和行业标准的主要制定者之一。公司“巨型工程子午胎成套生产技术与设备开发”项目获得国家科技进步一等奖。三角轮胎始终秉持“诚信、创新、勤奋、爱人”的核心价值观，以共赢为理念，将员工个人价值的实现与三角事业的发展壮大互相结合与促进，诚聘精英人才！', 'https://www.zhaopin.com/jobdetail/CC135621210J40270525805.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (123, '前端开发', '滑县巨旺商贸有限公司', '7月16日', '6000-11000元', '郑州-金水区', '电子商务', '20-99人', NULL, 'CCL1486365070J40800401813', '岗位职责：<br>1、负责前端程序的实现，熟悉前端工程化工具，提供合理的前端支持和技术选型；<br>2、对性能、体检、交互进行必要的优化；<br>3、在团队的代码格式和结构的规定下,编写易读、易维护、高质量、高效率的代码<br>4、执行力强，具备良好的团队协作精神<br>任职要求：<br>1、计算机相关专业大专及以上学历<br>2、熟练使用Vue2+Element UI+webpack，熟悉vue相关生态 vuex、vue-router<br>3、具备扎实的JavaScript基础，熟悉ES6语法。<br>4、精通HTML5和CSS3标准，能够使用原生或样式框架编写页面样式，熟悉响应式、移动版本的H5页面构建。<br>5、有微信小程序、UNIAPP开发经验，熟悉微信开发平台相关的服务接口和调用机制。<br>6、熟悉浏览器的兼容调试技巧，能够解决产品的兼容问题，了解javascript性能优化。<br>7、熟悉用友财务软件、泛微OA软件二开、echarts相关项目经验的优先。', '滑县巨旺商贸有限公司位于河南省滑县，是一家专注于建筑材料贸易与相关技术服务的综合性企业。公司立足商贸领域，业务涵盖建筑材料供应、设备运维支持及数据分析服务，致力于为环保监测、化工等行业提供专业化解决方案。团队核心优势体现在技术实践与数据处理能力上，成员需掌握化学分析方法及行业标准，通过远程监控与数据分析保障设备稳定运行。服务范围覆盖郑州等多个区域，依托国际企业中心等办公节点，形成跨区域协作网络。公司注重实效与规范管理，严格遵循数据处理标准，通过系统化流程确保服务质量。在环保监测领域积累了一定技术服务经验，持续优化运维站点数据管理方案。现处于稳健发展阶段，正通过人才引进强化技术实施能力，推动业务向精细化、专业化方向延伸。', 'https://www.zhaopin.com/jobdetail/CCL1486365070J40800401813.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (124, 'Java', '越亮传奇科技股份有限公司', '7月18日', '160-180元/天', '厦门-思明区', '计算机软件,IT服务,物联网,计算机软件', '500-999人', '未融资', 'CC676118620J40695763306', '岗位职责：<br>1、参与项目需求沟通；<br>2、根据项目组的安排完成相关开发工作，积极配合其他人员的对接工作；<br>3、对自己开发的功能代码进行严格的单元测试，确保提交代码的质量；<br>4、协助测试人员处理发现的BUG，积极配合团队进行相关系统的优化工作；<br>5、根据模版要求或培训要求完善负责系统模块的概要设计、详细设计等开发相关的文档材料。<br>岗位要求：<br>1、2026届本科应届生，计算机相关专业，能全职实习（5天8小时工作制，可请假）；<br>2.熟悉ORACLE、MySQL语法逻辑强的优先；<br>3.有过帆软报表开发经验优先；<br>4.有Python开发优先；<br>5.有使用过azkaban数据开发者优先；<br>6、有获得过软件技术类相关奖项的优先考虑；<br>7、性格活泼开朗，有较好的自主学习能力及团队协作精神。工作态度严谨认真，责任心强。', '公司简介：越亮传奇科技股份有限公司（原联想中望系统服务有限公司，2014年7月1日起正式更名）。我们是一家以电信行业为主要服务对象的it服务企业，以电信运营商相关的移动互联网应用作为主要市场目标和基础，致力于成为服务于电信运营商和其他领域的移动互联网应用专家。如今，除了传统的面向企业的IT服务领域外，公司在新兴的物联网、大数据和云计算领域也取得长足的突破和深厚积累，物联网通信解决方案和企业物联网应用解决方案一直保持国内领先水平。地址：广州市天河北路898号信源大厦307-308室北京平台：北京市海淀区紫竹院路116号嘉豪国际C座十层1001-1005室南京平台：南京市江宁区胜利西路9号京妆产业园3栋102室公司网站：http://www.hvgroup.com.cn诚邀有志在it互联网行业发展的您，在越亮传奇放飞梦想，创造奇迹。一经录用，我司将为您提供：（一）、优秀的企业文化1．公司愿景：一流的移动互联网支撑商。2．公司宗旨：以电信运营商相关的移动互联网应用作为主要市场目标和基础，成为服务于电信运营商和其他领域的移动互联网应用专家。3．创新、合作、共赢越亮传奇秉承“志高行远、创新融合、精准求实、服务共赢”的核心价值观，形成了“创业创新、合作共赢”的文化精髓。4．温暖包容我们是一个温暖的大家庭，更是一个包容的大集体，充满着浓浓的温情与人文关怀的团队。十年来员工伴着公司一起成长，他们把自己最宝贵的青春奉献给了公司的同时，也感受着这个温暖与包容的大家庭对每一个人细心而周到的关怀与照顾。在这里，我们情同手足，互为亲人，并因此不离不弃。5．亲民爱员公司高层一直秉承“亲民爱员”的团队带领思想，让“领导不像领导、员工不像员工”的工作氛围其乐融融。让每一位越亮传奇员工在尊重与自我的快乐环境中茁壮成长，与公司共同发展6．感恩责任越亮传奇在这十年间经历过变革与创新，能在行业中处于领先地位，我们感恩这个伟大的时代，感恩我们每一位员工，我们也将肩负起社会的责任，为社会上有需要的人提供爱心支持与援助。在每一次危难面前都有我们越亮传奇人的身影和爱心援助行动。（二）、良好的工作条件硬件条件：总部与广州平台位于成熟而便利的天河北，另在北京与南京核心地段设立技术与业务平台。与此同时，公司也注重员工的人文关怀：为员工提供读书、休闲活动场所，开展各项娱乐体育活动等丰富员工业余生活。软件条件：年轻奋发、团结协作、积极进取、快乐向上的工作氛围，优秀的技术与管理队伍，良好的人文关怀。（三）、完善的培训体系公司为员工提供全方位的支持，只要您有工作的兴趣，只要您有成就个人事业的愿望，我们将为您提供一系列培训机会；培训的课程有专业知识培训、技能技巧、心态管理等；同时公司还为优秀的员工出资外送培训。（四）、健全的福利体系1、薪酬福利：为员工提供富有竞争力的薪酬体系并根据每年的市场薪酬水平和个人业绩表现，同时结合企业实际，对员工进行年度（优才季度）薪酬调整。2、上班时间（双休制）：实行公司规定的五天八小时弹性上下班作息时间，所有假期与政府同，并设人性化奖励假期。3、保险/公积金：根据国家规定，公司为全体员工在入职当月（当月入职达十五天）缴纳五险一金。4、晋升机制：公司设立良好的晋升机制并提供内部招聘、职位轮换机会。5、员工锻炼：公司不定期组织体育比赛活动，如篮球、羽毛球、乒乓球及其他锻炼项目等。6、活动经费：公司每年定期举行户外郊游、拓展等活动，为员工提供一定活动费，以增强团队凝聚力,活跃并丰富员工业余生活，扩大员工休闲视野和与社会接触的机会。', 'https://www.zhaopin.com/jobdetail/CC676118620J40695763306.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (125, '实施工程师', '锘尔机械设备工程服务(大连)有限公司', '12月12日', '6000-9000元', '大连-甘井子区', '工程技术与设计服务,电气机械/电力设备', '20-99人', '不需要融资', 'CC855385470J00219716312', '技能要求：  实施 岗位职责：', '“亨金佳海洋工程有限公司”成立于 2015年 8月 14日，注册地香港，经营范围是船用设备和海洋工程设备。公司和各大石油公司和部分中国船厂，有着良好的合作关系。目前，公司正大力发展风电安装和运维业务，着手引进国外先进的深水风电技术，目标成为国内最早发展深水风电的公司，成为行业的引领着。风能是清洁的可再生能源，风力发电是新能源领域中技术最成熟、最具规模化开发条件和商业化发展前景的发电方式之一。我国风电发展，已从试验性阶段过渡为大规模商业化开发阶段，2000年以来，国为大力推进风电发展，确立了以项目带动产业、以产业推动规模的发展思路，推动了风电的大规模发展。“亨金佳海洋工程有限公司”将在未来几年，继续发展海洋工程深水技术，争取走在世界前列，成为行业的佼佼者。', 'https://www.zhaopin.com/jobdetail/CC855385470J00219716312.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (126, 'Java', '外企德科数字技术有限公司', '2025-07-27 00:25:12', '1.5-3万·14薪', '南京-雨花台区', '专业技术服务', '10000人以上', NULL, 'CCL1480117890J40782470405', '打造以数据+模型双轮驱动的工业软件aPaaS平台，构建工业软件产业生态资源，联合各方力量协同攻关，攻克核心软件急需解决的核心共性技术难题，助力工业软件国产化的快速发展。<br>采用互联网的技术和产品，协同现有的终端云和产业上云，提供云原生的根服务，为各行各业实现云化和数字化提供基础服务平台支持。部门提供KooMessage、KooMap、KooSearch等服务<br>岗位职责：<br>1、 担任aPaaS底座的开发工程师，负责系统模块的设计、代码编写及看护等工作。<br>2、 看护产品核心技术，并解决在项目开发过程遇到的关键问题。<br>岗位要求<br>1、 本科及以上学历，有力扣牛客刷题基础者优先<br>2、 具备较强的学习能力和基本沟通能力<br>我们能提供给您~<br>①大厂市场领先且稳定的薪酬福利收入（根据面试能力评价等定级定薪）；②个人编程能力的快速学习提升（导师6个月带教）；③行业前沿的技术框架（不用担心未来如果换工作技术框架不适用）；④行业领先的产品研发项目管理流程、编码规范培训、纯粹的工程师氛围（您要相信，和优秀的人一起工作，您也必定变得更优秀）。<br>您需要经过什么面试流程~<br>①机考；②综测；③在线面试。', '外企德科数字技术有限公司是一家2023年新成立的中外合资企业。成立于2023年11月24日，公司定位：专注于为信息技术企业提供人才及数字技术外包解决方案的中外合资企业。它是由中国人力资源服务行业的FESCO（北京国际人力资本集团）与全球人力资源服务领导者The Adecco Group（德科集团）合资成立的。公司主要提供网络技术服务、软件外包服务、计算机系统服务、技术进出口、软件开发等信息技术相关服务。专注于为信息技术企业提供信息技术类人才及数字技术外包解决方案。', 'https://www.zhaopin.com/jobdetail/CCL1480117890J40782470405.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (127, '硬件测试', '重庆科满福人力资源服务有限公司', '7月26日', '8000-10000元', '中山-None', '企业服务', '20-99人', NULL, 'CCL1487604860J40935937804', '【岗位职责】 ：<br>1、进行新产品研发阶段的测试工作<br>2、完成新产品的功能测试、可靠性测试、环境测<br>试、安全测试等技术工作<br>3、制定测试计划，设计测试用例，分析测试数<br>据，编制测试报告<br>4、为其他部门提供技术支持，与其他部门的产品<br>联合测试工作', NULL, 'https://www.zhaopin.com/jobdetail/CCL1487604860J40935937804.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (128, '实施工程师', '青岛安然物联网科技有限公司', '7月22日', '9000-18000元', '大庆-龙凤区', '物联网,物联网', '20-99人', '未融资', 'CC559764920J40822383504', '需要弱电技术、自动化、安防系统、工业互联网+危化安全生产、物联网人才，不要纯软件人才。  你能经常到全国各地出差吗？你能到工业生产现场生产现场做技术支持吗？  <br>真正的奋斗者在安然会有让人值得为之奋斗的事业，会有充实、高效的成长，会有高人一等的收入。  <br>你能做好售前技术支持、根据客户需求，高效制作方案吗？你能做好售中技术支持、指导他人正确安装、部署、调试系统向用户保质保量快速交付吗？你能做好售后维护，高效沟通和落实客户需求吗？  <br>迄今已服务中石化、中石油、延长石油、国能、兖矿、京能、索普、新安、奇美、昊源、潞安、旭阳、垦利、逸盛、海科、酒钢、金发等几百家石化、化工、选煤、钢铁、电厂企业。\n  <br>安然以客户为中心，以强者为本，抬头乐干，愿意与同道中人联合、链接，携手共建、共用、共享生产安全命运共同体，一起干，一起干，让优秀企业更安全，让优秀企业更高效！', '基于精准人员定位的工业安全生产信息化管理专家，安全生产信息化管理引领者！作为全国实时定位技术标准工作组成员和应急管理部“工业互联网+危化安全生产”人员定位系统技术支持机构，安然从2012年起致力于基于ZigBee Plus三维立体按需精准定位的“工业互联网+安全生产”的研究，获得了20多项安全智能管控系统发明专利和著作权，持续引领中国化工行业生产现场智慧安全！安然以“准、稳、狠”的ZigBee Plus三维立体按需精准人员定位统和“底数清、数据准、情况明、研判准、措施实”的安全生产信息化平台为核心，整合访客管理、出入口控制、人脸识别、视频监控、语音广播、重大危险源监控、可燃有毒气体监测等系统，对生产现场人、机、料、法、环五大要素进行实时、动态、智能管控和预警，规范人的安全行为，保障人的生命安全，有效防范风险、主动化解风险，实现智慧安全。安然“以用为本”，把安全生产信息化建设与公司管理体系“深度融合”，把安全生产信息化建设与日常工作“紧密结合”，对安全生产切实“有用、实用、好用”，避免建用“两张皮”，让安全管控更智能，让生产更高效才实用。迄今已服务中石化、中石油、延长石油、国能、兖矿、京能、索普、新安、奇美、昊源、潞安、旭阳、垦利、逸盛、海科、酒钢、金发等几百家石化、化工、选煤、钢铁、电厂企业。安然以客户为中心，以强者为本，抬头乐干，愿意与同道中人联合、链接，携手共建、共用、共享生产安全命运共同体，一起干，一起干，让优秀企业更安全，让优秀企业更高效！', 'https://www.zhaopin.com/jobdetail/CC559764920J40822383504.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (129, 'Java', '外企德科数字技术有限公司', '2025-07-27 00:26:10', '1.3-2.6万', '杭州-滨江区', '专业技术服务', '10000人以上', NULL, 'CCL1480117890J40796719905', '【任职要求】<br>1、统招本科及以上学历，学信网可查<br>2、热爱编程，熟悉掌握但不限于JAVA/C/C++/Python/JS/GO等编程语言中的一种或数种（均有岗位）<br>其他：<br>(1)导师制培训机制，新人入职后至少半年以上会有导师一对一辅导开展工作和学习<br>公司福利:<br>1.定级定薪都会有薪资涨幅，六险一金，全额缴纳,周末加班，双倍工资，节假日三倍工资<br>2.一年数次考评，薪资、职级可上浮~<br>3.带薪年假5-15天<br>4.免费夜宵，城际班车，健身房免费,舒适的办公环境', '外企德科数字技术有限公司是一家2023年新成立的中外合资企业。成立于2023年11月24日，公司定位：专注于为信息技术企业提供人才及数字技术外包解决方案的中外合资企业。它是由中国人力资源服务行业的FESCO（北京国际人力资本集团）与全球人力资源服务领导者The Adecco Group（德科集团）合资成立的。公司主要提供网络技术服务、软件外包服务、计算机系统服务、技术进出口、软件开发等信息技术相关服务。专注于为信息技术企业提供信息技术类人才及数字技术外包解决方案。', 'https://www.zhaopin.com/jobdetail/CCL1480117890J40796719905.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (130, 'C/C++', '北京罗森博特科技有限公司', '6月20日', '1.6-3万·14薪', '北京-海淀区', '医疗设备/器械,学术/科研', '20-99人', 'C轮', 'CC573891980J40584468403', '岗位职责：<br>1、Windows系统下应用软件开发；<br>2、软件代码编写与调试；<br>3.参与项目相关试验；<br>4、开发文档编写；<br> <br>任职要求：<br>1、通信、电子、计算机、数学以及生物医学工程专业等本科以上学历；<br>2、会使用C/C++，或者Qt开发；<br>3.了解基础的数据结构，了解多线程的使用；<br>4、英语水平良好，能够看懂研发相关的英文文档；<br>5、态度积极、有独立完成任务的能力和韧性；<br>职位福利：创业公司、五险一金、带薪年假、补助津贴、定期体检、节日福利、定期团建、股票期权  <br>', '北京罗森博特科技有限公司成立于2017年9月，荣获国家高新技术企业、科技型中小企业、北京市“专精特新”中小企业、中关村高新技术企业、中关村前沿技术企业、中关村金种子企业等荣誉称号，致力于医疗机器人数智化技术革新，以科技创新提升健康福祉。公司从⻣科⼿术中难度最⼤、临床需求最强烈的⻣盆⻣折治疗出发，以数智化⼿段“复制”临床专家经验，研发全球领先的智能化⻣科手术机器⼈，推动骨科手术向智能化、微创化、标准化发展。公司团队年轻活波、积极向上，公司文化开放透明、欢乐融洽，公司管理极度扁平，充分授权，公司提供一切资源帮助员工成长。', 'https://www.zhaopin.com/jobdetail/CC573891980J40584468403.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (131, '技术支持工程师', '成都百乐科技有限公司', '6月30日', '8000-13000元', '成都-武侯区', '医药制造', '100-299人', '未融资', 'CC130229950J40789587705', '工作职责：<br>1、负责客户售前及售后产品知识介绍、培训；<br>2、收集并整理潜在客户资料，及时反馈市场信息；<br>3、负责市场推广活动策划并组织开展；<br>4、负责售前方案设计及撰写；<br>5、负责公司内部人员培训；<br>6、负责demo实验及demo机管理。<br>岗位要求：<br>1、硕士及以上学历，生物学、医学等相关专业；<br>2、良好的人际沟通能力、语言表达能力、抗压能力和团队合作精神；<br>3、有良好的英文基础，可读懂相关英文技术资料；熟练使用office软件；<br>4、较强的生化及分子生物学实验动手能力，熟悉动物细胞、活体成像等优先考虑； <br>福利待遇： <br>1、六险+商业保险+交通补贴+餐补+通讯补贴+年终奖+体检 <br>2、工作时间：9:00-17:30（午休12:00-14:00），公司看重效率未严格实行考勤', '成都百乐科技有限公司致力于向用户提供生命科学领域技术与设备。目前，全权代理多项世界知名品牌在西南地区生命科学领域的销售及售后服务，如：Bio-Rad，Nanopore, Leica、Sartorius(Fortebio)、Miltenyi、Buchi、Nanolive、Implen等。用户遍布西南地区的各高等院校、医药、科研院所。我们凭借专业的技术力量，和优质的售后服务赢得了广大用户的认可。在这里，你可以得到：优良的专业培训机会，良好的职业发展前景！优秀的工作伙伴，和谐的工作氛围！上不封顶的薪资体系，满意的回报！公司发展迅速，不断需要引进人才。如果你有信念、有热情、有迎接挑战的决心和不断学习的意愿，那么请加入我们吧，我们将为你提供一个能尽情发挥才华的舞台！地址：成都市武侯区成科西路3号B座地址：重庆市渝中区虎踞路56号地址：贵阳市南明区花果园M区', 'https://www.zhaopin.com/jobdetail/CC130229950J40789587705.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (132, '科研人员', '郑州郑氏化工产品有限公司', '1月21日', '1.4-2万·15薪', '郑州-金水区', '农/林/牧/渔,农/林/牧/渔', '500-999人', '未融资', 'CC191232810J40660607616', '一、博士后招聘条件<br>  1. 具有博士学位，且获博士学位时间一般不超过3年；', '郑州郑氏化工产品有限公司成立于2001年，是一家集科研开发、生产、销售化工产品于一体的国家级高新技术企业、国家农药定点生产企业、国家肥料定点生产企业。公司总部位于河南省郑州市，现有员工700余人。公司实行集团化运营模式，下设河南省作物化控工程技术研究中心，以及鹤壁分公司、夏邑分公司两大现代化研发生产基地，设有河南郑州、新疆乌鲁木齐、广西南宁、辽宁沈阳四大物流中转中心，主营业务涉及原药、制剂、园林三大版块，业务范围覆盖全国并远销国外。', 'https://www.zhaopin.com/jobdetail/CC191232810J40660607616.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (133, '实施工程师', '青岛安然物联网科技有限公司', '7月24日', '8000-16000元', '石河子市-None', '物联网,物联网', '20-99人', '未融资', 'CC559764920J40884196004', '岗位职责：<br>1. 负责石化、化工厂人员定位系统的现场实施、现场交付和技术赋能等工作。<br>2. 对接客户需求，进行需求调研，制定详细的施工方案和计划。<br>3. 确保项目按照既定的时间节点和质量要求完成交付。<br>4. 对已交付的项目进行后期技术支持与维护。<br>岗位要求：<br>1. 年龄在25-35岁之间。<br>2. 能够适应经常出差的工作要求。<br>3. 熟悉信息化、弱电及工业互联网相关技术。<br>4. 具备良好的沟通协调能力和问题解决能力。', '基于精准人员定位的工业安全生产信息化管理专家，安全生产信息化管理引领者！作为全国实时定位技术标准工作组成员和应急管理部“工业互联网+危化安全生产”人员定位系统技术支持机构，安然从2012年起致力于基于ZigBee Plus三维立体按需精准定位的“工业互联网+安全生产”的研究，获得了20多项安全智能管控系统发明专利和著作权，持续引领中国化工行业生产现场智慧安全！安然以“准、稳、狠”的ZigBee Plus三维立体按需精准人员定位统和“底数清、数据准、情况明、研判准、措施实”的安全生产信息化平台为核心，整合访客管理、出入口控制、人脸识别、视频监控、语音广播、重大危险源监控、可燃有毒气体监测等系统，对生产现场人、机、料、法、环五大要素进行实时、动态、智能管控和预警，规范人的安全行为，保障人的生命安全，有效防范风险、主动化解风险，实现智慧安全。安然“以用为本”，把安全生产信息化建设与公司管理体系“深度融合”，把安全生产信息化建设与日常工作“紧密结合”，对安全生产切实“有用、实用、好用”，避免建用“两张皮”，让安全管控更智能，让生产更高效才实用。迄今已服务中石化、中石油、延长石油、国能、兖矿、京能、索普、新安、奇美、昊源、潞安、旭阳、垦利、逸盛、海科、酒钢、金发等几百家石化、化工、选煤、钢铁、电厂企业。安然以客户为中心，以强者为本，抬头乐干，愿意与同道中人联合、链接，携手共建、共用、共享生产安全命运共同体，一起干，一起干，让优秀企业更安全，让优秀企业更高效！', 'https://www.zhaopin.com/jobdetail/CC559764920J40884196004.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (134, '测试工程师', '嵩山实验室', '5月28日', '1.5-1.7万', '郑州-金水区', '网络/信息安全,通信/网络设备,计算机软件,云计算/大数据', '100-299人', '不需要融资', 'CCL1390391680J40740662607', '岗位职责： 1.负责新型电力系统（如微电网、分布式能源系统、智能电网等）的测试方案设计、测试用例编写和测试执行工作； <br>2.参与新型电力系统相关设备和软件的测试，包括但不限于：光伏逆变器、储能变流器、能量管理系统、微电网控制器等； <br>3.搭建和维护测试环境，包括硬件平台搭建、软件环境配置、测试数据准备等； <br>4.分析测试结果，编写测试报告，并跟踪问题解决进度； <br>5.参与新型电力系统相关技术标准和规范的制定和修订； <br>6.跟踪新型电力系统技术发展趋势，研究新的测试方法和工具。 <br>', '嵩山实验室是由郑州大学、信息工程大学和中电科第二十七研究所等单位共同发起组建、省政府批准成立的事业单位性质的新型科研机构。实验室对标国家重大战略需求，聚焦数字基础设施发展前言。业务领域包括数据科学与先进技术、量子信息应用基础、智联计算网络、网络空间安全与地球空间信息科学等领域。', 'https://www.zhaopin.com/jobdetail/CCL1390391680J40740662607.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (135, '软件测试', '重庆科满福人力资源服务有限公司', '6月28日', '8000-10000元', '重庆-沙坪坝区', '企业服务', '20-99人', NULL, 'CCL1487604860J40922565804', '【岗位职责】：<br>1、软件测试岗位职责 <br>2、接受测试任务，进行需求分析<br>3、按照测试计划搭建测试环境，并保证测试环境的可靠性<br>4、按照测试计划编亏测试用例，保证测试用例合理有效<br>5、按照测试用例执行测试，及时发现缺陷，并使用工具进行管理缺陷<br>6、编写和提交测试报告，保证测试进度按计划完成<br>7、参与审核其他测试工程师的测试用例和报告<br>8、学习公司已有方案和推广使用新的测试技术和工具', NULL, 'https://www.zhaopin.com/jobdetail/CCL1487604860J40922565804.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (136, '软件测试', '麦田房产', '7月11日', '1.5-1.7万', '北京-海淀区', '房地产中介', '10000人以上', '未融资', 'CC133216770J40661054516', '【公司总部面试，工作地点就近分配，请投递一份简历即可~】<br>毕业时间：不限！接受无经验小白！全北京就近分配！提供住宿方案！！<br>-----【收入福利】<br>1.收入构成=津贴+抽成【买卖+租赁+新房+金融+装修】+其他收入【团奖+奖学金+带看奖+精英股】<br>2.津贴：见习期 7000 元/月（含 1000 元奖学金）<br>3.我们建议您长期从事，从业时间越久收入越高也越稳定，抽成比例更高 <br>4.工作地点任您选，您可以去北京全域任意一家门店，同事友爱，环境舒适 <br>-----【工作职责】 <br>1.深度了解北京中高端楼盘及周边生活配套，与高净值人群为伍，成为城市房产专家<br>2.为顾客提供优质中高端房屋租赁、买卖服务体验，让房产交易化作美好的生命互动 <br>3.和社区业主建立深度链接，积累信任和口碑，以公益之心扎根社区，成为社区友邻 <br>-----【任职资格】 <br>1.年龄 22-45 周岁，大专及以上学历，专业不限，退伍军人亦可<br>2.正直真诚善良，强服务意识，良好的职业素养和操守 <br>3.致力于学习成长，勇于自我挑战，自强不息的进取之心', '麦田成立于2000年，覆盖北京、福州、厦门三地，拥有近1000家直营和加盟门店，10000名优秀伙伴。旗下拥有北京麦田、福州一麦、厦门麦田及小麦科技等多家子公司。业务范围囊括二手房买卖租赁、新房营销代理、在线房源信息服务等多个领域。2020年起麦田更是与文禾、金诚丰强强合作，为客户提供优质服务。麦田文化的核心是“利他”之道，这也是麦田的经营之道。对伙伴我们的使命是“一切为了成就人”，集所有资源培育优秀房产顾问，让伙伴们在麦田的土壤里成长、成功、成就梦想;对顾客我们的使命是“让人们居住更美好”，深度感知顾客需求，全力解决顾客问题，帮助人们实现家园梦想。我们以真挚的善意成为社区友邻，为城市带来一抹温暖的麦田黄。麦田浓厚的文化氛围带来温暖积极的工作环境，这里有善良友爱的伙伴，热情正向的团队，坚实长远的组织。欢迎加入，和我们一起“守望麦田，家的方向”。让商业不再沉重，利他之花开遍大地。', 'https://www.zhaopin.com/jobdetail/CC133216770J40661054516.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (137, '科研人员', '中国科学院上海应用物理研究所', '7月7日', '1.2-2万', '上海-嘉定区', '学术/科研,学术/科研', '1000-9999人', '未融资', 'CC131072840J40518807516', '岗位职责：  开展加工制造工艺对材料熔盐腐蚀行为影响的研究。', '中国科学院上海应用物理研究所是国立综合性核技术科学研究机构，筹建于1958年，在光子科学、加速器科学技术、核能技术、核科学技术与前沿交叉科学等领域，从事面向世界科技前沿和国家战略需求的基础与应用研究，开展原始创新和集成创新，致力于钍基熔盐堆核能系统的研究发展，致力于同步辐射光源和自由电子激光的大科学装置研制、运行与利用，致力于核科技前沿交叉的研究与核技术应用，以期将研究所建成我国独具特色、不可替代和具有国际竞争力的研究机构。上海应用物理所现承担中国科学院战略性先导科技专项“未来先进核裂变能——钍基熔盐堆核能系统（TMSR）”，研究和发展相关核能科学与技术，打造TMSR全产业链，目标是成为拥有最先进、最完备实验设施和条件，以工业应用为目标的世界级钍基熔盐堆核能系统的研究中心。上海应物所还承担上海光源线站工程、X射线自由电子激光试验装置工程、首台国产质子治疗示范装置研制项目，以及多项973项目、科技重大研究专项、基金委重大项目等国家重要科研任务。上海应用物理所是上海市核学会、中国核学会辐射研究与辐射工艺学分会的挂靠单位；主办《核技术》、《Nuclear Science and Techniques》（SCI）、《辐射研究与辐射工艺学报》等学术刊物。设有一级学科博士学位培养点 2个，二级学科博士学位培养点 5个，一级学科硕士学位培养点 3个，二级学科硕士学位培养点点 14个（其中专业学位 4个），并设有 2个博士后科研流动站。单位地址：上海市嘉定区嘉罗公路2019号网址：www.sinap.cas.cn E-Mail:hr@sinap.ac.cn', 'https://www.zhaopin.com/jobdetail/CC131072840J40518807516.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (138, '科研人员', '富生医疗器械', '7月23日', '6000-8000元·13薪', '长春-双阳区', '医药制造,医疗设备/器械,卫生服务', '100-299人', '未融资', 'CC193170610J40719869502', '岗位职责：  1.负责协助研发相关实验及方案设计。', '企业简介富生集团是集医疗器械、消毒产品及特医食品、肾健康食品研发、生产、经营为一体的国家级高新技术企业。成立于2004年1月。历经20年的发展，富生集团下设三家子公司：吉林省富生医疗器械有限公司、吉林省富生特医食品有限公司、吉林省康悦科技有限公司。富生公司是东北三省血液透析浓缩物生产产能与销量最大的专业厂家；同时也是吉林省长春地区第一家具有国家网上备案正规资质生产消杀产品的厂家。公司不仅有自己的品牌产品“富生”牌血液透析浓缩物，还有水机专用再生剂“富生”牌树脂盐，开发出“富生”牌透析机消毒液、除铁剂等，为客户提供血液透析方面最完善的相关技术服务。同时经销进口血液透析机、透析器、管路、内瘘针等透析耗材；经销反渗透水处理系统及水机配套耗材；经销余氯检测试剂盒、过氧乙酸残留测定试纸、水硬度检测试剂盒等水质检测相关产品。在公司董事长张海悦(教授，博士，长春市政协委员)领导下组建了国内外血液净化方面专家组成的研发团队，不断开发新产品，保持技术领先。富生人以“人类健康是我们最大的追求”为使命；以“专注顾客需求，保证产品质量，提供优质服务，坚持持续改进，实现顾客满意，创造和谐双赢！”为质量方针，打造客户最信任的产品。吉林省市场占有率达85%以上，东北三省市场占有率60%以上。成为了东北血液净化方面最专业最具实力的公司之一。富生牌血液透析浓缩物于2018年被评为“吉林省名牌产品”。2021年被评为国家级专精特新“小巨人”企业。历经近20年发展，富生牌血液透析浓缩物在全国二十多个省市、自治区各级医院累计使用已超过千万人份，客户已达到五百余家医院。产品安全性高、稳定性好、产品规格全、服务周到，临床效果好。“路漫漫其修远兮，吾将上下而求索”，富生公司以“富于创新生命为本”为企业宗旨，将不断开发新的血液透析相关及高科技医疗产品，保持技术领先，成为透析行业的领军企业，服务社会，让富生的员工生活的更美好！', 'https://www.zhaopin.com/jobdetail/CC193170610J40719869502.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (139, '技术支持工程师', '苏州凯尔视自动化科技有限公司', '7月28日', '7000-10000元', '苏州-昆山市', '工业自动化,工业自动化,计算机软件,计算机硬件', '20人以下', '不需要融资', 'CCL1249237920J40413630905', '技术岗位职责：<br> <br>1、 熟悉公司产品，熟练掌握软件应用操作及硬件功能（硬件部分包括相机、镜头、光源等）；<br> <br>2、配合销售工作进行前期方案书制定和后期项目调试，并对客户进行技术培训；<br> <br>3、用电话、网络远程技术支持和指导客户现场出现的问题，维护好客户关系；<br> <br>4、收集日常客户需求和BUG，能及时反馈给研发和项目负责人，为公司产品改进或研发提供相关建议；<br> <br> <br>岗位要求： <br>1. 学历专业：本科以上学历，能力突出者可放宽学历要求，理工科专业优先；<br> <br>2. 相关经验：机器视觉相关行业经验，应届毕业生不要求；<br> <br>3. 专业技能：有驾驶证，能够适应苏州及周边地区出差；<br> <br>4. 个性特点：头脑敏锐，思维活跃，有人际沟通能力，能够独立分析解决问题，较强的团队合作意识，积极好学，有责任心。<br>薪资待遇：<br>底薪+奖金，基本工资：6500-8000；根据项目完成度给予相应奖金；缴纳五险一金。<br>试用期2个月，能力突出可提前转正。<br>职位福利：五险一金、绩效奖金、带薪年假、周末双休、项目奖金<br>', '苏州凯尔视自动化科技有限公司成立于2020年3月，在团队的不懈努力下，在不到三年的时间已经成长为国家级高新技术企业，公司主要围绕机器视觉与光电技术开展业务，致力于为中国自动化智能制造提供最优质的产品与服务，为客户提供可配置视觉系统、智能视觉装备与核心视觉器件等高端产品与解决方案。公司从创立之初至今，一直致力于帮助客户提高产品质量、改善生产工艺、降低制造成本、加快生产效率；坚持以客户为中心，赋能3C电子、汽车零部件、新能源锂电、光伏、芯片半导体、家用电器等行业的智能“制造”。基于在光学成像、视觉软件与算法、核心视觉部件等领域的技术积累，努力成为客户心中的最佳合作伙伴。公司在服务客户的同时致力于为员工提供实现梦想的舞台，积极培养优秀员工，激发员工的积极性和上进心，培养了一支经验丰富、技术一流的经营团队；公司为员工的成长助力，实行人性化管理，有完善的培训和晋升机制，是员工心中的最佳雇主。', 'https://www.zhaopin.com/jobdetail/CCL1249237920J40413630905.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (140, '软件测试', '重庆科满福人力资源服务有限公司', '6月30日', '7000-10000元', '苏州-相城区', '企业服务', '20-99人', NULL, 'CCL1487604860J40922127804', '岗位职责】：<br>1、软件测试岗位职责 <br>2、接受测试任务，进行需求分析<br>3、按照测试计划搭建测试环境，并保证测试环境的可靠性<br>4、按照测试计划编亏测试用例，保证测试用例合理有效<br>5、按照测试用例执行测试，及时发现缺陷，并使用工具进行管理缺陷<br>6、编写和提交测试报告，保证测试进度按计划完成<br>7、参与审核其他测试工程师的测试用例和报告<br>8、学习公司已有方案和推广使用新的测试技术和工具<br>', NULL, 'https://www.zhaopin.com/jobdetail/CCL1487604860J40922127804.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (141, '软件测试', '深圳世纪百盛信息技术有限公司', '5月9日', '6000-9000元', '深圳-福田区', '新媒体,物联网,电子商务', '20-99人', '不需要融资', 'CCL1468660950J40890599804', '1.辅助工程师测试新品功能性和稳定性;<br>2.辅助测试工程师，进行测试记录及测试报告;<br>3.准确的定位及追踪软件问题，解决问题，对测试提出改进意见;<br>4.按时完成上级及部门其他领导交办的其他临时工作任务。<br>职位要求:<br>1、大专及以上学历，年龄21-32岁;<br>2、具有良好的职业操守，工作细心责任心强;<br>3、具备基本的电脑知识，熟练使用相关办公软件，接受应届生;<br>4、对互联网IT、计算机行业感兴趣，并打算在IT岗位长期发展;<br>福利待遇:<br>1、双休制，依法享受国家的法定节假日;<br>2、快速晋升空间，有效地竞聘晋升制度;<br>3、签订正式劳动合同，入职包住，享五险一金;<br>4、每季度员工聚会+员工生日会+节日礼物;<br>5、组织组织员工参与旅游，体育等业余活动，丰富员工的生活<br>年龄:21-32岁', '深圳世纪百盛信息技术有限公司，位于广东深圳市，是一家从事服务业为主的企业。自己有供应链，有线上电商平台。自己设计和文案，产品也深受年轻人喜欢公司也都是95后的办公气氛好，期待你的加入', 'https://www.zhaopin.com/jobdetail/CCL1468660950J40890599804.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (142, '测试工程师', '哈尔滨凌则科技有限公司', '2025-07-27 01:48:59', '4000-6000元', '哈尔滨-南岗区', '运营商/增值服务', '20-99人', NULL, 'CCL1501181030J40770361813', '1、负责研发产品的部件测试，并出具测试报告<br>2、参与和协助完成产品测试标准的确定工作，并执行工<br>作任务<br>3、负责测试仪器设备的相关工作<br>4、在负责人带领下完成职责范围内的各项工作任务<br>工作时间早九晚五点双休法定休息<br>薪资4-6k左右可谈晋升空间大<br>长期稳定', NULL, 'https://www.zhaopin.com/jobdetail/CCL1501181030J40770361813.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (143, 'Java', '南京众信慧德网络科技有限公司', '6月30日', '2000-4000元', '南京-浦口区', '计算机软件,互联网', '20-99人', '未融资', 'CC257684739J90250023000', '岗位内容：<br>1. 负责Java应用程序的设计与开发，包括需求分析、系统设计、编码和测试等环节。<br>2. 研究新技术，不断提升开发效率和程序性能。<br>3. 改进现有系统、优化系统资源，提高系统稳定性和可靠性。<br>4. 参与团队内部培训、交流与分享会议，促进整个团队技术水平的提升。<br>任职要求：<br>1. 熟悉Java语言，熟练掌握Spring框架及相关开源技术。<br>2. 具备扎实的计算机基础，熟悉数据结构、算法和网络编程等知识点。<br>3. 具备初步的Web开发经验，熟悉HTML、CSS、JavaScript等前端技术。<br>4. 具有较强的自学能力、问题解决能力和团队协作能力。', '南京众信慧德网络科技有限公司是一家从事软件开发、系统集成、网站开发运营推广的公司，目前旗下有多个商务平台。主要业务为：软件设计与开发、系统集成、网络工程、企业信息化、网站开发与运营、网页制作与优化、电子商务、通信系统开发集成、自动化控制系统开发与集成、自动化工程、软件销售、技术支持、技术服务、技术培训，云计算，大数据服务。', 'https://www.zhaopin.com/jobdetail/CC257684739J90250023000.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (144, '技术支持工程师', '杭州康德权饲料有限公司', '7月4日', '7000-12000元', '杭州-余杭区', '农/林/牧/渔', '100-299人', '不需要融资', 'CC350489610J40752694309', '1、动物营养、畜牧兽医相关专业，硕士研究生及以上学历。<br>2、有大型牧场养殖一线经验或技术服务经验者优先。<br>3、学习力和适应力强，能接受长期出差和短期驻场服务。<br>4、团队意识和服务意识强，能配合团队完成销售任务。 5、配合销售人员完成产品方案落地执行。  <br>6、各类型会议中完成技术结合产品的宣讲。', '康德权成立于1999年7月，是一家集饲料添加剂、兽药、化工合成、生物发酵的研发、生产、销售、服务于一体的高科技股份制企业。公司座落于杭州余杭国家级农业示范中心内，建筑面积2.5万多平方米，拥有兽药GMP车间、生物包膜车间、生物发酵基地、化工合成基地、研发中心和国际一流的质量控制检测中心。2003年被认定为浙江省高新技术企业；2004年通过ISO9001:2000质量体系认证；2006年7月通过国家兽药GMP认证；2008年8月通过欧盟FAMI-QS认证。2008年被国家发改委认定为生物饲料安全与污染防控国家工程实验室生物包膜工程中试基地。康德权通过“产学研”相结合的模式，与高等院校和科研机构的紧密合作，以技术创新和市场需求为导向，建立了饲料添加剂包膜、兽药制剂、有机化工合成、生物发酵四个强大的研发团队；随着国际畜牧养殖业和饲料业的发展，先后成立了浙江康德权科技有限公司（动保事业部）、杭州康德权饲料有限公司（添加剂事业部）、杭州恩诺威水生物科技有限公司（水产事业部）、杭州百煦汇进出口有限公司（国际贸易部），反刍动物营养事业部（反刍事业部），细分市场、精耕细作、贴近养殖、做专做精。“以德立人，以品做事；绿色健康，共赢发展”是康德权的经营哲学，公司专注于添加剂和动物保健品的开发、生产和销售，专注于为养殖场和饲料厂提供更优质的服务。公司运用拥有自主知识产权的智能微囊包膜技术，为产品生物利用率更高、投入产出更经济、环境更友好，而锐意进取。以我们的技术和智慧让饲料添加剂和动物保健品更加安全、优质、高效；以我们的努力和爱心让生活更加精致、美好；以我们的诚信和责任让社会更加和谐、共赢！我们致力于成为有特色的国际化饲料添加剂和动物保健品供应商！', 'https://www.zhaopin.com/jobdetail/CC350489610J40752694309.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (145, '技术支持工程师', '北京艾锐精仪科技有限公司', '2月8日', '1.1-1.5万', '上海-浦东新区', '医疗设备/器械,仪器仪表制造,医疗设备/器械', '20-99人', 'A轮', 'CCL1308509780J40733369913', '负责光学显微镜在不同领域的应用支持与技术服务，确保客户能够正确、高效地使用显微镜，推动产品在市场中的应用与推广。', '北京艾锐精仪科技有限公司依托北京大学席鹏实验室(www.xipenglab.com)的创新科研力量，以光学在体无创诊断技术和高速活细胞超分辨技术为核心，致力于超分辨显微成像系统及医学高端影像检测设备等高端仪器的研发和推广，打造生物医学超显微成像领域具有国际竞争力的产品，以公司化的形式实现科研成果的产业化。公司秉承精英汇集，优势互补的人才战略，合伙人拥有各自领域的成功经验和国际化视野，并特聘席鹏教授为公司首席科学家，共同构建锐意创新、积极进取的专业团队。对于锐意挑战物理极限、乐于跨界仪器与生命科学的你，我们虚位以待！', 'https://www.zhaopin.com/jobdetail/CCL1308509780J40733369913.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (146, 'Java', '外企德科数字技术有限公司', '2025-07-27 00:25:27', '1.6-2.2万·14薪', '深圳-龙岗区', '专业技术服务', '10000人以上', NULL, 'CCL1480117890J40786074205', '大厂核心自研项目，年底丰厚奖金池，试用期薪资不打折<br>岗位要求：<br>1、计算机、软件工程、数学等理工科专业背景，本科以上学历；<br>2、熟练掌握Java开发语言，熟悉SQL语言、数据库设计，掌握常见的数据结构、算法，了解软件工程、敏捷开发等知识；<br>3、熟悉Linux系统，有平台系统开发经验，具备大规模并发系统开发经验者优先；<br>4、掌握常见软件设计模式，熟练掌握软件系统设计及开发的工具与方法；<br>5、良好的沟通协调能力和团队合作精神，乐于学习并善于学习， 动手能力及解决问题能力强。<br>关于岗位：<br>1、个人技术提升很大，视野宽，有与业界专家交流的机会<br>2、方向前沿：涉及公司创新平台、公司产品可服务性云化桌面设计平台、测评平台以及认知服务等业界前沿的技术方向及软件应用', '外企德科数字技术有限公司是一家2023年新成立的中外合资企业。成立于2023年11月24日，公司定位：专注于为信息技术企业提供人才及数字技术外包解决方案的中外合资企业。它是由中国人力资源服务行业的FESCO（北京国际人力资本集团）与全球人力资源服务领导者The Adecco Group（德科集团）合资成立的。公司主要提供网络技术服务、软件外包服务、计算机系统服务、技术进出口、软件开发等信息技术相关服务。专注于为信息技术企业提供信息技术类人才及数字技术外包解决方案。', 'https://www.zhaopin.com/jobdetail/CCL1480117890J40786074205.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (147, '实施工程师', '常州春明环保科技有限公司', '7月25日', '5000-8000元', '常州-武进区', '环保,环保', '20-99人', '未融资', 'CC389987980J40149243303', '工作内容：', '主要从事大气、烟气、VOC自动监测系统的建设及运维、环境质量在线监测、水质自动监测系统、污染源在线监测、无人船排查走航监测、城镇污水处理设备及工程、VOC废气治理设备及工程、全自动实验室等系列产品。公司自成立以来，以“策略先行，经营致胜，管理为本”的推广理念，一步一个脚印发展成为同类企业中经营范围最广、在行业内颇具影响力的企业。', 'https://www.zhaopin.com/jobdetail/CC389987980J40149243303.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (148, 'Java', '海博泰科技(青岛)有限公司', '5月20日', '8000-12000元', '青岛-崂山区', 'IT服务,专业技术服务', '20-99人', '未融资', 'CCL1271304380J40538465308', '专业要求：软件工程、计算机类相关专业<br>学历要求：本科及以上学历<br>任职要求：<br>1.深入理解面向对象编程思想，具备扎实的Java编程基础，良好的编码习惯；熟<br>练使用svn、git等版本控制工具，熟练使用maven等项目管理工具；<br>2.熟练掌握Java开发语言，熟练掌握Java17新特性，JDBC<br>等，精通SpringBoot、SpringCloud、MyBatis等开发框架，<br>并了解其框架设计及工作原理；可以熟练使用编写业务<br>逻辑；<br>3.熟悉mysql、oracle等关系型数据库，熟练掌握SQL操作语句。', '海博泰科技（青岛）有限公司，针对涉海领域行业需求，开发应用前沿技术，服务于港口工程、海洋工程、船舶工程、水下工程等，推动产学研深度融合，促进科技成果转化应用，以科学专业手段提供可靠、精准、定制化的系统解决方案与安全策略。科研团队以长江学者、国家杰出青年基金获得者领衔，国内外名校博士为核心，专业涵盖物理海洋、海洋气象、船舶与海洋工程、控制理论与控制工程、计算机科学与技术、软件工程、人工智能与大数据等。以全球海洋数据为背景，建设海洋大数据系统，以下自主研发技术已在港口码头实施应用。船舶作业条件预报预警系统技术，采用实时观测、数值计算等手段，结合船舶作业要求，实现指定区域水文气象要素精细化预报，有效解决大型开敞式码头泊位受恶劣水文气象因素影响生产作业问题，保障码头系泊安全、提高码头接卸效率。船舶运动姿态智能实时监控技术，采用智能图像识别解决方案，对在泊船舶的运动姿态进行实时监测，对超出作业条件的运动量进行报警提示，便于船舶管理方及时处置，保证船舶作业期间的在泊安全。水上智慧调度技术，采用“优化调度算法”内核，基于机器自主学习，实时获取水文气象信息及船舶动态信息库数据，以水域利用率最高、船舶在港时间最短为目标进行全局寻优运算，迅速给出最优通航调度方案。解决港口调度管理水上通航效率短板，统筹全港资源，减少人为因素影响，优化调度流程，提升通航效率。公司根据实际需求研发关键技术，解决具体问题，提供定制化服实现产品内涵，满足用户需求。', 'https://www.zhaopin.com/jobdetail/CCL1271304380J40538465308.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (149, '技术支持工程师', '深圳市电科电源股份有限公司', '7月1日', '5000-6000元', '深圳-龙岗区', '新能源,新能源', '500-999人', NULL, 'CC552287820J40859209115', '岗位职责:<br>1.协助工程师进行日常技术研发与支持工作；<br>2.参与项目的设计、开发与实施过程；<br>3.按照项目需求，进行相关技术文档的编制与更新；<br>4.协助团队解决技术难题，提升项目质量与效率。<br>任职要求：<br>1.统招本科以上学历，25届电子信息工程、电气工程及其自动化、自动化、机械制造及其自动化等专业； 2.具备良好的沟通能力和团队合作精神； <br>3.对技术有浓厚的兴趣，愿意不断学习新知识； <br>4.有责任心，能够按时完成分配的任务； <br>5.适应能力强，能够在快节奏的工作环境中迅速解决问题；', '深圳市电科电源股份有限公司创立于2002年，自成立以来，一贯坚持为客户提供高品质专业服务的经营理念，致力于可充电镍氢电池、镍镉电池和锂离子电池的研究和开发，产品在应急照明设备、储能设备、家用电器、电动玩具、电动工具等等市场领域得到了广泛的应用，远销欧美世界各地，产品先后通过了CE、UL等的认证。随着公司的稳健发展，公司已在湖南衡阳建成了自己的镍电生产基地，主力研发和生产应急照明设备配套电池，把专、精作为发展方向。 2006年，公司在深圳开始投入锂电项目，立志在储能和备用电源领域作出贡献，目前产品已经在小型备用电源方面得到广泛应用。公司大力投入研发力量，形成了自己的技术体系，曾获得各种专利18项，结合公司的战略，自身的市场定位和产品定位，形成了自己的核心技术，为公司发展奠定了扎实的基础。公司追求规范化管理，坚持“信誉第一、质量为本，追求卓越、开拓创新”的质量方针，坚持“实施环境控制、持续改善提高，保护地球环境、创造绿色家园”的环境方针，通过了ISO9001和ISO14001认证，被认定国家高新技术企业，深圳市清洁生产企业，出口工业产品一类企业，中国质量诚信企业等等荣誉。深圳市电科电源股份有限公司诚邀您的加盟，愿您与我们携手共进，体现人生价值，共享丰厚成果！', 'https://www.zhaopin.com/jobdetail/CC552287820J40859209115.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (150, '技术支持工程师', '南京颖图电子技术有限公司', '3月6日', '5000-8000元', '南京-江宁区', '计算机硬件,计算机软件', '20-99人', NULL, 'CC610697380J00563108403', '▶与销售一同深入行业应用与客户现场，进行行业理解与客户技术需求分析；<br>▶负责制定行业视觉系统解决方案并辅助实施；<br>▶负责提供视觉图像器件和组件产品的现场使用支持及培训服务；<br>▶负责大客户售前、售后服务、用户现场验收、安装调试及培训，维护大客户良好关系；<br>▶能够独立分析、解决行业现场疑难问题<br> <br>任职资格：<br>▶自动化、机电、计算机等相关专业，本科及以上学历，工作经验不限；<br>▶熟悉c++语言和Windows编程，会使用Visual Studio开发环境；<br>▶熟悉Linux操作系统者优先；<br>▶具备图像处理及机器视觉的理论基础和算法知识，熟悉OpenCV或其它图像处理库者优先；<br>▶具有良好的沟通能力、团队意识、协作能力，能适应短期出差；<br>职位福利：五险一金、绩效奖金、员工旅游、周末双休、带薪年假  <br>', '南京颖图电子技术有限公司（以下简称“颖图电子”）成立于2017年，由上海和谦图像技术有限公司控股，致力于提供业界领先的机器视觉摄像机、配套产品，同时为客户提供完整的机器视觉解决方案。所涉及的行业有工业检测、智能交通、高清监控、科学研究等等。作为高新技术企业，颖图办公地址位于江宁开发区，周边优越的产学研环境和多种优惠政策的支持，为公司的发展壮大提供了良好的区位优势。颖图电子以高新技术产品为先导，以科技成果产业化为宗旨，今后将力争不断拓展核心业务，建立领域优势，积累经验，提高水平，为用户提供更优质的服务。', 'https://www.zhaopin.com/jobdetail/CC610697380J00563108403.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (151, '实施工程师', '华工激光', '5月6日', '6000-9000元·14薪', '长沙-浏阳市', '仪器仪表制造,电气机械/电力设备', '1000-9999人', '未融资', 'CC121124210J40478038504', '1、在项目实施中按照客户的要求进行工艺验证及材料性能分析；<br>2、与客户沟通和引导进行工艺方案的制定，并能进行工艺方案审核；<br>3、配合工程师对机器进行改善、为用户提供优质快捷的服务，***程度满足用户的服务需求；<br>4、对项目实施过程中技术支持问题收集和解决及进度控制；<br>5、搜集整理实验数据 ，编写报告专利；<br>6、新工艺应用方向的调研和前沿工艺的学习。<br>该岗位为劳务派遣用工，半年以上的派遣期后才能转内部正式员工，介意者慎投！', '武汉华工激光工程有限责任公司成立于1997年3月，坐落于武汉市东湖高新技术开发区光谷未来科技城未来二路66号华工科技精密微纳智能制造产业园，注册资本为壹拾亿元整，是著名高科技上市公司华工科技产业股份有限公司下属核心子公司。华工激光是中国激光工业化应用的开创者、引领者，全球激光加工解决方案权威提供商。作为中国第一家、全球第二家以激光智能装备为核心、全产业链布局的智能制造系统方案提供商，构筑从激光智能装备，到量测及自动化产线、智慧工厂全方位的智能制造体系。', 'https://www.zhaopin.com/jobdetail/CC121124210J40478038504.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (152, '技术支持工程师', '青岛安然物联网科技有限公司', '7月26日', '8000-16000元', '大同-平城区', '物联网,物联网', '20-99人', '未融资', 'CC559764920J40884196804', '岗位职责：<br>1. 负责石化、化工厂人员定位系统的现场实施、现场交付和技术赋能等工作。<br>2. 对接客户需求，进行需求调研，制定详细的施工方案和计划。<br>3. 确保项目按照既定的时间节点和质量要求完成交付。<br>4. 对已交付的项目进行后期技术支持与维护。<br>岗位要求：<br>1. 年龄在25-35岁之间。<br>2. 能够适应经常出差的工作要求。<br>3. 熟悉信息化、弱电及工业互联网相关技术。<br>4. 具备良好的沟通协调能力和问题解决能力。', '基于精准人员定位的工业安全生产信息化管理专家，安全生产信息化管理引领者！作为全国实时定位技术标准工作组成员和应急管理部“工业互联网+危化安全生产”人员定位系统技术支持机构，安然从2012年起致力于基于ZigBee Plus三维立体按需精准定位的“工业互联网+安全生产”的研究，获得了20多项安全智能管控系统发明专利和著作权，持续引领中国化工行业生产现场智慧安全！安然以“准、稳、狠”的ZigBee Plus三维立体按需精准人员定位统和“底数清、数据准、情况明、研判准、措施实”的安全生产信息化平台为核心，整合访客管理、出入口控制、人脸识别、视频监控、语音广播、重大危险源监控、可燃有毒气体监测等系统，对生产现场人、机、料、法、环五大要素进行实时、动态、智能管控和预警，规范人的安全行为，保障人的生命安全，有效防范风险、主动化解风险，实现智慧安全。安然“以用为本”，把安全生产信息化建设与公司管理体系“深度融合”，把安全生产信息化建设与日常工作“紧密结合”，对安全生产切实“有用、实用、好用”，避免建用“两张皮”，让安全管控更智能，让生产更高效才实用。迄今已服务中石化、中石油、延长石油、国能、兖矿、京能、索普、新安、奇美、昊源、潞安、旭阳、垦利、逸盛、海科、酒钢、金发等几百家石化、化工、选煤、钢铁、电厂企业。安然以客户为中心，以强者为本，抬头乐干，愿意与同道中人联合、链接，携手共建、共用、共享生产安全命运共同体，一起干，一起干，让优秀企业更安全，让优秀企业更高效！', 'https://www.zhaopin.com/jobdetail/CC559764920J40884196804.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (153, '技术支持工程师', '广东恒大新材料科技有限公司', '7月24日', '5000-9000元·13薪', '惠州-惠城区', '化学原料/化学制品,化学原料/化学制品', '300-499人', '未融资', 'CC141743030J40106308015', '岗位职责：  1、 负责公司产品或行业用胶市场信息的搜集、调研、整理及分析，为市场部制定营销策略及市场推广策略提供支持；', '广东恒大新材料科技有限公司成立于1995年，现为国家高新技术企业、中国胶粘剂工业协会会员单位，2003～2006年惠州市第一、二届“民营企业100强”；2004～2011年惠城区第一、二、三、四届“民营企业50强”，是“广东省胶粘剂工程技术研究中心”、“惠州市工程研究开发中心”与“惠州市企业技术中心”的挂牌企业，拥有广东省著名商标与广东省名牌产品荣誉称号。公司现建有两个厂区，位于惠州市惠城区龙丰都田工业区厂区占地13000㎡，建有生产厂房11000㎡和1000㎡的工程研发中心。位于惠州市惠城区下角观音山工业区厂区占地总面积40000㎡，建筑总面积约8400㎡。公司现生产能力达10000吨/年，是我国胶粘剂行业年生产能力过万吨企业之一。公司自成立之日起，不断规范企业管理、勇于开拓市场，长期与国内高校、科研院所保持密切的合作关系，积极进行技术创新，研究开发出一系列处于国内领先地位具有较大影响力的“恒大”牌系列电子装配工业用胶粘剂和光电行业用新型封装材料、“卡夫特”民用密封胶，是一家环境友好型的高科技新材料企业。在光电行业用新型封装材料（如LED、LCD封装胶产品）、桌面型3D打印光敏材料陆续推上市场，就得到广大消费者和光电行业知名企业的肯定，奠定了我司成为国内重要的工程胶粘剂和LED封装材料供应商及技术领先者的地位，销售业务遍及全国，产品为一大批地处珠江三角洲、长江三角洲等地的大型中外知名企业，如：惠州TCL、广州国光、上海飞乐、韩国三星集团、深圳创维、康佳、比亚迪、海信、长虹、雷士照明、松下、亿纬锂能、东莞勤上光电等大型中外企业所采用。公司邮箱：gdhdxkj@126.com', 'https://www.zhaopin.com/jobdetail/CC141743030J40106308015.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (154, '技术支持工程师', '中秀科技股份有限公司', '7月14日', '5000-7000元', '郑州-管城回族区', '医疗设备/器械,医药制造', '100-299人', '未融资', 'CC618987430J40755462411', '岗位职责<br>1、熟悉荧光/发光检测平台，对不同项目的临床应用有一定的了解；<br>2、对接市场，协助市场工程师处理相关售后问题；<br>3、收集市场信息，整理归类产品问题手册；<br>4、对接市场需求，协助营销完成产品推广；<br>5、完成领导安排的临时性工作。<br>任职要求<br>1、本科及以上学历，生物类相关专业优先；<br>2、工作严谨，计划性强，善于分析思考问题，有责任心；<br>3、有较强的维护协调客户的能力，能适应短期出差；<br>4、具备较强的学习能力，可快速掌握专业知识，及时开展工作；<br>5、勤奋踏实，良好的服务意识与团队合作精神；<br>6、有IVD研发工作经验者优先。<br>职位福利：六险一金、提供午餐、周末双休、项目奖金', '中秀科技股份有限公司，始建于2016年，位于河南省长垣市丁栾工业区，公司占地面积约100亩，前期投资额约2亿元。公司在郑州市经开区设有研发中心，核心研发人员约50人，硕士学历占比25%。公司拥有科学完善的管理制度、国家标准的净化车间、功能完备的检验中心。在此基础上，公司将持续投入研发、积累技术实力、更新制造设备、改进生产工艺、提高检验技术、提升产品质量，为顾客提供安全、有效的体外诊断产品。中秀科技股份有限公司是一家从事体外诊断产品研发、生产、经营的高新技术企业，公司研发的体外诊断产品涵盖POCT系列、免疫系列等试剂及配套的仪器。公司始终坚持“快速精准，不负生命”的核心理念，致力于为社会提供卓越的产品和服务，为人类的健康事业做出贡献。', 'https://www.zhaopin.com/jobdetail/CC618987430J40755462411.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (155, '硬件测试', '湖北省爱和瑞科技有限公司', '5月17日', '5000-8000元', '武汉-洪山区', '仪器仪表制造,电子设备制造', '20人以下', '未融资', 'CCL1389048440J40806732208', '工作内容：测试传感器性能参数，编辑产品datasheet，完善传感器测试条件，客户技术解答，项目对接。<br>任职要求：<br>1、大专及以上学历；<br>2、理工科<br>3、熟练掌握office软件；<br>4、会设计电路板<br>公司福利：<br>待遇5-6k元+餐补，买五险，有年终奖，工作环境好，周末双休，早九晚六，从不加班。<br>职位福利：五险一金、绩效奖金、全勤奖、员工旅游、周末双休、节日福利、餐补、带薪年假 <br>职位亮点：双休 不加班', '湖北省爱和瑞科技有限公司成立于2013年的高新技术企业，主要致力于气体传感器的研发、生产和销售。产品品质优秀，销量逐年增高。主要核心产品为电化学气体传感器。企业持续为员工、客户、投资人和社会创造更美好的明天。期望认真、积极、踏实的人才与公司共同成长，公司将不会辜负各位的努力付出，分享公司的成果，一起拥有一份美好的事业。', 'https://www.zhaopin.com/jobdetail/CCL1389048440J40806732208.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (156, '科研人员', '香港中文大学深圳研究院', '6月16日', '9000-13000元', '深圳-南山区', '政府/公共事业,学术/科研,科学技术推广', '100-299人', '不需要融资', 'CC224678420J40684192206', '职位概述：负责经济理论、经济政策方面的研究和数据分析。主要工作内容： <br>1、协助团队开展经济理论、经济政策方面的研究和数据分析； <br>2、负责文献及其他数据搜集整理工作； <br>3、协助团队进行经济实验相关工作； <br>4、完成上级交代的其他工作任务。', '2007年5月，在深圳市的支持下，香港中文大学在深圳设立香港中文大学深圳研究院（简称“深研院”）。深研院主体大楼坐落于深圳虚拟大学园国家大学科技园内，于2011年11月落成并投入使用。大楼建筑面积约2.5万平方米，地上建筑9层，设有大型演讲厅、培训课室、科研实验区及培育中小企业工作区等不同的应用区域，为科学研究，人才培训、产业合作及技术转移等提供场地和设施。学研提升结合国家科技发展规划与深圳市科技发展需求，深研院重点推动生物医药、信息科技及可持续发展等领域的科研发展。目前，香港中文大学深圳研究院已建立3个国家重点实验室的深圳基地，包括消化疾病研究国家重点实验室深圳研究基地、农业生物技术国家重点实验室深圳基地、再生医学教育部重点实验室深圳基地，另有4个深圳市重点实验室及3个深圳市工程实验室。经过数年悉心发展，深研院的科研实力获得了国家的认可，作为国家、省市项目的依托单位，已承担各级科研项目500余项。此外，深研院积极推动产学研合作，重视横向项目的合作与发展，利用优秀的研究平台和研究资源，吸引科研项目落地，并通过与外部机构合作，在促进科研产业化的同时进一步提升科研水平。人才培育深研院依托中大的优势师资资源和深厚的教学、科研基础，结合深圳市乃至全国范围内对高层次、专业化、国际化人才的需求；延续中大中英兼重、多重文化的教育传统，策划并开展各类面向全社会、适合本地经济社会发展的培训工作，旨在为深圳、粤港澳大湾区乃至全国培养优秀人才，为业界在相关领域的技术进步提供良好的技术与理论支持。深研院积极配合与落实深圳市政府有关高层次人才就业的系列政策，推动博士后入站、高层次人才认定等相关工作。此外，深研院不定期开展国际学术研讨会及讲座，在提升人才专业技能的同时促进不同行业间专业人士的沟通、交流，为培育高端人才搭建高层次的平台。全球接轨深圳作为大湾区中最具创新活力的城市之一，深研院通过举办国际性的论坛、研讨会、工作坊等，吸引全球各地来自不同领域的人才聚首深圳，为学术研讨提供国际性视野和平台，推动国际高端技术成果、项目的落地。截至2023年12月，深研院已经成功举办深圳·联合国气候峰会COP28新机遇大会、粤港澳大湾区发展论坛、中以合作创新论坛、3D打印与再生医学国际论坛暨工作坊等国际性的学术活动。吸引了来自中国大陆、港澳台、德国、以色列、英国、美国等不同国家或地区的学者的积极响应和参与。创新发展深研院立足地方产业发展的技术优势，不断激发科技活力和推动技术成果高效转化；坚持“技术创新，开放共享”的理念，持续加强与社会各界的合作创新。此外，深研院通过引进大学系统、健全的知识产权和技术转移管理体系，在为横纵发展和科研团队管理提供完备服务与指引的同时，积极探索科研机构、科研项目管理和技术转移的新模式。深研院于2018年成立众创中心，中心立足于本地，进行初创公司的培育孵化，旨在形成创业生态系统，促进深港两地产学研深入合作，以带动新一代信息技术、生物科学、智能制造等战略性产业的创新和发展。', 'https://www.zhaopin.com/jobdetail/CC224678420J40684192206.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (157, '科研人员', '曼迪匹艾(北京)科技服务有限公司', '2月6日', '1-1.9万', '北京-海淀区', '新闻/出版,学术/科研,新闻/出版', '1000-9999人', '未融资', 'CC207292010J40214605812', '一、岗位优势<br>1. 行业前景向好：全球学术开放获取出版的先驱；<br>2. 期刊领域广泛：300多种科技期刊，各类专业均可学以致用；<br>3. 注重新人培养：Open Course公开课、一对一Tutor指导、专业技能培训，快速实现角色转变；<br>4. 晋升机制成熟：业务、管理双渠道发展，提供完善的职业发展平台；<br>5. 发展机会多样：公费出国，海外中短期交流；鼓励兼任，内部资源充分共享；<br>6. 打造学习型组织：搭建多维学习平台，线上线下齐开课，碎片时间也能不断充电涨知识；<br>7. 团队专业素质高：深度接触开放获取出版行业，实时掌握前沿科技研究成果，与志同道合的小伙伴组建团队等。<br>二、工作职责<br> 1. 负责联系专家学者，组织稿件的同行评审，确保稿件的同行评审及时完成；<br> 2. 编排和处理稿件，确保稿件格式正确，及时发表；<br> 3. 与期刊主编，编委成员，作者及审稿人建立良好沟通，确保期刊正常运作，稿件顺利及时发表；<br> 4. 关注期刊学科领域内的研究进展，协助期刊责任编辑完成期刊发展目标。<br> <br>三、职位要求<br> 1. 理工类相关专业背景；<br> 2. 本科及以上学历；<br> 3. 英语六级；<br> 4. 熟练office办公软件；<br> 5. 学习能力强，能适应公司高强度职业培训，例如：参加职业培训讲座和一对一导师培训管理。<br>四、薪资福利<br> 1. 薪酬待遇：月基本工资10000-19000；<br> 2. 基础福利：六险一金，带薪年假，年度体检，节日福利，活动经费，丰富茶歇，营养晚餐等；<br> 3. 进阶福利：子女福利，父母福利，团队奖励，培训津贴，岗位津贴；<br> 4. 职业发展：导师培养，技能培训，管理培训，优秀员工提供出国交流和工作机会。<br> 五、办公地点<br> 北京市海淀区花园路甲13号庚坊国际发展中心4层<br> 乘车路线：地铁10/19号线-牡丹园站D口，步行900米', '瑞士MDPI出版公司（Multidisciplinary Digital Publishing Institute）成立于1996年，是一家全球领先的开放获取期刊出版公司，总部位于瑞士巴塞尔，同时在中国，西班牙，塞尔维亚，英国，日本，罗马尼亚，加拿大，波兰以及新加坡设有分公司。在中国设有7个办公室，分别位于北京通州，北京海淀，湖北武汉、天津、江苏南京、湖北光谷和辽宁大连。成立至今，已创办英文科技期刊390余个，其中包括Molecules, Sensors, International Journal of Molecular Sciences, Marine Drugs等近90余种SCIE期刊。曼迪匹艾（北京）科技服务有限公司成立于2008年，主要负责 MDPI出版公司的编辑服务工作，现有正式员工1500余人，其中硕博1200余人。2013年4月成立武汉代表处：曼迪匹艾（武汉）科技服务有限公司，现有正式员工1200余人，其中硕博600余人。2019年9月成立天津代表处：曼迪匹艾（天津）科技服务有限公司，现有正式员工600余人，其中硕博370余人。2021年5月成立南京代表处：曼迪匹艾（南京）科技服务有限公司，现有正式员工230余人，其中硕博170余人。2021年7月成立光谷代表处：曼迪匹艾（光谷）科技服务有限公司，现有正式员工300余人，其中硕博290余人。2021年10月成立大连代表处：曼迪匹艾（大连）科技服务有限公司。在MDPI，你的梦想有多大，舞台就有多大，赶快加入我们吧！企宣：https://v.qq.com/x/page/d33027h4a9j.html', 'https://www.zhaopin.com/jobdetail/CC207292010J40214605812.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (158, '技术支持工程师', '青岛安然物联网科技有限公司', '2月12日', '8000-14000元', '济南-历下区', '物联网,物联网', '20-99人', '未融资', 'CC559764920J40823511204', '需要弱电技术、自动化、安防系统、工业互联网+危化安全生产、物联网人才，不要纯软件人才。  你能经常到全国各地出差吗？你能到工业生产现场生产现场做技术支持吗？  <br>真正的奋斗者在安然会有让人值得为之奋斗的事业，会有充实、高效的成长，会有高人一等的收入。  <br>你能做好售前技术支持、根据客户需求，高效制作方案吗？你能做好售中技术支持、指导他人正确安装、部署、调试系统向用户保质保量快速交付吗？你能做好售后维护，高效沟通和落实客户需求吗？  <br>迄今已服务中石化、中石油、延长石油、国能、兖矿、京能、索普、新安、奇美、昊源、潞安、旭阳、垦利、逸盛、海科、酒钢、金发等几百家石化、化工、选煤、钢铁、电厂企业。\n  <br>安然以客户为中心，以强者为本，抬头乐干，愿意与同道中人联合、链接，携手共建、共用、共享生产安全命运共同体，一起干，一起干，让优秀企业更安全，让优秀企业更高效！', '基于精准人员定位的工业安全生产信息化管理专家，安全生产信息化管理引领者！作为全国实时定位技术标准工作组成员和应急管理部“工业互联网+危化安全生产”人员定位系统技术支持机构，安然从2012年起致力于基于ZigBee Plus三维立体按需精准定位的“工业互联网+安全生产”的研究，获得了20多项安全智能管控系统发明专利和著作权，持续引领中国化工行业生产现场智慧安全！安然以“准、稳、狠”的ZigBee Plus三维立体按需精准人员定位统和“底数清、数据准、情况明、研判准、措施实”的安全生产信息化平台为核心，整合访客管理、出入口控制、人脸识别、视频监控、语音广播、重大危险源监控、可燃有毒气体监测等系统，对生产现场人、机、料、法、环五大要素进行实时、动态、智能管控和预警，规范人的安全行为，保障人的生命安全，有效防范风险、主动化解风险，实现智慧安全。安然“以用为本”，把安全生产信息化建设与公司管理体系“深度融合”，把安全生产信息化建设与日常工作“紧密结合”，对安全生产切实“有用、实用、好用”，避免建用“两张皮”，让安全管控更智能，让生产更高效才实用。迄今已服务中石化、中石油、延长石油、国能、兖矿、京能、索普、新安、奇美、昊源、潞安、旭阳、垦利、逸盛、海科、酒钢、金发等几百家石化、化工、选煤、钢铁、电厂企业。安然以客户为中心，以强者为本，抬头乐干，愿意与同道中人联合、链接，携手共建、共用、共享生产安全命运共同体，一起干，一起干，让优秀企业更安全，让优秀企业更高效！', 'https://www.zhaopin.com/jobdetail/CC559764920J40823511204.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (159, '科研人员', '湖南潇湘人力资源服务有限公司', '6月30日', '1-2万', '南京-浦口区', '人力资源服务,培训/辅导服务,房地产中介,计算机硬件', '300-499人', 'B轮', 'CC419440410J40707373916', '博士硕士以及有留学经历的学士引进，需要博士硕士及有留学经历的学士人员参加，加入硕博高层次人才库，有愿意参加地方启*人才、领*人才、泰*人才 、火*人才、招才引智计划、海外优才计划等项目，都可以投递简历，可专职兼职灵活参加各各类**、企业、高校等项目，欢迎国内外博士硕士及有留学经历的学士人才投递简历（（学士报名必须有中留服认证，硕士博士可直接报名），可专兼职参加。 本公司有丰富的博士硕士人才库，有博士硕士项目也可洽谈沟通。', '湖南潇湘人力资源服务有限公司，系经工商行政管理局批准设立的，具有独立企业法人资格，并经人力资源和社会保障部批准备案，具有合法人力资源服务资质的，专业人力资源服务机构。公司积极响应国家号召，搭建供需平台，畅通就业渠道，充分发挥人力资源机构在促进就业中的积极作用，多渠道扩大就业。公司致力于打造成为立足湖南、覆盖全国的综合性专业人力资源服务供应商，依托于招聘会场和网络平台，为各企事业单位开展现场招聘、网络招聘、报纸招聘、代理招聘、招聘外包、劳务派遣、高级人才猎头和人力资源管理咨询等专业配套服务；为求职个人提供职业咨询、职业指导、职业介绍等就业服务。公司现场招聘平台--湖南招聘市场，于每周六、周日在贺龙体育场东门举办招聘会，欢迎各企事业单位和各类人才通过现场直面交流，我们将以专业、专注的精神，为您招才、择业，提供全面、优质的服务！招聘热线：400-000-7318、0731-83759001/02/03/04/05/06/07/08/09/10招聘会场：贺龙体育场正东门--湖南招聘市场(芙蓉中路、侯家塘北、摩天轮广场上台阶)乘车路线：1：乘105、115、150、159路至“侯家塘北”2：乘101、104、701、702、703、905路、长株潭201路至“侯家塘-芙蓉中路”3：乘旅2、2、4、8、104、123、137、140、145、160、202、314、402、601、803、804、906、908路至“侯家塘西”往芙蓉路至“侯家塘北”详情请访问： http://www.hnzpsc.com', 'https://www.zhaopin.com/jobdetail/CC419440410J40707373916.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (160, 'C/C++', '中智河南经济技术合作有限公司', '7月24日', '5000-8000元', '洛阳-洛龙区', '咨询服务,专业技术服务', '20-99人', '未融资', 'CC530229020J40792705305', '该岗位为光电所(613所)外包岗位<br>一、岗位职责：<br>负责软件设计协调与沟通、软件集成与测试、联试等技术保障工作<br>二、聘用条件：<br>统招本科以上学历，软件工程、计算机科学许技术等理工科专业； 具有良好的C/C++软件基础，有较强的逻辑判断和执行能力、文字和语言表达能力和沟通协调能力、熟练使用OFFICE办公软件；  <br>   30岁以下，应届毕业生优先   <br>三、薪资待遇：   <br>薪资：月薪5000-8000，具体面议；   <br>福利：五险一金，入职即办理社保五险，两年后办理公积金；   <br>四、工作地址：   <br>洛龙区王城大道696号（洛阳电光设备研究所）   <br>   <br>', '中智河南经济技术合作有限公司（以下简称“中智河南公司”），是国务院国资委直属中央企业——中国国际技术智力合作集团有限公司在河南地区的唯一全资子公司。中智河南公司成立于2012年10月，省级总部设立在郑州市郑东新区。2017年，被中国人社部评为“全国人力资源诚信服务示范机构”；2016-2019年，被河南省人社厅评为“河南省人力资源诚信服务示范机构”；2018年被郑州市政府评为“郑州市总部企业”；2019年，被中国企业联合会、企业家协会评为“企业信用评价AAA级信用企业”；2020年，被郑州市郑东新区管委会评为年度经济贡献“先进企业奖”；2021年被河南省企业联合会、企业家协会评为“河南省服务业企业100强”。作为中国专业的人力资源整体服务供应商，我们的服务内容主要有：业务外包、人事代理、劳务派遣、薪酬财税、健康福利、招聘及灵活用工、管理咨询、国际人力资源服务、人力资源技术服务及其他业务。我们的客户覆盖外资企业、中央企业、省属国有企业、上市公司、民营企业等多类实体和机关事业单位，横跨电力、金融、保险、通讯、电子、IT、汽车、医药、地产、制造、商贸、传媒、快速消费品等诸多领域，规模效益领先。为实现“立足郑州，布局全省”目标，我们已在河南省18个地市均开立了分公司或设立了五险一金账户，实现了河南省内全区域服务能力。同时，我们依托中智集团的全国网点布局平台，对省外委托服务可覆盖至全国370多个城市。中智河南公司自成立以来始终秉承“全员市场营销、全员服务领先、绩效管理文化、和谐创新发展”的文化理念，以“创业精神”为根基，“狼性精神”做驱动，致力于“打造区域强企，实现智领中原”，持续实现“政府推崇，客户信赖，雇员满意，业绩突出，员工幸福”的终极发展目标。作为中央企业，中智河南公司在全国疫情和河南汛情面前充分展现了央企责任担当，同时在全国人力资源服务业发展大会中积极参与政府合作交流、提升品牌知名度。未来，中智河南公司将继续以专业优势履行央企社会责任，立足于中原、服务于河南，持续发挥央企引领示范作用，通过专业的人力资源服务，推动中原地区政府、机关事业单位等解决社会就业，提升企业选人、育人、派人、留人的更快速发展方面，贡献中智更多力量。', 'https://www.zhaopin.com/jobdetail/CC530229020J40792705305.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (161, '前端开发', '郑州中业科技股份有限公司', '7月25日', '1.2-1.6万', '郑州-中原区', '互联网,互联网,人工智能', '20-99人', '已上市', 'CC385902710J40448421414', '职责描述：<br>  <br>1、优化前端开发方式及协作流程、技术标准及规范；<br>  <br>2、为前后端技术改进、网站性能优化、技术选型提供解决方案；<br>  <br>3、为组内的技术成长制定目标、计划并帮助实施，提升整体技术水平；<br>  <br>4、同时兼备服务端接口开发能力；<br>  <br>5、领导前端团队，负责任务拆分、技术指导、团队管理等。<br>  <br>任职要求：<br>  <br>1、硕士及以上学历，计算机或相关专业优先；<br>  <br>3、精通HTML/CSS/Javascript基础扎实；具备服务端开发能力如Python、Node、Java等<br>  <br>4、持续关注业界的新话题和新技术，研究过react/vue/angular等框架，至少精通其中一种；<br>  <br>5、对前端工程化与模块化有所掌握，并有实践经验（RequireJS/SeaJS/webpack等），重视团队协作，愿意探寻和改进目前还不成熟的前端开发流程，了解各种常用工具;<br>  <br>6、有大型网站前端架构、前端性能、可访问性、可维护性等方面的实践经验；<br>  <br>7、较强的自我管理能力，抱有积极的学习心态，乐于分享知识，喜欢沟通，逻辑清晰；<br>  <br>8、热爱前端技术，个性乐观开朗，逻辑性强，有一定的项目管理、团队协同经验者优先。<br>', '郑州中业科技股份有限公司(股票代码:834134)是一家专注于认知智能」领域的人工智能企业。公司通过大数据与人工智能算法相结合,围绕深度学习、知识图谱、自然语言处理、大数据治理等核心技术,为全球企业级用户提供人工智能场景化解决方案。在A+医疗领域中业科技通过对海量医学数据进行采集、处理、分析,利用人工智能技术构建算法模型,能够极大提高医院的科研实力、诊疗质量和管理水平,产品涵盖医学影像、辅助决策、精准医疗、健康管理、医疗信息化、医学研究等领域,可为各级别医院的不同科室提供定制化服。公司通过产品和服务聚焦，形成标准化产品和服务，强化与京东方、第四范式、昆明儿童医院等行业代表性客户关系，形成合作生态产业链。以代表性行业客户为依托，对智慧医疗、社交网络等行业及类行业客户进行深耕挖掘和产品线扩张，以打造细分行业龙头。公司先后荣获“通过CMMI5级认证”“河南省优秀软件产品”、“河南省优秀软件企业”“河南省优秀民营成长创新型企业”、“河南省人工智能创新型企业”、“河南省新三板30强”、“河南省优秀非公有制企业”、“河南省最具潜力互联网企业十强”和“中国人工智能大赛第六名”等荣誉。中业科技实施精细化人才培养，优化人才布局，提升人均效益。公司作为国家级高新技术企业，通过了“郑州市企业技术中心”、“郑州市自然语言处理工程技术研究中心”两项市级研发平台认定，并在2020年取得“河南省NLP人工智能自然语言处理工程技术研究中心”省级平台的认定；同时相继取得“河南省专精特新中小企业”和“国家级专精特新小巨人企业”的认定。并获得了第七届中国创新创业大赛二等奖、河南省中小企业创新创业大赛十强的好成绩。目前，公司获得各类专利9项，PCT专利1项（含已受理），已授权软件著作权130件；参与制修订国家标准1项，发表论文2篇。参与编撰《中国人工智能标准化白皮书（2021版）》、《人工智能行业标准（2020版）》，并且正在参与编撰《人工智能教育行业标准》、《人工智能信息技术行业标准》。', 'https://www.zhaopin.com/jobdetail/CC385902710J40448421414.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (162, '实施工程师', '南京高速齿轮制造有限公司', '7月22日', '1-1.2万·15薪', '南京-江宁区', '通用设备制造', '1000-9999人', '已上市', 'CC230197010J40795878505', '岗位职责:<br>1、依据PLC、CNC、自动化线、传感器设备的数据采集方案，调试Modbus、S7、OPC UA等工业协议，配置设备采集系统；<br>2、参与生产现场自动化控制系统（如PLC、HMI、DCS）的基础维护与技术支持；<br>3、利用数据分析工具（如 SQL, Python, Excel 高级功能，或BI工具如 Power BI, Tableau 基础应用)，对采集到的设备运行数据、工艺过程数据、生产业务数据（如OEE、产量、质量、能耗）进行清洗、整理与初步分析；<br>4、编写和更新相关技术文档、操作手册及维护记录。<br>任职要求:<br>1、硕士及以上学历，自动化、机械设计制造及其自动化、机械电子工程等工科专业；<br>2、熟悉工业数据采集和传输技术，了解OPC、Modbus、S7等通讯协议；<br>3、了解PLC基本原理，用过至少一种主流组态软件（SCADA/HMI）的配置与使用；<br>4、掌握 Excel 高级功能（公式、图表、透视表），了解 SQL 数据库基础操作（查询、增删改）。有使用 Python进行数据处理分析经验者优先;<br>5、有相关实习经验、课程设计、学科竞赛（如智能制造、工业互联网、机器人相关）获奖经历者优先考虑。<br>公司优势：行业领先、上市公司、发展前景好、发展通道完善、专业培训、管理规范<br>福利体系：全额五险一金、公积金12%、签约服务奖2w、补充医疗保险、免费班车、免费工作餐、员工公寓、带薪年假、节日礼金、高温补贴、年终奖金、定期体检、子女福利、社团活动', '南高齿集团以“为人类文明传递进步动力”为己任，致力于为全球用户提供齿轮箱与传动技术解决方案。公司始于1969年，隶属于港股上市公司“中国高速传动（00658.HK）”，现有员工7000余名，业已成为涵盖风力发电、工业智能装备、机器人减速机、新能源汽车等领域的全球齿轮传动领军企业，旗下品牌“NGC”是江苏省重点培育和发展的国际知名品牌。主要荣誉有：制造业单项冠军示范企业、国家技术创新示范企业、中国品牌500强、Windpower Monthly 2022年度最佳传动链金奖、500+个有效专利、100+个国家及省、市级荣誉奖励。', 'https://www.zhaopin.com/jobdetail/CC230197010J40795878505.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (163, '测试工程师', '深圳赫兹创新技术有限公司', '4月8日', '8000-13000元', '深圳-宝安区', '电子/半导体/集成电路,仪器仪表制造,电力/水利/热力/燃气', '20-99人', 'A轮', 'CC885699660J40775216803', '岗位职责<br>1、对中大功率无线电能传输产品进行产品功能测试、系统测试、性能测试、集成测试；<br>2、对单板、关键元器件进行测试，对来料进行测试和检查；<br>3、配合硬件工程师、软件工程进行技术方案验证；<br>4、配合实施工程师模拟客户现场环境测试；<br>5、协助外部认证测试机构的认证测试；<br>6、设计、整理测试用例；编写测试计划；执行测试计划。<br> 7、记录测试结果，编写测试报告，测试分析报告；', '深圳赫兹创新技术有限公司（Shenzhen Hertz Innovations Technology Co. Ltd）是国家高新技术企业，科技型中小企业，创新型中小企业。公司坐落于深圳市宝安区华丰国际机器人产业园。公司主要由两家与动力电池、汽车电子相关的A股上市企业高管投资设立，注册资金2105万元。公司专注于为工业及汽车应用领域提供中大功率无线电能传输（WPT，Wireless Power Transfer，包含无线充电、无线供电（也称非接触供电，CPS, Contactless Power Supply)）技术及产品解决方案，矢志成为中大功率无线充电、无线供电(非接触供电）技术的领导者，为客户实现“电能无线，自由无限”的应用场景，赋能无人化。赫兹创新（HzI）以产品技术创新为企业发展的核心理念，是全球少数几家能够提供大功率非接触供电技术和产品的公司。公司正在打造一支专业素质高、创新能力强的技术研发团队，主要研发成员来自国内知名大学无线充电技术研究团队以及该领域的知名企业，核心成员是国内无线电能技术研发及应用的开拓者。公司在无线电能传输效率提升、逆变控制和调节，大规模非接触供电应用网络，多对多无线充电、异物检测、防辐射、电气安全保护、应用创新等方面拥有核心技术，已申请并获得30项余发明专利授权、20余项实用新型专利授权及8件软件著作权。公司把产品的可靠性和质量视为企业发展根本，无论在研发和生产上都以质量优先，公司通过了ISO 9001质量认证体系，产品通过了安规、CE、CR等认证，公司还通过了ISO14001等标准的认证，产品代工厂通过IATF16949等质量认证体现的认证。赫兹创新（HzI）提供静态无线充电主要应用范围覆盖服务机器人、巡检机器人、清扫机器人、AGV、无人清扫车、无人送货车、无人售货车、各类需要防爆、防水充电的设备，乘用车等等；公司的非接触供电技术和产品主要应用在半导体及液晶面板洁净车间的AMHS（Automatic Material Handling System）系统，包括OHT（天车）、STK（晶圆FOUP及面板的存储系统）、OHS（穿梭车）、OHCV等系统，物流分拣先、RGV、直线电机及磁悬浮智能自动化产线等应用；产品功率范围覆盖50W到数十千瓦(KW)，可以满足客户的个性化定制需求。赫兹创新（HzI）秉持开放共赢的合作理念，愿与生态链上的合作伙伴密切合作，高效协同，推动应用创新，为终端客户提供领先的解决方案和优质的服务。', 'https://www.zhaopin.com/jobdetail/CC885699660J40775216803.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (164, '实施工程师', '江苏瑞洋安泰新材料科技有限公司南京分公司', '7月20日', '8000-16000元', '淮安-淮安区', '石油/石化,环保', '100-299人', '未融资', 'CC655052130J40639692312', '外贸技术服务协助国际业务部门，给客户提供多样化的技术支持，解决客户的痛点和难点，满足客户的需求，让客户做好胶产品，让我们的树脂成为客户的选择。<br>岗位职责：<br>1、对接国际业务部门，为客户提供解决方案，让我们的产品成为客户的选择<br>2、了解国际市场和客户的需求，收集国外STP树脂新的应用点，汇总反馈形成报告<br>3、国际业务售前技术文档的安排、细化、完善和归档<br>4、收集市场和客户的信息，了解国外行业发展的趋势<br>5、提供行业会议或展会等需求的展示样品<br>任职资格 基础要求：<br>本科学历以上<br>具有化工类或材料相关专业<br>良好的英语口语和书面沟通能力<br>具有化工行业相关的工作经历，对化工行业有一定的认识<br>有团队协作能力，责任心强，沟通学习能力 <br>薪资福利：<br>1、基本工资+津贴+奖金<br>2、包吃包住<br>3、五险<br>4、体检<br>5、传统节日发放福利', '江苏瑞洋安泰新材料科技有限公司是一家专业从事改性聚醚树脂(STP)和纺织助剂研发、生产、销售的新材料化工企业，纺织助剂事业部成立于2001年，STP事业部成立于2011年。STP树脂的目标客户是国内外密封胶、胶黏剂以及表面涂层生产厂家，纺织助剂的目标客户是国内知名品牌印染纺织企业，我们提供配套信息技术、初始配方建议、现场支持等帮助客户开发产品。瑞洋安泰一直重视研发、技术储备、人才储备，目前在美国费城，澳大利亚墨尔本，中国淮安分别设立了3个研发中心。2016年已正式完成内部产业升级改造，淮安盐化产业园区10万平方、年产能10万吨全自动化新生产基地正式投产，8000多平方的现代化仓储物流基地位于泰州白马工业园区，行政销售中心位于南京鼓楼区南大苏富特科创园。国家越来越重视环保，我公司加大对环保新材料的研发力度，不断研发生产出新型环保材料，产品颇受市场好评，业务激增。科技让世界变得更环保，我们诚邀您的加入，一起实现我们的光荣与梦想！', 'https://www.zhaopin.com/jobdetail/CC655052130J40639692312.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (165, '测试工程师', '广东威力电器有限公司', '7月23日', '6000-8000元·13薪', '中山-None', '耐用消费品', '1000-9999人', NULL, 'CC141230000J40725182414', '岗位职责：<br>1. 负责洗衣机整机的测试工作，确保产品性能和质量符合标准。<br>2. 对测试过程中出现的问题进行记录、分析，并提出改进建议。<br>岗位要求：<br>1. 大专以上学历。<br>2. 有2年家电产品测试经验。<br>3. 能适应产品大而重的工作环境。<br>4. 工作及学习态度积极，认真负责。', '中山东菱威力电器有限公司成立于1980年，专业从事洗衣机、微波炉、制冷等家电产品的研发、制造、销售，现有员工4500余人，其行业产品地位为微波炉全国前三、制冷小家电全国第一，洗衣机国内品牌前十。威力荣获“国家一级企业”、“中国驰名商标”荣誉；是国家高新技术企业，广东省优势传统产业转型升级示范企业。被认定为“广东省企业技术中心”、“广东省工程技术中心”、“中山市新型研发机构”，“中山市龙头骨干企业”。', 'https://www.zhaopin.com/jobdetail/CC141230000J40725182414.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (166, '科研人员', '黑龙江大数据产业发展有限公司', '7月23日', '1.5-2.4万', '哈尔滨-南岗区', '计算机软件,IT服务,计算机硬件,互联网', '20-99人', '不需要融资', 'CC531499030J40758767411', '重点招收计算机科学与技术、人工智能、大数据等领域2名科研人员，形成需求牵引的完全开放的基础研究平台和国家高端特色科技智库。', '黑龙江大数据产业发展有限公司组建于2017年6月28日，是由黑龙江省建设集团与北京九次方大数据信息集团、北京瑞德佳通科技有限公司合资成立的国有控股混合所有制企业。公司成立以来，始终遵循国家关于“推动实施大数据战略，加强完善数字基础设施，推进数据资源整合和开放共享，保障数据安全，加快建设数据中国”的规划部署，坚持以“成为卓越的数据资产运营商”为发展愿景，以“贡献数据智慧，释放数据价值”为企业使命，以“发展企业、幸福员工、服务社会”为核心价值观，以“立足龙江、面向全国”为市场定位，努力成为政府及行业垂直领域的大数据运营商，精准高效地为政府决策治理、社会产业发展、民生建设等各个领域提供优秀的数据产品和优质的数据服务。', 'https://www.zhaopin.com/jobdetail/CC531499030J40758767411.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (167, 'C/C++', '外企德科数字技术有限公司', '2025-07-27 00:23:26', '1.8-3.5万·14薪', '东莞-None', '专业技术服务', '10000人以上', NULL, 'CCL1480117890J40701125505', '招聘通用软件开发或者软件测试，数据仓库数据开发数据分析岗位都有。<br>Java、c、c++、Python、前端web、js，golang，算法工程师， 、大数据开发，软件测试，测试开发，嵌入式，鸿蒙，深度学习，机器学习等相关岗位在 南京，杭州，苏州，深圳 ，东莞， 上海 ，西安， 北京，武汉，成都，长沙，济南，都有办公处。<br>业务技能要求：<br>1、熟练掌握C/C++、Java、Scala、Python、go，JS 等开发语言一种或多种<br>2、学习了解软件工程、常见数据结构与算法等知识；<br>部门有偏软件的也有偏硬件的，或者软硬件结合业务', '外企德科数字技术有限公司是一家2023年新成立的中外合资企业。成立于2023年11月24日，公司定位：专注于为信息技术企业提供人才及数字技术外包解决方案的中外合资企业。它是由中国人力资源服务行业的FESCO（北京国际人力资本集团）与全球人力资源服务领导者The Adecco Group（德科集团）合资成立的。公司主要提供网络技术服务、软件外包服务、计算机系统服务、技术进出口、软件开发等信息技术相关服务。专注于为信息技术企业提供信息技术类人才及数字技术外包解决方案。', 'https://www.zhaopin.com/jobdetail/CCL1480117890J40701125505.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (168, '实施工程师', '山西慧源人才服务有限公司', '7月17日', '5000-9000元', '太原-小店区', '人力资源服务', '100-299人', '不需要融资', 'CCL1481513340J40757502809', '（一）岗位要求<br>1、机械工程、机电工程、电气工程、车辆工程、机电一体化、矿山机电、液压等工科相关专业大专及以上学历，本科优先，应届生可以报名；<br>2、具备扎实的专业基础知识，具备协作能力和沟通能力。<br>3、熟练使用办公软件。<br>（二）岗位职责<br>1、参与公司燃油车和新能源车辆的调试和技术支持等工作。<br>2、负责整理和更新车辆相关的调试、安装工艺、售后故障统计及处理技术文档。<br>薪资福利<br>月薪5000-9000元；缴纳五险。<br>工作时间<br>8：30—12：00；13：30—17：30。', '慧源集团成立于2005年，立足山西，辐射全国，为机关、企事业单位提供人才派遣、业务外包、商保服务、助残就业服务、招聘服务、考试外包、人才测评、背景调查、HR培训、人力资源研究、档案数字化管理等全产业链人力资源服务。累积为机关、企事业单位服务500万余人次，服务单位万余家，成功推荐中高端管理及专业技术岗位人员10万余人。', 'https://www.zhaopin.com/jobdetail/CCL1481513340J40757502809.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (169, 'C/C++', '鄱阳县黑金刚钓具有限责任公司', '2025年07月28日', '4000-8000元·13薪', '上饶-鄱阳县', '农/林/牧/渔', '100-299人', NULL, 'CC522814520J40762217514', NULL, '江西鄱阳自古以来有着制作鱼钩的传统，中国90%以上的鱼钩产自鄱阳，鄱阳湖丰茂的淡水渔业资源，孕育了这一传统产业在不断创新中茁壮成长。坐落于鄱湖之滨的黑金刚钓具，自1856年至今历经六代传承，作为一家专注于技术创新型的鱼钩研发与制造企业，黑金刚已在产品开发、工艺创新、材料创新、精密自动化制造方面达到国际领先水平，并在2019年成为国家鱼钩行业标准的主要定标企业，与此同时，黑金刚所属的BKK品牌，已成为国际鱼钩市场上“专业级”、“赛事级”、“核心技术”的代名词。作为目前国内规模最大的鱼钩生产企业，黑金刚为进一步夯实国际化发展的基础，黑金刚已先后在日本等海外市场设立分子公司，并于2019年在上海设立了全球总部，进一步强化从产品研发、市场、品牌、到供应链、信息化、企业经营的管理升级。黑金刚在快速成长的过程中，极为重视人才队伍建设，积极推进“以奋斗者和创造者为本”的人才理念。黑金刚并不满足目前已获得极佳口碑的“中国制造”，我们立志通过努力，成为全球鱼钩行业中“中国智造”的领跑者，这个团队，需要自信的你的加入和助力，不论男女、不分肤色，让我们共同去圆一个“百年黑金刚”的制造业帝国的梦想！黑金刚的过往殊荣：连续五年蝉联CHINA FISH最佳产品奖 AFTA TRADE SHOW最佳渔具配件类产品奖 Good Design Award最佳优良设计奖 CAA2017国家级钓具赛事合作伙伴 LTW国际路亚大奖赛官方战略合作伙伴中国钓具制造行业（钓钩类）示范生产企业', 'https://www.zhaopin.com/jobdetail/CC522814520J40762217514.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (170, '前端开发', '中能(济南)高新技术产业有限公司', '4月16日', '4000-8000元', '济南-历城区', '计算机软件', '20-99人', NULL, 'CCL1487792200J40645823216', '岗位职责:<br>1、负责小程序、APP、网页前端的开发;<br>2、与后台开发人员协同实现产品界面和数据呈现及交互专注通过技术改善用户体验;<br>3、根据效果图进行开发，并针对主流的桌面及移动端浏览器进行兼容性适配;<br>4、对页面整体结构及样式层结构进行设计和优化;<br>5、开发定制、可扩展的前端UI组件。<br>', NULL, 'https://www.zhaopin.com/jobdetail/CCL1487792200J40645823216.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (171, '测试工程师', '西安航星测控技术有限公司', '2025-07-27 01:00:18', '4000-6000元·13薪', '渭南-临渭区', '检测/认证,专业技术服务', '20-99人', NULL, 'CC892209470J40687989101', '专业要求：机电一体化、测控技术与仪器、机械设计制造等理工科相关专业<br>任职要求：<br>1、有相关工作经验者优先，优秀应届毕业生也可考虑；<br>2、熟悉国军标GJB150及GJB150A系列、GB/T2423、GJB1032等标准；<br>3、了解高低温试验箱、振动台等实验室设备。<br>工作职责：<br>1、对安排的试验条件进行确认，可完成试验前准备工作，按照技术标准、规范和作业指导书进行各项测试工作；<br>2、根据试验条件及要求，可以熟练操作设备、填写试验原始记录，快速有效的执行试验方案；<br>3、负责设备的日常维护保养及现场试验工作区域规整的保持；<br>4、根据试验任务及要求对试验原始记录和数据进行处理；<br>5、对所安排的试验有责任心，有重大问题及时向上级汇报；<br>6、对实验室所用新标准、新方法、新设备不断学习和研究。<br>福利待遇：<br>1、实习期1~3个月，可根据个人能力提前转正，有专业人员进行培训；基本工资+岗位工资+补贴+绩效工资+年终优秀员工奖。<br>2、公司提供免费住宿，不定期组织团建旅游活动和学习考察；<br>3、每年13薪，五险一金，提供免费住宿，餐补等。<br>职位福利：五险一金、绩效奖金、加班补助、全勤奖、包住、餐补、定期体检、节日福利', NULL, 'https://www.zhaopin.com/jobdetail/CC892209470J40687989101.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (172, '前端开发', '盈峰环境', '7月29日', '150-200元/天', '长沙-岳麓区', '环保', '10000人以上', '已上市', 'CC404818830J40763991102', '岗位职责:', '盈峰环境科技集团股份有限公司，深交所主板上市（股票代码000967），旗下拥有249家子公司，全国建有3大产业基地（长沙、顺德、绍兴），15个研发创新平台，329个服务网点。公司主营业务涵盖环保装备、城市服务、科学仪器、环卫机器人、垃圾焚烧发电、风机装备等，是中国环境企业50强、中国机械500强、中国环卫十大影响力企业。盈峰环境环保装备发端于国家级科研院所——建设部长沙建设机械研究院。盈峰环境致力于成为受人尊敬和信赖的以清洁服务机器人为龙头的智能环境装备及服务的行业引领者，围绕以“智能装备、智云平台、智慧服务”为核心的智慧环卫战略打造出公司强大竞争力。作为环保装备领域的开拓者，公司持续引领产品技术变革，将人工智能技术赋能环卫，创新推出了一系列新能源环卫装备、5G无人驾驶环卫机器人等行业领先产品，精准解决行业痛点难点；并将多年在技术、产品积淀和渠道资源优势延伸到环卫服务领域，利用以物联网、大数据、云计算等前沿技术打造的智慧环卫云平台，开展信息化、网络化、数字化环卫运营服务。构筑起从前端投放、中端运输到后端处理的全产业链，用智慧科技缔造人与自然的和谐共处。近年来，公司环保装备销售、城市服务年化合同额、合同总额等多次拿下“行业第一”，斩获环保装备和城市服务的“双冠”业绩。未来，盈峰环境将紧密围绕“智慧环卫”战略，持续推进环卫行业向机械化、新能源化、小型化、智能化、云联化方向发展，构建环卫新生态。', 'https://www.zhaopin.com/jobdetail/CC404818830J40763991102.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (173, 'Java', '外企德科数字技术有限公司', '2025-07-27 00:25:18', '1.2-2.4万·14薪', '深圳-龙岗区', '专业技术服务', '10000人以上', NULL, 'CCL1480117890J40784085905', '岗位职责： 1、负责应用软件开发和维护工作。 2、负责软件模块需求分析、系统新模块代码编写和单元测试，完成概要设计文档、详细设计文档。 3、积极主动的与项目相关人员沟通交流，持续改善产品体验。 业务技能要求： 1、熟练掌握常用数据结构。 2、熟悉计算机组成原理、操作系统、网络等。', '外企德科数字技术有限公司是一家2023年新成立的中外合资企业。成立于2023年11月24日，公司定位：专注于为信息技术企业提供人才及数字技术外包解决方案的中外合资企业。它是由中国人力资源服务行业的FESCO（北京国际人力资本集团）与全球人力资源服务领导者The Adecco Group（德科集团）合资成立的。公司主要提供网络技术服务、软件外包服务、计算机系统服务、技术进出口、软件开发等信息技术相关服务。专注于为信息技术企业提供信息技术类人才及数字技术外包解决方案。', 'https://www.zhaopin.com/jobdetail/CCL1480117890J40784085905.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (174, 'C/C++', '吉林省荣汇鑫网络技术有限公司', '7月17日', '5000-8000元', '长春-绿园区', '网络/信息安全', '300-499人', NULL, 'CCL1491859700J40813665603', '岗位职责：<br>1、负责物联网项目硬件选型，包括选择元器件、驱动器等，确保项目的兼容性和可靠性；<br>2、根据项目需求，参与物联网项目的设计，包括电路原理图的绘制、接线等；<br>3、使用C语言参与物联网项目的程序编写；<br>4、参与物联网项目的测试与调试，确保项目的功能和性能，并能反馈、解决问题；<br>5、负责项目的资料整理和归档，协助项目经理进行项目进度跟踪和管理。<br>职位要求：<br>1、大专及以上学历，计算机、物联网等相关专业优先；<br>2、熟悉物联网项目开发流程；<br>3、熟练运用C语言；<br>4、良好的沟通表达和团队协作能力，学习能力强。<br>福利待遇：<br>五险一金，周末双休，法定节假日正常休息，员工生日福利，定期团建，带薪年假。', NULL, 'https://www.zhaopin.com/jobdetail/CCL1491859700J40813665603.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (175, '实施工程师', '东华医为科技有限公司', '2025-07-27 01:11:56', '7000-12000元', '泰安-泰山区', 'IT服务,IT服务', '1000-9999人', '未融资', 'CC649781480J40413944105', '1、学习能力强,能较快掌握和应用新技术;', '东华医为科技有限公司（简称东华医为）成立于2012年5月，注册资金5000万，是东华软件股份公司旗下专业服务医疗、卫生等大健康领域IT业务的全资子公司。东华医为现有员工2000余人，其中技术人员占比达到90%，拥有近100项大健康类自主知识产权的软件产品，所覆盖的大健康领域有医疗机构、卫生管理机构、互联网医疗、人工智能、大数据、健康管理等，所涉及的主要业务有IT咨询规划、方案设计、系统集成、软件开发与交付、工程实施与交付、人才培养、售后运维、合作运营等。东华医为现为全国500余家大健康领域的各类用户提供着持续的技术服务，还连续多年蝉联中国十佳医疗行业解决方案商榜首。传承了东华软件医疗卫生事业部近二十年IT业务的东华医为，在高速发展的大健康领域，笃定能大有作为。', 'https://www.zhaopin.com/jobdetail/CC649781480J40413944105.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (176, 'Java', '四川锐狐网络科技有限公司', '7月23日', '3000-5000元', '成都-锦江区', '计算机软件,互联网,计算机软件,新媒体', '20-99人', '不需要融资', 'CC160493710J40780404813', '【岗位描述】<br>1、根据开发规范与流程独立完成模块的设计、编码、测试以及相关文档；<br>2、具有面向对象的分析和设计的能力；<br>【岗位要求】<br>1. 本岗位只招聘26、27届计算机相关专业本科实习生；<br>2.勤于思考、积极主动，较强的执行力、具备较好的沟通和学习能力；<br>3.保证可以实习6个月，可提供转正机会。<br>【福利待遇】<br>1、周末双休、法定节假日等福利；<br>2、公司发展稳健，运营体系完善，助力您与我们一起成长；<br>3、办公环境优越，办公区宽敞舒适、工作氛围轻松；<br>面试流程： 请大家注意，岗位均采取线下面试，无电话、视频等线上面试，不私加求职者QQ、微信等私人联系方式。', '四川锐狐网络科技有限公司是一家集信息化管理、信息化建设、信息化服务为一体，涉及政务、医疗、教育等领域的国家级高新技术企业，公司成立于2006年，总部及研发基地设立于风景秀丽的天府之国——四川·成都。公司以习近平新时代中国特色社会主义思想为指导，以国家政策为依据，以科学技术为基础，以用户需求为导向。依托云计算、互联网、大数据、AI人工智能等技术，深度整合内外资源，高效利用多维数据，全方位为组织用户构建信息智能系统及管理标准。公司在“互联网+”的时代背景下，不断学习先进技术及思想，打造了一只经验丰富、素质过硬、技术创新、服务贴心的优秀团队，致力于为用户创建数据共享、信息互联的智慧平台，提供专业贴心的个性化服务。上善若水，大爱无疆，长久以来，四川锐狐网络科技有限公司勇于承担社会责任，积极投身社会公益事业，荣获“爱心企业”、“爱心抗疫勇者”等多项荣誉称号，锐狐在做好企业发展的同时，着力回报社会，传递社会正能量。锐狐铺好路，互联每一步，以优化创新实现智能化高品质管理的追求，将是锐狐高质量发展的永恒目标。', 'https://www.zhaopin.com/jobdetail/CC160493710J40780404813.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (177, '前端开发', '湖南烽旗信息科技有限公司', '4月30日', '4000-8000元', '长沙-岳麓区', '通信/网络设备,通信/网络设备', '20-99人', '不需要融资', 'CCL1338300610J40768978912', '岗位内容：<br>1. 开发响应式Web页面和功能组件，确保优秀的用户体验<br>2. 与后端开发人员合作，实现应用程序的完整性和可维护性<br>3. 设计和实现复杂的前端UI交互，并在跨浏览器环境中进行测试和故障排除<br>任职要求：<br>1. 精通HTML、CSS和JavaScript，并熟悉至少一种主要的前端框架（如React或Angular）<br>2. 具备良好的沟通能力和团队合作精神，有解决问题的能力和创新思维<br>3. 良好的代码阅读能力和学习能力', '公司发展史：公司成立于2017年,注册资金1000万。公司主要业务为：面向全国通讯行业进行电话增值业务服务。拥有湖南、江苏两大运营中心。与三大运营商（中国移动、中国联通、中国电信）进行增值业务合作，合作过程中各运营商对我司服务高度认可。目前于湖南长沙共有4家公司，分别位于长沙市各区域：湖南盛雄信息服务有限公司、湖南烽旗信息科技有限公司、湖南山禾企业管理咨询有限公司、湖南瀚泰信息服务有限公司。公司以“专注服务、用心服务”为核心，用户需求为中心。', 'https://www.zhaopin.com/jobdetail/CCL1338300610J40768978912.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (178, '技术支持工程师', '长春市月全设备有限公司', '7月19日', '5000-6000元', '长春-绿园区', '智能硬件', '20-99人', NULL, 'CCL1505076830J40930785204', '主要职责：<br>- 负责公司网络设备的日常巡检和测试工作。<br>- 根据测试结果编写测试报告，记录测试过程中发现的问题。<br>- 负责记录并更新公司网络设备的测试文档。<br>- 协助项目经理完成相关项目工作。<br>67任职要求：<br>1、年龄18-28岁，中专以上学历，可接受应届生/往届生<br>2、有良好的沟通能力和表达能力；<br>3、会使用电脑软件的基础操作（有老员工带）<br>福利待遇：<br>1. 薪水：试用期底薪4000，转正后4500-5500+项目奖金<br>2. 福利：五险一金！<br>3. 假期：双休，法定节假日休息和国家规定一致', NULL, 'https://www.zhaopin.com/jobdetail/CCL1505076830J40930785204.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (179, '实施工程师', '金现代', '6月5日', '5000-9000元', '济南-历下区', '计算机软件', '1000-9999人', '已上市', 'CC342271710J40850858315', '1、协助项目经理完成项目交付全流程工作，包括需求调研、方案设计、开发跟进、测试验收及上线部署。<br>2、协助处理客户日常咨询及问题反馈，跟进问题解决进度并记录闭环。<br>3、协助解决客户技术问题（如系统部署、数据迁移）。<br>4、分析项目交付过程中的痛点，提出优化建议（如工具改进、流程简化等）。<br>任职要求：<br>学历：计算机、软件工程、信息管理等相关专业 本科及以上学历，  经验：0-1年工作经验。  <br>能力：逻辑清晰、沟通能力强，对IT技术和项目管理有兴趣。  <br>', '金现代信息产业股份有限公司位于中国软件名城——山东济南，是国家火炬计划软件产业基地骨干企业、山东省优秀软件企业、济南市十大千亿产业重点企业及国家电网公司信息化建设十强企业之一，自主软件收入位于山东省软件行业十强之列。自2001年创立以来，始终致力于电力、铁路、军工、石化、公安等领域的信息化建设，产品遍布全国22个省、5个自治区、4个直辖市，是国内领先的行业信息化解决方案提供商。公司与国家电网、中国石化、中国铁路总公司等十余家世界五百强企业保持着稳固的合作关系。同时，公司在大数据、互联网+、移动开发、物联网、智能视频、三维互动、节能环保等领域也进行了卓有成效的探索。公司先后被认定为山东省软件工程技术中心、山东省工程技术研究中心。具有高新技术企业、双软认证企业、计算机系统集成资质三级、CMMI5、武器装备科研生产单位保密资格三级、ISO27001:2013信息安全管理体系认证企业、ISO20000:2011信息技术服务管理体系认证企业和ISO9001：2008质量管理体系认证等资质。未来，公司将秉承“打造百年企业”的宏伟目标，努力成长为国内一流大型软件企业，争取为国内信息化产业的发展做出更大贡献', 'https://www.zhaopin.com/jobdetail/CC342271710J40850858315.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (180, '测试工程师', '广东台德智联科技有限公司', '7月11日', '6000-8000元', '东莞-None', '电子/半导体/集成电路,电子/半导体/集成电路,通信/网络设备', '1000-9999人', '已上市', 'CCL1228208910J40731310116', '岗位职责：（接受25届应届生，专业基础扎实）<br>1:制定测试计划，编写测试报告，根据测试需求进行分析，设计，开发测试用例；2:对产品进行测试并记录测试结果，对缺陷进行跟踪管理；<br>3:准确定位缺陷，协助解决缺陷，完成硬件产品设计；<br>4:硬件产品质量把控。<br>岗位要求:<br>1:本科及以上学历，电子类相关专业。<br>2:熟悉电子产品相关测试，分析标准。<br>3:熟悉使用各种仪器设备针对电子元器件，PCBA适配器等进行测试。<br>4:熟悉产品开发流程，有音频智能产品的测试经验，独立完成产品硬件测试项目。<br>5:具有较强的沟通能力和团队合作能力，有耐心，主动性强者优先，对测试工作有较高热情。<br>6:应届生亦可，专业知识扎实，有参加电子设计竞赛者优先。', '台德集团成立于2004年，致力于为用户提供轻奢品的人工智能产品。紧紧围绕智能连接、智能语音交互、智慧图像的软件、硬件、射频、语音、智慧制造、云、大数据等核心技术耕耘，形成了完整的研发、生产、销售、售后的一站式服务团队。公司自成立以来，通过不断的产品创新和技术升级改造，凭借先进的技术实力被评为“国家高新技术企业”、“上市后备企业”、“抚州市工程技术研究中心”、“江西省“专精特新”中小企业”、“东莞市倍增计划试点企业”等荣誉和称号。', 'https://www.zhaopin.com/jobdetail/CCL1228208910J40731310116.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (181, 'Java', '外企德科数字技术有限公司', '2025-07-27 00:25:40', '1.2-2.4万', '南京-雨花台区', '专业技术服务', '10000人以上', NULL, 'CCL1480117890J40788702205', '岗位职责：<br>1. 参与需求分析，设计技术方案，使用主编程语言，如Java/Python/Go/JS等编写高质量代码。<br>2. 负责软件模块需求分析、系核心模块代码编写和单元测试，完成概要设计文档、详细设计文档。<br>3.  优化系统性能、稳定性，保障代码质量（单元测试、Code Review）。<br>4.  与产品、测试等团队紧密配合，推动项目落地。<br>岗位要求：<br>1.一本以上学历，双证学信网可查（不要求专业） <br>2.热爱编程，基础扎实，熟悉掌握但不限于Java、C/C++、GO、Python、JS等1种或多种主流编程语言 ，精通多线程、IO、网络编程等；<br>3、精通客户端与服务器通信协议，精通 XML 、 JSON 数据交换格式，精通 STL、Curl、 DuiLib 等常用的开源库；<br>4.熟悉底层软件、应用软件，具备操作系统、嵌入式软件开发相关的知识；<br>5.具有良好的沟通能力，有良好的团队合作精神。对技术有激情，喜欢钻研，能快速接受和掌握新技术，有较强的独立、主动的学习能力。', '外企德科数字技术有限公司是一家2023年新成立的中外合资企业。成立于2023年11月24日，公司定位：专注于为信息技术企业提供人才及数字技术外包解决方案的中外合资企业。它是由中国人力资源服务行业的FESCO（北京国际人力资本集团）与全球人力资源服务领导者The Adecco Group（德科集团）合资成立的。公司主要提供网络技术服务、软件外包服务、计算机系统服务、技术进出口、软件开发等信息技术相关服务。专注于为信息技术企业提供信息技术类人才及数字技术外包解决方案。', 'https://www.zhaopin.com/jobdetail/CCL1480117890J40788702205.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (182, 'Java', '视德管理咨询(深圳)有限公司', '7月16日', '150-200元/天', '福州-闽侯县', '电子/半导体/集成电路,咨询服务,学术/科研,培训/辅导服务', '20人以下', '未融资', 'CC810238330J40779195314', '主要职责<br>技术开发<br>·       参与需求分析和技术方案讨论<br>·       在指导下完成模块设计、编码和单元测试<br>·       使用Java/Go语言开发后端服务<br>·       编写清晰的技术文档和API文档<br>·       参与代码审查，学习并遵循团队编码规范<br>系统维护<br>·       协助排查和解决线上问题<br>·       参与系统性能优化工作<br>·       维护和改进现有系统功能<br>团队协作<br>·       与产品经理、测试工程师密切合作<br>·       参与敏捷开发流程（Scrum/Kanban）<br>·       参加技术分享和团队建设活动<br>', '国际信息显示学会(Society for Information Display，简称SID)是由显示行业顶尖科学家、工程师、企业研发和高级管理人员组成的全球型专业学术组织，成立于1962年,已有62年历史。SID目前在全球设有33个分会近7000名显示领域精英及包括苹果、Intel、Google、三星、LG、Sony、松下等国际知名企业会员。在中国大陆设有SID北京分会，北京分会下设18个技术领域委员会，共238名来自各大名校、科研机构和名企的专家。SID北京分会会员超过1600人，是全球第一大分会；有40多家企业会员也是全球拥有企业会员最多的分会。SID代表3000多亿美元信息显示产业里最具领导地位、最权威、唯一的专业学术和技术组织。SID的宗旨在于促进信息显示科技和产业的发展。鉴于中国在显示产业中地位的大幅度提高，中国大陆已经成为全球显示产业的新引擎，SID在中国建立了实体运营中心SID China（视德管理咨询（深圳）有限公司），这是SID在美国之外成立的唯一一个海外运营实体。SID China运营中心于2018年入驻深圳湾科技生态园，2022年SID China上海创新中心在上海市黄浦区落户，SID China现已成为国际显示技术交流、技术人员能力提升、产业走向国际化的重要平台。SID China现招聘WEB前端工程师，运营实习生各1名，工作地点在福州大学国家大学科技园，协助SID China运营中心各大业务及功能板块开展。欢迎有开创性精神的符合条件的本科及以上学历应届毕业生和非应届毕业生应聘全职或实习。欲了解更多有关SID China资讯，请关注微信公众号：SID-Information;或登陆官网：www.sidchina.org', 'https://www.zhaopin.com/jobdetail/CC810238330J40779195314.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (183, 'Java', '外企德科数字技术有限公司', '2025-07-27 00:25:59', '1.2-2.4万', '西安-雁塔区', '专业技术服务', '10000人以上', NULL, 'CCL1480117890J40793567505', '岗位职责 参与软件系统的需求分析、设计、开发、测试和维护；<br> 编写高质量、可维护的代码，优化系统性能和稳定性；<br> 与产品经理、测试工程师等协作，确保项目按时交付；<br> 持续学习新技术，优化现有代码架构，提升开发效率；<br> 编写技术文档，参与代码评审，确保代码符合规范。<br>任职要求： 计算机科学、软件工程或相关专业本科及以上学历（或具备同等能力）；<br> 熟练掌握至少一门主流编程语言（如Java/Python/C++/JavaScript/Go等）；<br> 熟悉常用数据结构和算法，具备良好的编程习惯；<br> 了解数据库（SQL/NoSQL）和基本网络通信（HTTP/TCP/IP）；<br> 熟悉Git版本控制，掌握基本的Linux命令；<br> 具备良好的问题分析和解决能力，团队协作精神强。<br>', '外企德科数字技术有限公司是一家2023年新成立的中外合资企业。成立于2023年11月24日，公司定位：专注于为信息技术企业提供人才及数字技术外包解决方案的中外合资企业。它是由中国人力资源服务行业的FESCO（北京国际人力资本集团）与全球人力资源服务领导者The Adecco Group（德科集团）合资成立的。公司主要提供网络技术服务、软件外包服务、计算机系统服务、技术进出口、软件开发等信息技术相关服务。专注于为信息技术企业提供信息技术类人才及数字技术外包解决方案。', 'https://www.zhaopin.com/jobdetail/CCL1480117890J40793567505.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (184, '软件测试', '协腾博通(陕西)科技有限公司', '7月22日', '1.2-1.3万·13薪', '西安-长安区', '互联网', '20-99人', NULL, 'CCL1504953740J40759030009', '岗位内容：<br>1. 设计并执行测试用例，记录测试结果并准备测试报告。<br>2. 协调开发人员、项目经理和测试团队成员，以确保遵守时间表和产品质量标准。<br>3. 使用自动化测试框架和工具来提高测试效率和覆盖率。<br>4. 不断改进测试流程和方法，以提高质量和效率。<br>5. 关注产品质量和客户需求，确保稳定、可靠和用户友好的软件交付。<br>任职要求：<br>1. 熟悉软件测试方法和流程。<br>2. 掌握至少一种自动化测试框架和脚本语言（如Selenium、Python、Robot Framework）。<br>3. 具备良好的团队合作精神和沟通能力。<br>4. 能够承受压力，在快节奏的环境中高效工作。<br>5. 有问题解决的能力和主动学习的态度。', NULL, 'https://www.zhaopin.com/jobdetail/CCL1504953740J40759030009.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (185, '科研人员', '成都益鑫麒能源科技有限公司', '7月17日', '1-1.1万', '成都-新都区', '新材料', '20-99人', NULL, 'CCL1480157240J40800906313', '聚焦于将工程问题、实验数据或领域规律转化为数学模型（如微积分方程、微分方程组等），并通过编程（如 Python、MATLAB、C++）实现数值求解或解析分析，最终用于解决实际工程问题（如系统优化、性能预测、过程模拟等）。', NULL, 'https://www.zhaopin.com/jobdetail/CCL1480157240J40800906313.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (186, '前端开发', '云南正吉新能源汽车有限公司', '6月27日', '3000-5000元', '深圳-南山区', '新能源,新能源汽车,货运/物流/仓储', '20-99人', '未融资', 'CC870199500J40767761607', '工作职能  1. 执行项目经理分配的任务', '云南正吉新能源汽车有限公司于2019年2月份正式成立，目前公司团队由金融服务业务人员、销售业务人员、物流行业人员、售后服务人员等专业精组成之秉承公司精神：“做您身边商用车金融服务专家”。公司团队己具备成熟的新车二手车销售、新车二手车融资租赁及车辆挂靠管理服务体系，有丰富的业务经验、完善的风控体系和专业的业务、风控、金融骨干团队。经过公司上下一致努力，正吉新能源在云南新能源物流车市场上，获得了较大的名度和较好口碑。公司依托于现传统物流背景发展新物流，结合新能源，共同推动新的合作方式，搭建新的物流平台。用新能源车辆搭建低成本、高收益、全路板、高智能、全方位的管理车队，致力于用共享经济的方式提升司机收入，助力司机创业，促进物流行业的新篇草。', 'https://www.zhaopin.com/jobdetail/CC870199500J40767761607.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (187, '技术支持工程师', '安徽耀峰雷达科技有限公司', '7月16日', '5000-8000元·13薪', '合肥-蜀山区', '专用设备制造,电子/半导体/集成电路', '20-99人', NULL, 'CC838334870J40724311514', '工作职责 1.负责相关软件的协议、设计方案、测试方案及知识产权等文档的编写；  <br>2.设计雷达、通信相关数据处理算法，进行性能仿真和优化；  <br>3.撰写相关软件的使用说明；  <br>4.在软件的设置使用上配合其他部门的实验测试工作；  <br>5.对客户提供设备使用技术支持。', '安徽耀峰雷达科技有限公司成立于2016年3月，是一家专业从事监视雷达及立体防御系统研发、制造、销售和服务的国家高新技术企业。公司总部坐落于安徽合肥，占地面积约10000平米，拥有一座科研大楼，一座综合大楼，两栋生产厂房，在南京成立分公司，在北京设立办事处。在历届“无形截击”比赛均取得佳绩；产品入围公安部警用装备采购目录，广泛应用于机场、公安、监狱、边海防等领域。公司拥有一支高层次的研发团队，团队由博导领衔，具有多年雷达研发经验，承担多项国家自然科学基金项目、“十二五”、“十三五”预研项目，参与编制相关产品标准。公司采用开放式科研合作模式，推进产学研用深度融合，提高研发的厚度和广度；管理团队均来自军工央企和上市公司，管理经验丰富，深耕军工行业几十年，研制雷达三十多年，聚焦监视雷达及立体防御系统领域多年。公司建有高效、自主可控的运营管理体系，管控产品全生命周期，贯穿快速反应机制。公司拥有强大的雷达天馈系统研制能力，建成雷达整机装配生产线、雷达伺服系统生产线、雷达外场测试平台和微波暗室，各类检验设备齐全，全方位打造稳定可靠的精品。公司产品线丰富，涵盖机相扫、相相扫、相频扫、机频扫等类型雷达，现有八个系列十几款产品，可满足客户个性化需求；产品拥有空地一体、空海一体和低空探测等多种工作模式，具备目标智能分类识别和行进间探测功能。产品采用模块化设计，精巧便携，强杂波抑制、大机动目标跟踪、环境自适应，全方位、全天候保障安全。公司始终践行“严谨、诚信、合作、创新”的核心价值观，坚持“聚焦主业，构建行业生态圈”的经营理念，视“让家园更安全，让社会更稳定”为己任，矢志成为受人尊重的行业引领者，我们将以领先的技术、高品质的产品与服务，不断满足客户需求，和客户一起打造命运共同体！', 'https://www.zhaopin.com/jobdetail/CC838334870J40724311514.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (188, '硬件测试', '软通动力信息技术(集团)股份有限公司', '7月1日', '9000-12000元', '上海-青浦区', '互联网,IT服务,计算机软件', '10000人以上', 'D轮及以上', 'CC000544460J40728162916', '本岗位考虑有基带测试，电源测试实习经验的25届本科生，可培养。', '软通动力信息技术（集团）股份有限公司（以下简称“软通动力”）是中国数字技术产品和服务创新领导企业，致力于成为一家具有全球影响力的科技企业，企业数字化转型可信赖合作伙伴。公司2005年成立于北京，多年来始终坚持科技创新，具有软硬全栈的智能技术产品和服务能力，提供软件与数字技术服务、计算产品与数字基础设施、数字能源与智算服务以及国际化服务。目前，公司在10余个重要行业服务超过1100家国内外客户，其中超过230家客户为世界500强或中国500强企业，员工近90000人。软通动力拥有软通咨询、软通金科、软通工业互联、机械革命、软通华方等业务子品牌，并在全球40余个城市布局业务，构建北美、日本、东南亚、中东四大国际交付中心，在北京城市副中心、江苏无锡建设两大智能制造基地。同时，公司前瞻布局智能制造、ICT软硬基础能力和生产力智能化产品，打造产业链闭环。软通动力设立30个能力中心，拥有1个国家级工程实验室，6个省市政府认定的工程、技术实验室及研发中心，1个博士后科研工作站，50+技术合作伙伴的生态合作体系，不断探索前沿技术的巨大商业应用潜力。公司旗下教育品牌软通教育，拥有一家全日制本科学院——郑州西亚斯学院数字技术产业学院；同时在全国合作院校600多所，设有70多个校企联合人才培养基地，通过校企合作、协同育人，为社会培养高素质应用型人才。软通动力先后获得“2023年中国IT服务市场排名TOP 1”、“2024年Q4 PC出货量国内市场份额排名TOP 2”、“2024年中国软件和信息技术服务竞争力百强企业”、“2023年中国信创企业100强”、“2024万得ESG评级（Wind ESG Rating）AA级及信息技术服务行业ESG综合得分排名第一”等荣誉及市场认可，并拥有全球软件工程领域最高级别CMMI V2.0成熟度5级评估认证、国家研发运营一体化（DevOps）三级能力成熟度模型认证、信息技术服务标准（ITSS）运维能力成熟度一级认证等专业资质，支撑公司更优质的服务体系。', 'https://www.zhaopin.com/jobdetail/CC000544460J40728162916.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (189, '实施工程师', '北京恩天科技发展有限公司', '7月1日', '8000-10000元', '杭州-西湖区', '专业技术服务,专业技术服务', '20-99人', '未融资', 'CCL1309913630J40720805009', '一、岗位职责<br>1．在数字化转型项目中，负责生产设备数据接入，存储和转发技术方案设计、方案编写。<br>2．参与云边端物联网平台建设，实现现场采集数据的统一管理，平台日常维护和管理。<br>3．集成项目实施中，与现场数据采集和大数据人员对接，打通生产数据传输通道，解决工程问题，技术迭代优化。<br>4. 负责现场边端传感器配置管理软件开发。<br>二、岗位要求：<br>1. 自动化、计算机、通信、物联网、电气工程或机电一体化相关专业。<br>2．1年以上工厂物联网应用/平台经验，熟悉现场设备到服务器的网络架构。<br>3. 了解TCP、UDP、串口，mqtt等通信；常见的通信机制：WiFi、Ehthernet、4G/5G等。<br>4. 技术思路清晰，能根据接口文档落实代码开发工作；熟悉传感器、数据采集、计算机网络、数据库等。<br>5. 掌握一门编程语言：C/C++、python、具有程序功能模块或数据处理系统代码编写和调试经验。<br>6. 良好的团队合作精神。<br>三、职位福利<br>周末双休、五险一金、餐补、绩效奖金、全勤奖、年终奖、出差补贴、节日福利。', '北京恩天科技发展有限公司2016年成立于北京，是从事化工行业节能、减排、绿色环保的专业技术公司。恩天科技致力于为用户提供技术领先、品质卓越的节能、环保产品及方案。公司以上海交通大学、中国科学院、哈尔滨工业大学、华北工业大学、七一九研究所为技术依托，拥有教授、博士、高级工程师等技术人才。构筑“恩天智汇”工业互联网平台，从业务源头实现数据统一、平台统一、标准统一，并为制造业提供工业APP、工业算法、大数据分析等增值服务；公司一直大力推进综合能源系统的研究和开发，致力于开创能源互联网新时代，其重要业务面向综合能源整体解决方案服务商、配套商转型，同时随着国家能源结构调整，在综合能源领域开展全面、全方位的研究和开发，在系统层面实现技术协同、设备耦合，通过优化调度，实现风、光、水、火、储、一体化效率提升。', 'https://www.zhaopin.com/jobdetail/CCL1309913630J40720805009.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (190, 'Java', '外企德科数字技术有限公司', '2025-07-27 00:23:29', '1.4-2.8万·14薪', '成都-郫都区', '专业技术服务', '10000人以上', NULL, 'CCL1480117890J40739373005', '1、熟悉Java/Python/C/C++/Go/js等一种或多种编程语言；<br>2、熟练软件开发流程，热爱编程，有良好的代码风格；<br>3、善于沟通，有独立解决问题的能力。<br>前端、后端、测试、开发、运维，所有职位都在招聘<br>流程全部线上进行~', '外企德科数字技术有限公司是一家2023年新成立的中外合资企业。成立于2023年11月24日，公司定位：专注于为信息技术企业提供人才及数字技术外包解决方案的中外合资企业。它是由中国人力资源服务行业的FESCO（北京国际人力资本集团）与全球人力资源服务领导者The Adecco Group（德科集团）合资成立的。公司主要提供网络技术服务、软件外包服务、计算机系统服务、技术进出口、软件开发等信息技术相关服务。专注于为信息技术企业提供信息技术类人才及数字技术外包解决方案。', 'https://www.zhaopin.com/jobdetail/CCL1480117890J40739373005.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (191, '软件测试', '四川若扬企业管理咨询有限公司', '7月23日', '1.2-1.6万', '广州-天河区', '企业服务', '20-99人', NULL, 'CCL1506191320J40867333215', '岗位内容：<br>1. 设计并执行测试用例，记录测试结果并准备测试报告。<br>2. 协调开发人员、项目经理和测试团队成员，以确保遵守时间表和产品质量标准。<br>3. 使用自动化测试框架和工具来提高测试效率和覆盖率。<br>4. 不断改进测试流程和方法，以提高质量和效率。<br>5. 关注产品质量和客户需求，确保稳定、可靠和用户友好的软件交付。<br>任职要求：<br>1. 熟悉软件测试方法和流程。<br>2. 掌握至少一种自动化测试框架和脚本语言（如Selenium、Python、Robot Framework）。<br>3. 具备良好的团队合作精神和沟通能力。<br>4. 能够承受压力，在快节奏的环境中高效工作。<br>5. 有问题解决的能力和主动学习的态度。', NULL, 'https://www.zhaopin.com/jobdetail/CCL1506191320J40867333215.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (192, '科研人员', '三达膜', '7月22日', '1.5-2万', '厦门-集美区', '环保,电力/水利/热力/燃气', '500-999人', '已上市', 'CC633494920J40683281706', '研究方向：废水处理，水污染控制研究<br>任职要求：<br>1、环境工程、环境科学专业，取得博士学位或已通过博士论文答辩即将毕业的博士生；<br>2、身体健康，年龄35岁以下，具备较强科研能力，能独立承担科研项目，有相关工作经验者佳；<br>3、能全职在本公司从事企业科研工作。', '三达膜（股票代码：688101）是中国膜技术开发与应用领域的开拓者，早在20世纪90年代，就开始在中国从事过程工业先进膜分离应用工艺开发，将国外先进膜技术引入国内并进行大规模工业化应用。三达膜专注于膜材料研发、膜组件生产、膜软件开发、膜设备制造、膜系统集成和膜技术应用，掌握了先进无机非金属膜材料与高性能复合膜材料的研制方法，构建了一条涵盖“膜材料-膜组件-膜设备-膜软件-膜应用”的膜产业链，服务涵盖特种分离与水处理两大应用领域，为传统工业生产过程的升级改造提供清洁生产与绿色制造的手段与方法，为过程工业的分离纯化与污废水资源化提供基于膜技术应用的创新解决方案。公司致力于解决过程工业各行业客户的“提高产品质量、增加产品收率、降低生产成本、减少废弃物排放”四大诉求，是国内知名的集先进膜材料研发、特种分离膜技术应用、膜法水处理和水务投资运营为一体的科技创新型企业。三达膜主要业务涉及工业料液分离、产品分离纯化、废水资源化、饮用水安全保障等领域，应用于食品饮料、医药化工、生物发酵、冶金石化、水质净化、环境保护等多个行业，面向实体制造业、市政管理部门和终端净水家庭用户等，是国内知名的集先进膜材料研发、特种分离膜技术应用、膜法水处理和水务投资运营为一体的科技创新型企业。公司拥有博士后科研工作站和福建省膜分离工程技术研究中心，并且在全国多个县市通过BOT、TOT或委托运营方式在全国范围内多个地区投资和运营市政污水处理厂。公司拥有良好的成长平台、富有竞争力的薪资和完善的福利待遇，尊重知识、尊重人才，良好的沟通、浓烈的学习氛围，让您倍感工作的快乐，期待有志之士的加盟！★【集团员工福利】 1、5天八小时工作制； 2、补贴式的工作餐； 3、免费通勤车； 4、法定社保（五险）、住房公积金、补充商业险； 5、带薪年假、产假、陪产假、产检假、考试假、婚假、丧假、独生子女陪护假、育儿假等； 6、年度体检、年度旅游、中秋博饼、“三八”妇女节活动、年终表彰会； 7、考核式的绩效奖金； 8、其它：每周五下午1小时的运动时间，公司设有健身房、篮球场、羽毛球场、图书室；工会会发放结婚贺礼、生育贺礼、吊唁安抚等；公司内刊可以踊跃投稿。', 'https://www.zhaopin.com/jobdetail/CC633494920J40683281706.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (193, 'C/C++', '山东华云三维科技有限公司', '2月13日', '9000-15000元·14薪', '济南-历下区', '计算机软件,计算机软件', '100-299人', 'C轮', 'CCL1224370370J40636565202', '岗位职责：<br>1. 参与公司自主三维云架构CAD产品CrownCAD的底层算法研发工作；<br>2.根据整体设计和编码规范完成分配模块的设计、编码等工作。<br>岗位要求：<br>1.本科及以上学历，学习成绩优秀，数学与计算机基础良好；<br>2.熟悉C/C++/Python中的任意一种语言；<br>3.有图形学、图像处理等学习或开发经验者优先；<br>4.具备良好的学习能力，有良好的沟通协作和自我驱动力，适应团队协作。', '山东华云三维科技有限公司（简称“华云三维”），作为山东山大华天软件股份有限公司（简称“华天软件”）的全资子公司，致力于国产三维CAD软件的研发和推广，拥有自主研发的“三维几何建模引擎”和“几何约束求解器”，基于这两项三维CAD最核心的底层技术，专注打造国内基于云架构的三维CAD平台CrownCAD。华云三维由华天软件首席科学家、“国家人才工程”入选者、国内知名CAD专家梅敬成博士牵头创办。其核心研发团队均毕业于国内外知名高校，专业涵盖计算机图形学、应用数学、计算机科学与技术、软件工程、机械设计等，硕士及以上学历占比超过50%。华云三维与母公司华天软件紧密协作、协同攻坚，共同承担了多项国家级重大研发专项。华天软件作为国产工业软件的领军企业，华云三维则肩负重任，全面承担并负责新一代基于云架构的CAD研发工作，助力实现国产工业软件的“换道超车”。', 'https://www.zhaopin.com/jobdetail/CCL1224370370J40636565202.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (194, '测试工程师', '杰克科技股份有限公司', '7月15日', '9000-15000元', '台州-椒江区', '金属制品业,电子/半导体/集成电路,耐用消费品,贸易/进出口', '1000-9999人', '已上市', 'CC133087640J40781800415', '岗位职责:', '杰克科技股份有限公司（股票代码603337），是一家专注于工业缝纫机、自动裁床、节能伺服电机三大产品研发、生产、销售的跨国民营企业，现已成为行业领先的缝制机械制造商和全球缝制机械行业中产销规模最大的企业之一，在全球市场持续传递中国制造的力量。公司始终处于行业最前沿，引领行业发展。一共设立德国、杭州、西安、椒江、临海5大研发中心，研发领域涉及精密机构、智能传感、先进控制、故障诊断、人机互动、无线通讯、物联网等，超过30%的员工从事技术创新、产品研究与开发，已累计获得授权发明专利500多项。公司坚信：未来将是一个智能互联的时代。抓住全球新一轮工业革命机遇，逐步构建以智慧数据、智慧生产和智慧服务为一体的“智慧工厂”，创造出具有智能化、可视化、无线通讯网络化、互动性功能，并可实现信息存储、自动检测的智慧型缝制设备，为缝制设备行业和服装产业的发展做出贡献。', 'https://www.zhaopin.com/jobdetail/CC133087640J40781800415.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (195, '前端开发', '重庆淼速科技有限公司', '7月24日', '8000-12000元', '重庆-渝中区', '计算机软件', '20-99人', NULL, 'CC432293710J40796730005', '岗位内容：<br>1. 协助设计师进行Web页面和功能组件的设计，确保优秀的用户体验<br>2. 与后端开发人员合作，实现应用程序的完整性和可维护性<br>3. 设计和实现复杂的前端UI交互，并在跨浏览器环境中进行测试和故障排除<br>任职要求：<br>1. 大专以上学历，可接受应届生<br>2. 具备良好的沟通能力和团队合作精神，有解决问题的能力和创新思维<br>3. 会PS或AE优先。', '诚聘英才：', 'https://www.zhaopin.com/jobdetail/CC432293710J40796730005.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (196, '测试工程师', '天阳科技', '7月25日', '5000-7000元', '银川-金凤区', '计算机软件,计算机软件', '1000-9999人', '已上市', 'CC120408370J40824000708', '1.全国项目驻场测试，主要负责功能、数据或接口等相关测试工作；<br>2.统招本科学历及以上（学信网可查）；毕业满2年；计算机专业优先；<br>3.热爱软件测试行业、有强力的自驱力，能够在测试岗位深入学习研究；<br>4.有无经验均可，服从公司安排，接受公司培养，可接受异地工作优先；<br>福利待遇：<br>上市公司，公司可以提供住宿，提供五险一金；<br>欢迎符合要求的小伙伴们投递~', '天阳科技(股票代码：300872)，是全球金融创新服务的重要贡献者，持续赋能中国金融行业数字化转型，为客户提供咨询、金融科技产品、金融IT服务、云计算及运营服务。公司成立于2003年，服务超过300家金融行业客户，覆盖中央银行、政策性银行、国有银行、股份制银行、地方性商业银行、非银行金融机构等，员工人数近7000人，成为激活金融领域创新活力、推动金融科技迈入世界领先水平的重要力量。作为金融行业客户可信赖的合作伙伴，天阳科技凭借丰富的行业经验和端到端的专业服务，在信创、数字化金融、信贷、交易银行、信用卡、零售、营销、风险管理、征信监管等众多领域具备核心竞争力。据赛迪和IDC报告显示，近年来公司在中国银行业IT解决方案市场排名强势崛起，2019年收入及市场占有率综合排名分别位列第四位和第五位，并保持高速增长。同时，前瞻商业和科技趋势，入选2021年度未来银行科技服务商TOP100。天阳科技始终聚焦金融科技领域，加大自主创新力度，在超过100个城市建立本地化、专业化的研发和服务团队，拥有CMMI5级认证、软件测试成熟度模型集成（TMMi）3级认证、ISO9001质量管理体系认证、ISO20000信息技术服务管理体系认证、IS027001信息安全管理体系认证。通过部署人工智能、云计算、大数据、移动互联网、分布式计算和区块链等先进金融科技，公司致力于构建安全可控、普惠民生、开放共赢格局，在关键技术领域服务现代化金融发展大局，更好地为各利益相关方创造更大价值，为大中企业、小微企业以及每个个体提供优质金融服务。', 'https://www.zhaopin.com/jobdetail/CC120408370J40824000708.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (197, '实施工程师', '山东浦创流体技术有限公司', '5月8日', '6000-10000元', '烟台-莱山区', '环保,环保', '20-99人', '未融资', 'CC606127330J40693436415', '一、主要职责<br>1、协助销售和市场部一起建立/定义客户需求，基于已有的技术和竞争对手的分析，评估可能的设计方案；<br>2、与销售和客户紧密合作，将浦创系统集成到客户的工艺流程中；<br>3、与实验室中心一起制定客户测试计划，为实验室中心内部和现场测试提供技术支持；<br>4、准备系统成本估算和系统方案, 准备P＆ID和投标图纸；<br>5、支持系统方案准备，并根据需要到客户现场做技术交流；<br>6、开发用于系统自动化的系统控制功能描述，准备系统操作和维护手册，提供系统安装和开车技术支持服务，参与客户操作人员培训。<br>7、完成经理交付的其它工作。<br>二、工作标准/绩效目标<br>1、按时完成设计图纸；<br>2、给销售提供技术支持（PPT，投标澄清等）；<br>3、系统订单项目执行支持；<br>4、系统服务技术支持。<br>三、任职资格<br>1、本科及以上学历，专业为化学工程或相关专业；<br>2、良好的人际沟通能力，团队协作精神和积极肯干的工作态度；<br>3、熟悉办公软件和CAD软件 (比如 Pro/E, AutoCAD, PDM etc), 具备3D制图能力(Fusion or Inventor)；<br>4、愿意出差，有较强的学习能力，可以很快的适应有挑战性的工作。<br> 四、工作经验', '山东浦创流体技术有限公司，成立于2017年，注册资金3000万，总部位于烟台高新区联东U谷，营业部遍布北京，上海等主要城市。浦创致力于超高温、高压、大流量含尘气体工况的自动反吹过滤系统的设计、生产及系统服务指导，拥有一支强大的技术研发团队，集结了全球一流的陶瓷过滤专家。团队成员拥有多年复杂反吹系统设计经验、高温陶瓷多孔滤芯生产及研发经验。我们潜心钻研，只为提供可以真正为中国客户解决复杂工艺问题及苛刻环保排放问题的高端国产自动反吹系统。为了确保高品质的产品质量及稳定的交货期，浦创采用全新一代的陶瓷滤芯生产工艺，所有生产设备均来自德国及日本。浦创还配备了实验中心，该实验中心目前具备滤芯微观结构检测、滤芯孔隙率检测、滤芯强度测试、滤饼通透性测试以及系统性能测试等能力。公司产品广泛应用于石油化工行业、煤化工行业、钢铁制造行业、玻璃制造行业、垃圾焚烧行业等多个领域。在中国市场，浦创还配备一支强大的专业技术服务团队，可以为客户提供全方位从售前到售后的专业技术服务。', 'https://www.zhaopin.com/jobdetail/CC606127330J40693436415.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (198, '科研人员', '北京脑科学与类脑研究所', '7月22日', '1.5-2万', '北京-昌平区', '学术/科研,学术/科研', '300-499人', '未融资', 'CC713689230J40577901909', 'Job Description：<br>1、Conduct Research Projects: <br>Experimental postdocs perform animal surgery, training, recording experiments, histology, and data analysis. <br>Computational postdocs perform computer simulation of brain’s cognitive processing with brain-like ANN (using deep learning tools), and data analysis of anixperimental data.<br>2、Provide Research Support:  Assist and teach other lab members with various ongoing research activities, including animal surgeries, experiments, and data analysis.', '北京脑科学与类脑研究所（CIBR）是在科技部的指导下，由北京市人民政府联合中国科学院、军事科学院、北京大学、清华大学、北京师范大学、中国医学科学院、中国中医科学院等8家单位，共同发起成立的新型研发机构（以下简称“北京脑中心”），属于事业单位。北京脑所将结合全国科技创新中心的首都城市战略定位，围绕国家重大项目研究方向，承接国家脑计划，立足北京的工作基础和优势特色，搭建关键技术平台，在脑科学与类脑研究领域集中开展科技攻关，实现前沿技术和重大脑科学研究的突破，成为国际领先的脑科学研究所。北京脑科学与类脑研究所于2018年3月22日成立，前期建设工作全面启动，诚邀海内外优秀的行政服务人员加盟。', 'https://www.zhaopin.com/jobdetail/CC713689230J40577901909.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (199, '实施工程师', '玫德集团', '7月19日', '8000-16000元', '济南-历城区', '金属制品业,房地产开发,矿产/采掘,互联网', '10000人以上', '未融资', 'CC171456410J40733851216', '注：', '全球领先的流体输送产品制造商和解决方案专家。玫德集团创立于1961年，目前已发展为以流体输送产品及服务为主的现代化、多元化跨国企业集团。销售遍布全球130多个国家和地区，成功地将产品和服务应用于水务、消防、燃气、暖通、灌溉等多个领域及全球各大地标项目中，迪拜哈利法塔、纽约新世贸中心、上海中心大厦、西电东输特高压输电线路、京沪高铁和市政、医疗、洁净厂房、城市住宅等。玫德产品涵盖各类玛钢管件、沟槽管件、不锈钢管材管件、碳钢卡压管材管件、阀门、钢管螺旋管、不锈钢金属软管、电力金具、水电气热表、抗震支架、盘扣式脚手架、生铁、配重铁、灌浆套筒等，同时提供BIM设计、工厂预制加工、数字化安装、智慧水务等相关服务，以及智能工厂规划、工业MES、工业立库、智能硬件等智能制造解决方案。目前已形成跨区域、多基地、全球化发展格局，拥有济南、临沂、泰安、威海、鹤壁、肇庆、泰国、越南、波兰9个海内外生产基地，20余家工厂，占地5000多亩，员工约12000人。集团是数十项国家和行业标准的起草者，国家级企业技术中心和博士后科研工作站，已获得500余项专利，荣获中国轻工业百强企业、中国玛钢管件生产基地龙头企业、中国绿色铸造示范企业、全国守合同重信用企业和工信部制造业单项冠军等400余项荣誉。玫德集团积极投身公益、回报社会，在教育、抗疫、养老、生态、扶贫等领域捐资超5亿元，荣获中华慈善突出贡献奖。玫德集团坚持奋斗、创新、包容、分享的企业文化，坚定不移地进行全球化布局，将智能制造进行到底，把数字化能力惠及全球用户。地址：济南市平阴县工业园区玫德工业科技城邮编：250400电话：87885191 87885190传真：87871021 87872214网址：www.meide-casting.com', 'https://www.zhaopin.com/jobdetail/CC171456410J40733851216.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (200, '科研人员', '浙江新世纪人才开发有限公司', '7月16日', '3000-6000元', '杭州-上城区', '咨询服务,房地产中介', '100-299人', NULL, 'CC148971830J40758421011', '岗位职责<br>辅助用工单位相关团队开展相关项目研究，学生管理及实验室工作。<br>岗位要求<br>1.政治素质好，遵纪守法，品行端正；<br>2.具有较强的责任心，工作积极主动，具有较强的沟通能力和团队合作精神；<br>3.环境工程、生态学、农学等相关专业毕业，本科及以上学历，具有实验室研究经历者优先；<br>4.身心健康，年龄一般不超过30周岁。<br>工作地点：浙江省农业科学院，浙江省杭州市上城区德胜中路298号。<br>工资待遇<br>月薪3500-6000元。相关保险按国家相关规定执行。', '浙江新世纪人才开发有限公司成立于2001年2月，是由浙江省人才市场管理办公室、浙江省人才市场出资成立的国有有限责任公司，从事人才派遣、人才招聘等业务。自公司成立以来，我们以出色的服务团队，专业的人力资源服务赢得了市场，树立了良好的社会信誉。我们的客户有电信、移动、邮政、医院、银行、大中专院校等，发展日新月异。公司是“浙江省工商企业信用AA级‘守合同重信用’单位”，并获“杭州大学生见习训练基地”资格，荣获杭州社会责任建设先进企业等称号。我们秉承诚信服务、规范管理理念，提供诚信、专业、热情、周到、全程上门服务。联系电话：0571-87208960汪老师', 'https://www.zhaopin.com/jobdetail/CC148971830J40758421011.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (501, '软件测试', '东莞市智通快聘人力资源服务有限公司', '7月21日', '7000-10000元', '东莞-None', '人力资源服务', '300-499人', '未融资', 'CCL1214098010J40776640702', '岗位要求：<br>1.本科及以上学历，计算机或相关专业优先；<br>2.具有Java、web测试相关工作经验；<br>3.需熟悉软件测试理论和方法，如性能测试、功能测试、可靠性测试、安全测试等方法及用例设计技术；<br>4.工作责任心强，细致，耐心，具有较强学习能力和实际动手能力；<br>5、敬业爱岗，能抗压、吃苦耐劳、善交流。<br>薪资待遇：7K-10K<br>吃住情况：不包', '东莞市智通快聘人力资源服务有限公司成立于2019年09月09日，注册地位于广东省东莞市莞城街道莞太路莞城段79号101室，法定代表人为王亚东。经营范围包括企业管理咨询服务；人力资源外包服务；职业中介；劳务外包；仓储服务；通用机械设备租赁。（依法须经批准的项目，经相关部门批准后方可开展经营活动）', 'https://www.zhaopin.com/jobdetail/CCL1214098010J40776640702.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (502, 'Java', '南昌玢耀信息技术有限公司', '6月18日', '5000-8000元', '南昌-青云谱区', '财务/审计/税务,云计算/大数据', '20-99人', '不需要融资', 'CCL1468722750J40679155802', '岗位内容：<br>1. 开发高质量的Java应用程序，保证代码的可读性、可维护性、可扩展性和性能。<br>2. 参与需求分析、系统设计和开发计划的制定。<br>3. 能够快速识别问题并提供有效的解决方案。<br>4. 与产品和测试团队紧密合作，确保产品质量符合用户期望。<br>任职要求：<br>1. 精通Java编程语言和Spring框架，有大型项目开发经验。<br>2. 拥有扎实的计算机基础，熟练掌握面向对象编程思想和设计模式。<br>3. 熟练使用常见的Web容器和数据库（如Tomcat、MySQL）。<br>  4. 熟悉敏捷开发流程，具备优秀的沟通和协调能力。', '南昌玢耀信息技术有限公司成立于2023年06月30日，注册地位于江西省南昌市青云谱区抚河南路99支路88号巨成金山商业广场，法定代表人为张龙康。经营范围包括一般项目：网络技术服务，技术服务、技术开发、技术咨询、技术交流、技术转让、技术推广，计算机系统服务，信息系统集成服务，信息技术咨询服务，工业控制计算机及系统销售，智能控制系统集成，国内贸易代理，办公设备耗材销售，计算机软硬件及辅助设备零售，软件销售，网络设备销售，电子产品销售，互联网设备销售，软件开发，信息系统运行维护服务，通讯设备销售，信息咨询服务（不含许可类信息咨询服务），社会经济咨询服务，财务咨询，教育咨询服务（不含涉许可审批的教育培训活动），税务服务，商务代理代办服务（除许可业务外，可自主依法经营法律法规非禁止或限制的项目', 'https://www.zhaopin.com/jobdetail/CCL1468722750J40679155802.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (503, '测试工程师', '哈尔滨宇高电子技术有限公司', '7月21日', '5000-7000元', '哈尔滨-香坊区', '仪器仪表制造,学术/科研,专用设备制造', '20-99人', '未融资', 'CC413865880J40426226909', '岗位职责：     1.按照标准规范实施继电器、连接器、开关的环境试验、寿命试验、电参数测试等试验，并出具试验报告；', '哈尔滨宇高电子技术有限公司成立于2016年6月29日，注册资本1000万元，是由哈尔滨工业大学、哈尔滨工业大学电器与电子可靠性研究所共同投资组建的高新技术企业。公司依托于电机与电器国防特色学科和国家重点学科，主要经营范围包括：高端低压电器产品质量设计（结构设计、耐环境性能优化、一致性稳健设计），可靠性测试设备研发、生产、销售等。其中，公司核心产品为DZJC-Ⅲ型PIND航天自动检测系统，具有试验方案可选、自动识别、数据可存储、波形回放等功能，优于国外同类产品，已配套20余家航天院所，曾荣获国家科技进步二等奖、国家部委科技进步一等奖。公司坚持以人为本、长期可持续发展理念，专注于电器领域高端产品的设计与制造，旨在引领与促进行业发展。', 'https://www.zhaopin.com/jobdetail/CC413865880J40426226909.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (504, 'C/C++', '外企德科数字技术有限公司', '2025-07-27 00:25:20', '1.9-3.5万·14薪', '深圳-龙岗区', '专业技术服务', '10000人以上', NULL, 'CCL1480117890J40784506905', '全国均有岗位(开发、测试、算法等)<br>岗位要求:<br>一、软件开发工程师<br>1.热爱编程，熟悉掌握Java/C++/C/Python/Web开发等编程语言中的一种或多种编程语言扎实的编程功底:<br>2.具备良好的独立工作能力和解决问题能力，善于沟通，乐于合作，热衷新技术;<br>二、<br>软件测试工程师：<br>1.热爱编程，熟悉掌握C/C++/Java/Python等编程语言中的一种或多种编程语言，扎实的编程功底;<br>2.有web开发或测试经验、自动化开发或测试经验者优先。<br>3.熟练掌握系统测试、功能测试、专项测试、软件测试、韧性测试、安全测试方法中的一种或多种测试方法，有相关测试语言/脚本的编写和实践经验优先，也可接受纯测试经验的。<br>4.具备良好的独立工作能力和解决问题能力，善于沟通，乐于合作，热衷新技术;', '外企德科数字技术有限公司是一家2023年新成立的中外合资企业。成立于2023年11月24日，公司定位：专注于为信息技术企业提供人才及数字技术外包解决方案的中外合资企业。它是由中国人力资源服务行业的FESCO（北京国际人力资本集团）与全球人力资源服务领导者The Adecco Group（德科集团）合资成立的。公司主要提供网络技术服务、软件外包服务、计算机系统服务、技术进出口、软件开发等信息技术相关服务。专注于为信息技术企业提供信息技术类人才及数字技术外包解决方案。', 'https://www.zhaopin.com/jobdetail/CCL1480117890J40784506905.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (505, '前端开发', '烟台市平安海洋工程服务有限公司', '7月20日', '8000-14000元', '深圳-南山区', '装饰装修', '20-99人', '未融资', 'CC221641620J40758246109', '岗位内容：<br>1. 设计和开发适用于不同设备的易于使用的网站<br>2. 参与产品原型设计和产品需求分析<br>3. 跟进技术趋势及前端开发最佳实践，不断提升团队的技术水平<br>任职要求：<br>1. 两年以上前端开发经验，掌握HTML5/CSS/JavaScript等前端技术和常用框架<br>2. 具备良好的学习能力和解决问题的思维能力，能够配合其他团队成员完成项目工作<br>3. 对新技术有好奇心，并愿意持续学习和提高', '公司主要业务为海洋及船舶建造、维修工程承包、工程服务支持和国际货运代理等。公司先后承接了多项海上石油钻采、服务平台及常规船舶工程的制造和维修工程，包括钢结构建造、导管架和组块海上安装施工、管线、电仪、舾装保温暖通、涂装、脚手架、设备安装等项目。', 'https://www.zhaopin.com/jobdetail/CC221641620J40758246109.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (506, '实施工程师', '同望科技股份有限公司', '7月23日', '4000-6000元', '珠海-香洲区', '计算机软件,计算机软件,计算机硬件,IT服务', '300-499人', '未融资', 'CC136740500J40503966704', '1、售后技术支持：为公司软件产品提供全方位的售后技术支持，通过电话、邮件等方式解答客户问题，确保客户满意度。<br>2、产品培训：根据客户需求，为客户提供软件产品的操作培训，使其能够熟练、有效地使用产品。<br>3、客户端验收测试：负责产品的客户端验收测试，确保产品质量和客户体验。<br>4、问题与需求收集：收集并汇总客户反馈的产品问题，定期向研发团队提供详细的产品问题与需求报告。<br>职业发展方向<br>作为技术支持工程师，将有机会深入了解公司软件产品的技术细节和客户需求。在积累了足够的产品知识和市场洞察后，可以向产品经理方向发展，参与产品规划、设计和管理，实现职业晋升和成长。<br>任职要求<br>1、工程造价、土木工程、道路与桥梁及工程管理等相关专业本科及以上学历；<br>2、五官端正，普通话标准，能够准确理解客户需求并流利、清晰地与客户沟通；<br>3、具备良好的应变能力，能够在面对突发情况时迅速作出判断和处理；<br>4、对软件行业有浓厚兴趣，具备较强的学习能力和团队合作精神，能适应出差。', '同望科技股份有限公司（以下简称同望科技）成立于1997年，是科技部火炬计划项目重点软件企业。公司专业从事项目管理、协同办公领域相关业务的管理研究和信息化技术开发，以\\\\\"满足客户成长的管理需求，提供科学系统的解决方案\\\\\"为宗旨，面向政府行政机关和行业主管部门、项目投资业主、施工企业、监理以及设计单位等客户，提供业务和技术领先的软件产品、管理信息化整体解决方案。历经十多年的快速成长，同望科技已成为中国工程建设领域客户首选的软件产品和咨询服务提供商，我们的产品和服务广泛应用于交通、建筑、石油化工、市政公用等行业领域。同望科技持续投入研发的核心产品和整体解决方案获得了国家级重点新产品荣誉证书，并在全国普及推广应用，在业内牢固树立了同望科技\\\\\"自信、领先、实力\\\\\"的优质品牌形象，成为万千客户的信心之选。同望科技现有员工400余人，拥有一支紧跟国际信息技术发展主流的研发团队、一批具备国际先进管理理论和实践经验的咨询专家。公司通过整合 ISO9000质量管理体系和CMMI 3级软件能力成熟度模型，建立了同望统一过程管理体系，以此形成软件企业可持续发展的核心竞争优势，并逐渐转化为差异化客户价值--\\\\\"领先的业务和技术，高性价比的产品，工期和质量保证的项目\\\\\"。同望科技坐落于珠海国家高新技术产业开发区\\\\\"同望科技园\\\\\"，东邻京珠高速公路出口，西傍南中国海海岸线，远眺著名的风景名胜淇澳岛。园区总占地面积 21400平方米，规划建筑面积 28000平方米，风景优美、园林式的现代化办公场所充分体现了同望科技\\\\\"创造一流环境、开发一流产品、提供一流服务\\\\\"的经营理念。同望科技的营销和服务网络遍布全国 31个省市自治区，建立了华北、华南、华东、华中、东北、西北、西南 7个营销服务大区和 20多个服务网点，为全国万余家用户提供高效、专业、完善的全方位咨询和服务。同望科技以优厚的薪酬待遇、全方位的福利保障、精彩的生活体验、广阔的职业发展空间以及持续的学习成长机会，与员工携手共筑辉煌未来。我们为员工提供业内领先的薪酬，以及各类带薪假期、五险一金、高额公积金、免费工作餐、酒店式宿舍和上下班通勤车等全方位福利保障；注重员工生活品质，提供丰富多彩的活动，如各类团建活动，生日活动、节日庆典、精致下午茶等，公司自有独立园区提供舒适的办公环境，并设有食堂、KTV休闲区、羽毛球、乒乓球、篮球场等设施；鼓励员工学习成长，提供各类培训和考证补贴。因公司长期致力于工程行业的管理与咨询，并提供管理类软件工具。诚邀对工程领域信息化有浓厚兴趣，并对工程管理软件的应用和市场开拓充满信心者加盟！资质：国家规划布局内重点软件企业国家火炬计划软件产业基地骨干企业信息产业部计算机信息系统集成贰级资质通过软件能力成熟度模型CMM5级评估珠海总部乘车路线：1、乘坐3A、65路至赛迪生巴士站，至十字路口左转前行约150米。2、乘坐68路、3路、10路公交车到下栅站下，向回直走经金鼎大圆盘2000米左右，在石头竖立\\\\\"创新科技海岸\\\\\"前一个十字路口右手旁一栋淡黄色楼面、嵌有红色框的大楼。', 'https://www.zhaopin.com/jobdetail/CC136740500J40503966704.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (507, '科研人员', '中国科学院深圳先进技术研究院', '7月12日', '2.9-3.5万', '深圳-南山区', '学术/科研,学术/科研', '1000-9999人', '未融资', 'CC227408420J40659600216', '岗位职责:<br>研究方向：<br>1．开展柔性传感材料及人机交互集成应用；<br>2. 印制电子技术，能量与交互器件；<br>岗位职责：<br>该岗位为中国科学院深圳先进院与头部企业与医院共同设置，联合推动国家重点研发计划与工信部重大平台项目，<br>1．在医院等合作者支持下，发表高水平论文与专利；<br>2.协助合作导师完成项目申报与推动项目日常管理；<br>任职要求:<br>1．已经或即将获得博士学位；<br>2．年龄不超过35周岁，博士毕业不超过3年，未在广东省从事过博士后工作；<br>3．热爱科研、勤奋努力，有良好的团队协作精神和沟通协调能力；<br>4．材料、电子等相关专业领域；<br>5．具有柔性传感与能量器件等相关方向的科研经验和成果产出；', '中国科学院深圳先进技术研究院由中国科学院、深圳市政府、香港中文大学2006年在深圳共同组建，已经逐渐成为集教育、科研、产业、资本四位一体的新型科研机构。先进院拥有一支结构合理，创新能力卓越的研发队伍，拥有一支由研究生、博士后、访问学者组成的高水平流动人员队伍，现有员工1800多人，50%具有博士学历；超过600人具有海外留学背景，PI（教授、副教授）百分之九十从国外引进回国。拥有一套先进、高效的管理体制和合理完善的科技成果转移、转化的科技成果被企业广泛接受与应用，培养的专门人才得到社会广泛认同与欢迎，成为人才一流、科研一流、管理一流的国家研究机构。--------------------- Shenzhen Institutes of Advanced Technology(SIAT)-Chinese Academy of Sciences was jointly established by Chinese Academy of Sciences(CAS), The Chinese University of Hong Kong(CUHK), and the Shenzhen Municipal Government in 2006. Over the past 13 years, SIAT has earned an outstanding reputation for translating findings from basic research into industrial application under the efforts of the interdisciplinary teams of scientists and engineers. The wide-ranging expertise drawing from technical, engineering or science professions has now positioned SIAT at the interface between biology technologies(BT) and information technologies(IT) for the 21st century innovation.', 'https://www.zhaopin.com/jobdetail/CC227408420J40659600216.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (508, '科研人员', '中国信息通信研究院', '2025-07-28 00:17:01', '1.9-2.1万', '北京-海淀区', '通信/网络设备,学术/科研', '1000-9999人', '未融资', 'CC251266610J40736938602', '岗位职责:<br>1、从事量子计算、量子通信、量子精密测量三大领域的技术产业研究，政府支撑，国际国内标准研制，数据平台能力建设，技术产品测试等科研工作。<br>2、开展量子信息领域的研究报告撰写，数据平台建设、标准研究制定、联盟会议活动、技术产品测试等业务工作。<br>3、承担领导交办的其他科研、支撑和业务相关工作。<br> <br>任职要求:<br>1、具备量子信息、通信、计算机、电子工程等领域专业知识（至少一项），取得相关专业硕士及以上学位<br>2、从事通信、计算机、电子等相关领域的科研、开发、测试等类型技术工作1年及以上，有技术标准研制经验优先，有数据平台开发维护经验优先。<br>3、具备较强的研究报告撰写、工作总结汇报和PPT制作介绍能力。<br>4、具有良好的自驱学习、多任务并行、沟通表达，团队合作和抗压能力。<br>5、英语达到CET-6及以上，具有较强的听说读写能力。<br>6、应聘者须提供1-2篇反映个人专业水准、与应聘职位相关的技术论文、研究报告等材料。', '中国信息通信研究院（以下简称“中国信通院）始建于1957年，是工业和信息化部直属科研事业单位。多年来，中国信通院始终秉持“国家高端专业智库产业创新发展平台”的发展定位和“厚德实学兴业致远”的核心文化价值理念，在行业发展的重大战略、规划、政策、标准和测试认证等方面发挥了有力支撑作用，为我国通信业跨越式发展和信息技术产业创新壮大起到了重要推动作用。近年来，适应经济社会发展的新形势新要求，围绕国家“网络强国”和“制造强国”新战略，中国信通院着力加强研究创新，在强化电信业和互联网研究优势的同时，不断扩展研究领域、提升研究深度，在4G/5G、工业互联网、智能制造、移动互联网、物联网、车联网、未来网络、云计算、大数据、人工智能、虚拟现实/增强现实（VR/AR）、智能硬件、网络与信息安全等方面进行了深入研究与前瞻布局，在国家信息通信及信息化与工业化融合领域的战略和政策研究、技术创新、产业发展、安全保障等方面发挥了重要作用，有力支撑了互联网+、制造强国、宽带中国等重大战略与政策出台和各领域重要任务的实施。', 'https://www.zhaopin.com/jobdetail/CC251266610J40736938602.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (509, 'C/C++', '软通动力信息技术(集团)股份有限公司', '7月22日', '1-2万', '上海-浦东新区', '互联网,IT服务,计算机软件', '10000人以上', 'D轮及以上', 'CC000544460J40519964216', '1、熟练使用C/C++语言进行编程， 熟悉常用的数据结构、算法<br>2、熟悉基本的TCP和UDP的网络通信开发，<br>3、有多线程编程经验者优先<br>4. 对PCIe总线和设备驱动有深入理解和经验。<br>5. 熟悉DPDK和SPDK的使用和开发。<br>6. 熟悉网络协议栈和网络编程。<br>7. 具备良好的团队合作能力和沟通能力，能够与团队成员和其他相关部门协作。<br>8. 有良好的英文读写能力，可以阅读英文文档和参考资料。', '软通动力信息技术（集团）股份有限公司（以下简称“软通动力”）是中国数字技术产品和服务创新领导企业，致力于成为一家具有全球影响力的科技企业，企业数字化转型可信赖合作伙伴。公司2005年成立于北京，多年来始终坚持科技创新，具有软硬全栈的智能技术产品和服务能力，提供软件与数字技术服务、计算产品与数字基础设施、数字能源与智算服务以及国际化服务。目前，公司在10余个重要行业服务超过1100家国内外客户，其中超过230家客户为世界500强或中国500强企业，员工近90000人。软通动力拥有软通咨询、软通金科、软通工业互联、机械革命、软通华方等业务子品牌，并在全球40余个城市布局业务，构建北美、日本、东南亚、中东四大国际交付中心，在北京城市副中心、江苏无锡建设两大智能制造基地。同时，公司前瞻布局智能制造、ICT软硬基础能力和生产力智能化产品，打造产业链闭环。软通动力设立30个能力中心，拥有1个国家级工程实验室，6个省市政府认定的工程、技术实验室及研发中心，1个博士后科研工作站，50+技术合作伙伴的生态合作体系，不断探索前沿技术的巨大商业应用潜力。公司旗下教育品牌软通教育，拥有一家全日制本科学院——郑州西亚斯学院数字技术产业学院；同时在全国合作院校600多所，设有70多个校企联合人才培养基地，通过校企合作、协同育人，为社会培养高素质应用型人才。软通动力先后获得“2023年中国IT服务市场排名TOP 1”、“2024年Q4 PC出货量国内市场份额排名TOP 2”、“2024年中国软件和信息技术服务竞争力百强企业”、“2023年中国信创企业100强”、“2024万得ESG评级（Wind ESG Rating）AA级及信息技术服务行业ESG综合得分排名第一”等荣誉及市场认可，并拥有全球软件工程领域最高级别CMMI V2.0成熟度5级评估认证、国家研发运营一体化（DevOps）三级能力成熟度模型认证、信息技术服务标准（ITSS）运维能力成熟度一级认证等专业资质，支撑公司更优质的服务体系。', 'https://www.zhaopin.com/jobdetail/CC000544460J40519964216.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (510, 'C/C++', '太极计算机股份有限公司', '6月28日', '3000-4000元', '深圳-福田区', '计算机硬件,计算机软件,IT服务,互联网', '1000-9999人', '已上市', 'CC000058760J40761447010', '1、负责项目主要设计与开发，包括需求分析、系统设计、功能开发<br>2、负责项目技术攻关解决<br>3、参与项目实施及推广<br>4、26届，计算机相关专业，实习期能保证6 个月及以上。', '太极计算机股份有限公司（以下简称“太极股份”）是国内电子政务、智慧城市和关键行业信息化的领军企业，2010年在深圳证券交易所上市。公司以“做中国最优秀的数字化服务提供商”为愿景，致力于成为“自主可控的主力军，数据运营的国家队，智能应用的引领者，员工价值的成就者”，瞄准数字政府、数字企业、数字国防，着力打造自主通用产品，提升数据运营服务能力，推动行业智能创新应用，助推国家治理体系和治理能力现代化建设，成为网络强国、数字中国、智慧社会建设的中坚力量。成立三十余年来，砥砺奋进、精耕细作，太极股份以客户需求为导向，成为国家重大信息系统总体设计和工程建设的主要承担者，国家电子政务、网络信息安全以及关键行业政策和相关标准制定的倡导者与积极参与者，为党的领导和国防、外交、公共安全、宏观经济、金融、民生服务、工业生产等提供重要的信息化支撑作用。在持续为中央部委、地方政府、大型集团企业客户创造数字化价值过程中，公司树立了可信赖的“国家队”形象。作为中国电子科技集团有限公司软件与信息服务龙头企业、自主可控总体单位、智慧城市与数字政府牵头单位，太极股份坚持创新驱动，被列为国家科技部和中关村科技园区创新试点示范单位，连续多年被认定为国家规划布局内重点软件企业和全国软件产业收入前百家企业。此外，公司还是中国软件行业协会副理事长单位、中国智慧城市产业技术创新战略联盟副理事长单位、北京软件和信息服务业协会会长单位、智慧北京促进联盟理事长单位、信息技术应用创新工作委员会理事单位、WG12公共数据运营工作组成员单位，以及多个行业学协会的发起者和重要参与单位，携手合作伙伴和产业机构，共创和谐生态环境。进入数字化时代，太极股份坚持以“数据驱动、云领未来、网安天下”为核心战略指引，聚焦数字政府、数字企业、数字国防等领域，加大布局云与数据服务、自主软件产品及数字基础设施等战略性新兴产业，探索数据开发利用的标准规范与创新思路，着力打造数字化咨询、数字技术与核心产品创新、资本与产业融合等核心能力，推进公司数字化转型，推动“数字中国”建设。创新融合，让我们的世界更智慧。', 'https://www.zhaopin.com/jobdetail/CC000058760J40761447010.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (511, '技术支持工程师', '凌云光技术股份有限公司', '3月28日', '8000-9000元', '苏州-吴中区', '电子/半导体/集成电路,运营商/增值服务', '1000-9999人', 'B轮', 'CCL1290237120J40488020513', '岗位职责：<br>1、参与售前方案评估，负责设备的安装、调试、验收；<br>2、负责设备的维护、培训，与客户的各个层次的负责人做良好的技术交流。<br>岗位要求：<br>1、机械、电器、光电信息、自动化、计算机等相关专业；<br>2、具备良好的与人沟通的能力；<br>3、可适应出差。', '工业智能化是世界主题，更是历史机遇。凌云光技术股份有限公司以光技术创新为基础，战略聚焦机器视觉业务，坚持“为机器植入眼睛和大脑”，为客户提供可配置视觉系统、智能视觉装备与核心视觉器件等高端产品与解决方案。我们始终坚持以客户为中心，赋能电子制造、新型显示、印刷包装、新能源，影视动漫、科学图像、轨道交通等行业的智能“制造”。目前公司2000余人，硕博25%，研发39%，管理战略理念前瞻。基于近30年在光学成像、视觉软件与算法、核心视觉部件等领域的技术积累，公司持续产品创新，努力成为客户最优的、战略的、信赖的和荣耀的选择。我们事业目的是以服务各个行业辛苦劳作的技工，专家和管理者，让他们的工作更加高效为宗旨。MVV凌云使命MISSION为机器植入眼睛和大脑，赋能光速互联，创造和实现客户梦想。凌云愿景VISION成为视觉人工智能与光电信息领域的全球领导者！企业核心价值观VALUE以推动行业发展为己任，集体艰苦奋斗。把知识转化为财富，让财富归属于它真正的创造者。', 'https://www.zhaopin.com/jobdetail/CCL1290237120J40488020513.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (512, '科研人员', '浙江大学绍兴研究院', '6月30日', '1.6-3万·15薪', '绍兴-越城区', '学术/科研,学术/科研', '100-299人', '未融资', 'CCL1406588970J40707676412', '专业要求：', '为深入实施创新驱动发展战略，推动浙江大学科技资源更好地融入绍兴经济社会发展，2021年11月19日绍兴市越城区人民政府、绍兴市滨海新区管委会与浙江大学签署共建浙江大学绍兴研究院合作协议。浙江大学绍兴研究院于绍兴市越城区、滨海新区正式落地，并于2022年1月21日挂牌成立。浙江大学绍兴研究院是由浙江大学、绍兴市越城区、绍兴滨海新区管委会、共同组建的事业单位，是依托绍兴市区位、资源、产业优势和浙江大学在科技研究、人才培育、文化传承创新方面资源共同建立的新型研发机构，总部坐落在风景秀丽的迪荡湖。研究院以“资源共享、优势互补、合作共赢”为原则，围绕集成电路、生物医药、新材料、文化产业等领域，设立微电子研究中心、生命健康研究中心、亚洲文明研究中心，旨在面向科技发展前沿和产业发展需求，开展前沿关键技术研发创新与区域文化品牌拓展，引育一批高层次人才，孵化一批高科技产业项目。研究院下设微电子研究中心、生命健康研究中心、亚洲文明研究中心：（一）微电子研究中心：主要包括智慧电力芯片、智慧电力与信息装备、智慧电力与能源系统装备、先进封装平台、智能传感器芯片、高速与微弱信号处理设计、半导体高效能源材料等研发与转化，助推绍兴争创集成电路国家产业创新中心和省实验室。（二）生命健康研究中心：主要开展基因治疗、细胞治疗、新型疫苗、精准诊治、先进健康材料与器械、先进诊疗材料与器械、先进分离膜材料与器械设备等前沿颠覆性技术研发与转化，培育产业发展新动能，打造成为浙江大湾区生命健康产业的创新引擎，国内生命健康产业的战略高地，争创国际一流的生物医药创新中心、省级技术创新中心。（三）亚洲文明研究中心：立足亚洲文明互学互鉴和文旅融合发展，聚焦绍兴大禹、王阳明、鲁迅、书法、黄酒等文化金名片，着力彰显吴越文化、宋韵文化的独特价值，从名城、名人、名物、名胜四个方面提升区域品牌的国际化、特色化、数字化和品质化，助力打造“东亚文化之都”。浙江大学绍兴研究院将充分发挥浙江大学大学学科优势，面向国家和地方重大战略需求，时刻坚持科技赋能、文化引领的目标方针，以坚持人才强基为原则，引育并举打造高水平人才蓄水池，促进高水平成果转化，全面打造校地合作新典范。', 'https://www.zhaopin.com/jobdetail/CCL1406588970J40707676412.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (513, '硬件测试', '佛山耀立电气有限公司', '4月21日', '4000-7000元', '佛山-南海区', '电气机械/电力设备,电子/半导体/集成电路', '20-99人', 'A轮', 'CC488656880J40704903816', '岗位职责：<br>1、熟悉各类电子元器件及其性能，执行生产前的来料检验、测试；<br>2、负责电路与仪表仪器等设备的调试工作；<br>3、进行电路板的焊接与测试，并协助产品的装配、调试等工作。<br>任职资格：<br>1、大专及以上学历，电子信息工程、质量管理等相关专业;<br>2、具有半年及以上质量管理相关工作经验，熟悉电路与电子元器件:<br>3、能够使用万用表、示波器等基础检测工具;<br>4、具有 iso90001 质量管理体系认证证书优先；<br>5、责任心强，积极主动，具有良好的沟通表达能力。', '佛山耀立电气有限公司是一家高端智能装备公司，专注于为客户提供机器人智能焊接电源及自动化一站式解决方案。耀立电气基于自主研发的焊接控制算法，打造一系列适用于机器人自动焊接领域的智能硬件设备以及系统，打破了国外品牌在高端焊接装备领域的技术钳制，解决了企业招聘焊接工人难、生产效率低下、人力成本攀升等难题。公司已联合浙江中科院、华南理工大学，设立产学研创新中心，在船舶与海洋工程、海上风力发电、石油天然气管道、大型发电设备等领域进行行业应用研发、技术人才培养及客户技术服务的联合研究开发，助力我国制造业高质量发展。', 'https://www.zhaopin.com/jobdetail/CC488656880J40704903816.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (514, '测试工程师', '安徽刚毅电子科技有限公司', '7月26日', '4000-6000元', '六安-舒城县', '计算机硬件,电子设备制造', '1000-9999人', '不需要融资', 'CC462926530J40708715714', '岗位内容：<br>1. 建立和维护软件产品的测试计划和策略。<br>2. 负责软件测试阶段的进度管理和问题跟踪。<br>3. 审查需求文档，识别并管理关键的测试风险。<br>4. 持续改进测试流程和工具，提高测试效率和质量。<br>5. 向其他团队成员提供培训和支持。<br>任职要求：<br>1. 五年以上软件测试工作经验。<br>2. 精通测试常见工具和框架（如JIRA、TestRail、Appium）。<br>3. 熟悉测试理论和流程，能够制定测试计划和策略。<br>4. 具有较强的问题分析和解决能力。<br>5. 能够在压力下工作，并保证结果的准确性。 6.大专以上应届毕业生无经验可培养', '安徽刚毅电子科技有限公司隶属于台北连宏科技集团，成立于2016年6月，坐落于安徽省六安市舒城县杭埠镇经济开发区金基产业园，车间及办公区约13000㎡。我司主要制造销售计算机零组件、转轴组件、组立件。项目总投资人民币壹亿元，位于六安市舒城县杭埠镇金基产业园金桂路。目前在职员工将近1100人。团队在持续扩展相关设备也在不断增加，有独立自主研发团队，我司是六安市百强企业，舒城县十强企业，有规范的财务和管理制度，被六安市经济和信息化局评定为“专精特新”企业，短短几年我们已取得400多项专利，并成为联想、华为、小米、acer、hp、dell等国际企业的优质供应商，在电脑转轴这一细分领域市场占有较高地位，笔记本转轴市场份额目前位居全球第一。2020年度产值达到4个亿，产能达到4000万,纳税达到两千三百多万。', 'https://www.zhaopin.com/jobdetail/CC462926530J40708715714.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (515, '技术支持工程师', '武汉市恒际自动化科技有限公司', '2025年07月30日', '7000-10000元', '武汉-江夏区', '电气机械/电力设备', '500-999人', '不需要融资', 'CCL1491150470J40784831314', '岗位职责：<br>1、负责电力配套产品的售前、售后支持工作，包括现场演示、实验、检修及客户端交流，进行产品交货使用培训<br>2、产品现场测试、记录信息，技术素材的收集、整理、使用和归档<br>3、出具技术报告，为客户提供高质量的技术解决方案<br>4、负责公司内部员工产品及行业知识培训，与内部部门沟通协调配合<br>5、负责技术标书部分的编写和相关标书编写技术指导<br>6、领导交代的其他工作。<br>任职要求：<br>1、大专及以上学历；接受应届生<br>2、电气工程及其自动化、电力相关自动化等专业<br>3、熟练掌握CAD、3DMAX等制图软件<br>4、熟悉配网领域电力知识，从事过10kV配电线路配网不停电检修、维护、抢修等工作经验者优先考虑<br>5、具有较强的书面表达及PPT和文字撰写能力<br>6、吃苦耐劳、性格活泼开朗、具有较强的技术交流及专业服务能力<br>福利待遇：7000-10000元<br>五险一金 带薪年假 团队建设 节假日福利  单位提供免费住宿及生活用品（2-4人间，独卫，拎包入住)，上班期间提供免费餐', '在工业领域方面，主要从事自动化控制、智能制造、高低压配电产品、智能软启动器与计算机控制系统集成等。公司的业务涵盖冶金、化工、纺织等行业的自动化控制系统和电气传动系统的设计、制造、安装和调试。业务范围遍布全国及非洲地区。', 'https://www.zhaopin.com/jobdetail/CCL1491150470J40784831314.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (516, '技术支持工程师', '英创人才服务(上海)有限公司', '7月4日', '6000-8000元·17薪', '苏州-吴中区', '人力资源服务,电子/半导体/集成电路,电气机械/电力设备,工业自动化', '100-299人', '不需要融资', 'CC143661450J40796274113', '工作内容：<br>【业务内容】客户访问（技术咨询对应、现场对应）、分析业务、解析业务。', 'PERSOLKELLY是亚太地区最大的人力资源公司品牌之一，为客户提供全方位的人力资源解决方案。总部位于新加坡的PERSOLKELLY成立于2016年，在 13个国家和地区设有超过45个办事处，将更好的协助您引进海外人才和拓展海外市场。我们将继续秉持“实现员工与企业共成长”的理念，一如既往的为客户提供一站式人力资源服务。这些都标志着PERSOLKELLY正在竭力为客户打造一个世界领先的对接平台，使客户可以顺利获得世界一流的人才招聘和人事劳务咨询服务。PERSOLKELLY英创人才将一如既往地向每一位候选人提供一对一服务以及职业生涯指导作为特色，我们一直致力于协助求职者的职业发展，所有面向求职者的职业访谈，职业规划，面试辅导，简历指导都是免费提供。PERSOLKELLY英创人才拥有12000家以上的客户，57万名以上登陆者，以及每年超过1万件以上的海量招聘职位。在提供人才服务的同时，公司内还拥有丰富的培训经验的讲师团队。', 'https://www.zhaopin.com/jobdetail/CC143661450J40796274113.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (517, '测试工程师', '国轩高科股份有限公司', '6月25日', '1-2万·13薪', '合肥-包河区', '电子/半导体/集成电路', '10000人以上', '已上市', 'CC344684980J40644300712', '岗位职责:', '柳州国轩电池有限公司（简称“柳州国轩”）是合肥国轩高科动力能源有限公司控股子公司，成立于2020年6月30日。项目整体规划968亩，产能规划30GWh。2024年已建成年产能20GWh的磷酸铁锂电池生产基地，后期10GWh在筹备建设中。公司主要产品为磷酸铁锂方形电芯、动力电池组、电池管理系统及储能型电池组，主要应用于乘用车、商用车、轮船及工商业储能等市场领域。柳州是“国轩高科一带一路桥头堡”，定位于服务华南市场，同时做为国轩东南亚市场的平台主体支持东南亚市场，打造西部陆海大通道的最佳实践。作为国轩高科立足华南面向东南亚市场的辐射中心，深入贯彻“做精铁锂、做强三元、做大储能”的战略思想，助推国轩高科全球化进程。', 'https://www.zhaopin.com/jobdetail/CC344684980J40644300712.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (518, 'Java', '外企德科数字技术有限公司', '2025-07-27 00:23:23', '1.4-2.8万·14薪', '合肥-蜀山区', '专业技术服务', '10000人以上', NULL, 'CCL1480117890J40610764005', '岗位职责：<br>1、负责业务体验产品相关产品研发，完成多个模块/组件的软件设计（含增量方式）、代码编写、单元测试、集成测试、静态检查、本地构成等工作，确保所负责模块可信、及时、高质量交付；<br>2、负责设计实施高可用部署架构，实现弹性扩缩容，秒级故障自动切换，限流降级等核心功能，保障大规模集群的高效稳定运行；<br>经验要求：<br>1、有开发经验，C/C++、Java、Scala、Python、JS等开发语言一种或多种；<br>2、熟悉分布式系统的设计和应用，熟悉高并发、高负载、高可用性系统的设计开发及调优，熟悉分布式缓存、消息、数据库等机制；<br>3、具有一定的技术架构思维，确保设计的技术方案、开发的代码有较高性能、质量保障、扩展性，前瞻性；<br>4、参与系统以提升效率为目的的整体的优化、改进，出现问题时能够通过较强的技术手段较好的解决问题。  办公地点在南京，上海，苏州，杭州，深圳，北京，西安，成都，东莞，长沙，济南，武汉等研究所  <br>', '外企德科数字技术有限公司是一家2023年新成立的中外合资企业。成立于2023年11月24日，公司定位：专注于为信息技术企业提供人才及数字技术外包解决方案的中外合资企业。它是由中国人力资源服务行业的FESCO（北京国际人力资本集团）与全球人力资源服务领导者The Adecco Group（德科集团）合资成立的。公司主要提供网络技术服务、软件外包服务、计算机系统服务、技术进出口、软件开发等信息技术相关服务。专注于为信息技术企业提供信息技术类人才及数字技术外包解决方案。', 'https://www.zhaopin.com/jobdetail/CCL1480117890J40610764005.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (519, '硬件测试', '深圳市星视典劳务派遣有限公司', '7月20日', '7000-9000元', '深圳-龙华区', '人力资源服务', '1000-9999人', 'A轮', 'CC446535310J40753172907', '⭕正式工底薪：2600-3050元/月<br>三个月考核晋升资位，每晋升一个阶级底薪加班费随底薪基础上调，平时加班1.5倍，周六日加班2倍，法定节假日3倍，享有岗位津贴、绩效奖金、月综合工资7000左右<br>(入职当月享有买五险一金)⭕年底会有，甲，乙，丙，丁，甲年底5000奖金，以此类推', '深圳市星视典有限公司是一家专业的人力资源机构，公司成立于2010年，注册资金2000万，派遣员工有8000多人，公司以人力资源外包服务、高级人才猎头、HR管理咨询、后勤托管服务为主营业务，凭借对多年人力资源服务经验的总结与提炼，摸索出了一套完善的服务体系和管理流程，为众多世界500强企业、上市公司及世界一流的财团、商会提供了优质的人力资源服务，深受好评。我们秉承“开拓进取，创新服务，精益求精”的理念，致力于成为世界一流的人力资源服务供应商。真诚服务每位很想工作的朋友，', 'https://www.zhaopin.com/jobdetail/CC446535310J40753172907.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (520, '技术支持工程师', '浙江浙仪控股集团有限公司', '7月9日', '2.5-3万', '杭州-钱塘区', '仪器仪表制造', '100-299人', '不需要融资', 'CCL1357686830J40534299706', '研究方向：热分析及量热，锂电池安全<br>【岗位职责】<br>1.负责行业技术应用项目方案设计；<br>2.提出技术创新及原创仪器构想；<br>3.负责技术应用背景调研；<br>4.配合销售部门，提供售前技术支持；<br>5.配合市场部门，进行技术交流及宣传。<br>【任职资格】<br>1.年龄在35周岁以下，博士学位；<br>2.新能源、锂电池、化学、化工、材料等相关专业背景;<br>3.对仪器开发有强烈的兴趣，具有学科交叉思维和跨科学知识灵活运用能力,具备较强的工程能力。<br>【薪酬说明】<br>以博士后招收进站，在站期间薪酬水平30-40万元/年，出站后薪酬另议。同时享受各类人才补贴预计100万元。', '浙仪集团始建于2006年11月，总部位于中国杭州，是国家级高新技术企业，是国内领先的高质量专业仪器提供商。浙仪集团成立于2021年8月，以仰仪科技、泰默检测等公司为基础控股整合，设应用研究院、工程技术、工程服务等直属机构，拥有博士后工作站，多次获得省部级科技进步奖。集团面向新能源、精细化工等国家战略导向行业拥有领先的测试解决方案，相关产品获得国内知名企业、重点高校及科研院所的认可与选择，同时覆盖欧盟、北美、亚太、中东等地区。集团立足于需求与应用研究，融合前沿技术研究、创新仪器开发、高端装备制造，探索数智化创新升级与实践；持续为石化、新能源、精细化工、国防工业、生命科学等领域提供专业仪器、定制设备、系统解决方案、技术咨询和维保服务。集团致力于跻身国际高质量仪器行列，缔造专、精、尖的全新国产品牌，助推国家科技、经济与社会的进步与发展。', 'https://www.zhaopin.com/jobdetail/CCL1357686830J40534299706.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (521, 'C/C++', '陕西慧云联达企业管理咨询有限公司', '6月28日', '1.5-3万·16薪', '成都-郫都区', '人力资源服务', '20-99人', '不需要融资', 'CCL1445845820J40723362805', '岗位职责：<br>1.参与公司产品及项目开发，完成需求分析，完成子系统和模块设计。<br>2.根据项目进度要求，完成子系统和模块开发、单元测试和系统联调。<br>3.根据公司规范要求，编写技术文档。<br>4.系统重构、功能升级和解决bug。<br>任职要求：<br>1、熟悉掌握但不限于C++/C/Python/Go等编程语言中的一种或数种；<br>2、了解网络知识、linux配置和shell使用；<br>3、了解常用的软件机构模式、基本的编程编译工具；<br>4、统招本科及以上学历。', '陕西慧云联达企业管理咨询有限公司成立于2022年9月，是一家集高端猎头服务与专业代理记账报税业务于一体的综合性企业服务提供商。自成立以来，我们秉承“智聚英才，财通未来”的企业理念，致力于为国内外企业客户提供精准高效的人力资源解决方案及一站式财务管理服务，助力企业稳健成长，共创辉煌。', 'https://www.zhaopin.com/jobdetail/CCL1445845820J40723362805.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (522, 'C/C++', '陕西慧云联达企业管理咨询有限公司', '7月22日', '2-4万·14薪', '上海-浦东新区', '人力资源服务', '20-99人', '不需要融资', 'CCL1445845820J40795860105', '岗位内容： <br>1. 设计、开发和维护高质量的C++应用程序；<br>2. 实现并优化算法和数据结构；<br>3. 负责软件系统的性能优化和调试；<br>4. 参与项目需求分析和技术选型。<br>任职要求： <br>1. 本科及以上学历<br>2. 具有良好的算法和数据结构基础；<br>3. 具备沟通协调能力和团队合作精神；<br>4.有计算机科学/软件工程背景。', '陕西慧云联达企业管理咨询有限公司成立于2022年9月，是一家集高端猎头服务与专业代理记账报税业务于一体的综合性企业服务提供商。自成立以来，我们秉承“智聚英才，财通未来”的企业理念，致力于为国内外企业客户提供精准高效的人力资源解决方案及一站式财务管理服务，助力企业稳健成长，共创辉煌。', 'https://www.zhaopin.com/jobdetail/CCL1445845820J40795860105.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (523, '技术支持工程师', '石家庄鸣迅信息技术有限公司', '4月15日', '8000-12000元', '北京-海淀区', '企业服务', '20-99人', NULL, 'CCL1499764550J40900443904', '岗位职责：<br>1、完成产品安装、调试、维修、维护，保证设备正常运行；<br>2、解决客户在产品使用过程中遇到的问题；<br>3、根据用户需求、结合产品功能提供合适的解决方法；<br>4、按时按质按量完成上级临时交办的其他工作。<br>职位要求：<br>1、计算机类，网络工程，软件工程等相关专业优先考虑，专科及以上学历；<br>2、精通网络、主流网络设备调试；熟悉 TCP/IP协议架构；<br>3、熟悉网络原理以及网络原理及网络交换、路由、桥接等技术；<br>4、掌握数据库基本理论基础，了解 mongo db 或sql server基本维护；<br>5、具备良好的沟通能力和人际礼仪，待人诚实可信，语言表达能力和动手能力强；<br>6、能适应外派的工作。', NULL, 'https://www.zhaopin.com/jobdetail/CCL1499764550J40900443904.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (524, '技术支持工程师', '上海繁易信息科技股份有限公司', '6月25日', '7000-10000元·15薪', '苏州-虎丘区', '互联网,仪器仪表制造', '100-299人', '未融资', 'CC522883120J40804801503', '岗位职责：<br>1、 协助客户找到合适的技术方案，做售前咨询与售后技术支持 ；<br>2、电话或现场帮助客户解决使用公司产品遇到的问题 ；<br>3、为客户提供产品技术培训。<br>职位要求：<br>1、本科及以上学历，自动化、电气类、机械类专业优先，应届毕业生优先；<br>2、了解变频器，步进、伺服等常见工控设备；<br>3、良好的沟通协调能力和分析解决问题的能力；<br>4、工作认真,责任心强,积极主动 ；', '我们诚邀您加入上海繁易信息科技股份有限公司。上海繁易信息科技股份有限公司是国家高新技术企业，杨浦区专精特新企业，上海市软件企业，荣获杨浦区小巨人称号。繁易总部位于上海，在北京、深圳、江苏、浙江都有我们的分公司及办事处。繁易是一家工业物联网软硬件一体化解决方案提供商。我们为设备制造商和终端用户挖掘更多设备价值，提升效率、降低成本、优化管理，推动设备制造商服务转型。繁易自主研发和拥有FlexCloud物联网平台、FlexHub终端连接平台、FlexManager终端管理平台、FlexEdge边缘计算平台以及包括FBox、HMI、PLC在内的众多工业物联网终端产品。', 'https://www.zhaopin.com/jobdetail/CC522883120J40804801503.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (525, '科研人员', '大连测控技术研究所(中国船舶集团有限公司第七六〇研究所)', '8月26日', '8000-12000元', '大连-中山区', '学术/科研', '20-99人', NULL, 'CCL1473919760J40742147415', '参与我所有关科研项目的组织实施工作。 任职要求：', NULL, 'https://www.zhaopin.com/jobdetail/CCL1473919760J40742147415.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (526, '测试工程师', '贵州恒创顺互联网科技有限公司', '6月11日', '8000-14000元·13薪', '成都-锦江区', '云计算/大数据,IT服务', '100-299人', '未融资', 'CCL1249043630J40646886403', '岗位内容： <br>1. 设计测试用例并执行测试计划，对软件功能、性能、稳定性等进行全面测试。<br>2. 编写测试报告和Bug汇报，跟踪Bug的解决过程，并及时反馈BUG情况给研发团队。<br>3. 参与产品设计和需求评审，提供测试意见和建议。<br>4. 熟悉自动化测试框架或工具，并进行相关测试工作。', '自公司成立以来，始终专注空间信息技术的服务与应用，在土地数字化和信息化方面积累了人才、技术、经验及服务过近千家政府客户，成为国家自然资源部和农业农村部重要支撑单位。因为专注和创新才有了今天的突破与成绩:公司自主研发的时空大数据基础平台和农业地理大数据平台(国源地图),以“云+端”的方式，提供“数据+平台+应用”三位一体的空间信息SaaS服务，构建国源地图，使其成为中国数字农业的基础设施。', 'https://www.zhaopin.com/jobdetail/CCL1249043630J40646886403.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (527, '实施工程师', '烟台开发区德联软件有限责任公司', '7月18日', '8000-16000元·13薪', '烟台-福山区', '计算机软件,互联网,IT服务', '100-299人', '不需要融资', 'CC609978120J40757053610', '岗位职责：<br>1、海外客户技术交流：EMS系统及功能介绍，理解用户需求，完成前期需求分析，相关部门反馈。 2、技术咨询解答：EMS功能及适用介绍、电气设备选型、架构图设计等；协助销售人员给客户提供技术支持，提供技术方案。 <br>   3、技术与商务翻译协助：负责海外客户技术、商务交流，提供翻译支持，推动项目进展。  <br>4、资料翻译协助：负责处理海外业务、各类技术文档、商务资料、公司英文介绍等资料翻译。  <br>5、领导交代的其他事宜。  岗位要求：    <br>1、本科及以上学历，电气、计算机等相关专业，有海外经历优先。CET-6/专四专八等水平，英语语言可熟练交流。    <br>2、有电力电气相关行业工作经验优先。', '公司从事智能电网与新能源相关领域的软件开发，完成了多项国家级示范工程项目，如张北风光储输一体化监控系统的储能监控、青海格尔木时代光储项目、北京市数十个充换电监控与运营管理系统、华能风电集控系统、北京供电局广域控制系统等。公司员工大部分都是985学校毕业，是一只技术精湛、勤奋敬业的梦之队。欢迎有事业心、对软件编程有浓厚兴趣的人才加盟，共同努力，创造美好未来。公司成立于2001年，是一家专门为能源行业提供监控管理完整解决方案的企业。公司位于风景秀丽的海滨城市烟台，是烟台海外留学创业园区的骨干企业。德联公司自成立以来，一直专注于电力及新能源行业，多年来持续不断地研究开发，拥有了自主知识产权的能源物联网开发平台SE2000。基于SE2000平台,公司开发了30多种应用软件，能够为发电、输变电、配用电等多个领域提供完整的监控管理解决方案，主要产品包括：广域控制系统（WAMS）、电网调度监控系统、配网自动化系统、电力集控运维平台、电能计量计费系统、电厂调频性能考核评价软件、电力智能操作票管理软件、厂矿企业能源管理系统、故障测距主站系统软件、嵌入式通信管理机、新能源电站并网性能评价考核系统、AGC/AVC系统、新能源发电功率预测系统、风电集控运维系统、光伏集控运维系统、储能电站EMS系统、储能电池性能监测与大数据分析软件，电动汽车充换电站监控与运营管理系统、综合能源监控管理平台等。德联拥有三十多项软件著作权，是双软认证企业、国家高新技术企业，并通过CMMI3国际认证。德联公司已经发展了30余家经销商和OEM伙伴，为国内外500余家客户提供服务，完成了多项国家级有代表性的项目，比较典型的工程有：北京供电局广域控制系统（WAMS）、北京供电局储能电站调控平台、北京供电局储能运检平台、北京大型电动汽车充换电站综合监控管理系统、河北南网广域控制系统、张北风光储示范工程储能电站EMS系统、青海格尔木时代光储电站联合调度监控系统、青海海西州风光储热多能互补EMS系统、中国电科院分布式储能监控运维平台、山西火电厂储能调频系统、巴西风储EMS系统、河南台前县光伏扶贫监控平台、国电投800MW光伏运维平台、华能国际风电（集控）系统、胜利油田海上平台电力监控及实时WEB发布系统、邯郸峰峰煤矿电力调度与计量计费系统、天津变电站集中托管运维平台、国家电网数模混合仿真中心集中监控平台等，是国内少有的几家能提供几乎全系列能源管理解决方案的公司。近几年，公司积极开拓海外市场，产品已销往英国、波兰、巴西、印尼、越南、伊朗等国家。德联SE2000能源物联网开发平台，是公司自行开发的能源行业实时系统开发平台，具有完善的SCADA、EMS、WAMS功能，完全符合IEC 61850、IEC61968/61970、IEC 61400-25等电力行业的国际标准。软件支持所有主流的操作系统，包括：Windows系列、Linux、Unix等。数据库支持Oracle、Sybase、DB2、SQL Server、My SQL、PI及国产达梦、金仓等。软件支持英语、西班牙、葡萄牙、日语、阿拉伯语等多种语言。德联将秉持专业、专注的宗旨，以先进的技术和优质的服务，继续为能源行业广大客户提供优质的解决方案。欢迎广大有志之士加入德联大家庭。', 'https://www.zhaopin.com/jobdetail/CC609978120J40757053610.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (528, '科研人员', '长沙红海人力资源有限公司', '6月17日', '4000-6000元', '长沙-芙蓉区', '咨询服务,人力资源服务', '1000-9999人', '未融资', 'CC508666720J40757954010', '中南大学湘雅二医院刘姗姗教授课题组诚聘科研助理<br>刘姗姗，山东潍坊人，中南大学湘雅二医院代谢内分泌科、糖尿病免疫学教育部重点实验室、国家代谢性疾病临床医学研究中心 教授，博士生导师。长期致力于研究器官纤维化的免疫发病机制和干预策略，重点关注代谢异常在纤维化发生发展中的作用。相关成果以第一/通讯作者（含共同）发表在Immunity（2篇，2019，2021）、STTT（2020）、Acta Pharmaceutica Sinica B（2篇，2021，2023）、Journal of Advanced Research（2024）、Metabolism (2025)、Cell Reports（2023）等国际权威杂志，共发表学术论文40余篇。<br>现因工作需要，公开招聘科研助理1名。经面试考核后择优录取。具体招聘岗位及要求如下:<br>岗位内容:<br>1) 参与实验室日常管理；<br>2) 协助组织课题组日常科研相关活动；<br>3) 协助课题组科研相关工作。<br>岗位要求:<br>1)本科及以上学历；具有生物或医学专业背景；<br>2)具有强烈的事业心和责任感，吃苦耐劳，具备良好的人际沟通能力；<br>3)具有小鼠实验技能者优先；<br>4)能较长期稳定工作。<br> <br>岗位待遇:<br>拟录用人员实行劳务派遣，与长沙红海人力资源有限公司签订劳动合同，由红海派遣至中南大学湘雅二医院工作。待遇从优，具体面议。同时，课题组将对工作优秀者给予奖励。', '长沙红海人力资源有限公司长沙红海人力资源有限公司成立于2007年6月，2009年10月正式投入运营，是一家具有劳务派遣，劳务外包和人力资源管理咨询等资质并具备独立法人资格的专业人力资源服务有限公司，隶属红海人力集团。长沙红海公司依托红海人力集团雄厚的实力，自身优秀的专业团队，精湛的人力资源管理专业，全心全意为客户服务的精神，以崭新业务模式，竭诚为各专业用人单位提供理想的人力资源服务。长沙红海公司主要为各用人单位提供以下专业服务：劳务派遣：全风险劳务派遣；劳务外包：全风险服务外包；社保代理；工伤代理；业务外包；劳动保障咨询；职业资格认证培训等。长沙红海公司坚持“诚信连接，成就你我”的价值理念。致力于为我们的合作伙伴创建一个节约高效的人事管理体系。选择长沙红海与你走进色彩缤纷的人力资源世界，实现双赢。', 'https://www.zhaopin.com/jobdetail/CC508666720J40757954010.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (529, '技术支持工程师', '青岛安然物联网科技有限公司', '7月22日', '8000-16000元', '安庆-迎江区', '物联网,物联网', '20-99人', '未融资', 'CC559764920J40565608304', '需要弱电技术、自动化、安防系统、工业互联网+危化安全生产、物联网人才，不要纯软件人才。  你能经常到全国各地出差吗？你能到工业生产现场生产现场做技术支持吗？     真正的奋斗者在安然会有让人值得为之奋斗的事业，会有充实、高效的成长，会有高人一等的收入。', '基于精准人员定位的工业安全生产信息化管理专家，安全生产信息化管理引领者！作为全国实时定位技术标准工作组成员和应急管理部“工业互联网+危化安全生产”人员定位系统技术支持机构，安然从2012年起致力于基于ZigBee Plus三维立体按需精准定位的“工业互联网+安全生产”的研究，获得了20多项安全智能管控系统发明专利和著作权，持续引领中国化工行业生产现场智慧安全！安然以“准、稳、狠”的ZigBee Plus三维立体按需精准人员定位统和“底数清、数据准、情况明、研判准、措施实”的安全生产信息化平台为核心，整合访客管理、出入口控制、人脸识别、视频监控、语音广播、重大危险源监控、可燃有毒气体监测等系统，对生产现场人、机、料、法、环五大要素进行实时、动态、智能管控和预警，规范人的安全行为，保障人的生命安全，有效防范风险、主动化解风险，实现智慧安全。安然“以用为本”，把安全生产信息化建设与公司管理体系“深度融合”，把安全生产信息化建设与日常工作“紧密结合”，对安全生产切实“有用、实用、好用”，避免建用“两张皮”，让安全管控更智能，让生产更高效才实用。迄今已服务中石化、中石油、延长石油、国能、兖矿、京能、索普、新安、奇美、昊源、潞安、旭阳、垦利、逸盛、海科、酒钢、金发等几百家石化、化工、选煤、钢铁、电厂企业。安然以客户为中心，以强者为本，抬头乐干，愿意与同道中人联合、链接，携手共建、共用、共享生产安全命运共同体，一起干，一起干，让优秀企业更安全，让优秀企业更高效！', 'https://www.zhaopin.com/jobdetail/CC559764920J40565608304.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (530, 'C/C++', '外企德科数字技术有限公司', '2025-07-27 00:26:01', '1.5-3万·14薪', '成都-双流区', '专业技术服务', '10000人以上', NULL, 'CCL1480117890J40794055605', '岗位类型：OD招聘-软件类岗位<br>目前各大产品线均有需求，业务方向丰富，有Java、C、C++、Python、go、JS等语言开发，测试、算法、大数据开发、安卓、IOS、运维等也有涉猎。<br>岗位情况： <br>1.统招本科及以上，无经验要求，但是需要会相关技能（用对应的语言写代码）； <br>2.掌握Java、C/C++、Python、JS等其中的至少1种主流编程语言； <br>3.对数据结构和算法有一定了解（笔试考）； <br>4.对接的是全产品线的需求，所以业务方向多样； <br>5.先统一笔试后匹配部门面试； <br>6.薪资构成：底薪+绩效+年终，薪资根据面试表现定； <br>7.全流程线上面试，拿到Offer再线下报道，可异地面试。<br>工作地点： <br>北京、上海、深圳、杭州、东莞、苏州、南京、西安、武汉、成都等地的研究所', '外企德科数字技术有限公司是一家2023年新成立的中外合资企业。成立于2023年11月24日，公司定位：专注于为信息技术企业提供人才及数字技术外包解决方案的中外合资企业。它是由中国人力资源服务行业的FESCO（北京国际人力资本集团）与全球人力资源服务领导者The Adecco Group（德科集团）合资成立的。公司主要提供网络技术服务、软件外包服务、计算机系统服务、技术进出口、软件开发等信息技术相关服务。专注于为信息技术企业提供信息技术类人才及数字技术外包解决方案。', 'https://www.zhaopin.com/jobdetail/CCL1480117890J40794055605.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (531, '实施工程师', '青岛安然物联网科技有限公司', '2025-07-27 01:09:16', '9000-18000元', '镇江-京口区', '物联网,物联网', '20-99人', '未融资', 'CC559764920J40565606904', '需要弱电技术、自动化、安防系统、工业互联网+危化安全生产、物联网人才，不要纯软件人才。  你能经常到全国各地出差吗？你能到工业生产现场生产现场做技术支持吗？  <br>真正的奋斗者在安然会有让人值得为之奋斗的事业，会有充实、高效的成长，会有高人一等的收入。  <br>你能做好售前技术支持、根据客户需求，高效制作方案吗？你能做好售中技术支持、指导他人正确安装、部署、调试系统向用户保质保量快速交付吗？你能做好售后维护，高效沟通和落实客户需求吗？  <br>迄今已服务中石化、中石油、延长石油、国能、兖矿、京能、索普、新安、奇美、昊源、潞安、旭阳、垦利、逸盛、海科、酒钢、金发等几百家石化、化工、选煤、钢铁、电厂企业。\n  <br>安然以客户为中心，以强者为本，抬头乐干，愿意与同道中人联合、链接，携手共建、共用、共享生产安全命运共同体，一起干，一起干，让优秀企业更安全，让优秀企业更高效！', '基于精准人员定位的工业安全生产信息化管理专家，安全生产信息化管理引领者！作为全国实时定位技术标准工作组成员和应急管理部“工业互联网+危化安全生产”人员定位系统技术支持机构，安然从2012年起致力于基于ZigBee Plus三维立体按需精准定位的“工业互联网+安全生产”的研究，获得了20多项安全智能管控系统发明专利和著作权，持续引领中国化工行业生产现场智慧安全！安然以“准、稳、狠”的ZigBee Plus三维立体按需精准人员定位统和“底数清、数据准、情况明、研判准、措施实”的安全生产信息化平台为核心，整合访客管理、出入口控制、人脸识别、视频监控、语音广播、重大危险源监控、可燃有毒气体监测等系统，对生产现场人、机、料、法、环五大要素进行实时、动态、智能管控和预警，规范人的安全行为，保障人的生命安全，有效防范风险、主动化解风险，实现智慧安全。安然“以用为本”，把安全生产信息化建设与公司管理体系“深度融合”，把安全生产信息化建设与日常工作“紧密结合”，对安全生产切实“有用、实用、好用”，避免建用“两张皮”，让安全管控更智能，让生产更高效才实用。迄今已服务中石化、中石油、延长石油、国能、兖矿、京能、索普、新安、奇美、昊源、潞安、旭阳、垦利、逸盛、海科、酒钢、金发等几百家石化、化工、选煤、钢铁、电厂企业。安然以客户为中心，以强者为本，抬头乐干，愿意与同道中人联合、链接，携手共建、共用、共享生产安全命运共同体，一起干，一起干，让优秀企业更安全，让优秀企业更高效！', 'https://www.zhaopin.com/jobdetail/CC559764920J40565606904.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (532, '技术支持工程师', '摩尔机电工程无锡有限公司', '7月11日', '4000-6000元', '深圳-宝安区', '电子/半导体/集成电路,电子/半导体/集成电路', '20-99人', '未融资', 'CC529863980J40772878607', '一、工作内容：<br>1、负责现场测绘，并根据测绘数据绘制图纸<br>2、负责客户对接，根据客户要求完成工作内容<br>3、处理客诉，并与总部做好沟通<br>4、有钣金设计或服装设计工作经验的优先<br>二、岗位要求：<br>1、大专及以上学历，机电一体化等相关专业优先<br>2、会使用CAD绘图<br>3、会开车，有C1驾驶证 4、身体状况良好，头脑灵活，服从指挥，能吃苦耐劳', '半导体芯片、光伏设备及元器件、通用机械的研发', 'https://www.zhaopin.com/jobdetail/CC529863980J40772878607.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (533, '科研人员', '北京艺升控股有限公司', '6月10日', '1.5-2.5万', '北京-石景山区', '生物工程,生物工程', '20-99人', '天使轮', 'CCL1344417910J40686536801', '（一）肿瘤免疫治疗产品开发（1人）<br>要求：肿瘤学、细胞生物学、免疫学或相关专业；熟悉肿瘤免疫治疗领域，参与过针对实体肿瘤治疗的细胞治疗药物开发或细胞治疗药物临床试验的相关课题；具有独立制定和开展研究计划、自主分析和解决科学问题的研究能力；有较强的实验动手能力和写作能力，善于沟通表达和团队协作者优先。<br>（二）外泌体研究（1人）<br>要求：细胞生物学、分子生物学、转化医学等相关专业；具有外泌体相关课题研究背景；具有独立制定和开展研究计划、自主分析和解决科学问题的研究能力；有较强的实验动手能和力写作能力，善于沟通表达和团队协作者优先。<br>（三）实体肿瘤新生抗原检测筛选分析（1人）<br>要求：生物信息学、计算生物学、基因组学或相关专业；精通肿瘤多组学数据分析流程，熟悉肿瘤免疫治疗核心指标（PD-L1、TIL、TMB等）及新生抗原预测原理；熟练掌握Python/R语言，熟悉GATK、STAR、ANNOVAR等生信工具，熟悉TCGA/ICGC等公共数据库；具有独立制定和开展研究计划、自主分析和解决科学问题的研究能力；有较强的实验动手能力和写作能力，善于沟通表达和团队协作者优先。<br>申请条件<br>1.中华人民共和国国籍，遵守中华人民共和国宪法和法律，拥护中国共产党的领导，具有良好的思想政治素质和道德品质，政治立场坚定，无违法违纪及其他不良记录，恪守科研道德和学术规范，学风正派、诚实守信； 2.最近三年在国内外获得博士学位或将于2025年7月前获得博士学位的博士研究生，以及从其他博士后科研流动站（工作站）出站的博士后研究人员，原则上年龄在35周岁以下，特别优秀者可适当放宽（未满41周岁）；', '北京艺升控股有限公司是专注于“泛实体肿瘤疫苗”研发的高科技创新企业。是“国家博士后科研工作站”、“国家高新技术企业”，获批“十四五”国家重大科研计划，被国家人社部评为“全国优秀创业项目”。目前，全球尚无一款泛实体肿瘤疫苗获批，全球都在加紧研发，艺升的研发技术与国际最前沿为同一水平，有把握成为全球首批获批的泛实体肿瘤疫苗。公司拥有一个互补性很强的优秀团队。公司员工博士学位占比58.3%，核心团队全都有在海外知名机构长期留学、工作的经历。公司在第七届“创业北京”创业创新大赛中获得第一名，第六届“中国创翼”创业创新大赛全国总决赛中获得所有医疗和生物医药项目第一名。', 'https://www.zhaopin.com/jobdetail/CCL1344417910J40686536801.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (534, 'Java', '武汉世纪易软科技有限公司', '4月13日', '150-200元/天', '武汉-江岸区', '计算机软件,计算机硬件', '20-99人', '未融资', 'CC259775910J40036324115', '世纪易软公司已成立11年，虽然只是一个小软件公司，但我们是一个很专、很正规的纯做技术、做产品的品质型公司，对想进入计算机行业进行发展的各位同学是非常难得的跳板平台与才期发展平台！', '武汉世纪易软科技有限公司是武汉市一家专门从事自主研发和销售的科技软件企业,客户群涵盖国商业企业、教育事业单位。近年来，公司在服装业”E风软件”系统的信息化建设方面积极奋进，从服饰业的管理、应用咨询、培训辅导、经营战略、数据优化方面着手，架构了一套独特的服装业专用”E风软件”解决方案,并深入服装经营者思考层，协助外贸、内销服饰企业建立E化的国际管理轨道', 'https://www.zhaopin.com/jobdetail/CC259775910J40036324115.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (535, 'C/C++', '外企德科数字技术有限公司', '2025-07-27 00:23:25', '1.5-3万·14薪', '济南-历下区', '专业技术服务', '10000人以上', NULL, 'CCL1480117890J40692736805', '岗位职责<br>在这里，你将从事IT应用层软牛、分布式云化软件、互联网软件等的设计开发,可以采用敏捷、Devops、开源等先进的软件设计开发模式，接触最前沿的产品和软件技术，成为大容量高并发技术的专家;你将参与产品的软件研发工作,包括但不限于:<br>(1)完成从客户需求到软件产品定义、架构设计、开发实现、再到上线运营维护等产品生命周期中的各个环节;<br>(2)创造性解决产品在实现过程中的技术难题，应用前沿技术提升产品的核心竞争力，如分布式系统、性能调优、可靠性、数据库等;<br>(3)有机会参与业界前沿技术研究和规划，参与开源社区运作，与全球专家一起工作、交流,构建在业界影响力。<br>岗位要求<br>1、计算机、软件、通信等相关专业本科及以上学历；工作年限不限；<br>2、热爱编程，基础扎实，熟悉掌握但不限于JAVA/C++/C/Python/JS/HTML/GO等编程语言<br>中的一种或数种，有良好的编程习惯；<br>3、具备独立工作能力和解决问题的能力、善于沟通，乐于合作，热衷新技术,善于总结分享喜欢动手实践;<br>4、对数据结构、算法有一定了解;<br>5、优选条件:<br>(1)熟悉TCP/IP协议及互联网常见应用和协议的原理<br>(2)有IT应用软件、互联网软牛、IOS/安卓等相关产品开发经验，不满足于课堂所学，在校期间积极参加校内外软件编程大赛或积极参于编程开源社区组织;', '外企德科数字技术有限公司是一家2023年新成立的中外合资企业。成立于2023年11月24日，公司定位：专注于为信息技术企业提供人才及数字技术外包解决方案的中外合资企业。它是由中国人力资源服务行业的FESCO（北京国际人力资本集团）与全球人力资源服务领导者The Adecco Group（德科集团）合资成立的。公司主要提供网络技术服务、软件外包服务、计算机系统服务、技术进出口、软件开发等信息技术相关服务。专注于为信息技术企业提供信息技术类人才及数字技术外包解决方案。', 'https://www.zhaopin.com/jobdetail/CCL1480117890J40692736805.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (536, '科研人员', '牧原实验室', '7月24日', '1.5-3万·13薪', '南阳-卧龙区', '学术/科研', '100-299人', NULL, 'CCL1241575100J40703840707', '职位描述： 1、负责农秸秆生物质炼制项目的研究，承担主要研究任务，制定详细的研究方案并组织实施；', NULL, 'https://www.zhaopin.com/jobdetail/CCL1241575100J40703840707.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (537, '技术支持工程师', '位来小猎(宁波)信息技术有限公司', '7月14日', '6000-10000元', '西安-新城区', '计算机软件,专业技术服务', '100-299人', 'A轮', 'CCL1320375780J40723716607', '1、负责大模型产品的售后服务支持，为客户提供高效优质的服务体验；', '位来小猎成立于2018年1月，2019年6月完成A轮融资；聚焦行业精华，利用后发优势，在1年以内成为行业黑马公司。核心团队成员均有十年以上的人力资源经验，具备丰富的人力资源专业知识和项目实践，服务众多500强企业和知名互联网公司。位来小猎掌握专业领域核心资源，团队迅速扩张，以北京为中心，在全国建立了10家分公司及办事处，业务覆盖全国。现有300+名员工，派遣、外包员工10000+名；服务客户包括国家体育总局，百度，网易，物美多点，美团，字节跳动，喜马拉雅，作业帮，得物，VIPKID，瓜子，京东，拼多多，喜茶，中国人保等。位来小猎以互联网为载体，依托于位来小猎平台、微信公众号、入职有赏微信小程序上活跃的海量求职者资源，核心业务包括人才外包、专业招聘、业务外包、转编服务和灵活用工等。服务行业涉及全国各领域，其中包括社交电商，旅游酒店，互联网（教育），新零售，金融和国家单位等。位来小猎以“把求职者的未来当做自己的未来”为核心价值，希望通过我们专业的服务和不懈的努力，帮助求职者找到更合适、更有发展前景的工作，破冰职场迷茫，为未来指引方向。一直以来，位来小猎秉承以专业诚信为核心，在专注人力资源服务的同时，为众多求职者解决就业问题，优质、用心的服务赢得了众多用户的好评与信赖。除此之外，公司还建立了完善的服务体系，为求职者在工作中遇到的所有问题和困难提供指导帮助。我们相信，通过我们的不断努力和追求，一定能够创造我们和求职者更好的未来！', 'https://www.zhaopin.com/jobdetail/CCL1320375780J40723716607.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (538, '硬件测试', '北京城建智控科技股份有限公司', '7月23日', '150-200元/天', '北京-东城区', 'IT服务,计算机硬件,计算机软件,电子/半导体/集成电路', '500-999人', '未融资', 'CC200737780J40758418501', '职位描述： 1、根据测试用例执行硬件产品测试，编制测试报告、调试手册、检验指导书；', '北京城建智控科技股份有限公司（以下简称“城建智控”或“公司”）成立于2014年10月，是北京城建集团科技服务板块的重要组成部分。公司致力于成为国内领先的“数字城市”综合解决方案服务商，重点服务国家“数字经济”战略，打造集“设计、研发、制造、集成、运维”为一体的数字技术一站式服务体系。公司深耕数字交通领域，以“云计算、大数据、物联网、人工智能”等新兴技术为核心，打造“产品+服务”的交通数字化转型体系，推动了中国城市轨道交通行业的数字化转型升级。公司市场范围已覆盖国内28个省/自治区/直辖市，100个总包业主，60个城市，并为多个海外客户提供技术及产品输出服务。截至目前，公司已成为国家高新技术企业、国务院“科改示范企业”、国家级专精特新“小巨人”、北京市“隐形冠军”企业、北京市市级企业技术中心。作为轨道交通行业第一家拥有设计背景的智慧城轨综合解决方案提供商、中国第一家专注轨道交通云平台业务的国有控股公司，公司以设计引领和科技创新为双轮驱动，创新产品研发，实现高质量发展，力争“十四五”末，成为北京城建集团旗下第一家提供科技创新产品及服务的上市公司。', 'https://www.zhaopin.com/jobdetail/CC200737780J40758418501.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (539, 'C/C++', '杭州高谱成像技术有限公司', '2月6日', '1.8-3.5万', '杭州-西湖区', '人工智能,计算机硬件,计算机软件,云计算/大数据', '20-99人', '天使轮', 'CC887878130J40227154506', '工作职责：', '杭州高谱成像技术有限公司成立于2019年，致力于引领国产高性能光谱视觉技术的产业化应用，加速人工智能与光谱视觉技术的深度融合，为全球行业客户提供多维智能感知“生产力工具”。高谱成像公司基于自主研发的色散分光高光谱成像技术，可为科研和行业客户提供覆盖200nm-2500nm全谱段的高性能高光谱相机，并不断拓展光谱视觉在低空遥感、近场检测和微观检测等场景下的产业化应用，形成了从硬件到软件算法、从数据到结果的完整技术链，陆续推出了高光谱水质监测、高光谱自动分选、高光谱色彩检测等综合解决方案，助力环境监测、固废物自动分选、高精度颜色检测、半导体和光伏组件检测、医疗诊断等行业多维智能感知需求。', 'https://www.zhaopin.com/jobdetail/CC887878130J40227154506.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (540, 'C/C++', '北京瑞鑫天算资产管理有限公司', '3月8日', '1.5-3万', '北京-海淀区', '基金,基金,证券/期货', '20-99人', '未融资', 'CCL1241735280J40727670307', '岗位职责：<br>1、利用机器学习、深度学习等数据挖掘方法对历史数据进行研究分析、对交易算法进行改进、开发新的交易算法。<br>职位要求：<br>1、毕业或在读于国内外知名高校本科及以上学历，硕士、博士优先。具备扎实的计算机理论知识与机器学习、深度学习相关的知识；<br>2、有能力独立完成交易算法的研发及实施，精通计算机语言（C/C++或Python等）；<br>3、熟悉机器学习特别是深度学习，强化学习，熟悉深度神经网络DNN、卷积神经网络CNN、递归神经网络RNN、长期短期记忆LSTM、生成敌对网络GAN等模型的应用与实施；<br>4、熟悉强化学习或者有高频交易开发相关经验者优先考虑；', '北京瑞鑫天算资产管理有限公司成立于2017年，注册资金1000万，是在中国证券投资基金业协会登记备案的，具有私募证券投资基金管理人资格的阳光私募基金公司。公司专注于运用量化的手段、科学的方法获取投资收益，旨在更好地帮助高净值客户资产保值增值。目前公司持续运作的登记备案私募基金产品总计十余只。公司主要成员毕业于清华、北大、上海交大、复旦、浙大、哥伦比亚大学、MIT等国内外顶级学府，拥有深厚数理背景，具备先进、丰富的投资经验，平均从业年限5年以上。公司实行投研一体化的管理模式，通过自主培养精英毕业生培养优秀人才。投研机制上鼓励研究成果共享，投资决策独立。在公司丰富的因子库、策略库及公司自研交易系统的支持下，公司私募基金产品的业绩在市场中处于领先地位。公司管理的基金产品在中信证券举办的2021年“千里马”私募培育计划中获得“千里马”三星荣誉证书和私募培育计划荣誉奖；在私募排排网举办的私募实盘投资大赛2022年4月排名中进入前三；在中国平安举办的大浪淘沙全国私募大赛2022年7月获得管理期货组冠军。公司亦提供优厚的报酬给公司的投研人员，只要能跟上公司发展的脚步，年薪百万不是梦！', 'https://www.zhaopin.com/jobdetail/CCL1241735280J40727670307.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (541, '硬件测试', '重庆科满福人力资源服务有限公司', '7月17日', '7000-12000元', '东莞-None', '企业服务', '20-99人', NULL, 'CCL1487604860J40932690804', '【岗位职责】 ：<br>1、进行新产品研发阶段的测试工作<br>2、完成新产品的功能测试、可靠性测试、环境测<br>试、安全测试等技术工作<br>3、制定测试计划，设计测试用例，分析测试数<br>据，编制测试报告<br>4、为其他部门提供技术支持，与其他部门的产品<br>联合测试工作', NULL, 'https://www.zhaopin.com/jobdetail/CCL1487604860J40932690804.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (542, 'Java', '湖南六九零六信息科技股份有限公司', '5月23日', '70-100元/天', '长沙-天心区', '运营商/增值服务,运营商/增值服务', '300-499人', '天使轮', 'CC499839420J40845934915', '岗位职责：<br>1. 参与公司软件产品的开发与维护。<br>2. 根据项目需求，协助完成软件设计、编码、测试和文档编写工作。<br>3. 学习并掌握相关的软件开发工具和技术。<br>岗位要求：<br>1. 计算机相关专业，本科及以上学历。<br>2. 熟悉Java编程语言，会使用Spring全家桶（Spring Boot/Spring MVC/Spring Cloud）及MyBatis等ORM框架。<br>3. 会使用HTML5/CSS3/JavaScript（ES6+），掌握至少一种前端框架（Vue.js/React/Angular），具备前端页面开发能力，实现与后端的高效数据交互与功能联调。 4.具备良好的学习和沟通能力，有团队协作精神 <br>', '国信军创（岳阳）六九零六科技有限公司，原名中国人民解放军第六九零六工厂，是军队通信装备大修保障性企业。始建于1964年，并于2011年成功收购了以国防科大技术骨干为核心的湖南创越电子科技有限公司，并作为公司的技术创新和产品研发中心。公司北斗卫星导航应用产业化项目被列为全省24个重点帮扶项目之一，公司技术中心被认定为“省级企业技术中心”、“湖南省北斗运营中心”、“北斗卫星导航系统应用工程技术研究中心”，获总参测绘局授予的“北斗一号”、“北斗二号”科研生产资质和中国人民解放军总参谋部卫星导航定位办公室授予的“北斗导航民用分理服务资质”。目前公司主要产品有：通信装备大修、火炮控制指挥系统、北斗”卫星产品研发、制造、应用与运营。公司的北斗产品也已广泛应用于航天、航空、国防、金融、电信、交通、矿山、水务、工程机械等多个行业。公司正值蓬勃发展、力拓市场的黄金时期。特诚邀有志于通信及电子信息工程人才加盟，共创中国北斗卫星导航事业的美好明天。如今，6906正进入一个快速发展通道，资产规模不断壮大，技术实力不断增强，营销领域不断拓展，基础管理不断改进，计划在2020年成立集团公司并整体上市', 'https://www.zhaopin.com/jobdetail/CC499839420J40845934915.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (543, 'Java', '外企德科数字技术有限公司', '2025-07-27 00:23:25', '1-2万·14薪', '成都-郫都区', '专业技术服务', '10000人以上', NULL, 'CCL1480117890J40687601905', '1、统招 quan 日制 本科及以上学历；（已毕业拿到毕业证学位证）<br>2、熟悉Java/C/C++/Python/GO等其中一种主流开发语言，有相关工作经验优先；<br>3、熟练掌握数据结构与算法，能完成牛客上简单以及中等的题目。<br>4、热衷前沿技术的探索，能快速掌握和理解新技术；<br>5、有较强的学习能力、良好的团队协作能力、良好的沟通表达能力。', '外企德科数字技术有限公司是一家2023年新成立的中外合资企业。成立于2023年11月24日，公司定位：专注于为信息技术企业提供人才及数字技术外包解决方案的中外合资企业。它是由中国人力资源服务行业的FESCO（北京国际人力资本集团）与全球人力资源服务领导者The Adecco Group（德科集团）合资成立的。公司主要提供网络技术服务、软件外包服务、计算机系统服务、技术进出口、软件开发等信息技术相关服务。专注于为信息技术企业提供信息技术类人才及数字技术外包解决方案。', 'https://www.zhaopin.com/jobdetail/CCL1480117890J40687601905.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (544, '科研人员', '中国建设科技集团股份有限公司', '5月21日', '1.5-2.5万', '北京-西城区', '房地产开发,装饰装修,学术/科研', '10000人以上', '未融资', 'CC390500820J40908679604', '【企业简介】', '中国建设科技有限公司是国务院国资委直属的大型骨干科技型中央企业，2017年由中国建筑设计研究院改制更名。中国建筑设计研究院是2000年4月由原建设部4家直属单位建设部建筑设计院、中国建筑技术研究院、中国市政工程华北设计研究院和建设部城市建设研究院合并组建，前身为创建于1952年的中央直属设计公司，是改革开放后第一批进入国际建筑市场并较早获得对外经营权的设计企业之一。中国建设科技集团股份有限公司（简称“建设科技集团”，英文缩写CCTC）于2014年6月30日正式成立。公司股东包括中国建设科技有限公司、中国电力建设集团有限公司、中国能源建设集团有限公司及国创投资引导基金（有限合伙）。集团下设11家二级企业，其中“中国”字号企业5家，境外企业1家。2012年，集团全资收购新加坡CPG集团（前新加坡国家设计院），进一步巩固了集团建设科技领域综合优势、提升了国际竞争力。集团是能全面覆盖城乡建设领域各专业门类、整体实力领先的科技型中央企业，主营业务范围包括城乡规划、建筑工程、市政工程三大板块，专业门类涵盖：城乡规划（城市规划、城镇规划、乡村规划、文化遗产保护规划等）、建筑工程（建筑、结构、给排水、暖通空调、电气、室内装修、建筑历史、人防工程等）、市政工程（供水、供热、燃气、污水处理、道路桥梁、垃圾处理、轨道交通、风景园林等）。六十年来，集团已在42个国家和地区完成设计项目61000余项，先后设计完成了北京火车站、中国美术馆、北京国际饭店、国家图书馆、国家体育场（鸟巢）、首都博物馆、世园会中国馆、故宫保护、长城保护、引滦入津、西气东输、南水北调、长江三峡库区环境保护、丝绸之路：长安-天山廊道路网申遗、良渚古城遗址申遗、北京城市副中心市政府大楼、雄安新区市民服务中心等国家重点工程以及新加坡国家博物馆、新加坡滨海湾花园、新加坡樟宜机场、斯里兰卡班达拉奈克国际会议大厦等具国际影响的海外工程。集团现有员工总数（含境外）近13000人，其中境内员工11300余人。顶尖高端工程技术人才保有量居行业之首，拥有行业内规模大、价值高、创新力和引领力强的专业技术团队，其中中国工程院院士3人、全国工程勘察设计大师10人、国家级有突出贡献中青年专家8人、建设部有突出贡献的中青年专家17人、享受国务院政府津贴专家99人、国家“百千万人才工程”人选6人、各类注册人员1800余人、具有专业技术职称人数为8000余人，技术人员占境内员工总数的90%以上。', 'https://www.zhaopin.com/jobdetail/CC390500820J40908679604.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (545, 'Java', '深圳市智略云擎人工智能科技有限公司', '7月24日', '1.6-1.7万·13薪', '深圳-龙岗区', '人工智能', '20-99人', NULL, 'CCL1501176800J40815037608', '岗位内容：<br>1. 设计、开发并维护Java应用程序。<br>2. 解决各种技术难题，保证代码的可靠性、高效性和安全性。<br>3. 参与软件设计的讨论和计划制定。<br>4. 与其他团队成员协作工作，提高团队整体技术水平。<br>任职要求：<br>1. 熟悉Java语言及相关技术，熟悉Spring框架。<br>2. 具有扎实的编程基础和良好的面向对象编程思想。<br>3. 对常见数据库如MySQL、Oracle等有一定的了解和应用经验。<br>4. 对Web开发技术有深入理解，熟悉前端技术如HTML、CSS、JavaScript等。', NULL, 'https://www.zhaopin.com/jobdetail/CCL1501176800J40815037608.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (546, '硬件测试', '深圳市科皓信息技术有限公司', '7月25日', '100-150元/天', '南昌-新建区', 'IT服务,计算机硬件,计算机软件', '100-299人', '未融资', 'CC120081560J40756023501', '岗位内容：<br>1. 执行硬件测试任务，并维护测试数据和文档；<br>2. 跟进测试过程中发现的问题，协助解决硬件缺陷；<br>3. 收集硬件测试需求，推动测试工具和方法的改进。<br>任职要求：<br>1. 本科及以上学历，软件工程、物联网工程、信息工程等相关专业；<br>2.熟悉常用的硬件测试方法和工具；<br>3. 善于沟通和协作，具有良好的团队合作精神；<br>4. 具备较强的学习和自我提升意愿，能够快速适应新环境和新技术。<br>5.吃苦耐劳，能够适应出差。', '深圳市科皓信息技术有限公司成立于2001年6月，致力于安全生产（智慧安全）及水利信息化领域的产品研发与销售，是“国家级高新技术企业”、“深圳市重点软件企业”，公司获得了国家工业与信息化部颁发的“计算机信息系统集成贰级资质”、“跨地区电信增值业务许可证”，水利部颁发的水文、水资源调查评价乙级资质，国家质检总局颁发的“全国工业产品生产许可证”，通过了“ISO9001质量管理体系认证”、“软件成熟度模型CMMI 3级国际认证”，公司连续多年获得广东省政府授予的“重合同、守信用”企业称号。科皓公司总部位于深圳市高新技术产业园内，在北京、重庆、天津、广州、南昌、沈阳、南宁、昆明、长沙、郑州、武汉、大庆、东莞、青岛、漳州等地设有分公司或办事处。我们坚持以人为本的企业文化，不断地创造一个使优秀人才能够充分施展才能的环境，给员工提供良好的待遇和广阔的个人发展空间。如果您对自身的能力充满自信，渴望更广阔的施展天地，我们随时欢迎优秀的您加入我们的行列。', 'https://www.zhaopin.com/jobdetail/CC120081560J40756023501.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (547, '实施工程师', '沈阳仪佰通科技开发有限公司', '7月8日', '4000-8000元', '沈阳-铁西区', '仪器仪表制造,金属制品业', '20人以下', '不需要融资', 'CC631550920J40775331114', '岗位职责：<br>1. 负责现有经销商及终端客户的维护，提供技术支持，处理技术问题，建立长期稳定的合作关系；    <br>2. 执行公司产品推广计划，策划区域性市场活动，提升品牌影响力；  <br>3. 全程跟进订单流程（投标、报价、签约、交付、回款），全过程跟进；  <br>4. 收集市场竞品信息及客户反馈，协助优化产品与服务方案。  <br> <br>**任职要求：**  <br>1. 年龄23-30岁，本科及以上学历；<br>2. 生物工程、生物制药、医学生物技术、食品检验检测、环境科学、药物化学、应用化学、等相关专业；<br>3. 具备对业务拓展和市场推广能力，对市场变化敏感，<br>4.可独立分析和解决问题，具有较强的理解和应变能力，出色的语言表达与逻辑思维能力；<br>5.抗压能力强，适应短期出差，具有强烈的目标导向。  <br>6.熟练使用电脑及办公软件；  <br>7.持有驾照且熟练驾驶可优先；<br>- **优先条件：**  <br>▶ 有实验室仪器/分析仪器/食品药品检验/医疗设备/工业设备/技术服务经验；  <br>**岗位福利：**  <br>✔ 极具竞争力的\\\\\"底薪+提成\\\\\"机制，年薪上不封顶  <br>✔ 标准双休+带薪年假+五险一金+意外险<br>✔ 专业培训体系+清晰晋升通道（产品支持→销售工程师→区域经理→总监）  <br>✔ 团队旅游+节日福利+项目奖金+产品经理奖金+累计激励', '沈阳仪佰通科技开发有限公司成立于2012年，公司落户国家级经济技术开发区国家大学科技园内。专业经销进口及国产实验室仪器。一直为客户提供国内外先进的微生物、理化及分析检测仪器，并提供专业的应用解决方案。多年来，我们始终秉持客户至上，合作共赢、诚信为本，品质立企的理念，致力于为客户提供高效、专业、可靠的产品与服务。核心业务与产品我们的核心业务涵盖食品检验、生物制药、石油化工、环境检测、农林畜牧、卫生防疫、材料分析等领域。仪器种类涵盖灭菌器、培养箱、干燥箱、摇床、电化学及水质分析仪器，光谱色谱、原子吸收光谱仪，全自动智能一体化蒸馏仪，二氧化硫测定仪，傅里叶变换红外光谱仪设备等。经销品牌有德国 IKA、瑞士万通、上海博迅、海能技术、小聪仪器等。我们的产品高性能、个性化定制、高性价比等优势，广泛应用于科研院所、制药、食品、化工、农林畜牧，材料、环保、疾控中心等，赢得了市场的高度认可。团队与文化​我们是一支专业高效、充满激情的团队，致力于为客户提供卓越的产品与服务。公司注重人才培养与发展，为员工提供广阔的职业发展空间和完善的培训体系。同时，我们倡导客户至上、诚信共赢的企业文化，营造积极向上、和谐融洽的工作氛围。​客户与合作​通过我公司的销售+技术+售后一体化服务模式，已为东北地区数百家客户提供专业解决方案，市场认可度持续领先。未来，我们将继续秉持“以客户为中心”的服务宗旨，不断优化产品与服务，携手更多合作伙伴，共创美好未来。​', 'https://www.zhaopin.com/jobdetail/CC631550920J40775331114.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (548, '测试工程师', '国机集团北京飞机强度研究所有限公司', '4月1日', '1.1-1.2万·13薪', '北京-朝阳区', '学术/科研', '20-99人', NULL, 'CC244622180J40727599814', '【岗位要求】  1）结构载荷、环境测试系统设计；  <br>2）测试设备及传感器选配；  <br>3）测试原理图、线路图的绘制；  <br>4）测试系统搭建、调试、标定试验数据采集；  <br>5）飞行实测数据采集和初步检验等工作；  <br>6）飞行实测试验现场的排故等工作；  <br>7）按照研究所管理制度履行相应的质量、安全和保密职责；  <br>8）完成领导交办的其他工作。  <br>', '国机集团北京飞机强度研究所有限公司（简称:北京飞机强度研究所，Beijing Aircraft Strength Institute）是专门从事飞机、航空发动机结构寿命可靠性理论与试验研究的国有科研机构，隶属国机集团科学技术研究院有限公司，是中国机械工业集团有限公司下属的三级企业。', 'https://www.zhaopin.com/jobdetail/CC244622180J40727599814.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (549, '技术支持工程师', '安美微客(上海)互联网科技有限公司', '7月5日', '150-200元/天', '桂林-七星区', '通信/网络设备', '20-99人', '未融资', 'CCL1297902840J40769815914', '岗位职责： <br>1.通过培训和自学熟悉公司产品，接听400技术支持热线，故障处理、记录、反馈和问题咨询； <br>2.通过技术支持热线电话、远程工具，对客户做技术指导，解决客户问题； <br>3.通过电话或者邮件方式协助客户经理维护好现有客户关系； <br>4.完成上级安排的其他工作。 <br>  岗位要求：  <br>1. 有计算机基础知识，对计算机网络知识感兴趣者；  <br>2. 良好的沟通、团队合作能力，具备良好的职业道德和敬业精神；  <br>3. 能接受倒班（两班倒，上一天白班休一天，上一天晚班休两天）。  <br>  <br>', '作为全球领先酒店智能生态运营商“安美数字”旗下专注于酒店互联网服务管理运营的子公司“安美互联”——安美微客（上海）互联网科技有限公司。自2006年伊始，紧随互联网技术发展峰向，潜心研究酒店互联网接入特点，酒店互联网运营管理的特殊性，“安美互联”与时俱进，自主研发了酒店互联网管理和认证计费系统（AMTT innFOR eFlow HSIA）、专业的有线宽带、无线覆盖解决方案、基于移动互联网应用的微信微服务O2O运营平台、酒店大数据产品等。从产品的研发，生产，项目咨询设计，安装，员工培训，以及后期的使用保障，后台服务等，安美酒店互联网管理服务运营以全产业链自主服务体系，为酒店构建稳定、高速、便捷的互联网运营管理及全方位服务，为高星级酒店入住客人带来了安全、迅捷、稳定的上网应用体验，并为酒店管理人员提供便捷、高效、实用的网络管理以及服务工具。经过多年的不断完善，网关产品已升级为酒店高速互联网接入及综合管理服务系统（Hotel High Speed Internet Access and Management Service）。安美互联的网关产品和服务已成为行业龙头，中国大陆市场占有率超过80%，服务约3000家高端星级酒店客户，包括万豪、洲际、雅高、香格里拉、温德姆、喜达屋、希尔顿等在内的30多家跨国酒店管理集团，并且成为产品、服务的认证供应商……如今，安美互联业务已涵盖酒店网关软硬件、产品客服中心、酒店互联网服务、会议互联网保障服务、手机端酒店O2O微服务、酒店LBS位置服务、酒店大数据、酒店商城等。引人关注的是，安美互联针对高端星级酒店客户打造的整体服务体系，以独有的400、800服务中心，每时每刻，7×24小时随时待命。确保第一时间内提供服务支持，倾力保障酒店网络运营的安全、稳定、高效，堪称酒店服务领域中的经典。', 'https://www.zhaopin.com/jobdetail/CCL1297902840J40769815914.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (550, 'C/C++', '外企德科数字技术有限公司', '2025-07-27 00:25:00', '1.2-2.4万·14薪', '成都-郫都区', '专业技术服务', '10000人以上', NULL, 'CCL1480117890J40779698305', '岗位内容：<br>1. 技术方案的设计和优化，对技术问题进行跟踪解决；<br>2. 负责工程项目的整体进度规划，保证工期、质量、安全达标；<br>3. 及时掌握国内外技术动态并将其应用到实践中；<br>4. 完善设计流程，提高设计效率和质量；<br>任职要求：<br>1. 本科及以上学历<br>2. 精通C/C++、Python等编程语言。<br>  3.运维、前端、测试岗位都可以接受无经验以及转行', '外企德科数字技术有限公司是一家2023年新成立的中外合资企业。成立于2023年11月24日，公司定位：专注于为信息技术企业提供人才及数字技术外包解决方案的中外合资企业。它是由中国人力资源服务行业的FESCO（北京国际人力资本集团）与全球人力资源服务领导者The Adecco Group（德科集团）合资成立的。公司主要提供网络技术服务、软件外包服务、计算机系统服务、技术进出口、软件开发等信息技术相关服务。专注于为信息技术企业提供信息技术类人才及数字技术外包解决方案。', 'https://www.zhaopin.com/jobdetail/CCL1480117890J40779698305.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (551, 'C/C++', '上海文华财经资讯股份有限公司', '7月9日', '1.4-2.8万·15薪', '苏州-工业园区', '计算机软件,证券/期货', '300-499人', '不需要融资', 'CC354498210J40724218802', '岗位薪酬体系：  <br>     大连薪资12K~30k * 15个月   <br>苏州/上海薪资14K~30k * 15个月   <br>薪资与工作能力挂钩，每半年进行一次评定   <br>*为技术水平突出的应届生提供6w卓越人才奖金。获得国家级竞赛名次的，奖金可升档。', '文华财经成立于1996年，是一家金融软件公司，行业软件开发独角兽企业。公司成立至今一直服务于证券行业，在证券--期货这个细分领域，市场占有率第一。公司拥有一流的软件研发技术和平台运营能力，产品已经打入10家证券公司、139家期货公司和314家投资机构，日均百万级终端用户，市场覆盖率超过90%。文华产品占据着中国期货交易者的手机和电脑屏幕。公司总部在上海，拥有苏州、大连两个研发中心。技术方面，文华一直追求技术领先。早在2012年文华就在产品中有效的运用了云计算、大数据等新技术，近两年业务深入股票和其他投资市场，现在基于大数据、人工智能技术的程序化交易系列软件成为我们的又一个核心业务。人才方面，文华秉持“用一流待遇吸纳一流人才”的理念，打造了“一线城市起薪水平、每年2次涨薪评定、年年持续增长”的薪酬体系，以及“免除员工后顾之忧、惠及员工父母家人”的福利体系，为人才打造一个终身成长、终身发展的平台。一流的企业渴求一流的人才，如果您自信无畏、不惧考验，诚挚欢迎加入文华财经！', 'https://www.zhaopin.com/jobdetail/CC354498210J40724218802.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (552, '技术支持工程师', '来邦科技股份公司合肥分公司', '7月22日', '6000-8000元·13薪', '长沙-芙蓉区', '运营商/增值服务', '500-999人', '未融资', 'CC487729280J40747317501', '1、熟练掌握公司产品的安装、功能使用、故障处理。<br>2、负责区域内项目售前演示、安装调试指导、售后服务等电话及现场技术工作;<br>3、负责收集、分析客户需求并反馈相关部门。<br>4、及时有效解决客户日常反馈问题，维护客户关系，提高客户满意度。<br>任职资格：<br>1、计算机软件、通信工程、电子信息工程相关专业，大专及其以上学历。<br>2、有通信产品、软件产品/项目技术支持经验，有医疗，养老、安防智能化项目实施运维管理经验者优先。<br>3、熟悉通信原理、了解互联网常用协议，学习能力强。<br>4、较好的文字及语言表达能力，熟练掌握办公软件操作。<br>5、吃苦耐劳，能适应长期出差。<br>公司福利：<br>1、入职即买五险一金；<br>2、法定年休假、节假日补贴、春节三周有薪假期；<br>3、每年两次调薪机会 ；', '来邦科技创立于1997年，新三板企业（股票代码：836888），国家级高新技术企业，国家AAA级信用企业，中国安防十大品牌，中国安防十大民族品牌，深圳安防协会副会长单位。公司以“可视对讲”音视频技术为核心，提供医院、养老、学校、监狱、平安建设、高速公路、银行等领域的智能化建设方案。来邦秉承“专心做好一件事”的经营理念，始终重视技术研发与创新。现拥有IP网络高清音视频编解码、双工免提大音量对讲消回音、数字动态降噪、多媒体信息发布等多项自主研发核心技术，处于行业领先水平。•拥有占地70亩的自建生产基地，建筑面积达4.6万平方米。•建立深圳、合肥、西安三地研发中心，取得60多项专利证书。•在国内多个省会城市设立了分公司或办事处，并与3000余家工程商保持着长期良好合作关系。不论资排辈，年轻人也能当“将军”。核心员工股权激励，工作氛围好，领导超亲和，期待您加入我们！', 'https://www.zhaopin.com/jobdetail/CC487729280J40747317501.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (553, 'C/C++', '广东南方数码科技股份有限公司', '7月23日', '8000-14000元', '广州-天河区', '计算机软件,计算机软件', '500-999人', '未融资', 'CC133964100J40795497712', '欢迎投递，优秀的朋友薪资open谈~', '广东南方数码科技股份有限公司成立于2003年，总部位于广州，是一家集数据、软件、服务于一体的中国领先的地理信息产业服务商、中国地理信息产业“百强企业”，产品业务覆盖地理信息产业链，提供一站式的就近服务。公司是信息产业部认定的“软件企业”，同时也是广东省认定的“高新技术企业”、“广州市重点软件企业”、“广东省优秀自主品牌”，具有测绘甲级资质、CMMI3级认证、系统集成三级资质、ISO9001：2008国际质量体系认证。公司全面面向数字城市，以数据为基础，以基础测绘、房产、国土、市政、规划等行业为核心发展地理信息产业，产品服务贯穿产业链。公司拥有遍布全国的数码专业分公司，专业、专注、就近服务。目前，公司已有数百个政务管理系统稳定运行在各级政府和行业管理部门。公司承担了多项省、市、区科技攻关项目，并多次获国家、省、市政府和科技部门的奖励。自主开发的70多个软件产品获得“软件产品登记”和“著作权登记”。其中南方地形地籍成图与建库软件（ CASS）拥有全国90%的市场份额，并成为业界事实标准；房测之友BMF成为房地产测绘行业唯一通过权威机构评测的专业软件，居同类软件市场占有率之首；CMS成为国土资源部推荐使用的城镇建库软件。秉承“以人为本、专业专注、和谐共赢”的理念，南方数码始终坚持以“数据·软件•服务”为核心，以提升地理信息价值为已任，愿与同行一起，推动中国的信息化建设事业，让更多人体验地理信息价值！', 'https://www.zhaopin.com/jobdetail/CC133964100J40795497712.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (554, '科研人员', '深圳中科欣扬生物科技有限公司', '12月10日', '1.5-3万', '深圳-龙岗区', '医药制造', '100-299人', 'B轮', 'CC514058280J40688184810', '岗位职责:', '中科欣扬是专注合成生物学创新智造的高新技术企业，致力于为全球各行业提供全新的生产方式及解决方案，始终坚持合成生物学行业特有的一芯二合多产业“π”战略。目前，公司已搭建一支来自中科院、北大、清华、UC Berkeley、南洋理工大学、Wageningen UR等国内外顶级高校和科研院所，涵盖合成生物学、化学、生命科学、生态学、环境科学、食品科学、农业科学多个领域海内外高层次人才的核心研发团队。先后前往中南美洲火山、印度洋深海、喜马拉雅冰川、云贵高原热泉等极端环境，搜集大量嗜冷、耐热、耐酸碱极端环境微生物资源，通过菌株保存、DNA测序建立起一整套全球极端环境微生物资源库，为合成生物学开发提供了大量元件。公司在深圳设有23000㎡合成生物学研发智造基地，在北京设有合成生物学创新研究基地，在上海设有2300㎡的美丽健康应用研究与品牌孵化中心，在无锡设有具备1000吨产能的产业化基地。作为合成生物学领军企业，中科欣扬在2021 EmTech China全球新兴科技峰会上入选《麻省理工科技评论》年度“50家聪明公司”（50 Smartest Companies，TR50）。', 'https://www.zhaopin.com/jobdetail/CC514058280J40688184810.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (555, '实施工程师', '吉林省嘉驰工程技术服务有限公司', '5月6日', '4000-7000元', '长春-南关区', '物联网', '100-299人', NULL, 'CCL1499869610J40756653513', '岗位职责：负责通信系统、设备的安装、调试、维护和故障排除；为客户提供技术咨询和解决方案，解答客户关于通信技术方面的疑问；参与通信项目的实施，协助制定项目技术方案和计划，并确保项目按照技术要求顺利进行；跟踪通信技术的发展动态，对新技术进行评估和测试，为公司技术升级和产品优化提供建议。 接受无经验，试用期薪资4000转正6000，双休法休正常。', NULL, 'https://www.zhaopin.com/jobdetail/CCL1499869610J40756653513.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (556, '实施工程师', '海尔施生物医药股份有限公司', '7月1日', '6000-7000元', '舟山-定海区', '医药制造,医疗设备/器械', '1000-9999人', '未融资', 'CC458696410J40817348908', '1、试剂售后的维护和开发<br>2、按要求和规范高效完成和解决客户端各项任务包括但不限于应用培训、仪器校验和问题处理等；<br>3、定期完成客户回访，收集客户各项需求、意见和建议，及时向相关部门和领导反馈汇报并跟进，保障和提升客户满意度；<br>4、对区域内市场活动提供支持并协助相关部门进行产品推介；<br>资格要求：<br>1、医学检验或相关专业，本科及以上学历，有相关工作经验者优先；<br>2、对岗位热爱并富有激情，具有强烈责任心和良好的团队合作精神；<br>3、具有良好的沟通能力，善于协调各种资源推动工作目标达成；<br>4、具有良好的抗压能力及较强的独立分析和解决问题能力；<br>5、具有一定英文读写能力和办公自动化能力；', '创立于1992年，总部设在东海之滨宁波的海尔施（HEALTH）是一家以致力于“为人类健康做出卓越贡献”为企业发展宗旨的生物医药企业集团，其以专业的、专注的服务精神，引领、参与和见证了中国生物医药行业的发展。自创建以来，海尔施坚持以诊断产品研发、生产、销售和服务，药品研发、生产、销售和流通，及健康服务等健康产业链为主的发展战略，在北京、上海、杭州、宁波、南京、泰州、沭阳等地设有十余家分子公司或办事机构，员工人数近2000人，其旗下骨干企业包括：海尔施生物医药股份有限公司、上海海尔施医疗器械有限公司、浙江海尔施医疗设备有限公司、江苏恒奇诊断产品有限公司、宁波海尔施基因科技有限公司、金华强盛生物科技有限公司、宁波大红鹰药业股份有限公司、宁波海尔施医药有限责任公司、江苏恒奇医药有限公司、宁波海尔施医学检验所有限公司、杭州金诺医学检验所有限公司、宁波美晶医疗技术有限公司、宁波开发区中心医院、宁波海尔施投资控股有限公司等。海尔施旗下现有五家国家高新技术企业，在宁波设有海尔施生命科学研究院，包括：分子诊断产品研发中心、诊断产品仪器和试剂研发中心、药品研发中心、肿瘤细胞检测技术研发中心等。其骨干企业拥有众多自主知识产权、自营进出口权、医疗器械生产企业许可证、医疗器械经营许可证、药品生产许可证、药品经营许可证、药品生产质量管理规范（新版GMP）证书、药品经营质量管理规范认证（新版GSP）、ISO9001质量管理体系认证证书、中国公共安全产品认证证书等经营资质等。海尔施现有现代物流仓储总面积为20000余平方米，其中常温库近20000平方米，温控库3000余平方米，冷库及冷冻库3000余立方米。上海海尔施医疗器械有限公司、宁波海尔施医药有限责任公司的2家公司具有医疗器械第三方物流资质并已开展相关业务。海尔施自2002年度起至2010年度连续九年被评为浙江省医药商业十强企业，2009年度排入中国医药商业百强企业，2010年度获得宁波市北仑区服务业企业“121”工程龙头企业，2012年度被评为宁波市外贸龙头企业、获得中国科技创业计划大赛三等奖，2013年度被评为宁波市优势总部企业，2014年度被评为中国质量诚信企业、全国药品流通行业信息统计先进单位，2015年度公司被评为浙江省商贸流通业诚信示范企业、公司是浙江省医药行业协会副会长单位、浙江省医疗器械行业协会第六届会长单位、宁波市医疗器械行业协会第四届理事会会长单位。', 'https://www.zhaopin.com/jobdetail/CC458696410J40817348908.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (557, 'Java', '外企德科数字技术有限公司', '2025-07-27 00:25:54', '1.5-3万', '杭州-滨江区', '专业技术服务', '10000人以上', NULL, 'CCL1480117890J40792249205', '软件开发工程师<br>1.学信网可查的本科以上学历，计算机相关专业优先<br>2.掌握C/C++/Java/Python等其中一种或多种编程语言，熟悉Linux环境下相关开发。<br>3.对基本数据结构和算法有一定了解，喜欢动手实践。<br>4.具备良好的问题解决能力，乐于团队写作，热衷新技术，善于总结和分享。<br>5.有容器领域、分布式系统、Linux内核、数据库引擎开发经验者优先。<br>6.经验不限，年限越高能力越高薪资越高<br>7.入职后有培训带教贯穿试用期，试用期不打折<br>8.五险一金全额缴纳，商业保险。<br>9.有班车', '外企德科数字技术有限公司是一家2023年新成立的中外合资企业。成立于2023年11月24日，公司定位：专注于为信息技术企业提供人才及数字技术外包解决方案的中外合资企业。它是由中国人力资源服务行业的FESCO（北京国际人力资本集团）与全球人力资源服务领导者The Adecco Group（德科集团）合资成立的。公司主要提供网络技术服务、软件外包服务、计算机系统服务、技术进出口、软件开发等信息技术相关服务。专注于为信息技术企业提供信息技术类人才及数字技术外包解决方案。', 'https://www.zhaopin.com/jobdetail/CCL1480117890J40792249205.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (558, '测试工程师', '四川金汇能新材料集团股份有限公司', '7月22日', '4000-5000元', '雅安-天全县', '新能源,新能源', '500-999人', 'C轮', 'CCL1283550790J40708755614', '1.完成日常测试；  2.对现有测试方式进行改善优化；', '四川金汇能新材料股份有限公司，成立于2017年9月。公司总部位于成都市青白江区欧洲产业城，是锂离子电池负极材料集研发、生产、销售于一体的专业制造商，旗下拥有深圳金润、四川金泰能、雅安金汇能、四川金亚能、重庆金汇能等全资子公司。公司拥有以中国科学院成会明院士为首席科学家的国内外杰出的负极材料研发高端人才团队，具有强大的自主创新实力，现有国家发明专利近30项，并与宁德时代、华为、中国科学院金属研究所先进碳材料部等建立了良好的技术合作与交流平台，储能石墨负极和硅氧硅碳负极处于行业一流水平。公司着眼长远，高度重视下一代硅氧硅碳负极、钠离子电池负极、连续石墨化等三大研发方向，并致力于负极设备、智能化改造等自主开发，不断锻造企业核心竞争力。公司注重技术改造和科研投入，继2021年获得成都市、四川省“专精特新”的基础上，2022年8月又获得国家级“专精特新”小巨人企业称号，12月被认定为2022年四川省新经济示范企业、2022年成都市企业技术中心、2022年成都市新经济梯度培育企业以及2022年国家级高新技术企业等一系列荣誉称号。此外，公司获得了汽车行业最高体系IATF16949认证，四川金汇能股份和子公司四川金泰能2021年被授予四川省“专精特新”企业称号，并努力打造绿色工厂、零碳工厂。2022年，金汇能(雅安)10万吨锂离子电池负极材料一体化基地全面建成，公司实现13万吨/年的一体化产能，成功跃居行业第一梯队。随着四川金亚能15万吨石墨化、重庆金汇能10万吨负极项目签约与建设，金汇能产能将进一步大幅提升，以期满足行业爆发式增长的需求。公司秉承“为员工提供平台、为客户创造价值、为企业增加效益”的经营理念，践行“诚实、诚心、诚信”的企业使命，致力于打造卓越的客户服务能力，为新能源产业添砖加瓦，立志成为全球极具竞争力的负极材料和解决方案供应商！欢迎优秀的您加入公司，与公司共同发展。（http://2212235104.p.make.dcloud.portal1.portal.thefastmake.com/index.html【公司官网处于测试阶段，不影响正常浏览】）', 'https://www.zhaopin.com/jobdetail/CCL1283550790J40708755614.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (559, '软件测试', '南京翰卓信息科技有限公司', '7月25日', '5000-8000元', '南京-秦淮区', '互联网', '100-299人', NULL, 'CC580008920J40825481108', '软件测试实习生<br>岗位要求：<br>1、本科计算机相关专业在读<br>2、具备良好的沟通能力<br>3、能制定和编写文档<br>4、熟悉Linux系统基础命令<br>5、熟悉数据库常用命令<br>6、具备软件实施、测试能力<br>7、会JS代码者优先考虑<br>工作职责：<br>1、协助及参与测试项目的流程<br>2、参与系统测试、编写测试阶段性报告和测试结果总结报告', NULL, 'https://www.zhaopin.com/jobdetail/CC580008920J40825481108.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (560, '技术支持工程师', '青岛安然物联网科技有限公司', '7月18日', '8000-16000元', '鹤壁-淇滨区', '物联网,物联网', '20-99人', '未融资', 'CC559764920J40884193604', '岗位职责：<br>1. 负责石化、化工厂人员定位系统的现场实施、现场交付和技术赋能等工作。<br>2. 对接客户需求，进行需求调研，制定详细的施工方案和计划。<br>3. 确保项目按照既定的时间节点和质量要求完成交付。<br>4. 对已交付的项目进行后期技术支持与维护。<br>岗位要求：<br>1. 年龄在25-35岁之间。<br>2. 能够适应经常出差的工作要求。<br>3. 熟悉信息化、弱电及工业互联网相关技术。<br>4. 具备良好的沟通协调能力和问题解决能力。', '基于精准人员定位的工业安全生产信息化管理专家，安全生产信息化管理引领者！作为全国实时定位技术标准工作组成员和应急管理部“工业互联网+危化安全生产”人员定位系统技术支持机构，安然从2012年起致力于基于ZigBee Plus三维立体按需精准定位的“工业互联网+安全生产”的研究，获得了20多项安全智能管控系统发明专利和著作权，持续引领中国化工行业生产现场智慧安全！安然以“准、稳、狠”的ZigBee Plus三维立体按需精准人员定位统和“底数清、数据准、情况明、研判准、措施实”的安全生产信息化平台为核心，整合访客管理、出入口控制、人脸识别、视频监控、语音广播、重大危险源监控、可燃有毒气体监测等系统，对生产现场人、机、料、法、环五大要素进行实时、动态、智能管控和预警，规范人的安全行为，保障人的生命安全，有效防范风险、主动化解风险，实现智慧安全。安然“以用为本”，把安全生产信息化建设与公司管理体系“深度融合”，把安全生产信息化建设与日常工作“紧密结合”，对安全生产切实“有用、实用、好用”，避免建用“两张皮”，让安全管控更智能，让生产更高效才实用。迄今已服务中石化、中石油、延长石油、国能、兖矿、京能、索普、新安、奇美、昊源、潞安、旭阳、垦利、逸盛、海科、酒钢、金发等几百家石化、化工、选煤、钢铁、电厂企业。安然以客户为中心，以强者为本，抬头乐干，愿意与同道中人联合、链接，携手共建、共用、共享生产安全命运共同体，一起干，一起干，让优秀企业更安全，让优秀企业更高效！', 'https://www.zhaopin.com/jobdetail/CC559764920J40884193604.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (561, 'C/C++', '外企德科数字技术有限公司', '2025-07-27 00:24:28', '1.7-3万·16薪', '上海-青浦区', '专业技术服务', '10000人以上', NULL, 'CCL1480117890J40769644005', '1:统招度大学，理工科相关。毕业证学位证齐全<br>2:会一种语言就可Python、JAVA、JS、测试C++3:华为目前在招城市:北京、上海、深圳、杭州、南京、西安、成都、武汉，以上研究院均有hc<br>4:华为目前在招产品线:BPIT，消费者终端，2012实验室，carbu，IT装备部，华为云，GTS，数字能源，光，无线，云核，公共开发，计算产品线，数存，数通，存储、数据库、云计算、人工智能、智能驾驶、音视频、实验室、芯片等5:福利待遇<br>全程线上面试，全额六险一金，试用期全薪资，有班车和食堂，独立办公园区<br>6:工作时间:弹性打卡，周末双休，每天早上9点上班，12-2点午休2小时，提供免费夜宵，周三周五家庭日，月末最后一个周六上班双倍加班费', '外企德科数字技术有限公司是一家2023年新成立的中外合资企业。成立于2023年11月24日，公司定位：专注于为信息技术企业提供人才及数字技术外包解决方案的中外合资企业。它是由中国人力资源服务行业的FESCO（北京国际人力资本集团）与全球人力资源服务领导者The Adecco Group（德科集团）合资成立的。公司主要提供网络技术服务、软件外包服务、计算机系统服务、技术进出口、软件开发等信息技术相关服务。专注于为信息技术企业提供信息技术类人才及数字技术外包解决方案。', 'https://www.zhaopin.com/jobdetail/CCL1480117890J40769644005.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (562, '测试工程师', '青岛瑞晟元人力资源有限公司', '2025年07月28日', '1-1.2万·13薪', '长春-朝阳区', '人力资源服务', '20人以下', '不需要融资', 'CCL1431271280J40777384407', NULL, NULL, 'https://www.zhaopin.com/jobdetail/CCL1431271280J40777384407.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (563, '技术支持工程师', '中科慧居(浙江)科技集团有限公司', '4月11日', '5000-8000元', '长沙-雨花区', '人工智能,云计算/大数据,企业服务', '100-299人', '未融资', 'CCL1320402630J40724011002', '工作职责： 1.负责项目售前投标事务，停车场现场勘察调研，道闸系统方案设计，绘制系统示意图，出具设备清单等。 <br>2.与客户进行技术交流，了解客户的技术要求和关注点，根据客户反馈，对方案进行调整和优化。 <br>3.负责项目售中协调设备到货，指导施工队进行设备安装调试工作。 <br>4.负责项目售后设备维护，能及时现场处理已有停车场设备故障，远程电话值守停车场，必要时进行抬杆操作。 <br>5.协助完成项目其他事宜。', '中科慧居科技集团是一家国家级双高新技术企业，是国际上技术领先的城市智慧停车解决方案提供商和运营商。公司依托中科院、北京科技大学等研发团队，自主研发了多款智能停车设备，已累计获得了50多项知识产权和专利，业务已涵盖城市级停车规划设计、城市级智慧停车解决方案及系统配套、停车场运营管理、停车场智能化建设及服务、立体车库投资建设、智慧停车商业系统平台开发等领域。因公司发展需要，工作地点在浙江嘉善，现特面向社会招聘优秀人才，我们诚邀您的加入。', 'https://www.zhaopin.com/jobdetail/CCL1320402630J40724011002.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (564, '科研人员', '嘉庚创新实验室', '2月29日', '2.2-4万', '厦门-翔安区', '学术/科研,新能源,电子/半导体/集成电路', '300-499人', '未融资', 'CCL1293679000J40623759115', '一、岗位职责 1.与项目负责人及项目组成员共同制定研究计划，独立开展应用技术研发并发表具有国际影响力的研究成果； <br>2.参与项目产业化技术难题攻克，以负责人身份依托项目组申请国家自然科学基金委青年项目等国家级、省市级项目； <br>3.协助项目组建设和管理，协助指导博后、研究生、本科生科研工作。', '以上岗位由厦门大学化学化工学院采用劳动合同/劳务派遣方式用工。嘉庚创新实验室（全称：福建能源材料科学与技术创新实验室）是由福建省政府批准设立、厦门市政府与厦门大学共同举办的二类事业单位。实验室以攻克“卡脖子”技术、推动高技术产业化为己任，布局高效能源存储、低碳能源系统、未来显示技术、石墨烯等先进材料、仪器装备网络、能源政策智库、产业建设与标准等7大研发方向等研发方向。', 'https://www.zhaopin.com/jobdetail/CCL1293679000J40623759115.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (565, 'Java', '外企德科数字技术有限公司', '2025-07-27 00:23:28', '1.5-3万·14薪', '上海-青浦区', '专业技术服务', '10000人以上', NULL, 'CCL1480117890J40725397505', '岗位要求：<br>1、扎实的编程能力，熟悉算法和数据结构；熟悉计算机的基础理论；<br>2、熟练使用JAVA，掌握Spring相关生态开源框架，熟悉MySql、MQ、Redis、SpringCloud等，熟悉事务、缓存、消息、负载均衡等；<br>3、熟悉Linux开发环境；<br>4、具有大规模高并发云服务设计和开发经验优先；<br>5、有微服务、容器相关开发经验优先<br>职位福利：五险一金、周末双休、带薪年假、大牛带队、绩效奖金、定期体检、补充医疗保险、试用期全薪<br>职位亮点：大牛带队 人才培养', '外企德科数字技术有限公司是一家2023年新成立的中外合资企业。成立于2023年11月24日，公司定位：专注于为信息技术企业提供人才及数字技术外包解决方案的中外合资企业。它是由中国人力资源服务行业的FESCO（北京国际人力资本集团）与全球人力资源服务领导者The Adecco Group（德科集团）合资成立的。公司主要提供网络技术服务、软件外包服务、计算机系统服务、技术进出口、软件开发等信息技术相关服务。专注于为信息技术企业提供信息技术类人才及数字技术外包解决方案。', 'https://www.zhaopin.com/jobdetail/CCL1480117890J40725397505.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (566, 'Java', '科锐尔人力资源服务(苏州)有限公司', '5月12日', '2-4万·16薪', '南京-雨花台区', '咨询服务', '1000-9999人', '已上市', 'CC453635220J40630245003', 'base：深圳、东莞、上海、南京、苏州、杭州、武汉、西安、成都、北京、广州、济南、长沙等多地区可选，线上面试，面试定薪定级，初中高级都有hc。', '科锐国际人力资源有限公司成立于1996年，总部位于北京。作为亚洲领先的整体人才解决方案服务商，科锐国际在中国大陆、香港、印度、新加坡等亚洲地区拥有超过79家分支机构，1,500余名专业招聘顾问，在超过18个行业及领域为客户提供中高端猎头、招聘流程外包、灵活用工、营销外包、校园招聘、培训、招聘咨询等解决方案。截至目前，科锐已与2,000余家跨国集团、国内上市公司、快速成长性企业及非盈利组织建立长期合作关系。其中70%为外资500强企业。', 'https://www.zhaopin.com/jobdetail/CC453635220J40630245003.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (567, 'Java', '沈阳瞻言科技有限公司', '2月26日', '5000-8000元', '沈阳-浑南区', '计算机软件,计算机软件,IT服务', '20-99人', '未融资', 'CCL1245865320J40699934409', '岗位职责：<br>1.参与软件项目的需求分析，理解业务需求，并转化为技术实现方案；<br>2.负责JAVA应用系统的设计和开发工作，编写高质量的代码；<br>3.负责系统的性能优化和故障排查，保证系统的稳定性和可靠性；<br>4.配合测试团队进行系统测试，确保软件的质量和用户体验；<br>5.编写和维护相关的技术文档，参与团队的技术交流和分享。<br>岗位要求：<br>1.本科及以上学历，计算机科学、软件工程或相关专业；<br>2.熟练掌握JAVA编程语言，具备良好的编程习惯和代码规范；<br>3.熟悉常用的JAVA开发框架和工具，如Spring、Hibernate、Maven等；<br>4.对面向对象编程、设计模式、数据结构和算法有深入理解；<br>5.具备良好的数据库设计和优化能力，熟悉SQL语言以及常见的数据库产品；<br>6.了解Linux操作系统和基本的网络知识；<br>7.具备良好的沟通能力和团队协作精神，能够与产品经理、前端工程师、测试工程师等紧密合作；<br>8.具备责任心、自我驱动能力和抗压能力，能够在快节奏的工作环境下保持高效的工作状态；<br>9.有良好的学习能力和英文阅读能力，能够快速掌握新的技术和工具。', '瞻言科技是一家专注智能AI应用技术的公司。公司拥有自主知识产权的视觉识别技术。公司主要业务范围：视觉识别技术及解决方案、基于“云+智能终端设备”的应用开发，大数据和物联网应用开发等。公司秉持“以智能应用技术为客户创造最大价值”的原则，致力于为用户提供卓越的软件产品与解决方案。公司拥有多年工作经验的管理团队，技术储备雄厚、攻坚能力出色的开发和测试团队。', 'https://www.zhaopin.com/jobdetail/CCL1245865320J40699934409.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (568, '技术支持工程师', '江苏朗誉企业服务有限公司', '7月15日', '7000-8000元', '苏州-工业园区', '企业服务,企业服务', '20人以下', '未融资', 'CCL1212063460J40863367615', '岗位要求：', '江苏朗誉企业服务有限公司是在工商行政管理局注册成立的专业从事人才招聘、人事代理、人力资源外包、人力资源管理业务的正规机构，我公司与全省120多家招聘网点接轨，与60多家大、中专院校有着密切的联系，为保障企业用工奠定了坚实的基础。公司以优质快速服务为宗旨，认真做事是我公司的基本原则，“诚信为本，客户至上”是本公司的经营理念。及时、迅速是我公司的特点，不论用人单位需要批量还是零星补充，我公司一视同仁，急用人单位所急，本公司愿成为企业一站式人力资源服务的提供商，通过对工作的持续改进，实现客户的永远满意!公司始终本着“以信为本,以质取胜”的宗旨，着眼于市场需求，高瞻远瞩，凭借多年来辛勤耕耘和守信的经营，已及广大客户的支持，赢得了客户的一致好评和信任!公司在不断发展的过程中逐渐建立起一套完善的服务流程、客户在这里可以得到技术咨询、项目服务合理化方案和标准化服务等一整套完善的服务支持，从而最大限度的满足客户的需求。', 'https://www.zhaopin.com/jobdetail/CCL1212063460J40863367615.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (569, 'C/C++', '东莞普莱信智能技术有限公司', '4月15日', '1.2-1.5万', '东莞-None', '仪器仪表制造,电子设备制造', '100-299人', 'B轮', 'CC614731080J40711492611', '岗位职责：1、根据软件开发项目管理和软件工程的要求，按照系统总体设计规格说明书进行软件<br>  <br>模块设计、实现及测试，并编写相关设计文档；<br>  <br>2、进行工业控制产品软硬件整体调试，实现特定的功能，达到工业产品性能要求；<br> 3、编写产品测试及使用说明书。<br>  <br>岗位要求：<br>  1、本科及以上学历，自动化、计算机、机械电子工程、电子信息工程、软件工程等相关专业；<br>   <br>2、精通C/C++，熟练使用开发工具<br>   <br>3、有数控系统、运动控制器、伺服驱动器等相关产品开发经验，或精通LINUX操作系统及驱动编写<br>   <br>3、熟悉硬件开发平台；<br> 5、对软件工程有较深的理解。<br>', '普莱信智能简介：普莱信是一家专门从事高端智能装备及关键零部件的研发、生产、销售的一体化解决方案提供商，是广东省重点引资的国家高新科技企业。普莱信拥有运动控制、机器视觉、直线电机和算法等全套核心技术，并以这些技术为基础，结合具体工艺，为半导体封测行业、光通信行业、电子元器件行业及锂电装备行业等提供固晶、绕线、焊线、点胶设备及智能化解决方案。深圳普莱信智能技术有限公司成立于2016年12月，是东莞普莱信控股子公司。深圳研发中心主要负责AOI设备、半导体设备的研发和销售。在国内发展先进半导体技术上，普莱信具有巨大的市场潜力和技术门槛，吸引了业界投资的密切关注，公司已在2018年宣布完成A轮融资。普莱信将继续在全球范围内吸引优秀人才，持续的增加研发投入，进入规模化的生产，致力于成为全球半导体设备领军企业，力促半导体关键设备的国产化。', 'https://www.zhaopin.com/jobdetail/CC614731080J40711492611.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (570, '软件测试', '青岛瑞晟元人力资源有限公司', '2025年07月30日', '1-1.2万·13薪', '银川-兴庆区', '人力资源服务', '20人以下', '不需要融资', 'CCL1431271280J40778344707', '岗位职责：<br>1. 负责软件的功能测试。<br>2. 执行测试用例，报告缺陷并跟踪缺陷的修复。<br>3. 与开发团队协作，确保软件质量满足需求。<br>4. 参与软件测试流程的优化和改进。<br>岗位要求：<br>1. 熟悉软件测试理论、方法和流程。<br>2. 具备功能测试经验。<br>3. 了解运维工程师、网络工程师的工作内容，能进行基本的IT质量管理。<br>4. 有信息技术、标准化、电子或电路工程相关背景者优先。<br>薪资待遇：包住、六险一金、工龄工资、生日礼金、定期体检、带薪年假、绩效奖、项目奖、年终奖.', NULL, 'https://www.zhaopin.com/jobdetail/CCL1431271280J40778344707.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (571, '前端开发', '武汉清达环保科技有限公司', '7月9日', '8000-16000元', '武汉-江夏区', '环保', '100-299人', '不需要融资', 'CC186107820J40747887211', '岗位职责：  岗位内容：  <br>1. 负责开发和维护前端系统和模块，确保其运行稳定可靠  <br>2. 编写高效、清晰、易于维护的代码  <br>3. 协调需求，与其他团队成员进行有效沟通和协作  <br>', '武汉清达环保科技有限公司成立于2002年，公司注册资金200万元，公司位于武汉市关山大道光谷软件园，公司现有工作人员40人，其中高级职称14人，中级职称16人，初级职称10人。拥有一批专业能力强，富有创造力，敢于开拓，团结合作，具有良好环境工程、环境监测、环境管理工作经验的中青年环保专家。公司与清华大学、北京大学、武汉大学、华中科技大学、湖北工业大学等高校建立了长期、紧密、广泛的技术合作关系，为公司的发展奠定了良好的环境和氛围。公司实行董事长领导下的总经理负责制，公司设有综合管理部、市场部、工程技术部、售后服务部。各室部之间团结互助，协调发展。公司主要从事废水、废气、废渣、噪声治理，环境影响评价，环境保护计划规划，清洁生产审核，ISO14000论证等环境技术咨询、技术服务。环境保护设备、设施研制、开发、生产、销售，是一个高新技术环保企业。', 'https://www.zhaopin.com/jobdetail/CC186107820J40747887211.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (572, 'Java', '四川若扬企业管理咨询有限公司', '7月23日', '1.5-2.2万', '广州-天河区', '企业服务', '20-99人', NULL, 'CCL1506191320J40867333315', '岗位内容：<br>1. 开发高质量的Java应用程序，保证代码的可读性、可维护性、可扩展性和性能。<br>2. 参与需求分析、系统设计和开发计划的制定。<br>3. 能够快速识别问题并提供有效的解决方案。<br>4. 与产品和测试团队紧密合作，确保产品质量符合用户期望。<br>任职要求：<br>1. 精通Java编程语言和Spring框架，有大型项目开发经验。<br>2. 拥有扎实的计算机基础，熟练掌握面向对象编程思想和设计模式。<br>3. 熟练使用常见的Web容器和数据库（如Tomcat、MySQL）。<br>4. 熟悉敏捷开发流程，具备优秀的沟通和协调能力。', NULL, 'https://www.zhaopin.com/jobdetail/CCL1506191320J40867333315.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (573, 'Java', '外企德科数字技术有限公司', '2025-07-27 00:25:09', '1.5-3万·14薪', '武汉-江夏区', '专业技术服务', '10000人以上', NULL, 'CCL1480117890J40781899505', '入职一对一带教，技术菜可培养，有年终奖，线上面试城市选择多<br>1.学信网可查的本科以上学历，计算机相关专业优先<br>2.掌握C/C++/Java/Python等其中一种或多种编程语言，熟悉Linux环境下相关开发。<br>3.对基本数据结构和算法有一定了解，喜欢动手实践。<br>4.具备良好的问题解决能力，乐于团队写作，热衷新技术，善于总结和分享。<br>5.有容器领域、分布式系统、Linux内核、数据库引擎开发经验者优先。<br>6.经验不限，年限越高能力越高薪资越高<br>7.入职后有培训带教贯穿试用期，试用期不打折<br>8.六险一金全额缴纳<br>9.有班车', '外企德科数字技术有限公司是一家2023年新成立的中外合资企业。成立于2023年11月24日，公司定位：专注于为信息技术企业提供人才及数字技术外包解决方案的中外合资企业。它是由中国人力资源服务行业的FESCO（北京国际人力资本集团）与全球人力资源服务领导者The Adecco Group（德科集团）合资成立的。公司主要提供网络技术服务、软件外包服务、计算机系统服务、技术进出口、软件开发等信息技术相关服务。专注于为信息技术企业提供信息技术类人才及数字技术外包解决方案。', 'https://www.zhaopin.com/jobdetail/CCL1480117890J40781899505.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (574, 'Java', '外企德科数字技术有限公司', '2025-07-27 00:23:29', '1.3-2.6万', '上海-浦东新区', '专业技术服务', '10000人以上', NULL, 'CCL1480117890J40735236805', '岗位职责：<br>1、社招OD岗位（全职非实习）。<br>2、深入部门，了解各业务需求，在此基础上进行软件架构设计与模块规划，确保软件功能契合业务目标。<br>3、研发效率和质量提升相关工具及解决方案开发；<br>4、负责研发工具需求模块设计、接口设计、代码开发及验证；<br>5、支撑工具应用推广及部门应用。<br>专业知识与业务技能要求：<br>1、统招本科及以上学历（需持双证），计算机，通信等相关专业优先。<br>2、热爱编程，精通java、C/C++等语言开发和编译原理相关知识；熟练掌握Java/Python/C++/C/等任意一种编程语言，有良好编程习惯<br>3、了解软件工程、敏捷开发等知识，熟悉常用设计模式。<br>4、具备云化、服务化等相关知识并能熟练运用。<br>5、熟悉Linux，并且能熟练搭建web服务器者优先。<br>6、具备独立工作及解决问题能力、善于团队沟通合作。工作有责任心、细心和耐心。<br>7、较好的自学能力和优秀的语言表达能力，热爱技术研发工作。<br>其余补充：<br>1、导师带教制度，工作经验不限；有it应用软件、互联网软件等相关开发经验优先。<br>2、前端/后端/测试等多岗位招聘<br>3、全国多地区有岗：北京/上海/南京/杭州/苏州/深圳/东莞/西安/成都/武汉/广州/济南四川等等<br>岗位亮点：<br>1、 大厂背书：依托平台强大的技术实力与行业资源，深度参与前沿大数据项目，接触顶尖技术与多元化业务场景。<br>2、 发展机遇：完善的培训体系与广阔的晋升空间，表现优秀者有机会在内部获得更多的发展机会。', '外企德科数字技术有限公司是一家2023年新成立的中外合资企业。成立于2023年11月24日，公司定位：专注于为信息技术企业提供人才及数字技术外包解决方案的中外合资企业。它是由中国人力资源服务行业的FESCO（北京国际人力资本集团）与全球人力资源服务领导者The Adecco Group（德科集团）合资成立的。公司主要提供网络技术服务、软件外包服务、计算机系统服务、技术进出口、软件开发等信息技术相关服务。专注于为信息技术企业提供信息技术类人才及数字技术外包解决方案。', 'https://www.zhaopin.com/jobdetail/CCL1480117890J40735236805.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (575, '硬件测试', '重庆科满福人力资源服务有限公司', '7月7日', '7000-10000元', '重庆-九龙坡区', '企业服务', '20-99人', NULL, 'CCL1487604860J40928936704', '【岗位职责】 ：<br>1、进行新产品研发阶段的测试工作<br>2、完成新产品的功能测试、可靠性测试、环境测<br>试、安全测试等技术工作<br>3、制定测试计划，设计测试用例，分析测试数<br>据，编制测试报告<br>4、为其他部门提供技术支持，与其他部门的产品<br>联合测试工作<br>', NULL, 'https://www.zhaopin.com/jobdetail/CCL1487604860J40928936704.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (576, 'C/C++', '北京微视新纪元科技有限公司', '7月9日', '4000-6000元', '北京-海淀区', '计算机软件,计算机硬件,电子/半导体/集成电路,IT服务', '100-299人', NULL, 'CC120504200J90250255000', '岗位职责：', '北京微视新纪元科技有限公司是北京市新技术产业开发区所属的股份制高新技术企业。公司从事视频图像采集板卡、模块、系统、软件、高速、高清晰度摄像头等自有产品的研制与开发。以图像处理、医学影像应用、工业检测、安防监控、模式识别、科学研究等领域为主要经营方向。公司具有多年开发视频图像产品的经验，一贯坚持技术上的不断创新和精益求精，并注重完善的售后服务。多年来，在设计、生产各种图像板卡和支持用户二次开发方面，公司投入了大量的技术力量，集中了一批优秀高级工程师作为企业技术核心，同时与多所著名大学和研究院保持着良好的长期合作关系。公司研究与开发的成果及产品在国内具有领先技术水平，受到广大用户的认可。公司拥有一支高效的营销队伍，从市场开拓、售后服务到技术支持都尽量做到最优，满足用户的需求。经过几年的不断发展，已成立了上海分公司及武汉办事处、南京办事处，并在西安、杭州、成都、深圳、沈阳等地发展了产品代理商。在用户的关爱和支持下，微视图像品牌产品用户群现已遍及各个行业领域，用户选用微视图像品牌图像卡、摄像头所开发的产品已销往德国、日本、美国、澳大利亚、俄罗斯等国家。', 'https://www.zhaopin.com/jobdetail/CC120504200J90250255000.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (577, '实施工程师', '广东健康在线信息技术股份有限公司', '7月20日', '2000-3000元', '中山-None', '卫生服务', '100-299人', NULL, 'CC428974930J40466056414', '工作要求', '广东健康在线信息技术股份有限公司是北京好医生健康产业集团旗下子公司，公司自2008年成立以来，一直专注于医疗卫生领域的解决方案，产品包括医疗信息化软件和医疗器械。公司秉承集团“助医康民”宗旨，以创新服务于医改，引入医学内涵给医疗行业软件和医疗服务带来新的价值。公司注册地在广东，在北京、合肥均设有研发中心，在全国各省市都设有分支机构。公司产品和解决方案包括：家庭医生系列产品、基层卫生信息系统（健康档案、HIS、医学知识库…）、区域卫生信息平台、健康云平台、健康一体机设备、全科医生出诊箱等等，公司产品已经在安徽、吉林、河北、广东、江西、湖南、陕西等多个省市使用，2017年公司产品用户突破2万人。我们通过“云时代”的技术创新，不断完善产品线，推动医疗卫生信息资源共享，逐步实现医疗服务、公共卫生、医疗保障、药品供应保障和综合管理等应用系统信息互联互通。并致力于开发、运营以健康数据收集、评估、干预为基础的健康管理应用产品。', 'https://www.zhaopin.com/jobdetail/CC428974930J40466056414.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (578, 'C/C++', '湖南飞象通用数据科技有限公司', '6月13日', '6000-12000元', '长沙-岳麓区', '计算机软件,云计算/大数据,计算机软件', '20-99人', NULL, 'CCL1447754770J40431953810', '1、根据需求高质量实现数据库管理系统及其相关工具的功能;', '飞象数据是专注于数据库、数据仓库和大数据等数据管理产品研发和技术服务的专业厂商，致力于为企业提供弹性灵动、自主可控的企业数据架构解决方案。飞象数据核心团队均在企业数据架构领域从业多年，对企业数据架构技术、产品和服务市场的发展演变有着独到的见解，在传统数据库和分布式数据库、数据仓库、大数据、数据即服务平台 DaaS等领域具有丰富的技术研究、产品研发、市场与营销、系统建设及服务经验。秉承\\\\\"技术引领、行业驱动、社区协同\\\\\"的产品理念，飞象数据紧扣国家的信息化发展战略和行业的信息化发展要求，以强大的Postgres数据库内核为产品基础，以持续的国产化研发和快速、专业的本地化服务为保障，面向传统企业应用和新一代的互联网应用、物联网应用、大数据应用等，为广泛的行业客户提供涵盖数据库、数据仓库、大数据等一体化企业数据架构解决方案。', 'https://www.zhaopin.com/jobdetail/CCL1447754770J40431953810.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (579, '技术支持工程师', '四川建设工程监理有限公司', '6月30日', '6000-8000元', '成都-金牛区', '建筑设备安装,工程施工', '100-299人', '未融资', 'CC387126230J40688863406', '岗位职责：<br>对能源改造或新建项目进行前期规划和售前技术支持（主要包括前期现场调研、方案的规划、技术交流、方案宣讲）；<br>1. 前期现场调研，调查所需要的事项，确定现场实际情况,并明确可以从实地调查中获得的信息；<br>2. 方案的规划，从前期现场调研和需求信息采集中设计解决方案通过需求调研、数据分析，输出能提升客户效益的解决方案；<br>3. 技术交流，与客户就设计方案进行面对面的沟通交流，通过阐述方案，让客户明确问题的解决方法；<br>方案宣讲，为客户讲解项目具体实施方案，并解答客户疑问；  4.领导安排的其他工作内容。', '四川建设工程监理有限公司为四川省建筑科学研究院有限公司的全资子公司，始建于1992年，是全国第一批监理试点单位，是川内最早一批注册成立的监理单位，也是四川建设监理协会理事单位、成都市建设监理协会常务理事单位。公司发展至今，已具有房屋建筑和市政公用工程监理双甲资质、工程造价咨询乙级资质、航天航空和水利水电工程专业乙级资质以及环境监理乙级等级证书。公司成立以来立足四川，放眼国内，始终秉持以监理业务为本业，坚持“诚实、守信、科学、公正”的工作作风，以“严格监理、热情服务”为服务尊旨，努力提高自身的监理水平，始终为业主着想，在提供监理常规服务的前提下，尽力提供差别化服务，做有特色监理，努力满足各类业主的需要。我公司监理的项目涉及住宅工程、商业办公、医院、学校、厂房、市政工程、装修工程等多个领域，其中多个项目还获得过鲁班奖、天府杯、芙蓉杯、全国建筑工程装饰奖等多种荣誉，如“华西医大附一院综合住院大楼”获得“鲁班奖”、“中国现代五项赛事中心场馆工程”等五个项目获得“天府杯”金奖、“四川博物馆主馆工程”等九个项目先后获得过“天府杯”银奖，“国药集团西南生产及物流中心工程”等项目获得“芙蓉杯”。在深耕监理业务的同时，公司也致力于打造一支“规范、专业、精细、高效”的人才队伍，依托四川省建筑科学研究院有限公司高级专业人才的优势，常设专家顾问团队，在设计咨询、方案审查及技术经济分析等方面发挥着重要的作用，专家组的技术领域覆盖地基基础设计与施工、结构设计、复杂及超高层建筑施工、钢结构工程施工、建筑节能与绿色建筑工程、通风空调工程、新能源及可再生能源工程、消防工程、智能建筑及信息化工程、质量事故分析处理、造价及合同管理等。公司现有正高级职称1名，高级职称12名，中级职称42名，注册监理工程师32名，一级造价工程师5名，一级注册建造师13名，中级安全工程师8人，一级注册消防工程师1名。在注重自身持续发展的同时，公司还积极响应政府号召，切实履行社会责任。在5.12地震、芦山地震、宜宾地震发生后的第一时间抽调专家组奔赴灾区，帮助灾区人民进行抗震救灾工作，有力地促进了灾后重建工作的顺利进行。此外，还认真贯彻落实省委、省政府脱贫攻坚的要求，扎实推进脱贫攻坚住房建设工作，派出公司精干技术力量，深入贫困地区开展技术帮扶工作！公司始终坚持“不求最大，只求最好，精耕细作”的宗旨，稳扎稳打，一步一个脚印，坚持以人才和品牌打造企业核心竞争力，目前已发展成为具备项目管理前期咨询、招标代理、造价咨询、工程监理、技术服务、第三方评估、运营维护、检测鉴定能力的综合性工程咨询企业。业务范围：房屋建筑工程监理、市政公用工程监理、航空航天工程监理、水利水电工程监理工程项目管理、工程造价咨询、招标代理', 'https://www.zhaopin.com/jobdetail/CC387126230J40688863406.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (580, '科研人员', '中国钢研科技集团有限公司', '7月23日', '1.3-1.5万', '保定-涿州市', '学术/科研,钢铁/有色金属冶炼及加工', '1000-9999人', '未融资', 'CC170490510J40688711410', '岗位职责：', '中国钢研科技集团有限公司（简称中国钢研）是国务院国资委直接管理的中央企业。2006年12月，经国务院同意、国务院国资委批准、原钢铁研究总院（创建于1952年）更名为中国钢研科技集团公司，冶金自动化研究设计院（创建于1973年）并入中国钢研科技集团公司。中国钢研是我国冶金行业最大的综合性研究开发和高新技术产业化机构，2009年5月，经国务院国资委批准改制为国有独资公司，设立董事会。中国钢研是国家首批103家创新型企业试点单位之一，是中关村科技园首批100家创新型企业之一，是我国金属新材料研发基地、冶金行业重大关键与共性技术的创新基地、国家冶金分析测试技术的权威机构，在长期的发展过程中，承担了大量863、973、国防军工、自然基金等国家重大项目和课题，在海洋、陆地、航空、航天、核技术等军工领域和国民经济主要行业领域都展示了不凡的研发实力，做出了重要贡献，创造了无愧于时代的业绩。展望未来，作为公益类科技型中央企业，中国钢研将以党的十九大精神为指导，贯彻创新驱动发展战略，全面深化改革，加快转型升级，在新的起点迈出更加坚实的步伐，早日建设成为国际一流的高新材料及科技创新企业集团，携手各界走向美好的明天！', 'https://www.zhaopin.com/jobdetail/CC170490510J40688711410.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (581, 'Java', '外企德科数字技术有限公司', '2025-07-27 00:25:08', '1.7-3万·14薪', '杭州-滨江区', '专业技术服务', '10000人以上', NULL, 'CCL1480117890J40781579905', '【岗位要求】<br>1、统招四年制本科/硕士，毕业证学位证齐全<br>2、3年以内/3-5年/5年以上Java开发工作经验；<br>3、熟悉SpringBoot/MyBatis框架，掌握MySQL基础应用；<br>4、具备基础Linux操作能力，了解Git版本管理工具。<br>注：初级岗位优秀的应届可以接受工作经验<br>【岗位职责】<br>1、负责核心业务模块开发，独立完成功能设计及代码实现<br>2、维护现有系统，优化代码质量与系统性能<br>3、参与技术方案讨论，配合团队完成项目交付<br>【面试流程】<br>流程：机考-匹配部门-hr面-2轮技术面-综面<br>重难点：机考和技术面<br>流程时长：2周~一个月（主要看机考，机考通过后一周闭环）<br>【可选择城市】<br>北京、上海、深圳、东莞、杭州、武汉、西安、成都、南京、长沙、济南<br>【待遇及福利】：<br>1、15-35k月薪14-16薪，周末加班双倍(根据技术面试能力定级定薪)<br>2、试用期全薪<br>3、入职全额五险一金<br>4、一带一导师制<br>5、优质研究所办公环境和技术氛围<br>6、交通报销、免费宵夜、班车、健身房、下午茶，团建，带薪年假', '外企德科数字技术有限公司是一家2023年新成立的中外合资企业。成立于2023年11月24日，公司定位：专注于为信息技术企业提供人才及数字技术外包解决方案的中外合资企业。它是由中国人力资源服务行业的FESCO（北京国际人力资本集团）与全球人力资源服务领导者The Adecco Group（德科集团）合资成立的。公司主要提供网络技术服务、软件外包服务、计算机系统服务、技术进出口、软件开发等信息技术相关服务。专注于为信息技术企业提供信息技术类人才及数字技术外包解决方案。', 'https://www.zhaopin.com/jobdetail/CCL1480117890J40781579905.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (582, 'Java', '山东鼎信数字科技有限公司', '5月8日', '6000-8000元', '济南-历下区', '互联网', '300-499人', NULL, 'CC463656010J40778014808', '岗位职责：<br>1、参与系统需求设计、编码及单元测试。<br>2、负责系统文档的编写，以及项目的内外沟通。', '山东鼎信数字科技有限公司(Decent鼎信)，成立于2010年，是国内领先的数字权益解决方案提供商，先后荣膺国家级高新技术企业、山东省瞪羚企业、山东省双软认证企业、山东省数字经济示范平台企业、山东省“一企一技术”研发中心企业、ISO9001质量管理体系认证企业。鼎信以“品牌赋能和合共生”为经营理念，凭借行业顶尖的全业务支撑能力，持续深耕数字权益领域，不断整合一线数字权益资源，业已全面联接覆盖国内主流品牌方，涵盖美食饮品、影音娱乐、商超购物、机酒出行、生活服务、知识阅读、充值缴费、运动健康等八大门类，上千种权益产品。在此基础上，鼎信陆续打造推出橙券、小橙生活、橙票票、橙积分、车加加等核心品牌，为银行、保险、电商、运营商等行业客户提供开放高效的专业服务，助力传统行业数字化转型升级和价值落地。 10年行业深耕，鼎信加速布局多场景生态，与企业级客户共享用户、场景、技术、运营能力，已为300+金融机构和上千家企业提供专业数字化服务。合作客户包括：中国银联、中国银行、中国农业银行、中国工商银行、招商银行、浙商银行、微众银行、中国人寿、中国平安、泰康人寿、新华保险、中国人民保险、中邮保险、中国移动、中国联通、中国电信、阿里、腾讯、京东、央视、国家电网、小鹏汽车等。', 'https://www.zhaopin.com/jobdetail/CC463656010J40778014808.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (583, '实施工程师', '陕西盛为网络科技有限公司', '6月4日', '3000-5000元', '西安-雁塔区', '计算机软件,通信/网络设备', '20-99人', '未融资', 'CCL1484388920J40859970504', '岗位职责：<br>1.根据企业内部、外部和资源状况等，分析建立方案的可行性,科学制定该项目的战略目标;<br>2.根据企业的实际情况，确定企业的需求，包括功能、时间、效率等方面的要求;<br>3.根据企业需求与产品之间的差距，制定产品改进方案。<br>任职要求：<br>1. 能负责项目实施的各个方面，全面调动人员积极性<br>2. 能合理安排工作任务,确保任务细化到人<br>3. 对各个任务有明确的计划。', '陕西盛为网络科技有限公司简介公司概述陕西盛为网络科技有限公司是一家专注于网络技术服务的企业，总部位于中国陕西省西安市。自成立以来，公司始终秉承“科技创新，服务至上”的理念，致力于为客户提供高效、优质的网络科技解决方案。业务领域陕西盛为网络科技有限公司主要业务涵盖网络系统集成、软件开发、网络安全服务、云计算服务、大数据分析等领域。凭借丰富的行业经验和强大的技术实力，公司已经成为陕西省内乃至全国范围内备受信赖的网络科技服务提供商之一。技术优势公司拥有一支由资深网络工程师、软件开发工程师、网络安全专家、大数据分析师等组成的专业团队。他们不仅具备深厚的技术功底，而且拥有丰富的项目实施经验。公司还与多家国内外知名IT企业建立了战略合作伙伴关系，确保能够为客户提供最前沿的技术支持和服务。服务理念陕西盛为网络科技有限公司始终坚持“客户至上，服务第一”的原则，致力于满足客户的各种需求。公司提供7*24小时的售后服务和技术支持，确保客户在使用过程中遇到任何问题都能够得到及时解决。未来展望面向未来，陕西盛为网络科技有限公司将继续加强技术创新，拓展业务领域，提升服务质量，努力成为国内领先的网络科技服务提供商。同时，公司也将积极履行社会责任，为推动信息化建设和数字经济发展做出更大贡献。', 'https://www.zhaopin.com/jobdetail/CCL1484388920J40859970504.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (584, '技术支持工程师', '山西金蝉电子商务有限公司', '7月9日', '1000-2000元', '太原-小店区', '互联网,企业服务,IT服务,电子商务', '100-299人', '未融资', 'CC404011380J40755677611', '岗位职责:<br>(1)负责公司客户以及公司内部各部门技术支持服务工作;<br>(2)负责各项目部技术支持人员输出工作;<br>(3)负责整理对外信息资料，业务信息流转工作;<br>(4)负责公司所有平台各类公告公示抽专家注册等的审核工作;<br>(5)负责对外信息对接等工作。<br>任职要求<br>(1)学历：本科及以上；<br>(2)专业：计算机、软件等相关专业；<br>(3)能独立工作，具有良好的沟通协调及抗压能力，能适应短期出差，有学生会干部经历者优先。<br>薪资：100-150元/天（本岗位为兼职实习生，以开标项目为工作单位，实习薪资按天数核算，无需整月在公司坐班，时间灵活。只接受大三及以上年级学生进行实习。）', '山西金蝉电子商务有限公司成立于2016年，注册资金4000万元，是响应2014年总理讲话要求、国办发〔2015〕63号文件精神以及国家治理机构数字化需求，在整合全国公共资源交易领域的过程中成立的一家专注于为政府及企业提供公共资源交易平台、企业数字采购平台、产业互联网平台及供应链金融平台的综合性高新科技公司。金蝉公司总部位于太原公共资源拍卖中心，在太原、北京和成都均设有研发中心，现有研发人员200余人，在山西省政务服务中心、山西转型综改示范区政务服务中心设立服务窗口。金蝉公司是国家级高新技术企业和双软认证企业、山西省数字招标采购领域高科技龙头企业、中国招标投标协会会员单位、中国物流与采购联合会会员单位、山西省招标投标行业协会电子招标投标交易平台专业委员会主任委员单位、山西省品牌与标准化建设促进会副会长单位、山西省2020年数字经济发展专项资金奖励企业、山西省专精特新企业、太原市数商协会会长单位。金蝉公司坚持自主研发，通过CMMI-3级认证，拥有9项专利和120余项软件著作权。“金蝉电子招标投标综合交易平台”是山西省首家全流程电子招投标交易平台，是山西省政府授权、国家及省发改委认定的法定省级电子招投标交易平台，并和国家、省公共资源交易电子服务系统、电子监管系统实现了互联互通。金蝉公司还自主研发了企业数字采购、供应链金融、产业互联网系列产品，正在为中煤地质总局、中国化工集团、山西转型综合改革示范区、山西省交通厅、山西省水利厅、山西省公路局、山西交通控股集团、山西建投、太重集团、华阳新材料科技集团、山西云时代技术有限公司、中条山有色金属集团、万家寨水务控股集团、山西航空产业集团、美锦能源集团、山西文旅集团等百余家政府部门和国有企业，数万家投标人、供货商提供服务，市场占有率领先同行。金蝉公司是京东生态合作伙伴、腾讯领航生态合作伙伴、腾讯千帆计划合作伙伴、百度战略合作伙伴、平安银行战略合作伙伴、中化物流港资管平台技术服务商，也是浦发银行电子保函系统服务商、山西银行和太原农商行电子保函系统开发商，并与中信银行、渤海银行、华夏银行、邮储银行、交通银行、民生银行、光大银行、中国人保财险、中国人寿保险、平安保险、太平保险等20余家金融机构保持长期深度合作。', 'https://www.zhaopin.com/jobdetail/CC404011380J40755677611.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (585, 'C/C++', '外企德科数字技术有限公司', '2025-07-27 01:14:31', '1-2万', '惠州-惠城区', '专业技术服务', '10000人以上', NULL, 'CCL1480117890J40792419805', '工作地点：', '外企德科数字技术有限公司是一家2023年新成立的中外合资企业。成立于2023年11月24日，公司定位：专注于为信息技术企业提供人才及数字技术外包解决方案的中外合资企业。它是由中国人力资源服务行业的FESCO（北京国际人力资本集团）与全球人力资源服务领导者The Adecco Group（德科集团）合资成立的。公司主要提供网络技术服务、软件外包服务、计算机系统服务、技术进出口、软件开发等信息技术相关服务。专注于为信息技术企业提供信息技术类人才及数字技术外包解决方案。', 'https://www.zhaopin.com/jobdetail/CCL1480117890J40792419805.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (586, 'Java', '东华医为科技有限公司', '2025-07-27 00:12:40', '5000-9000元', '呼和浩特-玉泉区', 'IT服务,IT服务', '1000-9999人', '未融资', 'CC649781480J40152371905', '工作职责：<br>1.负责医疗软件系统相关产品模块的研发工作，包括：医生工作站、药房药库、护理工作站、集成平台接口等<br>2.并能协助进行项目售前、咨询、实施、需求调研、需求分析等工作。<br>应具备的资格及条件:<br>1.计算机及相关专业本科及以上学历，具备基础开发经验<br>2.从事过大型管理系统的调研、设计、编程、文档撰写等工作优先<br>3.熟悉医院HIS系统者优先<br>4.有相关证书、工作经验者优先<br>专业知识和技能：<br>1. 熟练掌握至少一门计算机高级语言，如C#或Java等。<br>2. 了解web前端开发技术与工具，如JQuery，ExtJS，EasyUI等，能熟练使用javascript语言，熟悉HTML布局技术（HTML、DOM、CSS）。\n<br>3. 至少使用过一种数据库并能熟练使用SQL。\n<br>4. 具备一定的需求分析和系统设计能力，能够独立完成系统的开发、测试以及部署。\n<br>具备良好的沟通能力和表达能力，熟悉各种开发文档的编写。应届生放宽招聘要求。<br>职位福利：五险一金、通讯补助、定期体检、弹性工作、周末双休、包住、带薪年假、年终分红', '东华医为科技有限公司（简称东华医为）成立于2012年5月，注册资金5000万，是东华软件股份公司旗下专业服务医疗、卫生等大健康领域IT业务的全资子公司。东华医为现有员工2000余人，其中技术人员占比达到90%，拥有近100项大健康类自主知识产权的软件产品，所覆盖的大健康领域有医疗机构、卫生管理机构、互联网医疗、人工智能、大数据、健康管理等，所涉及的主要业务有IT咨询规划、方案设计、系统集成、软件开发与交付、工程实施与交付、人才培养、售后运维、合作运营等。东华医为现为全国500余家大健康领域的各类用户提供着持续的技术服务，还连续多年蝉联中国十佳医疗行业解决方案商榜首。传承了东华软件医疗卫生事业部近二十年IT业务的东华医为，在高速发展的大健康领域，笃定能大有作为。', 'https://www.zhaopin.com/jobdetail/CC649781480J40152371905.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (587, '测试工程师', '重庆科满福人力资源服务有限公司', '2025年07月30日', '6000-10000元', '焦作-修武县', '企业服务', '20-99人', NULL, 'CCL1487604860J40937111704', '【岗位职责】：<br>1、软件测试岗位职责 <br>2、接受测试任务，进行需求分析<br>3、按照测试计划搭建测试环境，并保证测试环境的可靠性<br>4、按照测试计划编亏测试用例，保证测试用例合理有效<br>5、按照测试用例执行测试，及时发现缺陷，并使用工具进行管理缺陷<br>6、编写和提交测试报告，保证测试进度按计划完成<br>7、参与审核其他测试工程师的测试用例和报告<br>8、学习公司已有方案和推广使用新的测试技术和工具<br>', NULL, 'https://www.zhaopin.com/jobdetail/CCL1487604860J40937111704.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (588, 'Java', '外企德科数字技术有限公司', '2025-07-27 00:23:22', '1.7-3万·14薪', '南京-雨花台区', '专业技术服务', '10000人以上', NULL, 'CCL1480117890J40600151105', '业务简介：<br>●Car Bu：问界智能车、智能驾驶、驾驶座舱、车载软件<br>●终端：手机、PC、平板、可穿戴产品、智慧办公等产品研发<br>●数存：数据存储部门主要着力于数据存储技术研发，业务排名国内第一。发展快，技术前沿。<br>●数字能源：部门业务涵盖了光伏发电、智能锂电池、电车机电系统、超速充电桩、模块电池、网络配电数据中心（国家新基建重点项目）、能源云等方向。是现在发展最快的行业之一。<br>●云：云计算部门主要做云服务、公有云、云平台及数字化平台等云相关业务。<br>●2012中央媒体院： 中媒鸿蒙项目新增软件开发和软件测试（开发和测试都必须是C++）<br>●除此以外，智能车、计算产品线、2012实验室、GTS、海思等部门都有需求<br>岗位要求：<br>1、具备良好的计算机、软件工程领域知识，熟悉软件系统设计、开发、测试等研发领域的流程、工程方法和工具；<br>2、精通C/C++、java、web、JS、python开发任意一种语言；<br>3、工作有责任心、细心和耐心', '外企德科数字技术有限公司是一家2023年新成立的中外合资企业。成立于2023年11月24日，公司定位：专注于为信息技术企业提供人才及数字技术外包解决方案的中外合资企业。它是由中国人力资源服务行业的FESCO（北京国际人力资本集团）与全球人力资源服务领导者The Adecco Group（德科集团）合资成立的。公司主要提供网络技术服务、软件外包服务、计算机系统服务、技术进出口、软件开发等信息技术相关服务。专注于为信息技术企业提供信息技术类人才及数字技术外包解决方案。', 'https://www.zhaopin.com/jobdetail/CCL1480117890J40600151105.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (589, '软件测试', '天阳科技', '7月19日', '5000-7000元', '中山-None', '计算机软件,计算机软件', '1000-9999人', '已上市', 'CC120408370J40654910508', '1.全国项目驻场测试，主要负责功能、数据或接口等相关测试工作； <br>2.统招本科学历及以上（学信网可查）；毕业满2年；计算机专业优先； <br>3.热爱软件测试行业、有强力的自驱力，能够在测试岗位深入学习研究； <br>4.有无经验均可，服从公司安排，接受公司培养，可接受异地工作优先； <br>福利待遇： <br>上市公司，公司可以提供住宿，提供五险一金； <br>欢迎符合要求的小伙伴们投递~', '天阳科技(股票代码：300872)，是全球金融创新服务的重要贡献者，持续赋能中国金融行业数字化转型，为客户提供咨询、金融科技产品、金融IT服务、云计算及运营服务。公司成立于2003年，服务超过300家金融行业客户，覆盖中央银行、政策性银行、国有银行、股份制银行、地方性商业银行、非银行金融机构等，员工人数近7000人，成为激活金融领域创新活力、推动金融科技迈入世界领先水平的重要力量。作为金融行业客户可信赖的合作伙伴，天阳科技凭借丰富的行业经验和端到端的专业服务，在信创、数字化金融、信贷、交易银行、信用卡、零售、营销、风险管理、征信监管等众多领域具备核心竞争力。据赛迪和IDC报告显示，近年来公司在中国银行业IT解决方案市场排名强势崛起，2019年收入及市场占有率综合排名分别位列第四位和第五位，并保持高速增长。同时，前瞻商业和科技趋势，入选2021年度未来银行科技服务商TOP100。天阳科技始终聚焦金融科技领域，加大自主创新力度，在超过100个城市建立本地化、专业化的研发和服务团队，拥有CMMI5级认证、软件测试成熟度模型集成（TMMi）3级认证、ISO9001质量管理体系认证、ISO20000信息技术服务管理体系认证、IS027001信息安全管理体系认证。通过部署人工智能、云计算、大数据、移动互联网、分布式计算和区块链等先进金融科技，公司致力于构建安全可控、普惠民生、开放共赢格局，在关键技术领域服务现代化金融发展大局，更好地为各利益相关方创造更大价值，为大中企业、小微企业以及每个个体提供优质金融服务。', 'https://www.zhaopin.com/jobdetail/CC120408370J40654910508.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (590, '科研人员', '南昌硅基半导体科技有限公司', '6月25日', '2-3万·13薪', '南昌-青山湖区', '电子/半导体/集成电路', '100-299人', NULL, 'CC416357410J40520232105', '（1）机械工程（0802）、电气工程（0808）、控制科学与工程（0811）、电子信息（0854）、计算机科学与技术（0812）、软件工程（0835）、仪器科学与技术（0804）、材料科学与工程(0805)等学科专业；<br>（2）研究生学历、博士学位；<br>（3）年龄：40周岁以下；<br>（4）工作职责及要求：从事半导体高端装备设计和开发工作，熟悉真空结构、智能制造技术、先进控制技术，有半导体设备研发经验者优先。<br>简历投递邮箱：*********************', '南昌硅基半导体科技有限公司（以下简称公司）是由南昌市人民政府（通过南昌市雍盛资产经营管理有限公司投资）、南昌高新技术产业开发区管理委员会（通过南昌高新区创业投资有限公司投资）、南昌大学和技术团队四方投资设立的有限责任公司，注册资本为1亿元人民币，于2011年4月27日在南昌市高新区注册成立。公司以南昌大学“国家硅基LED工程技术研究中心”（下称“工程中心”）为技术依托，主要从事 LED专用MOCVD装备的研发、生产和销售以及LED外延片、芯片、器件及其应用产品的研发、生产和销售等。其目标是在若干年内建成具有国际水准的MOCVD装备制造基地和LED工程中心。南昌硅基半导体科技有限公司与国家硅基LED工程技术研究中心，二者的建设合二为一，相互依存，共同发展，共同进步。公司已研制成功（37片/2吋）和（60片/2吋）MOCVD设备，已达到国际先进水平，部分指标优于进口设备。公司硅衬底蓝光与绿光LED外延与芯片制造技术已达到国际一流水平。公司目前正在南昌市高新区赣江之滨、艾溪湖畔建厂，实施产业化。同时实现新一代硅基LED芯片的规模化生产。', 'https://www.zhaopin.com/jobdetail/CC416357410J40520232105.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (591, '实施工程师', '上海麦本医疗科技有限公司', '7月22日', '7000-12000元', '上海-闵行区', '医疗设备/器械,贸易/进出口,卫生服务', '20-99人', '未融资', 'CC313702080J40675765406', '岗位职责：<br>1、负责动物医疗器械产品的现场安装、调试、培训、技术解答服务，保证仪器良好运行。<br>2、负责国外客户售前、售中和售后的远程技术支持。<br>3、负责产品的出货前检测，确保各项技术指标运行正常。<br>4、定期回访客户，及时解决客户日常使用中的技术问题，收集客户的反馈信息，提高客户满意度。<br>5、协助销售人员为客户提供产品讲解、实操演示和试机服务。<br>6、为销售人员提供定期的产品培训和及时的技术支持。<br>7、在展会或技术交流会提供产品展示和新产品宣讲。<br>8、研究同行竞品特点和我司产品优势，为销售人员提供营销支持。<br>9、积极关注动物医疗行业技术发展趋势和动态，为公司新产品开发提供支持。<br> <br>任职要求：<br>1、自动化类、电子电气类、机械类、计算机类、网络工程类等相关专业本科以上学历。<br>2、外语能力良好，CET-4级以上，能用英语与客户沟通者优先考虑。<br>3、良好的沟通能力和服务意识，快速的分析问题能力，动手能力强。<br>4、有责任心和团队协作精神，能适应短期国内出差和偶尔的国外出差。<br> <br>薪资待遇：基本工资＋绩效工资＋社保（五险一金）＋年终奖＋节日福利＋生日关怀＋周末双休+带薪休假（满1年5天年假）<br>工作时间：9:00~12:00；13:00-18:00<br>双休制：周六、周日休息，其他节假日按国家法律规定正常休假<br>试用期：2-6个月<br>工作地点：上海市莘庄商务区（顾戴路/中春路口）<br>工作地址：上海市闵行区顾戴路3009号祥鹿大厦707室<br>交通路线：<br>1、 地铁12号线“七莘路”站（距公司1KM，步行15分钟）；<br>2、 公交748路、759路到“顾戴路中春路站”（站台在公司楼下）；<br>3、 公交125路b线到“友东路顾戴路”站（距公司300米，步行3分钟）；<br>4、 公交87路、735路到“中春路华中路”站（距公司350米，步行5分钟）；<br>5、 公交闵行21路、闵行33路到“顾戴路秀波路”站（距公司700米，步行10分钟）。<br> <br>注：<br>此岗位工作地点在上海市闵行区顾戴路（近中春路），为节约您的时间，请视自身居住地点的实际情况再决定是否投递简历，谢谢配合！', 'SHINOVA|施诺华，麦本医疗旗下品牌，动物医疗创新者。麦本医疗，专注于动物医疗领域的产品制造商和解决方案提供商。凭借其在动物医疗领域深耕多年的国际市场运营经验，为欧洲、北美、澳洲、中国等在内的数万家动物医院（含宠物医院和马医院）和兽医院校（含动物实验和教学实训）提供创新的精准医疗产品和医学解决方案。', 'https://www.zhaopin.com/jobdetail/CC313702080J40675765406.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (592, '实施工程师', '东华医为科技有限公司', '2025-07-27 00:17:41', '9000-14000元', '漳州-龙海区', 'IT服务,IT服务', '1000-9999人', '未融资', 'CC649781480J40497191605', '工作内容<br>1、具备HIS实施经验优先考核。<br>2、根据项目经理要求按计划实施项目, 做好项目实施中的沟通协调及实施过程反馈；<br>3、了解医院业务，确定医院业务流程，整理用户需求，进行软件调试、安装、培训，解决实施过程中出现的问题；<br>4、对医院医生、护士、操作员等进行操作培训；<br>5、指导用户进行基础数据准备；<br>6、根据公司要求，完成相关实施文档。<br>任职要求<br>1、有PMP、软考项目管理等资质者优先考虑；<br>2、入职地区可在厦门、漳州、泉州、福州、三明、龙岩、莆田；', '东华医为科技有限公司（简称东华医为）成立于2012年5月，注册资金5000万，是东华软件股份公司旗下专业服务医疗、卫生等大健康领域IT业务的全资子公司。东华医为现有员工2000余人，其中技术人员占比达到90%，拥有近100项大健康类自主知识产权的软件产品，所覆盖的大健康领域有医疗机构、卫生管理机构、互联网医疗、人工智能、大数据、健康管理等，所涉及的主要业务有IT咨询规划、方案设计、系统集成、软件开发与交付、工程实施与交付、人才培养、售后运维、合作运营等。东华医为现为全国500余家大健康领域的各类用户提供着持续的技术服务，还连续多年蝉联中国十佳医疗行业解决方案商榜首。传承了东华软件医疗卫生事业部近二十年IT业务的东华医为，在高速发展的大健康领域，笃定能大有作为。', 'https://www.zhaopin.com/jobdetail/CC649781480J40497191605.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (593, '硬件测试', '重庆科满福人力资源服务有限公司', '6月28日', '8000-10000元', '重庆-丰都县', '企业服务', '20-99人', NULL, 'CCL1487604860J40922843504', '【岗位职责】 ：<br>1、进行新产品研发阶段的测试工作<br>2、完成新产品的功能测试、可靠性测试、环境测<br>试、安全测试等技术工作<br>3、制定测试计划，设计测试用例，分析测试数<br>据，编制测试报告<br>4、为其他部门提供技术支持，与其他部门的产品<br>联合测试工作', NULL, 'https://www.zhaopin.com/jobdetail/CCL1487604860J40922843504.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (594, '前端开发', '海南新珠江人力资源开发管理有限公司', '7月23日', '6000-11000元', '海口-龙华区', '专业技术服务', '20-99人', NULL, 'CC384412210J40760137912', '工作职责：<br>1.负责前端界面的构建，各类交互设计与实现；<br>2.前端样式和脚本的模块化设计和开发；<br>3.系统测试，开发及使用等文档的编制。<br>职位要求：<br>1.计算机科学或相关本科专业毕业；<br>2.熟悉 Web 前端开发技术，HTML、CSS 和 Javascript 基础扎实；<br>3.对 Web 技术有强烈兴趣，有优秀的学习能力和强烈的进取心；<br>4.对界面的布局有良好的规划、设计及实现能力。<br>具有以下能力者优先考虑：<br>1.熟悉 W3C 标准，对表现与数据分离、Web 语义化有深刻理解；<br>2.熟悉 ES6 语法；<br>3.有 Vue 框架开发经验；<br>4.有 Node.js 开发经验；<br>5.有前端性能优化经验；<br>6.能使用 Git 等代码工具进行团队协作。', '海南新珠江人力资源开发管理有限公司成立于2007年6月，是“广东锐博人力”集团下属的全资子公司。传承锐博“锐志前行，博业为专”的精神，立足海南，提供全方位的人力资源服务。在全省十九个市县均设有分公司，并于各注册地社保局开有社会保险登记帐户。', 'https://www.zhaopin.com/jobdetail/CC384412210J40760137912.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (595, '前端开发', '信雅达', '7月23日', '8000-15000元', '合肥-包河区', '计算机软件,IT服务', '1000-9999人', '已上市', 'CC146032650J40730527716', '1、统招本科毕业，计算机相关专业优先 2、沟通协作能力：具有良好的语言表达能力、人际沟通技巧和团队合作精神，能够与产品、设计、测试等团队紧密合作', '信雅达系统工程股份有限公司信雅达系统工程股份有限公司成立于1996年，是浙江省第一家在上海证券交易所上市（股票代码：600571）的高科技软件企业，系国家计算机信息系统集成一级资质企业、国家规划布局内重点软件企业、国家火炬计划重点高新技术企业、“十五”国家863计划成果产业化基地、中国软件业百强企业、中国BPO十强企业等,是经国家密码管理委员会批准的商用密码产品生产定点单位。公司设有省级企业技术中心和博士后工作站。经过多年积累，公司在金融软件、金融设备、金融服务、金融咨询等领域积累了自身的核心技术优势。金融软件领域，信雅达一直坚持技术创新和技术积累，帮助金融行业打造集中运营能力、流程再造和和流程创新能力、风险管理能力、渠道及客户管理能力，实现了基于业务创新的技术革新，取得了国内领先的成绩。金融咨询领域，信雅达为金融行业客户提供专业的咨询规划，包括集中运营建设咨询、远程银行建设、呼叫中心建设和运维咨询、业务流程外包实施咨询等多项咨询服务，帮助金融企业加速业务流程和技术革新等能力。金融设备领域，信雅达在十余年的金融领域积累了丰富的行业应用经验和强大的技术实力，迄今为止已形成了以安全平台为基础的金融安全设备产品线和以支付平台为基础的金融终端设备产品线。金融服务领域，信雅达在杭州、合肥、苏州、大连设立了四大数据处理中心，创造了中国BPO领域的独特模式。同时，信雅达大力发展软件外包事业，承接欧美、日本软件外包项目。信雅达产品已在中国人民银行、中国工商银行、中国农业银行、中国银行、中国建设银行、招商银行、中信银行、华夏银行、广发银行、平安银行、香港交通银行、工银亚洲、中国银联等总行总部及分支机构，以及证券、保险等领域获得广泛应用，并出口日本、美国、德国、新西兰等三十多个国家。', 'https://www.zhaopin.com/jobdetail/CC146032650J40730527716.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (596, '测试工程师', '软通动力信息技术(集团)股份有限公司', '3月24日', '1-1.8万', '上海-青浦区', '互联网,IT服务,计算机软件', '10000人以上', 'D轮及以上', 'CC000544460J40331984616', '岗位一：  <br>1、熟悉相关网络协议，熟悉无线通信理论知识，理解并应用过主流测试框架unitest,seleniumrobotframework  <br>2、有过攻放相关BBIT，UT，可靠性测试经验，具备射频性能测试，环境搭建维护能力，具有硬件板级电源UT,数字中射频，射频单元测试，器件替代和滤波器测试经验，个别人员需要具备自动化AW能力，例如Python Ruby Java  <br>3、测试执行能力，具备开展测试分析场景构造和评执行评估能力，具备领域特性/领域特性责任田看护能力，具备复杂场景分析的构建能力，熟悉使用软硬件测试平台和工具，具备常用缺陷分析能力。  <br>4、专题保障:具备独立开展兼容性、一致性测试类型和活动的能力。  <br>', '软通动力信息技术（集团）股份有限公司（以下简称“软通动力”）是中国数字技术产品和服务创新领导企业，致力于成为一家具有全球影响力的科技企业，企业数字化转型可信赖合作伙伴。公司2005年成立于北京，多年来始终坚持科技创新，具有软硬全栈的智能技术产品和服务能力，提供软件与数字技术服务、计算产品与数字基础设施、数字能源与智算服务以及国际化服务。目前，公司在10余个重要行业服务超过1100家国内外客户，其中超过230家客户为世界500强或中国500强企业，员工近90000人。软通动力拥有软通咨询、软通金科、软通工业互联、机械革命、软通华方等业务子品牌，并在全球40余个城市布局业务，构建北美、日本、东南亚、中东四大国际交付中心，在北京城市副中心、江苏无锡建设两大智能制造基地。同时，公司前瞻布局智能制造、ICT软硬基础能力和生产力智能化产品，打造产业链闭环。软通动力设立30个能力中心，拥有1个国家级工程实验室，6个省市政府认定的工程、技术实验室及研发中心，1个博士后科研工作站，50+技术合作伙伴的生态合作体系，不断探索前沿技术的巨大商业应用潜力。公司旗下教育品牌软通教育，拥有一家全日制本科学院——郑州西亚斯学院数字技术产业学院；同时在全国合作院校600多所，设有70多个校企联合人才培养基地，通过校企合作、协同育人，为社会培养高素质应用型人才。软通动力先后获得“2023年中国IT服务市场排名TOP 1”、“2024年Q4 PC出货量国内市场份额排名TOP 2”、“2024年中国软件和信息技术服务竞争力百强企业”、“2023年中国信创企业100强”、“2024万得ESG评级（Wind ESG Rating）AA级及信息技术服务行业ESG综合得分排名第一”等荣誉及市场认可，并拥有全球软件工程领域最高级别CMMI V2.0成熟度5级评估认证、国家研发运营一体化（DevOps）三级能力成熟度模型认证、信息技术服务标准（ITSS）运维能力成熟度一级认证等专业资质，支撑公司更优质的服务体系。', 'https://www.zhaopin.com/jobdetail/CC000544460J40331984616.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (597, '实施工程师', '蓝太平洋', '7月2日', '6000-10000元', '北京-海淀区', '计算机软件,IT服务,互联网,计算机硬件', '20-99人', '已上市', 'CC120725050J40738623705', '岗位职责：<br>1、针对公司产品进行系统的配置，运行；<br>2、独立解决软件安装、运行过程中出现的各种问题；<br>3、完成对产品的集成测试、联调测试；<br>4、针对公司的产品给客户出具报告；<br>5、与客户解决方案交流沟通以及讲解。<br>任职要求：<br>1、计算机相关专业；<br>2、熟悉linux操作系统、数据库及网络环境；<br>3、较强的逻辑分析能力和学习能力，能够快速的学习所实施软件产品，了解其功能点；<br>4、良好的沟通能力及团队合作精神，较强的责任感和进取精神；<br>5、热爱实施工作，工作细致认真，有耐心。', '北京蓝太平洋科技股份有限公司成立于1999年，是国家高新技术企业、中关村瞪羚计划企业、软件企业、AAA信用企业，通过了国际质量体系ISO9001认证、环境管理体系14001认证。公司拥有发明专利2个，软件著作权证书63个，各类行业获奖证书20多个。蓝太平洋是新三板企业，于2015年6月份挂牌。蓝太平洋下属武汉公司、吉林公司、包头公司、太原公司、日照公司、上海办事处、广州办事处、成都办事处、哈尔滨办事处、乌鲁木齐办事处。蓝太平洋是专业的大数据服务厂商，提供大数据平台、融媒体平台、评估服务平台等综合服务。蓝太平洋建立了自己的云数据中心，在全国各运营商以及国外部署了大量的网站数据探测节点。构建了互联网数据监测服务中心、网站体检监测云服务中心。', 'https://www.zhaopin.com/jobdetail/CC120725050J40738623705.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (598, '技术支持工程师', '现代电梯(杭州)有限公司', '3月18日', '5000-7000元', '杭州-西湖区', '电气机械/电力设备', '100-299人', '未融资', 'CC208701080J40640055413', '岗位职责： <br>1、负责土建图绘制； <br>2、根据客户询单出具非标技术方案及报价； <br>3、针对售前技术问题进行答疑，及时响应客户需求； <br>4、为新梯销售业务提供技术支持，促进销售的成交；<br>5、完成上级领导安排的其他工作。<br>岗位要求： <br>1、本科及以上学历，机械相关专业； <br>2、熟练使用AUTOCAD等制图软件； <br>3、有较强的沟通表达能力； <br>4、具备主动学习的意愿和能力。', '现代电梯（杭州）有限公司于1994年经杭州市工商局核准成立，注册资金为2.16亿元。生产基地位于浙江省杭州市，专业设计制造各类乘客电梯、自动扶梯、载货电梯，并提供强大的技术支援体系，包括研发、设计、制造、安装、改造、维修、保养等全程服务。现代电梯依托于三杭集团在国内电梯配件市场的垄断地位，并凭借自身电梯研发、设计、制造技术的积累，数年来一直为中国乃至亚太地区提供智能建筑交通解决方案和服务支持。公司经过26年的发展，规模不断扩大，凭借着高品质的产品生产、销售与售后服务，先后被评为杭州高新技术产业及国家高新技术产业。未来，现代电梯将继续秉承“科技、创新、服务、极致”的宗旨，努力将城市转变为最佳的居住地。在每一步工作中，我们都将力争全面了解客户的需求，在整个项目生命周期内提供安全、优质的乘客运输解决方案。我们相信，随着中国制造到中国创造的崛起，我们也将代表中国品牌，重新塑造电梯品牌的世界格局。', 'https://www.zhaopin.com/jobdetail/CC208701080J40640055413.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (599, '实施工程师', '四川建设工程监理有限公司', '6月30日', '6000-8000元', '成都-金牛区', '建筑设备安装,工程施工', '100-299人', '未融资', 'CC387126230J40688863406', '岗位职责：<br>对能源改造或新建项目进行前期规划和售前技术支持（主要包括前期现场调研、方案的规划、技术交流、方案宣讲）；<br>1. 前期现场调研，调查所需要的事项，确定现场实际情况,并明确可以从实地调查中获得的信息；<br>2. 方案的规划，从前期现场调研和需求信息采集中设计解决方案通过需求调研、数据分析，输出能提升客户效益的解决方案；<br>3. 技术交流，与客户就设计方案进行面对面的沟通交流，通过阐述方案，让客户明确问题的解决方法；<br>方案宣讲，为客户讲解项目具体实施方案，并解答客户疑问；  4.领导安排的其他工作内容。', '四川建设工程监理有限公司为四川省建筑科学研究院有限公司的全资子公司，始建于1992年，是全国第一批监理试点单位，是川内最早一批注册成立的监理单位，也是四川建设监理协会理事单位、成都市建设监理协会常务理事单位。公司发展至今，已具有房屋建筑和市政公用工程监理双甲资质、工程造价咨询乙级资质、航天航空和水利水电工程专业乙级资质以及环境监理乙级等级证书。公司成立以来立足四川，放眼国内，始终秉持以监理业务为本业，坚持“诚实、守信、科学、公正”的工作作风，以“严格监理、热情服务”为服务尊旨，努力提高自身的监理水平，始终为业主着想，在提供监理常规服务的前提下，尽力提供差别化服务，做有特色监理，努力满足各类业主的需要。我公司监理的项目涉及住宅工程、商业办公、医院、学校、厂房、市政工程、装修工程等多个领域，其中多个项目还获得过鲁班奖、天府杯、芙蓉杯、全国建筑工程装饰奖等多种荣誉，如“华西医大附一院综合住院大楼”获得“鲁班奖”、“中国现代五项赛事中心场馆工程”等五个项目获得“天府杯”金奖、“四川博物馆主馆工程”等九个项目先后获得过“天府杯”银奖，“国药集团西南生产及物流中心工程”等项目获得“芙蓉杯”。在深耕监理业务的同时，公司也致力于打造一支“规范、专业、精细、高效”的人才队伍，依托四川省建筑科学研究院有限公司高级专业人才的优势，常设专家顾问团队，在设计咨询、方案审查及技术经济分析等方面发挥着重要的作用，专家组的技术领域覆盖地基基础设计与施工、结构设计、复杂及超高层建筑施工、钢结构工程施工、建筑节能与绿色建筑工程、通风空调工程、新能源及可再生能源工程、消防工程、智能建筑及信息化工程、质量事故分析处理、造价及合同管理等。公司现有正高级职称1名，高级职称12名，中级职称42名，注册监理工程师32名，一级造价工程师5名，一级注册建造师13名，中级安全工程师8人，一级注册消防工程师1名。在注重自身持续发展的同时，公司还积极响应政府号召，切实履行社会责任。在5.12地震、芦山地震、宜宾地震发生后的第一时间抽调专家组奔赴灾区，帮助灾区人民进行抗震救灾工作，有力地促进了灾后重建工作的顺利进行。此外，还认真贯彻落实省委、省政府脱贫攻坚的要求，扎实推进脱贫攻坚住房建设工作，派出公司精干技术力量，深入贫困地区开展技术帮扶工作！公司始终坚持“不求最大，只求最好，精耕细作”的宗旨，稳扎稳打，一步一个脚印，坚持以人才和品牌打造企业核心竞争力，目前已发展成为具备项目管理前期咨询、招标代理、造价咨询、工程监理、技术服务、第三方评估、运营维护、检测鉴定能力的综合性工程咨询企业。业务范围：房屋建筑工程监理、市政公用工程监理、航空航天工程监理、水利水电工程监理工程项目管理、工程造价咨询、招标代理', 'https://www.zhaopin.com/jobdetail/CC387126230J40688863406.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (600, '测试工程师', '天阳科技', '7月24日', '5000-7000元', '临沂-兰山区', '计算机软件,计算机软件', '1000-9999人', '已上市', 'CC120408370J40824184708', '1.全国项目驻场测试，主要负责功能、数据或接口等相关测试工作；<br>2.统招本科学历及以上（学信网可查）；毕业满2年；计算机专业优先；<br>3.热爱软件测试行业、有强力的自驱力，能够在测试岗位深入学习研究；<br>4.有无经验均可，服从公司安排，接受公司培养，可接受异地工作优先；<br>福利待遇：<br>上市公司，公司可以提供住宿，提供五险一金；<br>欢迎符合要求的小伙伴们投递~', '天阳科技(股票代码：300872)，是全球金融创新服务的重要贡献者，持续赋能中国金融行业数字化转型，为客户提供咨询、金融科技产品、金融IT服务、云计算及运营服务。公司成立于2003年，服务超过300家金融行业客户，覆盖中央银行、政策性银行、国有银行、股份制银行、地方性商业银行、非银行金融机构等，员工人数近7000人，成为激活金融领域创新活力、推动金融科技迈入世界领先水平的重要力量。作为金融行业客户可信赖的合作伙伴，天阳科技凭借丰富的行业经验和端到端的专业服务，在信创、数字化金融、信贷、交易银行、信用卡、零售、营销、风险管理、征信监管等众多领域具备核心竞争力。据赛迪和IDC报告显示，近年来公司在中国银行业IT解决方案市场排名强势崛起，2019年收入及市场占有率综合排名分别位列第四位和第五位，并保持高速增长。同时，前瞻商业和科技趋势，入选2021年度未来银行科技服务商TOP100。天阳科技始终聚焦金融科技领域，加大自主创新力度，在超过100个城市建立本地化、专业化的研发和服务团队，拥有CMMI5级认证、软件测试成熟度模型集成（TMMi）3级认证、ISO9001质量管理体系认证、ISO20000信息技术服务管理体系认证、IS027001信息安全管理体系认证。通过部署人工智能、云计算、大数据、移动互联网、分布式计算和区块链等先进金融科技，公司致力于构建安全可控、普惠民生、开放共赢格局，在关键技术领域服务现代化金融发展大局，更好地为各利益相关方创造更大价值，为大中企业、小微企业以及每个个体提供优质金融服务。', 'https://www.zhaopin.com/jobdetail/CC120408370J40824184708.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4301, '实施工程师', '武汉中瀚科技有限公司', '7月23日', '4000-6000元', '长沙-天心区', '通信/网络设备,互联网,计算机硬件,运营商/增值服务', '100-299人', '未融资', 'CC121143210J40776351507', '岗位职责     1、负责中国移动长沙分公司驻点支撑   <br>2、负责长沙分公司相关业务的现场处理   <br>3、负责协助市管理员处理相关流程问题   <br>4、负责梳理市公司组织架构，找到关键人，便于后期能够突破   <br>5、通过业务培训及汇报材料，工作量统计，完成移动对项目的整体要求', '武汉中瀚科技有限公司是集位置产品研发、销售和服务为一体的高新技术企业，拥有高新、双软及多项产品著作权，公司注册资金2500万，公司资产规模达到1.8亿。产品主要以BDS北斗卫星导航系统、GPS全球定位系统、GIS地理信息系统技术为核心研发的位置管理平台于2013年通过了国家交通部符合性审查，为湖北省交通厅获批“两客一危”运营服务企业之一，目前运营平台车辆用户数近5.5万，用户总量为华中地区位置服务运营商首列，现有位置信息化解决方案已覆盖98%以上行业用户自2012年底，国家北斗定位导航系统正式宣布提供区域服务开始，作为位置服务运营龙头企业，积极响应国家号召，致力于北斗产业运营推广工作，现已与“华中北斗产业联盟”、“华中甩挂联盟”、“湖北运输物流协会”等行业协会及联盟结成紧密合作伙伴关系。是“湖北省北斗产业联盟”常务理事会员。公司秉承“安全、便捷”的服务理念，采用互联网、移动互联网等多渠道信息网络，为用户提供优质安全高效的服务，产品服务网点遍布全国31个省、市、自治区，700余家基层服务单位。公司坚持以“软件、硬件、服务三位一体”，为客户和社会创造更高价值，致力于成为技术领先、市场领先的品牌，做物联网行业应用市场的领导者，向成功的长跑型企业的目标不断迈进。', 'https://www.zhaopin.com/jobdetail/CC121143210J40776351507.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4302, '实施工程师', '东华医为科技有限公司', '2025-07-27 00:28:41', '7000-12000元', '济南-槐荫区', 'IT服务,IT服务', '1000-9999人', '未融资', 'CC649781480J40792096905', '1、英语水平较高；', '东华医为科技有限公司（简称东华医为）成立于2012年5月，注册资金5000万，是东华软件股份公司旗下专业服务医疗、卫生等大健康领域IT业务的全资子公司。东华医为现有员工2000余人，其中技术人员占比达到90%，拥有近100项大健康类自主知识产权的软件产品，所覆盖的大健康领域有医疗机构、卫生管理机构、互联网医疗、人工智能、大数据、健康管理等，所涉及的主要业务有IT咨询规划、方案设计、系统集成、软件开发与交付、工程实施与交付、人才培养、售后运维、合作运营等。东华医为现为全国500余家大健康领域的各类用户提供着持续的技术服务，还连续多年蝉联中国十佳医疗行业解决方案商榜首。传承了东华软件医疗卫生事业部近二十年IT业务的东华医为，在高速发展的大健康领域，笃定能大有作为。', 'https://www.zhaopin.com/jobdetail/CC649781480J40792096905.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4303, '实施工程师', '北京用尚科技股份有限公司', '6月30日', '5000-8000元', '天津-南开区', '计算机软件,电力/水利/热力/燃气', '100-299人', '已上市', 'CC150587510J40752385711', '岗位职责：<br>  <br>1、负责在建业务系统的项目推进工作，包括需求交流、需求分析设计、安装部署、接口调试、升级维护等；<br>  <br>2、负责项目技术资料的输出；<br>  <br>3、主导或协助项目成果的验收交付、用户培训；<br>  <br>4、现场用户使用体验跟进与反馈；<br>  <br>5、承担在运业务系统日常技术支持与运维工作。<br>  <br>岗位要求：<br>  <br>1、统招本科及以上学历，计算机、软件工程、信息管理自动化、电子信息等专业；<br>  <br>2、对计算机软件、硬件、网络知识有一定的掌握；<br>  <br>3、对数据库、操作系统、网站部署等相关知识熟练掌握；<br>  <br>4、文字组织能力强，能够独立完成软件工程文档；<br>  <br>5、工作积极主动，善于沟通，责任心强，敢于钻研，有一定抗压能力；<br>  <br>6、适应出差，有一年及以上相关软件实施工作经验者优先。<br>', '北京用尚科技股份有限公司成立于2002年，公司总部位于上地信息产业基地，已在天津、石家庄、太原、成都等城市设立研发中心和办事处，是国家认定的高新企业和双软企业，注册资本2000万。2016年2月，公司在“新三板”即全国中小企业股转系统正式挂牌上市，证券代码：835775，股票简称：用尚科技。用尚科技以“品质卓越，效用为尚”为经营理念，自成立至今一直致力于电力企业的信息化建设，为用户提供性能卓越的产品和优质的技术服务。公司紧密跟踪电力行业的技术方向和动态，先后执笔或参与制定了《智能电网调度控制系统调度管理应用（OMS2.0）功能规范》、《变电站监控信息智能管理系统技术规范》、《基于监控数据的变电站设备运行大数据分析功能规范》等多项标准。公司的OMS系统、智能防误操作票系统、变电站三维预警系统等均高质量通过由电力工业电力系统自动化设备质量检验测试中心（中国电力科学研究院）的技术/安全检测。公司研发的基于大数据的变电站监控信息决策分析专家系统、调控智能防误操作系统、基于物联网技术的保护压板状态在线监测系统或是作为成立以来的拳头产品或是针对大运行改革后推出的主打产品已在多个省份部署实施，得到现场用户的好评，全国覆盖用户达十几家省市公司。', 'https://www.zhaopin.com/jobdetail/CC150587510J40752385711.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4304, '技术支持工程师', '南京东送新能源有限公司', '12月19日', '6000-10000元', '南京-江宁区', '新能源', '20-99人', NULL, 'CC633017480J40611094809', '岗位职责：<br>1、负责光伏项目前期的现场踏勘收资、技术评估及相关技术协调工作；<br>2、负责绘制组件布置图、编制项目方案、项目建议书；<br>3、负责为开发人员提供技术支持解答开发过程中业主提出的技术问题；<br>4、负责协助投标人员编写技术标文件；<br>任职要求：<br>1、本科学历，新能源、电力系统、电气工程及其自动化、机械等电气相关专业；<br>2、熟练掌握office办公软件、CAD绘图、PVsyst、meteonorm；<br>3、有光伏从业经验者优先。', NULL, 'https://www.zhaopin.com/jobdetail/CC633017480J40611094809.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4305, 'Java', '石家庄汇控鑫科技有限公司', '4月16日', '7000-14000元', '石家庄-裕华区', '互联网,计算机软件', '20-99人', '不需要融资', 'CCL1296669470J40435718013', '1.负责客户端APP产品中服务器后端的工程设计，架构设计以及开发工作。<br>2、研究业界最新技术及其应用，解决创新研发过程中的关键问题和技术难点。<br>3、根据项目任务计划按时完成软件编码和单元测试工作。<br>4、按照开发流程编写相应模块的设计文档。<br>5、与产品经理、测试工程师、其他团队沟通合作，保证产品研发工作的质量和进度。<br>6、协调或指导团队里其它开发人员的工作。<br>7、一种主流后端语言编程经验：Java，或Scala，或Node.js，或Python。', '一家集实训、研发、人才输出为一体的java开发技术服务公司，长期为多家企业提供Java开发工初程师、中、高级技术人才服务致力于公司在互联网行业发展与创新，并建设性地指导公司工作，保证技术紧跟时代发展，每年更新升级课程内容。', 'https://www.zhaopin.com/jobdetail/CCL1296669470J40435718013.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4306, '测试工程师', '高邮市北方动力机械有限公司', '5月8日', '7000-12000元', '南京-江宁区', '电气机械/电力设备,汽车研发/制造,仪器仪表制造', '100-299人', '未融资', 'CC543017220J40731433409', '1.负责研发阶段整机园林工具产品的负载寿命、实际操作寿命测试和整机功能和性能测试；<br>2.测试方法评估、维护/搭建与方法匹配的测试环境；<br>3.评估审核测试评估数据、测试异常现象和测试结果；<br>4.汇总各阶段测试项的过程数据、异常现象和测试结果，结合测试过程向项目组进行测试过程汇报；<br>5.完成和提交各项目阶段与测试相关的工作输出；<br>要求：<br>1.机械相关专业，机电测试和开发有5年工作经验，有电动工具、园林工具、家用电器等测试工作经验优先；<br>2.能熟练运用各种测试设备，发现设备问题和维护；<br>可以接受省内出差', '北方动力机械有限公司创建于1998年，期初生产替代进口摩托车配件，2010年进入出口园林机械的研发，是国家首批研发园林机械的企业之一，2014年导入新能源汽车车桥的开发与研究，现有园林机械七大类33个规格型号，车桥两大类8大系列20多个品种；拥有20多项具有自主创新的国家专利；多项产品被评定为“江苏省高薪技术”、“国家重点产品”。公司坐落于千年古城高邮，南临文明古今的名城扬州，东倚G2京沪高速路边，据扬州泰州国际机场半小时路程，2018年底连淮扬镇高铁将建成通车，立体交通十分便利。公司先后荣获ISO9001质量管理体系认证，ISO14001：2008环境体系认证，ISO/TS16949认证，被评为国家高薪技术企业，江苏省AAA级信用企业，江苏省安全生产标准化示范企业，扬州市劳动保障诚信示范企业，科技创新企业等，是中国汽车工业协会车桥委员会会员单位。', 'https://www.zhaopin.com/jobdetail/CC543017220J40731433409.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4307, '测试工程师', '宁波察微生物科技有限公司', '2025年07月30日', '6000-10000元', '宁波-慈溪市', '医疗设备/器械', '20-99人', NULL, 'CC840956710J40748974112', '岗位职责：<br>1.负责产品开发过程的调试协助。<br>2.负责产品开发阶段的性能、功能、可靠性验证。<br>负责验证过程中的数据及问题的记录、整理分析及报告的编制。<br>3.负责产品调试过程中仪器操作规程、维护保养规程及整机检验工艺的编制。<br>4.负责测试相关SOP文件的编制、更新、维护。<br>5.完成上级交付的其他工作。<br>岗位任职要求：<br>1.本科及以上学历，计算机相关专业，软件方向，一年以上工作经验，优秀应届生亦可。<br>2.有意向技术类工作方向发展，能接受重复性的工作内容。<br>3.熟练掌握常用测试工具和测试管理工具，能够编写测试脚本。<br>4.具有良好的团队协作能力，较强的自我学习能力。<br>5.可适应出差。<br>', '山东察微生物科技有限公司是一家专业从事集设计、开发、研制、生产、销售各种病理设备为一体的高新技术企业。产品范围涉及自动封片机、全自动组织染色机、染色封片工作站、全自动免疫组化仪、冰冻染色封片工作站、全自动冰冻染色机等。公司一直以“企业的价值蕴于客户的成功之中，企业的成功享于员工价值最佳表现之时”作为我们的经营理念。公司坚持走以质量求生存，以科技求发展的道路，以一流的产品、技术、品质为客户提供专业化、标准化的服务。山东察微打造了一支效率高、责任强的团队，全体职工努力拚搏，积极进取，日积月累的付出取得了丰硕成果。山东察微以先进的设备，卓越的产品性能，稳定可靠的产品质量，及时周到的售后服务，并在友好、平等、诚实、守信和互利的原则下与各界有识之士交流合作，从而共同开拓美好的未来!察微公司生产的自动封片机/自动盖片机产品填补国内空白；察微公司的自动封片机/盖片机产品与德国徕卡比较，察微的产品速度更快、稳定性更好、彩色触摸屏操作更加方便、独有的质量控制系统、完善的售后服务体系；察微公司的自动封片机/盖片机产品与日本樱花比较，察微的产品速度更快、稳定性更好、彩色触摸屏操作更加方便、独有的质量控制系统、没有专用耗材、完善的售后服务体系。察微公司的自动封片机/盖片机产品与美国赛默比较，察微的产品速度更快、稳定性更好、彩色触摸屏操作更加方便、独有的质量控制系统、完善的售后服务体系。察微公司生产的自动封片机/盖片机产品，根据中国市场量身定做，在不失高性能的前提下，采购德国徕卡、日本樱花、美国赛默与采购察微公司的自动封片机/盖片机产品，察微能给购买科室节省采购费用；察微公司的自动封片机产品封片速度更快、处理任务能力更强，大大提高使用科室的工作效率，节省人力；察微公司的自动封片机工作重复性和稳定性很棒，有效避免人工盖片才生的不稳定导致重复性工作；察微公司的自动封片机产品具有高效的二甲苯抽排处理系统，为使用者创造良好的工作环境，避免使用者接触二甲苯，减少对人体的危害。', 'https://www.zhaopin.com/jobdetail/CC840956710J40748974112.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4308, '硬件测试', '宁波中嘉科贸有限公司', '5月9日', '8000-10000元', '东莞-None', '计算机硬件,零售/批发', '1000-9999人', '未融资', 'CC131606690J40671737206', '岗位职责：<br>1.熟悉VBIOS、Function、Driver/周边产品相关测试； 2.负责产品兼容性及稳定性实验；', '宁波中嘉科贸有限公司是台北技嘉科技股份有限公司于2003年6月在大陆成立的一家子公司，主要自营各类商品/技术的进出口等。技嘉简介全球科技领导品牌─技嘉科技 GIGABYTE，致力于「创新科技，美化人生 Upgrade Your Life」的企业使命，经营范围涵盖家用、商用、电竞、云端等多元科技领域。技嘉以持续前进的品牌动能，掌握众多突破性的专利技术，并结合 5G、AI、AIoT布局云端智能，积极打造高效能、高质量与超耐久的科技解决方案。同时，我们坚守回馈和关怀社会的经营理念，链结永续发展目标，矢志为全人类带来更美好的生活。经营理念创新科技，美化人生(Upgrade Your Life)主要商品/服务项目从一片主板开始，逐步拓展到显示适配器、计算机周边、笔电；并以恒久稳定的储存装置、服务器，协助全球各大企业完善企业解决方案；同时为人工智能、深度学习等前瞻性科技，提供丰厚的发展基础。我们持续与消费者深入对话，针对特殊需求量身打造：挑战感官激情的顶级电竞品牌─ AORUS，职人指定使用的专业笔电─ AERO系列，以及性能强悍又体积轻巧的超威型计算机─ BRIX。技嘉以创新技术研发出质量稳固的产品，多元产品满足全面需求。声明：鉴于目前在全国范围内出现假冒技嘉科技、宁波中嘉科贸有限公司的名义进行招聘的行为，为保证广大应聘者的合法权益，如您接到以我司名义发出的面试邀请、培训要求等情况，请务必至官网或大型招聘网站（如51job、智联招聘网）确认岗位名称及联络方式，如有疑问欢迎来电&Email咨询。以上信息特予以声明！', 'https://www.zhaopin.com/jobdetail/CC131606690J40671737206.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4309, '测试工程师', '福建富昌维控电子科技股份有限公司', '5月6日', '5000-10000元', '福州-马尾区', '仪器仪表制造,互联网,仪器仪表制造,物联网', '300-499人', '未融资', 'CC291402110J40744162110', '岗位职责： 1、根据测试大纲完成产品的性能测试、可靠性测试，测试后报告的撰写，对测试结果进行分析，测试问题的跟踪。 <br>2、负责新部品的性能测试、可用性测试，输出测试报告。 <br>3、协助研发人员完善测试标准和规范，对测试工作有自己见解和想法。 <br>', '福建富昌维控电子科技股份有限公司是一家专业从事先进制造和自动化领域产品研究、开发与销售的国家高新技术企业。维控自主研发的主要产品有：人机界面(HMI)、可编程逻辑控制器(PLC)、维控慧网(V-NET)和企智云(V-IEC)、智能网关产品慧盒(V-B0X)、伺服驱动器、运动控制系统、视觉控制系统等，产品广泛应用于装备制造业、农业养殖、节能环保、新能源等领域，为客户提供专用控制、工业物联网解决方案。维控总部位于福州市马尾区维控科技园，近600名年轻、充满激情的职工在这里工作。维控凭借其创新技术、持续改良的产品和服务，销售网络遍布全球。在国内主要工业城市设有四十余个办事处，为各地代理商和客户提供产品销售和技术支持服务。同时，维控产品远销八十多个国家，在意大利、巴西、土耳其、印度、巴基斯坦等四十余个国家设有代理商，为产品提供全球联保服务。维控经过多年努力，已获得业内肯定，拥有《福建省科技型企业》、《福建省“专精特新”中小企业》、《国家高新技术企业》等荣誉称号同时，公司已通过ISO9001质量管理体系认证，所有产品均通过CE认证(欧盟安全）截止到2025年4月份，公司拥有169项核心自主知识产权，其中发明专利14项，实用新型专利28项，外观专利9项，软件著作权118项。', 'https://www.zhaopin.com/jobdetail/CC291402110J40744162110.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4310, '软件测试', '重庆科满福人力资源服务有限公司', '6月29日', '6000-10000元', '郑州-中原区', '企业服务', '20-99人', NULL, 'CCL1487604860J40925301104', '【岗位职责】：<br>1、软件测试岗位职责 <br>2、接受测试任务，进行需求分析<br>3、按照测试计划搭建测试环境，并保证测试环境的可靠性<br>4、按照测试计划编亏测试用例，保证测试用例合理有效<br>5、按照测试用例执行测试，及时发现缺陷，并使用工具进行管理缺陷<br>6、编写和提交测试报告，保证测试进度按计划完成<br>7、参与审核其他测试工程师的测试用例和报告<br>8、学习公司已有方案和推广使用新的测试技术和工具<br>', NULL, 'https://www.zhaopin.com/jobdetail/CCL1487604860J40925301104.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4311, 'Java', '外企德科数字技术有限公司', '2025-07-27 00:26:01', '1.5-3万·14薪', '南京-雨花台区', '专业技术服务', '10000人以上', NULL, 'CCL1480117890J40794008505', '岗位优势：<br>1、导师制培训机制，新人入职至少半年以上会有导师一对一辅导开展工作和学习。<br>2、部门：ICT（公开、光、计算、无线、数存等）、云、2012（中硬、中软、中媒）、消费者BG、BPIT、上海海思、Carbu（智能汽车）、数字能源等<br>3、主要地点：<br>十大研究所（北京、上海、东莞、深圳、杭州、南京、苏州、武汉、西安、成都）<br>三大办事处（广州、长沙、济南）<br>基本要求：<br>1、熟悉掌握C/C++/python/JAVA/go/JS等语言开发；<br>2、熟悉一种以上脚本语言，shell、python等；<br>3、掌握常用的数据结构、数据算法；<br>4、良好的表达能力，钻研精神、注重团队协作。<br>公司福利：<br>1、入职缴纳五险一金+商业险，全额缴纳社保公积金，试用期薪资全额发放不打折。<br>2、上下班班车接送<br>3、良好的团队氛围、首屈一指的技术大拿带教，成长性max<br>4、过节福利优厚，包括但不限于（过节费、节日礼盒、年终奖、福利活动、部门定期团建等）', '外企德科数字技术有限公司是一家2023年新成立的中外合资企业。成立于2023年11月24日，公司定位：专注于为信息技术企业提供人才及数字技术外包解决方案的中外合资企业。它是由中国人力资源服务行业的FESCO（北京国际人力资本集团）与全球人力资源服务领导者The Adecco Group（德科集团）合资成立的。公司主要提供网络技术服务、软件外包服务、计算机系统服务、技术进出口、软件开发等信息技术相关服务。专注于为信息技术企业提供信息技术类人才及数字技术外包解决方案。', 'https://www.zhaopin.com/jobdetail/CCL1480117890J40794008505.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4312, '测试工程师', '贵州振华群英电器有限公司(国营第八九一厂)', '7月5日', '8000-12000元', '贵阳-乌当区', '船舶/航空/航天/火车制造', '500-999人', NULL, 'CC218626220J40714689602', '一、主要岗位职责<br>1、负责例行试验、周期检验、委托试验、摸底验证试验、第三方鉴定试验、极限评估试验、第三方性能验证试验、市场专项验证试验、科研新品试验、检验试验有效性研究验证、应用验证实施。<br>2、负责全厂的J品、新品检验大纲的编制，负责试验过程和认可实验室的技术指导工作，负责开展相关工艺验证、质量提升、应用验证项目策划和实施。负责例行试验、周期试验、维持试验、可靠性试验报告的审核等工作，确保交付产品质量满足用户要求。', '贵州振华群英电器有限公司始建于1966年，隶属中国振华（集团）科技股份公司，现有员工800余人，是微型密封电磁继电器和用接触器研制、生产的骨干企业和定点厂家。企业产品广泛应用于电动汽车、充电设施、光伏电站等新能源领域。研制的产品包含电磁继电器、接触器、电磁锁控装置、固体继电器、控制组件等，产品发展方向为研制可靠继电器、智能控制器及机电组件。研发涉及电磁、热、力学、电路仿真设计技术和CAD/CAM计算机辅助技术。企业的研发中心为省级技术中心，2010年起与哈尔滨工业大学联合组建了贵阳研发中心（地址：贵阳市乌当区083基地），2015年成立了北京研发中心（地址：北京市定慧西里甲18号），2016年成立了西安研发中心（地址：西安市中国电子西安产业园）。企业将进一步强化创新管理，不拘一格引进各类高端人才，不断完善以业绩为导向的绩效考核机制和按劳计酬的薪酬体系平台，持续推进精益六西格玛、燎原创新管理工作，通过规范高效的运营机制，更好促进企业与员工的共同成长。', 'https://www.zhaopin.com/jobdetail/CC218626220J40714689602.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4313, 'C/C++', '成都瑞戈科技有限公司', '5月12日', '7000-10000元·14薪', '成都-大邑县', '专用设备制造,工业自动化,专用设备制造,通用设备制造', '20-99人', '未融资', 'CC444751580J40833758315', '岗位职责<br>1、协作机器人应用调试，结合3D相机数据、运动学算法、机器人轨迹规划，力闭环控制等，实现机器人特定功能控制；<br>２、针对汽车零部件环境耐久试验、疲劳试验、泥水试验、性能检测等试验设备编程，通常下位机为Beckhoff系统，使用ST编写实时程序，上位机使用LabView或VS编写，实现各试验信号采集，实现力闭环、位移闭环等伺服控制，上位机对试验信号曲线展示，数据保存；<br>３、对核心代码进行维护、改进完善，以满足新需求；<br>４、参与技术攻关，解决技术问题，如路谱信号迭代复现，多耦合系统解耦控制，真实复现汽车零部件运动及受力。<br>任职资格<br>1、本科以上学历，软件工程、机械电子工程、自动控制等相关专业；<br>2、熟练掌控C/C++，LabView或ST语言；<br>3、数学功底扎实，熟悉自动控制原理，熟悉信号采集（力、位移、加速度、温湿度、压力、流量等）；<br>4、有实际工作经验优先，有严密的逻辑思维能力；<br>5、能承受工作压力，有责任心和上进心。<br>', '成都瑞戈科技有限公司是一家高端非标设备服务提供商，从事专用试验设备，自动化生产设备，检测设备的设计，制作，以及工装，夹具，模具，检具等工艺装备的设计及制造，并提供非标设备相关的服务。公司位于成都市大邑沙渠工业园区，拥有1500㎡的厂房及精良的设备。我们资深的设计及生产制作团队将为您提供卓越的装备服务。', 'https://www.zhaopin.com/jobdetail/CC444751580J40833758315.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4314, '科研人员', '厦门通灵生物医药科技股份有限公司', '7月29日', '2-3万·13薪', '厦门-海沧区', '医疗设备/器械,化学原料/化学制品', '100-299人', '未融资', 'CC621509430J40615630005', '岗位职责：<br>1、负责承担罕见基突变因、融合基因、免疫组化等检测系统的技术路线选择及体系设计与优化；<br>2、负责领导项目研发组成员技术对临床标本进行检测并准确分析结果；<br>3、负责新检测项目、新技术与新平台的验证与检测体系建立；<br>4、完成上级安排的其他工作。<br>任职要求：<br>1、博士学历，病理学、医学检验、医学遗传、生化免疫或生物学等相关专业；<br>2、具免疫组化科研或人体病理学研究工作经验优先；<br>3、有丰富的操作经验，具备较强动手能力、分析问题能力和解决问题能力者优先；<br>4、有较强科研精神，较强的责任心、细致耐心、善于沟通和团队合作。<br>5、拥有良好的职业道德及敬业精神，旺盛的事业心，愿与企业长期共同发展。', '厦门通灵生物医药科技有限公司由福建省科技创业领军人才和厦门“双百计划”领军型(A+)人才郭金灿博士于2017年回国创办，现已发展成集研发、生产和销售于一体的病理诊断高科技企业。经过多年的努力，通灵生物形成了以免疫组化为优势的多系列病理诊断产品线，其中葡萄串式多聚物酶标技术打破国际垄断，为全球客户提供性能卓越的二抗试剂。高通量全自动免疫组化染色机及配套检测试剂已获得国内外17项发明专利。独家采用竖片摆放、热蒸汽抗原修复及多通道加样机制，实现了144高通量检测，具有“多、快、好、省”等特点。通灵生物依托强大的研发实力，已开发超过500种一抗试剂，充分满足常规诊断、科学研究和药企合作需求。截至目前，通灵生物已先后荣获国家高新技术企业、国家“专精特新”科技小巨人企业、科技部创业领军人才企业、福建省引进高层次人才企业、厦门市‘双百计划’领军型人才创业企业、厦门市纳税先进企业、全国科技创新大赛厦门赛区第一名、厦门科技创新一等奖、厦门科技进步二等奖、厦门市专利奖二等奖等多项荣誉称号。', 'https://www.zhaopin.com/jobdetail/CC621509430J40615630005.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4315, '技术支持工程师', '湖南精循科技有限责任公司', '7月29日', '8000-12000元', '长沙-岳麓区', '通信/网络设备', '20-99人', NULL, 'CCL1497255050J40777257607', '岗位职责： 1、技术支持和客户服务 2、软件培训和演示 3、项目方案设计与实施 4、市场与产品支持 5、跨部门协作 岗位要求： 任职要求 学历：光学工程、物理、光电信息等相关专业本科及以上学历。 经验： 熟悉光学设计软件（如Zemax、CodeV、LightTools、VirtualLab等），有实际项目经验者优先。 了解几何光学、物理光学、像差理论、激光光学等基础知识。 技能： 熟练使用Python/Matlab进行光学数据处理或自动化优化。 具备良好的沟通能力，能清晰地向客户解释技术问题。', NULL, 'https://www.zhaopin.com/jobdetail/CCL1497255050J40777257607.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4316, '软件测试', '大连创升科技有限公司', '7月18日', '3000-4000元', '大连-沙河口区', '互联网', '100-299人', NULL, 'CC378036630J40922529304', '主要职责：<br>1.、负责测试、调整、发布API接口&amp;网爬相关代码（重点看此能力）<br>2、了解经销商数据库环境、了解经销商/商务意见、为经销商/商务解答疑问等<br>3、统计并记录经销商对接信息<br>4、配合主管优化运营流程，提升运营效能<br>5、完成上级交办的其他任务<br> <br>任职要求：<br> <br>1. 计算机相关专业（专业是信息管理等涉及数据算法等最佳），大专以上学历<br>2. 掌握Windows、Linux、Unix等主流操作系统基本使用；<br>3. 熟悉Sql server 、Oracle、Mysql等数据库的基本操作；熟悉数据库表关联，可熟练编写数据库查询语句；<br>4. 同时掌握Python、C#开发语言，并能完成简单的代码测试以及BUG修改。<br>此两语言不擅长的话，具备做接口开发能力者也可以。<br>5. 富有责任心、创新精神和团队合作精神，能够承受相应工作压力，工作积极主动；<br>思路清晰，具有独立解决问题的能力。<br> <br>行业背景：医药行业工作背景与计算机相关工作背景优先', '大连创升科技有限公司于2016年成立于浪漫之都大连，注册资本200万人民币。拥有办公区2000平方米，位于高新区三丰大厦创升科技自成立7年以来，不断深耕与突破，开拓多类型IT服务模式，跨多行业领域，为客户提供高效、个性化的IT服务;作为一家具有专业开发团队的科技公司，创升自主开发多种服务平台产品，包括自动化测试平台、招聘管理系统、餐饮一体化系统等。以大连为核心，服务范围覆盖全国多个城市', 'https://www.zhaopin.com/jobdetail/CC378036630J40922529304.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4317, '实施工程师', '青岛安然物联网科技有限公司', '7月24日', '9000-18000元', '咸宁-嘉鱼县', '物联网,物联网', '20-99人', '未融资', 'CC559764920J40823800904', '需要弱电技术、自动化、安防系统、工业互联网+危化安全生产、物联网人才，不要纯软件人才。  你能经常到全国各地出差吗？你能到工业生产现场生产现场做技术支持吗？  <br>真正的奋斗者在安然会有让人值得为之奋斗的事业，会有充实、高效的成长，会有高人一等的收入。  <br>你能做好售前技术支持、根据客户需求，高效制作方案吗？你能做好售中技术支持、指导他人正确安装、部署、调试系统向用户保质保量快速交付吗？你能做好售后维护，高效沟通和落实客户需求吗？  <br>迄今已服务中石化、中石油、延长石油、国能、兖矿、京能、索普、新安、奇美、昊源、潞安、旭阳、垦利、逸盛、海科、酒钢、金发等几百家石化、化工、选煤、钢铁、电厂企业。\n  <br>安然以客户为中心，以强者为本，抬头乐干，愿意与同道中人联合、链接，携手共建、共用、共享生产安全命运共同体，一起干，一起干，让优秀企业更安全，让优秀企业更高效！', '基于精准人员定位的工业安全生产信息化管理专家，安全生产信息化管理引领者！作为全国实时定位技术标准工作组成员和应急管理部“工业互联网+危化安全生产”人员定位系统技术支持机构，安然从2012年起致力于基于ZigBee Plus三维立体按需精准定位的“工业互联网+安全生产”的研究，获得了20多项安全智能管控系统发明专利和著作权，持续引领中国化工行业生产现场智慧安全！安然以“准、稳、狠”的ZigBee Plus三维立体按需精准人员定位统和“底数清、数据准、情况明、研判准、措施实”的安全生产信息化平台为核心，整合访客管理、出入口控制、人脸识别、视频监控、语音广播、重大危险源监控、可燃有毒气体监测等系统，对生产现场人、机、料、法、环五大要素进行实时、动态、智能管控和预警，规范人的安全行为，保障人的生命安全，有效防范风险、主动化解风险，实现智慧安全。安然“以用为本”，把安全生产信息化建设与公司管理体系“深度融合”，把安全生产信息化建设与日常工作“紧密结合”，对安全生产切实“有用、实用、好用”，避免建用“两张皮”，让安全管控更智能，让生产更高效才实用。迄今已服务中石化、中石油、延长石油、国能、兖矿、京能、索普、新安、奇美、昊源、潞安、旭阳、垦利、逸盛、海科、酒钢、金发等几百家石化、化工、选煤、钢铁、电厂企业。安然以客户为中心，以强者为本，抬头乐干，愿意与同道中人联合、链接，携手共建、共用、共享生产安全命运共同体，一起干，一起干，让优秀企业更安全，让优秀企业更高效！', 'https://www.zhaopin.com/jobdetail/CC559764920J40823800904.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4318, '软件测试', '天津挚云数字科技有限公司', '7月24日', '150-200元/天', '天津-河东区', '计算机软件,计算机软件,IT服务', '20-99人', '不需要融资', 'CCL1355530700J40584897110', '1. 编写、执行测试用例，确保软件质量。<br>2. 跟踪、管理缺陷，确保缺陷得到修复。<br>3. 参与需求评审、设计评审，提前发现潜在问题。<br>4. 编写测试报告，总结测试成果。<br>5. 与开发团队紧密合作，共同推进项目进度。<br>感兴趣联系我，欢迎加入我们的团队！', '天津挚云数字科技有限公司（简称：挚云数科）于2020年4月成立，注册资本金1000万元，是行业领先的供应链金融科技解决方案提供商，天津市商业保理协会副会长单位。挚云数科专注于为保理公司提供最专业、最高效的供应链金融科技系统与运营服务，同时服务包括实体企业、第三方机构及金融机构在内的参与各方，致力于构建覆盖供应链金融全流程的生态系统。', 'https://www.zhaopin.com/jobdetail/CCL1355530700J40584897110.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4319, '硬件测试', '新能动力', '7月9日', '9000-16000元', '无锡-锡山区', '电力/水利/热力/燃气,电力/水利/热力/燃气', '100-299人', 'C轮', 'CC175513320J40619465309', '岗位职责：<br>1、对产品（或样机）进行过程测试，记录相关测试数据，并定期汇总<br>2、负责产品测试环节，对存在的或潜在的质量问题，提出纠正和预防措施<br>3、针对发现的不合格品，提出初步的处理意见，并跟踪质量改进和关闭质量问题，确保符合相应的质量标准<br>4、协助处理售后反馈的质量问题<br>5、熟练使用万用表，示波器，电能质量分析仪等检测仪器<br>6、熟悉常用的电器元件，对样品物料可以根据产品手册进行样品检测，并生成检测报告<br>7、需要适应短时出差工作<br>8、熟悉电气原理图，能根据电气原理图发现产品问题，并解决问题', '简介新能动力（北京）电气科技有限公司位于中关村高科技园区，是国家高新技术企业，从事电力电子及新能源高端装备制造，致力于电能质量治理、电网节能、尖端大型电力电子装备等领域产品的研发、生产、销售与服务。新能动力独到的技术研发能力，赢得了行业内普遍赞誉。产品广泛应用于轧钢、橡胶、冶炼、石油钻采、化工、军工、医药、芯片制造、显示面板、地铁、机场、高速公路、化纤、电网、大型场馆、医院等行业，获得用户高度评价。新能动力在国内有800多家客户，遍及所有省份，拥有多项核心技术，获得包括中国、美国、欧洲、日本、加拿大、南非、埃及、墨西哥等20多项国内外发明专利，通过ISO9001、ISO14001、OHSAS18001等体系认证，产品已通过德国TÜV莱茵认证、欧盟CE认证、金太阳认证、国家电控配电设备质量监督检验中心检测认证、低电压穿越认证等多项国内外权威认证。新能动力坐落于北京的研发中心和制造基地，在全国设有本地化销售体系。不断的创新、一流的客户、优秀的人才为市场提供具有竞争力的选择和价值。', 'https://www.zhaopin.com/jobdetail/CC175513320J40619465309.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4320, '硬件测试', '重庆科满福人力资源服务有限公司', '7月29日', '6000-9000元', '焦作-山阳区', '企业服务', '20-99人', NULL, 'CCL1487604860J40937016804', '【岗位职责】 ：<br>1、进行新产品研发阶段的测试工作<br>2、完成新产品的功能测试、可靠性测试、环境测<br>试、安全测试等技术工作<br>3、制定测试计划，设计测试用例，分析测试数<br>据，编制测试报告<br>4、为其他部门提供技术支持，与其他部门的产品<br>联合测试工作<br>【薪资待遇】：<br>试用期：（试用期5350-转正6500）元/月＋300全勤+（300-800）元/岗位补贴+（1000-1500）元/月绩效+加班费=-6000-9000左右<br>', NULL, 'https://www.zhaopin.com/jobdetail/CCL1487604860J40937016804.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4321, 'Java', '大连同方软银科技股份有限公司', '11月21日', '6000-8000元', '大连-沙河口区', '计算机软件,IT服务', '500-999人', '已上市', 'CC189336910J40669681108', '岗位需要长期出差，一年10个月左右，可接受再投递', '大连同方软银科技股份有限公司成立于2005年，注册资本金5120万元，主要为商业银行、财务公司和其他金融机构提供软件开发、系统测试和人力外包等信息技术服务。公司总部位于大连，在北京、长春、石家庄、上海、杭州、长沙、贵阳等地设有服务机构。全力打造中国具有影响力的商业银行IT服务商。作为一家专业从事金融软件开发的企业，同方软银成立16年以来，已先后为100家以上的客户（主要为国内中小银行）成功实施超过2500个IT建设项目。公司在核心业务和普惠信贷领域一直保持产品领先，目前已全面实现分布式、微服务和国产化技术落地，是国内银行领域的领先厂商之一。公司目前拥有超过1200名专业人员为银行客户提供软件开发与测试服务，平均行业经验超过5年，其中核心团队的行业经验超过20年、骨干团队的行业经验超过10年。公司与多家国内外知名IT企业如民生科技、宇信科技、Oracle、IBM、华为、阿里、腾讯、中兴等保持着良好的伙伴关系，并已开展了多年的卓有成效的合作。同方软银是国家认定的“高新企业”，主要产品包括：核心业务系统、贷款核算平台、信贷管理系统、普惠零售系统、票据管理系统、资金管理系统、柜面交易系统、支付业务系统、中间业务平台、统一报送平台等，已有超过150项软件产品先后取得了软件著作权，并多次获得国家相关奖项。公司已通过了CMMI-5、TMMI-3、ITSS-3、ISO9001、ISO27001、ISO20000、ISO22301、ISO14001、ISO45001、信息安全服务资质-软件安全开发3级、AAA级信用企业等多项体系认证和评级，将公司经营、项目流程控制和质量管理全面纳入国际标准规范的轨道，为客户提供符合国际/国家标准的专业的IT服务。', 'https://www.zhaopin.com/jobdetail/CC189336910J40669681108.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4322, '技术支持工程师', '位来小猎(宁波)信息技术有限公司', '6月30日', '6000-9000元', '西安-莲湖区', '计算机软件,专业技术服务', '100-299人', 'A轮', 'CCL1320375780J40766930407', '职位描述<br>1、负责火山引擎大模型产品的售后服务支持，为客户提供高效优质的服务体验；<br>2、协助客户解决在使用大模型相关产品(方舟/扣子专业版)时遇到的产品咨询、操作指导、异常排查等各类问题；<br>3、收集用户反馈信息，汇总提炼，推动产品不断优化；<br>4、负责快速响应客户问题，针对复杂问题，与技术专家或者研发直接合作，确保问题得到高效解决；<br>5、负责帮助团队沉淀知识库与技术文档，协助管理者推进流程以及工具体系的优化完善。', '位来小猎成立于2018年1月，2019年6月完成A轮融资；聚焦行业精华，利用后发优势，在1年以内成为行业黑马公司。核心团队成员均有十年以上的人力资源经验，具备丰富的人力资源专业知识和项目实践，服务众多500强企业和知名互联网公司。位来小猎掌握专业领域核心资源，团队迅速扩张，以北京为中心，在全国建立了10家分公司及办事处，业务覆盖全国。现有300+名员工，派遣、外包员工10000+名；服务客户包括国家体育总局，百度，网易，物美多点，美团，字节跳动，喜马拉雅，作业帮，得物，VIPKID，瓜子，京东，拼多多，喜茶，中国人保等。位来小猎以互联网为载体，依托于位来小猎平台、微信公众号、入职有赏微信小程序上活跃的海量求职者资源，核心业务包括人才外包、专业招聘、业务外包、转编服务和灵活用工等。服务行业涉及全国各领域，其中包括社交电商，旅游酒店，互联网（教育），新零售，金融和国家单位等。位来小猎以“把求职者的未来当做自己的未来”为核心价值，希望通过我们专业的服务和不懈的努力，帮助求职者找到更合适、更有发展前景的工作，破冰职场迷茫，为未来指引方向。一直以来，位来小猎秉承以专业诚信为核心，在专注人力资源服务的同时，为众多求职者解决就业问题，优质、用心的服务赢得了众多用户的好评与信赖。除此之外，公司还建立了完善的服务体系，为求职者在工作中遇到的所有问题和困难提供指导帮助。我们相信，通过我们的不断努力和追求，一定能够创造我们和求职者更好的未来！', 'https://www.zhaopin.com/jobdetail/CCL1320375780J40766930407.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4323, '科研人员', '广州医科大学', '7月24日', '8000-10000元', '广州-荔湾区', '学术/科研', '1000-9999人', NULL, 'CC260264080J40516966208', '广州医科大学封红亮教授——广东省人民医院王诗镔主任联合招聘科研助理<br>一、PI介绍<br>封红亮，入选广东省重大科技人才计划青年学者，现为广州医科大学附属脑科医院生物节律实验室主任、教授、博士生导师；兼任中国睡眠研究会运动与睡眠健康专委会副主任委员、BMC Medicine等SCI期刊编委等。聚焦睡眠-觉醒昼夜节律新表型及其对神经精神疾病作用和机制研究，主持国家科技创新2030-“脑科学与类脑研究”重大专项（子课题负责人）和国家自然科学基金等纵向课题5项，作为骨干成员参与“十四五”国家重点研发计划“常见多发病防治研究”重点专项1项，近五年以第一或通讯作者（含共同）于Lancet Healthy Longevity、Nature Communications等期刊发表论著15篇，其中，1篇论文被Science的Editors’ Choice收录和编辑述评正面评价，以及Nature出版集团（Nature Portfolio）推荐Highlight（关注度居所有Nat Commun论文前1%），ESI高被引论著论文2篇，被写入睡眠领域实践指南专著。副主编身份编写人民卫生出版社《昼夜节律原理与临床实践》，参编“十四五”普通高等教育研究生规划教材《睡眠医学》和北京大学出版社《睡眠医学》2部教材，撰写昼夜节律睡眠障碍相关章节；获第3届亚洲睡眠医学大会“青年科学家奖”并受邀进行大会报告。<br>王诗镔，副研究员，硕士生导师，广东省人民医院（广东省医学科学院），广东省精神卫生中心公共卫生事业科主任；吉林大学公共卫生学院预防医学学士、医学博士（流行病与卫生统计学），国家公派加拿大萨省大学医学院、公共卫生学院联合培养博士（慢性病与精神卫生），澳门大学健康科学学院博士后研究员（精神卫生）。从事失眠、抑郁、焦虑、认知障碍、严重精神障碍的预防与康复流行病学研究，牵头“健康广东行动（2019-2030年）”心理健康促进行动和社会心理服务体系构建研究。主持国家自然科学基金、广东省医学科研基金项目、广州市科技计划项目、广东省人民医院科技专项等15项，参与国家重点研发计划项目、国家社会科学基金重大项目、省级科研课题20余项。近年发表科技论文118篇（SCI收录97篇，其中一作/通讯51篇）。兼任中国康复医学会精神卫生康复专委会青年工作组副组长，中华医学会精神医学分会社会精神医学学组委员，广东省心理健康协会公共精神卫生专委会副主任委员，广东省卫生信息网络协会智慧心理健康分会会长，广东省预防医学会精神卫生专委会常务委员，广东省中医药学会中医心理学专委会委员，广东省心理健康和精神卫生专家库科普专家，中山大学公共卫生学院和吉林大学公共卫生学院研究生校外行业导师。所在学科为国家“双一流”建设学科、国家临床重点专科，全国排名第六；拥有硕、博士学位授权点和博士后流动站。课题组有完善的科研训练体系、良好的临床和基础研究科研条件、丰富的生物样本资源、扎实的国内外知名团队合作基础以及充足的在研科研经费。拥有多导睡眠监测仪10余台、体动记录仪200余台、动物生物节律采集和分析系统、动物脑电肌电系统、动物精细行为监测系统、多项睡眠节律紊乱造模仪器、多项动物行为学评估平台等生物节律和睡眠神经科学研究的先进平台。此外，配备双光子显微镜、共聚焦显微镜和一系列分子生物学实验设备，为各项实验提供良好条件。所在团队已配备专职科研人员4名，博士后10名，研究生和科研助理20余名，主要来自神经生物学、心理学、生物信息学、临床医学等脑科学相关专业领域。因学科建设及科研工作需要，现招聘科研助理，从事科研项目、基础研究、行政事务等相关工作，具体要求如下：<br>二、招聘岗位：科研助理（3-4名）<br>1、主要工作内容:<br>（1）协助睡眠和昼夜节律相关临床课题的受试者招募。<br>（2）协助科室宣传、文章和课题申报工作。<br>2、招聘条件要求:<br>(1)应届毕业生或年龄不超过35周岁的非应届毕业生，本科及以上学历；<br>(2)精神健康、公共卫生和心理学等领域相关专业<br>(3)有科研训练经验者，可优先考虑<br>(4)有一定的写作和文书能力，熟悉办公室应用软件系统<br>(5)具有强烈的事业心和责任感，办事效率高，能按时完成工作任务，有较强的沟通交流能力和良好的团队合作精神。<br>三、人事与薪酬管理<br>1) 用工形式：劳务派遣制。<br>2) 薪酬待遇：按照研究助理岗位薪酬管理规定执行，薪酬面议；购买“五险一金”、职工意外伤害保险、定期的员工福利。<br>四、联系方式：<br>1、工作地址：广东省广州市荔湾区明心路36号<br>2、工作时间:早9点-12点，下午2点半-6点半，周末休息，按照项目进度自行灵活安排工作<br>3、报名方式:直接投简历即可', NULL, 'https://www.zhaopin.com/jobdetail/CC260264080J40516966208.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4324, '实施工程师', '北京凯隆分析仪器有限公司', '5月27日', '6000-12000元', '北京-通州区', '仪器仪表制造,IT服务,电子/半导体/集成电路', '100-299人', '未融资', 'CC152849920J40052211001', '请注意！不是软件系统！是自动化集成设备的整体方案设计！主要是给客户提供在线分析设备！', '北京凯隆分析仪器有限公司是专业从事在线分析系统的制造商.成立于1993年，至今已有二十八年的历史，所拥有的过程气体在线分析系统产品（称为采样预处理系统），获得了卓越的国际国内声誉，在技术方面遥遥领先。赢得了用户广泛的赞誉。当今已有超过 2000套分析系统安装使用在国内外的各个工业领域内。迄今在中国北京设有研发制造基地、在杭州、成都、鞍山等多个主要城市设有销售与技术服务中心，并拥有研发、生产、销售与服务全方位业务。2008年、2009年2010年连续3年的订单均在每年1亿人民币。北京凯隆分析仪器有限公司总部设在北京的亦庄国家级经济开发区.位于中关村科技园区通州园金桥科技产业基地景盛中街21号，设计，研制,生产一系列采样预处理部件及气体分析系统。分析系统不仅可与磁氧，红外，紫外，热导等在线气体分析仪配套；同时可与在线工业气相色谱，光谱，热值，水中碳烃光学仪器等配套广泛应用石油化工、冶金、电厂、建材，环保等领域。出口产品占整个销售领域30%份额，经常出口提供给世界40多个国家和地区。领先于国内同行业。北京凯隆分析仪器有限公司KALOON Analytical Instruments CO.Ltd', 'https://www.zhaopin.com/jobdetail/CC152849920J40052211001.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4325, 'C/C++', '外企德科数字技术有限公司', '2025-07-27 00:25:59', '1.5-3万', '西安-雁塔区', '专业技术服务', '10000人以上', NULL, 'CCL1480117890J40793540605', '工作内容:<br>1.负责研发领域IT系统技术方案的设计，开发等工作;<br>2.负责项目开发过程中的技术攻关及解决运行中出现的技术问题;<br>3.负责产品核心模块的代码编写和测试;<br>4.负责产品疑难问题的分析和定位。<br>岗位要求:<br>1.热爱编程，基础扎实，熟悉掌握但不限于JAVA/Python/JS/HTML/GO/C/C++/C#等编程语言中的一种或数种，有良好的编程<br>习惯;<br>2.熟悉算法基础<br>3.具备独立工作能力和解决问题的能力、善于沟通、乐于合作、热衷新技术、善于总结分享，喜欢动手实践;', '外企德科数字技术有限公司是一家2023年新成立的中外合资企业。成立于2023年11月24日，公司定位：专注于为信息技术企业提供人才及数字技术外包解决方案的中外合资企业。它是由中国人力资源服务行业的FESCO（北京国际人力资本集团）与全球人力资源服务领导者The Adecco Group（德科集团）合资成立的。公司主要提供网络技术服务、软件外包服务、计算机系统服务、技术进出口、软件开发等信息技术相关服务。专注于为信息技术企业提供信息技术类人才及数字技术外包解决方案。', 'https://www.zhaopin.com/jobdetail/CCL1480117890J40793540605.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4326, '实施工程师', '伯来克科技(北京)有限公司', '7月25日', '7000-9000元', '北京-海淀区', '环保,咨询服务,化工,新能源', '20人以下', '未融资', 'CC557229480J40803553713', '岗位职能：<br>1， 无需坐班，全国范围均可。<br>2，负责项目的售前售后支持工作，协助销售人员深入了解客户需求，通过专业的技术指导，为客户排忧解惑。<br>3， 和公司其他们部门进行沟通和对接，及时准确的掌握项目进展信息；<br>4， 负责项目过程中的技术指导，包括安装指导、培训、过程管理等。<br>5， 售后支持：定期进行回访，解决用户日常使用中的各类问题，完善售后技术资料。<br>任职要求：<br>1、 化学、化工、环保工程、制药工艺、制药工程等相关行业；<br>2、 有责任心，有耐心，能出差，具有独立解决问题的能力；<br>3、 掌握计算机办公软件操作，会使用AUTOCAD软件画图；<br>4、最好有一定的制药化工企业相关经验，了解活性炭技术优先考虑。', '公司成立于2017年，主要从事化工、制药领域的液体脱色及技术服务。公司研发、生产和销售高品质活性碳纤维膜，主要用于化工及制药领域的液体脱色过程及水处理行业COD深度处理，可以降低原材料成本，提高产品收率，改善操作环境，减少固体废弃物，缩短生产周期，减轻劳动强度。目前已经应用于抗生素类、抗病毒类、激素类、解热镇痛类、维生素类、氨基酸、糖、淀粉、农药、精细化工产品、中药、酒类、饮料类等产品。公司产品优势在于可以重复使用，大大减少企业固废，节能减排。', 'https://www.zhaopin.com/jobdetail/CC557229480J40803553713.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4327, 'Java', '中软国际', '7月25日', '面议', '成都-郫都区', '计算机软件,运营商/增值服务', '10000人以上', '已上市', 'CC508620120J40800831312', 'JAVA岗位要求：', '中软国际是行业领先的全球化软件与信息技术服务企业，成立于2000年，为香港主板上市公司（股票代码：00354.HK），拥有中国分支40+、海外分支14个，拥有员工超过9万人，服务覆盖超过40个国家。中软国际应用开发与管理专业沉淀深厚，企业数字化转型的最佳实践和专家人才充沛。公司与华为等战略伙伴一起，构建软件产业互联网平台，领先技术变革，提升产业效率，致力于使能软件企业引领发展，服务制造企业转型升级，为政企客户提供“好、快、多、省”的信息技术服务。中软国际四大业务蓬勃发展：夯实基石业务作为第一增长曲线的地位，确定云智能业务为第二增长曲线，发展鸿蒙生态、解放号为第三增长曲线，推动解放号作为软件产业互联网平台全面升级。公司在云计算、大数据、人工智能、物联网、移动互联网等方面具有丰富的咨询、设计、实施和服务经验，是全球客户数字化转型的共创伙伴。公司长期服务于多家全球500强企业等头部客户和众多高成长潜力客户，覆盖金融、电信、互联网、高科技、政府、制造与流通、交通、能源、教育等行业。公司已连续四年创造超百亿人民币营收，并立志在未来成为全球最优秀IT服务商之一。', 'https://www.zhaopin.com/jobdetail/CC508620120J40800831312.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4328, '技术支持工程师', '上海东证期货有限公司', '4月14日', '1-2万', '上海-黄浦区', '证券/期货', '500-999人', '未融资', 'CC218538310J40649362410', '岗位职责：<br>1、负责大宗商品期现贸易系统的市场推广、客户服务，独立开展市场调研，撰写报告；<br>2、根据公司战略目标，制定并实施软件推广任务；<br>3、深入了解客户需求，提供定制化解决方案；<br>4、定期收集市场信息，分析竞争对手状况，为产品改进提供建议；<br>5、协调内部团队（如技术、客户服务等），确保项目顺利进行；<br>6、参加行业会议和展会，提升公司和技术品牌知名度。<br>任职要求：<br>1、大学本科及以上学历；<br>2、具备出色的沟通能力和谈判技巧；<br>3、熟练掌握办公软件（如MS Office套件）；<br>4、对新兴技术有敏锐的洞察力；<br>5、良好的团队合作精神和服务意识；<br>6、能够适应短期出差；<br>7、1年以上软件推广服务经验，有大宗商品交易系统经验者优先；<br>8、熟悉大宗商品市场运作机制，了解期货与现货贸易流程及风险管理者优先。', '创新点燃激情专业引领未来----------上海东证期货有限公司公司股东：东方证券股份有限公司（以下简称\\\\\"公司\\\\\"）东方证券股份有限公司（以下简称公司）是一家经中国证券监督管理委员会批准设立的综合类证券公司，其前身是于1998年3月9日开业的东方证券有限责任公司，总部设在上海，现有注册资本69.94亿元。公司于2015年3月23日成功登陆上交所（600958），2016年7月8日H股成功发行并上市（03958），成为行业内第五家A+H股上市券商。经过20年的发展，公司从一家仅有586名员工、36家营业网点的证券公司，逐渐壮大为一家总资产达2000亿，净资产超过500亿，员工4000余人、在全国76个城市设有153家分支机构，提供证券、期货、资产管理、理财、投行、投资咨询及证券研究等全方位、一站式专业综合金融服务的上市证券金融控股集团。上海东证期货有限公司（以下简称“东证期货”）上海东证期货有限公司成立于2008年，是一家经中国证券监督管理委员会批准的经营期货业务的综合性公司。东证期货是东方证券股份有限公司全资子公司，注册资本金23亿元人民币，员工600余人。公司主要从事商品期货经纪、金融期货经纪、期货投资咨询、资产管理、基金销售等业务，拥有上海期货交易所、大连商品交易所、郑州商品交易所和上海国际能源交易中心会员资格，是中国金融期货交易所全面结算会员。公司拥有东证润和资本管理有限公司，上海东祺投资管理有限公司和东证期货国际（新加坡）私人有限公司三家全资子公司。东证期货以上海为总部所在地，在大连、长沙、北京、上海、郑州、太原、常州、广州、青岛、宁波、深圳、杭州、西安、厦门、成都、东营、天津、哈尔滨、南宁、重庆、苏州、南通、泉州、汕头、沈阳、无锡、济南等地共设有33家营业部，并在北京、上海、广州、深圳多个经济发达地区拥有139个证券IB分支网点，未来东证期货将形成立足上海、辐射全国的经营网络。自成立以来，东证期货秉承稳健经营、创新发展的宗旨，坚持以金融科技助力衍生品发展为主线，通过大数据、云计算、人工智能、区块链等金融科技手段打造研究和技术两大核心竞争力，坚持市场化、国际化、集团化发展方向，朝着建设一流衍生品服务商的目标继续前行。公司网站：http://www.orientfutures.com', 'https://www.zhaopin.com/jobdetail/CC218538310J40649362410.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4329, 'C/C++', '外企德科数字技术有限公司', '2025-07-27 00:26:04', '1.3-2.6万·14薪', '北京-海淀区', '专业技术服务', '10000人以上', NULL, 'CCL1480117890J40794957805', '全程线上面试，接受无经验<br>国内一线大厂，地点可选择： 北京 上海 南京 杭州 苏州 济南 深圳 东莞 广州 西安 成都 武汉 长沙<br>入职即缴纳六险一金，团建，下午茶，应有尽有，试用期薪资不打折扣！！<br>带教老师一对一指导~基本要求: <br>1、熟练学握C/C++/python/java/go等任意一种开发语言，或者自动化测试也可以的 <br>2、熟悉一种以上脚本语言,shell、python等: <br>3、掌握常用数据结构、常用算法; <br>4、良好的表达能力,钻研精神,注重团队协作,主动担责。 <br>5、统招本科及以上学历,学信网可查 <br>', '外企德科数字技术有限公司是一家2023年新成立的中外合资企业。成立于2023年11月24日，公司定位：专注于为信息技术企业提供人才及数字技术外包解决方案的中外合资企业。它是由中国人力资源服务行业的FESCO（北京国际人力资本集团）与全球人力资源服务领导者The Adecco Group（德科集团）合资成立的。公司主要提供网络技术服务、软件外包服务、计算机系统服务、技术进出口、软件开发等信息技术相关服务。专注于为信息技术企业提供信息技术类人才及数字技术外包解决方案。', 'https://www.zhaopin.com/jobdetail/CCL1480117890J40794957805.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4330, '实施工程师', '中晨高(重庆)科技有限公司', '7月21日', '6000-8000元', '重庆-江北区', '电子商务', '20-99人', NULL, 'CCL1476022970J40696510606', '岗位内容：<br>1. 负责公司产品的规划、设计、安装、调试及优化。<br>2. 解决客户在安装和使用过程中可能出现的技术问题。<br>3. 维护客户关系，了解客户需求并及时响应，并根据客户需求反馈，做出相应调整。<br>任职要求：<br>1. 大学专科学历及以上、计算机、自动化等相关专业优先考虑。<br>2. 熟练掌握网络设备的安装及调试知识。<br>3. 能有效组织和协调团队工作。<br>4. 具备良好的客户服务意识和高度的责任心。   工作时间：朝九晚五、周末双休、节假日正常休息', NULL, 'https://www.zhaopin.com/jobdetail/CCL1476022970J40696510606.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4331, '技术支持工程师', '大益同心(北京)科技发展有限公司', '7月2日', '7000-10000元', '北京-朝阳区', '医疗设备/器械,医疗设备/器械', '20-99人', '未融资', 'CC245943481J00170463311', '职位描述：<br>1、负责为所属区域内的客户提供专业的产品技术支持；<br>2、与客户建立良好的关系推进所属区域的销售工作；<br>3、给客户提供专业的学术支持，帮助医生了解最新的产品知识；<br>5、完成手术跟台工作。<br> <br>任职要求：<br>1、本科学历，视光学、临床医学专业优先；<br>2、良好的学习能力、演讲能力和责任心；<br>3、积极主动，具备较强的团队合作精神；<br>4、可适应出差。<br>', '大益同心（北京）科技发展有限公司潜心于医疗行业的产品营销。包括德国蔡司眼科全系列检查、治疗、手术设备及耗材，外科全系列手术显微镜；德国STORZ设备和手术器械，应用于耳鼻喉、头颈外科、呼吸科，所推广和销售产品均为医疗行业一线品牌，对于产品带来的成效均荣获行业内专家共识和认同，对造福社会和广大患者提供良好的医疗诊断体验。公司秉承“信任是基础，积极是态度，感恩是品质，共赢是目标”的企业核心价值观，践行“凝聚有理想、有愿望的人才，在医疗行业做点实事儿；打造员工为自己做事的平台，成为医疗行业内值得客户信赖的合作伙伴”愿景理念，脚踏实地一步步成为医疗行业的知名企业。公司总部设立在北京，公司拥有强大的三甲医院客户市场资源及国际品牌后盾；为客户提供创新的，有竞争力的医疗解决方案，医疗设备和服务，坚持从服务行业客户需求出发，基于公司十几年营销经验的坚实积累。未来公司会持续开拓创新，致力成为一家国际水平的现代高科技企业。公司福利：六险一金、双休、餐费补助、交通补助、话费补助、高温补贴、业务提成、年假、拓展、出国旅游等，同时公司有健全的晋升和薪酬机制，希望每一位员工都能在公司有一个良好的职业发展。', 'https://www.zhaopin.com/jobdetail/CC245943481J00170463311.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4332, '技术支持工程师', '青岛安然物联网科技有限公司', '7月15日', '8000-14000元', '白银-白银区', '物联网,物联网', '20-99人', '未融资', 'CC559764920J40823511404', '需要弱电技术、自动化、安防系统、工业互联网+危化安全生产、物联网人才，不要纯软件人才。  你能经常到全国各地出差吗？你能到工业生产现场生产现场做技术支持吗？  <br>真正的奋斗者在安然会有让人值得为之奋斗的事业，会有充实、高效的成长，会有高人一等的收入。  <br>你能做好售前技术支持、根据客户需求，高效制作方案吗？你能做好售中技术支持、指导他人正确安装、部署、调试系统向用户保质保量快速交付吗？你能做好售后维护，高效沟通和落实客户需求吗？  <br>迄今已服务中石化、中石油、延长石油、国能、兖矿、京能、索普、新安、奇美、昊源、潞安、旭阳、垦利、逸盛、海科、酒钢、金发等几百家石化、化工、选煤、钢铁、电厂企业。\n  <br>安然以客户为中心，以强者为本，抬头乐干，愿意与同道中人联合、链接，携手共建、共用、共享生产安全命运共同体，一起干，一起干，让优秀企业更安全，让优秀企业更高效！', '基于精准人员定位的工业安全生产信息化管理专家，安全生产信息化管理引领者！作为全国实时定位技术标准工作组成员和应急管理部“工业互联网+危化安全生产”人员定位系统技术支持机构，安然从2012年起致力于基于ZigBee Plus三维立体按需精准定位的“工业互联网+安全生产”的研究，获得了20多项安全智能管控系统发明专利和著作权，持续引领中国化工行业生产现场智慧安全！安然以“准、稳、狠”的ZigBee Plus三维立体按需精准人员定位统和“底数清、数据准、情况明、研判准、措施实”的安全生产信息化平台为核心，整合访客管理、出入口控制、人脸识别、视频监控、语音广播、重大危险源监控、可燃有毒气体监测等系统，对生产现场人、机、料、法、环五大要素进行实时、动态、智能管控和预警，规范人的安全行为，保障人的生命安全，有效防范风险、主动化解风险，实现智慧安全。安然“以用为本”，把安全生产信息化建设与公司管理体系“深度融合”，把安全生产信息化建设与日常工作“紧密结合”，对安全生产切实“有用、实用、好用”，避免建用“两张皮”，让安全管控更智能，让生产更高效才实用。迄今已服务中石化、中石油、延长石油、国能、兖矿、京能、索普、新安、奇美、昊源、潞安、旭阳、垦利、逸盛、海科、酒钢、金发等几百家石化、化工、选煤、钢铁、电厂企业。安然以客户为中心，以强者为本，抬头乐干，愿意与同道中人联合、链接，携手共建、共用、共享生产安全命运共同体，一起干，一起干，让优秀企业更安全，让优秀企业更高效！', 'https://www.zhaopin.com/jobdetail/CC559764920J40823511404.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4333, 'Java', '软通动力信息技术(集团)股份有限公司', '4月18日', '6000-10000元·13薪', '西安-雁塔区', '互联网,IT服务,计算机软件', '10000人以上', 'D轮及以上', 'CC000544460J40704060016', '岗位内容：<br>1. 负责Java应用程序的设计与开发，包括需求分析、系统设计、编码和测试等环节。<br>2. 研究新技术，不断提升开发效率和程序性能。<br>3. 改进现有系统、优化系统资源，提高系统稳定性和可靠性。<br>4. 参与团队内部培训、交流与分享会议，促进整个团队技术水平的提升。<br>任职要求：<br>1. 熟悉Java语言，熟练掌握Spring框架及相关开源技术。<br>2. 具备扎实的计算机基础，熟悉数据结构、算法和网络编程等知识点。<br>3. 具备初步的Web开发经验，熟悉HTML、CSS、JavaScript等前端技术。<br>4. 具有较强的自学能力、问题解决能力和团队协作能力。', '软通动力信息技术（集团）股份有限公司（以下简称“软通动力”）是中国数字技术产品和服务创新领导企业，致力于成为一家具有全球影响力的科技企业，企业数字化转型可信赖合作伙伴。公司2005年成立于北京，多年来始终坚持科技创新，具有软硬全栈的智能技术产品和服务能力，提供软件与数字技术服务、计算产品与数字基础设施、数字能源与智算服务以及国际化服务。目前，公司在10余个重要行业服务超过1100家国内外客户，其中超过230家客户为世界500强或中国500强企业，员工近90000人。软通动力拥有软通咨询、软通金科、软通工业互联、机械革命、软通华方等业务子品牌，并在全球40余个城市布局业务，构建北美、日本、东南亚、中东四大国际交付中心，在北京城市副中心、江苏无锡建设两大智能制造基地。同时，公司前瞻布局智能制造、ICT软硬基础能力和生产力智能化产品，打造产业链闭环。软通动力设立30个能力中心，拥有1个国家级工程实验室，6个省市政府认定的工程、技术实验室及研发中心，1个博士后科研工作站，50+技术合作伙伴的生态合作体系，不断探索前沿技术的巨大商业应用潜力。公司旗下教育品牌软通教育，拥有一家全日制本科学院——郑州西亚斯学院数字技术产业学院；同时在全国合作院校600多所，设有70多个校企联合人才培养基地，通过校企合作、协同育人，为社会培养高素质应用型人才。软通动力先后获得“2023年中国IT服务市场排名TOP 1”、“2024年Q4 PC出货量国内市场份额排名TOP 2”、“2024年中国软件和信息技术服务竞争力百强企业”、“2023年中国信创企业100强”、“2024万得ESG评级（Wind ESG Rating）AA级及信息技术服务行业ESG综合得分排名第一”等荣誉及市场认可，并拥有全球软件工程领域最高级别CMMI V2.0成熟度5级评估认证、国家研发运营一体化（DevOps）三级能力成熟度模型认证、信息技术服务标准（ITSS）运维能力成熟度一级认证等专业资质，支撑公司更优质的服务体系。', 'https://www.zhaopin.com/jobdetail/CC000544460J40704060016.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4334, '科研人员', '四川国软科技集团有限公司', '3月6日', '4000-6000元', '成都-金牛区', 'IT服务,计算机软件,通信/网络设备,电子/半导体/集成电路', '100-299人', '未融资', 'CC219030910J40649406906', '岗位内容：<br>1. 处理部门各项行政，内联外联事宜，进行科研项目的调研、规划和实施，并对项目进行深入分析、总结和评估。<br>2. 编制科研项目相关的研究报告、技术文献、学术论文等。<br>3. 持续掌握行业动态和科技创新情况，推动实验室的技术研发和转化应用。任职要求： <br>1. 具有材料相关学科的学士或以上学历，具备良好英语口语表达能力。 <br>2. 具备较强的逻辑思维和科学素养，熟练使用科研工具和技能，包括文献检索、数据分析等。 <br>3. 具有良好的英语听说读写能力，具备国际交流和合作的能力。', '四川国软科技发展有限责任公司成立于2006年，公司主要从事轨道交通、高端装备、一带一路的智能化和投融建业务。公司以“轨道交通+机器人”为战略方向，以人工智能为核心，综合研究机器视觉、深度学习、物联网、工业4.0等机器智慧应用，重点研制无人驾驶、物流装卸、工程施工、焊接装配、自动检测等智能装备，是集项目研发、设计、集成、投资、运营一体化的新型高科技公司。公司年产值约1.2亿元，总部大厦坐落于成都金牛区金凤凰大道666号66号楼。在北京、兰州、乌鲁木齐、拉萨、非洲、欧洲等地设有分公司或办事处。公司是中国人工智能学会企业会员、中国机器人产业联盟成员单位、四川省软件行业协会副理事长单位，成都市军民融合企业、成都市企业技术中心、成都轨道交通协会理事单位、成都金牛区轨道交通行业十大重点企业、华为ISV独立软件开发商，华为多产品认证服务商；拥有软件著作权和专利百余项；具有电子与智能化工程专业承包贰级资质、建筑智能化系统专项设计乙级资质、国防武器装备科研生产二级资质、涉密信息系统集成乙级资质；具有高新技术企业认证、软件企业认证、CMMI-3软件能力成熟度集成认证、欧洲轨道交通IRIS认证、动车产品供应和服务资格证（Wi-Fi）、ISO 9001质量管理体系认证、ISO 14001环境管理体系认证、ISO 18001职业健康管理体系认证、ISO 27001信息安全管理体系认证、知识产权管理体系认证和AAA信用等级证书等。技术在不断的发展，市场竞争日益激烈。公司坚持以“轨道交通机器人全国第一”为发展目标，建立“奋斗和分享”的企业文化，坚持“以客户为中心，以奋斗者为本，长期坚持艰苦奋斗”的企业宗旨，树立“认真、负责、谦虚、谨慎”的企业形象，为行业客户提供最优秀的机器智慧产品和最完善的技术服务。地址：四川省成都市金牛高新技术产业园区金凤凰大道666号66号楼', 'https://www.zhaopin.com/jobdetail/CC219030910J40649406906.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4335, '实施工程师', '东华医为科技有限公司', '2025-07-27 00:37:01', '7000-12000元', '烟台-芝罘区', 'IT服务,IT服务', '1000-9999人', '未融资', 'CC649781480J40792168605', '1、学习能力强,能较快掌握和应用新技术;', '东华医为科技有限公司（简称东华医为）成立于2012年5月，注册资金5000万，是东华软件股份公司旗下专业服务医疗、卫生等大健康领域IT业务的全资子公司。东华医为现有员工2000余人，其中技术人员占比达到90%，拥有近100项大健康类自主知识产权的软件产品，所覆盖的大健康领域有医疗机构、卫生管理机构、互联网医疗、人工智能、大数据、健康管理等，所涉及的主要业务有IT咨询规划、方案设计、系统集成、软件开发与交付、工程实施与交付、人才培养、售后运维、合作运营等。东华医为现为全国500余家大健康领域的各类用户提供着持续的技术服务，还连续多年蝉联中国十佳医疗行业解决方案商榜首。传承了东华软件医疗卫生事业部近二十年IT业务的东华医为，在高速发展的大健康领域，笃定能大有作为。', 'https://www.zhaopin.com/jobdetail/CC649781480J40792168605.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4336, '硬件测试', '深圳极联信息技术股份有限公司', '7月8日', '6000-11000元', '广州-黄埔区', '计算机软件,互联网', '500-999人', '未融资', 'CC409287530J40761388807', '岗位职责： 负责公司自研安卓系统商显产品的测试工作，在 TV、消费电子、嵌入式设备领域有测试经验者优先； 1、对我司自研硬件平台进行硬件知识学习和消费类电子接口的功能测试和性能测试，例如：HDMI、TYPE C、DP、USB等； 2、根据测试计划搭建和维护测试环境； 3、可以按照测试用例执行测试，输出完成、清晰的测试报告，包含测试用例执行结果、问题记录、测试小结，按照公司规范流程提交缺陷至内部缺陷管理系统。 4、基于产品需求与特性，编写测试用例。 任职要求： 1、学历与专业：大专及以上学历，计算机、电子类等理工科专业优先；； 2、有同类电子产品（如 TV、消费电子、嵌入式设备 ）或安卓商显产品软件测试经验者优先；有HDMI、TYPE C、DP、USB等接口功能和性能测试者优先；有手机app功能测试和性能测试经验的优先； 3、熟悉测试理论，熟悉基于web的网站测试方法和App测试方法； 4、有压力测试、性能测试、安全测试经验者优先； 5、熟悉兼容性测试和APP性能测试； 6、根据平台相关需求写出测试用例； 7、热爱测试工作并具有高度的工作热情和敬业精神，具有良好的团队合作、抗压能力、沟通协调能力，可高效协同研发、产品等团队。', '公司简介深圳极联信息技术股份有限公司是中国领先的IT技术服务供应商，致力于为客户提供全方位、高性价比的综合IT技术服务，公司在北京、广州、上海、武汉、香港设有分公司，挂牌代码681396。极联股份为客户提供战略咨询、IT资源服务、行业解决方案、软件研发外包一体化服务，行业涉及IT互联网、金融、通信、能源、高端制造业、教育、物流、医疗等领域。极联以客户满意为奋斗目标，服务了腾讯、招商银行、中国电子、康佳、飞亚达、西门子等行业品牌企业，并与众多大型品牌企业建立长期伙伴关系，通过提供专业、高效的服务，不断提高服务能力与客户的满意度，赢得客户的好评。公司福利上班时间：周一至周五9：00-18:30，周末双休福利机制：五险一金，下午茶，节假日福利，部门聚餐，公司团建等活动，成熟的晋升机制，调薪机制等。更多福利，等你来挖掘~人才理念以人为本，尊重员工的个性与发展，使员工在平等、竞争、和谐的环境下充分发挥自身的创新能力和潜能，在达成公司发展目标的同时实现个人的理想和奋斗目标公司详情可通过公众号搜索“极联股份”了解更多资质荣誉高新技术企业双软证书 ISO9001认证 AAA资信等级认证广东省守合同重信用企业 42项软件著作权深圳市软件行业协会理事单位、深圳用户体验交互设计协会理事单位国家软件公共服务平台、国家信息产业公共服务平台：2016年度移动应用开发行业企业奖中国工业合作协会、国家信息产业公共服务平台：2017年度中国互联网+应用服务首选品牌奖中国软件行业协会：2018年中国软件行业IT技术服务标杆企业奖中国信息协会：2019中国信息技术服务影响力企业业务范围研发平台包括：Android、iOS、HTML5、小程序、大型web网站系统、ERP、SAP。核心团队有10年的技术外包开发服务经验，极联软件通过严苛的标准筛选优秀的开发团队，采用公司自主积累BMBP管理模式，为客户提供价格更低、质量更好、工期更有保障的开发服务。 IT资源服务是客户将系统开发工程的分工细化，划分为产品规划、需求分析、架构设计、方案制定、编程、测试、集成和维护等多个阶段，再将其中的一个或几个阶段或产品的某个子系统或模板外包给以公司为代表的服务提供商。 IT战略（IT Strategy，ITS）是在诊断和评估企业信息化现状的基础上，制定和调整企业信息化的指导纲领，争取企业以最适合的规模，最适合的成本，去做最适合的信息化工作。', 'https://www.zhaopin.com/jobdetail/CC409287530J40761388807.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4337, '实施工程师', '青岛青禾人造草坪股份有限公司', '7月8日', '6000-7000元', '烟台-福山区', '橡胶和塑料制品,贸易/进出口', '1000-9999人', NULL, 'CC319445710J40787906005', '岗位职责： 1.负责产品需求管理：a.为销售提供技术支持，客户需求对接，理解客户产品/技术相关需求并对接后端部门。b.参与销售过程，协助进行技术产品类分析、设计等，根据需要陪同拜访客户。c.沟通客户反馈，跨部门协调制定产品解决方案，协助销售团队提升产品/技术专业知识。', '公司主要从事人造草坪及人造草丝的研发、生产和销售业务，是全球生产和销售规模世界前列的人造草坪企业。公司坚持在环保健康理念的前提下，持续专注于研发和生产高质量、高标准、高性价比的人造草坪和草丝产品。公司始终秉持着“让运动更精彩，让世界更美丽”的理念，在紧跟市场发展潮流的同时通过自身的研发，不断带动行业新业态、新工艺的发展，目前已成为全球人造草坪行业的领跑者之一。作为首家在越南投资设立生产基地并投入使用的中国人造草坪生产商，公司率先利用当地优势，在扩大产能的同时提高了运营效率，进一步引领了行业发展，行业领先地位越发凸显。公司坚持技术领先发展战略，重视产品创新和技术进步等方面的持续发展；通过对行业发展需求的解读以及行业标准的深入学习，公司积极探索新工艺、新产品并将研发成果快速应用至产品交付。公司目前的草丝版型数量达到50余款，绿色系草坪品类高达100余种，不同颜色组合千余种，能够快速应对日益复杂的市场需求。在传统产品的基础上，公司自主研发出了一系列创新性产品，如高度可回收系列产品Bellin-GRE、适用于强光照区域的高性能产品Bellin-Strength、宠物用抗菌高拔出力产品Bellin-Smart、强降水地区使用的高渗水产品Bellin-flowtech等。公司把创造客户满意的品质作为矢志不渝的追求，依靠持续且丰富的产品开发能力，通过长期、广泛的客户服务与优化积累，建立了遍布美洲、欧洲、亚洲、大洋洲、非洲等100多个国家及地区的销售网络，在全球范围建立起了品牌形象。公司是FIFA（国际足联）全球人造草坪的合格供应商，同时也是FIH（国际曲联）认证生产商和ITF（国际网联）产品认证供应商；在国内，公司被评为省级企业技术中心、进入青岛市工业中小企业“隐形冠军”名单，青禾品牌被认定为山东名牌和中国驰名商标。工作地点：烟台市福山区鸿福街92号', 'https://www.zhaopin.com/jobdetail/CC319445710J40787906005.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4338, '前端开发', '陕西慧云联达企业管理咨询有限公司', '5月8日', '1.5-3万·14薪', '东莞-None', '人力资源服务', '20-99人', '不需要融资', 'CCL1445845820J40769910605', '岗位内容：<br>1. 开发响应式Web页面和功能组件，确保优秀的用户体验<br>2. 与后端开发人员合作，实现应用程序的完整性和可维护性<br>3. 设计和实现复杂的前端UI交互，并在跨浏览器环境中进行测试和故障排除<br>任职要求：<br>1. 精通HTML、CSS和JavaScript，并熟悉至少一种主要的前端框架（如React或Angular）<br>2. 具备良好的沟通能力和团队合作精神，有解决问题的能力和创新思维<br>3. 统招本科及以上学历。', '陕西慧云联达企业管理咨询有限公司成立于2022年9月，是一家集高端猎头服务与专业代理记账报税业务于一体的综合性企业服务提供商。自成立以来，我们秉承“智聚英才，财通未来”的企业理念，致力于为国内外企业客户提供精准高效的人力资源解决方案及一站式财务管理服务，助力企业稳健成长，共创辉煌。', 'https://www.zhaopin.com/jobdetail/CCL1445845820J40769910605.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4339, '技术支持工程师', '上海耀唐科技有限公司', '3月26日', '1.2-2.4万', '北京-海淀区', '计算机软件', '20-99人', NULL, 'CCL1270864680J40356840916', '1、机械设计自动化及相关专业,本科及以上学历;', '上海耀唐科技有限公司是一家专注于为行业客户提供达索系统各领域产品及解决方案的高科技公司，主要涉及汽车、轨道交通、机械、电子、通讯、医疗等各大领域。公司总部位于上海，并在天津、重庆、广州等地设有分支机构。依托达索系统，耀唐科技着力于为客户提供单一项目乃至整个生命周期的解决方案和技术支持，包括咨询、售前及售后技术支持、培训和各种定制化服务，以满足客户不同的需求。', 'https://www.zhaopin.com/jobdetail/CCL1270864680J40356840916.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4340, '软件测试', '外企德科', '2025-07-27 00:17:01', '1.4-2.8万·14薪', '北京-海淀区', '人力资源服务,咨询服务', '1000-9999人', '不需要融资', 'CC138117190J40792683205', '岗位职责:岗位职责：<br>1、熟悉JAVA、C/C++、Python、JS、GO等主流语言 ，或者能转语言的（有导师教）。<br>2、对软件开发、测试、算法有兴趣，对经验无要求，接受考研、考公二战失败。<br>3、注重团队合作，良好的自律性和沟通能力。<br>4、全国有岗，软件开发、测试、算法等各个岗位均有需求，有意向可投递简历。<br>5、统招本科及以上学历，全职不招实习生。<br>薪资待遇：<br>1、薪资范围：对应技术定级D1~D5的薪资范围<br>2、薪资结构：底薪+绩效+奖金<br>3、绩效工资：2k起，A/B两个等级<br>4、加班费结算：非工作日双倍日薪<br>5、其他福利：五险一金以底薪为基数全额缴纳<br>6、年终奖根据绩效：2-4个月', '北京外企德科人力资源服务上海有限公司（FESCO Adecco）：官方网站：http://www.fescoadecco.com/北京外企德科人力资源服务上海有限公司(外企德科 FESCO Adecco)是值得客户信赖的人力资源解决方案提供商和全球合作伙伴，是中国人力资源服务行业最具竞争力和品牌价值的FESCO（北京外企服务集团）与全球人力资源服务行业领航者The Adecco Group（德科集团）于2010年成立的一家中外合资人力资源服务企业，为企业及个人提供业务外包、人事服务、招聘猎头和员工福利等人力资源解决方案。目前，FESCO Adecco在浙江、陕西、重庆、深圳、苏州设立了分支机构，全国服务人数超过200万名，服务客户超20,000家。', 'https://www.zhaopin.com/jobdetail/CC138117190J40792683205.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4341, '测试工程师', '浙江江山变压器股份有限公司', '7月2日', '1-1.8万·14薪', '长沙-岳麓区', '电力/水利/热力/燃气', '300-499人', '未融资', 'CC297958680J40689468806', '岗位职责：  负责新能源领域电力电子类产品测试，指导培训生产工人完成产品的调试测试。', '浙江江山变压器股份有限公司始建于1969年，原国家二级企业，现国家高新技术企业，国家变压器行业协会理事单位，国家级变压器标准化技术委员会委员单位，国家经贸委城乡电网改造首批推荐优强企业，浙江省文明单位，浙江省标准创新型企业，浙江省管理创新试点企业，省级智能工厂，衢州市绿色低碳工厂，江山市工业龙头企业，拥有国家职业技能认证资格，建有国家级技能大师工作室。公司现有员工500余人（其中35%以上员工拥有大专以上学历），年产值6.5亿元，占地面积23万平方米，配套齐全，拥有完备的管理体系，经营发展迅猛。公司以人为本，职场氛围和谐向上，重视人才培养。拥有企业大学，重视培训，鼓励自我提升，提供带薪培训，晋升渠道通畅，有充分的提升发展空间。企业福利：入职缴纳五险、转正即缴公积金、商业保险、高温津贴、节日福利、生日福利、工龄工资、员工子女助学金、年度体检、团建活动、为外地员工提供免费住宿（家电齐全、带免费无线网）、免费工作餐、拥有大专及以上学历或专业技能证书的另行发放学历和专业技能补贴。我公司员工还可享受江山市政府提供的人才奖励政策：1、住房补贴：符合条件，2022年新引进博士，从缴纳社保月份开始计算，补贴4000元/月，共5年。硕士，从缴纳社保月份开始计算，补贴3000元/月，共5年。本科生，从缴纳社保月份开始计算，补贴2000元/月，共5年。大专生，取得初级职称或高级工技能等级，从缴纳社保月份开始计算，补贴1500元/月，共5年。中专学历，取得初级职称或中级工技能等级，从缴纳社保月份开始计算，补贴1000元/月，共5年。2、就业补贴：毕业五年内，签订一年及以上劳动合同，在劳动合同期内专科本科3000元/年、硕士研究生5000元/年、博士研究生10000元/年的就业补贴，就业参保满1年，共3年。3、各类津贴：高级技师、高级工程师10000元/年；技师6000元/年。', 'https://www.zhaopin.com/jobdetail/CC297958680J40689468806.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4342, '测试工程师', '上海微创软件股份有限公司', '7月24日', '5000-6000元', '福州-闽侯县', 'IT服务,计算机软件', '10000人以上', '不需要融资', 'CC000638920J40782335014', '岗位要求：<br>1、统招本科及以上学历；<br>2、熟悉模拟数字电路<br>3、有焊接经验<br>4、有示波器调试测试经验<br>岗位职责：<br>1、设备调试测试<br>2、物料管理<br>3、测试环境搭建<br>4、流程协助<br>5、其他产品开发事项协助等<br>工作时间：9:00-18:30 午休1.5h；周末双休', '上海微创软件股份有限公司2002年由微软与上海市政府共同创办，是微软在华投资的第一家合资公司。微创始终秉承高标准的服务品质与“成就客户”的服务理念，在全球设有20余处交付中心，分布在中国、美国、日本、澳大利亚，凭借在汽车、保险、高科技、金融、互联网等行业的深厚积累和丰富经验，与2500余家企业与政府客户达成了长期、稳定、友好的合作。', 'https://www.zhaopin.com/jobdetail/CC000638920J40782335014.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4343, '科研人员', '深圳市环境科学研究院', '7月22日', '2.2-2.5万', '深圳-罗湖区', '社团/组织/社会保障,环保,学术/科研', '100-299人', NULL, 'CC260684630J40741293012', '岗位职责:从事环境DNA技术研究及在水生态保护中应用相关工作。<br>基本条件：<br>（1）环境科学、生态学、生物学、水生生物学等相关专业博士研究生；<br>（2）研究方向为环境DNA技术研究与应用，有相关项目或研究经验者优先；<br>（3）专业理论知识较强，逻辑思维清晰，具有较强的独立科研能力、良好的团队合作精神和沟通协调能力；', '深圳市环境科学研究院成立于1987年，是深圳经济特区创立初期组建的环境科学研究机构，是直属于深圳市人居环境委员会的事业单位。其主要职能是紧紧围绕深圳城市建设和经济社会发展所面临的生态环境问题，有针对性开展环境生态基础研究和应用技术开发，为环境管理与决策提供科技支撑，为社会环境保护需求提供咨询服务。我院是深圳市高层次科技人员高度密集的科研单位之一。', 'https://www.zhaopin.com/jobdetail/CC260684630J40741293012.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4344, '前端开发', '杭州速客网络服务有限公司', '7月28日', '1.3-1.4万', '宁波-鄞州区', 'IT服务', '20-99人', NULL, 'CC635221330J40797770505', '岗位内容：<br>1. 设计和开发适用于不同设备的易于使用的网站<br>2. 参与产品原型设计和产品需求分析<br>3. 跟进技术趋势及前端开发最佳实践，不断提升团队的技术水平<br>任职要求：<br>1. 两年以上前端开发经验，掌握HTML5/CSS/JavaScript等前端技术和常用框架<br>2. 具备良好的学习能力和解决问题的思维能力，能够配合其他团队成员完成项目工作<br>3. 对新技术有好奇心，并愿意持续学习和提高', NULL, 'https://www.zhaopin.com/jobdetail/CC635221330J40797770505.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4345, 'C/C++', '广东高云半导体科技股份有限公司', '4月7日', '1-2万', '广州-黄埔区', '电子/半导体/集成电路,IT服务,电子/半导体/集成电路', '100-299人', NULL, 'CC246598730J40379321106', '职位描述：     1、现有EDA工具中解析、布局等模块的维护和优化；', '广东高云半导体科技股份有限公司成立于2014年，是一家专业从事现场可编程逻辑器件（FPGA）研发与设计的国产FPGA高科技公司，致力于向客户提供从芯片、EDA开发软件、IP、开发板到整体系统解决方案的一站式服务。经过多年的积累，高云半导体在FPGA芯片架构、SOC芯片设计、FPGA集成EDA开发环境、FPGA通用解决方案等整个生态链均有核心自主知识，以及国内外发明专利。通过最新工艺的选择和设计优化，高云半导体已经取得与现有市场国际巨头同类产品媲美的高质量、高可靠性FPGA产品，并已经在汽车、工业控制、电力、通信、医疗、数据中心等应用领域实现规模量产。目前公司拥有员工200余人，在广州、上海、济南设有研发中心，随着公司业务在国内外市场的快速发展，公司规模一直在持续的扩张中。核心骨干拥有国际著名FPGA公司15年以上实战经验，亲历国内外数代FPGA芯片硬件、EDA软件、IP研发及市场、销售、技术支持等工作，是一支经验丰富、具备持续创新能力的务实团队。公司于2015年一季度规模量产出国内***款产业化的55nm工艺400万门的中密度FPGA芯片，并开放EDA开发软件下载；2016年***季度顺利推出国内首颗55nm嵌入式Flash SRAM的非易失性FPGA芯片；2017年实现FPGA芯片的规模出货；2019年，发布国内***颗FPGA车规芯片，并实现规模量产。立足本土，布局全球市场，截止2021年，高云半导体实现三大系列：小蜜蜂（GW1N）、晨熙（GW2A）、ASSP GoBridge百余款FPGA及专用芯片在全球多个地区的规模量产。总部及分支机构：★广东高云半导体科技股份有限公司（公司总部-广州研发中心）☆山东高云半导体科技有限公司（济南研发中心）☆上海先基半导体科技有限公司（上海研发中心）☆香港高云半导体科技有限公司（香港研发中心）☆北美销售中心（硅谷）☆高云半导体欧洲办事处（英国）', 'https://www.zhaopin.com/jobdetail/CC246598730J40379321106.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4346, '硬件测试', '西安正麦科技有限公司', '7月20日', '6000-11000元', '西安-雁塔区', '计算机软件', '20人以下', NULL, 'CCL1484160000J40579167616', '岗位内容：<br>1. 负责测试流程的设计、建立和落地，包括测试用例编写，测试环境搭建等；<br>2. 进行硬件测试并记录测试相关数据，参与缺陷跟踪和管理；<br>3. 搭建硬件测试平台，提高测试效率和测试覆盖率。<br>任职要求：<br>1. 本科及以上学历，电子工程、自动化或相关专业；<br>2. 具备较强的自我驱动力和学习能力，善于思考和持续改进。', NULL, 'https://www.zhaopin.com/jobdetail/CCL1484160000J40579167616.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4347, '硬件测试', '佛山耀立电气有限公司', '4月1日', '4000-7000元', '佛山-南海区', '电气机械/电力设备,电子/半导体/集成电路', '20-99人', 'A轮', 'CC488656880J40688797416', '岗位职责：<br>1、熟悉各类电子元器件及其性能，执行生产前的来料检验、测试；<br>2、负责电路与仪表仪器等设备的调试工作；<br>3、进行电路板的焊接与测试，并协助产品的装配、调试等工作。<br>任职资格：<br>1、大专及以上学历，电子信息工程、质量管理等相关专业;<br>2、具有半年及以上质量管理相关工作经验，熟悉电路与电子元器件:<br>3、能够使用万用表、示波器等基础检测工具;<br>4、具有 iso90001 质量管理体系认证证书优先；<br>5、责任心强，积极主动，具有良好的沟通表达能力。', '佛山耀立电气有限公司是一家高端智能装备公司，专注于为客户提供机器人智能焊接电源及自动化一站式解决方案。耀立电气基于自主研发的焊接控制算法，打造一系列适用于机器人自动焊接领域的智能硬件设备以及系统，打破了国外品牌在高端焊接装备领域的技术钳制，解决了企业招聘焊接工人难、生产效率低下、人力成本攀升等难题。公司已联合浙江中科院、华南理工大学，设立产学研创新中心，在船舶与海洋工程、海上风力发电、石油天然气管道、大型发电设备等领域进行行业应用研发、技术人才培养及客户技术服务的联合研究开发，助力我国制造业高质量发展。', 'https://www.zhaopin.com/jobdetail/CC488656880J40688797416.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4348, '科研人员', '中国科学院空间应用工程与技术中心', '7月3日', '1.2-2.4万', '北京-海淀区', '电子/半导体/集成电路,计算机硬件,通信/网络设备', '100-299人', NULL, 'CC623720820J40329277108', '职责描述：', '载人航天工程是当今世界高新科技发展水平的集中展示，也是衡量一个国家综合国力的重要标志。1992年我国启动的载人航天工程是继“两弹一星”之后，又一个国家重大科技工程。也是我国航天事业创立以来规模最庞大，系统最复杂，可靠性和安全性要求最高的航天工程。20年来我国载人航天工程坚持高起点、瞄准高目标，用较短的时间突破并掌握了载人航天的多项关键技术，国际影响力不断扩大。作为工程三大发起部门之一——中国科学院在载人航天工程立项之初即牵头负责空间应用系统。1993年中科院党组研究决定组建“中国科学院空间科学与应用总体部”（以下简称总体部）非法人单元，负责空间应用系统工程组织管理及总体技术研究。1993年至2003年，总体部挂靠空间科学与应用研究中心，独立运行。2003年至2010年，总体部挂靠光电研究院，独立运行。20年来，总体部有效组织全国众多承研单位，充分利用“神舟”系列飞船以及“天宫一号”空间实验室的实（试）验支持能力开展了一大批空间科学与应用项目，研制的众多有效载荷产品圆满完成了历次飞行试验任务。同时在地球环境监测、空间天文、空间生命、空间材料、空间环境监测与预报、微重力流体物理等空间科学领域取得一大批具有重大价值的空间科学与应用成果。众多技术与成果在相关业务卫星中得到了推广应用，极大地提升了我国空间科学发展水平，为我国经济建设、科技发展、国家安全、社会进步作出了积极贡献。　2010年11月，中科院党组决定在总体部的基础上成立中国科学院空间应用工程与技术中心（筹）。中心代表中国科学院牵头负责载人航天等重大科技应用系统方面的总体管理和技术集成。具体包括组织协调相关科研力量，开展空间应用系统的战略研究、总体规划、系统总体设计、总体计划与管理、系统总体集成、系统总体测试、总体支撑保障、在轨运行和应用等工作。同时中心还负责协助管理中科院承担的载人航天工程各大系统协作配套任务。　2012年8月，中央机构编制委员会办公室批复同意成立中科院空间应用工程与技术中心，这是我院唯一一个以组织完成国家重大科技专项工程任务而建立的研究所。自成立以来，中心坚持以建设国内一流、国际著名的空间总体机构，建设空间站空间应用系统等重大任务的龙头与核心为目标，坚持统筹工程管理和科学研究的协调发展，着力加强中心战略研究规划、总体设计、总体计划与管理、总体支撑保障等能力建设，努力推进中心跨越发展。根据中心建设发展以及工程任务进展需求，中心设立综合办公室、工程处、科技处、人事教育处、质量标准处、财务处、条件保障处等7个职能管理部门，设立系统工程部、专业技术部、战略发展部、可靠性保障中心4个科研及任务支撑部门。其中系统工程部下设系统设计研究室（并行设计与仿真实验室）、集成测试研究室（空间软件评测中心）、有效载荷运控中心；专业技术部下设电子信息技术研究室、结构热控技术研究室、综合保障技术研究室；战略发展部下设战略规划研究室、空间探索研究室、数据利用中心。截至2013年2月，中心共有在职职工186名，其中中国科学院院士1名、正高级专业技术人员25名，副高级专业技术人员70名。在职职工中共有中共党员89名。共有在读研究生67名，其中博士生12名，硕士生55名。目前，中心已获得信息与通信工程、计算机科学与技术、航空宇航科学与3个硕士学位授权一级学科培养点和计算机技术、电子与通信工程2个全日制工程硕士专业学位培养点。拥有计算机科学与技术、信息与通信工程2个博士招生专业。　20载凝聚辉煌，空间应用中心（总体部）自成立以来，获国家科技进步特等奖1项、一等奖1项，全军武器装备科技进步一等奖4项、二等奖15项、三等奖7项。1次被授予全国五一劳动奖状，1次被授予“中国青年五四奖章集体”，2次被表彰为载人航天突出贡献集体。共有5人获全国五一劳动奖章，1人获中国青年五四奖章，29人次获“载人航天突出贡献个人”荣誉称号，3人获曾宪梓载人航天基金奖。当前中心正处在科学院落实“创新2020”发展战略、“一三五”规划和载人航天工程空间站计划全面实施的关键时期，中心将将紧紧抓住新的发展机遇，以院党组确定的中心定位为核心，以落实院“一三五”规划为指导，以完成载人航天任务为根本，以作出“三性”贡献，成为不可替代的总体单位和实现中心可持续发展为总目标，切实履行好职责，尽心竭力，攻坚克难，以实际行动实现中心更深、更远、更高的发展。', 'https://www.zhaopin.com/jobdetail/CC623720820J40329277108.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4349, '测试工程师', '陕西益信伟创智能科技有限公司', '7月24日', '4000-6000元·13薪', '渭南-临渭区', '船舶/航空/航天/火车制造,船舶/航空/航天/火车制造', '20-99人', '未融资', 'CC840692900J40110854804', ' 学历要求：专科及以上学历', '陕西益信伟创智能科技有限公司成立于2017年1月，注册资本2000万元，位于西安市高新区研祥城市广场，专业从事高效换热器、热管理系统研发设计、生产和销售及相关技术服务。公司拥有一支专业化高素质的研发团队，研发人员30余人，均为硕士及以上学历。公司自成立以来一直专注于军工领域的科技创新，基于仿生设计理念，应用超精加工技术手段，为解决航空、航天、电子等军工领域的微小空间散热、微纳防冰设计、超精接触表面设计等工程技术问题提供高结构可靠性系统解决方案。目前所设计开发的仿生换热器系列产品具有轻量化、耐高温高压、结构紧凑、低压损等特点，符合航空航天先进装备的应用需求，相关产品技术已经申请了20余项国家专利。公司具有换热器的设计开发能力，储备了丰富的超精加工工艺技术、配套生产设备和相关领域优质合作伙伴，建立了试验测试中心，可以根据用户的需求提供换热组件以及热管理系统的研发设计、生产及相关技术服务。公司在创业过程中坚持“精益求精、信守承诺、持续创新”的经营理念，践行工匠精神，目标成为国内热管理系统设计和制造的领军企业，为航空、航天、电子等国防事业发展提供技术产品支撑，引领行业的技术创新和产品升级换代，推动科学技术的创新发展与军民融合。', 'https://www.zhaopin.com/jobdetail/CC840692900J40110854804.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4350, '硬件测试', '陕西跃北机电设备有限公司', '7月22日', '7000-8000元', '西安-未央区', '人工智能', '500-999人', NULL, 'CCL1500059560J40760907211', '我们正在寻找一位资深的硬件测试工程师，<br>负责确保公司硬件产品的质量和稳定性。<br>工作内容：<br>包括设计测试方案、执行测试、撰写测试报告、跟踪缺陷等。<br>岗位要求：<br>1. 电子、通信、计算机等相关专业大专及以上学历；<br>2. 有以上硬件测试工作经验；<br>3. 熟练掌握各种测试仪器和设备；<br>4. 良好的问题定位和解决能力；<br>5. 责任心强，有团队精神。', NULL, 'https://www.zhaopin.com/jobdetail/CCL1500059560J40760907211.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4351, '实施工程师', '东华医为科技有限公司', '2025-07-27 00:34:20', '5000-8000元', '丽江-None', 'IT服务,IT服务', '1000-9999人', '未融资', 'CC649781480J40505025005', '工作职责: 主要参与项目的实施交付运维包括但不限于;1、负责客户项目的软件接口调试工作; 2、解答系统用户操作问题;维护信息管理系统(包括操作系统、中间件、数据库的日常巡检) ;系统日常故障排除(参 与IT日常任务响应，及时排除正在使用中的系统故障) ;系统数据梳理及维护，系统巡检和监控; 3、负责初始化数据收集、整理及导入工作;协助开发人员定位和解决系统问题 4、负责编制部分项目资料文档; 5、负责售后问题处理、用户培训。 任职要求: 1.本科及以上学历，计算机或软件设计相关专业优先; 2.熟练excel,有使用excel整理千万及数据或实施运维过资产管理系统经验者优先; 3.熟练掌握MySq|、ORACLE等数据库开发技术，可编写复杂SQL语句，熟悉SQL性能优化; 4.熟悉使用Kafka/Rabbitmq等常用消息中间件，并了解其工作原理; 5.熟悉L inux操作系统，熟悉ShelI脚Unix管理命令; 6.了解webservice，会使用postman等工具做接口联调测试。 7.思路清晰,头脑灵活能独立分析并解决复杂的线上问题; 8、有一定的文档编辑能力; 9、有良好的沟通表达能力及团队协作意识、可短期出差者优先。 职位福利:年终奖、带薪年假、周末双休、五险一金职位亮点:五险一金', '东华医为科技有限公司（简称东华医为）成立于2012年5月，注册资金5000万，是东华软件股份公司旗下专业服务医疗、卫生等大健康领域IT业务的全资子公司。东华医为现有员工2000余人，其中技术人员占比达到90%，拥有近100项大健康类自主知识产权的软件产品，所覆盖的大健康领域有医疗机构、卫生管理机构、互联网医疗、人工智能、大数据、健康管理等，所涉及的主要业务有IT咨询规划、方案设计、系统集成、软件开发与交付、工程实施与交付、人才培养、售后运维、合作运营等。东华医为现为全国500余家大健康领域的各类用户提供着持续的技术服务，还连续多年蝉联中国十佳医疗行业解决方案商榜首。传承了东华软件医疗卫生事业部近二十年IT业务的东华医为，在高速发展的大健康领域，笃定能大有作为。', 'https://www.zhaopin.com/jobdetail/CC649781480J40505025005.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4352, '科研人员', '浙江大学', '2月25日', '4.5-5.5万', '杭州-萧山区', '学校/学历教育,学术/科研,社团/组织/社会保障,科学技术推广', '1000-9999人', NULL, 'CC199796410J40869848704', '浙江大学杭州国际科创中心高纯分离团队诚聘“百人计划”研究员<br>浙江大学杭州国际科创中心（简称科创中心）成立于2019年2月28日，是新时代杭州市和浙江大学全面深化市校合作共建的重大创新平台，位于杭州市萧山区。科创中心面向国家重大战略、区域发展重大需求和国际科学前沿，聚焦物质科学、信息科学、生命科学的会聚融通，重点围绕微纳智造、合成生物、功能材料、电子信息、生态环保五大攻关领域，以及集成电路、合成生物、先进材料和仪器装备四大生态圈，打通前沿科学研究、颠覆性技术研发和成果产业化的全链条，致力建设面向人才培养、前沿科技和社会服务的新型大学校区，推动成果转化、技术交易和产业投资的开放科技园区，促进技术创新、产业创新和制度创新的卓越创新特区，打造先进制造的示范地、创新经济的策源地、硬核科技的集聚地。<br>生物与分子智造研究院是科创中心下设的科研机构，研究院设有合成生物研究所、分子智造研究所、AI交叉研究中心，并建设以高通量技术为核心的自动化科学装置，支撑合成生物学和新物质精准智造两大战略性领域研究。研究院具有iBioFoundry、iChemFoundry两大特色装置和大型仪器公共服务平台；利用装置可大幅度提升实验效率，结合使能技术和BTIT/CTIT深度融合技术实现人工合成体系的精准设计、标准合成与精准调控；有望实现新物质的精准创制。<br>高纯分离团队面向芯片制造、化工新材料等重要产业，从事分离工程、电子化学材料、数据驱动材料智造等领域的应用基础研究和技术开发。依托浙江大学杭州国际科创中心、全省功能化学品智造重点实验室（筹）、化工功能材料智能设计与制造浙江省工程中心、浙江大学-华为电子化学材料工程联合创新实验室等平台，现有教职工11位，其中教授/研究员5位、国家杰青1人、国家/海外优青3人。承担国家重大仪器项目、国家重点研发课题、企业合作项目等40余项，发表论文250余篇，其中Science主刊3篇，多项技术实现产业化应用。获国家技术发明二等奖、教育部自然科学一等奖、中国化工学会基础研究成果一等奖、浙江省科技进步一等奖等奖励。团队负责人邢华斌为浙江大学求是特聘教授、工学部副主任。更多信息请见课题组网站：https://person.zju.edu.cn/xinghb。<br>由于科研工作需要，课题组面向全球诚聘科创百人计划研究员。<br>一、研究方向（包括但不限于）<br>1. 分离工程、电子化学品、工业催化、高分子合成与纯化；<br>2. 有金属离子吸附、膜分离、精馏、萃取、表面涂层等相关科研经历者优先。<br>二、聘任条件<br>1. 在海内外高水平大学或研究机构获得博士学位，具有化学工程、化学、高分子、材料、环境等相关的专业背景；<br>2. 有坚实的专业基础，在化学化工学术期刊上发表多篇高水平论文，具备独立开展研究工作的能力，如业绩优秀博士后，以及相当水平的海内外青年人才。<br>3. 年龄原则上学术类不超过35周岁（特别优秀者可放宽至38周岁），技术类不超过38周岁（特别优秀者可放宽至40周岁）。<br>三、待遇及保障条件<br>1. 岗位职务：担任团队核心骨干。<br>2. 薪酬待遇：提供具有竞争力的市场化薪酬，具体一人一议；依托科创中心申报入选各级青年层次人才项目的，可额外享受补贴或奖励。<br>3. 住房保障：可享受科创中心及属地政府人才房政策；符合条件的可认定为杭州市C类人才，享受相应津补贴待遇。<br>4. 科研经费：提供最高500万元科研启动经费；依托科创中心申报入选各级青年层次人才项目的，可额外获得项目经费支持。<br>5. 办公实验空间：根据实际需要提供一定面积的办公、科研用房。<br>6. 服务保障：提供“专人一站式”科研保障服务，共享科创中心大型仪器设备；协助解决子女入学入托和配偶工作；支持人才及团队成员申报各级各类科研/人才项目。<br>7. 发展通道：可兼聘至浙江大学相关院系，配备领域资深专家任职业导师；符合条件者可申请浙江大学长聘/预聘教职。<br>四、应聘方式<br>应聘者请将个人简历（包括个人基本信息、学习和工作经历、主要科研成果等）发送至课题组助理邮箱，邮件主题注明“应聘科创百人-姓名”。<br>本招聘启事长期有效。', '浙江大学（Zhejiang University）是一所历史悠久、声誉卓著的高等学府，坐落于中国历史文化名城、风景旅游胜地杭州。浙江大学的前身求是书院创立于1897年，为中国人自己最早创办的新式高等学校之一。1928年，定名国立浙江大学。抗战期间，浙大举校西迁，在贵州遵义、湄潭等地办学七年，1946年秋回迁杭州。1952年全国高等学校院系调整时，浙江大学部分系科转入兄弟高校和中国科学院，留在杭州的主体部分被分为多所单科性院校，后分别发展为原浙江大学、杭州大学、浙江农业大学和浙江医科大学。1998年，同根同源的四校实现合并，组建了新浙江大学，迈上了创建世界一流大学的新征程。习近平总书记主政浙江期间，亲自联系浙江大学，18次莅临指导，对学校改革发展作出了一系列重要指示，描绘了高水平建成中国特色世界一流大学的宏伟蓝图。在120多年的办学历程中，浙江大学始终秉承以“求是创新”为校训的优良传统，以天下为己任、以真理为依归，逐步形成了“勤学、修德、明辨、笃实”的浙大人共同价值观和“海纳江河、启真厚德、开物前民、树我邦国”的浙大精神。浙江大学是一所特色鲜明、在海内外有较大影响的综合型、研究型、创新型大学，其学科涵盖哲学、经济学、法学、教育学、文学、历史学、艺术学、理学、工学、农学、医学、管理学等十二个门类。设有7个学部、37个专业学院（系）、1个工程师学院、2个中外合作办学学院、7家附属医院。学校现有紫金港、玉泉、西溪、华家池、之江、舟山、海宁等7个校区，占地面积5870761平方米，校舍总建筑面积2746377平方米，图书馆总藏书量777.8万册。截至2018年底，浙江大学现有全日制在校学生54641人（其中：本科生25425人，硕士研究生19038人，博士研究生10178人），国际学生7074人（其中：攻读学位的国际学生4409人）。有教职工8909人（其中：专任教师3741人），教师中有中国科学院院士、中国工程院院士（含双聘）45人、文科资深教授10人、教育部“长江学者奖励计划”特聘（讲座）教授121人、国家杰出青年科学基金获得者133人。在国家公布的“双一流”建设名单中，学校入选一流大学建设高校（A类），18个学科入选一流建设学科，居全国高校第三。根据2019年5月ESI公布的数据，学校有8个学科进入世界学术机构排名前1‰，居全国高校第一；有1个学科进入世界学术机构排名前万分之一，有8个学科进入世界学术机构排名前100位，均居全国高校第二；有5个学科进入世界学术机构排名前50位，居全国高校第三。浙江大学紧紧围绕“德才兼备、全面发展”的核心要求，全面落实立德树人根本任务，着力培养德智体美劳全面发展、具有全球竞争力的高素质创新人才和领导者。在长期的办学历程中，涌现出大批著名科学家、文化大师以及各行各业的精英翘楚，校友中当选为两院院士的有200余人。学校始终保持与时俱进的教育思想，教育教学模式改革走在了全国高校前列；丰富的校园文化、先进的教学设施和广泛的国际交流为学生成长创造了优越条件。2018届毕业生初次就业率达到97.64%，本科毕业生海内外深造率达到60.30%。浙江大学注重精研学术和科技创新，建设了一批开放性、国际化的高端学术平台，汇聚了各学科的学者大师和高水平研究团队。近年来，学校发明专利授权数、权威学术期刊论文发表数、科研总经费等主要科研指标保持全国高校领先地位，在科学技术和人文社科领域取得了丰硕成果。学校主动对接国家和区域重大战略需求，着力打造高水平的创新源、人才泵和思想库。“十二五”以来，学校作为牵头单位获得国家科技进步特等奖1项、一等奖7项、二等奖40项；《中国历代绘画大系》、《中华礼藏》、敦煌学等文化传承创新成果在海内外产生了广泛影响。“国有成均，在浙之滨”。今天的浙江大学，坚持以习近平新时代中国特色社会主义思想为指导，秉承求是创新精神，致力于传播与创造知识，弘扬与引领文化，服务与奉献社会，坚定不移地为加快进入中国特色世界一流大学行列、迈向世界一流大学前列而奋斗，为实现中华民族伟大复兴、促进人类文明进步作出卓越贡献。', 'https://www.zhaopin.com/jobdetail/CC199796410J40869848704.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4353, '软件测试', '重庆科满福人力资源服务有限公司', '7月15日', '6000-10000元', '成都-成华区', '企业服务', '20-99人', NULL, 'CCL1487604860J40929110604', '【岗位职责】：<br>1、软件测试岗位职责 <br>2、接受测试任务，进行需求分析<br>3、按照测试计划搭建测试环境，并保证测试环境的可靠性<br>4、按照测试计划编亏测试用例，保证测试用例合理有效<br>5、按照测试用例执行测试，及时发现缺陷，并使用工具进行管理缺陷<br>6、编写和提交测试报告，保证测试进度按计划完成<br>7、参与审核其他测试工程师的测试用例和报告<br>8、学习公司已有方案和推广使用新的测试技术和工具', NULL, 'https://www.zhaopin.com/jobdetail/CCL1487604860J40929110604.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4354, 'C/C++', '外企德科数字技术有限公司', '2025年07月29日', '1.5-3万·14薪', '东莞-None', '专业技术服务', '10000人以上', NULL, 'CCL1480117890J40797692605', '岗位优势：<br>1、导师制培训机制，新人入职至少半年以上会有导师一对一辅导开展工作和学习。<br>2、部门：ICT（公开、光、计算、无线、数存等）、云计算、2012（中硬、中软、中媒）、消费者BG、BPIT、上海海思、Carbu（智能汽车）、数字能源等<br>3、主要地点：<br>北京、上海、东莞、深圳、杭州、南京、苏州、武汉、西安、成都<br>广州、长沙、济南<br>基本要求：<br>1、熟悉掌握C/C++/python/JAVA/go/JS等语言开发；<br>2、熟悉一种以上脚本语言，shell、python等；<br>3、掌握常用的数据结构、数据算法；<br>4、良好的表达能力，钻研精神、注重团队协作。<br>公司福利：<br>1、入职缴纳五险一金+商业险，全额缴纳社保公积金，试用期薪资全额发放不打折。<br>2、上下班班车接送<br>3、良好的团队氛围、首屈一指的技术大拿带教，成长性max<br>4、过节福利优厚，包括但不限于（过节费、节日礼盒、年终奖、福利活动、部门定期团建等）', '外企德科数字技术有限公司是一家2023年新成立的中外合资企业。成立于2023年11月24日，公司定位：专注于为信息技术企业提供人才及数字技术外包解决方案的中外合资企业。它是由中国人力资源服务行业的FESCO（北京国际人力资本集团）与全球人力资源服务领导者The Adecco Group（德科集团）合资成立的。公司主要提供网络技术服务、软件外包服务、计算机系统服务、技术进出口、软件开发等信息技术相关服务。专注于为信息技术企业提供信息技术类人才及数字技术外包解决方案。', 'https://www.zhaopin.com/jobdetail/CCL1480117890J40797692605.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4355, '科研人员', '智联猎头', '7月4日', '2.6-4万', '扬州-广陵区', '互联网,人力资源服务', '1000-9999人', '不需要融资', 'CCL1318355140J40806966703', '2025“百名海外博士江苏行”活动扬州站<br>海外博士学历等相关专业领域；<br>专业基础扎实，机械工程专业方向、材料学专业方向、电子科学专业方向、认工智能专业方向、医学领域等。<br>具有团队精神，能服从领导安排，工作积极主动。', '智联猎头作为智联招聘旗下品牌，以满足企业中高端岗位的人才招聘需求为出发点，整合全球优质资源，覆盖数字经济、新一代信息技术、人工智能、金融、电子信息、装备制造、生物医药与健康、房地产/建筑等数十个行业，拥有规模庞大、覆盖面广的交付团队，致力于向企业输出专业化的招聘解决方案。智联猎头目前拥有卓聘平台服务、招聘流程外包服务、高端人才猎寻服务三大类核心服务，具备高度定制化能力，能够为不同发展阶段的企业提供一站式招聘解决方案，同时为企业转型升级提供保障，全面增强企业核心竞争力！智联猎头利用自身独特的资源优势、成熟的服务模式，以及多层次的产品，致力于打造高效、专业的一站式人才服务模式，让招聘更加美好！', 'https://www.zhaopin.com/jobdetail/CCL1318355140J40806966703.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4356, '科研人员', '万众壹芯', '6月30日', '2.5-2.6万', '成都-双流区', '医药制造,电子/半导体/集成电路,医疗设备/器械,检测/认证', '100-299人', 'C轮', 'CC559546030J40761784310', '四川大学华西医院精准医学转化研究中心（PMTRC）是一家致力于将医学科学研究成果转化为临床应用的专业机构，是国家精准医学产业创新中心、教育部医学攻关产教融合国家级创新平台的重要组成部分。在医工结合和生物芯片等领域，该中心处于国内领先地位。我们的研究团队由医学、工程学、生物学等多个领域的专家组成，由国家级海外高层次人才胡文闯教授和刘亚龄教授领衔，具有丰富的学术背景、研究与产业化经验。在医工结合领域，我们致力于将工程技术与医学实践相结合，开发新型医疗设备和治疗方案，以提高医疗水平和患者生活质量。我们的研究包括基于生物芯片的基因测序及分子诊断技术、器官芯片与药物筛选、纳米材料高敏诊断技术、人工智能疾病模型等多个方面，旨在为医疗实践提供更安全、更有效的解决方案。具体在生物芯片领域，我们致力于研发和应用先进的生物传感器与微流控芯片技术，以实现对生物样本的高通量、高灵敏检测和分析。通过生物芯片技术，我们能够快速、准确地诊断疾病、评估治疗效果，并开展个体化治疗。同时，我们也在探索生物芯片在疾病机制研究、药物筛选、生物合成等方面的应用，为精准医学的发展提供重要支持。研究中心有国际一流的科研设备，包括微纳米光刻与微纳制造、芯片探针点样、生物芯片探针台、单分子显微镜、单分子免疫诊断、多种测序与分子诊断设备、纳米材料表征、AFM、试剂冻干、纳米材料合成等。作为精准医学转化研究的重要推动者，我们将继续致力于医工结合和生物芯片等领域的研究与应用，为推动医学科学的进步和人类健康事业的发展贡献我们的力量。<br>导师介绍<br>四川大学华西医院精准医学转化研究中心主任，教育部长江讲席教授，成都岷山计划生物芯片研究院联席院长，成都万众壹芯科技有限公司创始人、董事长、首席科学家。获国家基金委海外基金（海外杰青）、美国NSF自然科学基金Career奖、美国NSF Air奖、IEEE纳米技术杰出讲者、IEEE纳米技术委员会主席、四川省峨眉计划专家、四川省创新创业团队领军人才、成都蓉漂人才、江苏省双创人才称号。兼任IEEEAccess期刊客座编辑、中国人体健康科技促进会临床微生物与感染精准检验专业委员会副主任委员和四川省抗衰老科学研究促进会副会长等社会职务。在Nat Commun、ACS Nano、Nano Lett、Biosens Bioelectron、Biomaterials、LabChip等期刊及会议发表论文200余篇，被引约5400次（Google Scholar）。已授权多项国际和国内专利。共承担 35 项研究项目（总经费1.8亿元）。发明专利20项。长期致力于微流控芯片和医工结合交叉领域，在高端医疗器械研发方面，团队成功研发了多款新型医疗设备，并已通过临床试验，进入市场推广阶段。率先研发出30分钟内全封闭微流控卡盒的分子居家快检技术，获得国内首个可居家用的核酸扩增器的国家医疗器械证,取得了标志性的成果。研发出首个微流控全自动化肿瘤治疗基因突变测序试剂盒（近万例临床病例验证），在第十届国际精准医学会议上进行发布（省长、省卫建委主任、省科技厅厅长、科学院及工程院院士等出席）。目前在研的多个项目已处于转化过程中，包括呼吸道病原体十重快速检测、336种病原体微流控自动化建库和快速测序试剂盒（覆盖临床多科室病原体种类）、心衰指标的指尖血断点检测技术（实现心衰疾病的居家全程管理）等技术和产品，针对重大疾病具有泛的临床应用场景。<br>【岗位要求】<br>1.遵纪守法、学术端正、身心健康，具有较强的责任心，能够全身心投入科研工作，年龄35岁以下。<br>2.国内博士毕业生需取得博士学历证与学位证，国外博士毕业生应通过教育部学历学位认证，具有良好的科研能力和业绩基础。<br>3. 分子生物学、生物医学工程、基础医学等相关专业背景，.熟练掌握DNA/RNA相关的基础知识和实验操作、熟练掌握NGS建库湿实验流程（如Illumina、华大等平台）和测序原理。具有空间转录组实验经历优先；主要从事空间转录组生物芯片及配套试剂盒研发工作。<br>4.有较好的科学研究经历和教育学背景，承担/参研过国家级科研项目或已发表高水平论文者优先，具有海外留学经历者优先。<br> <br>【岗位职责】<br>1. 专职博士后聘期为三年，在站期间必须全职脱产从事博士后研究工作，科研业绩要求以及出站后留院要求按四川大学华西医院博士后管理有关规定执行；<br>2. 承担相关研究课题，发表高水平文章；<br>3. 协助指导博士、硕士研究生。<br> <br>【岗位待遇】<br>1.税前30万/年（含五险一金），科研业绩奖励视产出具体情况而定，上不封顶（参与成果转化工作及产学研合作等项目按绩效另行奖励）。<br>2.专职博士后在聘期内享有学校及医院专职科研人员同样的学术待遇，研究中心协助申请博新计划等额外支持项目，业绩达到相关要求后可以申请留院。<br>3.参与更贴近临床转化应用的科研工作，参与国内外高水平研究团队学术交流、医工交叉融合团队的培养培训。', '万众一芯聚焦生物芯片0到1的原始创新，跨领域技术积累10余年，超百项知识产权，匠心打造“小于时代、先于时代”的分子诊断POCT系列产品：新冠核酸居家自检、更小更快的基因测序仪等，打造诊断“芯”时代，获苏州市首批独角兽培育企业、四川省顶尖团队、2021未来医学榜创新IVD器械全国44名及全国最具潜力留学生企业等荣誉。融资获知名风投亲睐，最新一轮由启明领投，老股东经纬持续跟投。公司总部位于苏州，成都，深圳，美国均设子公司，已建成2000平GMP产线，联合华西医院在建“国家精准医学产业中心”，1.4万平的“万众一芯精准医学产业创新中心”拟建中，依托国家级平台搭建下游生态圈，海外市场先行，驱动爆发性成长。', 'https://www.zhaopin.com/jobdetail/CC559546030J40761784310.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4357, 'Java', '外企德科数字技术有限公司', '2025-07-27 00:25:49', '1.5-3万', '东莞-None', '专业技术服务', '10000人以上', NULL, 'CCL1480117890J40791078505', '（1）具有较强的逻辑分析和学习接受能力，耐心细致，动手能力强；（2）有创新能力和发展潜力，愿意从事科学研究；（3）熟练掌握Java、C/C++、Python、GO等任一编程语言，熟悉Linux操作系统；（4）遵纪守法、品行端正、身体健康、工作负责、不怕辛苦，具有较强团队合作意识和良好的沟通能力；（5）有相关系统研发经验者优先。', '外企德科数字技术有限公司是一家2023年新成立的中外合资企业。成立于2023年11月24日，公司定位：专注于为信息技术企业提供人才及数字技术外包解决方案的中外合资企业。它是由中国人力资源服务行业的FESCO（北京国际人力资本集团）与全球人力资源服务领导者The Adecco Group（德科集团）合资成立的。公司主要提供网络技术服务、软件外包服务、计算机系统服务、技术进出口、软件开发等信息技术相关服务。专注于为信息技术企业提供信息技术类人才及数字技术外包解决方案。', 'https://www.zhaopin.com/jobdetail/CCL1480117890J40791078505.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4358, '前端开发', '上海扬丝信息科技有限公司', '7月26日', '3000-6000元', '上海-嘉定区', '计算机软件,互联网,专业技术服务', '20-99人', '天使轮', 'CC424126880J40702490814', '此岗位是招储备型新人的，培养需要在公司待满三年，三年之间的工资也会是每年正常固定递增的，但是需要长期稳定踏实肯干的人。 <br>以下是必须掌握的初级技术需求：<br>1.熟练使用vue，了解uniapp，有两个以上vue实际开发的项目 <br>2.对组件的做法有深刻理解，会自行拆分组件 <br>3.熟练掌握HTML5、javascript、CSS、JQuery、AJAX，至少熟练使用一种前端框架，包括但不限于：<br>岗位职责： <br>1.负责前端页面开发和维护，并根据需求优化产品性能、用户体验、交互效果及各种主流浏览器的兼容适配工作 <br>2.独立承担分析业务系统前端的设计、开发与实现 <br>3.与后端工程师合作，为客户提供更好的体验和更丰富的功能 <br>4. 具备扎实的编程基础，良好的代码风格，注重代码品质<br>5. 擅长和团队合作，具备很好的沟通和协调能力<br>6. 有一定基础模块审美能力，会PS的优先考虑', '上海扬丝信息科技成立于2010年，是一家优秀的电子商务系统及服务提供商，公司致力于通过最精湛的技术、最全面的服务为国内各大企业建设优质的电子商务平台。上海扬丝科技根据电商行业特点和最新技术，从PC到移动，从线上到线下，从前端到后端，从直销到分销，为企业量身定制高质量解决方案，让企业在竞争中脱颖而出。', 'https://www.zhaopin.com/jobdetail/CC424126880J40702490814.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4359, '科研人员', '北京师范大学中国基础教育质量监测协同创新中心', '7月26日', '8000-15000元', '北京-海淀区', '学术/科研,学校/学历教育,学术/科研', '100-299人', '不需要融资', 'CC219659580J40715021211', '岗位职责： 1. 主责国家级重大科研项目中所有汇交的磁共振数据在中心侧的质量评估工作；', '中国基础教育质量监测协同创新中心成立于2012年7月，并于2014年10月通过教育部认定，是我国教育学和心理学领域唯一的国家级协同创新中心。中心目前已成为基础教育质量监测的国家权威机构、高层次评价人才培养基地和国家基础教育质量决策支撑平台。自成立以来，中心持续承担国家义务教育质量监测工作，牵头研制教育部发布的系列教育质量评价指南，研发9大学科领域国家监测标准和工具、10余套智能化测评系统和平台，助力搭建我国基础教育评价的“四梁八柱”，每年监测覆盖32个省份、约330个区县、6700所学校、近20万名学生，研制一千多份各类监测报告，支撑国家建立具有中国特色、国际可比的基础教育质量监测体系，在促进基础教育高质量发展中发挥了重要支撑作用。中心是北京师范大学直属二级院系，为研究生独立招收和培养单位，聚焦教育质量监测与评价，在教育学和心理学两个双一流A+一级学科下设置四个特色专业方向，自2015年起招收硕、博士研究生。十年来，中心在人才培养、学科建设、国际交流等方面成效显著。', 'https://www.zhaopin.com/jobdetail/CC219659580J40715021211.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4360, '科研人员', '河源市艾佛光通科技有限公司', '7月15日', '2.1-3.5万', '广州-天河区', '电子/半导体/集成电路', '300-499人', 'B轮', 'CCL1450836240J40911117304', '岗位描述：<br>岗位类型：博士后（A、B、C 岗） 1-3人 02<br>研究方向：<br>1、第三代半导体材料与芯片<br>2、高速移动宽带通信核心芯片<br>3、先进能源材料与器件<br>4、高性能LED外延材料与芯片<br>5、高性能太阳电池<br>招聘要求：<br>1、遵守法律法规，具有良好的思想政治表现和品德修养，身心健康，无违法违纪记录。<br>2、身心健康，年龄在35周岁（含）以下。<br>3、具有国内外知名高校或科研院所博士学位，获得博士学位一般不超过3年；或通过博士学位论文答辩的应届博士。<br>4、应聘者应接受过系统的科研训练，科研基础扎实，具有较强科研能力，思维严谨、条理清晰，善于沟通，愿全职在校从事博士后研究工作。<br>待遇福利<br>工作条件：<br>1、学校提供综合年薪，***可达57万元，学校为博士后研究人员提供“双一流”A类高校的国家、部省级高水平科研平台和科研条件，现有***科研平台30个，部省级科研平台249个，支持博士后申请国家、广东省各类科研项目和人才计划；<br>2、按规定缴纳社会保险和住房公积金，并享受相关福利待遇；<br>3、享受博士后公寓或住房补贴；<br>4、子女入学可读学校优质附属幼儿园和实验学校；<br>5、依托广州国际校区招收的博士后可额外获得20万元科研启动费；<br>6、出站后留粤工作，符合广东省相关政策的，省财政额外给予40万元住房补贴（3年）。<br>晋升通道：<br>1、在站满18个月或期满出站后1年内，可参评博士后副研究员；<br>2、博士出站后留校通道畅通。<br>校简介&amp;政策<br>华南理工大学地处广州——粤港澳大湾区的核心，是直属教育部的全国重点大学，办学溯源至1918年成立的广东省立***甲种工业学校(世称“红色甲工”)。是新中国“四大工学院”之一.1960年成为全国重点大学，1981年成为全国首批博士和硕士学位授予单位1995年进入“211工程”行列，2001年进入“985工程”行列，2017年进入“双一流”建设A类高校行列，2023年起跻身软科“世界大学学术排名”前150强。<br>路走来，华南理工大学得改革风气之先，勇立潮头，创新发展，成为“南方工科院校的一面旗帜”。<br>而今站在世界150强的新高度，学校怀爱才之诚，聚焦青年科技人才成长关键环节，整合资源，再推新政：<br>一、政策大大礼包 <br>1.师资博士后，鼎力培养！出站择优留校。所有流动站博士后均纳入学校师资博士后培养。<br>2.综合年薪***可达57万元，待遇优厚！博士后综合年薪***57万元，出站成果突出的，可获额外奖励；除年薪外，学校另提供博士后公寓或住房补贴，广州国际校区聘用的博士后，另获得20万元科研启动费。<br>3.尊重学科和人才成长规律，重视每一个努力的你！在站目标任务由博士后和导师商定，年度和出站考核目标任务执行。<br>4.海阔凭鱼跃，支持优秀的你脱颖而出！出站成果突出者，薪酬之外再给予考核特别资助奖励。<br>5.多渠道、多方式、多重机会留校，发展通道更宽阔！出站可按学校规定申请教研、教学、专职研究系列岗位，学校择优选聘留校；获得出站考核特别资助的，可100%留校聘用。<br>二、我们的“硬核资源库”<br>1.学科引领前沿。16个学科进入ESI全球排名前1%。<br>2.科研实力卓越。30个***科研平台，249个省级科研平台。数量位居全国高校前列、广东高校***，且均对博士后开放。<br>3.覆盖7大学科门类，34个博士后科研流动站任你选！<br>学院简介<br>华南理工大学材料科学与工程学院是在原华南工学院相关传统优势专业基础上发展起来的，其历史可以追溯到二十世纪五十年代。1952年华南工学院开设全国***家橡皮工学专业和全国第一批硅酸盐工学专业，1958年开设属于全国第一批的金属学与热处理工艺及设备专业、高分子化工和化学纤维专业，1959年建立了全国***家电子陶瓷专业。1978年经教育部批准成立材料科学研究所。1995年成立材料科学与工程学院。2008年成立金属材料科学与工程系，2012年成立生物医学工程系，2020年成立光电材料与器件系，形成了学科更完整、综合实力更强的材料科学与工程学院。<br>学院现设有6个系(高分子材料科学与工程系、无机材料科学与工程系、金属材料科学与工程系、电子材料科学与工程系、生物材料系、光电材料与器件系);1个全国重点实验室(发光材料与器件全国重点实验室);1个国家工程技术研究中心(国家人体组织功能重建工程技术研究中心);28个省部级教学科研平台;1个***实验教学示范中心(材料科学与工程教学实验中心);1个***光电材料与器件虚拟仿真实验教学中心。<br>学院教学育人条件优越，近5年获广东省高等教育教学成果奖4项。共拥有教学和实验室面积约3.8万平方米，完备先进的教学与科研仪器设备约2.6万台，总价值约8.11亿元，能够充分保障各层次学生得到系统的实验训练和全面的综合素质培养。<br>学院科研实力与成绩突出，先后获得国家、省部级各类科研奖励100余项(包括国家自然科学二等奖2项、国家技术发明二等奖3项、教育部科学技术奖6项、广东省科学技术一等奖17项等)。2021-2024年，学院发表三大索引论文约6062篇，申请专利1984件，授权1548件，到校经费12亿元，各项科研成果位居学校前列。<br>材料科学与工程学院一直秉承优良学术传统，努力为全院师生营造良好工作环境和学习氛围，在人才培养、科学研究、社会服务与文化传承等各项事业不断取得进步，已为国家培养了上万名材料专业人才。目前，材料科学与工程学院正在为建设“具有一定国际影响的材料领域教育与研究机构”而不断努力，必将为中国材料科学与工程领域的科学进步与产业发展不断做出新的贡献。<br>团队导师简介<br>以李国强教授为核心的半导体材料与芯片团队依托于华南理工大学发光材料与器件国家重点实验室，是一支由国家万人计划科技创新领军人才、国家青年长江学者、国家优青、国家青拔、广东省青年拔尖等20多位博士为核心的科技创新团队；聚焦第三代半导体材料与芯片技术,涵盖材料生长、芯片设计、制造工艺和关键装备4个关键方向；在国家重点研发计划项目、国家工业强基计划、国家重大科研仪器研制项目课题、国防科技创新重点项目、广东省重点研发计划等国家、省部级20余项项目支持下，取得了多项技术突破，研制出多种关键芯片，解决了我国多项“卡脖子”技术难题。<br>李国强，华南理工大学发光材料与器件国家重点实验室教授、博士生导师，入选国家万人计划科技创新领军人才(2019)、中青年科技创新领军人才（2020）、国家青年长江学者(2016)、国家优青(2014)、广东省特支计划科技创新领军人才（2020）、广东省珠江学者特聘教授（2016）、广东省杰青（2013）等人才计划，是国家重点研发计划首席科学家(2次)，国家多个部委责任/咨询专家；致力于发展GaN、AIN、GaAs等高性能III-V族化合物半导体材料与芯片，主持国家工业强基计划、国家重点研发计划项目、国家重大科研仪器研制项目课题、广东重点领域研发计划等多项国家及省部级项目；相关成果在Adv. Mater.、Adv. Funct. Mater.、Rep. Prog. Phys.、Light Sci. App.、Nano-Micro Lett.、lEEE Electron Dev.Lett.、Appl. Phys.Lett.等高水平期刊发表论文200余篇，其中ESI高被引论文10余篇，SCI 他引6800余次；授权中外发明专利200余件；成果已产业化，应用在航空航天、卫星通信等重大工程及华为、中兴的基站及手机上；获国家技术发明二等奖(第四)、广东省技术发明一等奖(***)、广东省丁颖科技奖(***)、中国专利奖优秀奖(***)中国产学研合作创新成果奖(***)等奖项。', '新时代、新机遇、新挑战，第三代半导体是全球战略竞争的制高点，是未来电子信息产业的基石，也是我国长期受到西方发达国家卡脖子的重大技术难题。以发展我国第三代半导体核心技术为使命的艾佛光通科技有限公司，拥有以国家科技创新领军人才、国家长江学者、国家重点研发计划首席科学家等20多位博士为核心的国际一流科学家技术团队，历经10多年、投入近10亿元的刻苦研发攻关，率先在第三代半导体的材料生长、芯片设计、制造工艺和关键装备等方面上取得多项原创性技术突破，使我国成为继美日之后，少数几个全方位掌握第三代半导体技术的国家。艾佛光通开创了完全独立自主的全链条Si基GaN、AlN等第三代半导体材料与芯片技术。艾佛光通所研发生产的多种芯片已在多个领域得到应用。艾佛独有技术获得了包括国家技术发明二等奖、广东省技术发明一等奖在内的省部级以上科技奖励8项。荣誉资质获得国家技术发明二等奖、广东省技术发明一等奖等省部级以上科技奖励8项已在国防上得到应用，并于国际龙头企业签订多项产品及技术开发合同获得项目：国家重点研发计划、广东省重大专项、广东省扬帆计划等已获发明专利100余件，国际PCT专利20余件，实审公开发明专利100余件', 'https://www.zhaopin.com/jobdetail/CCL1450836240J40911117304.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4361, '测试工程师', '软通动力信息技术(集团)股份有限公司', '8月9日', '8000-9000元', '深圳-龙华区', '互联网,IT服务,计算机软件', '10000人以上', 'D轮及以上', 'CC000544460J40375974216', '岗位要求：', '软通动力信息技术（集团）股份有限公司（以下简称“软通动力”）是中国数字技术产品和服务创新领导企业，致力于成为一家具有全球影响力的科技企业，企业数字化转型可信赖合作伙伴。公司2005年成立于北京，多年来始终坚持科技创新，具有软硬全栈的智能技术产品和服务能力，提供软件与数字技术服务、计算产品与数字基础设施、数字能源与智算服务以及国际化服务。目前，公司在10余个重要行业服务超过1100家国内外客户，其中超过230家客户为世界500强或中国500强企业，员工近90000人。软通动力拥有软通咨询、软通金科、软通工业互联、机械革命、软通华方等业务子品牌，并在全球40余个城市布局业务，构建北美、日本、东南亚、中东四大国际交付中心，在北京城市副中心、江苏无锡建设两大智能制造基地。同时，公司前瞻布局智能制造、ICT软硬基础能力和生产力智能化产品，打造产业链闭环。软通动力设立30个能力中心，拥有1个国家级工程实验室，6个省市政府认定的工程、技术实验室及研发中心，1个博士后科研工作站，50+技术合作伙伴的生态合作体系，不断探索前沿技术的巨大商业应用潜力。公司旗下教育品牌软通教育，拥有一家全日制本科学院——郑州西亚斯学院数字技术产业学院；同时在全国合作院校600多所，设有70多个校企联合人才培养基地，通过校企合作、协同育人，为社会培养高素质应用型人才。软通动力先后获得“2023年中国IT服务市场排名TOP 1”、“2024年Q4 PC出货量国内市场份额排名TOP 2”、“2024年中国软件和信息技术服务竞争力百强企业”、“2023年中国信创企业100强”、“2024万得ESG评级（Wind ESG Rating）AA级及信息技术服务行业ESG综合得分排名第一”等荣誉及市场认可，并拥有全球软件工程领域最高级别CMMI V2.0成熟度5级评估认证、国家研发运营一体化（DevOps）三级能力成熟度模型认证、信息技术服务标准（ITSS）运维能力成熟度一级认证等专业资质，支撑公司更优质的服务体系。', 'https://www.zhaopin.com/jobdetail/CC000544460J40375974216.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4362, '科研人员', '广州机施建设集团有限公司', '3月24日', '2.3-2.5万', '广州-黄埔区', '房地产开发,房地产开发', '500-999人', '未融资', 'CC163205910J40315634605', '岗位职责：<br>  <br>1、负责博士后课题的开题报告、中期考核报告、出站报告的编写与答辩，配合公司博士后管理办公室办理博士后入站及出站手续；<br>  <br>2、负责博士后课题研究，取得相关技术成果；<br>  <br>3、主持或参与企业具体工法、专利、科技计划项目、标准规范等课题的研究或编制；<br>  <br>4、参与科技部、合规部业务线的管理工作及各经营单位、项目部的现场技术调研或技术培训；<br>  <br>5、完成领导安排的其他工作任务。<br>  <br> <br>  <br>任职条件：<br>  <br>1、在国内外已获得博士学位，年龄35周岁以下；土木工程、工程管理、岩土工程、建筑材料、结构工程、道路与桥梁工程、法学等相关专业毕业；<br>  <br>2、具有良好的思想政治素质和职业素养，思想品行端正，作风正派，严谨负责；<br>  <br>3、具有较强的独立科研能力和良好的敬业精神，在国内核心期刊及以上级别刊物上已发表两篇专业学术论文的优先考虑；<br>  <br>4、没有违纪违法行为；<br>  <br>5、具备全职从事博士后研究工作的条件，身体健康，能胜任岗位工作。<br>', '广州机施建设集团有限公司，原名广州市建筑机械施工有限公司，创建于1960年，为全国500家最大经营规模建筑企业之一，现拥有资产总额超过60亿元，年经营规模超过150亿元。公司拥有房屋建筑工程总承包、市政公用工程总承包、机电安装工程总承包、建筑装修装饰工程、地基与基础工程、钢结构工程、土石方工程专业承包等多项一级资质，并已基本具备建设部申报特级企业资质标准。近年来公司不断拓展创新，承建和参与建设了亚运会开闭幕式场馆海心沙“亚运之舟”工程、亚运主媒体中心、广东省博物馆新馆工程、广州国际会展中心、亚运马术场工程、广州新体育馆等多项省、市重大工程项目。先后获省、市优良样板工程70多项，获国家工法8项、省级工法35项，国家专利15项，编制省级、国家级标准3部，拥有国家认定博士后科研工作站和广东省认定的企业技术中心。近年来，公司积极探索走多元化经营道路，主攻本地市场的同时还积极开拓外地市场，已在新疆、武汉等地组建分公司，在建的工程项目更辐射至深圳、中山等珠三角地区，经营业绩逐年攀升。公司一直秉承“责任、服务、关爱、创新”的企业价值观，保持良好经营发展势头的同时，致力给员工创造广阔的发展平台，用人更育人，使公司及员工都能得到发展实现双赢。', 'https://www.zhaopin.com/jobdetail/CC163205910J40315634605.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4363, '实施工程师', '上海易算精技术服务有限公司', '7月28日', '7000-10000元', '宁波-海曙区', '通信/网络设备,计算机软件', '20-99人', NULL, 'CCL1491790950J40742814214', '岗位职责:', '上海易算精科技有限公司是一家专门从事大数据金融类软件产品的研发、销售与售后服务的高科技跨国企业。成立以来，公司致力于以软件终端为载体，以互联网为平台，向投资者提供精准的金融数据和专业的技术分析。25年来公司坚持为客户开展专业证券知识的培训，致力于帮助投资者树立正确的投资理念、掌握投资技巧、分析投资信息，凭借先进的知识和发达的“软件武器”帮助投资者在证券这个行业内获取不菲的利润。公司依靠强大的技术研发实力、敏锐的市场洞察力和丰富的实操经验，始终前瞻性地把握行业发展方向，不断地引进国际上先进投资分析技术，进而开发出满足投资者需求的新产品，在海内外证券软件行业内均有重要影响力。公司统一福利待遇：1.多个分店，实习期结束后多个工作地点可供选择；2.灵活休假制度，法定节假日，更有14天超长带薪年假；3.完善的培训体系（入职培训+在职带薪培训+专业知识/技能视频资料培训+师徒制）帮助新人快速成长。', 'https://www.zhaopin.com/jobdetail/CCL1491790950J40742814214.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4364, 'Java', '众阳健康科技集团有限公司', '10月9日', '1-1.5万', '济南-历下区', '计算机软件,互联网,IT服务,人工智能', '1000-9999人', '未融资', 'CC227606010J40595914606', '岗位职责:<br>1、根据需求设计完成产品功能或者服务的设计，文档编写，代码实现，单元测试和接口测试。<br>2、配合研发经理完成sql脚本审核，codeReview 工作。<br>3、对产品的分析设计、开发发布、系统的性能、安全性、稳定性负责。<br>任职要求:<br>1、计算机、软件工程、电子信息、自动化、通信等相关专业，本科及以上学历；<br>2、计算机基础知识扎实，掌握数据结构、C语言基础知识、Java基础知识；<br>3、掌握JavaWeb常用框架，熟悉J2EE常用框架，对SSH、SSM、Spring等框架熟练掌握。<br>4、具备良好的沟通能力与协作理解能力，爱好钻研技术，学习能力强。', '众阳健康科技集团，创立于1998年，现有职工3000余人，总部位于山东省济南市，产品和服务涵盖卫健委、医院、医保、养老等业务领域，拥有近300项软件产品著作权，具有100%的自主知识产权。集团目前在我国医疗健康信息化领域排名前三，县域医疗健康信息化领域排名第一，云模式医疗健康信息化领域排名第一。主营产品和服务有医院信息化系统、智慧医疗系统、智慧服务系统、智慧管理系统、HRP系统、医保管理系统、医共体信息平台、互联网医院、人工智能应用、咨询服务、电子病历评级、互联互通评级等。目前已广泛应用于国内2000余家二级以上医疗机构，及200余家省、市、县级区域医疗卫生信息平台，累计服务人口超过5亿人。众阳健康集团是国内最早提出“一体化数字医院建设”理论的倡导者、践行者，国内以电子病历为核心的智慧医院建设思想最早的实践者。在云计算、大数据时代，众阳健康基于微服务和数据中台打造的“云健康”平台，高度契合国家医疗健康十四五规划，实现了大规模的应用落地，成为了引领医疗健康行业数字化转型的标杆。集团荣获山东省科学技术进步一等奖、吴文俊人工智能科学技术一等奖等奖项，是“国家智慧健康养老示范企业”、“中国医疗业信息技术服务示范企业”、“中国信息技术服务产业医疗健康领域示范企业”、山东省“十强”产业集群领军企业，获得山东省科技厅颁发的“院士工作站”及全国博士后管委会办公室批准的“博士后科研工作站”。与北京大学联合成立了“大数据联合研发中心”，与山东大学齐鲁医院共同成立了“数字健康联合实验室”。众阳健康打造的样板工程“平阴模式”、“成武模式”，以服务为核心的“淄博模式”，受到了全国人大常委会副委员长陈竺、国家卫健委主任马晓伟、北京大学中国健康发展研究中心主任李玲等国家领导和专家的高度认可。在共计12个国家基层卫生健康综合建设试验区中，众阳承建了河南“郏县”、广西“上思县”紧密型医共体建设，打造了全国示范。', 'https://www.zhaopin.com/jobdetail/CC227606010J40595914606.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4365, '硬件测试', '和美汽车零部件青县有限公司', '2025年07月30日', '5000-7000元', '沧州-青县', '汽车零部件', '300-499人', NULL, 'CC537505680J40760610901', '岗位内容：<br>1. 执行硬件测试任务，并维护测试数据和文档；<br>2. 跟进测试过程中发现的问题，协助解决硬件缺陷；<br>3. 收集硬件测试需求，推动测试工具和方法的改进。<br>任职要求：<br>1. 熟悉常用的硬件测试方法和工具；<br>2. 善于沟通和协作，具有良好的团队合作精神；<br>3. 具备较强的学习和自我提升意愿，能够快速适应新环境和新技术。', '和美汽车零部件青县有限公司位于河北省沧州市青县范官屯开发区，占地75亩，注册资金5000万，主要从事汽车零件的设计、生产、销售、服务的专业化厂商，主要客户有北京奔驰、北京现代、北汽、奥托立夫、大众、宝马等一线汽车厂商；', 'https://www.zhaopin.com/jobdetail/CC537505680J40760610901.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4366, 'Java', '大连高新园区仁源计算机软件开发有限公司', '5月20日', '4000-7000元', '大连-甘井子区', '计算机软件,电子商务', '100-299人', '未融资', 'CCL1468857000J40599587809', '任职要求：<br>1.计算机/软件工程/信息管理等相关专业；<br>2.对软件开发有浓厚兴趣，学习能力强，学习意愿强，敢于承担工作压力；<br>3.工作态度端正，有责任感，组织性、纪律性强，学习意愿强，敢于承担工作压力；<br>4.英语cet4级相当或以上水平，有读写能力；<br>5.沟通能力好，有团队合作精神；<br>6.长期稳定在大连发展；<br>7.对JAVA/ web开发有概念，基础知识扎实，对前端和后端开发有一定了解。', '位于美丽海滨城市大连，自成立以来我们已经参与联合研发的I-RPA、智慧MES系统、智慧调度管理系统、工艺管理系统等已经实现了在生产环境的部署，并取得积极的评价。公司主要以自研开发和为各大企业提供后台系统管理业务为主，目前已经有超过30+国内外大型企业达成合作。从成立至今，我们已经成功申请超过 35项的软件著作权等相关知识产权。产品主要包括：智慧工业平台、I-MES、I-RPA、I-HR，我们研发的智分享人力资源平台(I-HR)已经在超过 3家的大中型人力资源公司进行了部署使用。研发的 I-RPA、智慧MES系统、指挥调度管理系统、工艺管理系统等已经实现了在生产环境的部署。', 'https://www.zhaopin.com/jobdetail/CCL1468857000J40599587809.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4367, '销售运营', '河南青碧信息科技有限公司', '7月8日', '6000-12000元', '郑州-管城回族区', '零售/批发,零售/批发', '100-299人', '未融资', 'CCL1224990300J40749554714', '岗位职责： <br>1. 学习公司产品知识以及运营体系，熟悉基础业务; <br>2. 组织和策划金融产品的推广、维护活动； <br>3. 处理日常运营合作及产品推广事务； <br>4.后期能力突出，可负责新人岗前培训、团队管理工作、办公室整体运营。 <br>', '河南青碧信息科技有限公司是一家集百货礼品，教育培训，移动支付、金融、O2O电商为一体的科技推广及应用的服务业公司。企业专注于为商户和个人提供:新型、安全、便捷的高科技智能收单终端+信用卡办理服务+专业的银行消费贷款服务+银商天下（购物、车票和酒店预订等多功能O2O电商APP）。公司引进国外先进的WWI管理体制，实行一对一的针对性专业培训，注重个人的能力的培养，打造出学习型的平台！公司所有管理层都从基层选拔，有公开透明的晋升机制，打造全新的创业型平台。公司以人的提升推动企业的成长，近年来培养了众多优秀的实干型管理人才。为集团500家分公司的伟大布局做出了卓越的贡献！公司与国有控股公司、大型国有股份制银行、国内上市企业、国内知名企业等形成战略合作伙伴关系。与具有国资背景、在业内排名靠前的支付公司——北京海科融通支付服务股份有限公司达成战略合作，成为海科融通在全国颇具实力的线下支付直营服务商，并获得授予先进团队荣誉称号；与大型国有股份制银行——民生银行和浦发银行达成合作伙伴，成为此两家银行信用卡网申业务优秀合作商。公司经营完美地融合了“创业平台”与“管道建设”的双向发展平台。颠覆了传统的企业经营模式，让我们的产品和服务不是一次交易，而是可以无限次地和客户发生链接从而多次获利，真正做到让员工获得连续不断的可持续性收入，这是业内的一次伟大创新和变革，极大的提升了员工的安全感。', 'https://www.zhaopin.com/jobdetail/CCL1224990300J40749554714.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4368, '质量管理/测试', '湖南力通恒裕电缆科技有限公司', '7月27日', '4000-7000元', '怀化-中方县', '电气机械/电力设备,通用设备制造', '100-299人', '未融资', 'CC575122180J40690904702', '本科及以上、材料类、电气类专业优先。年龄20-30岁<br>岗位职责：           <br>1、原材料、半成品、成品的检验、分析及数据整理上传（ERP系统）、检验报告及合格证制作与打印。确保产品的质量和可靠性‌<br>2、产品认证、生产许可证、体系认证等合格评定管理、确保产品符合相关标准和要求。<br>3、客户投诉处理‌、搜集客户的品质意见和品质要求、处理客户投诉、并对投诉进行分析和改进、确保客户满意。<br>‌岗位要求：<br>1、‌教育背景‌：本科及以上学历、通信、电子工程、自动化等相关专业。<br>2、‌工作经验‌：具备2年以上机械加工行业工作经验、有对供应商质量管理和客户投诉问题处理经验者优先。<br>3、‌技能要求‌：熟悉ISO9001、ISO14000标准、PPAP流程、有内审员资格。<br>4、‌其他要求‌：良好的沟通表达能力、踏实勤勉、具有抗压能力。<br>5、会使用设计类软件（如Cad、ProE、PS等）、有驾照会开车。<br>6、优秀应届本科毕业生亦可作为骨干培养。', '湖南力通恒裕电缆科技有限公司，位于湖南省怀化市鹤城区鸭嘴岩工业园，是一家专业生产及销售钢芯铝绞线、钢绞线、电线电缆的专业厂家，公司注册资金6375万元，拥有高级工程师3人，工程师、经济师、会计师、专业技师等各类专业技术人员100余人。本公司先后承担怀化市电力集团农网改造，渝怀铁路电力工程，怀化电信公司百万大行动，怀化移动传输工程第一、二期等工程，产品主要供应湖南、贵州、吉林等省中标的农配网线路材料以及广西、四川、重庆、湖北、江西等地的电力建设工程与输变电线路改造项目，产品质量与服务得到了用户的一致好评与肯定。2014年为适应企业发展需要，恒裕实业分离其原电线电缆生产项目，单独成立“湖南力通恒裕电缆科技有限公司”，全面整合市场资源与生产优势，生产销售10KV及以下架空线、钢芯铝绞线、钢绞线、电线电缆等产品，实现年产值数亿元,上缴利税逾千万元。公司已取得10KV及以下电线电缆生产许可证，并通过ISO9001-2008质量管理体系、ISO14001环境管理体系、OHSAS18001职业健康安全管理体系认证，组织机构健全，设有行政事务中心、企业管理中心、质量技术中心、设备安全中心、财务运营中心等五大管理中心，公司管理制度严格、技术力量雄厚、生产设备先进、检测装备齐全、产品质量过硬，拥有导地线18000吨、电缆80000KM的产品生产能力。现我司已全面接收原怀化市恒裕实业有限公司优良客户资源，产品主要供应湖南、贵州、湖北、广西、吉林、安徽、山东等全国逾20省市的电力建设工程与输变电线路改造项目，将为客户提供更优良的产品质量与服务。力通恒裕始终坚定“以人为本、质量第一、客户至上、诚信经营、共谋发展”的经营宗旨；坚守“行事以恒、如斯则裕”的品行作风；秉承“团结求实、诚信创新、开拓进取、追求卓越”的公司团队精神；与时俱进，争创一流，实施“品牌战略”，努力为电力事业和地方经济发展做出持久贡献，愿一如既往地为广大客户竭诚服务，共同发展！', 'https://www.zhaopin.com/jobdetail/CC575122180J40690904702.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4369, '总助/CEO助理/董事长助理', '郑州百壹源信息科技有限公司', '7月7日', '6000-12000元', '郑州-金水区', '快速消费品,零售/批发', '100-299人', '未融资', 'CC823714350J40721998702', '职位要求: <br>1、有无工作经验均可<br>2 、具备良好的组织、协调、沟通能力; <br>3、有清晰的职业规划，愿意从事管理工作，愿意为了自己的目标付出努力; <br>  薪资待遇：  <br>1、实习期两个月，实习期6000（4000无责+2000绩效）+提成，转正综合薪资8000元---15000  <br>  <br>2、提供员工住宿，无需交水电费，配套设施齐全。带薪培训，带薪年假，节日福利  <br>  <br>3、公司不定期组织聚餐、团建、户外旅游活动等  <br>  <br>4、入职即签合同  <br>  <br>  <br>  <br>  <br>', '公司简章郑州百壹源信息科技有限公司目前是做中小微商户推广银行聚合收单支付等多项业务。业务开展两年多以来，市场不断扩大，现因业务需要，扩招人才。招聘职位：经理助理(管理层方向培养)：5000—10000+提成+奖金+年终奖市场推广专员：6000—15000+提成+年终奖实习生/储备干部（两个月后转正）：3000—5000+奖金+年终奖福利待遇：工作环境优越，工作氛围融洽和谐，帅哥美女多，成长发展空间大公司地址：河南省郑州市金水区郑东新区绿地原盛国际3C', 'https://www.zhaopin.com/jobdetail/CC823714350J40721998702.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4370, '质检员', '湖南雪帝食品科技有限公司', '7月3日', '3000-5000元', '湘潭-雨湖区', '快速消费品,快速消费品', '500-999人', '未融资', 'CCL1257195280J40490740211', '理化检验的岗位职责：<br>1、协助主管制定来料的检验标准和检验规范；<br>2、按照相关标准、要求检验方法和来料检查程序，对原材料、外购件、包装物等进行检验，并出具报告；<br>3、识别和记录来料质量问题，对供应商提出质量改进建议；<br>4、通过再检验，验证供应商纠正措施的实施效果；<br>5、协助采购部处理不合格材料的退货工作；<br>6、对原料供应商、协作厂商交货质量进行整理、分析与评价；<br>7、对来料的规格和质量提出改善意见或建议；<br>8、检验仪器、量规和试验设备的管理与保养<br>9、来料库存品的抽验以及鉴定报废品；<br>10、拒收来料中的不合格材料和物件；<br>11、做好质量原始记录，对所检物品的质量情况进行统计、分析、上报；<br>12、完成上级领导安排的其他工作。', '湖南雪帝食品科技有限公司成立于2014年，是一家集研发、生产、销售为一体的大规模冰淇淋生产企业。坐落于湘潭经开区石码头路，占地面积约4万平方米，拥有多条自动流水生产线，生产旺季员工达800余人。 2013年中国中产阶级消费崛起，我们清醒的把握住了行业脉搏，果断转型升级，决定用更大胆的创新精神开始更大的征途，一个全新的品牌诞生----她就是雪帝，2015年雪帝旗下“小明”荣获中国冰淇淋营销策划大奖。2016年雪帝旗下“活酸”奶冰淇淋荣获中国冰淇淋创新大奖。 2017年，雪帝坚定“努力保持新鲜”的品牌理念，扩大生产规模，扩充产品数量，进发出前所未有的激情与活力，再次实现迭代升级。联系电话：0731-55551180', 'https://www.zhaopin.com/jobdetail/CCL1257195280J40490740211.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4371, '运营助理/专员', '深圳市博诚项目管理有限公司', '5月12日', '7000-10000元', '东莞-None', '建筑设计', '20-99人', '未融资', 'CCL1473424430J40711637416', '岗位职责<br>1协助主管对公司平台的日常经营和活动维护工作<br>2.配合上级策划实施促销活动，节假日等促销活动<br>3.协助运营对各部门已知及未知的问题进行记录，提供相应的解决方案<br>4.完成上级布置的其他工作任务<br>5.协助制定推广方案，包括线上线下活动策划、社交媒体推广等<br>6.内容宣传资料、文案等，确保推广内容符合品牌形象<br>任职要求<br>1.学信网统招本科及以上学历，有市场推广或相关工作经验优先考虑<br>2.年龄在23-32岁之间<br>3.头脑灵活，工作细致、严谨，具有较强的工作热情和责任感<br>4.执行力强、良好的沟通能力，有较好的团队协作精神<br>5.工作时间:8:00-12:00 14:00-18:00，周末双休，五险一金<br>福利待遇<br>1.员工生日福利+节日福利+年终奖等<br>2.完善的薪酬体系和考核晋升机制，为优秀员工提供良好的薪资晋升通道<br>3.每月10号发工资<br>4.带薪年假逐年增加', '我们主要是做工程资质招商加盟的，服务性的业务公司。老板目前有两个公司，一个是做工程的，一个是做教育的（深圳睿智教育科技有限公司），两个公司都在招人哦，都是长青行业。公司福利待遇好，节日礼物，生日聚餐，团建活动，都很丰厚的哦。', 'https://www.zhaopin.com/jobdetail/CCL1473424430J40711637416.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4372, '律师助理', '成都初阳知识产权代理事务所(特殊普通合伙)深圳分所', '7月7日', '4000-6000元', '深圳-龙岗区', '专利/商标/知识产权', '20-99人', '不需要融资', 'CCL1392398930J40336757214', '​1、法律文书处理​<br>起草、审核起诉状、答辩状、代理词、合同等法律文件，确保格式规范且内容合法。<br>整理案件卷宗，归档证据材料，确保资料完整有序。<br>​2、案件协助与调研​<br>参与案件前期准备，包括证据收集、法律研究（检索法规、判例）、制定诉讼策略。<br>协助律师出庭，记录庭审要点，跟进案件进展（如补充证据、提交代理词等）。<br>​3、客户沟通与服务​<br>接待客户咨询，解答法律问题，维护客户关系。<br>参与合同谈判、调解会议，协助处理非诉事务（如企业法律顾问工作）。<br>​4、行政与外勤事务​<br>递送法律文件、法院立案、调取档案等外勤工作。<br>协助律所日常运营（如会议安排、资料维护等）', '初阳知识产权代理事务所（特殊普通合伙）成立于2016年12月，目前拥有20多人团队，主要专注专利申请、知识产权纠纷案件、高新申请与政府项目补贴申请业务、审计、法律诉讼。经过多年发展，业务快速成长。公司价值观：主动、踏实、专业、诚信，公司理念：为客户创造价值是我们唯一存在理由，客户需求是我们发展原动力！公司目前布局律师、审计、专利、项目四个版块业务，均有用相关的专业资质。公司就是你的船，是你发挥专业知识的平台，期待您的加入，我们一起共同成长！', 'https://www.zhaopin.com/jobdetail/CCL1392398930J40336757214.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4373, '网络销售', '深圳市乐有家控股集团有限公司', '7月2日', '8000-10000元', '深圳-龙华区', '房地产中介,房地产中介,咨询服务', '10000人以上', '未融资', 'CC298754310J40548605402', '一、【任职资格】<br>新手、应届生均可，优秀导师带教培训、老员工热情帮助，上手速度快。只要你有一颗勇敢上进的心和敢于挑战的精神，随时欢迎加入我们的团队<br>二、【薪酬福利】<br>置业助理薪酬构成：<br>大专A02最高薪酬8000元：底薪补贴4000+1000行动量化绩效+ 3000职务绩效<br>本科A03 最高薪酬9000元 ：底薪补贴5000+1000行动量化绩效+ 3000职务绩效<br>3、专属优秀老员工带教与免费培训；<br>4、五险一金、节日福利、不定时聚餐团建活动。<br>三、【工作职责】<br>1.获取和整合附近社区楼盘及商圈信息，满足客户需求，提供置业前期的信息服务。<br>2.运用E2E（端到端）理念，用好乐有家APP等数字化大平台，精耕社区，为用户提供“最前一公里”到“最后一公里”的房产交易服务解决方案。<br>3.在精耕的社区及商圈，开展走亲访友式的用户关系维护等工作，服务社区，实地考察房源并提供专业建议，及时促进买卖双方商务谈判。<br>4.在平台强大支撑下，搭档作业，组团服务，为签约双方降低交易成本，控制交易风险，定制新的置业规划。<br>四、发展路径<br>公司支持员工全方位横纵向发展！<br>岗位晋升：置业顾问---置业经理---店长---营销副总经理----营销副总裁----营销总裁<br>明确的职级晋升标准和后备培养机制，帮助下属晋级是考核上级的重要指标；职能、营销晋升通道畅通无阻，助您纵向、横向多维度发展！<br>职位福利：绩效奖金、五险一金、节日福利<br>职位亮点：购买五险一金', '乐有家控股集团为“以房地产经纪为龙头、金融和互联网为两翼”的大型企业集团，成立于2008年，总部位于深圳市，2020年度交易额突破5000亿，在深圳市场占有率稳居行业第一，粤港澳大湾区多个城市市占率稳居行业前列。集团旗下拥有“乐有家”、“顺联担保”、“万顺通资产”、“家家顺物联科技”等优秀品牌，业务涵盖二手房买卖、房屋租赁、项目策划、新房代理、人工智能、资产管理、金融服务等领域，获得“中国十大品牌中介机构”、“全国优秀房地产经纪机构”、“年度最佳雇主”、“最值得信任的地产经纪品牌”、“广东省诚信企业”、“最具影响力雇主”等殊荣。集团始终坚持“真诚正义，先人后己”的核心价值观，积极推行“真服务、真保障”服务战略，为客户提供及时精准、专业可信、高效超值的房产交易全价值链服务。通过运用互联网、人工智能等新技术，打造线上线下一体化的E2E智能生态系统，致力于为客户打造房产交易全过程、全网络、全家庭生命周期的极致服务体验。集团以“立足大深圳、密布珠三角、连锁全中国”为发展战略，有效整合全国各项资源，实现“有家的地方就有乐有家”的宏伟愿景！', 'https://www.zhaopin.com/jobdetail/CC298754310J40548605402.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4374, '律师助理', '广东信达(西安)律师事务所', '7月4日', '2000-4000元', '西安-雁塔区', '法律服务,咨询服务,法律服务', '20-99人', '未融资', 'CC552709630J40781498705', '工作地点：西安或深圳<br>职位要求：<br>1、法学专业本科生(大四)或研究生；<br>2、已经通过司法考试；<br>3、法学专业基础知识扎实，具有较强的逻辑思维能力和法律知识运用能力；<br>4、具备良好的沟通表达能力和法律文书写作能力；<br>5、品行端正，有志于长期从事律师行业，有较强的团队合作精神和服务意识，抗压能力强；<br>6、实习期需1年以上，暂时不接收短期实习。', '广东信达律师事务所（以下简称“信达总所”）成立于1993年，总部位于深圳，是中国早期设立的合伙制律师事务所之一。经过30余年发展，信达已成为以资本市场业务为核心，提供一站式法律服务的综合性律所，在西安、北京、上海、香港、迪拜、广州、武汉、苏州等地设有分所。广东信达（西安）律师事务所（以下简称“信达西安分所”）成立于2017年，是信达总所直接设立、一体化管理的核心分所，坐落于西安市高新区锦业路CBD，交通便利，办公环境优美。信达西安分所致力于成为一家以公司证券、知识产权、财税法为核心业务的中等规模强所，在公司证券、知识产权、财税法、数据合规与监管、私募基金与资产管理、民商事争议解决、房地产与建筑工程、银行与金融、劳动与人力资源等领域拥有丰富经验。信达西安分所现有员工50余名，执业律师30余名，其中多名资深律师担任西安交通大学、西北工业大学、西北政法大学法学教授、陕西省人民政府法律顾问、西安仲裁委员会委员、中国民法学研究会理事、陕西省决策咨询专家委员会委员、陕西省人大常委会立法咨询专家等。信达西安分所是西安交通大学研究生培养育人实习基地，多次被中共西安高新区工委、西安高新区管委会评为优秀律师事务所。信达西安分所秉承共同发展、合作共赢的理念，为提成律师提供具有竞争力的收入提成制度，并采取多种措施助力提成律师成长。信达西安分所为授薪律师、律师助理、实习生提供具有竞争力的薪酬待遇，并缴纳五险一金。具体待遇面谈。', 'https://www.zhaopin.com/jobdetail/CC552709630J40781498705.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4375, 'BD经理', '湖南金浦电子科技有限公司', '4月1日', '8000-15000元', '长沙-芙蓉区', '电子/半导体/集成电路,零售/批发', '20人以下', NULL, 'CC711243430J40327815011', '安装Led显示屏，信息发布软件，液晶拼接屏及银行的电金融产品等等设备', '湖南金浦电子科技有限公司是福建公司长沙分公司，生产基地在福建；其主要经营的产品：湖南省银行的网点设备（显示屏、广告机、排队机、信息发布系统维护、5G智慧设备等等产品）维修、安装公司的工作时间：每月上班:24天(没固定的信息时间、一般周末、超出24天工作有补贴)、在湖南省在到处跑（安装、维修、业务等等）、要求会开车、能搞辛苦活（冲击钻、手电钻、切割机等等简单的使用）、计算机或弱电方面的优先、大专以上的学历、', 'https://www.zhaopin.com/jobdetail/CC711243430J40327815011.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4376, 'APP推广', '福州朴朴电子商务有限公司', '2025-07-27 00:13:40', '8000-16000元', '福州-台江区', '互联网,新零售', '10000人以上', 'D轮及以上', 'CC408522280J40764838210', '岗位职责:<br>1.负责推广公司产品，吸引新用户下载并使用。<br>2.分析市场趋势，找到合适的推广区域。<br>3.与团队合作，完成推广任务。<br>任职要求：<br>1.具有良好的沟通能力和团队合作精神。<br>2.能够快速适应工作环境，学习新知识。<br>3.对推广工作有热情，能够承受工作压力。', '朴朴是一家30分钟即时配送的移动互联网购物平台。品类包含：水果蔬菜、肉禽蛋奶、粮油调味、酒水饮料、休闲食品、个人护理、化妆品、清洁用品、日用百货等。 2016年6月，朴朴正式在福州成立。带着“让每个平凡的人活得更好”的初心和使命，朴朴开启了自己的新零售即时电商之旅。以高频生鲜作为流量入口，所有日常所需一站式购齐。用户足不出户，只需通过手机端APP或小程序轻松下单，30分钟内，我们为用户将物品配送到家。从福州、厦门、深圳、广州，再到武汉、成都、佛山，朴朴所到之地，皆成平价便利之城，目前员工数已突破60000多人。我们希望以创新的商业模式，高效的仓储配送模式，从用户体验出发，打造新一代B2C即时电商平台，作为潜力无限的新零售黑马，未来可期的互联网新锐，目前已经历七轮融资。公司以技术为核心驱动力，以可靠品质推动中国电商环境改善，同时推动中国食品安全进程，立志成为一家让中国消费者喜欢的即时电商公司。我们希望能寻找到优秀的伙伴，携手共创电商新时代。如果你充满激情、敢于创新、勇于挑战，那么，请加入我们，共写即时零售新篇章！', 'https://www.zhaopin.com/jobdetail/CC408522280J40764838210.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4377, '资料管理', '四川金掌柜人力资源有限公司', '7月28日', '8000-10000元', '上海-长宁区', '人力资源服务', '20-99人', NULL, 'CCL1314363420J40763380711', '岗位内容：<br>1. 负责建立和管理公司文档、企业文件、纪录档案等信息资源的分类、整理、归档工作<br>2. 管理文件借阅、销毁、流转等事项，并保障信息的安全性和完整性<br>3. 进行档案数字化化、电子化工作，构建信息化档案管理系统<br>4. 协助编制出资料归档、档案分类、信息检索、档案鉴定、保密审查等各项规章制度<br>任职要求：<br>1. 具有相关学科背景，如档案学、图书馆学等<br>2. 精通文件管理、文献检索、档案鉴定等知识和技能，熟悉档案数字化技术<br>3. 热爱档案工作，具备较强的沟通、协调和组织管理能力<br>4. 有责任心和敬业精神，具备一定的主动性和创新意识', NULL, 'https://www.zhaopin.com/jobdetail/CCL1314363420J40763380711.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4378, '猎头顾问', '天津联礼人力资源有限公司', '7月17日', '7000-12000元', '天津-西青区', '人力资源服务,人力资源服务', '10000人以上', '未融资', 'CCL1281615740J40859478015', '岗位职责：<br>1. 负责进行网络平台招聘、劳务派遣、三方招聘等相关业务活动。<br>2. 维护和拓展客户资源，为客户提供专业的人力资源解决方案。<br>3. 根据客户需求，制定招聘计划并执行，确保招聘效果满足客户要求。<br>岗位要求：<br>1. 具备销售、电销、招聘、劳务派遣、三方招聘中至少一项工作经验，过往工作经历优异者可适当放宽要求。<br>2. 具备良好的沟通能力和商务洽谈技巧。<br>3. 熟悉人力资源行业的相关法律法规及市场动态。', '天津联礼人力资源有限公司（曾用名：天津市联礼劳务服务有限公司），成立于2011年，位于天津市，是一家以从事商务服务业为主的企业。企业注册资本950万人民币，实缴资本950万人民币。许可项目：职业中介活动；劳务派遣服务。（依法须经批准的项目，经相关部门批准后方可开展经营活动，具体经营项目以相关部门批准文件或许可证件为准）一般项目：劳务服务（不含劳务派遣）；人力资源服务（不含职业中介活动、劳务派遣服务）；承接档案服务外包；普通货物仓储服务（不含危险化学品等需许可审批的项目）；企业管理咨询；信息咨询服务（不含许可类信息咨询服务）；会议及展览服务；装卸搬运；生产线管理服务；通用设备制造（不含特种设备制造）；机械零件、零部件加工；电子元器件与机电组件设备制造；金属结构制造；物业管理；家政服务；专业保洁、清洗、消毒服务；业务培训（不含教育培训、职业技能培训等需取得许可的培训）。（除依法须经批准的项目外，凭营业执照依法自主开展经营活动）', 'https://www.zhaopin.com/jobdetail/CCL1281615740J40859478015.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4379, '档案管理', '山西三友和', '5月26日', '3000-6000元', '太原-杏花岭区', '计算机硬件,计算机软件,印刷/包装/造纸', '100-299人', '未融资', 'CC236605110J40449856113', '工作内容：<br>1、负责档案整理，将文件按照要求进行分类整理。<br>2、负责档案扫描，并对图片进行去黑边、纠斜处理等工作。<br>3、负责档案著录，按文件编号进行名称录入，方便查找。<br>4、负责档案装订，并放在指定位置。<br>5、工作内容简单，免费培训上岗。<br>职位要求：<br>1、熟练使用计算机及office办公软件；<br>2、工作有条理、责任心强<br>3、有较强的学习能力和团队合作精神<br>4、有很强的保密意识，有良好职业操守，无不良犯罪记录。<br>晋升机会：<br>1、培训上岗，试用期三个月，优秀人员可提前转正；<br>2、晋升通道：数字化加工专员 – 小组负责人 – 项目负责人 – 部门技术负责人 – 部门经理<br>3、在公司工作半年以上能够申请小组负责人，享受管理人员津贴。<br>公司福利：<br>1、重大节日津贴<br>2、员工生日津贴<br>3、年终评优奖励<br>4、年度体检<br>5、带薪休假<br>', '山西三友和智慧信息技术股份有限公司始创于1996年，经过二十年的高速发展,于2016年在“新三板”上市(股票代码：NEEQ:839220)。是专业从事档案信息管理系统的研发、档案整体规划、设计、档案咨询服务、影像扫描、档案网站建设、档案信息服务、档案办公自动化系统集成等业务为一体的双软、高新技术企业。三友和以档案信息化产品服务为核心，是山西档案软件市场的领跑者，被评为省级新型研发机构、山西省中小企业公共服务示范平台、山西省专精特新中小企业、山西省信息技术应用创新工作委员会理事单位和省级产学研新型研发机构。今天，已有超过1000家合作伙伴选择三友和作为发展平台。三友和始终秉承“服务档案信息化发展,推动档案信息化建设进程”的企业宗旨，恪守“严谨、热情、团结、创新”的核心价值观，二十年如一日坚持档案软件建设。今天，三友和以“推动档案数字化建设“为使命，以”服务中国档案信息化”为愿景，秉承“用户至上”的产品服务理念，致力于成为中国档案数字化建设领先者。公司拥有涉密信息系统集成资质、涉密信息系统集成工程监理资质、涉密档案数字化加工资质，取得档案行业二项发明专利：《三友和智慧档案大数据平台》、《全自动档案文件扫描机器人》；十三项\\\\\"SYH档案管理系列软件\\\\\"国家版权局软件著作权、通过了国家档案局的行业测评。', 'https://www.zhaopin.com/jobdetail/CC236605110J40449856113.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4380, '运营助理/专员', '中国平安', '7月2日', '面议', '南阳-卧龙区', '保险,保险', '10000人以上', '已上市', 'CC000204810J40760150812', '🔸世界五百强平安运营项目🔸<br>✅工作时间 09:00-18:00午休两小时工作七小时⚠绝不加班，到点下班，五险一金<br>🍉固定周末双休，法定假日带薪休假，丰富团建及下午茶丰盛<br>🔥🔥薪资构成<br>基础底薪(2800-3600)面试根据过往工作经历定+新人津贴持续一年(1000-10000每月)+转正加职级津贴(500-700)+过节费+激励方案+高绩效提成(10-50%)<br>✅新人入职实习学习期1-3月工资5-7k左右✅在职员工4月以上综合人均工资8-18k左✅右高提成:客户续费产品以及总金额不等10-50%<br>✅新人津贴发放一年，一年后有续费津贴也会高于(1000-10000每月)<br>😘😘😘福利待遇<br>1.入职签订合同，平安的超多福利待你解锁<br>2.公司提供专业培训，素拓，聚餐等活动，优秀者可进入深圳平安大学进阶学习<br>3.世界五百强提供多元化晋升机会，内部三条职能发展线路，灵活跨岗位发展机制，为所有员工提供全面发展的机会<br>4.发放丰厚的奖励，优秀员工每月有表彰<br>🥳🥳🥳工作环境<br>5A级写字楼办公环境，中央空调，入职分配平板电脑，冰箱微波炉等设备齐全<br>🛍🛍🛍员工关怀<br>1.为员工提供多途径反馈工作、生活中遇到的问题困难，通过面对面圆桌会，线上答疑等方式给予解助<br>2.为家庭特别困难员工提供帮助，领导可爱同事暖心', '中国平安致力于成为国际领先的科技型个人金融生活服务集团。2019年，中国平安深入推进\\\\\"金融+科技\\\\\"、\\\\\"金融+生态\\\\\"战略转型，持续提升数据化经营能力，整体业绩及核心金融业务持续稳健增长，科技赋能成效显著，生态赋能效果初显，综合金融用户数、客户数、客均合同、客均利润均有明显增长。公司实现营业收入同比增长19.7%至11,688.67亿元。截至2019年底，公司个人客户数首次突破两亿，互联网用户量达5.16亿，全年新增客户数3,657万，其中40.7%来自集团五大生态圈的互联网用户。中国平安始终践行\\\\\"金融为实体经济服务\\\\\"的精神，坚持把实体经济服务作为出发点和落脚点，通过旗下的保险、银行、信托、金融科技等业务，把逾4万亿金融资源配置到经济社会发展的重点领域和薄弱环节，包括通过保险保障、提供贷款、债权股权计划、普惠金融等多种方式，全面助力实体经济发展。凭借全球领先的创新科技，中国平安将科技深度运用于金融主业中，助力降本增效、风险管控，打造优质产品和极致服务体验，提升客户口碑。与此同时，平安将领先科技广泛应用在金融、医疗及智慧城市等领域，全面支撑\\\\\"金融服务、医疗健康、汽车服务、房产服务、智慧城市\\\\\"五大生态圈建设。在企业社会责任方面，平安深化可持续发展理念，MSCI ESG评级连续两次调高至A级，打造AI-ESG平台赋能责任投资，截至2019年12月末，公司责任投资规模达9,544.49亿元，可持续保险金额达121.21万亿元，绿色信贷年度授信总额590.56亿元。同时，平安积极响应国家脱贫攻坚战的号召，推进\\\\\"三村扶贫工程\\\\\"项目，累计提供专项扶贫资金249.05亿元。面对新冠肺炎疫情，平安第一时间推出保险保障、医疗支持、对外捐赠等多重支持举措，提供的物资及现金捐赠总额超1.75亿元。2020年，中国平安品牌价值持续提升，名列美国《财富》“世界500强企业”第21位，居全球金融企业第2位，《福布斯》全球上市公司2000强第7位，BrandZ™全球品牌价值100强第38位，蝉联全球保险品牌第1位。', 'https://www.zhaopin.com/jobdetail/CC000204810J40760150812.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4381, '律师', '广东良马律师事务所', '7月8日', '8000-13000元', '深圳-南山区', '法律服务,法律服务', '100-299人', '未融资', 'CC516867280J40773997103', '【业务领域】合同审核、民商事诉讼方向<br>【岗位职责及要求]<br>1、熟知民商事诉讼案件流程，具备独立处理案件能力；<br>2、有诉讼经验的优先；<br>3、法律基础扎实，具备良好的法律逻辑思维，责任心强，有耐心，细心；<br>4、有较强的学习能力、执行能力、分析能力、抗压能力强。<br>【工作待遇】薪资待遇具体面议<br>【简历投递】******** 24 9@qq.co m，备注授薪律师', '良马筹备于2014年，正式设立于2016年，坐落于中国“硅谷”——深圳！设立之初，良马是专注于知识产权的双证精品律所——既是律师事务所，又是由国家知识产权局批准设立的专利代理机构。成立伊始，创始团队充分发挥了兼具有法律及理工科复合型专业背景的优势，成功代理了多宗具有广泛影响力的知识产权案件，以“黑马”姿态进入了公众视野，并获得了多项知识产权领域的荣誉。短短几年，秉持“专业致远，不负所托”的价值观，良马得到了越来越多的认可，自有规模和业务总量不断增长，办公场地面积不断扩大。现有办公面积2080平，设有45个房间，138个卡座，4个洽谈室，2个茶室，2个会议室，2个档案室，1个茶水间。为了不辜负客户的信任，满足客户多元化的法律需求，良马通过持续吸纳各领域专业团队，不断地辐射多元化的法律服务领域：婚姻家事、政府及企业法律顾问、股权融资、商事仲裁、刑事辩护、民商诉讼、国际贸易……打造“知识产权领先、多领域深耕发展”的湾区特色综合律师事务所是良马新一阶段的发展目标，并将逐步发展为全国性的综合大所。“竭良马之智，捍客户之利”是我们立志践行的使命，我们愿为做一家深受景仰的律师事务所而不断努力、奋进，在大湾区及全国的法治建设事业中写下浓墨重彩的壮丽篇章！', 'https://www.zhaopin.com/jobdetail/CC516867280J40773997103.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4382, '招聘专员/助理', '上海太屋网络科技有限公司', '7月19日', '6000-12000元·13薪', '上海-徐汇区', '房地产开发', '1000-9999人', '未融资', 'CC294547880J40814837203', '岗位内容：<br>1. 设计并执行招聘计划，确保高质量的招聘结果并控制成本<br>2. 与业务部门紧密合作，理解各个职位的技能需求并寻找合适的候选人<br>3. 分析招聘数据，探索新的招聘渠道和方式<br>4. 建立和维护候选人的数据库并进行有效的跟进工作<br>任职要求：<br>1. 本科及以上学历，人力资源管理、市场营销等相关专业优先考虑<br>2. 至少2年以上招聘工作经验，有成功的招聘案例和资源库管理经验者优先<br>3. 具备敏锐的市场洞察力和创新意识，熟练使用数据分析工具和招聘软件<br>4. 出色的沟通、协调和推动能力，能够快速适应多任务、高压环境', '太屋集团太屋集团始创于上海，是一个以“服务于人类居住”为核心的集团化企业。集团立足于房地产服务行业，历经30年发展，企业从房地产经纪、房地产咨询代理、商业招商等业务模块开始起步，逐步发展出资产管理、供应链金融、地产开发、互联网科技、职业教育等全新业务模块，伴随着20多家子公司和5个子品牌的相继成立，企业开始走向集团化发展的道路。太屋集团一直以来秉承“锐意进取，开拓创新”的发展理念，以品质服务赢得社会各界的广泛认可和客户的高度信赖。多品牌运营，创建地产生态圈太屋集团旗下拥有【太平洋】和【菁英】2大主力地产服务品牌，形成了太平洋经纪、太平洋房屋、太平洋置业、太平洋物业、菁英地产、菁英置业、菁英物业等众多房地产领域的独立企业；同时，还拥有【太屋网】、【菁铧】、【王典】这3大品牌，分别涉足地产网络科技、供应链金融、资产管理等相关行业；集团业务重心始终围绕着“居住产业”，希望通过多元化、产业化、平台化的发展，从房地产一级市场到三级市场，业务扩展到房地产行业全产业链，创建企业化的地产生态圈。【太平洋房屋】1994年成立于上海，集团于2004年接手该企业，成为集团旗下的主力企业之一。太平洋房屋作为上海房地产经纪行业协会的副会长企业之一，伴随着上海房地产市场的发展不断壮大。目前，公司业务范围覆盖全上海13个大区，拥有600家线下门店，10000名专业经纪人，年累积交易金额达5000多亿元，市场市占率稳居上海前二！公司历经30年的发展，100多个业界奖项与殊荣铸就了企业发展的历史，其中，上海市白玉兰纪念奖、蝉联18届“金桥奖”的殊荣等历史荣誉都是太屋人的骄傲。作为行业的领跑者和颠覆者，太屋集团整合旗下地产类各项业务，开创【太屋网】这一全新品牌，以“安心托付，幸福满屋”的经营理念，打造全产业链的房地产服务平台，让集团业务从线下向多元化、产业化、平台化方向发展……企业商学院，孵化企业人才团队随着集团业务规模不断扩大，企业的人才战略将成为决定集团未来发展的重要指标。2019年，上海太屋教育科技有限公司正式成立，我们集团的商学院——“太屋大学”也孕育而生。太屋大学，拥有强大的师资团队，以及由行业翘楚和权威专家组成的客座教授团体；建立了课程培训、名家讲堂、拓展训练、全球游学等科学化系统化的教学培训体系，针对行业的不同岗位和职务，开展有针对性的职业教育与培训，为企业人才赋能，共同创造价值。热心公益，企业向上向善的力量扶危渡厄，使命担当。太屋集团始终以“成就员工以成就企业，成就企业以回报社会”为愿景，时刻肩负着企业的社会责任，积极投身于公益事业。太平洋爱心基金、阳光之家公益活动、环卫工人“爱心接力站”、红马甲社区志愿者、免费社区便民服务、高考加油站、垃圾分类志愿互动……在此次新型管状病毒疫情的抗疫过程中，集团立即组织捐赠大量医疗物资，火线驰援抗战在一线的医疗单位。在点滴的生活中，太屋人始终用一颗向善之心，让世界多一份美好……太屋集团，一个有理想、有信仰、有温度、有情怀、有灵魂的集团企业，期待您的加入！', 'https://www.zhaopin.com/jobdetail/CC294547880J40814837203.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4383, '储备经理人', '安徽大海家政集团有限公司', '7月19日', '5000-10000元', '合肥-蜀山区', '家政服务,物业管理,工程施工,居民服务', '500-999人', NULL, 'CCL1429049030J40608939409', '岗位内容：<br>1. 公司各部门轮岗，承接和完成指派的各种任务，并向领导汇报结果。<br>2. 协助处理日常事务和项目。<br>3. 学习公司模式，对市场形势进行分析研究，参与制定公司战略规划。<br>任职要求：<br>1. 大学期间在班级、院系做过班委及领导职务的优先。  2、本科及以上学历，沟通表达能力和学习能力强，热爱挑战，有成功意愿和独立思考能力。', '招聘愿景：一、吸引一线城市回流人才1、我们诚挚欢迎在一线城市工作过的人才回归，加入我们共同建设家乡。一线城市的工作经历使您具备了先进的工作理念和高效的工作方法，而我们为您提供了将这些宝贵经验应用于家乡发展的广阔舞台。您能够为公司带来新的思路和突破，助力我们在本地市场脱颖而出。2、我们根据您的能力和经验，量身定制合理的薪资结构，让您的收入水平与一线城市接轨。3、让您能够充分施展才华，展现个人能力，成为公司发展的核心力量。二、家政物业行业的广阔前景1、家政物业行业作为朝阳产业，正处于快速发展的黄金时期，潜力巨大。随着人们生活水平的提高和工作节奏的加快，对家政服务和物业管理的需求日益增长，市场空间广阔。2、近两年国务院常务会议多次提到家政行业。政策的支持和社会的关注，使得家政物业行业的发展环境日益优化，为企业的成长提供了有利条件。3、家政行业由于起步晚，科技含量不是很高，一般不被人重视。因此给从业者留着充分的发展空间，很可能实现职业成功的弯道超车。4、其行业对高领从业者很友好，不因年龄大而被淘汰反而更占优势，特别是女同志，可以做的退休的年龄。为员工提供更多的发展机会。公司介绍：安徽大海家政集团有限公司成立于2004年7月1日,注册资金2004万，是由历届大学生组织的优质服务团体，故:“大海-------大学生下海”的意思。是一家专业提供高端精细保洁服务的服务公司。在全国家政行业中具有较强的竞争优势。大海公司成立以来,一直致力于为客户提供便捷的服务。并研发投入使用安徽省家政企业专用数据库。公司分别在合肥市包河区、蜀山区、庐阳区、瑶海区和经济开发区、巢湖市共设立了7家分公司，会员客户突破10万家。目前开展的业务有:家政服务、清洗保养、物业托管、高空作业、保安服务、管道清洗、专业培训,以及新增的整理收纳服务业务，让您享受精致的生活方式。企业荣誉：2010年被国家商务部评为“合肥市家政龙头企业”。v 2011、2012、2015年安徽唯一一家连续 3年被国家人社部评为“全国家政百强企业”。v 2012年被安徽省人社厅评为“安徽省家政企业先进单位”。v 2012年大海两名员工被评为“合肥市优秀家政服务员称号”。v 2012年被商务部认定为“重点流通企业检测企业”。v 2013年被安徽省商务厅评为“放心家政”龙头企业。v 2013年我公司总经理吴海峰同志荣获安徽省“优秀民营企业家”荣誉称号。v合肥市工商联总工会会员单位。v 2014年被批准为安徽省服务业标准化试点单位并通过验收。v 2015年安徽省清洗保洁行业协会副会长单位。v 2016年建筑物清洁委员会会员单位。v 2017年被合肥市人力资源社会保障局选定为“合肥市高校毕业生就业见习基地”。v 2019年 6月通过安徽省服务业标准化试点单位评估验收。v 2020年起草省级地方标准《员工制家政企业管理规范》已发布。v 2021年被批准为国家级标准化试点单位。v 2020年大海职业培训学校批准。v 2020长三角家政服务百强企业。v 2020疫情防控先进集体v 2020年爱心服务优秀企业。v 2020年度最佳公益企业。v 2021年包河区放心满意消费示范单位v 2021年中国家庭服务业先进会员单位v 2022年度优秀服务供应商v 2022年安徽省放心满意消费示范单位v 2022年度优秀志愿服务组织v清洗保洁企业二级等级资质v 2022年度疫情防控先进企业v 2022年安徽家庭服务行业突出贡献单位v 2022年安徽家政服务诚信经营先进企业。v 2022年度省级优秀家政服务企业', 'https://www.zhaopin.com/jobdetail/CCL1429049030J40608939409.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4384, '培训师', '河南储汇企业管理咨询有限公司', '7月14日', '1-2万', '郑州-中牟县', '银行,银行', '20-99人', '未融资', 'CC532572230J40791877912', '【岗位职责】', '河南储汇企业管理有限公司成立于2017年3月，注册资金6001万，以下简称“河南储汇”。河南储汇自成立以来，公司不断拓展业务、开发和探索新的业务品种、推出新的平台，通过规范化管理、多元化合作、多项化选择，现有员工30余人，本着“以人为本、诚信合作、高质高效”的经营理念，充分挖掘中小微企业领域的金融需求，致力于个人及企业经营融资的标准化与普惠化。河南储汇对接各大国有银行、股份制商业银行、城市商业银行、外资银行等金融机构，在同行业稳列前茅，吸引众多银行与金融机构争相与我司洽谈合作。为大家提供一个广泛优质平台，更大发展空间，携手共赢！', 'https://www.zhaopin.com/jobdetail/CC532572230J40791877912.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4385, '招聘专员/助理', '鑫俊达(沈阳)物流管理有限公司', '7月25日', '3000-6000元', '沈阳-沈河区', '货运/物流/仓储', '500-999人', '未融资', 'CCL1453207630J40777115007', '岗位内容：<br> 负责编写和发布招聘信息，筛选简历，后续跟踪员工入职情况<br>任职要求：<br>1.18-55岁男女不限<br>2.无犯罪记录<br>3.高中以上文凭<br>工作时间:<br>早8.30-晚5.30，早9-晚6（个人可选择）<br>薪资待遇:<br>无责底薪2800+满勤200<br>转正公司提供五险<br>每周一天休息（可自己选择）', '鑫俊达（沈阳）物流网络管理有限公司是一家从事食品销售,国内货物运输代理,技术服务等业务的公司，成立于2022年11月10日，公司坐落在沈阳市，详细地址为：辽宁省沈阳市沈河区大西路360-4号;经国家企业信用信息公示系统查询得知，鑫俊达（沈阳）物流网络管理有限公司的信用代码/税号为91210103MAC1WJ2P3W，法人是米男，注册资本为5万人民币，企业的经营范围为:许可项目：食品销售（依法须经批准的项目，经相关部门批准后方可开展经营活动，具体经营项目以相关部门批准文件或许可证件为准）一般项目：国内货物运输代理；技术服务、技术开发、技术咨询、技术交流、技术转让、技术推广；礼仪服务；装卸搬运；餐饮管理；企业管理咨询；市场营销策划；会议及展览服务；广告设计、代理；信息咨询服务（不含许可类信息咨询服务）；社会经济咨询服务；外卖递送服务。（除依法须经批准的项目外，凭营业执照依法自主开展经营活动）', 'https://www.zhaopin.com/jobdetail/CCL1453207630J40777115007.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4386, '咨询顾问', '成都鼎合创赢信息技术咨询有限公司', '2025年07月30日', '5000-9000元', '成都-武侯区', '企业服务', '20人以下', '未融资', 'CCL1508438570J40699585306', '任职要求:<br>1.普通话标准，形象气质佳，沟通能力强<br>2.口齿清晰，普通话流利语言富有感染力;<br>3为人正直真诚，良好的个人信誉及职业操守，<br>4.年龄20-30岁;<br>5.有责任心，能承受较大的工作能力;<br>6.有销售经验者优先，接受小白，带薪培训;<br>7.注重团队合作，有集体荣誉感，追求上进。     工作内容：   <br>       1.充分了解市场需求，研究跟踪市场结构变化，及时做出相应的销售方案;', '不是电销公司！！！不是电销公司！！！办公环境舒适，公司氛围良好，公司都是帅男靓女。薪资待遇：4000+500满勤奖，每周会有200-500元奖励不等。业务奖金：5%，开单奖励也会有开单奖励。上班时间：早九晚六午休1.5个小时法定节假日正常休息。岗位名称：信息咨询顾问，FA，网络销售岗位职责：主要负责项目前期业务，项目尽调，提供解决方法，以及商业BP的筛选。任职要求：年龄20-30岁大专学历以上，具备良好的语言表达能力，心里素质好，有一定的抗压能力、有销售经验的优先，无经验也可以培养，入职日起既享受正式员工的薪资待遇。', 'https://www.zhaopin.com/jobdetail/CCL1508438570J40699585306.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4387, '统计员', '呼伦贝尔查干矿业有限公司', '6月27日', '8000-9000元', '呼伦贝尔-新巴尔虎右旗', '矿产/采掘', '100-299人', '不需要融资', 'CC303017820J40680881109', '1.40周岁以下；<br>2.能够熟练操作word/excel等电脑办公软件；<br>3.具有良好的沟通协调能力；<br>4.有扎实的文案起草和撰写能力；<br>5.能力优秀者可适当放宽条件。 <br>', '呼伦贝尔查干矿业有限公司成立于1996年11月12日，注册地位于内蒙古自治区呼伦贝尔市新巴尔虎右旗阿日哈沙特镇，注册资本8000万元，企业性质为国有。隶属黑龙江省地质矿产局。公司执行董事、经理成学光。经营范围包括铅、锌、银、铜等产品的采选、冶炼、加工、销售;硫加工、销售。公司目前下辖8个主要职能部门:安全管理部、财务管理部、党政综合部、后勤管理部、机械动力部、技术管理部、企业发展部、生产管理部。公司目前拥有两个采矿系统，分别是本区(中央竖井)采矿系统和十号矿体采矿系统，同时拥有日产能1000吨/选矿厂一处、尾矿库一处以及蓄水池、材料库、火工炸药库、办公楼、职工宿舍、食堂、体育馆等生产、生活附属设施。', 'https://www.zhaopin.com/jobdetail/CC303017820J40680881109.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4388, '销售工程师', '江苏亚电科技股份有限公司', '6月30日', '9000-18000元', '泰州-姜堰区', '专用设备制造,电气机械/电力设备,电子设备制造', '300-499人', 'B轮', 'CC861330130J40761820602', '【工作内容】<br>- 负责公司半导体湿法设备的销售工作，开拓新市场及新客户。<br>- 深入了解客户需求，为客户提供专业的解决方案。<br>- 定期拜访客户，维护良好的客户关系，提高客户满意度与忠诚度。<br>- 收集市场及竞争对手信息，分析行业趋势，制定有效的销售策略。<br>- 完成个人销售目标，参与团队销售目标的达成。<br>【任职要求】<br>-统招一本及以上学历，机械、电气理工科、市场营销等相关专业。<br>- 具备较强的沟通能力、谈判技巧及客户服务意识。<br>- 熟悉半导体行业或相关领域的知识者优先。<br>- 具备一定的市场分析能力，能够独立完成客户开发及维护工作。<br>- 接受较多出差，工作积极主动，具备良好的团队合作精神及抗压能力。<br>- 英语好、会韩语、有设备销售经验者优先，优秀应届生亦可。', '亚电科技是半导体晶圆制造行业湿法制程设备商,专注于晶圆前道湿法刻蚀清洗技术,是国内首批推进半导体高端设备国产化的企业之一，目前公司在江苏无锡和海外设立了研发基地。亚电的核心产品包括8吋、12吋槽式/单片湿法刻蚀清洗设备，作为一家拥有自主知识产权的高新技术企业，所有核心技术均已申请发明专利。通过多年的技术研发和积累，亚电通过多样化、个性化的解决方案致力于为客户提供更有竞争力的产品和服务。我们的总部坐落于江苏泰州，占地120亩，员工近500人，本科及以上学历人数占比达80%；目前公司在国内外分别设立了独立的研发中心和生产基地。我们注重产品研发人才梯队的建设，我们拥有优越的办公环境、优秀的国内外高端技术人才队伍和先进的人才培养理念；我们拥有科学、高效的人才选拔和任用机制，能够激励员工不断创新，充分发挥自己的才干与潜能；我们尊重劳动、尊重知识、尊重人才，我们重视学习、重视创造，不论您是经验丰富的大牛还是初入职场的萌新，亚电都将为您提供广阔的发展空间，为您搭建实现自己人生价值和梦想的舞台！亚电科技欢迎您的加入！泰州地址：泰州市姜堰区山水街道科技大道151号无锡地址：无锡新吴区国家软件园海豚座B1座1层公司网址：www.aelsystem.com', 'https://www.zhaopin.com/jobdetail/CC861330130J40761820602.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4389, '资料管理', '中国人寿保险股份有限公司郑州市分公司', '2025年07月30日', '6000-8000元', '郑州-金水区', '保险', '1000-9999人', '已上市', 'CC253842210J40782613302', '职位描述<br>资料整理资料收集<br>1.老客户信息整理、资料维护、保单检视及客户加保。<br>2.部门领导安排的其他工作。<br>【任职要求】:<br>1.教育程度:大专及以上学历，年龄23-45岁；<br>2.工作经验:有相关从业经验者优先;<br>3.核心素质:沟通能力，执行力;<br>4.应变能力、执行能力强、富有激情；<br>5.具有较强的团队精神。<br>职位福利：绩效奖金、补充医疗保险、通讯补助、定期团建、出国游、全勤奖、项目奖金、多次晋升机会', '中国人寿保险（集团）公司是目前国内最大的综合性保险集团，是国务院100%控股的世界500强副部级央企。下设中国人寿保险股份有限公司、中国人寿资产管理有限公司、中国人寿财产保险股份有限公司、中国人寿养老保险股份有限公司等多家公司和机构，业务范围全面涵盖寿险、财产险、养老保险、资产、实业投资、海外业务等多个领域。中国人寿是中信证券第二大股东、广东发展银行第一大股东、民生银行、中粮期货、南方电网第二大股东。中国人寿郑州市分公司招募首批新型大学生服务团队中国人寿郑州市分公司一直服务于郑州市城乡建设，在郑州市所有县区设立分支机构，在全市80%以上的乡镇设立服务部，目前服务窗口正在向村级延伸。自2001年起，开始陆续为河南省省直机关以及郑州市220万城镇职工、城镇居民提供大额补充医疗服务，具有常年经营意外保险、健康医疗保险以及政府委托经办业务等丰富的管理经验和能力。2011年，在郑州市政府的支持下，中国人寿郑州市分公司创新性地经办了新农合业务，并于2013年开始承办农村居民大病保险业务，服务于430万农村居民，“郑州模式”得到全国广泛关注。', 'https://www.zhaopin.com/jobdetail/CC253842210J40782613302.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4390, '售后客服', '太平人寿保险有限公司黄石中心支公司', '7月17日', '3000-5000元·13薪', '黄石-西塞山区', '保险', '1000-9999人', '已上市', 'CC228322220J40652261902', '我们正在寻找一位专业的售后客服，<br>负责处理客户的咨询、投诉与建议，确保客户满意度。<br>工作内容：<br>1.电话提醒客户续期缴费<br>2.通知客户权益领取<br>3.处理客户咨询、投诉及建议<br>岗位要求：<br>1. 大专及以上学历，有售后客服经验者优先；<br>2. 良好的沟通能力和服务意识，能解决客户问题；<br>3. 熟练使用常用办公软件；<br>4. 责任心强，有团队精神，能承受一定的工作压力。', '太平人寿隶属于中国太平保险集团有限责任公司（以下简称\\\\\"中国太平\\\\\")，是国内大型寿险企业之一。公司总部设在上海，注册资本100.3亿元，总资产超10000亿元，目前已开设包括38家分公司在内的1400余家机构，服务网络基本覆盖全国。凭借稳健的财务表现，太平人寿连续八年获得惠誉国际\\\\\" A+\\\\\"（强劲）财务实力评级。同时，公司已连续七年在中国保险行业协会公布的保险公司法人机构经营评价中，获评 A类。中国太平是管理总部设在香港的中管金融企业，是我国历史上持续经营最为悠久的民族保险品牌，已连续六年入选《财富》世界500强。\\\\\"十四五\\\\\"时期，中国太平立足新发展阶段，贯彻新发展理念，服务构建新发展格局，按照\\\\\"央企情怀、客户至上、创新引领、价值导向\\\\\"的战略要求，积极服务国家战略和民生保障，促进\\\\\"双循环\\\\\"，维护\\\\\"一国两制\\\\\"和港澳长期繁荣稳定，践行\\\\\"共享太平\\\\\"发展理念，开启高质量发展新篇章，努力打造中国保险业最具价值成长的国际化现代金融保险集团。依托集团综合性、多元化经营平台，太平人寿不断拓宽个人代理、银邮代理、服务拓展、电话销售、网络销售等服务渠道与方式，提供涵盖人寿、意外、健康、年金等多种类型的保险产品，同时公司积极推动\\\\\"医康养\\\\\"生态圈建设，为客户提供周全的保险保障和一站式、一揽子金融保险服务。作为中国太平成员公司，太平人寿积极参加国家重大战略实施，提升服务民生质效。始终坚持以客户为中心、高质量发展的经营思路，坚持品质管理，推动业务价值和规模的协同发展。截至2023年6月底，太平人寿期末有效保险金额超320000亿元累计服务客户超7500万人，支付理赔款和生存金总额超1995亿元。', 'https://www.zhaopin.com/jobdetail/CC228322220J40652261902.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4391, '广告销售', '诚和致远科技集团有限公司', '5月16日', '4000-8000元', '上海-宝山区', '印刷/包装/造纸,零售/批发', '100-299人', '未融资', 'CC397151520J40767123715', '任职要求：<br>招聘应届生<br> 性格开朗，善于沟通，具备良好的心理素质和团队协作精神。 <br>有耐心、细心、同时具备培训和讲解工作内容流程的能力。 <br>岗位职责：<br>1、 商务开单后，根据订单完成拣货。<br>2、 根据订单，完成采购下单工作。<br>3、 收集客户反馈的问题，及时汇报领导。<br>4、 票据整理以及上报总部。<br>5、开具发票、以及相关信息的登记。<br>6、具有团队合作精神，愿为公司的发展尽力。', '诚和致远商业集团有限公司成立于2010年，注册资本1亿元，是国内知名的办公综合服务提供商。我司已通过ISO9001质量管理体系、ISO14001环境管理体系以及OHSAS18001职业健康安全管理体系等多项认证。公司秉承以客户服务为核心的经营理念，提供精准、便利、省心的一站式服务，经过多年经营，我司已成为了业内知名品牌直营商。为响应国家“阳光采购、高效办公”的号召，我司顺应“互联网+政府采购”的经营模式，整合了办公用品、文具耗材、办公设备、劳保用品、家用电器、电脑及外设、数码产品、运动户外、日用百货等资源，拥有SKU数量四万余。以满足广大用户需求并为其提供全面的线上和线下一站式综合办公服务。“诚信、周到、精准”是诚和致远人的核心服务理念，精益求精、贴心优质的服务旨在为广大用户提供精妙绝伦的精彩呈现。', 'https://www.zhaopin.com/jobdetail/CC397151520J40767123715.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4392, '猎头顾问', '华世先达咨询(北京)有限公司', '2月17日', '5000-10000元', '武汉-武昌区', '人力资源服务,企业服务,人力资源服务', '100-299人', NULL, 'CC254027630J40633317011', '岗位职责:  <br>', '2014年，华世先达咨询（北京）有限公司正式宣布成立，作为一家合伙人制的高端猎头公司，专注于芯片半导体、高科技互联网、医疗大健康、清洁能源、先进制造等细分行业的中高端职位，通用职能招聘及企业咨询服务，致力于和行业领先的企业和优秀候选人建立起深度的长期战略合作伙伴关系。华世先达总部设立于首都北京，分支机构分布在上海、深圳、武汉、长沙、天津、苏州等地，目前公司有近两百人的成熟顾问团队，数十位高级合伙人，专注于年薪百万以上的精英人才寻访，为全球超过 500家头部企业提供高端猎头服务。面向未来，华世先达紧跟国际化浪潮，敏锐察觉行业变化，凭借专业的顾问团队+大数据解决方案+强大的海内外人才体系+高效的交付协作，通过对候选人质量的承诺、诚信、专业和效率把控，在最短的时间内助力客户引进国际化人才、复合型人才、商业领袖、技术领袖等顶尖人才，在数智化驱动下促进客户业务快速发展，技术不断创新，实现商业成功。', 'https://www.zhaopin.com/jobdetail/CC254027630J40633317011.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4393, '资料管理', '中国人寿保险股份有限公司郑州市分公司', '2月16日', '5000-7000元', '郑州-金水区', '保险', '1000-9999人', '已上市', 'CC253842210J40602439702', '职位描述：<br>1.负责老客户信息、资料的整理、归档和保管;<br>2.提供保单资料查询服务；<br>3.完成部门领导安排的其他相关工作。<br>任职要求：<br>1.大专及以上学历，优秀者可放宽条件<br>2.沟通能力强，执行力强，富有激情', '中国人寿保险（集团）公司是目前国内最大的综合性保险集团，是国务院100%控股的世界500强副部级央企。下设中国人寿保险股份有限公司、中国人寿资产管理有限公司、中国人寿财产保险股份有限公司、中国人寿养老保险股份有限公司等多家公司和机构，业务范围全面涵盖寿险、财产险、养老保险、资产、实业投资、海外业务等多个领域。中国人寿是中信证券第二大股东、广东发展银行第一大股东、民生银行、中粮期货、南方电网第二大股东。中国人寿郑州市分公司招募首批新型大学生服务团队中国人寿郑州市分公司一直服务于郑州市城乡建设，在郑州市所有县区设立分支机构，在全市80%以上的乡镇设立服务部，目前服务窗口正在向村级延伸。自2001年起，开始陆续为河南省省直机关以及郑州市220万城镇职工、城镇居民提供大额补充医疗服务，具有常年经营意外保险、健康医疗保险以及政府委托经办业务等丰富的管理经验和能力。2011年，在郑州市政府的支持下，中国人寿郑州市分公司创新性地经办了新农合业务，并于2013年开始承办农村居民大病保险业务，服务于430万农村居民，“郑州模式”得到全国广泛关注。', 'https://www.zhaopin.com/jobdetail/CC253842210J40602439702.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4394, '项目专员/助理', '上海外服江苏人力资源服务有限公司', '7月14日', '6000-7000元·13薪', '南京-建邺区', '人力资源服务,人力资源服务', '1000-9999人', '已上市', 'CC238503680J40772261607', '1.协助业务组客户经理按照项目上报要点完成上报材料的整理与系统录入，维护与更新客户信息<br>2.根据合同制作要点完成合同制作、合同审核及用印流程<br>3.收集包含合同在内的放款资料，按照审核要点进行要件核查，材料错漏短缺情况及时通知客户经理或经销商，积极跟踪，辅助业务投放<br>4.处理部门综合运营事务，严格把控资金管理， 及时提醒租金回收，并完成ukey复核、租金核销、发票寄送等<br>5.协助业务开展正常类项目回访，落实租后管理任务，协助完成租后变更事项，做好资产相关数据统计及分析', '上海外服江苏人力资源服务有限公司，是在南京市外事服务有限公司人力资源业务服务的基础上(1987年成立)，于2005年12月由南京市外事服务公司和东浩兰生集团上海外服（集团）有限公司共同出资组建的专业从事人力资源服务的有限公司。我公司目前服务于来自100多个国家和地区的3,000余家公司，同时服务于约70,000余名在这些机构当中从事着管理、顾问、技术研发、市场、销售、人力资源、行政等不同工作的各国员工。服务涉及通讯、电子、汽车、石化、消费品等众多行业的精良客户群体，世界500强企业中100余家选用我们的服务。大客户包含：福特、华润、联通、ABB、港龙、五星电器等', 'https://www.zhaopin.com/jobdetail/CC238503680J40772261607.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4395, '统计员', '大连艺境空间装饰工程有限公司', '7月25日', '4000-6000元', '大连-甘井子区', '装饰装修', '20-99人', NULL, 'CCL1391868640J40564376212', '工作内容：<br>协助常务董事做好质量、研发、技术端的过程监督，负责公司文件管理、文稿撰写、会议记录等。<br>职位要求：<br>- 工作过程具有较强的原则性，具备良好的沟通技巧、较强的的文字表达能力以及数据分析能力；<br>- 熟练掌握办公软件，如Word、Excel、PowerPoint等；<br>- 良好的时间管理能力，能够适应工作中的压力；<br>- 具备团队协作精神，责任心强，工作态度认真积极；<br>-大专以上学历，年龄25-30周岁。年龄要求：25-30岁<br>', NULL, 'https://www.zhaopin.com/jobdetail/CCL1391868640J40564376212.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4396, '风电工程师', '内蒙古自治区企华风电有限公司', '7月23日', '9000-12000元', '赤峰-松山区', '工业自动化', '20人以下', NULL, 'CCL1504753470J40757089101', '风电：内蒙古为中国风力发电基地，乌蒙核心区，全国安排，先总部录取，后按志愿分配。<br>工作地点:全国范围均可安排， 内蒙古（呼和浩特、乌兰察布、包头、鄂尔多斯等）<br>岗位及职责：<br>对机组进行巡检，维护，检修，运行管理，提供技术支持，保障风电机组安全稳定运行。<br>1、负责工程项目风力发电机组的现场调试和运行维护。<br>2、负责工程项目现场风机运行过程的问题消缺和故障记录。<br>3、完成运维项目风力发电机的定期维护、日常检修、日常维护。<br>4、提交风力发电项目现场运行分析报表，拟订检修工作计划、备品备件计划和耗品采购计划。<br>5、负责项目现场物资的备件管理。<br>6、分析、整理现场运行记录，并提出改进建议。<br>7、进行现场风电机组的运行研究，优化风机运行性能。<br>岗位要求：<br>1、性别年龄：18-31周岁，大专及以上学历（优秀者放宽到中专）。<br>2、自身能力：能够吃苦耐劳，责任心强，有强烈的服务意识、良好的沟通能力，抗压性强，能适应偶尔出差。<br>3 身体素质：无恐高、心脏病、高血压、高血糖、等职业禁忌症。<br>薪资待遇：<br>风力发电直签，户籍就近原则，初审，面试，体检，签订劳动合同，首签合同三年，实习期三个月，实习工资4000-5000，转正工资6000-12000，转正以后，三个月考核一次（季度考核）工资逐步上涨，入职当月缴纳上六险一金，工龄奖、生日福利、意外保险、带薪休假、结婚生育津贴、高温补贴、话费补贴、电脑补贴、岗位晋升奖励金等。有晋升机制，上班期间包吃住，两人宿舍。<br>上班时间：8小时长白班。工作50天休30天，工作22天休8天（连上连休）无夜班无加班，公司报销', NULL, 'https://www.zhaopin.com/jobdetail/CCL1504753470J40757089101.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4397, '风电工程师', '四川瑞柏电力工程有限公司厦门分公司', '7月22日', '8000-12000元', '枣庄-薛城区', '电力/水利/热力/燃气', '1000-9999人', '未融资', 'CCL1500420670J40910368204', '1.岗位职责：负责风力发电机组的日常巡检、运行维护、故障消缺；巡检运行记录填报；检维修方案编制和备品备件计划编制上报；现场设备运行监控、机组系统调试和试运行等。<br>2.任职要求：<br>大专及以上学历；年龄19-30周岁；电气、机电、机械、自动化、装备技术、数控、工业机器人、汽修、电子、计算机、建筑等理工类相关专业优先；需持有高压电工证、低压电工证、登高证；职业健康体检合格，无色盲、色弱，无恐高、心脏病、高血压等职业健康康禁忌症。<br>3.工资待遇：入职前3个月执行5000-5500元；3-6个月可晋升为6800-7300元；前三个月工资按照80%发放，第四个月按正常工资标准发放，并补全前三个的20%工资，然后每半年考核晋升一次，月薪资涨幅600-1200；工作满一年工资8000元左右；工作2-3年，月薪资可达9000-12000，表现优秀者可连续升级加薪；入职缴纳六险一金，管吃住、节假日享有节假日补贴。话费补贴100元/月；电脑补贴80元/月(现场发放)；高温补贴200元/月(每年6、7、8月享受补贴) 国家法定假日在场则发放福利费，200元/天：清明、端午、五一、 中秋、元旦、 国庆(3天)；春节(7天)发放300元/天。公司额外发放中秋、春节福利。<br>4.作息时间：长白班，综合时制8小时；月休5-10天；2-3个月休息10-15天。报销往返的路费，按照高铁二等座标准(由现场审批报销)。<br>5.工作地点：可根据籍贯就近分配，全国都可分配，不能指定片区，可报销来回家路费。', '瑞柏电力工程有限公司，成立于 2017年，总部在成都，山东、江苏、福建等省市设有分公司；全国各地区八个经营片区；是我国专业化新能源风电运维、定检、技改、技术研发与利用等知名电力企业，旨在为全国，乃至全球客户提供清洁、高效、可靠的电力资源和服务；通过不断的技术创新和优化管理，已建立起了研发、质量、安全、职业健康等规范的管理体系，公司拥有经验丰富的一流管理团队和专业化的技术人才团队，确保了项目的高效执行和卓越运营。公司秉承“质量第一、诚信经营、服务优质”的经营理念，为推动我国新能源风电的发展做出了积极贡献。', 'https://www.zhaopin.com/jobdetail/CCL1500420670J40910368204.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4398, '英语翻译', '中软国际', '7月21日', '面议', '北京-海淀区', '计算机软件,运营商/增值服务', '10000人以上', '已上市', 'CC508620120J40790219612', '岗位职责: 1. 根据SOP将用户反馈原声进行业务分类标注，并需要监控和分析短视频产品的用户反馈原声； 2. 通过用户反馈及时发现产品功能问题，与产研、QA团队协作，跟进并解决产品功能Bug 3. 站在用户视角，从用户反馈中挖掘用户需求，收集、汇总产品优化方向和建议 必备技能: 1：大专及以上学历，适应呼叫中心管理模式，接受KPI考核管理，有客服、审核标注等相关领域的工作经验者优先； 2. 具备较好的英文读写能力，熟悉操作电脑办公软件；愿意接受排班和倒班制度； 3. 性格外向，具备良好的沟通能力和抗压能力 加分技能: 具备较好的英文读写能力', '中软国际是行业领先的全球化软件与信息技术服务企业，成立于2000年，为香港主板上市公司（股票代码：00354.HK），拥有中国分支40+、海外分支14个，拥有员工超过9万人，服务覆盖超过40个国家。中软国际应用开发与管理专业沉淀深厚，企业数字化转型的最佳实践和专家人才充沛。公司与华为等战略伙伴一起，构建软件产业互联网平台，领先技术变革，提升产业效率，致力于使能软件企业引领发展，服务制造企业转型升级，为政企客户提供“好、快、多、省”的信息技术服务。中软国际四大业务蓬勃发展：夯实基石业务作为第一增长曲线的地位，确定云智能业务为第二增长曲线，发展鸿蒙生态、解放号为第三增长曲线，推动解放号作为软件产业互联网平台全面升级。公司在云计算、大数据、人工智能、物联网、移动互联网等方面具有丰富的咨询、设计、实施和服务经验，是全球客户数字化转型的共创伙伴。公司长期服务于多家全球500强企业等头部客户和众多高成长潜力客户，覆盖金融、电信、互联网、高科技、政府、制造与流通、交通、能源、教育等行业。公司已连续四年创造超百亿人民币营收，并立志在未来成为全球最优秀IT服务商之一。', 'https://www.zhaopin.com/jobdetail/CC508620120J40790219612.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4399, '游戏推广', '菏泽仙女文化传媒有限公司', '7月23日', '5000-10000元', '荆州-荆州区', '文化艺术/娱乐,新媒体', '1000-9999人', '不需要融资', 'CCL1331427280J40795966303', '【工作介绍】<br>指定平台开黑玩游戏，接单完成游戏陪陪/陪练，边玩边赚钱【工作内容】<br>1、有手机耳机即可<br>2、陪付费客户打游戏，聊天，唱歌，按时间或局数收费<br>3、有专门组织培训，带你快速人门，赚钱无忧。<br>4、不要求技术【人员要求】<br>1、18-30岁2、<br>会和平精英/绝地求生/英雄联盟/王者荣耀/云顶之弈、其中任意一款游戏<br>3、工作认真负责，积极主动<br>4、良好的沟通能力，性格开朗，喜欢与人交流<br>5、兼职全职均可，不限制在线时间<br>【薪资结算】<br>奖励机制+下单提成，时间充足者每天收入至少200+', '虎牙旗下千万流水钻石公会虎牙交友前三公会旗下几十个专业运营团队！艺人共计5000+陪练师共计10000+集交友、陪玩、颜值、二次元为一体的顶尖经纪公司行业顶尖运营团队，致力打造最优质的品牌公会。', 'https://www.zhaopin.com/jobdetail/CCL1331427280J40795966303.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4400, '档案管理', '吉林省梓楗新型建材', '2025年07月30日', '3000-4000元', '长春-经济开发区', '矿产/采掘', '1000-9999人', NULL, 'CC694661522J00358758901', '<p class=\\\\\"MsoNormal\\\\\" style=\\\\\"margin-left:21.0000pt;text-indent:-28.1000pt;mso-char-indent-count:-2.0000;text-autospace:ideograph-numeric;mso-pagination:none;line-height:150%;\\\\\"><b><span style=\\\\\"mso-spacerun:\'\'yes\'\';font-family:宋体;line-height:150%;font-weight:bold;font-size:14.0000pt;mso-font-kerning:1.0000pt;\\\\\"><font face=\\\\\"宋体\\\\\"> 工作地点：吉林省磐石市</font></span></b></p><p class=\\\\\"MsoNormal\\\\\" style=\\\\\"margin-left:21.0000pt;text-indent:-28.1000pt;mso-char-indent-count:-2.0000;text-autospace:ideograph-numeric;mso-pagination:none;line-height:150%;\\\\\"><b><span style=\\\\\"mso-spacerun:\'\'yes\'\';font-family:宋体;line-height:150%;font-weight:bold;font-size:14.0000pt;mso-font-kerning:1.0000pt;\\\\\"><font face=\\\\\"宋体\\\\\"> 岗位职责：</font></span></b><b><span style=\\\\\"mso-spacerun:\'\'yes\'\';font-family:宋体;line-height:150%;font-weight:bold;font-size:14.0000pt;mso-font-kerning:1.0000pt;\\\\\"><p></p></span></b></p><p class=\\\\\"MsoNormal\\\\\" style=\\\\\"margin-left: 21.25pt; text-indent: -21.25pt; line-height: 150%;\\\\\"><font face=\\\\\"宋体\\\\\">1、接收公司全部的文件，办理移交手续，纸质版的存档，电子版的更新；</font></p><p class=\\\\\"MsoNormal\\\\\" style=\\\\\"margin-left: 21.25pt; text-indent: -21.25pt; line-height: 150%;\\\\\"><font face=\\\\\"宋体\\\\\">2、接收文件进行扫描，文件信息录入系统，装订，编辑档案号后装入相应档案盒；</font></p><p class=\\\\\"MsoNormal\\\\\" style=\\\\\"margin-left: 21.25pt; text-indent: -21.25pt; line-height: 150%;\\\\\"><font face=\\\\\"宋体\\\\\">3、根据借阅人提供信息，查找系统，确认后提供给借阅人需要借阅的文件，借阅人进行借阅人手续的登记；</font></p><p class=\\\\\"MsoNormal\\\\\" style=\\\\\"margin-left: 21.25pt; text-indent: -21.25pt; line-height: 150%;\\\\\"><font face=\\\\\"宋体\\\\\">4、借阅人归还文件时，确认文件是否和登记表上对应，文件是否完好无损，后登记表进行注销，文件放回原位置；</font></p><p class=\\\\\"MsoNormal\\\\\" style=\\\\\"margin-left: 21.25pt; text-indent: -21.25pt; line-height: 150%;\\\\\"><font face=\\\\\"宋体\\\\\">5、办理文件发放，需要提供部门领导签字后的发放清单并写清用途，系统进行文件已发放标注；</font></p><p class=\\\\\"MsoNormal\\\\\" style=\\\\\"margin-left: 21.25pt; text-indent: -21.25pt; line-height: 150%;\\\\\"><font face=\\\\\"宋体\\\\\">6、各公司的公章和合同章的使用和借出需要有公司领导的签字同意或微信软件请章截图同意，确认请章内容和实际文件相符后予以盖章并进行登记；</font></p><p class=\\\\\"MsoNormal\\\\\" style=\\\\\"margin-left: 21.25pt; text-indent: -21.25pt; line-height: 150%;\\\\\"><font face=\\\\\"宋体\\\\\">8、公司较重要的文件，如有需要查阅的人员，需要请示部门领导，准许后方可查阅；</font></p><p class=\\\\\"MsoNormal\\\\\" style=\\\\\"margin-left: 21.25pt; text-indent: -21.25pt; line-height: 150%;\\\\\"><font face=\\\\\"宋体\\\\\">9、负责离职人员电脑文件的归档。</font></p><p class=\\\\\"MsoNormal\\\\\" style=\\\\\"line-height: 150%;\\\\\"><b><span style=\\\\\"mso-spacerun:\'\'yes\'\';font-family:宋体;line-height:150%;font-weight:bold;font-size:14.0000pt;mso-font-kerning:1.0000pt;\\\\\"><font face=\\\\\"宋体\\\\\">任职资格：</font></span></b><span style=\\\\\"mso-spacerun:\'\'yes\'\';font-family:宋体;mso-bidi-font-family:Arial;line-height:150%;font-size:10.5000pt;mso-font-kerning:1.0000pt;\\\\\"><p></p></span></p><p class=\\\\\"MsoNormal\\\\\" style=\\\\\"margin-left: 21.25pt; text-indent: -21.25pt; line-height: 150%;\\\\\"><font face=\\\\\"宋体\\\\\">1、年龄22-30岁，大专及以上学历；</font></p><p class=\\\\\"MsoNormal\\\\\" style=\\\\\"margin-left: 21.25pt; text-indent: -21.25pt; line-height: 150%;\\\\\"><font face=\\\\\"宋体\\\\\">2、熟悉档案管理流程和方法；</font></p><p class=\\\\\"MsoNormal\\\\\" style=\\\\\"margin-left: 21.25pt; text-indent: -21.25pt; line-height: 150%;\\\\\"><font face=\\\\\"宋体\\\\\">3、具备较强的保密意识。</font></p>职位福利：五险一金、包住、定期体检、免费停车、餐补、带薪年假<br>', '吉林省梓楗新型建材股份有限公司，是一家生产和开发绿色环保、节能新型建筑材料的新型企业。公司以十三五规划为指导，发展循环经济为出发点，大力提倡技术创新，着重研发有色金属、玉石废渣的综合利用及生产。公司位于磐石市富太镇三河矿区境内，距小红石砬子铅、锌矿仅1.2公里。周边公路、铁路、珲春口岸等交通大动脉为公司提供了贯穿东北、辐射全国的便利交通条件，更好的满足了各地市场对新型建材的需求。公司与中国矿业大学、武汉理工大学、咸阳陶瓷研究设计院、河北承德尾矿综合利用研究院、中国建材规划研究设计院、武汉建筑材料工业设计研院等科研单位合作，不断研发绿色环保、高端高附加值的微晶石、微晶玉石系列产品。公司投资建设的微晶石系列高端建材项目总投资达到25亿元，属于国家鼓励类，符合《国家产业结构调整指导目录》第三十八条环境保护与资源节约综合利用中第27款：尾矿、废渣等资源综合利用的国家政策。一期项目建设包括：微晶石及微晶玉石生产线、岩棉生产线、加气块混凝土及板材生产线和水磨石生产线，每年可消耗尾矿总量可达50万吨，可将三河矿区有色金属尾矿、玉石废渣“吃干榨净”。据初步核算，项目建成后可达年产值35亿元，年利润达9亿元。公司投资建设的同时，不忘承担社会责任。绿色新型建材作为发展地方经济的接续产业，将带动运输、加工等相关行业的共同发展，为农民工提供就业机会，为繁荣地方经济贡献自己的一份力量。公司设计建设的微晶石、微晶玉石系列建材项目是石材市场的一场革新，也将改变中国石材市场格局。未来，吉林省梓楗新型建材股份有限公司将成为东北首家微晶石、微晶玉石系列新型建材生产基地，实现节能利废，发展循环经济。将吉林经济的发展推向一个崭新的平台，使吉林省成为中国北方，乃至全国高端建材的制造中心，', 'https://www.zhaopin.com/jobdetail/CC694661522J00358758901.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4401, '统计员', '石家庄市汇智新程网络科技有限责任公司', '7月8日', '3000-5000元', '石家庄-桥西区', '专业技术服务', '100-299人', NULL, 'CCL1478411800J40686760211', '纯文职岗位 周末双休，法定节假日休息 <br>   9:00-12:00，13:00-18:00      薪资:3-5K   <br>   <br>', NULL, 'https://www.zhaopin.com/jobdetail/CCL1478411800J40686760211.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4402, '风电工程师', '四川瑞柏电力工程有限公司厦门分公司', '7月19日', '6000-12000元', '泰安-泰山区', '电力/水利/热力/燃气', '1000-9999人', '未融资', 'CCL1500420670J40909781604', '2.招聘岗位：风电运维工程师<br>2.1、岗位职责：负责风力发电机组的日常巡检、运行维护、故障消缺；巡检运行记录填报；检维修方案编制和备品备件计划编制上报；现场设备运行监控、机组系统调试和试运行等。<br>3.任职要求：<br>3.1、大专及以上学历；年龄19-29周岁；电气、机电、机械、自动化、装备技术、数控、工业机器人、汽修、电子、计算机、建筑等理工类相关专业优先；需持有高压电工证、低压电工证、登高证，(面试通过公司统一安排考取，入职满一年后考证费用全额报销) <br>3.2.职业健康体检合格，无色盲、色弱，无恐高、心脏病、高血压等职业健康康禁忌症。<br>4.工资待遇：入职前3个月执行5000-5500元；3-6个月可晋升为6800-7300元；前三个月工资按照80%发放，第四个月按正常工资标准发放，并补全前三个的20%工资，然后每半年考核晋升一次，月薪资涨幅600-1200；工作满一年工资8000元左右；工作2-3年，月薪资可达9000-12000，表现优秀者可连续升级加薪；入职缴纳六险一金，管住、节假日享有节假日补贴。<br>话费补贴100元/月；电脑补贴80元/月(现场发放)；高温补贴200元/月(每年6、7、8月享受补贴) <br>国家法定假日在场则发放福利费，200元/天：清明、端午、五一、 中秋、元旦、 国庆(3天)；春节(7天)发放300元/天。公司额外发放中秋、春节福利。<br>5、工资晋升档次及等级：<br>6、作息时间：长白班，综合时制8小时；月休5天；3个月休息10天。报销往返的路费，按照高铁二等座标准(由现场审批报销)。<br>7、工作地点：入职需服从分配 尽量根据意向地就近原则分配', '瑞柏电力工程有限公司，成立于 2017年，总部在成都，山东、江苏、福建等省市设有分公司；全国各地区八个经营片区；是我国专业化新能源风电运维、定检、技改、技术研发与利用等知名电力企业，旨在为全国，乃至全球客户提供清洁、高效、可靠的电力资源和服务；通过不断的技术创新和优化管理，已建立起了研发、质量、安全、职业健康等规范的管理体系，公司拥有经验丰富的一流管理团队和专业化的技术人才团队，确保了项目的高效执行和卓越运营。公司秉承“质量第一、诚信经营、服务优质”的经营理念，为推动我国新能源风电的发展做出了积极贡献。', 'https://www.zhaopin.com/jobdetail/CCL1500420670J40909781604.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4403, '项目招投标', '中屹泰祥工程咨询有限公司', '7月25日', '6000-8000元', '长春-朝阳区', '房地产开发,互联网', '20-99人', '未融资', 'CC842773800J40781945905', '1、会操作招标线上平台招标流程，（例政采云平台、吉林省一体化平台等），了解招投标法律法规，熟悉各种类型招标、开标现场掌握进度、形式  2、招标工作经验丰富', '基本情况：中屹泰祥工程咨询有限公司，成立于2009年9月，注册资本金5000万元，公司位于吉林省长春市高新开发区卫星路中天大厦，办公面积600平方米，现有员工70人，其中注册造价师14人，高级工程师16人，造价员28人，招投标人员6人。经营范围：工程造价咨询、招投标代理、建筑装修设计、政府采购代理、工程咨询、财政投资评审、项目管理、全过程造价管理等。服务客户：各市县财政局、审计局、政府机关、大中型企业、房地产开发企业、医院、高等院校等企事业单位。专业力量：房屋建筑工程、市政公用工程、园林景观绿化工程、公路工程、水利水电工程、高标准农田工程、地质灾害治理工程、石油化工工程、冶金矿山工程、煤矿井巷工程、电力工程、光伏风电新能源工程等。', 'https://www.zhaopin.com/jobdetail/CC842773800J40781945905.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4404, '项目招投标', '天地和兴', '12月5日', '5000-8000元', '武汉-江汉区', '计算机软件,IT服务,网络/信息安全,通信/网络设备', '500-999人', 'D轮及以上', 'CC155507010J40503111103', '岗位职责:', '北京天地和兴科技有限公司（简称天地和兴）是我国最早专注于工业网络安全的专精特新企业，自2007年创立以来，凭借着深厚的技术底蕴和卓越的创新能力，迅速崛起成为国家级专精特新“小巨人”企业以及国家级高新技术企业。在国产化不断推进的背景下，天地和兴基于对工业网络安全的深度研究和不断探索，倾力打造“天地和兴·安全守护”八大产品体系，全面满足从生产业务到数据传输等全域工业网络安全需求。“天墀”、“地盾”、“和睿”、“兴邦”覆盖检测评估、防护隔离、监测审计、平台管理等环节，旨在提升威胁发现、安全防护、分析检测等能力，实现安全统一管理并满足合规要求。“安疆”、“全界”、“守邑”、“护阖”专注于业务安全，聚焦边缘物联、国密改造、智慧运维、智能安监等领域，运用定制化模式，切实满足行业客户个性化需求，有效应对各类新场景下的网络安全问题，促进安全与业务的深度融合。天地和兴以北京为总部，业务广泛辐射全国31个省、自治区、直辖市，深度服务于电力电网、石油石化、轨道交通、智能制造、冶金矿山、市政水务、应急环保和运营商等关键信息基础设施行业。公司在各分支机构配备专业服务团队，能有效应对内外部网络安全事件，为工业控制系统网络安全体系的规划、建设和实施提供全生命周期的专业服务保障及解决方案。天地和兴始终铭记“投身国家网信事业，护卫关键信息基础设施”这一崇高使命，直面时代发展的重大战略转折与关键挑战，勇立潮头，通过持续创新驱动技术变革，不断提升自身的综合实力与核心竞争力。通过与产业组织和生态伙伴开放合作，构建工业网络安全生态体系，共同营造安全稳定环境，为关键信息基础设施安全、国家网信事业繁荣贡献力量。', 'https://www.zhaopin.com/jobdetail/CC155507010J40503111103.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4405, '电话客服', '北京五八信息技术有限公司', '2025-07-28 00:29:40', '4000-7000元', '天津-滨海新区', '互联网,计算机软件', '10000人以上', '已上市', 'CC330611210J40670980203', '月休六天全白班<br>  工作职责  <br>1.主动外呼个人车主，收集车辆信息，汇总为工单；  <br>2.汇总用户的问题信息，并录入系统，对接相关部门；  <br>3.快速有效、保质保量的完成工单记录处理；  <br>4.具备较强的学习能力，及时学习并领会业务更新内容；  <br>5.主动发现并提供增值信息；  <br>6.上级交代的临时工作任务；  <br>纯文职外呼电话客服，无销售属性，上四休一，每天19:00准时关闭系统。  <br>绩效考核指标看个人达成成果，不依据排名评定。  <br>  <br>任职资格  <br>1. 专科及以上学历；  <br>2. 普通话标准，保证在通话过程中不带有地方口音；  <br>3. 良好的语言表达和沟通能力，应变能力；  <br>4. 熟练掌握业务知识，熟背话术。  <br>  <br>福利待遇  <br>1、朝九晚六午休一小时，有年假婚假产假；  <br>2、入职即缴纳五险一金；  <br>3、季度调薪（400-800），晋升机制公开透明；  <br>4、入职提供带薪培训，入组后有老带新，无须担心角色适应问题，帮助你尽快融入工作环境；  <br>5、补贴：高低温补贴（高温三个月低温三个月，总计六个月）、餐补；  <br>6、公司提供宿舍，宿舍就在园区内，步行抵达工位只需三分钟;如需远距离通勤，公司班车路线涵盖市内六区、大港、汉沽、东丽、津南、塘沽；  <br>7、公司食堂提供早、中、晚三餐；  <br>8、办公环境优越，工区内配有按摩椅、桌球台、水吧等；  <br>9、每年一次体检。', '58同城作为中国领先的生活服务平台，遵循“用户第一、简单可信、成就奋斗者”的企业核心价值观，以“帮助人们安居乐业”为企业使命，以“成为领先的产业化生活服务集团”为愿景。业务覆盖招聘、房产、汽车、本地生活服务等领域。旗下拥有赶集直招、58魔方、中华英才网、安居客、58爱房、巧房、58到家、人人车、驾校一点通、转转、58数科等品牌。2005年12月，58同城创立于北京，并于2013年10月31日，正式于纽交所挂牌上市，2015年58同城先后完成安居客、中华英才网并购，同年11月正式合并赶集网。58同城不断进行产业化、数智化升级和技术创新，完善用户服务标准化和保障体系，为客户提供更专业、高效的服务，全方位的市场营销解决方案。2021年，58同城全面向产业化布局发展，目标是成为全球第一家完成产业化升级的生活服务平台。公司以“4+N”投资布局发展战略，围绕招聘、房产、汽车、本地生活服务等各个事业群，通过内部孵化、投资等向N个创新的细分业务方向发展，打通上下游服务产品链，逐步完成生活服务信息流程的在线化和一体化解决方案。', 'https://www.zhaopin.com/jobdetail/CC330611210J40670980203.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4406, '统计员', '上海奏裳网络科技有限公司', '7月17日', '6000-9000元', '佛山-顺德区', '云计算/大数据', '20-99人', NULL, 'CCL1506628370J40933003204', '职位描述：<br>1、高效处理日常事务，独立完成上级日常行程安排等工作；<br>2、按上级要求组织安排会议，及时更新日历；<br>3、谨慎处理流程性邮件、转发传达、签收登记、分类归档；<br>4、文件处理、文档处理排版，确保内容条理清晰，账单处理； <br>5、负责完成上级指派的其他工作。<br>任职要求：<br>1，形象气质佳；<br>2、大专以上学历，秘书、中文、英文等相关专业优先；<br>3、熟练掌握电脑操作及办公软件；<br>4、理解能力强，善于沟通协调，具备较强的文字表达能力；<br>5、具有服务理念和团队合作精神；<br>6、细心、踏实，勤奋、做事积极主动，有一定抗压适应能力和学习能力强；', NULL, 'https://www.zhaopin.com/jobdetail/CCL1506628370J40933003204.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4407, '销售工程师', '江苏大全高压开关有限公司', '7月22日', '7000-14000元', '邢台-襄都区', '电力/水利/热力/燃气,电气机械/电力设备,电子设备制造', '100-299人', '未融资', 'CC360620410J40713959812', '岗位职务： <br>1. 负责产品销售及推广；<br>  <br>2. 负责客户拓展及维护；<br>  <br>3. 合同履约跟进及货款回笼。<br>  <br>     任职要求：<br>  1. 35周岁及以下，本科及以上学历（大专需5年相关工作经验）；<br>  <br>2. 电气、市场营销、技术类相关专业，同行业工作经验者优先考虑；<br>  <br>3. 具有较强的沟通协调及商务谈判能力。<br>  <br>     薪酬福利：<br>  1. 差旅费、各类补贴，福利，带薪年假，五险一金；项目费用按公司规定报销；<br>  <br>2. 薪资结构：月薪7-14K(基本工资+绩效工资+业绩奖金)；<br>  <br>3. 客户经理可根据户籍所在地就近选择工作区域（北京、上海、江苏、浙江、安徽、贵州、昆明、重庆、成都、西安、郑州、石家庄、山东、广东等区域）。<br>职位福利：五险一金、绩效奖金、交通补助、通讯补助、节日福利、定期体检  <br>', '集团简介大全集团是从事高低压成套电气、元器件、环保、高速铁路设备、新材料（多晶硅及太阳能电池）等产业的国家级大型企业集团，在江苏扬中市、南京江宁开发区、重庆万州区、北京高新区建有四大产业基地。集团拥有员工6500余人，有 23家子公司，其中 7家是与德国西门子、德国默勒、美国伊顿、瑞士赛雪龙、丹麦安凯特等公司合资的企业。大全是国家重点高新技术企业、国家科技部 863计划成果产业化基地、国家 863计划 CIMS示范企业、中国机械工业 100强企业和中国电气工业领军企业，中国电气工业自主创新名列第一，产品先后荣获“中国名牌产品”和“国家免检产品”称号。拥有国家级企业技术中心、国家级博士后科研工作站、国家级电气检测站，科技研发人员 600余人，博士、硕士以上高级专业技术人员 110多人，科技开发能力和技术装备水平已居于国内同行业前列，在国家 863计划项目以及一系列重大科技攻关项目上取得多项成果，每年有近 10项具有完全自主知识产权的新产品问世，累计申报各类专利 250多项。公司简介：江苏大全高压开关有限公司是中国电气工业领军企业大全集团（原江苏长江电气集团）旗下的核心子公司，专业从事高、中压输配电设备的研发、生产、销售和服务。公司秉持“专业决定品质。专注铸就品牌的经营理念，致力于开关设备和断路器技术及应用的研究与开发，精心打造国内知名电工品牌。大全高压开关坐落于南京江宁高新技术开发区，总投资1.6亿元，公司厂房总面积逾万平方米。拥有国内最先进的断路器自动化生产线，断路器年生产能力20000台。稳居国内高压电器设备设计与制造行业的一线阵营。公司的主要产品有：7.2~40.5kV系列户内高压真空断路器、12kV户外柱上真空断路器、40.5kV真空负荷开关等。服务于核电站、发电厂、变电站、城乡电网、石油、化工、冶金、电气化轨道、地铁、轻轨、港口、垃圾电站及环保等多个行业，并参与了多项国家重点项目建设。公司秉承大全集团“开放合作，科技领先”的企业战略，拥有完整的研发体系和多名该领域的资深专家；与清华大学、西安交通大学、西安高压电器研究所等多家高等院校、科研机构建立了广泛的合作关系；是中国输配电企业最早成立博士后工作站的企业之一。公司非常注重工艺设备、检验仪器、研发手段和管理模式的现代化、智能化，拥有断路器智能车间、全自动端子机、立体仓库等。公司将以“全球化视野，开放性思维”的企业精神和“诚实、敬业、创新”的工作作风，卓越运作，精细管理，向用户提供一流的产品和服务。', 'https://www.zhaopin.com/jobdetail/CC360620410J40713959812.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4408, '档案管理', '北京汉龙致远科技有限公司', '5月9日', '4000-6000元', '北京-通州区', 'IT服务,互联网', '100-299人', '未融资', 'CCL1211999620J40842731215', '岗位职责：<br>1.按照要求对档案进行数字化加工工作，包括档案扫描、图像质检、档案装订等工作；<br>2.职业发展规划：数字化加工员—项目主管—项目经理；<br>任职要求：<br>1.中专及以上学历，计算机专业优先<br>2.有一定的电脑基础<br>3.吃苦耐劳、有上进心和责任心，有一定的学习能力，服从项目安排。<br>薪资构成：岗位薪资+超额提计<br>职位福利：员工旅游、节日福利、五险一金、周末双休、餐补、团建 培训 <br>', '公司介绍北京汉龙致远科技有限公司（汉龙致远），成立于2012年3月，注册资金2000万元，总部设立于北京经济技术开发区（天骥智谷商务园区）内，是一家专业为党政机关、军工企事业单位提供信息系统集成、软件开发、纸质档案整理、图档数字化技术服务、录音录像档案数字化、数模整合、档案信息化咨询的技术型企业。汉龙致远拥有一批责任心强、职业化素养高的员工队伍。公司核心管理人员均从事行业多年，具备非常丰富的档案资源管理经验。能够向用户提供技术咨询、解决方案、项目实施等综合服务。汉龙致远将《成为客户信赖的服务商》作为公司的经营思想和品牌承诺，作为一家以技术服务为核心的公司，我们通过开放式创新、卓越运营管理、人力资源发展等战略的实施，全面构造公司的核心竞争力，创造客户和社会的价值，从而实现公司员工的价值体现，以不断满足需求和优化服务质量，从而实现与客户的共同成长和可持续发展理念。', 'https://www.zhaopin.com/jobdetail/CCL1211999620J40842731215.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4409, '招聘专员/助理', '吉林省蓝青蛙劳务派遣有限公司', '6月5日', '4000-7000元', '长春-宽城区', '人力资源服务', '100-299人', '未融资', 'CC418019230J40797512703', '工作地点在长春， 工作内容：联系主动投递简历的求职者，介绍工作内容 工作时间：8小时，双休 薪资：日结+提成+满勤+绩效+补助=7000-8000', '吉林省蓝青蛙劳务派遣有限公司是由吉林省人社厅批准从事经营劳务派遣、人力资源等服务的企业，公司实缴注册资金200万元，并已通过ISO9001质量管理体系认证,是一家专业为企业提供劳务派遣、劳务外包、人力资源的供应商。蓝青蛙是一家具备现代企业管理制度和服务意识的专业人力资源服务企业。现设有市场运营部、猎头部、人力资源部、办理用工手续、保险缴纳、保险理赔、工社会保障部、综合办公室、财务部等部门，其中汇聚了多名来自省内知名企业、劳动保障部门的资深人力资源管理专家。并在烟台、吉林市、延吉等地设有分公司及办事处。蓝青蛙为企业提供的服务包括：劳务外包、劳务派遣、劳动仲裁委托、社保代缴等人事外包服务。其中所涉及的服务项目包括了：与员工签订劳动合同、资计算发放、退工手续办理等相关的人事服务。', 'https://www.zhaopin.com/jobdetail/CC418019230J40797512703.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4410, '储备经理人', '上海引贤企业发展有限公司', '7月27日', '8000-15000元', '上海-浦东新区', '企业服务,互联网,咨询服务,专业技术服务', '100-299人', '不需要融资', 'CCL1299555640J40811703203', '岗位职责：<br>1、负责公司老客户资源开发，预约、洽谈客户。<br>2、协助客户优化家庭财务配置，提供定制化方案。<br>3、负责发展团队，搭建并管理团队，策划业务活动，带领团队完成业绩目标。<br> 任职要求： <br>1、25-55岁，大专以上学历，学信网认证，符合金融从业的个人征信要求； <br>2、善于与人沟通，有良好的沟通能力和服务意识； <br>3、具备养老、保险、金融、法律、医疗、销售和团队管理经验，优先录用。 <br> <br>   薪资福利：  <br>1、底薪+绩效+提成，综合年薪15-50万，业绩出色者收入无上限。  <br>2、针对保险领域的杰出人才及主管，特别推出优才扶持政策。  <br>3、享有太保家园与细胞治疗集团提供的内部培训机会，更有行业资深专家亲自指导。  <br>4、节日礼金、生日惊喜、年度高端健康体检，全方位关怀，让您感受满满爱意。  <br>5、定期举办国内外高峰会议，工作之余畅享旅游乐趣，梦想与现实完美融合。  <br>  <br>', '上海引贤企业发展有限公司是一家专业性的商务服务企业，经营服务包括：职业中介。企业管理咨询；商务代理代办服务；企业形象策划；市场营销策划；会议及展览服务；软件开发；图文设计制作；信息系统集成服务；网络与信息安全软件开发；专业设计服务；信息咨询服务；人事服务；广告设计、代理；互联网技术及咨询服务；', 'https://www.zhaopin.com/jobdetail/CCL1299555640J40811703203.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4411, '网络客服', '京东集团', '7月2日', '4000-7000元·14薪', '宿迁-宿城区', '互联网,电子商务', '10000人以上', '已上市', 'CC192921310J40617827209', '【注】:此岗位为京东内部直聘，非外包!<br>本科毕业未缴纳社保人员有机会申请购房抵用券“五万元”，可直接用于购房抵用。<br>“无需经验，入职试用期也享受五险一金，带薪培新等老人福利”京东内部招聘经理，可放心投递，随时验证工作身份<br>岗位职责：处理五金类，工业品类等商家入驻后一系列问题，业务量不高<br>二、任职要求<br>1.大专及以上学历<br>2.较强的服务意识，表达清晰，热爱为人解决问题，热爱客服行业(无经验者我们会用心培训噢)<br>3.打字速度不低于40字/分钟，可自行下载金山打字通练习<br>4.9-18点<br>三、薪酬福利与晋升发展<br>1. 薪资标准:试用期：2000+1000.转正之后底薪2000+评分1-1.4<br>2.每年2次升职加薪机会:①横向转岗(运营 /培训/质 检/数据分析/人事/行政等) ;②纵向晋升:主管-→经理 - &gt;高级经理- &gt;总监;③专业序列:普通客服-→资深客服 (明星客服)<br>3. 每周零食、免费班车、免费员工公寓 (入职凭借无异常体检报告即可申请)、健身房、 节日大礼包、定期团建、生日神秘礼包、结婚生子礼金等等<br>四、培训与办公<br>1.14- -20天左右带薪培训，带领你快速从小白变成优秀客服~<br>2.京东客服总部宿迁:高大上的京东大厦，敞亮的办公大楼，充足的办公工位，专业的设备。<br>3.双人酒店式公寓住宿，配备独立卫浴、中央空调、洗衣房、茶水间~', '京东（JD.COM）是中国领先的技术驱动型电商，并致力于成为领先的以供应链为基础的技术与服务提供商。其尖端的零售基础设施使消费者可以随时随地购买所需的任何商品。京东向合作伙伴、品牌商和多个领域开放了技术和基础设施，作为零售基础设施服务商推动各行各业生产效率的提升和创新。京东也是纳斯达克100指数的一员和财富全球500强企业。', 'https://www.zhaopin.com/jobdetail/CC192921310J40617827209.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4412, '统计员', '山西中标商务咨询有限公司', '7月23日', '3000-4000元', '太原-小店区', '企业服务', '20-99人', '未融资', 'CCL1452952130J40818829608', '岗位职责：  <br>1.熟练使用办公软件、整理文档资料。  <br>任职要求：  <br>1、具有良好的沟通能力、具有团队协作精神。', '山西中标商务咨询有限公司是一家专门从事投标书制作的公司，从帮助标书客户解决撰写困惑开始，逐步发展成一家致力服务于企业标书编写的专业公司，团队成员来自知名高校和大型国企，积累了多年专业标书编写、咨询机构工作经验，同时公司拥有的专业顾问团队，具有雄厚的标书编写、投融资咨询实力和丰富的项目咨询经验。在这里，我们希望看到人尽其才，让每个人的闪光点照亮万物聚兴的美好。', 'https://www.zhaopin.com/jobdetail/CCL1452952130J40818829608.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4413, '统计员', '大连新南洋食品有限公司', '1月11日', '3000-4000元', '大连-金州区', '快速消费品', '20-99人', '不需要融资', 'CC215579620J40526236111', '职位描述：<br>1、接听来访电话、客户接待等日常行政事务；<br>2、办公用品等采买和管控，各类资产的建档、维护管理；<br>3、完成领导交办的其他工作; 4、企业的各种认证的记录整理工作。 <br>任职要求： <br>1、文秘、行政管理等相关专业本科及以上学历；应届生也可； <br>2、熟悉办公室行政管理知识及工作流程； <br>3、工作仔细认真、为人正直，具备较强的书面和口头表达能力，有较强的责任心。', '我公司大连新南洋食品有限公司是与韩国合资，成立于1994年，公司经十几年的发展现已拥有厂房2000平方米，员工近100余人，固定资产1000万元人民币。公司主要生产糖花系列、硬糖卡通和软糖卡通系列，产品种类已达上千种，是食品装饰品（全手工制作），为全国首创，产品种类已达上千种，产品主要销往欧洲（俄罗斯、意大利、法国、英国、西班牙）、亚洲（韩国、香港、马来西亚）、国内（好利来、元祖、克莉丝汀、IDQ）等年产值400万元以上。并受到国外客户的高度评价。由于欧美地区及国内对装饰品需求量的增多，现有厂房已满足不了生产需求，为此公司已经开始另建3000平方米厂房，投资400万元，增加员工120人。', 'https://www.zhaopin.com/jobdetail/CC215579620J40526236111.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4414, '猎头顾问', '华夏城投项目管理有限公司', '4月27日', '2000-3000元', '西安-未央区', '房地产开发,房地产开发', '100-299人', '未融资', 'CC263935530J40839183215', '任职要求:有水利专业咨询师证书', '华夏城投项目管理有限公司成立于2001年3月，注册资金8000万元。公司实行董事长领导下的总经理负责制，公司拥有中华人民共和国建设部批准的工程造价咨询甲级资质和工程招标代理甲级资质，是一家综合性工程项目咨询企业。公司总部位于陕西省延安市宝塔区嘉陵商务大厦（B）写字楼7层，办公面积800平方米。公司下设总经理办公室、造价咨询一部、造价咨询二部、招标代理一部、招标代理二部、财务部、工程监理部、市场管理部、工程营销部、网络技术部。先后在陕西、宁夏、海南、贵州、青海、甘肃、西藏、重庆、广东、黑龙江、江西、河南、湖北、湖南、吉林、福建、内蒙古、广西、河北、四川、山西、辽宁、新疆等区域设立多家分支机构。总公司现有员工88人，其中专业技术人员50人，高级工程师12人，中级职称20人，初级职称14人，注册造价师30人，专家库成员120人，全部具有大专及以上学历，并曾在工程施工单位、工程建设单位从事过专业技术工作，具有丰富的实际工作经验和扎实的专业理论基础。长期以来，公司秉承“诚信创新、务实高效”的企业理念，坚持“强化服务意识、提高服务质量、加强行业自律、塑造品牌形象”的企业宗旨，华夏公司始终坚持公开、公平、公正的招标原则，建立严格、科学、规范的管理制度，凭借专业的技术水平，为提供高质量的服务奠定了坚实的基础，得到广大客户的一致好评。2016年，我公司获得延安市工程造价咨询“优秀企业”荣誉称号。目前，华夏公司可竭诚为广大客户提供专业性服务，坚定不移的打造华夏品牌,做一流的管理,一流的服务,一流的品牌,一流的信誉。竭诚接受业主委托，承担以下业务：一、工程造价咨询业务范围：企业依法从事工程造价咨询活动，不受行政区域限制。甲级工程造价咨询企业可以从事各类建设项目的工程造价咨询业务。工程造价咨询业务范围包括：(一)承接建设项目建议书与可行性研究投资估算、项目经济评价报告的编制和审核;(二)建设项目概预算的编制与审核，并配合设计方案比选、优化设计、限额设计的工作进行工程造价分析与控制;(三)建设项目合同价款的确定(包括招标工程工程量清单和标底、投标报价的编制和审核);合同价款的签订与调整(包括工程变更、工程洽商和索赔费用的计算)及工程款支付，工程结算及竣工结(决)算报告的编制与审核等;(四)工程造价经济纠纷的鉴定和仲裁的咨询;(五)提供工程造价信息咨询服务;工程造价咨询企业可以对建设项目的组织实施进行全过程或者若干阶段的管理和服务。二、工程招投标代理业务范围：可承担各类工程的招标代理业务。包括：各类土木工程、建筑工程、线路管道和设备安装工程及装修工程项目的勘察、设计、施工、监理以及与工程建设有关的重要设备(进口机电设备除外)、材料采购招标的代理。三、工程咨询服务业务范围包括：（一）规划咨询：含总体规划、专项规划、区域规划及行业规划的编制；（二）项目咨询：含项目投资机会研究、投融资策划，项目建议书（预可行性研究）、项目可行性研究报告、项目申请报告、资金申请报告的编制，政府和社会资本合作（PPP）项目咨询等；（三）评估咨询：各级政府及有关部门委托的对规划、项目建议书、可行性研究报告、项目申请报告、资金申请报告、PPP项目实施方案、初步设计的评估，规划和项目中期评价、后评价，项目概预决算审查，及其他履行投资管理职能所需的专业技术服务；（四）全过程工程咨询：采用多种服务方式组合，为项目决策、实施和运营持续提供局部或整体解决方案以及管理服务。', 'https://www.zhaopin.com/jobdetail/CC263935530J40839183215.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4415, '大客户代表', '贝壳找房(南京)科技有限公司', '5月13日', '1.2-1.5万', '南京-雨花台区', '互联网,房地产开发', '1000-9999人', NULL, 'CC814052280J40291985604', '如果你不甘平庸；如果你渴望进步与成长，链家欢迎阳光、靠谱、聪明、诚实的你，加入链家，与优秀的人同行，为同一个目标前进。<br>岗位要求：<br>1、本科及以上学历，热爱房地产工作<br>2、高度的敬业精神、优秀的服务意识和团队合作能力，高执行力者优先；<br>3、抗压能力强，能吃苦，亲和力强；<br>4、拼搏进取诚实守信是你的价值观。<br>5、高度的工作热情和团队合作意识，有销售、客户服务或学生社团干部经验者优先考虑；<br>6、市场营销专业、经管类学生优先考虑。<br>7、沟通能力强，普通话标准；有亲和力，工作积极，乐观开朗<br>岗位职责：<br>1、负责客户接待、咨询工作，为客户提供专业的房地产置业咨询服务；<br>2、了解客户需求，提供合适房源，进行商务谈判；<br>3、陪同客户看房，促成二手房买卖或租赁业务；并负责业务跟进和房屋过户手续办理等后续服务工作。<br>4、负责公司房源开发与积累，并与业主建立良好的业务协作关系。<br>我们为您提供：<br>1、完善的培训体系：<br>链家拥有链家专有培训基地、链家学院、专业培训讲师；为所有经纪人开设新人培训、在职经纪人能力提升衔接培训、新任店经理管理培训。<br>2、公平的晋升机制：<br>实力说话，有能力绝对给你好职位！经纪人—店经理-商圈经理-大区总监-总经理<br>3、单纯的工作氛围和工作环境：<br>上下同欲，团结一致！在链家有经理，有师傅，有搭档，在困难的时候会帮你一把，在成长路上会祝你一臂之力，在链家，我们努力不让一个伙伴掉队。在这里您不仅只有工作，还有“家”的温暖<br>4、薪酬与福利<br>见习期：薪资5000+5%提成；<br>转正后：底薪2500元+38%起提<br>7项保险（社保+商保）+带薪年假+年度体检+出国旅游<br>链家地产精英社，最高荣誉舞台，每年给予精英社成员更多的激励奖励，带薪出国游<br>5、工作地址<br>可根据个人意愿就近安排<br>职位福利：五险一金、年底双薪、员工旅游、高温补贴、带薪年假、弹性工作<br>职位亮点：五险一金 弹性工作 团队融洽', '在城市的汪洋中，我们都是漂泊的贝壳，不断的寻找心之安定的居所，形态各异的贝壳，也象征着人们对家的美好向往，在贝壳，有新房、二手、租赁、旅居，海外等房产服务，提供海量的真实房源信息，结合精准的智能搜索，帮你从茫茫“房”海中，找到属于你的那一间。我们开放平台、赋能行业、装修、家居、社区服务……与“住”相关的一切，在这里都可以找到。新的服务和技术在贝壳生态体系里迭代，建立居住新标准，为万千家庭带来更美妙的家的体验。智能、丰富、真实，这就是贝壳。贝壳找房将继承和升级链家网在产品技术、品质控制和数据挖掘等方面的优势能力，继承和持续迭代大数据产品“楼盘字典”，研发和应用VR看房等创新技术手段，为消费者提供更好的服务体验。通过线上交易流程的可视化、线下的闭环服务和平台承诺，为消费者提供安全保障。贝壳找房还将搭建服务者的信用评价体系，为消费者甄选优质服务商，通过营销、经营、供应链、技术、数据、金融、交易等各角度的赋能，让优质服务者和品牌在平台生态中得以更好的发展。未来几年，贝壳将覆盖全中国超过300个城市，服务超过2亿的社区家庭，连接100万职业经纪人和10万家门店，赋能超过100个品牌，作为基础设施推动行业正循环。', 'https://www.zhaopin.com/jobdetail/CC814052280J40291985604.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4416, '内容审核', '首聘(北京)科技有限公司', '7月22日', '4000-6000元', '大连-甘井子区', '企业服务,电子商务', '1000-9999人', '未融资', 'CCL1272782040J40768285814', '轻松审核专员 看看文字~刷刷图片~<br>有违规内容，删除下架处理<br>10-7 双休 月休8天<br>要求：大专及以上学历<br>接受无经验小白，接受25届应届生，入职有培训，有老师教', '首聘(北京)科技有限公司成立于2015年08月31日，注册地位于北京市朝阳区霄云路40号院1号楼12层。经营范围包括一般项目：技术服务、技术开发、技术咨询、技术交流、技术转让、技术推广；企业管理咨询；社会经济咨询服务；软件开发；市场调查（不含涉外调查）；计算机系统服务；电子产品销售；通讯设备销售；计算机软硬件及辅助设备批发；计算机软硬件及辅助设备零售；人力资源服务（不含职业中介活动、劳务派遣服务）；外卖递送服务；物业管理；园林绿化工程施工；城市绿化管理；电子、机械设备维护（不含特种设备）；电气设备修理；通用设备修理；专用设备修理；停车场服务。（除依法须经批准的项目外，凭营业执照依法自主开展经营活动）许可项目：建筑劳务分包；第二类增值电信业务；测绘服务；劳务派遣服务；食品销售。（依法须经批准的项目，经相关部门批准后方可开展经营活动，具体经营项目以相关部门批准文件或许可证件为准）（不得从事国家和本市产业政策禁止和限制类项目的经营活动。）首聘(北京)科技有限公司对外投资12家公司，具有17处分支机构', 'https://www.zhaopin.com/jobdetail/CCL1272782040J40768285814.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4417, '招聘专员/助理', '苏州云千企业管理有限公司', '7月18日', '9000-10000元', '无锡-滨湖区', '网络/信息安全', '300-499人', NULL, 'CCL1493543080J40774856407', '诚聘有志青年，不甘平庸，敢于突破自己，敢于奋斗<br>工作内容：<br>给厂区招人。通过58、boss、智联、快手、抖音（公司提供）<br>工轻作松一人一台电脑（一对一教学），环境优雅<br>中午12点休息到下午两点。上六休一，平时主要工作就是回复消息，与求职者沟通<br>小白也有一对一教学。<br>薪酬模式：<br>50%提成（和公司对半）<br>无责底薪4500+10%提成<br>综合工资12000+（上不封顶）<br>任职要求：<br>16-28周岁，晋升空间大（专员-组长-团队长）<br>福利待遇：<br>办公室配备茶水间，零食水果奶茶，不定期聚餐（每半月一次甚至更频繁），公司有pk有奖励，对表现优异者奖励丰厚，具体可面议（最新iPhone16等），定期户外旅游，节假日奖品不定<br>公司提供住宿，刚来这座城市没租房的朋友可带行李入职住宿，欢迎加入我们', '苏州云千企业管理有限公司成立于2024年08月02日，注册地位于苏州高新区马运路218号华枫大厦1幢3楼332室，法定代表人为张利亚。经营范围包括许可项目：第二类增值电信业务；互联网信息服务；第一类增值电信业务；职业中介活动（依法须经批准的项目，经相关部门批准后方可开展经营活动，具体经营项目以审批结果为准）一般项目：企业管理；企业管理咨询；物业管理；生产线管理服务；软件外包服务；劳务服务（不含劳务派遣）；信息咨询服务（不含许可类信息咨询服务）；装卸搬运；家政服务；日用百货销售；劳动保护用品销售；人力资源服务（不含职业中介活动、劳务派遣服务）（除依法须经批准的项目外，凭营业执照依法自主开展经营活动）', 'https://www.zhaopin.com/jobdetail/CCL1493543080J40774856407.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4418, '招聘专员/助理', '蜜蜂速聘(天津)科技有限公司', '7月16日', '9000-12000元', '北京-朝阳区', '企业服务,咨询服务,在线生活服务（O2O）,互联网', '300-499人', NULL, 'CC863634910J40773149102', '月薪10000以上，接受小白，五险一金，晋升空间大，法定节假日正常休息，就近分配<br>【薪资待遇】<br>无责底薪7000/转正无责7500+绩效，综合薪资：9000-13000<br>【岗位职责】<br>账号运营，筛选简历，电话沟通，邀约面试等工作<br>【工作时间】<br>1、09:00-20:00<br>2、月休8天<br>3、法定节假日正常休息，【过年放10天】<br>【晋升体系】<br>A、纵向发展路线：<br>1、职级晋升（底薪）：P1级别-P8级别，每次晋级底薪都上涨<br>2、晋升管理：小HRBP-大区主管-部门经理-中心总监<br>【工作氛围】：身边同事均为各高校的本科或研究生，逢节必过、经常团建和出游！<br>【岗位要求】<br>1、年龄21-28周岁，本科及以上学历，211和985及相关经验者优先；<br>2、形象气质佳，语言沟通能力强，富于亲和力；<br>3、吃苦耐劳，有上进心、抗压能力强；<br>4、有良好价值观，有较强的沟通协调能力和团队协作精神；', '公司成立于2017年初，历经多年的专业深耕，业务已经覆盖全国20个多个省市及地区，企业好评获得官方与政府的一致好评，目前公司在北京、天津、河北、贵阳、长沙、上海、南京等多地都分别开设相应的分公司，公司员工百人，服务人员涉及覆盖关系约60万人，服务近百家企业，包括多家国企，央企，众多企业保持多年的长期合作。感受公司的服务：勤劳，诚信，坚守，增值，不忘初心，砥砺前行。做有温度，有付出，有收获，有包容，有理想，有利于国家与人民的企业。', 'https://www.zhaopin.com/jobdetail/CC863634910J40773149102.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4419, 'BD经理', '广州欢创信息咨询有限公司', '6月26日', '7000-10000元', '宜昌-当阳市', '人力资源服务,咨询服务,专业技术服务,人力资源服务', '100-299人', '未融资', 'CC531289680J40750028009', '岗位职责：<br>1、维护区域现有加盟餐饮商户，并通过各种途径开发新餐饮商户<br>2、了解并根据商户需求，制定个性化营销方案，与商户谈判并达成合作<br>3、通过现场销售，提升餐厅的信息化、数据化管理水平<br>4、优秀的谈判能力，配合Marketing团队完成营销项目跟进并能够独自完成营销项目<br>5、及时处理来自商户的投诉，反馈、建议等，以提高商户的满意度。<br>任职要求：<br>1、行业不限，有餐饮、面对面销售、020行业经验者优先考虑<br>2、学历大专及以上，优秀应届生可以择优录用，27周岁以下<br>3、市场拓展能力强，具有较强的陌生拜访及挖掘客户能力<br>4、优秀的语言表达能力、良好的人际沟通能力，乐于从事挑战性的工作<br>5、抗压能力强，能够独立负责一个区域的销售和推广工作', '广州欢创信息咨询有限公司是一家全国性集团公司，以技术驱动的整体人·财解决方案服务商，全国80+自营分公司，500+服务网点，公司拥有人社局颁发的劳务经营许可、人力资源服务许可等相关行业资质，已获得行业门槛较高的《增值电信业务经营许可证》，同时是众多大型企业的呼叫中心外包服务商。已顺利通过IS09001质量管理体系认证，荣获第七届世界军人运动会后勤保障突出贡献奖、美的集团优秀人才供应商、58集团颁发中国卓越雇主奖、招商银行薪酬福利典范企业，是行业规模、专业素质和客户满意度方面均位居前列的人力资源、税务筹划综合服务商。', 'https://www.zhaopin.com/jobdetail/CC531289680J40750028009.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4420, '猎头顾问', '灏信法务咨询(佛山)有限公司', '2025-07-28 01:54:53', '8000-15000元', '海口-秀英区', '咨询服务,咨询服务', '100-299人', '未融资', 'CCL1441470070J40782887314', '服务咨询顾问信用卡逾期、网贷逾期、债务优化师(可兼职)<br>  <br> <br>  <br>行业概况：<br>  <br>个人/企业债务领域一站式解决债务问题，给予债务人一个重新履约的机会，具备绝对的市场竞争力，万亿级的蓝海市场，业务覆盖全国范围!<br>  <br> <br>  <br>主营业务：<br>  <br>1、各大银行信用卡、信用贷逾期: 停息挂账、避免催收、避免诉讼、停止罚息、违约金等费用，最长可分60期<br>  <br>2、互联网金融/网货平台： 避免催收困扰，高额利息/罚息，减免超出司法保护上限利息<br>  <br> <br>  <br>企业以及个人相关法律咨询服务帮扶制度：<br>  <br>1、多维度培训系统：从项目培训到推广和管理，手把手引导新手小白创业/入行<br>  <br>2、一对一帮扶系统：合似人传承制一对一扶持，从小白到大咖的路径扶持<br>  <br>3、纵深服务系统：向下延伸服务，全方位赋能支持<br>  <br>4、售后客服体系：无忧操作，及时解答客户疑问<br>  <br>5、律所法务支持：自家的律所为强大后台，以专业、敬业的态度解决客户问题<br>  <br>6、积极创新能力：持续不断开发新的市场项目，保证业务持续性<br>  <br> <br>  <br>岗位要求:<br>  <br>1、性别年龄不限，口齿清晰，语音富有感染力，心态年轻积极健康。<br>  <br>2、可接受无经验（前期有导师培训）有销售经验者优先，无经验者培训上岗。<br>  <br>3、思维清晰，学习能力强，有目标感，能够为达目标善于思考<br>  <br>4、热爱销售行业，善于与人打交道，熟练使用微信及网络<br>  <br>5、深刻领会公司的经营理念，服务理念，并落实到实际工作中<br>  <br>6、勤奋、吃苦耐劳，能承受前期开拓压力，抗得住诱惑，受得了委屈，经得起打击，守得住希望、那么我们的故事就可以开始了！<br>  <br>7、有过负债经历、有过 POS机、办过信用卡、货款、催收、保险金融、旅游行业、美业、房地产、二手车新车交易、微商小伙、人力资源外包公司相关经历工作的，上手更加容易<br>  <br> <br>  <br>工作内容：<br>  <br>1、公司可提供精准优质客户资源，可自身开发，客户意向高，好成交<br>  <br>2、对客户进行整理归类，长期维护好客户关系 <br>  <br> <br>  <br>工作时间：朝九晚六，午休1.5小时（双休）工作氛围轻松无压力<br>  <br> <br>  <br>薪资构成：底薪+高提成+开单奖，综合薪资8000起<br>  <br>1、社保+节假日福利+免费专业知识培训<br>  <br>2、不定期下午茶、定期团建、户外拓展、节日活动；<br>  <br> <br>  <br>福利制度：<br>  <br>国家法定节假日心意礼品+每月奖金，冰箱，微波炉，水果，零食下午茶，节日+生日福利+<br>  <br>不定期团建活动<br>  <br>月度季度年度奖状奖杯奖金<br>  <br>定期进行活动及专业知识培训等<br>', '行业概况：个人/企业债务务领域一站式解决债务问题，给予负债人一个重新履约的机会，具备绝对的市场竞争力，万亿级的蓝海市场，业务覆盖全国范围!主营业务：1、各大银行信用卡、信用贷逾期:停息挂账、避免催收、避免诉讼、停止罚息、违约金等费用，最长可分60期2、互联网金融/网货平台：避免催收困扰，高额利息/罚息，减免超出司法保护上限利息', 'https://www.zhaopin.com/jobdetail/CCL1441470070J40782887314.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4421, '项目经理/主管', '江苏久高电子科技有限公司', '7月17日', '6000-12000元·13薪', '南京-玄武区', '计算机软件,通信/网络设备', '20-99人', '未融资', 'CC551369320J40402201009', '岗位职责：<br>1、工作内容直接向项目总监进行汇报；<br>2、 协助进行公司业务产品的前期技术交流、需求沟通，中期产品选型、清单报价、技术方案支持；<br>3、分析客户需求、与客户进行交流，编写方案设计报告及其他技术方案；<br>4、参加招投标会，进行技术、商务上的讲解和答疑；<br>5、参加商务和技术的谈判，参与起草项目技术协议书；<br>6、对行业内新技术新产品和新项目进行技术跟踪；<br>7、与客户对接各项技术需求，协调指导研发工程师开展各项工作，成为公司内部与客户之间的纽带。<br>岗位要求：<br>1、大专以上学历，具有相关项目管理及服务经验；<br>2、熟悉机械、机电产品，具有一定机电一体化领域的专业知识；<br>3、性格开朗活泼，良好的心理素质，能够适应挑战，抗压能力强；<br>4、具备不断学习的态度，责任心强，思路清晰，具备较强的客户服务意识以及良好的沟通协调能力。<br>公司提供福利：<br>1、优厚的薪资待遇：不低于行业水平的薪资、明确的涨薪体系、不吝啬重奖每一位员工，还有绩效奖、季度奖、年终奖、股票期权红利，我们全包。<br>2、完善的晋升机制：周末双休、五险一金、午餐补贴、带薪休假、节日礼品、生日欢庆、定期团建，这些统统有！<br>3、透明的晋升机制：成熟透明的晋升体制，唯才是举，帮助每一个员工步步高升！<br>4、扁平化的成长空间：没有繁琐的工作流程、没有复杂的工作汇报，自由与效率、职责与权利的最大化！<br>5、结识牛人的机会与资源：行业大咖、企业大佬、研发狂人，我们天天见！<br>6、自我价值实现的平台：最大的输出空间，敢想敢做、敢拼敢闯在这里是经典加分项！<br>7、轻松的工作环境：我们的团队70后幽默、80后热情、90后大胆、00后活泼，与领导见面不拘束，与同事见面不张扬是我们的常态！<br>公司诚聘精英，广募良才，希望这样的你加入团队：<br>有良好的团体精神和协作力，做事认真、仔细、吃苦耐劳、责任心。<br>有理想有抱负，希望通过推动公司的发展推动各人能力的提升，和公司一起成长。<br>不一定有学历，但一定要有学习力！<br>职位福利：五险一金、加班补助、交通补助、餐补、周末双休、带薪年假  <br>', '江苏久高电子科技有限公司，是一家集研发、生产、销售于一体的军民融合性高新技术企业。公司成立于2013年，注册资本1000万元，研发中心位于江苏省南京市玄武区徐庄软件园福中高科技产业园。公司以服务于武器装备现代化为目标，以确保战斗力提升为导向，注重于技术创新及其可靠应用，聚焦进口产品的国产替代，聚焦武器装备自主可控，打造优势产品与服务。公司致力于风机领域深耕细作，深入了解武器装备制造热控专业领域的特殊需求，专注于不同场景、适用严苛环境（气候、振动、电磁）条件的风机，为客户定制化设计、研发、制造与集成，重点对标国外一流高性能风机提供商相关产品，无缝替代AMETEK、LMB及EBM等公司产品。广泛应用于航天、机载、舰船载、车载、弹载等多种武器装备平台。公司一贯坚持“以客户需求为使命、视产品质量为生命”，按照GJB9001C-2017标准规范化研发、生产与服务，公司目前已整合国内优质风机设计、生产与试验配套资源，包括各型风洞、各型环境试验设备、风机专用设备及工装，可为客户提供以高性能直流风机为核心的全方位热控解决方案。公司愿景：国产替代自主可控创新引领者。公司提供福利：优厚的薪资待遇、完善的晋升机制、透明的晋升机制、扁平化的成长空间、结识牛人的机会与资源、自我价值实现的平台、轻松的工作环境。公司诚聘精英，广募良才，希望这样的你加入团队：有良好的团体精神和协作力，做事认真、仔细、吃苦耐劳、责任心。有理想有抱负，希望通过推动公司的发展推动各人能力的提升，和公司一起成长。不一定有学历，但一定要有学习力！', 'https://www.zhaopin.com/jobdetail/CC551369320J40402201009.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4422, '知识产权/专利代理', '北京汇思诚业知识产权代理有限公司', '6月20日', '8000-12000元·13薪', '天津-南开区', '咨询服务,咨询服务', '100-299人', '未融资', 'CC591550920J40382776514', '职责描述： <br>', '北京汇思诚业知识产权代理有限公司（Beijing UNI-INTEL Patent& Trademark OFFICE，机构代码11444）是一家综合性知识产权服务机构，致力于解决客户知识产权问题，为客户提供有关商标、专利、版权、法律诉讼等一站式知识产权服务。从2013年成立至今，汇思诚业实现高速发展，总部位于北京，并且还设立有东京、上海、深圳、天津、成都、济南均设立有办公室。汇思诚业拥有热诚的知识产权顾问和强大的专利代理人团队，快速应对客户需求，解决客户知识产权问题，助力客户利用知识产权这个工具获得更大的商业成功。汇思诚业的客户遍布各行各业，均为国内外的大型企业。汇思诚业企业文化汇思诚业的使命：使客户更加成功；成就员工理想；担负社会责任。汇思诚业的愿景：打造一家大型国际化知识产权服务机构。汇思诚业的经营理念：快速响应客户需求，解决客户知识产权问题。汇思诚业的精神：诚信、精业、勤勉、厚重。汇思诚业的核心价值观：客户利益优先、员工竞争激励制度、可持续发展理念为什么选择汇思诚业？·汇思诚业是一家高速成长型公司，组织架构灵活，客观上能够为德才兼备的人才提供晋升机会，各地办公室非常欢迎有经验的资深代理人加盟，优秀人才可以挑战领导岗位；·汇思诚业注重对员工的培养，在专业上、管理上帮助员工提升能力；·汇思诚业在北京、天津、深圳、上海、东京均设有办公室，为员工提供多种选择；·汇思诚业的服务对象均为国内外知名高端企业，方便代理人长期服务固定客户、提供服务效率和质量；·汇思诚业处理了大量的诉讼、无效业务，积累了非常宝贵的经验，对于资深代理人，汇思诚业通过模拟口审进行培训，并提供机会与汇思律师共同处理无效诉讼业务。·汇思诚业的涉外业务同样做得非常出色，欢迎涉外代理人加盟，在汇思诚业可以同时承办外内、内外、FTO、无效、诉讼等业务。·完善的福利，极具竞争力的福利体系：双休、法定节假日、年休假、忠诚奖（工龄工资）、社保金、过节礼品/礼金、生日礼品、定期娱乐活动、定期体育活动……', 'https://www.zhaopin.com/jobdetail/CC591550920J40382776514.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4423, '律师', '山东平正大律师事务所', '7月25日', '1-2万', '济南-历城区', '咨询服务', '20-99人', NULL, 'CC608436320J40528428004', '1、热爱法律行业，支持律所发展，能够认同山东平正大律师事务所的发展理念，适应律所创新发展模式;<br> <br>　　2、合伙人律师需已取得律师执业资格证，具备明确业务方向(公司法、行政法、刑事、民事、商法、涉外等业务领域)，可以独立组建业务团队或法律部门;并具有较强的业务拓展能力、稳定的客户资源和固定案源收入。<br> <br>　　3、有独立承办某一专业领域诉讼或非诉讼项目的经验;<br> <br>　　4、有较强的组织管理能力和沟通协调能力，带领团队发展;<br> <br>5、工作作风严谨、品行端正、具有良好的律师职业操守，遵守律师执业规范;<br> <br>招聘人数：20位<br> <br>　　薪资待遇：参与律所管理，享受律所正常提成和律所投资收益。', '山东平正大律师事务所成立于1996年，是山东省司法厅直属的律师事务所。坐落于济南市东环国际广场，具有1000多平方米的办公场所，下设民商、刑事、房地产、公司、金融证券、知识产权六个业务部室及行政办公室和财务室，有50余名律师，其中高级律师4名，研究生以上学历律师11名。因发展需要，现向社会招募优秀人才。', 'https://www.zhaopin.com/jobdetail/CC608436320J40528428004.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4424, '猎头顾问', '平安融易(江苏)融资担保有限公司河南分公司', '7月26日', '9000-15000元', '新乡-红旗区', '互联网金融/小额贷款', '1000-9999人', '已上市', 'CC878477620J40782997613', '工作地点：郑州、新乡、平顶山、商丘可选', '平安融易品牌简介：平安融易是中国平安集团旗下陆金所控股的融资服务品牌，专注于为小微企业主、个体经营者及个人提供融资服务。秉持“专业，让融资更容易”的使命，以科技驱动创新，以服务赢得信赖，赋能合作金融机构提质增效，助力客户成长，助推普惠金融高质量发展。依托强大的金融实力与科技赋能，平安融易运用智能风控、大数据分析等领先金融科技，为小微企业主、个体经营者及个人提供精准、便捷的融资解决方案。同时，注重线下服务的深度与温度，通过专业的服务团队，为客户提供面对面的融资咨询服务，切实满足其多样化的金融需求。平安融易（江苏）融资担保有限公司（原平安普惠融资担保有限公司）是“平安融易”的核心业务主体，经监管部门批准，在全国各地设立分支机构。面小微企业主、个体经营者及个人提供融资担保、融资咨询服务。', 'https://www.zhaopin.com/jobdetail/CC878477620J40782997613.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4425, '游戏推广', '德阳今玺文化传媒有限公司', '7月29日', '200-400元/天', '全国-None', '新媒体', '10000人以上', NULL, 'CCL1486510840J40784202714', '无销售性质 简单轻松<br>1.工作内容简单 接受小白 有师傅带<br>2.手机即可工作 学生宝妈上班族都可以（18-35岁）<br>3.居家办公 时间灵活自己安排<br>4.无任何押金及费用没有培训费 不受约束时间越长收益越多<br>感兴趣欢迎投递无销售性质 简单轻松<br>全程不收取费用', '公司全是可爱的年轻人，没有代沟，不需早起上班哦，工作弹性大，只要敢想敢做，就差可爱的你和我们一起共同努力啦！！！！期待每一位有能力，有梦想的你，加入我们一起共创辉煌！！！！！！！！！！！！！！！！！！！！', 'https://www.zhaopin.com/jobdetail/CCL1486510840J40784202714.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4426, 'BD经理', '齐齐哈尔天行运输服务代理有限公司', '7月25日', '1-2万', '南京-建邺区', '货运/物流/仓储', '100-299人', NULL, 'CCL1438629580J40797018205', '岗位内容：<br>1. 负责制定并实施营销策略，拓宽潜在客户渠道；<br>2. 负责开拓新客户，并维护已有客户关系；<br>3. 完成销售任务及业绩指标，提升客户满意度；<br>4. 分析并了解市场发展趋势，为公司提供有价值的建议。<br>任职要求：<br>1. 具备从事BD工作的经历，能够打开市场；<br>2. 对本行业市场行情有很好的了解，并具备市场开拓能力；<br>3. 具备优秀的谈判和沟通能力，善于发现问题并解决；<br>4. 执行力较强，能够承受一定的工作压力，认真负责。', NULL, 'https://www.zhaopin.com/jobdetail/CCL1438629580J40797018205.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4427, 'BD经理', '广州市九重天信息科技有限公司', '5月27日', '4000-5000元', '广州-天河区', '计算机硬件,计算机软件,IT服务', '20-99人', NULL, 'CC158467510J40305305503', '岗位描述：<br>1、做好商务信息的收集、整理、分类，对项目信息实时跟踪；<br>2、在上级经理的指导下做询价，报价工作，采购合同的执行，采购物品交期的跟踪及控制，与供应商的沟通协调；<br>3、协助技术经理做好标书，整理、编制商务文件模板，改进和规范技术工作流程，收集并对往来商务信函、传真、邮件存档备案；<br>4、制定每周工作安排，并制作周报表，月报表交由主管部门经理审查与考核。<br>6、完成对公司所有产品售后的协调与跟进。<br>7、执行完成上级交给的其他临时性工作。<br>职责要求：<br>1、应届毕业生或毕业1-2年，大专或以上学历，计算机等相关专业优先；<br>2、工作认真负责，细心周到，形象气质佳，有采购、销售及会计经验者优先；<br>3、积极进取、细致周到，能承受工作压力、责任心强、对数字敏感； <br>4、具有较强的语言表达能力、沟通能力和文字组织处理能力；<br>5、具有良好的人际沟通、协调能力和团队合作精神；<br>6、能够熟练应用办公室OFFLCE软件。', '广州市九重天信息科技有限公司是一家专业从事IT数据计算、数据安全保护、视频监控以及IT增值服务为一体，面向商业计算和数据安全的高科技公司。面向新世纪的机遇和挑战，公司将专注于中国行业信息化应用，致力于为客户提供以应用为核心的信息技术产品、应用方案及服务，全面构建互联网时代客户所需的核心业务系统及电子商务平台，成为中国企业、政府等走向数字化时代的倡导者和服务者。九重天公司自成立以来，一直以专业服务为导向，以专业的团队，专业的技术服务能力，在数据管理和IT服务细分市场内，为客户提供专业的数据管理与IT服务支持，满足用户在IT服务企业过程中对专业技术服务支持能力的要求，用九重天人的激情、勤奋、专业，与客户共享专业技术服务所带来的价值，同时努力将九重天打造成中国最专业的数据管理与IT服务供应商之一。主要经营范围：数据计算设备：包括小型机、PC服务器、高性能计算设备，计算机集群系统(百万亿次）等产品和解决方案，保证业务运行永不停顿；企业级数据存储设备：经营国际国内一流存储设备产品，包括EMC、LSI、浪潮等产品和解决方案。企业级数据安全保护：包括面向企业级数据备份、数据归档、数据同步、数据保护CDP、数据容灾等一系列数据安全产品及解决方案，保证业务数据永不丢失；军方级涉密数据保护：提供国家军方级数据保护产品和方案，包括金盾系列和金刚系列。 IT运维管理平台：提供IT多角度全方位管理维护，包括集中管理、网络管理、应用管理、桌面管理、安全管理等五大管理模块。视频监控设备：提供监控服务器和存储设备、摄像机、3G无线图传设备等。广州市九重天信息科技有限公司是一个不断创造奇迹的企业，一个值得您信赖的企业、一个您必将选择的高科技企业。福利待遇： 1、薪酬待遇=具有市场竞争力的底薪+绩效+提成+报销+午餐补助+社保+公积金+丰厚节日福利礼品+广阔的晋升空间。 2、依法享受国家法定节假日（元旦、五一、国庆、春节、中秋等）；劳动法规定的带薪假（如：婚假、产假、陪产假等）；劳动法规定带薪年假； 3、标准工作周时间：一周五天工作制（双休：周六、日休息）。 4、标准工作日时间：9：00-12：00，14：00-18：00，中午休息2小时。', 'https://www.zhaopin.com/jobdetail/CC158467510J40305305503.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4428, 'BD经理', '康源博创生物科技(北京)有限公司', '11月11日', '1.5-3万', '北京-通州区', '医药制造', '100-299人', 'B轮', 'CC535562480J40530551910', '招聘职位:销售经理<br>岗位职责:<br>1. 负责公司药物研发领域相关产品和服务，包括工程细胞、体内体外药效，抗体发现等技 术平台在制药/生物技术公司工业客户以及其他相关机构的销售和推广。<br>2. 开发和维护制药/生物技术公司工业领域新客户。<br>3. 全面了解客户的需求，参加展会。制定销售计划。<br>4. 上级交办的其他工作。<br>任职要求:<br>1. 本科及以上学历，要求生物等相关专业。 有销售经验者优先。<br>2. 有责任心、忠诚可靠、有团队协作精神。<br>3. 性格外向，开朗，乐于沟通。对客户推进有明晰的管理，对产品销售有策划和执行力， 能完成销售任务，有一定的抗压能力。<br>4. 能接受出差。<br>工作地点<br>居住地在北京/天津/山东等 薪资面谈，待遇丰厚，职业生涯成长广阔，底薪加销售提成，公司期权等', '康源博创成立于2017年，是一家致力于基因工程细胞株构建和肿瘤药物筛选研发服务的生物高科技平台公司。2017年3月注册，注册资本为500万元。位于北京市经济技术开发区科创六街88号生物医药园内，2017年获得中关村自主创业示范园区“金种子工程企业”认定。2018年3月经北京市科技委员会认定为北京市科技型中小企业，2018年4月被亦庄经济技术开发区评为“亦麒麟”领军人才创办企业。公司拥有自主产权的肿瘤细胞库包括基因工程细胞株、传代细胞株和原代肿瘤细胞株，合计1000多株。公司构建了全合成的人源噬菌体抗体库，拥有自主知识产权抗体项目4个。公司开发了线上数据库innopedia.kyinno.com.公司开发的NovoImmunity肿瘤精准医疗和Neoantigen生物信息分析工具已为医院和患者提供服务。', 'https://www.zhaopin.com/jobdetail/CC535562480J40530551910.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4429, '英语翻译', '北京天星浩宇国际文化传播有限责任公司', '6月16日', '100-120元/天', '北京-丰台区', '广播/影视,翻译服务,广播/影视,咨询服务', '20-99人', '未融资', 'CC374169030J40372899009', '岗位职责：<br>1.配合项目经理，负责纪录片项目查证工作，协助管理分派翻译项目并跟进落实；<br>2. 对翻译稿件进行文字质检并格式规范化处理。<br>任职要求：<br>1.有一定的英语基础，通过大学英语4、6级或者专业四级、八级优先；<br>2.对外语纪录片、影视剧感兴趣，熟悉视频媒体翻译行业者优先；', '北京天星浩宇国际文化传播公司成立于2012年，致力于国外电视视频节目的引进、译制配音以及后期制作服务，专为国家级乃至世界著名的广播电视媒体提供服务，主要服务对象有BBC、CCTV、央视风云等大牌电视媒体，同时也包括优酷、咪咕、爱奇艺、腾讯、B站等一些新兴的网络媒体。近几年来，在政府提倡文化大繁荣大发展的背景之下，我们作为一家提供专业性服务的民营公司一直扎根视频媒体行业，凭借在引进片翻译领域和视频后期技术领域的优秀人才储备和经验积累，以及我们以服务客户为第一要务的敬业精神，实现了公司相关业务的持续高速发展，并得到了业界的广泛好评和推荐。随着与多家知名媒体企业合作的日益深入，我们希望能够作为一分子，在将全世界的优秀电视节目引进来，让中国的优秀电视节目走出去的文化使命性工作中发挥优势，贡献力量。译制作品包括：《王朝 Dynasty》、《蓝色星球 The Blue Planet》、《地球脉动 Planet Earth》、《Top Gear》的英国版、美国版、韩国版等各国版本等作品', 'https://www.zhaopin.com/jobdetail/CC374169030J40372899009.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4430, '管培生/储备干部', '沈阳东管电力科技集团股份有限公司', '7月28日', '6000-10000元', '北京-朝阳区', '专用设备制造,石油/石化,金属制品业,电气机械/电力设备', '300-499人', '已上市', 'CC189169110J40759741101', '1、每天负责跟踪国内电力/石化等重点项目，收集相关项目信息。<br>2、辅助销售经理开展签合同签订，项目执行等工作。<br>3、制作标书。', '沈阳东管电力科技集团股份有限公司（以下简称“东管科技”），拥有东管重工（沈阳）有限公司、东管核电新能源装备（沈阳）有限公司等四个子公司），主要从事锅炉、压力容器、高温高压管件、管道系统模块化产品的研发、设计和制造，是高新技术企业。产品主要应用于石油、化工、煤化工、高效火电、核电、天然气发电等能源领域。东管科技位于沈阳经济技术开发区沈西三东路33号，注册资本1.43亿元，现有员工380余人。目前已经获得沈阳市财政局下“恒西创投”总额6,000万股权投资，持有公司11.92%的股份，辽宁省产业创业投资引导基金对集团下属子公司东管核电新能源装备（沈阳）有限公司投资2600万元，实现初步的混合所有制经济形式。2015年12月29日，东管科技在北京新三板正式挂牌上市。2019年东管科技被评为国家级“专精特新”小巨人企业。东管科技厂区占地面积360亩，分二期建设。其中一期工程建筑面积78500㎡已全部投入使用。主厂房为六连跨结构（63800㎡），包含1）压力容器生产车间、2）管件（弯管）生产车间、3）配管车间、4）锅炉生产车间、5）成品、原材料储存仓库，以及与其配套的相关设施如酸洗间、变电所、焊材库、油漆库、检测中心等。一期工程还建设了办公辅楼4000㎡、食堂5000㎡、职工宿舍5700㎡。东管科技拥有压力容器（A1、A2级）制造及设计许可证、锅炉（A级）制造许可证、压力管道元件（A(1)(3)级、B级、B1(2)级）制造许可证，美国机械工程师协会（ASME）颁发的压力容器（U）、锅炉（S）、压力管道（PP）的授权钢印和证书，还通过了ISO质量、环境及职业健康体系认证。公司锅炉、容器类产品包括：电力锅炉类：过热器、再热器、省煤器、低低温省煤器、环形集箱、集箱、布风板等；电力容器类：高压加热器（U型管式、蛇型管式）、低压加热器、除氧器、热网加热器、辅气联箱、耦合器、闭式水换热器、定期排污扩容器，连续排污扩容器、分汽缸、压缩空气储罐等；石化容器类：高温高压单层容器、管壳式热交换器（固定管板，浮头式，U型管式），特殊换热器（高通量管换热器，波节管换热器，螺旋折流板换热器，折流杆换热器，余热回收器，翅片管换热器）、中压汽包、塔器、反应器、反应釜、储罐等。东管集团主要业绩1、石油化工领域：东管集团作为石化设备的设计和制造商，为国内外石化项目提供高品质压力容器设备，主要客户业绩包括：1)中石化：一级供应商，为中科炼化、镇海炼化、燕山石化、沧州石化等项目长期提供换热器、储罐等产品，与中石化洛阳院、上海院、SEI等有长期合同关系，为中科炼化等项目供应加氢裂化高端重型装置。2)中海油：为中海壳牌惠州项目提供P91等高材质管件。3)中国化工集团：为昌邑石化等提供换热器等装置。4)中国化学集团：为中国成达公司的印尼芝拉扎、拉布湾等项目提供管材等产品。5)神华集团：为新疆化工等项目供应高通量管、螺旋折流板换热器等高难度设备。6)大唐集团：为大唐阜新煤制气、克什克腾煤制气、多伦煤化工等项目提供产品。7)阳煤集团：为其下属的昔阳化工、平定化工等项目提供换热器、储罐等产品。8)中粮集团：为其下属的中粮生物化学项目提供管材管件产品。9)地方化工项目：为多家化工企业，如恒力石化、宝泰隆煤化工、唐山金坤化工、盘锦宝来、陕西龙门化工、江西晶昊等化工企业提供反应装置所用容器等设备。10)造纸行业：为晨鸣纸业、玖龙纸业等造纸企业供应管道管件等产品。11)宝泰隆煤化工项目：国内首台波节管重叠式循环气换热器。12)出口项目：为伊朗化肥项目等提供换热设备。2、火电、核电、天然气发电领域：作为电力管道系统及锅炉设备的设计和制造商，为国内外多个火电、核电、天然气发电项目提供服务，核心业绩包括：1）世界首台1350MW超超临界二次再热机组工程——申能安徽平山电厂二期四大管道、管件及工厂化配管供应商2）国内首个1000MW、660MW超超临界火电机组四大管道总承包商,首次引进火电超超临界机组用A335P92钢材。2004年集团中标中国首个1000MW级超超临界火电机组项目——华能玉环电厂（4×1000MW）；2005年中标中国首个600MW级超超临界机组项目——华能营口电厂（2×600MW），成为其四大管道、管件、工厂化加工总承包商。依托这两个项目，东管集团首次引进A335P92管材、管件、焊材应用于国内超超临界火电机组，开创国内A335P92钢使用之先河。3）在行业中率先通过P92钢材焊接性能鉴定。为了适应我国超超临界火电机组的发展需要，填补国内P92新型钢种的焊接工艺的空白。', 'https://www.zhaopin.com/jobdetail/CC189169110J40759741101.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4431, '社区运营', '八宇健康科技集团有限公司', '7月22日', '5000-10000元', '德州-德城区', '互联网,计算机软件,物联网,居民服务', '100-299人', 'A轮', 'CC880989530J40793109113', '岗位职责：  <br>1、根据集团的经营指标要求及标准化管理体系流程要求，协助运营总监负责居家养老业务线的运营管理工作；', '八宇健康科技集团总部在山东济南，主营业务在智慧养老方向，在业内有较高的品牌知名度。八宇是国家级高新技术企业、双软认证企业、省专精特新企业、省瞪羚企业和济南市瞪羚企业，截至目前在黑龙江、辽宁、内蒙古、陕西、新疆、山东、江苏、河南、湖北、湖南、安徽、江西、重庆、四川、贵州等省份设立有子公司，面向全国市场的布局框架已形成，处于高速发展阶段。八宇现阶段主要聚焦于家庭养老床位建设业务，以适老化改造作为服务场景的切入点，通过为民政局建设养老服务监管平台和提供平台深度运营服务，推动实现区域（地级市/区县）内所有养老机构的业务线上化；再辅以养老服务自营示范的轻量级运作方式，助推区域智慧养老服务体系的建立、加快养老行业的服务规范化进程和市场主体的培育催熟。养老行业目前处于大风口期，是眼下有限的几个新兴大行业之一。八宇对自身的定位是互联网型的行业解决方案公司，业务模式和理念在业内领先，目前已形成布局全国市场的框架，综合实力位于行业赛道的第一梯队，邀德才兼备者加入平台共谋发展。', 'https://www.zhaopin.com/jobdetail/CC880989530J40793109113.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4432, 'BD经理', '位来小猎(宁波)信息技术有限公司', '7月1日', '8000-13000元', '合肥-蜀山区', '计算机软件,专业技术服务', '100-299人', 'A轮', 'CCL1320375780J40764934607', '福利:六险一金+早十晚七工作+周末法定正常休息+高薪补贴+快速晋升<br>岗位优势:<br>1.抖音正式编制岗位(工作长期稳定、福利待遇好);<br>2.抖音商家团购板块，全品类类目都可做，目前不饱和度高且商家对抖音认可度高，好做(其他团购平台依然可以免费入驻);<br>3.长期存量商家，越久薪资越高;<br>4.六险正常底薪基数+公积金最高比例缴纳;<br>5.1-2周培训，第一天开始就正常发放薪资。<br>岗位职责:<br>1.对于本地商家全品类BD邀请入驻:<br>2.已邀请商家运营工作(帮助推广、安排引流等)。<br>任职资格<br>1.学信网可查本科及以上，有相关销售经验优先<br>2.具备较强的销售能力、客情维护能力、谈判能力、问题解决能力;<br>薪资待遇：<br>底薪+320餐补+500交通补贴+提成 入职六险一金<br>工作时间：<br>早10 晚7 周末双休 法定休息 城市就近分配', '位来小猎成立于2018年1月，2019年6月完成A轮融资；聚焦行业精华，利用后发优势，在1年以内成为行业黑马公司。核心团队成员均有十年以上的人力资源经验，具备丰富的人力资源专业知识和项目实践，服务众多500强企业和知名互联网公司。位来小猎掌握专业领域核心资源，团队迅速扩张，以北京为中心，在全国建立了10家分公司及办事处，业务覆盖全国。现有300+名员工，派遣、外包员工10000+名；服务客户包括国家体育总局，百度，网易，物美多点，美团，字节跳动，喜马拉雅，作业帮，得物，VIPKID，瓜子，京东，拼多多，喜茶，中国人保等。位来小猎以互联网为载体，依托于位来小猎平台、微信公众号、入职有赏微信小程序上活跃的海量求职者资源，核心业务包括人才外包、专业招聘、业务外包、转编服务和灵活用工等。服务行业涉及全国各领域，其中包括社交电商，旅游酒店，互联网（教育），新零售，金融和国家单位等。位来小猎以“把求职者的未来当做自己的未来”为核心价值，希望通过我们专业的服务和不懈的努力，帮助求职者找到更合适、更有发展前景的工作，破冰职场迷茫，为未来指引方向。一直以来，位来小猎秉承以专业诚信为核心，在专注人力资源服务的同时，为众多求职者解决就业问题，优质、用心的服务赢得了众多用户的好评与信赖。除此之外，公司还建立了完善的服务体系，为求职者在工作中遇到的所有问题和困难提供指导帮助。我们相信，通过我们的不断努力和追求，一定能够创造我们和求职者更好的未来！', 'https://www.zhaopin.com/jobdetail/CCL1320375780J40764934607.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4433, '运营助理/专员', '乐山万达广场商业管理有限公司', '2025-07-27 01:07:57', '2000-3000元', '乐山-市中区', '物业管理', '100-299人', NULL, 'CC264339130J40808444803', '职位描述： <br>', '大连万达集团创立于1988年，已形成商业地产、高级酒店、旅游投资、文化产业、连锁百货五大支柱产业，企业资产达到2500亿元，年销售额1400亿元，年纳税200亿元。万达集团在全国已开业60个万达广场、35家五星级酒店、100家院线共866块电影银幕、52家连锁百货店、58家量贩KTV。万达商业管理有限公司系大连万达集团股份有限公司的核心子公司之一，是中国最大的全国性连锁商业经营管理企业，其经营管理范围覆盖全国所有的万达广场，创造了连续多年租金收缴率超过99%的世界行业纪录。万达商业管理有限公司拥有丰富的商业资源，强大的运营管理能力，确保万达广场无论建在城市中心还是新发展区域，都能开一个火一个，成为万达商业地产的核心竞争优势。乐山万达广场是乐山市2014年度重点招商引资项目，总占地面积约266亩，总建筑面积约78.94万平方米。项目经营业态包括：整个项目由步行街、SOHO、花样洋房、购物中心、城市广场等组合业态构成，是集购物、文化、娱乐、休闲、商务、居住等多功能于一体的、功能配套最新最齐全的城市综合体，打造一站式消费、体验式消费、全龄层消费的主流商业平台。', 'https://www.zhaopin.com/jobdetail/CC264339130J40808444803.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4434, '培训师', '浙江交通技师学院', '7月29日', '5000-8000元', '金华-金东区', '学校/学历教育', '10000人以上', '未融资', 'CC214584210J40473441608', '专业为设计学，电影学、数字媒体技术、数字媒体艺术、视觉传达、动画等相关专业', '浙江交通技师学院（ZheJiang Traffic Technician College）位于浙江省金华市，隶属于浙江省交通运输厅，是一所以培养技师、高级工等高技能人才为主的全日制技师学院，是全国交通职业教育示范院校、国家级重点技工学校、国家中等职业教育改革发展示范学校、国家级高技能人才培训基地、浙江省高技能人才公共实训基地、浙江省中职名校建设单位。学院占地631亩，建筑面积15.1万平方米，总资产5.58亿元，现有在职教职工448人，全日制在校学生8000余人，拥有中央财政支持职业教育实训基地1个、省级高技能人才培（实）训基地3个、省级开放实训中心1个，各类实验实训室100余个，开设有交通、机电、经贸3大类21个专业。学院创建于1974年，校名为浙江汽车驾驶技工学校金华分校。2004年7月，经省编委办批复同意，正式更名为浙江交通技师学院。 1974年8月，学校初建，校名为浙江汽车驾驶技工学校金华分校。 1987年8月，省汽车运输管理体制实行重大改革，根据省人民政府浙政发[1987]75号文规定，我校划归省交通厅直接管理。 1988年2月，更名为浙江金华汽车技工学校。 1989年5月，更名为浙江汽车技工学校。 1994年，我校获评为省交通系统文明学校、全国交通系统规范化技工学校和浙江省重点技工学校。 1997年评为国家级重点技工学校。 1999年2月，经国家劳动和社会保障部批准改建为浙江交通高级技工学校。 2003年6月，经省劳动保障厅、省计划发展委员会批准，在浙江交通高级技工学校基础上组建浙江交通技师学院。 2004年7月，经省编委办批复同意，正式更名为浙江交通技师学院。建设成果历年来学院教师参与厅局级以上科技项目（课题）77项，参加编审的教材出版141种。科研平台拥有中央财政支持职业教育实训基地1个、省级高技能人才培（实）训基地3个、省级开放实训中心1个，各类实验实训室100余个，实验实训仪器设备总值8440余万元；拥有省级技能大师工作室1个、市级职教名师工作室4个，其中程晟技能大师工作室被浙江省人社厅列入首批省级技能大师工作室，并被评为“省级优秀大师工作室”。师资力量浙江交通技师学院现有教职工448人。其中教师328人。正高级职称3人，副高级职称92人，“双师型”教师262人。享受国务院政府特殊津贴1人，全国交通中等职业教育专业带头人2人，全国交通技术能手9人，浙江省技术能手8人，浙江省十佳能工巧匠1人，浙江省百行百星1人，浙江省交通系统“283”拔尖人才1人，交通运输职业教育教学名师1人，浙江省技工院校省级专业（学科）带头人（第二批）4人，浙江省技工院校教研之星4人，金华市职业教育名师4人。', 'https://www.zhaopin.com/jobdetail/CC214584210J40473441608.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4435, '售后客服', '河北汉马腾胜文化传媒有限公司', '5月2日', '3000-5000元', '石家庄-桥西区', '电子商务', '500-999人', NULL, 'CCL1337320910J40764439308', '岗位职责:<br>1.高效处理电商平台内的订单售后问题；<br>2.积极配合团队，及时处理退款事宜；<br>任职要求：<br>1.具备良好的沟通能力和问题解决能力；<br>2.具备良好的服务意识，能够处理客户的投诉和建议。', '1.我们公司是本地最大的直播带货公司，有80多个直播间，200多个在播账号，发展稳定。 2.品类包含家纺，睡衣，女装，内衣，服装配件，家居百货，丝巾，床品，户外服装，女鞋等等，有自己的仓库，发展稳定，前景广阔，而且工作氛围好，薪资待遇高，工作地在市中心 3.想挣钱的，想发展稳定的，想学习经验的欢迎加入', 'https://www.zhaopin.com/jobdetail/CCL1337320910J40764439308.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4436, '网络客服', '北京益信保信息咨询服务有限公司', '7月20日', '7000-14000元', '北京-朝阳区', '咨询服务', '100-299人', 'A轮', 'CCL1491578920J40767667210', '接听客服 长白班、可接受小白，小白优先！<br>工作内容：系统热线/在线形式 了解客户情况，审核是否符合要求，对于客户进行咨询解答。 薪资待遇： <br>1.底薪6500+奖金 基本薪资8000-12000； <br>2.节假日礼品； <br>3.有宿舍； <br>4.定期涨薪以及各种带薪假期； <br>入职要求： <br>工作认真，热爱学习，男女不限，室内上班不用外出，工资给力超级简单； <br>不用担心不会做，入职后有人带，分分钟上手.', '我们服务客户，帮助客户从包括银行等持牌金融机构在内的机构合规获得贷款，改善自身的流动性，优化杠杆经营环境，为客户的发展助力。我们关注自身业务的风险，团队的效率、产出以及福利的实施，实现公司整体性的长远发展。', 'https://www.zhaopin.com/jobdetail/CCL1491578920J40767667210.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4437, '质量管理/测试', '豪迈集团股份有限公司', '4月8日', '8000-15000元', '潍坊-高密市', '电气机械/电力设备,通用设备制造,专用设备制造', '10000人以上', '已上市', 'CC546568620J40794697208', '岗位职责:', '◇企业简介豪迈，始创于1995年，位于山东省高密市，历经20余年的发展，现拥有1家上市公司、8家海外生产型公司、11家专精特新企业。目前是世界上最大的轮胎模具制造商、世界上有影响力的高档机械零部件制造商，连续4次登上美国福布斯《中国潜力企业榜》，2014年在福布斯“中国上市潜力企业100强”中排名第40位。集团行业涉及机械、油气、海工、能源、地产、金融、教育等领域，与多家世界500强企业展开深度合作。◇岗位对口、技术先进、发展空间广阔提供专业对口技术岗位，掌握世界领先的模具、零部件、油气装备等研发技术；集团快速发展，提供技术、管理、商务多通道晋升。◇福利待遇年终奖金、五险一金、交通补贴、用餐补贴、工龄补助、免费体检、带薪年假、节日礼品等。◇配套完善的住房设施提供高标准单身公寓（热水器、空调、独立卫生间等）、独立产权的商品房、经济适用房。◇独特的教育配套设施公司附近配套建设省级示范标准的豪迈幼儿园、小学、中学，为员工子女提供12年的优质教育。', 'https://www.zhaopin.com/jobdetail/CC546568620J40794697208.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4438, '储备经理人', '江苏远望仪器集团有限公司', '2月26日', '4000-8000元', '泰州-姜堰区', '仪器仪表制造', '100-299人', NULL, 'CC276639410J40677959415', '1、大专及以上，机电一体化、电气工程及其自动化等相关专业的应往届毕业生；<br>2、20-35岁，男女不限；<br>3、工作积极，主动学习，能服从安排。', '江苏远望集团由江苏远望仪器有限公司（总部）、江苏远望仪器工程有限公司、江苏远望仪器科技有限公司和泰州市姜堰区远望船舶设备有限公司组成。公司总部位于中国历史文化名镇-溱潼镇，毗邻于国家5A级风景区-溱湖湿地公园，公司交通方便，环境优美。公司总资产1.5亿元，固定资产5000多万元，占地面积80000平方米，建筑面积50000多平方米，是集科研、生产、工程、贸易为一体的江苏省高新技术企业。公司拥有先进的科研、生产、检测设备和完善的管理体系，专业生产船用压力、温度、液位、流量等测量控制仪器仪表、舱柜监测报警、液位遥测、阀门遥控装置、机舱监测、船舶电站等成套测控设备。创建了省船舶自动化测控工程技术研究中心，与江苏科技大学和江苏大学联合建立了企业研究生工作站。公司研制的多项船舶测控设备，其技术水平可与国外同类产品相媲美。公司坚持以人为本的管理理念，为员工提供各种锻炼和培训学习的机会，让员工在工作中不断成长、提高，成就员工追求理想。时值公司飞速发展，对人才的渴求不断提高，为实现公司的长远战略目标，今面向社会诚邀有识之士加入我们的团队，与我们共抓机遇，在成长中分享成功，在成功中分享快乐，共铸辉煌明天！', 'https://www.zhaopin.com/jobdetail/CC276639410J40677959415.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4439, '内容审核', '位来小猎(宁波)信息技术有限公司', '7月21日', '4000-6000元', '邯郸-丛台区', '计算机软件,专业技术服务', '100-299人', 'A轮', 'CCL1320375780J40739431507', '【工作内容】主要负责平台用户上传的视频图片文章，审核是否合规合法，是否涉及政治敏感信息，违规进行删除。<br>【福利待遇】五险，优秀员工奖<br>【晋升机制】初级审核专员—中级审核专员—高级审核专员—小组长—大组长，也可晋升质检岗，或者培训师<br>【工作环境】办公环境优美，独立工位，茶花间等，园区环境干净好<br>【岗位要求】大专及以上，不需要经验，入职有带薪培训<br>【工作时间】 8小时合理化工作制度，月休6天<br>【工作地点】地理位置优越，交通便捷<br>职位福利：绩效奖金、五险、年轻化团队、团队气氛活泼、员工食堂、多次晋升机会、优秀员工奖金', '位来小猎成立于2018年1月，2019年6月完成A轮融资；聚焦行业精华，利用后发优势，在1年以内成为行业黑马公司。核心团队成员均有十年以上的人力资源经验，具备丰富的人力资源专业知识和项目实践，服务众多500强企业和知名互联网公司。位来小猎掌握专业领域核心资源，团队迅速扩张，以北京为中心，在全国建立了10家分公司及办事处，业务覆盖全国。现有300+名员工，派遣、外包员工10000+名；服务客户包括国家体育总局，百度，网易，物美多点，美团，字节跳动，喜马拉雅，作业帮，得物，VIPKID，瓜子，京东，拼多多，喜茶，中国人保等。位来小猎以互联网为载体，依托于位来小猎平台、微信公众号、入职有赏微信小程序上活跃的海量求职者资源，核心业务包括人才外包、专业招聘、业务外包、转编服务和灵活用工等。服务行业涉及全国各领域，其中包括社交电商，旅游酒店，互联网（教育），新零售，金融和国家单位等。位来小猎以“把求职者的未来当做自己的未来”为核心价值，希望通过我们专业的服务和不懈的努力，帮助求职者找到更合适、更有发展前景的工作，破冰职场迷茫，为未来指引方向。一直以来，位来小猎秉承以专业诚信为核心，在专注人力资源服务的同时，为众多求职者解决就业问题，优质、用心的服务赢得了众多用户的好评与信赖。除此之外，公司还建立了完善的服务体系，为求职者在工作中遇到的所有问题和困难提供指导帮助。我们相信，通过我们的不断努力和追求，一定能够创造我们和求职者更好的未来！', 'https://www.zhaopin.com/jobdetail/CCL1320375780J40739431507.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4440, '网络销售', '石家庄天德圣门诊部有限公司长安中医门诊部', '7月18日', '7000-9000元', '石家庄-长安区', '卫生服务', '20-99人', NULL, 'CC874038160J40647765206', '岗位职责:  1.通过网络平台抖音、快手、小红书等宣传、引流、推广医院  <br>2.负责网络内容的截流与优化  <br>3.监控并分析推广效果，调整策略  <br>4. 通过各大社交app平台进行引流推广  <br>  <br>  <br>  <br>', NULL, 'https://www.zhaopin.com/jobdetail/CC874038160J40647765206.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4441, '质检员', '蓝月亮', '11月21日', '4000-7000元', '重庆-巴南区', '快速消费品,快速消费品', '10000人以上', '已上市', 'CC000558690J40510121314', '工作内容：<br>1、落实首检、巡检、末检相关工作，并做好记录；<br>2、对过程异常参数纠正，对异常品处理与追踪；<br>3、监督储运或物流落实在库物料、产品质量管理工作；<br>4、负责生产环境的监督、控制，确保生产环境符合要求；<br>5、检测设备状态的保持与维护；<br>6、负责成品的退货及返工品的质量判定工作；<br>7、协助生产过程质量改善、验证及结果确认；<br>8、定期数据整理分析，反馈。<br>任职资格：<br>1、本科学历，可接受应届毕业生，食品、化学机械类专业等相关专业；<br>2、原则性强、执行力好，具备敏锐观察力，能及时发现异常的质量问题；<br>3、具备良好的团队合作精神；<br>4、能适应加班倒班（两个班次：8:30-20:30,20:30-8:30）。<br>薪资待遇：<br>1、员工宿舍（3人间），免费班车<br>2、员工食堂<br>3、综合薪资4-7K', '蓝月亮品牌诞生于1992年，是以消费者为核心、以创新为驱动力的家庭清洁解决方案提供商，旗下拥有衣物清洁护理、个人清洁护理和家居清洁护理三大系列共108个品种的产品。根据中国商业联合会、中华全国商业信息中心统计数据,蓝月亮洗衣液连续15年(2009-2023)、洗手液连续12年(2012-2023)荣列同类产品市场综合占有率第一;根据Chnbrand发布的中国品牌力指数品牌排名和分析报告,蓝月亮洗衣液、洗手液品牌力指数连续14年(2011-2024)第一。2008年，蓝月亮率先向全国推广洗衣液，打破十几亿中国人的洗衣习惯，开创中国洗衣“液”时代。2015年，蓝月亮突破技术难关，推出国内首款采用泵头计量式包装「浓缩+」洗衣液机洗至尊，再一次掀起中国洗涤市场变革，推动行业浓缩升级。2018年，“至尊”洗衣液丰富了国内衣物洗涤剂高端市场，引领行业进入生物科技洗衣液时代。2019年起，蓝月亮创新推出天露餐具果蔬洁净精华、油污克星泡沫型、卫诺除霉去渍剂、净享氨基酸洗手露、泡沫抑菌洗手液、浓缩柔顺剂等多款新品，帮助消费者更加轻松地解决家居清洁难题，实现洁净无忧。32年行业深耕，蓝月亮秉承着“一心一意做洗涤”的宗旨，以优质产品为根本、以科技创新为驱动力，走出了一条中国品牌独有的发展壮大路径。', 'https://www.zhaopin.com/jobdetail/CC000558690J40510121314.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4442, '销售工程师', '杭州海康威视数字技术股份有限公司', '2025-07-27 01:57:28', '1.5-2.5万', '徐汇区-None', '人工智能,工业自动化,人工智能,物联网', '10000人以上', '已上市', 'CC120975580J40472834415', '职位描述：<br>1、海康威视产品的市场开拓及销售，参与制定市场策略，为客户制定切实可行的营销方案；；<br>2、负责与客户，合作伙伴及甲方客户建立长期而稳定的合作关系；<br>3、负责客户的定期拜访、沟通，进行客户关系的维护和进一步开发，了解竞争对手的销售策略及价格体系等市场信息。<br> <br>任职资格：<br>1、本科及以上学历,计算机、通信、电子等相关专业优先；<br>2、3年以上行业或相近行业销售工作经验，对市场营销工作有一定的理解；<br>3、良好的沟通能力，客户导向能力强；<br>4、正直诚信，具有高度的工作热情和良好的团队合作意识；', '【公司介绍】海康威视成立于2001年，是一家专注技术创新的科技公司，致力于将物联感知、人工智能、大数据技术服务于千行百业，引领智能物联新未来：以全面的感知技术，帮助人、物更好地链接，构筑智能世界的基础；以丰富的智能产品，洞察和满足多样化需求，让智能触手可及；以创新的智能物联应用，建设便捷、高效、安心的智能世界，助力人人享有美好未来。【公司实力】全球业务覆盖150+国家/地区，11大全球研发中心，7大全球制造基地；58000+全球员工，其中研发人员和技术服务人员超27951人，研发投入占全年营业收入11.80%，绝对数额占据业内前茅（2022年年报）；视频感知—国家新一代人工智能开放创新平台（中华人民共和国科学技术部颁布）；连续6年蝉联“全球安防50强”第1位（a&s《安全自动化》）；连续6年蝉联“中国最佳雇主”全国30强（智联招聘）。【薪酬福利】基础福利：五险一金、补充商业保险、年度健康体检；假期福利：带薪年假、全薪病假、婚假、产育假、母婴照顾假、育儿假等；多重补贴：餐饮补贴、交通补贴、通讯补贴、团队建设津贴；乐活配置：免息住房借款、特色员工餐厅、免费停车场、免费健身房、理疗室、定期义诊等园区服务等（园区服务部分区域可享，详请咨询当地HR）；人才激励：年终奖、核心员工跟投创新业务计划股权激励、金砖奖；*公司为常驻海内外的员工，提供健全的物质和人身保障、人性化的探亲福利。', 'https://www.zhaopin.com/jobdetail/CC120975580J40472834415.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4443, '储备经理人', '太原任我行科技有限公司', '4月26日', '5000-8000元', '太原-小店区', '新零售', '20-99人', '未融资', 'CCL1231902420J40569700914', '岗位职责:<br>1、储备干部是我们集团内部中高层储备对象，二十年来集团高层都是从内部轮岗晋升。对于新进员工前期需要到各个部门轮岗学习通过轮岗来提高未来管理员的综合管理能力。<br>职位要求:<br>1、18-30岁，身体健康，男女不限，<br>2、喜欢和人打交道，能与顾客建立良好的人际沟通、团队协作能力。<br>3、不安于现状，有谋求长远发展的相法<br>4、具有良好的学习态度与工作态度，自律能力强，<br>5、有过销售经验者、退伍军人表现优秀者可者虑安排公司管理岗位。<br>6、对应届毕业实习生可从优先录用。我们提供老员工带，公司提供的带薪培训。<br>薪资恃遇:<br>1、底薪5000<br>2、每年2次从上免费旅游<br>3、公司提供免费住宿<br>职位晋升渠道:<br>实习生--部门主管--部门高管--副经理--经理<br>我们完善的培训机制，一经录用，本公司将提供产品知识、业务、外务、人事管理、办公管理等系统在职培训，欢迎社会各界精英即刻加入我们，我们寻找的是合作伙伴，工作氛围轻松愉悦，每周末都有团队经费，团队一起聚餐玩乐，我们的宗旨:工作要尽力，玩儿也要玩儿的尽兴!我们是一家人，是创业伙伴，没有勾心斗角，一起变得更好!', '本公司集研发，生产，市场推广为一体的高新技术企业其经营范围涉及到家用，商业，工业等领域，满足市场智能健康生活用品消费需求。企业拥有顶尖的研发团队和雄厚的技术力量，主要包括绿色环保器材、健身按摩器材小家电及人工智能，移动支付方面三大版块科技产品。集团自成立以来，不断谋求新的发展思路，专注全国各地市场开拓。目前，总部已在重庆，长沙，贵阳，昆明，成都，西安，柳州，乌鲁木齐等大中城市设立60多家分公司，和全国多家品牌企业及商超达成合作战略联盟，产品已成功进驻国美电器，苏宁电器，红星美凯龙，天猫商城，京东商城，苏宁易购等全国一线商超和网络渠道。我们是一家创业型的集团公司，集团注重人才的培养，在总部成立有为分公司培养和选拔人才的商学院，集团有公平、公正、公开的晋升原则；每年对优秀员工提供一/二次国内、国外旅游及西式化培训的机会。', 'https://www.zhaopin.com/jobdetail/CCL1231902420J40569700914.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4444, '销售助理', '湖南湘楚情食品有限责任公司', '7月16日', '5000-8000元', '长沙-雨花区', '农副产品加工制造,快速消费品', '20-99人', '未融资', 'CC391541220J40078821005', '岗位职责<br>1、接待公司来访客户，介绍相关业务内容；<br>2、负责记录客户的相关意向，维护良好的客户关系，定期回访客户，协调客户咨询和争议，做好与客户的后期服务和再次开发；<br>3、协调与其他部门的合作；<br>4、完成上级领导交办的其他工作。<br>任职资格<br>1、本科以上学历，市场营销、电子商务或相关专业优先考虑。<br>2、具备较强的工作责任心，具有出色的语言表达能力与沟通协调能力；<br>3、具备较强的工作积极性和主动服务的意识；<br>4、具备独立处理复杂问题和危急事件的能力；<br>5、有团队协作精神，善于挑战；<br>6、熟练使用各类办公软件；<br>7、能接受出差。<br>职位福利：五险、节日福利、工龄工资、交通补助、绩效奖金  <br>', '湖南湘楚情食品有限公司成立于2006年，注册资金3000万元，生产基地位于湖南长沙浏阳经开区，占地23亩，总建筑面积15000平方米，投资约8000万元，是一家集生产、研发、销售为一体的农业产业化综合型企业。经过12年积累沉淀，公司打造的“地道湘”已成为湘菜配料产业的知名品牌，被认定为“湖南省著名商标”，深受消费者喜爱。2012年，公司被长沙市人民政府认定为“长沙市农业产业化龙头企业”。公司专注于湘菜复合调味料赛道，精耕餐饮及加工业渠道。已通过“ISO9001质量管理体系”和“ISO22000食品安全管理体系”认证。公司始终将产品质量与安全放在首位，建立了一套严格的质量管理与检测体系。公司坚持创新精神，建立专业研发团队，不断升级产品品质，开发新产品作为企业发展的动力。未来，湘楚情将坚持责任、创新、信任、共赢的核心价值观，以“让美味更简单，让生活更时尚”为使命，在发展的道路上奋力前行，努力实现“做一流产品，创一流品牌”的梦想。', 'https://www.zhaopin.com/jobdetail/CC391541220J40078821005.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4445, '储备干部', '博宇金属股份有限公司', '1月16日', '5000-8000元', '沈阳-铁西区', '贸易/进出口,零售/批发', '300-499人', '未融资', 'CC215259524J90250882000', '岗位职责：<br>满足老客户采购需求维护为主，新客户开发。（客户资源及商业信息已整合好，无需自主盲目查找建立销售渠道。团队绩效，减少个人压力）。<br>任职资格：<br>本科（含）以上学历。优秀者学历可以适当放宽。 <br>薪资福利： <br>薪资：无责任底薪（4500至5000）+月提成+年终提成（上年度该岗位年薪7.6至30万）<br>注：国内硕士或者双一流、985、211院校应往届毕业生，额外享有学历补贴1000元/月。<br>福利：五险、单双休、带薪培训、免费住宿、每年两次探亲假及补助、每年一次旅游。 <br>补助：交通、电话、生日、节假日、高温、团建、书籍。 <br>其他：党、工、青相关福利补助，社会评比等。1、分配城市：天津、唐山、济南、青岛、淄博、郑州、太原、西安、武汉、长沙、上海、无锡、南京、宁波、温州、台州、永康、广汉、佛山。  <br>  <br>总部地址：沈阳市铁西区北一西路24号', '始创于1994年，是我国最大的有色金属、钢铁炉料全国性连锁销售集团。现以沈阳为总部，天津、唐山、济南、青岛、淄博、郑州、广汉、太原、西安、武汉、长沙、上海、无锡、南京、宁波、福州、温州、台州、永康、佛山等建立销售部。主营产品销售国内各钢厂、机械设备、汽车配件、通用零部件等几十个行业领域，市场规模巨大，且行业整体模式落后。博宇年营业额30亿元,现有员工300余人。资金雄厚，抵御风险能力强，无贷款和外欠。旗下拥有博宇金属股份有限公司（5000万元），辽宁博宇科技股份有限公司（1000万元）等子公司。自有总部园区和仓储物流加工园区及快捷酒店和慧幸福健康产业。集团拥有多项技术专利和近百项软件著作权认定。博宇在产业链专业分工上，紧抓分销节点以便利店形式，直营连锁经营商业模式，通过高效为客户、供应商提供个性精准性价比高商品、服务，挣取集采优惠及厂批零差，地区差，代销、代购服务费用，为供应商质押货物提供流动资金等盈利模式，经过二十几年的迭代已日趋成熟，博宇作为全国第一个获得中国驰名商标生产性服务业企业，2017年集团销售收入三十多亿元，计划明后年开始在全国各地大规模布销售部、仓库，中期尝试在国外布销售部、仓库，从国外直接进口和通过与生产厂带料加工合作获得更有价格竞争优势商品来为大型用户超大需求供货，及为国内外生产资料需求客户、供应商采销、进行招投标提供平台等服务，远期争取成为顶级世界资源赋能公司。企业VR视频https://www.720yuntu.com/tour/ce5944f1d62c209a', 'https://www.zhaopin.com/jobdetail/CC215259524J90250882000.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4446, '电话销售', '中企动力科技集团股份有限公司石家庄分公司', '5月10日', '8000-16000元', '石家庄-新华区', 'IT服务', '100-299人', NULL, 'CC212992410J40454021516', '我司为上市公司中国数码旗下全资子公司，全国85家分公司，总部在北京，石家庄分公司拥有100人的销售运营团队。我们是一支年轻富有激情和梦想的团队，在这里我们一起学习，成长，挣钱，买车，买房，升职加薪 ......<br>薪资结构：无责任底薪（4000-7600，【职级不同底薪不同，有资源能力者可面谈高职级入职，每月均有晋级涨薪机会】） + 高提成 + 五险一金；<br>酱油干：8000元-12000元/月，跟着干15000-20000/月，努力干：2万-3万/月，干卓越了：月均3万以上；<br>企业数字化主营业务：<br>内贸品宣型门户规划；外贸营销型独立站搭建; <br>推广业务（内贸：百度、360、头条搜索推广； 外贸：谷歌、社媒、Yandex）; <br>互联网安全相关认证; <br>企业宣传片/VR场景拍摄等周边；<br>招聘岗位——客户代表 / 电话销售 / 客户经理<br>1、入职后即签订劳动合同，给您职业安全感有力保障；<br>2、完备的社会统筹福利，五险一金<br>3、优秀员工定期进行出国游、国内精品游；<br>4、公司提供双向的职业晋升通道：晋升产品专家（享受每月额外补助）；试用期商务代表→商务代表→高级商务代表→资深商务代表及以上→商务经理→分公司总监（提高管理能力）；<br>5、公司提供完善的行业、专业、销售技能培训和职业发展规划；<br>6、带薪年假、病假、婚假、丧假、产假等国家法定节假日。<br>7、为优秀应届毕业生提供广阔的发展空间。<br>工作模式：<br>通过电话联系客户邀约上门洽谈成交（有师徒/主管领带）<br>岗位要求：<br>1、性别不限，大专以上学历，专业不限，有无销售经验均可（我司有系统化培训）<br>2、积极上进，性格开朗，有自信，勇于挑战自我、激情、勤奋、正直，坚信成功靠自己争取。<br>3、拒绝意志不坚定! 拒绝懒惰！ 拒绝思想消极者！', '中企动力科技集团股份有限公司成立于1999年，是香港联合交易所上市公司中国数码集团旗下的一家大型股份制高新技术企业，营运总部位于北京，是国内发展最早、规模最大、服务网络最广、专业服务人员最多的企业IT应用服务运营商之一，现已在全国设立了60多家直属分支机构，员工总数逾6000人，拥有研发工程师600余人，已经为20余万家企业客户提供了全方位、多层面的IT应用服务和信息化解决方案。根据全球权威机构研究报告显示，中企动力在2004年度中国IT服务外包市场排名第二，与包括IBM、惠普在内的众多国际知名企业比肩，成为进入前五名的唯一本土企业。自成立以来，中企动力始终秉承“以客户为中心”的经营理念，视推动中国企业开展电子商务、实现信息化为己任，深入研究企业客户的实际需要，开创性地建立了最适合中小企业需要的IT应用服务运营模式，运用先进的信息技术搭建起一个适合企业业务和管理需要的应用服务平台，并透过庞大的全国性商务网络，面对面地向企业客户提供全方位、标准化、一站式的IT应用服务和信息化解决方案。其产品包括网络基础系列、数字商务系列、企业通讯系列和网络推广系列等。多年来的执著追求和不懈努力，使中企动力赢得了企业客户的广泛认同和赞誉，曾先后荣获“中国信息产业2005年度诚信企业奖”、“2005年中国IT创新企业奖”、“企业用户最满意的互联网应用服务平台”、“企业用户最满意的互联网应用服务提供商”、“用户最满意的电子商务平台”和“2005年度首选互联网应用服务品牌”等。总经理陈丹女士更是凭借其在中企动力做出的卓越成绩，被评为“2005中国IT十大财经人物”与“2005中国信息产业年度新锐人物”，引得业界瞩目。', 'https://www.zhaopin.com/jobdetail/CC212992410J40454021516.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4447, '资料管理', '河北北上节能科技有限公司', '2025-07-27 02:04:19', '3000-4000元', '唐山-丰润区', '环保,电力/水利/热力/燃气', '20-99人', '未融资', 'CC412208330J40715951016', '岗位内容：<br>1. 负责管理公司相关资料的收集、整理和归档工作；<br>2. 组织协调各部门提交的文档，确保其及时准确；<br>3. 维护公司数据的安全性和完整性；<br>4. 协助领导进行数据分析和汇总，提供决策依据；<br>5. 搭建并维护数据存储系统，包括文档管理系统等；<br>任职要求：<br>1. 本科及以上学历，理工科相关专业优先；<br>2. 具备良好的信息处理能力和沟通协调能力；<br>3. 熟悉Office办公软件及数据库管理系统；<br>4. 英语读写能力良好，能够熟练运用英文技术文档。<br>5. 具备数据分析经验者优先考虑。<br> <br>6.适应驻场<br>', '河北北上节能科技有限公司（北方电磁）是一家集科技研发、生产销售、售后服务为一体的国家高新技术企业，注册资金2000万元，在电采暖领域匠心躬耕20余年，北方地区14省50城的煤改电工程招标中标入围企业。河北北上节能科技有限公司位于河北省唐山市高新区，厂区占地面积26000平米（自有），涵盖5层综合办公楼1栋、2个大型现代化生产车间、超大存贮仓库、国家级超高温实验室、国家级超低温实验室等，专业承接全国各地的煤改电工程任务。公司设有技术研发部、生产部、发展决策部、销售部、办公部、人力资源部、客服部、售后部等多个公司部门，基础团队规模80人以上，含有多位经验资深的热力工程师以及经验丰富的可以上门服务的暖通技工，能够更好更快地为北方地区的居民提供冬季清洁取暖等服务。因创新而生、因技术而立，北方电磁专注科技研发，旗下拥有直热式/蓄热式变频电磁供热机组、蓄热式电暖器、太阳能辅热设备、直热式电暖器、电锅炉等多款电采暖设备，陆续获得了国家CCC认证、质量体系ISO9001认证、等资质荣誉认证，并拥有大量的电磁加热技术证书以及国家技术专利。现如今，河北北上节能科技有限公司已成为了国家电网、中石油、中国移动、新疆高速、中铁集团、边防部队、张家口冬奥会等大型单位的煤改电工程合作伙伴，生产的单机设备功率从5kW到5000kW，可以满足50平米到100万平米以上的冬季取暖需求，深受政府、社会、群众的一致好评。', 'https://www.zhaopin.com/jobdetail/CC412208330J40715951016.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4448, '培训师', '长沙市中远职业中专学校', '1月7日', '5000-8000元', '长沙-浏阳市', '培训/辅导服务,互联网,广播/影视,学术/科研', '100-299人', NULL, 'CC143306980J40218011110', '岗位职责 : 承担中职新能源汽车理论课程教学和实训课程教育教学。<br>任职要求:<br>1、遵纪守法，无违法违纪记录;<br>2、品行端正，具备良好的教师职业道德素养，能关心爱护学生，有大局观念和团队意识，热爱教育事业;<br>3、身体健康，能胜任岗位工作;<br>4、大学本科及以上学历;具有相应教师资格证、普通话等级证书、计算机等级考试合格证书等。有高级技工、技师、高级技师证书者优先聘用。有管理工作经验及研究生学历者优先聘用。<br>条件优秀者可约谈薪资待遇，成为本专业学科带头负责人。亦招聘兼职老师，待遇优厚，欢迎联系<br>职位福利：五险、节日福利，学生提供免费就餐及住宿', '长沙市中远职业学校是经长沙市教育局批准，湖南省教育厅备案，市属直管的一所全日制中等职业职院校，在校学生3000多人，连续三年被长沙市教育局评为招生就业工作先进单位。学校根据《国家中长期教育改革和发展规划纲要2010-2020年》文件，全力培养既有扎实的理论基础又有较高专业水平的复合型人才。', 'https://www.zhaopin.com/jobdetail/CC143306980J40218011110.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4449, '内容审核', '万宝盛华企业管理咨询(上海)有限公司大连分公司', '6月28日', '8000-13000元', '深圳-龙岗区', '互联网,人力资源服务', '1000-9999人', '已上市', 'CC880319660J40858390615', '岗位职责：', '万宝盛华成立于1948年，公司年度总收益超过220亿美元，为雇主提供涵盖整个雇佣生命周期和商业周期的一系列服务，包括人才推荐服务、临时和合同派遣服务、员工测评和筛选、培训服务、转职推荐服务、外包和咨询服务等。万宝盛华集团——全球开创性的人力资源解决方案的领导者——于1994年首次将业务拓展至中国大陆，提供全方位的人力资源服务。', 'https://www.zhaopin.com/jobdetail/CC880319660J40858390615.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4450, '知识产权/专利代理', '深圳众鼎专利商标代理事务所(普通合伙)', '7月9日', '5000-10000元', '郑州-中原区', '咨询服务,企业服务', '100-299人', '未融资', 'CC490803430J40644352003', '岗位责任：<br>1、专利申请文件撰写和审核<br>2、审查意见答复<br>3、与发明人沟通技术内容<br>4、专利检索与专利分析<br>5、处理专利复审、无效<br>6、协助各部门处理相关案件<br>7、协助专利管理中心及流程部完成案件状态表<br>8、完成部门领导布置的其他任务<br>任职要求：<br>1、硕士以上学历，机械及相关理工科专业；<br>2、可独立进行专利申请相关的实务工作，有撰写经验者优先；<br>3、英语四级以上，具备良好的科技英语应用能力，专利撰写能力；<br>4、热爱专利撰写文书事业，勤奋敬业，善于沟通，有团队合作精神。公司福利：<br>  <br>1）弹性工作时间：8:30-9:00上班、17:30-18:00下班，7.5小时/天，5天制，双休；<br>  <br>2）5-15天带薪年休假；<br>  <br>3）五险一金购买；<br>  <br>4）提供新员工入职培训及行业、相关专业知识培训；<br>  <br>5）享受国家法定节假日。传统节日发放礼品等；<br>  <br>6）接收人事档案。可申请住房补贴1.5至3万。<br>  <br>7）深圳高层次人才认定办理、技术资格评审办理、挂代理人证。<br>', '深圳众鼎专利商标代理事务所由前比亚迪知识产权创始人黄章辉先生创办，是国内综合实力领先的综合性知识产权服务机构，众鼎是经国家知识产权局、国家工商行政管理总局指定和认可的专业从事国内和涉外知识产权代理业务的法律服务机构，同时也是中华全国专利代理人协会的会员单位。众鼎业务范围涵盖国内专利代理、涉外专利代理、国内商标注册、涉外商标注册、法律诉讼、海关备案、双软认证、高新技术企业认定、知识产权贯标、专利预警分析、知识产权运营、知识产权战略设计等。众鼎立足于深圳，布局全国发展战略，始终致力于为客户提供个性化和本土化的服务。先后在北京、广州、东莞等地设立分所，并在深圳地区拥有独立服务机构。众鼎具有良好的信誉和国际水准的服务，拥有一批经验丰富、素质高、敬业精神良好的知识产权顾问、专利代理人、商标代理人和律师，目前员工近80人，专业人才具有丰富的从业经验，专利领域涉及机械、电子、计算机、软件、生物、医药、化工等，团队规模及人才素质行业领先。目前众鼎已与国内外上千家优秀客户建立了稳定的合作关系，与百余个国家（地区）的专业知识产权服务机构有着频繁的业务往来，建立了全球性的知识产权服务网络。客户群体包括腾讯、比亚迪、大亚湾核电、广汽、优必选、平安集团等。', 'https://www.zhaopin.com/jobdetail/CC490803430J40644352003.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4451, '社区运营', '中国平安', '7月26日', '面议', '佛山-三水区', '保险,保险', '10000人以上', '已上市', 'CC000204810J40800079712', '工作职责：<br>1)根据公司客户划分，需完成负责区域内客户售后服务响应、服务活动完成；<br>2)负责区域内客户建联，通过企业微信等做好客户日常经营；如热点话题、健康养生、生活小细节等，提升客户活跃度；<br>3)依托公司内外部资源，打造个人IP“做客户保险小帮手、生活小助手”，进行产品销售； <br>4)客户原保单的续收提醒，具备基础的保险专业知识；<br>5)通过系统的培训学习，不断提升自身服务水平及综合解决各类产品营销的能力；<br>任职资格：<br>学历：大专及以上学历<br>1)具有2年及以上金融行业面销、电销、网销等从业经验；<br>2)综合素质优秀的其他行业2年以上销售工作经验的从业人员；<br>3)乐于助人，服务意识强，不抗拒销售；<br>4)善于沟通协作，执行力强，性格热情开朗，且具有较强的学习能力；<br>5）8Q测试中AQ/EQ/AAQ综合得分≥6.5分、 LQ≥7分，分数不达标，不予录用；<br>职位优势：<br>1)优质客户资源提供，解决了销售的核心痛点，做好客户服务<br>2)工作以面访服务、客户经营为基础进行产品营销；<br>福利待遇：<br>1)基础收入构成包含职级津贴、行为津贴及新人津贴，以上收入关联日常行为、客户服务指标、续收指标达成，及基础销售考核要求；<br>2)销售收入根据实际业绩达成情况进行计算；<br>3)综合福利保障（公司缴纳）；<br>4)节假日福利（视具体情况而定）；<br>', '中国平安致力于成为国际领先的科技型个人金融生活服务集团。2019年，中国平安深入推进\\\\\"金融+科技\\\\\"、\\\\\"金融+生态\\\\\"战略转型，持续提升数据化经营能力，整体业绩及核心金融业务持续稳健增长，科技赋能成效显著，生态赋能效果初显，综合金融用户数、客户数、客均合同、客均利润均有明显增长。公司实现营业收入同比增长19.7%至11,688.67亿元。截至2019年底，公司个人客户数首次突破两亿，互联网用户量达5.16亿，全年新增客户数3,657万，其中40.7%来自集团五大生态圈的互联网用户。中国平安始终践行\\\\\"金融为实体经济服务\\\\\"的精神，坚持把实体经济服务作为出发点和落脚点，通过旗下的保险、银行、信托、金融科技等业务，把逾4万亿金融资源配置到经济社会发展的重点领域和薄弱环节，包括通过保险保障、提供贷款、债权股权计划、普惠金融等多种方式，全面助力实体经济发展。凭借全球领先的创新科技，中国平安将科技深度运用于金融主业中，助力降本增效、风险管控，打造优质产品和极致服务体验，提升客户口碑。与此同时，平安将领先科技广泛应用在金融、医疗及智慧城市等领域，全面支撑\\\\\"金融服务、医疗健康、汽车服务、房产服务、智慧城市\\\\\"五大生态圈建设。在企业社会责任方面，平安深化可持续发展理念，MSCI ESG评级连续两次调高至A级，打造AI-ESG平台赋能责任投资，截至2019年12月末，公司责任投资规模达9,544.49亿元，可持续保险金额达121.21万亿元，绿色信贷年度授信总额590.56亿元。同时，平安积极响应国家脱贫攻坚战的号召，推进\\\\\"三村扶贫工程\\\\\"项目，累计提供专项扶贫资金249.05亿元。面对新冠肺炎疫情，平安第一时间推出保险保障、医疗支持、对外捐赠等多重支持举措，提供的物资及现金捐赠总额超1.75亿元。2020年，中国平安品牌价值持续提升，名列美国《财富》“世界500强企业”第21位，居全球金融企业第2位，《福布斯》全球上市公司2000强第7位，BrandZ™全球品牌价值100强第38位，蝉联全球保险品牌第1位。', 'https://www.zhaopin.com/jobdetail/CC000204810J40800079712.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4452, '储备干部', '河南中恩企业管理咨询有限公司', '7月8日', '7000-12000元', '郑州-金水区', '培训/辅导服务', '300-499人', NULL, 'CC393813030J40754387305', '1.电话、微信拜访高端企业家客户；<br>2.集团公司发展25家公司、储备经理管理层；<br>3.公司商学院培训赋能、一对一培训；<br>4.准备晋升至管理职位优秀人才<br>优秀候选人请联系我。', '中恩教育，立志建设更懂中小民营企业、更实战的自运转商学堂课程模式，为企业提供全方位、全生命周期服务，包含实效管理培训、咨询辅导、年度顾问和学习工具。中恩教育深耕教育行业，一直保持稳健快速的发展，现有南京、郑州两大运营中心，13家直营公司，覆盖8大省份，未来3-5年布局全国，致力于成为全球最值得信赖的教育机构!中恩教育创始人具有15年以上管理经验，导师团队由知名公司创始人、高管和各领域专家组成，研发中心位于上海，已沉淀多项知识产权，坚持让学习更有效的教学理念，截止目前，已有超10万企业家学员走进中恩教育，助力企业打造核心竞争力，帮助企业实现自动运转，拉动企业业绩倍增。中恩教育以其自身实力和卓越表现赢得了客户和业界的一致认可。2018年荣获“中国品牌年度匠心品牌奖”称号、“年度品牌影响力教育集团”称号、“中国管理创新优秀品牌”称号，2019年荣获“年度综合实力教育集团”称号，2021年荣获“年度口碑影响力教育品牌”奖。', 'https://www.zhaopin.com/jobdetail/CC393813030J40754387305.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4453, '游戏运营', '喔租(石家庄)商业管理有限公司', '7月25日', '3000-6000元', '石家庄-新华区', '景区/商业/市场等综合管理', '20-99人', NULL, 'CCL1380753450J40758587801', '运营专员岗位职责：<br>1. 负责内部系统维修工单全流程管理（审批、分类、评估合理性），对接维修商跟进进度并反馈结果。<br>2. 处理线上维修单、保洁单的查收、派单、审核，定期与合作商核对账务，确保数据准确。<br>3. 负责房源家纺类物资采购，保障供应及时适配，录入账单并核对；每月盘点库房家具家电，及时处理问题。<br>4. 服从财务主管安排，执行公司制度，完成其他交办任务。<br>福利待遇：定期团建、生日福利、五险、亲属福利、节日福利等。<br>薪资：转正3k-4k➕绩效工资500，试用期2个月执行2500<br>上班时间：8:30-12:00，13:30-18:00。', NULL, 'https://www.zhaopin.com/jobdetail/CCL1380753450J40758587801.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4454, '质检员', '广东全智人力资源有限公司', '7月22日', '8000-9000元·13薪', '长春-宽城区', '人力资源服务', '1000-9999人', '已上市', 'CCL1325835190J40761203911', '本地新建工厂，本厂直接招聘，应聘当天入职，安排免费吃住上班，直接到厂区面试，全程不花冤枉钱，厂区签合同有保障(不被坑)<br>短期工 长期工 都可以！！！！<br>----------------------------------------------<br>薪资待遇：<br> 小时工：月薪8000-9000多劳多得  正式工：早8晚5，保底工资7000，', '[广东全智]是一家专注于人力资源领域的综合性服务公司。自成立以来，我们始终秉持着“专业、高效、创新、共赢”的核心价值观，为客户提供全方位、一站式的人力资源解决方案。在人才招聘方面，我们拥有庞大的人才数据库和专业的招聘团队，能够精准匹配企业需求，快速为企业输送各类优秀人才。无论是高端管理人才，还是技术骨干，我们都能以专业的眼光和高效的流程为企业选拔最合适的人员。培训与发展也是我们的核心业务之一。我们与众多行业专家和培训机构合作，为企业和个人提供定制化的培训课程，涵盖领导力、专业技能、职业素养等多个领域，助力客户提升自身竞争力。同时，我们还提供人力资源外包、薪酬福利设计、劳动法律咨询等多元化服务。凭借丰富的行业经验和专业知识，我们已经为[X]家企业提供了优质的服务，赢得了客户的广泛信赖和好评。未来，[公司名称]将继续深耕人力资源领域，不断创新服务模式，为客户创造更大的价值。', 'https://www.zhaopin.com/jobdetail/CCL1325835190J40761203911.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4455, '项目招投标', '福建晟捷管理咨询有限公司', '7月7日', '5000-6000元', '福州-闽侯县', '企业服务', '1000-9999人', '不需要融资', 'CCL1305446730J40399702506', NULL, '业务覆盖多个省市，加入我们能给你提供： 1.完善的社会保险2.根据法律规定提供各类法定带薪假期： 3.丰富多彩的员工活动 4.良好的培训及完善的职业生涯规划...作为一个年轻的平台，期待您的加入与之共同成长', 'https://www.zhaopin.com/jobdetail/CCL1305446730J40399702506.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4456, '运营助理/专员', '徽辰智电科技股份有限公司', '5月9日', '3000-5000元', '合肥-肥西县', '电力/水利/热力/燃气,电力/水利/热力/燃气,新能源', '100-299人', '未融资', 'CC875515490J40733333211', '岗位职责：<br>- 协助进行新能源项目的日常运营和维护工作；<br>- 收集和整理运营数据，进行初步分析；<br>- 学习并了解新能源行业相关政策、标准和市场动态；<br>- 完成上级安排的其他相关工作。<br>岗位要求：<br>- 在校大学生，专业不限，新能源、电力等相关专业优先；<br>- 对新能源行业有浓厚兴趣，愿意学习相关知识和技能；<br>- 良好的沟通能力和团队协作精神；<br>- 熟练使用办公软件，具备基础的数据分析能力。', '徽辰智电科技股份公司（以下简称“公司”），成立于2010年5月，注册资金5000万元。历经十载，公司已成为提供一站式电力服务的国家级高新技术企业，其主营业务分为电力咨询设计（E）、电力设备供应（P）、电力工程建设（C）和智能运维管理（O）四类，这四类业务环环相扣，共同组成了公司的EPCO一站式服务体系。专业输变电配套服务商，国家级高新企业、电子与智能化工程专业承包壹级资质、电力承装修叁级、承试叁级资质、电力工程施工总承包叁级资质、消防设施工程专业承包贰级资质、建筑装饰装修专业承包贰级、建筑工程施工总承包叁级、建筑机电安装工程专业承包叁级资质、城市及道路照明工程专业承包叁级资质、环保工程专业承包叁级资质、安全生产许可证资质、施工劳务资质、电梯安装服务。公司集电力设备及系统的研发、生产、销售、检修、施工为一体的综合型企业，注册资本5000万，AAA级信用企业、通过ISO9001、ISO14001、OHSAS18000认证。公司技术实力雄厚，国内率先实现北斗卫星导航通讯系统在电力行业高压输电线路中的应用，该项目成功获得国家创新科技基金奖励，同时在国家电网移动式变电站整站研发及租赁、撬动式电气设备预制舱、高压输电线路“三跨”、线路可视化研究、电网施工安全管控、变电站高压设备及电缆沟消防监测、智能自动灭火、配电房智能自动巡检、轨道交通及管廊综合在线监测系统、10KV高压计量装置的研究、10kV固体绝缘环网柜、35kV户外永磁断路器、10kV断路器一二次融合等领域的科学研究成绩突出。电力相关专业中高级职称25人，各类工程师、技术人员70余人，已经取得各类专利30项，软件著作权18项、省级新产品认证8项、国家创新科技基金奖励项目1项。业务范围覆盖强电、弱电两大板块。强电部分：1000kV以下电网带电状态检测服务；1000kV以下变电站运维及标准化整治服务；35kV以下变电站和线路总包施工及一二次整体检修服务；配电设备（10kV开闭所、柱上智能断路器等）。弱电部分：变电站、配电房、机房等机器人巡检、智能环境辅控解决方案；消防以及机电工程、电子智能化及亮化项目。徽辰智电，服务电力。立足于长期稳健的发展战略，用我们雄厚的技术力量来支持，追求使客户的投资得以最大的收益，通过完善的售前、售中及售后的服务来解除用户的一切后顾之忧，公司将本着“创新发展，完美服务，合作共赢”的宗旨与您共创美好的明天。', 'https://www.zhaopin.com/jobdetail/CC875515490J40733333211.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4457, '统计员', '北京晶澳太阳能光伏科技有限公司', '6月13日', '8000-15000元·13薪', '北京-丰台区', '新能源,电力/水利/热力/燃气', '10000人以上', '未融资', 'CC677096020J40807411408', '一、工作范围 The scope of work<br>负责董事会办公室各类行政文书的起草、管理工作。<br>二、主要工作职责 Major responsibilities<br>1、公司主要领导和重要活动文字材料起草；<br>2、公司对外重要材料起草、审核；<br>3、负责重要会议纪要整理；<br>4、负责部门档案的管理工作。<br>5、协助公司重要活动策划组织；<br>三、要求：<br>1、本科及以上学历，文秘、中文、新闻等相关专业优先；<br>2、有一定的文字功底，具有较强的学习能力和信息收集整理能力；<br>3、具备良好的沟通能力和责任心，具有一定的抗压能力和自我挑战精神；<br>4、具备良好的职业道德和敬业精神、保密意识强；英语可作为工作语言的优先。', '晶澳太阳能是全球领先的高性能光伏产品制造商，其产品应用于住宅、商业和地面光伏电站发电系统。晶澳成立于2005年5月，2007年2月在美国纳斯达克证券交易所挂牌上市。自2010年以来，晶澳一直是全球顶级的光伏电池生产商，并确立了一流光伏组件供应商的地位。晶澳利用已有光伏电池技术的优势，致力于提供卓越的高转换效率、高发电效率和高可靠性的光伏组件，使客户在光伏项目上的效益最大化。晶澳已发展成为覆盖硅片、电池、组件及电站业务的垂直一体化全球光伏领军企业，目前在国内外拥有十一个生产基地，硅片产能达3.0GW、电池产能达6.5GW、组件产能达7.0GW。目前，晶澳累计出货超过23GW。一流的行业经验，不懈的研发创新，专注的客户服务及稳定的财务状况——晶澳太阳能是您最值得信赖的长期合作伙伴。', 'https://www.zhaopin.com/jobdetail/CC677096020J40807411408.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4458, '游戏推广', '菏泽仙女文化传媒有限公司', '7月25日', '5000-10000元', '滁州-南谯区', '文化艺术/娱乐,新媒体', '1000-9999人', '不需要融资', 'CCL1331427280J40795977003', '【工作介绍】<br>指定平台开黑玩游戏，接单完成游戏陪陪/陪练，边玩边赚钱【工作内容】<br>1、有手机耳机即可<br>2、陪付费客户打游戏，聊天，唱歌，按时间或局数收费<br>3、有专门组织培训，带你快速人门，赚钱无忧。<br>4、不要求技术【人员要求】<br>1、18-30岁2、<br>会和平精英/绝地求生/英雄联盟/王者荣耀/云顶之弈、其中任意一款游戏<br>3、工作认真负责，积极主动<br>4、良好的沟通能力，性格开朗，喜欢与人交流<br>5、兼职全职均可，不限制在线时间<br>【薪资结算】<br>奖励机制+下单提成，时间充足者每天收入至少200+', '虎牙旗下千万流水钻石公会虎牙交友前三公会旗下几十个专业运营团队！艺人共计5000+陪练师共计10000+集交友、陪玩、颜值、二次元为一体的顶尖经纪公司行业顶尖运营团队，致力打造最优质的品牌公会。', 'https://www.zhaopin.com/jobdetail/CCL1331427280J40795977003.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4459, '管培生/储备干部', '上海商睿智能科技有限公司', '7月21日', '8000-15000元', '深圳-龙华区', '智能硬件', '20-99人', '天使轮', 'CC829706200J40753063110', '岗位职责：<br>1、负责区域内客户开发，维护和项目操作，完成销售目标；<br>2、挖掘并逐步引导行业需求，在公司的支持下独立制作解决方案，树立行业样本和提升品牌形象；<br>3、参与制定区域内各类型客户（渠道，软件商等）目标制定与业务拓展计划并主导落实；<br>4、做好内部资源和外部需求的协调，确保产品需求内外一致性和交付准确性，供应链交付及时性，满足客户业务需求；<br>岗位要求：<br>1、本科及以上学历应届生，对销售工作具备强烈兴趣，内驱动力强大，具备良好的综合素质和抗压能力；<br>2、有高度客户敏感度，良好的沟通技巧和谈判能力，良好的对内对外协调和沟通能力；<br>3、具有全局观和目标导向，喜欢挑战，学习能力强；<br>4、相关行业：智能软硬件、收银行业、PDA行业销售工作经验者优先；<br>薪酬结构： 底薪+提成奖金<br>晋升通道：销售管理培训生-销售专员-销售经理-销售总监-销售VP', '上海商睿智能科技有限公司成立于2017年底，是一家专注为O2O互联网平台，软件开发商、第三方支付公司、软件代理商以及中小型商户提供专业的具性价比的智能商用硬件及解决方案的创新型科技企业。公司的研发团队成员主要来自高通、华为及展讯，在硬件系统集成上有着较深厚的技术底蕴。商睿团队凭借多年在商用硬件领域的研发经验和市场资源积累，整合上下游供应链，协同互联网平台资源，以智能硬件产品体验,智慧新零售的革新。公司以“做智能商用设备的开拓者”为发展理念，立足智能商用领域技术的投入和创新研究，以技术带动贸易，通过智能商用硬件的迭代与更新，完善便利我们生活圈的同时，与合作伙伴共赢，为新商业文明带来价值。公司有过千万级天使轮投资，目前筹备A轮融资。期待有缘的小伙伴加入，为公司的发展添砖加瓦', 'https://www.zhaopin.com/jobdetail/CC829706200J40753063110.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4460, '律师助理', '北京浩天(郑州)律师事务所', '6月17日', '3000-4000元', '郑州-金水区', '法律服务', '20-99人', NULL, 'CCL1470047270J40692332115', '1、法学类本科及以上学历。211、985重点院校毕业生，具有法院工作经历者优先；<br>2、取得法律职业资格A证，具有扎实的法学理论功底者优先；<br>3、工作态度认真，具有良好的个人品质、团队合作精神；<br>4、熟悉使用各种办公软件，撰写、整理相关文书、证据，进行案卷整理和归档；<br>5、热爱律师行业，具有创新精神，有良好的沟通、执行以及语言表达能力；<br>6、认同浩天（郑州）发展理念，适应律所发展模式； <br>7、薪资面议；<br>8、有篮球运动特长者优先考虑。', '公司是一家北京市律师协会批准设立的全国性律师事务所，目前在郑州设立分所，律师事务所坐落于环境优美的北龙湖，社会福利待遇好，固定工作时间，双休工作制，入职可长期规划职业生涯，工作强度不大，财务专业知识可在平台上尽力施展。', 'https://www.zhaopin.com/jobdetail/CCL1470047270J40692332115.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4461, '网络客服', '深圳乐信软件技术有限公司', '7月24日', '5000-7000元', '北海-海城区', '互联网,互联网', '1000-9999人', '已上市', 'CC542186980J40765903510', '上司公司！！甲方自招！！入职缴纳五险一金，月休8天，新职场筹建，发展空间大，欢迎有客服经验且优秀的人儿来咨询呀~~<br>岗位职责：<br>用户通过分期乐APP联系在线客服，我们接到后根据用户的问题通过打字形式进行相应解答，不涉及任何电话<br>薪资待遇：<br>月休8天排休，无责底薪2700+晚班补贴(晚班补贴50元一个班次、天地班补贴80元一个班次)+绩效(根据服务质量和服务效率决定，多劳多得)<br>第一个月:综合工资5k-6k(有新人保护)<br>第二个月及之后:综合工资6k-9k<br>其他福利：<br>1.五险一金(入职就缴纳，无需转正);<br>2.底薪+津贴+职级工资+晚班补贴，均薪5K-9K，top选手1W+<br>3.带薪年假+生日福利+节假日福利+下午茶+各种奖金，拿到手软<br>4.每月固定10号发薪工作时间<br>早班:9:00-18:00午休1小时，12点或者13点排班休息;<br>晚班:12:00-21:15，晚餐休息1小时15分，16点或者16点<br>45休息;<br>天地班:9:00-21:15,13点-17:15休息。月休8天排班', '乐信（NASDAQ:LX）成立于2013年8月，是中国领先的新消费数字科技服务商。公司以科技创新不断创造新消费方式，打造了以分期消费品牌分期乐、数字化全场景分期消费产品乐花卡、跨生态会员权益聚合平台乐卡、智能化契约式消费产品约惠、先享后付产品买鸭为核心的新消费服务生态，打通线上线下消费场景，帮助亿万用户快乐消费，通过科技助力商家提升经营能力，助力中国新商业文明加快建设，推动中国经济健康蓬勃发展。截至2021年3月，乐信用户数达到1.32亿。乐信还入选“中国服务业企业500强”、“中国互联网百强企业”、“广东民营企业100强”、“深圳创新企业70强”、“南山区纳税百强”等榜单，并成功入选哈佛商学院案例，获得《亚洲银行家》、《快公司FastCompany》等上百家媒体的众多荣誉及人民日报、央视、CNBC、彭博等国内外主流媒体关注。集团官网http://www.lexinfintech.com/', 'https://www.zhaopin.com/jobdetail/CC542186980J40765903510.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4462, '猎头顾问', '安徽新华教育集团', '7月24日', '4000-6000元', '呼和浩特-土默特左旗', '学校/学历教育', '10000人以上', '已上市', 'CC493641730J40673114709', '岗位职责：<br>1.电话信息录入，电话回访邀约上门 <br>2.数据统计分析； <br>3.有K12咨询工作经验优先； <br>4.有销售、课程顾问经验这优先。 <br>任职资格： <br>1、形象好，气质佳，年龄不限； <br>2、大专及以上学历，坐班兼职； <br>3、较强的服务意识，熟练使用电脑办公软件； <br>4、具备良好的协调能力、沟通能力，负有责任心，性格活泼开朗，具有亲和力；', '新华教育集团创立于1988年，是改革开放后最早一批社会力量办学机构，自创办以来，始终遵循党的教育方针，以服务经济发展、满足社会需求为导向，以技能教育为根本，自觉肩负“新华教育、兴教报国”的崇高使命，坚持“办中国最好的职业教育”宏伟目标,秉承“贴近市场、领先行业、服务就业”的办学思路，着力培养应用型技能人才，致力于创造让学生满意和尊重的教育服务。办学32年来，集团采用多品牌、直营连锁的办学模式，开创了独具特色、高质量的职业教育体系，成功打造了新华互联网教育、新东方烹饪教育、万通汽车教育、欧米奇西点西餐教育、华信智原大学生教育、美味学院私人订制教育六大职业教育品牌，形成了覆盖全国的多层次、多专业新华教育办学格局，成为中国职业教育发展模式成功典范。目前，集团在全国29个省份及香港共开办院校175所（其中包含19个私人订制烹饪体验中心），员工1万余人，常年在校生超过13万人，总建筑面积逾187万平方米，累计为社会培养和输送了大批适应经济社会发展的各类实用型、技能型人才。集团先后获得了“品牌中国金谱奖—中国教育行业年度十佳品牌”、“改革开放30年中国民办教育成功典范”、“改革开放30年中国十大品牌教育集团”和“改革开放40年培养人才突出贡献单位”等多项殊荣，是中国著名的职业教育示范基地和规模最大的民办职业教育机构，已成为中国职业教育的标杆！集团于2019年6月12日在香港联交所主板成功上市（股票代码：667.HK），融资净额约为47.69亿港元，成为全球教育界有史以来规模最大的IPO。集团坚持以“团结、务实、开拓、奉献”的企业精神为指导，在激烈的市场竞争中，紧抓发展机遇，连续多年保持良好发展势头。多年来，集团积极参与社会公益事业，通过免费为下岗职工、退伍军人、贫困家庭、国际慈善机构提供培训，为希望工程、光彩事业、灾区重建、贫困学生奖助减免等累计捐款捐物数亿元，在社会品牌知名度和美誉度持续提升，赢得了各级领导和社会各界的高度赞誉。', 'https://www.zhaopin.com/jobdetail/CC493641730J40673114709.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4463, '电话客服', '河南通汇商务信息咨询有限公司', '2025年07月30日', '7000-14000元', '郑州-金水区', '互联网金融/小额贷款', '20-99人', '不需要融资', 'CC542251380J40500056711', '一，工作职责<br>1、通过电话的方式联系逾期的客户，提醒客户处理逾期的账单<br>二，岗位要求<br>1、18-40岁，男女不限，学历不限，有销售、话务员、客服类工作经验者可放宽年龄要求；<br>2、可以接受应届毕业生，是实习生<br>福利待遇：<br>无责4500+绩效+奖金+社保，综合薪资8000以上，<br>月入过万不是梦，领导管理风格人性化，轻松愉快，倡导开心工作，快乐生活', NULL, 'https://www.zhaopin.com/jobdetail/CC542251380J40500056711.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4464, '培训师', '安徽新华教育集团', '6月24日', '4000-8000元', '长春-绿园区', '学校/学历教育', '10000人以上', '已上市', 'CC493641730J40749099609', '主要工作：航空轨道类专业课教师<br>岗位职责：<br>1、担任一线教学工作，主要教授航空、轨道类专业等相关课程；<br>2、熟悉掌握履行岗位职责所需理论知识、技能和方法，具备较好的语言表达能力；<br>3、积极参与教研工作、完成教学任务。<br>任职条件：<br>1、空乘、轨道交通类相关专业，大专及以上专业，有铁路、地铁、空乘类实际工作经验。　　<br>工作时间：单双休。法定节假日<br>福利待遇：<br>1、五险一金、法定假、带薪寒假（近20天）、带薪婚丧假、带薪旅游假、职工宿舍、工作餐等；<br>2、学习培训、节日礼品/礼金（春节、端午节、中秋节、教师节等）、婚丧礼金等；<br>3、年终考核奖、定期健康体检、高温补贴、部门活动、旅游拓展等。', '新华教育集团创立于1988年，是改革开放后最早一批社会力量办学机构，自创办以来，始终遵循党的教育方针，以服务经济发展、满足社会需求为导向，以技能教育为根本，自觉肩负“新华教育、兴教报国”的崇高使命，坚持“办中国最好的职业教育”宏伟目标,秉承“贴近市场、领先行业、服务就业”的办学思路，着力培养应用型技能人才，致力于创造让学生满意和尊重的教育服务。办学32年来，集团采用多品牌、直营连锁的办学模式，开创了独具特色、高质量的职业教育体系，成功打造了新华互联网教育、新东方烹饪教育、万通汽车教育、欧米奇西点西餐教育、华信智原大学生教育、美味学院私人订制教育六大职业教育品牌，形成了覆盖全国的多层次、多专业新华教育办学格局，成为中国职业教育发展模式成功典范。目前，集团在全国29个省份及香港共开办院校175所（其中包含19个私人订制烹饪体验中心），员工1万余人，常年在校生超过13万人，总建筑面积逾187万平方米，累计为社会培养和输送了大批适应经济社会发展的各类实用型、技能型人才。集团先后获得了“品牌中国金谱奖—中国教育行业年度十佳品牌”、“改革开放30年中国民办教育成功典范”、“改革开放30年中国十大品牌教育集团”和“改革开放40年培养人才突出贡献单位”等多项殊荣，是中国著名的职业教育示范基地和规模最大的民办职业教育机构，已成为中国职业教育的标杆！集团于2019年6月12日在香港联交所主板成功上市（股票代码：667.HK），融资净额约为47.69亿港元，成为全球教育界有史以来规模最大的IPO。集团坚持以“团结、务实、开拓、奉献”的企业精神为指导，在激烈的市场竞争中，紧抓发展机遇，连续多年保持良好发展势头。多年来，集团积极参与社会公益事业，通过免费为下岗职工、退伍军人、贫困家庭、国际慈善机构提供培训，为希望工程、光彩事业、灾区重建、贫困学生奖助减免等累计捐款捐物数亿元，在社会品牌知名度和美誉度持续提升，赢得了各级领导和社会各界的高度赞誉。', 'https://www.zhaopin.com/jobdetail/CC493641730J40749099609.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4465, '项目招投标', '河南永光电力科技有限公司', '7月27日', '4000-5000元', '漯河-召陵区', '通信/网络设备', '100-299人', NULL, 'CC661215520J40820218815', '任职要求：大专及以上学历，25-35岁，1.有相关工作经验优先；2.具有一定的沟通能力，执行能力等； 3.掌握营销管理技巧，营销基本礼仪；4.熟悉标书制作知识，流程； 5.熟练运用计算机办公软件。工作职责;1.负责信息收集及处理，标书制作，商务和技术资料的更新和归档，资料信息提供，电子商务平台微信及监督各地市审核资料准备。', '河南永光电力科技有限公司（原漯河市永光电气设备有限公司），位于中原腹地漯河市，是一家有限责任公司，成立于2001年，现占地面积100余亩，新增占地面积600余亩，现有员工300余名，是国家电网合格供应商，有500KV角钢塔、电力金具、电线电缆全国工业生产许可证，220KV钢管杆、500KV变电站钢架构、500KV钢管塔产品合格证等资质，并通过了3C强制性认证及质量、环境、健康三体系认证。公司自成立以来，稳步、健康发展，先后获得“科技企业”、国家“高新技术企业”等多项殊荣，现已成为国家电网重点供货单位之一。公司自成立以来，以优质高效的品质，科学严谨的作风承接了国内外多条输电线路、多座变电站钢架构及设备支架的加工。在设备投资方面引进国际先进大型双联动液压机、数控火焰切割机、数控相贯线切割机、三辊卷板机、角钢全自动生产线、自动埋弧焊机、大型钢管自动生产流水线、钢板冲孔自动生产线、2400T压力锥型管自动生产流水线，法兰盘自动焊接设备，高精度铆焊坐标平台、数控平面钻床、塔脚自动焊接机器人、钢管内纵缝焊机、剪板机、万能材料试验机、直读光谱仪、盐雾试验机、冲击试验机、五大元素分析仪、超声波探伤等四百多台（套）生产检验设备。目前产品加工工艺成熟，技术先进，具有较强的产品开发创新，生产制造能力，主要产品有输电线路钢管塔，单柱钢管杆，角钢塔，变电站钢构架，通信塔，电力金具，电线电缆，电气化铁路接触网支柱等系列产品。公司自入围国家电网以来，每年按30%的产值递增。2013年产值达到2.8亿元，公司先后参与了南疆输电工程、吐鲁番输电工程、喀什输电工程、南水北调工程、云阳风电工程、哈郑线输电工程等国家重点工程的建设。', 'https://www.zhaopin.com/jobdetail/CC661215520J40820218815.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4466, '资料管理', '重庆善道人力资源有限公司', '7月17日', '3000-5000元', '重庆-巴南区', '咨询服务,人力资源服务', '100-299人', '未融资', 'CC432930480J40773983402', '岗位职责：  <br>', '重庆善道重庆善道永恒企业服务集团有限公司（简称：善道企服）成立于2014年11月，总部位于重庆市，集团旗下核心企业包括重庆善道人力资源有限公司、重庆志翔航空票务代理有限公司、重庆巧实力商业管理有限公司、重庆轩泽代理记账有限公司、重庆峰窝科技有限公司、重庆善道置业顾问有限公司和重庆其乐装饰工程有限公司等。服务企业上千家，遍及全国各地。善道企服集团始终以“用心服务，客户至上”为宗旨倾力打造闭环的“企业一站式服务平台”，为企业客户提供商业办公选址、差旅、人力资源、工商/税务、企业网络安全等级保护测评等综合性优质服务。集团各下属公司均拥有专业的项目运营团队，具备丰富的项目实操经验，秉承“开拓创新、追求极致、拥抱变化、友爱正直”的企业价值观，建立了规范化、专业化、现代化和科学化的管理体制；不断加强高素质人才梯队建设，深化企业“一站式服务”品牌，已形成技术优势、人才优势和品牌优势。让我们共同携手，为企业的发展赋能，共创美好灿烂的明天！', 'https://www.zhaopin.com/jobdetail/CC432930480J40773983402.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4467, '游戏推广', '邯郸太空船信息科技有限公司', '7月17日', '5000-10000元', '广州-天河区', '游戏', '20-99人', '未融资', 'CCL1267141030J40794629205', '岗位职责:', '友情提醒:公司办公地点位于邯郸市高开区珈鼎大厦。我们:是一个充满活力的创业团队，专注于移动互联网，只做自己喜欢的产品，不接外包项目；实行民主的，扁平化的管理方式，轻松融洽的工作氛围，以及弹性工作时间；信奉”要么不做,要么做到最好”，同时我们相信”空谈可耻, show me the code!”；提供有竞争力的待遇，外加良好的装备，注重代码质量，关心员工的个人成长，并积极的学习和应用行业里的最前沿开发方法、技术和工具。项目核心成员更有机会赴美国硅谷参加Google/IO, F8, WWDC等前沿会议。总之这是一个重视人、重视技术的团队，创始人有多年移动互联网创业经验，公司目前的主要产品成功打入苹果AppStore游戏榜单Top3，小游戏突破百万日活、千万月活。如果你也对技术有浓厚兴趣，希望通过技术改变人们的生活，改善自己的生活，欢迎来试试。我们的面试流程大致分为两部分，首先会测试几个职位相关的问题,通过后会安排面试时间，面试根据具体情况不同大约为30-90分钟。技术岗位最后需要上机做Online Judge类型的测试(不会太难,基础题型)。', 'https://www.zhaopin.com/jobdetail/CCL1267141030J40794629205.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4468, 'APP推广', '成都歪马科技有限公司', '7月22日', '8000-11000元', '中山-None', '电子商务', '1000-9999人', '未融资', 'CCL1492920960J40780392108', '​​【酒水门店驻店配送员】​​​【超时不扣钱可兼职可短期可周结】​<br>中山全城均可就近安排，全职/兼职均可<br>​​【福利待遇】​<br>1、薪资构成：星级激励+全勤奖+高额提成+补贴等，多劳多得，全职综合9000+，兼职综合4000+​<br>2、员工福利：团建聚餐不断，团队氛围好​​<br>【工作内容】<br>​完成所属门店的酒水配送工作，并做好客情维护​​<br>【岗位优势】<br>​1、门店直招，无需办理健康证和缴纳任何费用，最快当日面试即可入职​2、互联网新平台，发展空间大，行业红利期，晋升机会多​​<br>【晋升发展】<br>​1、全职：店员-储备店长-店长-储备主管-主管-经理，最快2-3个月即可晋升​<br>2、兼职：表现优异者，可转全职，享受全员工晋升待遇', '歪马送酒是美团旗下的酒水即时零售品牌，经营品类涵盖啤酒、白酒、红酒、洋酒四大品类。通过与酒水品牌直接合作，严控供应链，自建配送体系，给前置仓配货，商家在小程序和外卖平台为用户提供平价、保真、平均15分钟送达的酒水及时送服务。歪马送酒在2021年6月23日广东惠州开展单城探索，启动1个城市中心仓+N个前置仓，40天开仓8家，覆盖惠州主要城区。截止2024年7月，歪马送酒在广东地区（深圳、广州、东莞、佛山、惠州、汕头、江门、中山、河源），江苏地区（南京、苏州）、浙江地区（杭州、宁波、温州）北京、上海、杭州、成都、西安、重庆、武汉、福州等22个城市建有直营门店，门店数量超过家。2025年还会入驻青岛、南宁、郑州、合肥、贵阳等城市，预计实现全国省会城市、一线城市全覆盖，门店数量超1000+。', 'https://www.zhaopin.com/jobdetail/CCL1492920960J40780392108.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4469, '统计员', '山西鸿源恒通科技有限公司', '6月3日', '3000-6000元', '太原-小店区', '运营商/增值服务,通信/网络设备,零售/批发', '20-99人', '未融资', 'CC617921320J40740125501', '1、负责对接移动公司,完成云电脑、摄像头、路由器等电子产品；<br>2、对接各移动营业厅，完成小程序移动权益的销售上量；<br>3、权益超市的开发及维护；<br>4、负责确认客户（含运营商）的各项佣金费用，及时对账', '山西鸿源恒通科技有限公司创建于2013年10月，是中国移动指定经销商，注册资金1000万，流动资金2000万，物流送货车2辆，是一家经济性质的独资企业，从事通讯设备、销售、服务于一体的专业企业，目前经营项目：手机平台（一个月平均出货一万台以上的TD手机）.手机卖场（在大南门天桥东侧地理位置好.卖场面积500平方目前经营20个以上的TD品牌手机，是太原市第一家纯TD手机的卖场，月销售TD手机3000台左右）.手机配件。公司拥有十多年的通讯业务销售经验，拥有员工100余人，其中有20人的高素质骨干力量，可根据市场需求及时开发新产品，可根据客户需求精确调整市场战略，公司有较大的销售规模，设有十余家移动自办营业厅的销售网点。企业文化：企业发展的策略:尊重人才，成就人才。勇于创新，持续改善。自我提升，相互欣赏。良性竞争，相互支持。用人标准及留才政策:品德务实思想毅力合群信任培育机遇福利待遇心胸有多大,舞台就有多大用人标准及留才政策留才计划：基本福利员工出游交通补助、话费补助夏季福利法定节假日福利年假鸿源恒通能给你带来什么高新手机技术产品，前景无限光明行业一流的管理和技术。高速成长的发展公司，舞台任你发挥追求卓越的企业文化，架设成功平台系统完善的培训体系，能力快速提升体贴温馨的留才福利规划，缔造人才乐园', 'https://www.zhaopin.com/jobdetail/CC617921320J40740125501.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4470, '项目经理/主管', '潍坊趁年华信息技术有限公司', '2月10日', '7000-14000元', '潍坊-奎文区', '计算机软件,IT服务,互联网,计算机硬件', '20人以下', '不需要融资', 'CCL1382930670J40626918102', '位要求：21-36岁，无不良嗜好，有销售经验者优先', '公司介绍：我们属于餐饮saas行业，是美团餐饮SAAS当地业务拓展团队，业务方向主要面向潍坊的餐饮商家，售卖美团收银软件和硬件设备以及做好售后维护，协助商家做好门店经营管理，提供最优的餐厅收银解决方案，比如对账、点餐、出单、接单等等薪资待遇：无责底薪3000＋社保+软件提成+硬件毛利+分润分红+每月团建人均消费100＋，同事月收入10000以上工作时间：早上9.00-下午6.00，每周单休，法定节假日带薪休假入职后，会有师傅、主管长期带你，公司有自己的线上学习知识库，可以满足你90%的学习需求，获客方式：公司专属资源APP40%+外卖团购等部门同事转介绍30%＋陌拜20%+其他10%', 'https://www.zhaopin.com/jobdetail/CCL1382930670J40626918102.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4471, '管培生/储备干部', '禾丰食品股份有限公司', '7月25日', '5000-8000元', '葫芦岛-兴城市', '农副产品加工制造,互联网,农/林/牧/渔', '10000人以上', '已上市', 'CC131932530J40798660412', '岗位职责<br>1. 深入了解市场需求，精准推荐产品：<br>经常走访客户，了解他们对肉鸡分割品的具体需求，比如口感、质量、用途（烹饪、加工等）和价格敏感度。<br>根据客户反馈，向生产团队提出改进建议，如调整分割方式、提高肉质口感等，以满足市场需求。<br>2. 制定实际销售策略，提升销售业绩：<br>分析销售数据，找出热销产品和滞销产品，根据库存，确保热销产品畅销，滞销产品找到新渠道。<br>策划促销活动，如限时折扣、买赠活动，吸引客户购买，提高销量。<br>利用社交媒体和线下活动，宣传产品特点，吸引新客户，同时维护老客户，提高客户复购率。<br>3. 建立良好客户关系，提供优质服务：<br>定期与客户沟通，及时解决客户在使用产品过程中遇到的问题。<br>为客户提供产品销售建议，如渠道、烹饪技巧、保存方法等，提高客户对产品的满意度。<br>4. 关注市场动态，及时调整销售策略：<br>密切关注竞争对手的动态，如价格调整、新品推出等，及时调整自己的销售策略。<br>关注行业趋势，了解新技术、新工艺在肉鸡分割皮领域的应用，为公司的产品创新提供建议。<br>5. 拓展销售渠道，增加市场份额：<br>开拓新的销售渠道，增加产品的曝光度和销售量。<br>与潜在客户进行深入沟通，了解他们的需求，提供定制化的解决方案，争取合作机会。<br>任职资格： 1、统招本科及以上学历，动物营养与饲料科学、畜牧兽医、水产养殖等相关专业优先。985/211院校优先考虑。 <br>2、责任心强，目标感强，热爱销售，有较好的语言表达能力、较强的逻辑思维和解决问题的能力。<br>3、有校园学生会、社团经验、社会实践经验者优先。<br>4、热爱销售工作，愿意长期发展。<br>本岗位优点：<br>1、新人友好保护期<br>2、实打实的薪酬<br>3、为新人在家门口提供好岗位', '禾丰食品股份有限公司创立于1995年4月，经过不懈奋斗，已发展成为在全球畜牧业舞台上颇具影响力的大型农牧食品企业。公司拥有饲料及饲料原料贸易、肉禽产业化、生猪养殖三大核心业务，同时涉猎动物药品、养殖设备、国际事业、宠物诊疗及食品加工等相关领域。目前拥有200余家下属企业，产品覆盖32个省市，并在尼泊尔、印尼、菲律宾、俄罗斯等国家设有工厂。2006年10月，拥有百年历史的荷兰饲料企业——皇家De Heus公司与禾丰成为战略合作伙伴，在增强禾丰技术研发实力、丰富禾丰管理经验的同时使禾丰始终拥有国际化视野、享有国际化发展资源。 2014年8月8日，禾丰股份于上海证券交易所成功上市。禾丰股份从零起步，2022年合并范围销售收入328.12亿元。28年快速发展，上市9年以来保持业绩持续增长。更多招聘动态，请关注禾丰股份招聘公众号：hfjtzp。', 'https://www.zhaopin.com/jobdetail/CC131932530J40798660412.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4472, '培训师', '长春数字科技职业学院', '5月26日', '5000-8000元', '长春-九台区', '学校/学历教育', '100-299人', '未融资', 'CCL1488169220J40738239009', '岗位职责：<br>1. 负责电气自动化技术专业的课程教学及学生指导工作<br>2. 参与制定和执行专业人才培养方案<br>3. 参与专业建设和教学改革活动<br>4. 开展科研项目和实验室建设<br>5. 参加学术交流及专业培训活动<br>岗位要求：<br>1. 具有电气自动化及相关专业背景，研究生及以上学历；高级职称可放宽至本科<br>2. 具备高校教师资格证，有教学经验者优先<br>3. 熟悉电气自动化领域专业知识和技术<br>4. 具备良好的语言表达和沟通协调能力<br>5. 具备一定的科研和创新能力', '长春数字科技职业学院，经吉林省人民政府批准设立，教育部备案，已纳入吉林省统一报考平台，具有颁发国家认定的学历证书和考取职业技能等级证书的全日制专科层次高职学校。学校占地26万平方米，建筑面积16万平方米，配备智慧教室279间、一体化教室86间、实训室67个、教学工坊3个、实训机房16个，工业机器人、智能制造等12个具有真实生产过程的教学实训中心，设备总值1.2亿元。学校拥有体育馆、运动场等，体育设施数量充足、功能完备；630余间现代化学生公寓，全天提供热水、淋浴、自助洗衣、休闲服务，功能完善、温馨舒适；生活服务中心可容纳5000人就餐，条件优越、卫生安全；校园智慧管理系统，高效便捷、个性服务。学校以“数智立教、数智立校、数智立人”为办学理念，立足“数字吉林”建设，坚持产教融合科教融汇，与华为、科大讯飞等数字科技头部企业深度合作办学，建设智能制造、智能交通、数字文旅、数字商务4个产业学院，开设计算机应用技术、软件技术、网络技术、智能机器人技术、智能网联汽车技术、城市轨道车辆应用技术6个专业，面向全国培养高素质数智化技术技能人才。', 'https://www.zhaopin.com/jobdetail/CCL1488169220J40738239009.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4473, '售后客服', '邯郸市菲豪科技有限公司', '7月24日', '5000-6000元', '长沙-岳麓区', '计算机软件', '20-99人', NULL, 'CCL1495760510J40735509216', '薪资：底薪3500+绩效1700+全勤300，综合5500元左右<br>工作时间：10:00-19:00<br>休息时间：月休8天<br>发薪日：20号<br>福利：五险一金<br>工作要求：<br>沟通协调能力：能有效应对和处理情绪激烈的疑难、投诉，保持自身情绪稳定，积极推动问题解决。', NULL, 'https://www.zhaopin.com/jobdetail/CCL1495760510J40735509216.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4474, '销售助理', '亚信科技(中国)有限公司', '6月11日', '150-200元/天', '济南-市中区', '通信/网络设备', '10000人以上', '已上市', 'CC139131340J40746122411', '数据类支持，公司内流程跟进<br>招投标协助支持<br>会议室预定，餐厅预订等行政事项<br>希望你 26年毕业（92本科，一本研究生最好）<br>关注细节，情商高，想在此职位方向发展<br>（实习生职位不需要直接对接客户，辅助，支持类工作，无销售性质）<br>提供宿舍床位<br>有转正机会，可短期请假。', '亚信科技是中国领先的信息科技产品及服务提供商，拥有丰富的软硬件产品开发和大型工程实施经验。公司深耕市场超过 30年，在 5G、云计算、大数据、人工智能、物联网、数智运营、业务及网络支撑系统（BSS&OSS）等领域具有先进的技术能力和众多成功案例，客户遍及通信、广电、能源、交通、政务、金融、邮政等行业。近年来，亚信科技持续聚焦云网、数智、IT三类产品的研发，并结合咨询规划、数智运营和系统集成能力，不断向“产品与服务双领先”目标迈进。2024年公司进一步提出“四个转变”发展战略，聚焦打造 5G专网、边缘智能、信创数据库、大数据与可信数据流通、xGPT等战略级软件及软硬一体产品，并加强向非通信及国际市场的开拓。亚信科技始终致力于将 5G、人工智能、大数据等数智技术赋能至百行千业，与客户共创数智价值。面向未来，公司将努力成为最可信赖的数智价值创造者，并依托数智化全栈能力，创新客户价值，助推数字中国。', 'https://www.zhaopin.com/jobdetail/CC139131340J40746122411.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4475, '产品专员/助理', '云钞金融服务(北京)有限公司', '5月7日', '7000-14000元', '北京-西城区', '计算机软件', '100-299人', NULL, 'CC838479040J40841850715', '岗位职责：   1. 协助经理处理研发日常事务，包括日程安排、会议组织、文件起草及汇报材料整理。', NULL, 'https://www.zhaopin.com/jobdetail/CC838479040J40841850715.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4476, '管培生/储备干部', '南京天奕创业服务有限公司', '7月23日', '8000-10000元', '上海-浦东新区', '咨询服务,企业服务', '100-299人', '未融资', 'CCL1328788790J40933968304', '世界五百强企业，德国奥乐齐集团（ALDI）（年营业收入10500亿），零售精英管培生岗位，无销售性质，上海，苏州，无锡均可分配，2年内晋升超市店长 <br>【公司介绍】 <br>德国奥乐齐（ALDI），世界五百强企业，是德国最大的连锁超市，百年企业，至今已在全球10余个国家拥有超过1万家店铺， 并成为国际市 场上享有盛誉和备受肯定的零售品牌，是世界品牌500强。2019年公司进入中 国市场。目前奥乐齐在华东已有几十家线下门店店铺 <br>【岗位要求】 <br>1、2025届本科毕业（优秀的大专应届生也可） <br>2、接受工作时间和接受城市内区域分配；  <br>3、热爱零售商超行业，具备快速学习能力，勇于挑战自我，追求卓越；  <br>4、可以近期线下面试（上海，苏州，无锡其中一个城市） <br>【薪资待遇】 <br>1、月收入8K至10K，五险一金， <br>2、晋升机制：1-3个月晋升值班经理，4-12个月晋升副店，12-24个月晋升店长 <br>【工作地点】<br>上海，苏州，无锡，3个城市均招聘中，市内进行分配 <br>有意向请投递简历，留个微信具体沟通，不接受工作地点或已经投递过的请勿投递，谢谢', '南京天奕是一家专门从事科技企业发展顾问服务的公司，围绕科技创业主线，拥有专业相结合的运营管理服务团队，拥有高层次顾问专家队伍，致力于为科技创业企业提供优质的孵化服务，并建立了一套具有特色的服务体系，从企业发展成长过程中的实际需求出发，为企业从初生到成长加速、发展壮大的全链条培育提供全方位服务。', 'https://www.zhaopin.com/jobdetail/CCL1328788790J40933968304.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4477, '广告销售', '顺世宏信', '7月8日', '5000-6000元', '北京-平谷区', '运营商/增值服务,通信/网络设备', '20-99人', '未融资', 'CC370650580J40564123610', '岗位职责：<br>1）协助完成本公司内业务小组分配的ERP系统录入和维护工作（移动运营商系统）；<br>2）核查相关信息并制作相关文件（如：核查话务量、制作回款审核单、制作扣款通知函、免责材料等）；<br>3）系统相关流程的跟进和处理；<br>4）领导交代的其他工作；<br>任职要求：<br>1）本科及以上学历，应届毕业生优先；<br>2）具有良好的计划和执行能力、协调能力和人际沟通能力；<br>3）能使用Word、Excel、PPT、PS等办公软件；<br>4）积极主动，具备团队意识，具有高度的责任心，能够承受较强的工作压力。', '北京顺世宏信科技有限公司1999年成立，立足于北京，公司与歌华以及电信、移动和联通三大运营商，深耕无线网络建设与服务，是北京市唯一的一家与各大运营商在4G、5G领域均有深度合作建设项目的专业型公司。业务范围涵盖运营商各频段4G宏站、一体化微基站的商务选址和基站建设与服务保障。', 'https://www.zhaopin.com/jobdetail/CC370650580J40564123610.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4478, '社区运营', '中国平安', '7月25日', '面议', '秦皇岛-海港区', '保险,保险', '10000人以上', '已上市', 'CC000204810J40801080812', '●●岗位急招 招满即停<br>●企业文化:<br>我们固定早九晚六周末双休我们绝对不加班，下班就走，我们适合喜欢做服务，而又不想有太多工作压力的人同时对于有晋升欲望、有赚钱欲望的人，我们也给予充足的空间。人性化工作时间+周末双休不加班!<br>●福利待遇：<br>工资构成:<br>1、基础无责底薪+职级津贴+岗位津贴+绩效，综合薪资7-25k<br>2、缴纳社保:医疗保险，意外医疗、疾病医疗、生育险、失业保险+企业保险+住房公积金。<br>●工作时间:<br>早上:09:00-17:00，7小时工作制，午休两个小时。绝不加班。<br>周末双休。带薪年假，年底双薪，法定节假日带薪休假+带薪158天产假<br>●发展空间:<br>需要锻炼自己、提升自己，那么平台就很重要，上市公司五百强晋升培养机制完善，管理岗位需求大，对于有晋升意愿的伙伴提供职位直升扶持!<br>绝对的公平公正公开，全靠实力，全是实力派。<br>●培训<br>不用担心自己不会哦<br>1、新人入职了解公司、熟悉产品、超简单、这么聪明的你肯定没问题。也有平安大学做后盾<br>2、培训结束，公司分配师傅、组长、团队主管手把手教<br>●工作环境:<br>1、5A级舒适的办公环境(氛围融洽友好，团队年轻而富有活力)<br>2、员工旅游+员工生日会+发放丰厚的奖励，优秀员工每月有表彰(超多惊喜等你一起)<br>3、每年5-15天带薪年假(幸福感超足哦)<br>4、享受国家法定婚假产假以及陪产假等(一起见证你人生的每一个重大时刻)<br>5、琳琅满目的零食、咖啡、饮料、下午茶(工作的同时放松一下)<br>6、丰富的企业活动，团建聚餐等<br>●●●员工关怀<br>1.为员工提供多途径反馈工作、生活中遇到的问题困难，通过面对面圆桌会，线上答疑等方式给予解助<br>2.为家庭特别困难员工提供帮助，领导可爱同事暖心', '中国平安致力于成为国际领先的科技型个人金融生活服务集团。2019年，中国平安深入推进\\\\\"金融+科技\\\\\"、\\\\\"金融+生态\\\\\"战略转型，持续提升数据化经营能力，整体业绩及核心金融业务持续稳健增长，科技赋能成效显著，生态赋能效果初显，综合金融用户数、客户数、客均合同、客均利润均有明显增长。公司实现营业收入同比增长19.7%至11,688.67亿元。截至2019年底，公司个人客户数首次突破两亿，互联网用户量达5.16亿，全年新增客户数3,657万，其中40.7%来自集团五大生态圈的互联网用户。中国平安始终践行\\\\\"金融为实体经济服务\\\\\"的精神，坚持把实体经济服务作为出发点和落脚点，通过旗下的保险、银行、信托、金融科技等业务，把逾4万亿金融资源配置到经济社会发展的重点领域和薄弱环节，包括通过保险保障、提供贷款、债权股权计划、普惠金融等多种方式，全面助力实体经济发展。凭借全球领先的创新科技，中国平安将科技深度运用于金融主业中，助力降本增效、风险管控，打造优质产品和极致服务体验，提升客户口碑。与此同时，平安将领先科技广泛应用在金融、医疗及智慧城市等领域，全面支撑\\\\\"金融服务、医疗健康、汽车服务、房产服务、智慧城市\\\\\"五大生态圈建设。在企业社会责任方面，平安深化可持续发展理念，MSCI ESG评级连续两次调高至A级，打造AI-ESG平台赋能责任投资，截至2019年12月末，公司责任投资规模达9,544.49亿元，可持续保险金额达121.21万亿元，绿色信贷年度授信总额590.56亿元。同时，平安积极响应国家脱贫攻坚战的号召，推进\\\\\"三村扶贫工程\\\\\"项目，累计提供专项扶贫资金249.05亿元。面对新冠肺炎疫情，平安第一时间推出保险保障、医疗支持、对外捐赠等多重支持举措，提供的物资及现金捐赠总额超1.75亿元。2020年，中国平安品牌价值持续提升，名列美国《财富》“世界500强企业”第21位，居全球金融企业第2位，《福布斯》全球上市公司2000强第7位，BrandZ™全球品牌价值100强第38位，蝉联全球保险品牌第1位。', 'https://www.zhaopin.com/jobdetail/CC000204810J40801080812.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4479, '游戏运营', '河南墨徊网络科技有限公司', '7月15日', '6000-9000元', '葫芦岛-龙港区', '游戏', '20-99人', NULL, 'CCL1506194460J40772236702', '这边是招线上游戏打手，我们平台包含 原神、崩铁、三角洲、鸣潮、燕云十六声 会以上游戏任意一款就行 <br>热爱游戏，具备良好的游戏素养和团队合作精 <br>神。 <br>  精通至少一款热门游戏，拥有丰富的游戏经验和  <br>出色的游戏技能。', NULL, 'https://www.zhaopin.com/jobdetail/CCL1506194460J40772236702.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4480, '游戏推广', '成都萌小玺文化传媒有限公司', '7月25日', '5000-8000元', '西安-碑林区', '新媒体', '10000人以上', NULL, 'CCL1486511100J40839135515', '年龄18-30，会玩热门手游，例如:王者荣耀有经验者优先，例如:王者荣耀历史段位达到钻石及以上<br>性格活泼，普通话比较标准，能提供高情绪价值，能接受开麦', '成都萌小玺文化传媒有限公司，成立于2024年，位于四川省成都市，是一家以从事文化艺术业为主的企业。成都萌小玺文化传媒有限公司，成立于2024年，位于四川省成都市，是一家以从事文化艺术业为主的企业。', 'https://www.zhaopin.com/jobdetail/CCL1486511100J40839135515.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4481, '质检员', '东莞市众博人力资源有限公司', '7月22日', '7000-8000元', '南京-秦淮区', '人力资源服务', '10000人以上', NULL, 'CCL1222401860J40758092001', '本地新建工厂，本厂直接招聘，应聘当天入职，安排免费吃住上班，直接到厂区面试，全程不花冤枉钱，厂区签合同有保障(不被坑)<br>短期工 长期工 都可以！！！！<br>----------------------------------------------<br>薪资待遇：<br>小时工：月薪7000-9000多劳多得 正式工：早8晚5，保底工资7000，有五险一金<br>打卡15天可预支3000<br>----------------------------------------------<br>薪资发放：<br>每月10号发工资，不压工资，人走账清。可现金<br>----------------------------------------------<br>工作内容：<br>目前主要代加工手机、平板电脑、智能手表和各类高端数码相机，长白班、坐着上班，不过安检门、有流水线和非流水线，可玩手机<br>岗位有普工、组装、仓库管理员、质检、扫码、贴标签、包装、储备干部，上班自由，岗位很多，可自行选择（不会可以教）<br>----------------------------------------------<br>福利待遇：<br>公寓住宿，4-6人间，有免费夫妻房，三餐公司免费提供<br>公司为员工缴纳五险一金，不扣工资<br>----------------------------------------------<br>招聘要求<br>16-50岁，身体只要健康即可，男女不限，不分时间当到了就可安排住宿<br>----------------------------------------------<br>报名点击下方---申请职位----点击微聊---在线添加咨询<br>----------------------------------------------<br>▲郑重承诺此招聘不以任何形式收费，薪资待遇全部属实24小时接受咨询▲|', NULL, 'https://www.zhaopin.com/jobdetail/CCL1222401860J40758092001.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4482, '管培生/储备干部', '三明厦钨新能源材料有限公司', '7月22日', '6000-9000元·13薪', '三明-None', '钢铁/有色金属冶炼及加工,新能源', '300-499人', '未融资', 'CC605346030J00423096304', '1.针对24、25届毕业生，本科以上学历；<br>2.安全工程人力资源管理/行政管理/工商管理/社会学，专业基础扎实，学习成绩良好；<br>  3.通过英语四级，具备一定文字功底，掌握专业相关软件使用技能；', '三明厦钨新能源材料有限公司成立于2012年6月8日，由厦门厦钨新能源材料股份有限公司与三明市投资发展集团有限公司按7：3比例出资设立，注册资本金1.45亿元，用地面积约400亩。公司现已形成年产22000吨锂正极材料生产能力。公司主营产品为锂离子电池正极材料，包括钴酸锂产品、三元材料产品。其中钴酸锂主要应用于小型数码电池领域，三元材料主要应用于混合动力及纯电动汽车、电动工具及电单车、储能电池等领域。公司自2014年一期建成投产以来，产销量快速攀升。2019-2022年，公司销售额连续四年突破40亿元，钴酸锂产品市场占有率连续五年位居全国第一位，荣获“福建省单项冠军产品”。公司已通过ISO9001质量管理体系、ISO45001职业健康安全管理体系、ISO14064温室气体盘查体系等七个管理体系认证。近年来，公司通过了“福建省专精特新企业”“福建省第五批工业龙头企业”“福建省第五批绿色工厂”等资质认证，荣获“福建省五一劳动奖状”“福建省工人先锋号”和“三明市模范职工之家”称号。公司依托厦门钨业和厦钨新能源的技术研发优势，秉承“以发展壮大能源新材料产业为己任”的企业愿景和“为实现碳中和提供先进材料解决方案”的企业使命，在三明这片绿水青山的热土上，重点围绕能源新材料产业，将公司打造成国内重要的钴酸锂生产基地，并为三明市奋力建设革命老区高质量发展示范区做出应有的贡献。一、管理机制1.公平晋升：提供管理、技术、专业序列三条职业发展通道；2.注重培养：为专业技术人才提供“导师制”培养机制，助力新员工成长；3.机制完善：建立绩效、项目、骨干激励、竞聘、评先评优等激励机制；4.假期完整：享受法定节假日、带薪年休假、（陪）产假、婚丧假等；5.福利齐全：享七险二金、带薪年假、生日慰问、健康体检、年节福利品等福利。二、工作环境1.职工住宿：厂区提供宿舍（套房、2人间宿舍，内部配置齐全，可拎包入住），骨干员工提供市区周转房；2.职工食堂：自办职工福利食堂，提供卫生、丰富、实惠的伙食；3.职工班车：提供职工通勤班车；4.娱乐休闲：建立员工活动中心（羽毛球场、乒乓球室、台球室等）、篮球场、健身广场、职工书屋、党建活动室等；5.活动多样：迎新晚会、拔河比赛、唱响金明、各类球赛、金秋慢跑、金明讲坛、节庆民俗趣味活动、手游比赛等各类活动竞赛；6.环境舒适：厂区整洁干净、环境优美、空气清晰、团队关系友善融洽。', 'https://www.zhaopin.com/jobdetail/CC605346030J00423096304.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4483, '游戏运营', '郑州文祺电子商务有限公司', '7月24日', '4000-6000元·13薪', '郑州-中原区', '互联网,零售/批发', '300-499人', '未融资', 'CC498376230J40825994208', '公司属于大平台，稳定，五险一金+餐补+年终奖+单双休+每年有2次调薪机会+晋升渠道 上班时间:9:00-18:30，中午休息一个半小时', '郑州文祺电子商务有限公司简介郑州文祺电子商务有限公司成立于2016年，主要经营家电产品的零售及服务。公司现有办公面积3000多平方米，团队规模300人以上。自成立以来，公司始终坚持“为员工创造平台、为客户创造价值、为社会创造财富”的使命，以市场需求为导向，持续为用户及客户提供优质产品和专业服务。通过7年多的发展，公司已形成了线上零售、自营商城、运营服务3大业务板块，成长为多品牌、多品类、多渠道覆盖，以满足用户和客户需求为中心的品牌服务商。其中线上零售渠道覆盖了传统电商（京东等）、社交电商（拼多多等）、兴趣电商（抖音/快手等）等国内主流电商销售平台。公司在业务发展的同时持续关注团队的成长、办公条件的改善和管理体系的优化，最大限度为员工提供舒适的办公环境和充分的发展空间。目前公司为员工提供入职带薪培训、餐补、个人社保、公积金、团建活动、员工生日会、节假日福利、带薪年假等福利；在个人发展方面，公司提供职业发展规划、岗位技能培训及内部晋升计划，为个人能力成长和职业上升提供发展舞台。回顾过去，第一个7年我们创业初成，取得了一定成绩，为持续发展打下基础；放眼未来，第二个7年已经开启，我们将始终保持创业创新精神，以开拓进取的态度跨越新的起点，开启新的征程，书写新的篇章！', 'https://www.zhaopin.com/jobdetail/CC498376230J40825994208.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4484, '项目经理/主管', '三维海容(青岛)科技有限公司', '7月25日', '1-1.2万', '济宁-任城区', '电气机械/电力设备,专用设备制造,建筑设备安装,医疗设备/器械', '300-499人', NULL, 'CCL1290054480J40484803506', '工作内容：', '三维海容创建于2010年，公司集研发、生产、销售、施工及服务于一体，以“与你共创智慧医院”为理念，致力于为医院提供医用物品自动传输的专业解决方案，推动中国智慧医院建设发展。现已建成占地面积30000平方米的生产基地，进行产品自主生产，并于青岛西海岸自贸区设立营销基地，开展研发、销售、运营等工作。现公司旗下员工300余人，至今已获得专利证书近300项，产品遍布全国27个省市，为全国600多家医院提供医用物品自动传输服务。公司参与多项行业医用物流标准的制定，并荣获山东省瞪羚企业、山东省知名品牌、中国医院建设品牌服务企业匠心奖，中国医院建设十大金牌装备供应商等荣誉称号，是中国医疗行业最具品牌影响力的企业。产品覆盖了医院日常的洁物传输、污物回收，两大类别下又细分八种核心产品，洁物传输包括箱式物流传输系统、气动物流传输系统、标本物流传输系统、机器人物流传输系统、医用手供一体化仓储系统；污物回收包括桶式污物回收系统、机器人污物回收系统、负压管道式污物回收系统，已形成完整的医院多元智慧物流体系。', 'https://www.zhaopin.com/jobdetail/CCL1290054480J40484803506.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4485, '储备干部', '广州星火未来通信有限公司', '4月10日', '5000-10000元', '广州-天河区', '通信/网络设备,通信/网络设备,运营商/增值服务', '100-299人', NULL, 'CCL1317164830J40663138512', '【福利待遇】：', '星火通讯，致力于推动中国5G市场发展，与中国移动，中国联通深度合作，陆续建立多家移动，联通营业厅。在传统营业厅的基础上，嵌入星火独特的运营管理体系，使之更适应今天的发展，同时也为中国的5G事业培养更多优秀的人才。', 'https://www.zhaopin.com/jobdetail/CCL1317164830J40663138512.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4486, '广告销售', '温州赏金猎人网络科技有限公司', '8月26日', '3000-5000元', '沈阳-浑南区', '互联网', '20-99人', '未融资', 'CC842923730J40480970811', '主要负责招商加盟,寻找游戏推广员,和游戏代理进行合作!介绍我们平台的优势,', '许可项目:第二类增值电信业务互联网信息服务互联网游戏服务(依法须经批准的项目,经相关部门批准后方可开展经营活动,具体经营项目以审批结果为准)。一般项目:信息系统集成服务信息咨询服务(不含许可类信息咨询服务)信息技术咨询服务企业管理咨询互联网销售(除销售需要许可的商品)网络与信息安全软件开发网络技术服务互联网安全服务市场营销策划广告发布电影摄制服务数字内容制作服务(不含出版发行)广告设计、代理组织文化艺术交流活动品牌管理文化场馆管理服务专业设计服务文化娱乐经纪人服务其他文化艺术经纪代理知识产权服务(专利代理服务除外)软件开发动漫游戏开发数字文化创意软件开发', 'https://www.zhaopin.com/jobdetail/CC842923730J40480970811.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4487, 'BD经理', '内蒙古才驰汽车贸易有限公司', '7月7日', '5000-8000元', '呼和浩特-回民区', '贸易/进出口', '20-99人', '未融资', 'CCL1503953960J40752141101', '1、负责公司线上平台以及线下运营的推广及宣传<br>2、根据流程，配合运营团队完成拉新目标<br>3、跟据所辖区域，制定沟通方式，吸引客户<br>4、参与运营团队管理，给出有实效性的引流活动策划<br>5、收集市场信息，收集竞品信息<br>薪资：5000+  五险一金  月休8-10天', '内蒙古才驰汽车贸易有限公司是数智赋能于汽车，数字化运营的汽车综合联盟，集团目前同步运营的有内蒙古901和内蒙古讯佳公司。公司位于呼和浩特市汽车销售核心商圈–→恒茂汽车中心大厦。场地面积4000平方米。我们专注于新能源汽车的全方位数字销售服务，同时公司将赋能于汽车品牌，数字化机制全区推广联盟。展厅采用智能化展示，汇聚国内外主流汽车品牌，零元购车，排队领车，汽车金融等一站式购车服务。公司依托先进的数字化管理平台，构建了线上线下相结合的创新营销体系，通过大数据分析为客户提供个性化服务方案，快速推动全区绿色新能源汽车、数智化转型升级。公司在战略阶段，正式运营上线后将成为全区规模最大的汽车销售集团化公司。涵盖新能源汽车销售、运营及汽车后市场全产业链服务。公司积极响应国家2025年发展规划，将全面推进十二盟市及旗区分支机构的联盟布局，打造全区的汽车服务网络。现因业务快速拓展，现面向社会广纳贤才，岗位需求广泛，涵盖数智销售、运营、技术、品牌推广等多个领域的管理岗位。我们为员工提供：1、行业领先的薪资机制，入职后即缴纳五险一金。2、弹性化办公机制，实行月休8～10天的自主调休，保障工作生活相平衡。3、公司晋升体系完善，拥有广阔的发展空间，共享发展红利。我们诚挚邀请有志之士的加入，共同开创内蒙古汽车行业新蓝海！数智赋能，共赢绩业！', 'https://www.zhaopin.com/jobdetail/CCL1503953960J40752141101.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4488, '销售运营', '吉林省蓝青蛙劳务派遣有限公司', '6月27日', '4000-6000元', '长春-绿园区', '人力资源服务', '100-299人', '未融资', 'CC418019230J40805660303', '岗位职责：', '吉林省蓝青蛙劳务派遣有限公司是由吉林省人社厅批准从事经营劳务派遣、人力资源等服务的企业，公司实缴注册资金200万元，并已通过ISO9001质量管理体系认证,是一家专业为企业提供劳务派遣、劳务外包、人力资源的供应商。蓝青蛙是一家具备现代企业管理制度和服务意识的专业人力资源服务企业。现设有市场运营部、猎头部、人力资源部、办理用工手续、保险缴纳、保险理赔、工社会保障部、综合办公室、财务部等部门，其中汇聚了多名来自省内知名企业、劳动保障部门的资深人力资源管理专家。并在烟台、吉林市、延吉等地设有分公司及办事处。蓝青蛙为企业提供的服务包括：劳务外包、劳务派遣、劳动仲裁委托、社保代缴等人事外包服务。其中所涉及的服务项目包括了：与员工签订劳动合同、资计算发放、退工手续办理等相关的人事服务。', 'https://www.zhaopin.com/jobdetail/CC418019230J40805660303.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4489, '律师助理', '北京市盈科律师事务所', '7月7日', '3000-5000元', '福州-台江区', '咨询服务', '1000-9999人', '未融资', 'CC147727150J40860818815', '1.具有院校法学(法律)本科及以上学历；<br>2.通过司法考试或法律职业资格考试；<br>3.语言表达能力好，具备良好的沟通、组织及协调能力，逻辑思维清晰；<br>4.勤奋好学、接受指导律师的工作安排、有责任感、文书写作能力强；<br>5.具有团队协作精神，做事认真严谨；<br>6.完成其他交办工作，热爱律师行业；<br>7.认同盈科律师事务所发展理念、适应盈科所创新发展模式。', '北京市盈科律师事务所是一家全球化法律服务机构，成立于2001年，总部位于中国北京，是联合国南南合作全球智库网络联合创始机构，自2022年以来在Global 200全球律师人数排名中蝉联第一。盈科坚持“党建引领，建设国际一流律师事务所”，秉承“全球视野、本土智慧”，积极应对法律服务市场变化，促进律所稳步发展，2021年开启“国际化、专业化、数智化、碳中和”高质量发展新阶段。盈科致力于搭建“全球一小时法律服务生态圈”，总部采取“直接投资、直接管理”的模式，在中国大陆地区拥有124家律所及1家粤港澳联营律所。截至目前，盈科全球法律服务网络已经覆盖了104个国家和地区的199个国际城市。基于全球布局，盈科坚持“以客户为中心，以律师员工为本，律师事务所可持续发展，党和人民满意”的发展原则，全面加强专业化建设，在全国层面设立专业委员会45个、法律服务中心21个、专业部门1000余个，满足客户在各个法律领域、全球范围的法律服务需求。此外，盈科聘请了在国内外法学理论及实务领域享有声誉的多位法学专家担任专家顾问。盈科全国24400余名员工，致力于为客户提供全球商务法律服务，为客户创造价值。盈科成立二十余年来，已累计为超过1590000家海内外企业提供高品质法律服务。无公益，不盈科。盈科积极履行社会责任，持续打造具有创新力和公信力的公益平台，通过成立公益基金、法律援助、普法讲座、捐资助学、扶贫济困等形式，助力社会公益事业发展。与时俱进，守正创新。随着数字时代的来临，盈科加速“数智化律所”的转型与升级，大数据管控平台全面上线，实现对盈科系统内各类数据的实时监控；“Law Wit”云端办公系统投入使用，打破空间限制、高效匹配律师办公需求；盈科AI律所智能空间站正式发布，通过物联网+新媒体+视频+AI的方式，在全球范围内为客户提供及时、高效的一站式自助法律服务。“诚信、卓越、创新、开放、共享”是每一位盈科人恪守的律所文化。未来，盈科还将努力发挥自身商务律师事务所的优势，整合全球资源为客户提供优质、高效的法律服务，让客户满意，建设国际一流律师事务所，为法治中国建设贡献力量。', 'https://www.zhaopin.com/jobdetail/CC147727150J40860818815.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4490, '游戏推广', '无锡余音缭绕文化有限公司', '2025-07-27 02:01:16', '1-1.6万', '惠州-惠城区', '文化艺术/娱乐', '10000人以上', NULL, 'CCL1385391730J40867121015', 'TT语音平台公会招聘数名游戏嘉宾<br>线上居家办公<br>年龄要求：18~39周岁<br>工资：新人1200+一周，老员工做熟练了一周可在5000+一周，薪资周六周日平台自提,每个月10号公会发放工会福利（游戏厅时长奖励+礼物情况奖励）<br>工作时间：游戏厅上午10点开厅，凌晨2点关厅，在这时间段内选取2-6个小时来做，2个小时起做，没时间可以不做<br>职位详情：在游戏厅接客户点单，1个小时的单咱到手50，20分钟的单咱到手15，互动过程中也可获取礼物，游戏种类不限，技术和段位不要求（王者黄金，和平黄金即可）', NULL, 'https://www.zhaopin.com/jobdetail/CCL1385391730J40867121015.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4491, 'BD经理', '京东集团', '6月8日', '8000-15000元·16薪', '成都-武侯区', '互联网,电子商务', '10000人以上', '已上市', 'CC192921310J40743039809', '岗位职责：（招餐饮商家、协助商家上线、客情维护、爆品选品、促销活动谈判）；<br>1.负责餐饮类品牌招商清单梳理，通过电话触达进行商务洽谈达成合作关系，并完成商家季度和年度销售目标制定；<br>2.辅助商家在平台完成建店建品工作，并赋能商家熟悉平台运营机制和模式，提升商家的运营效率；<br>3.结合市场情况并不断挖掘用户需求，制定符合品牌的个性化营销和运营方案，帮助品牌不断提升经营水平和销售交易额；<br>4.协同履约、客服等部门，做好品牌和用户的服务体验保障；<br>5.做好品牌的客情维护工作，并持续跟踪与分析合作效果，并不断完善运营动作，实现品牌与平台的共赢；<br>任职要求：<br>1.专科及以上学历（优秀者放宽学历至中专/高中）；<br>2.1年以上的零售、快消、餐饮行业的客户经理或运营类岗位经验优先；<br>3.具备成熟的商家谈判技巧，熟悉商家运营工作，过往有优秀的业绩结果；<br>4.具备良好的服务意识，团队合作精神和敬业精神；<br>5.个性开朗，反应敏捷，逻辑性强，有责任心；<br>工作时间：9:00-18:00、周末双休<br>薪酬区间：8k~13k*16，底薪5k+提成（多劳多得制）<br>福利待遇：五险一金、带薪年假、节日福利、定期团队建设活动；<br>职业发展：清晰的晋升路径（销售代表→高级销售→团队主管→销售经理）及系统化培训；<br>工作地点：成都市武侯区京东西南总部大厦', '京东（JD.COM）是中国领先的技术驱动型电商，并致力于成为领先的以供应链为基础的技术与服务提供商。其尖端的零售基础设施使消费者可以随时随地购买所需的任何商品。京东向合作伙伴、品牌商和多个领域开放了技术和基础设施，作为零售基础设施服务商推动各行各业生产效率的提升和创新。京东也是纳斯达克100指数的一员和财富全球500强企业。', 'https://www.zhaopin.com/jobdetail/CC192921310J40743039809.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4492, '网络客服', '博岳通信', '7月18日', '4000-6000元', '石家庄-裕华区', '运营商/增值服务,IT服务,通信/网络设备', '10000人以上', NULL, 'CC351377410J40756790001', '缴纳社保 无压力简单 挑战高薪<br>【工作内容】轻松无压，无销售，无任务量硬性要求，打字录入<br>【薪资待遇】 试用期保底 3000 综合 3000-4000<br>转正薪资是在 4000-5500+上不封顶<br> 5险，奖金、生日会节假日福利等 <br>【工作时间】8h工作制，月休5-7天 下班不再处理工作内容，生活工作兼顾~ <br>【要求】18-35周岁，晋升空间大速度快，招满即止 <br>公司福利: <br>按国家规定购买五险、生日会、团建活动 <br>公司所有岗位均为内部培养，内部晋升（机会公平选拔透明] <br>方向一：运营岗—储备干部、运营团长（班长）、运营主管、运营经理等; <br>方向二：支撑岗一数据专员，质检专员、培训讲师等岗位： <br>方向三：职能岗一人事行政专员、绩效专员、财务专员等岗位 <br>培训安排: <br>面试通过，统一安排带薪培训，培训期短，让员工“0”基础学习，轻松面对工作', '河北博岳通信技术股份有限公司是一家大型的电子商务、呼叫中心运营及信息服务供应商，主要从事大数据建模/分析/应用、呼叫中心运营、运营商业务渠道、云服务、网络与信息服务业务。专注于为运营商、电子商务、金融、互联网企业和中小企业提供端到端的运营及服务解决方案。公司现有员工15000名，拥有运营坐席超过16000个，目前在北京、河北、四川、湖南、江西、辽宁、福建、宁夏、贵州、浙江、陕西等多个省市设有分公司和办事处。在大数据应用和呼叫中心运营领域，博岳股份与全国十几个省市通信运营商客户进行了全面合作,包括北京移动、中国移动咪咕公司音乐基地、咪咕动漫、四川移动、河北移动、河北铁通、宁夏移动、卓望信息、辽宁移动、江西移动、陕西移动、湖南电信、贵州联通、虚商迪信通；博岳股份与十几家互联网企业在运营和服务领域进行全方位的合作，包括小米科技、去哪网、多点生活、牛电科技、海选网运营支撑服务；博岳与互联网金融九鼎投资-借贷宝进行了全方位的战略合作，包括人人行客服、人人行催收、人人推和研发合作。博岳股份全面服务于通信运营商、金融、电商及互联网企业，服务用户超过5亿。在云服务领域，基于互联网模式建立了端到端的云客服平台，向互联网企业和各中小企业提供系统平台、数据库、数据建模及分析、物理场所、台席、人员及培训等端到端解决方案；为互联网企业和各中小企业提供快速、便捷、性价比高的优质服务。同时公司根据客户的需求，为客户设计完整的呼叫中心解决方案，并负责呼叫中心的建设、运营与维护，承接客户的对外联络、咨询、投诉、问卷调查、营销、客服等各项工作。作为河北省高科技企业，博岳股份于2016年3月份成功挂牌新三板。公司具备工信部颁发的“中华人民共和国增值电信业务经营许可证（全国呼叫中心业务许可证、河北省因特网信息服务业务许可证）”、“通信信息网络系统集成乙级”及“道路运输经营许可证”等资质，并且通过了ISO9001质量管理体系和ISO14001环境管理体系等权威认证。博岳股份立志发展成为业界一流的信息服务和网络服务提供商，博岳股份全面向世界优秀企业学习。博岳股份吸纳业界优秀人才，聚焦客户、聚焦业务，实现平台化和规模化的管理和运作，公司将秉承“以客户为中心、以贡献者为本、持续艰苦奋斗”的企业核心价值理念，我们相信通过全体员工的不懈努力和追求，一定能够为客户提供最好的解决方案和最优质的服务，并为客户实现商业成功!', 'https://www.zhaopin.com/jobdetail/CC351377410J40756790001.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4493, '广告销售', '浙江友华工程咨询有限公司', '7月25日', '6000-10000元', '杭州-滨江区', '通信/网络设备,通信/网络设备,运营商/增值服务', '1000-9999人', '未融资', 'CC284529010J40759264301', '岗位职责： <br>1. 商务拓展：协助商务经理开展与运营商及合作伙伴的商务拓展、合作沟通。<br>2. 客户关系管理：建立和维护与客户的良好关系，挖掘潜在客户。<br>3. 市场分析：收集市场信息及竞争对手动态，为商务决策提供支持。<br>4. 项目管理：协助项目整体进度管理的跟进，协调各部门工作。<br>5. 合同与预算管理：协助商务经理完成合同管理及项目预算控制。<br>岗位要求：<br>1. 学历要求：本科及以上学历，市场营销类相关专业、空乘或酒店管理相关专业。<br>2. 核心素质要求：沟通能力强；拥有较强分析能力；抗压能力好；形象气质佳，熟悉基本商务礼仪。<br>3. 其他条件：熟练使用办公软件(Word、Excel、PPT等)；具备驾驶技能(C1驾照)者优先。', '浙江友华是一家专业从事通信技术研究与应用的高新技术企业，注册资本1.5亿元。公司总部位于杭州，在全国设立6个事业部、4个区域公司、6个省级项目部。浙江友华致力于为客户提供通信网络规划设计、通信建筑设计、数据中心建设、行业应用及系统集成等服务，具有电子通信广电行业通信工程及通信铁塔设计专业甲级资质，建筑行业乙级设计资质、勘察乙级资质、通信工程监理甲级资质、市政房建电力工程监理乙级资质，具备全产业链综合服务能力。公司以“仁恭信友，行实德华”为核心理念，顺应时代潮流，实现社会价值；满足客户需求，实现客户价值；帮助员工成长，实现人生价值。展望未来，全体友华人矢志不移，努力成为优秀的通信网络与信息技术服务供应商。欢迎您了解友华、走进友华，体验并共同建设友华“亲如一家”的文化，与友华共同发展进步！', 'https://www.zhaopin.com/jobdetail/CC284529010J40759264301.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4494, 'BD经理', '广东爱才人力资源有限公司', '7月22日', '9000-15000元', '哈尔滨-道里区', '人力资源服务,货运/物流/仓储,零售/批发,培训/辅导服务', '10000人以上', '未融资', 'CCL1283957410J40793593305', '工作内容：<br>地推找商家入驻抖音做抖音团购和外卖业务<br>1、负责餐饮外卖业务新商户开拓，与商户进行治谈合作与签约，跟进上线流程;<br>2、根据商户需求制定合理的运营方案，提供促销活动、外卖品设计与运营支持，做好交易额提升优化;<br>3、及时处理商户及用户问题与投诉，跟进问题解决，提高商家和消费者满意度；<br>薪资架构：无责底薪5~6k+提成（多的7-8万，少的几千）<br>福利待遇：入职及缴纳六险一金按照当地最高比例12%进行缴纳<br>工作时间：10:00-7:00 周末双休，节假日均正常休息<br>补贴：包三餐，交通补助每月500(实报实销）', '爱才人力资源集团成立于2016年1月，总部位于中国杭州国际人力资源服务产业园11-15层，是“浙江省人力资源服务协会理事单位”、“杭州市人力资源促进会理事单位”、“浙江中小企业协会理事单位”。荣获2018《中国HR好服务》TOP30优秀服务机构、浙江省人力资源服务企业信用等级“四星级企业”。', 'https://www.zhaopin.com/jobdetail/CCL1283957410J40793593305.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4495, '项目招投标', '安徽优采全过程工程咨询有限公司', '7月24日', '4000-6000元', '合肥-蜀山区', '咨询服务', '20-99人', NULL, 'CCL1463384610J40825497208', '岗位职责： 1、负责采购项目的方案编制、招标文件编制、组织开标评标； 2、负责招投标信息平台的操作等相关事宜； 3、跟进招标过程，做好甲方和政府的沟通工作； 4、公司安排的其它事项。 任职资格： 1、本科及以上学历，男女不限； 2、有良好的沟通协调能力，做事认真负责。3、大小周制度。4、接受优秀应届生5、非统招，大专以下勿扰！！！', NULL, 'https://www.zhaopin.com/jobdetail/CCL1463384610J40825497208.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4496, '储备经理人', '内蒙古润隆餐饮管理有限公司', '7月26日', '4000-5000元', '西宁-城西区', '餐饮服务,餐饮服务', '1000-9999人', '未融资', 'CC500969620J40758931909', '工作职责:<br>1.从实地训练、区域管理及楼面管理，学习基本的餐厅营运知识 ；<br>2.管理指定值班的员工、产品及设备，以达到最佳的品质、服务、清洁及物超所值；<br>3.逐项学习财务管理，成本控制，生产订货，服务管理，人力资源管理等运营管理知识体系。<br>任职要求 ：<br>1.热爱顾客服务工作并有意愿成为领导者 ；<br>2.喜欢快节奏的工作并能适应轮班 ；<br>3.可提供任意上班时间段；<br>薪资福利<br>1.全职员工缴纳五险一金、提供带薪年休；<br>2. 享受专业的、一对一的带训；<br>3.国家法定假日三倍工资及商业保险；<br>4.免费餐饮及员工打折卡；<br>5.节日关怀及日常激励活动；', '麦当劳是全球零售食品服务业龙头，世界500强。截止2019年底，全球有超过38,000家麦当劳餐厅。麦当劳在BrandZ全球最具价值品牌排行榜连续十年排名前10名，是全球排名最前的餐饮服务企业，品牌价值超过1293亿美金。麦当劳中国第十一次获得“中国杰出雇主”并连续第八次获得怡安翰威特“中国最佳雇主“称号。内蒙古润隆餐饮管理有限公司成立于2012年，目前已在呼和浩特、包头、鄂尔多斯、通辽、满洲里、赤峰、锡林浩特、海拉尔、乌海、乌兰浩特、乌兰察布、巴彦淖尔等地开设麦当劳餐厅64家。', 'https://www.zhaopin.com/jobdetail/CC500969620J40758931909.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4497, '招聘专员/助理', '北京九州华海科技有限公司', '7月7日', '1-2万·13薪', '北京-通州区', '汽车研发/制造,汽车研发/制造,汽车零部件', '20-99人', '未融资', 'CC446840320J40798226508', '一、岗位职责<br>1、协助人事经理制定和执行招聘计划，确保招聘流程的顺利进行。<br>2、协助组织和安排面试，包括面试场地的准备、面试官的协调等。<br>3、跟踪和记录招聘过程中的各项数据。<br>4、协助处理候选人的入职手续，包括背景调查、录用通知等。<br>5、收集和分析招聘数据，定期生成招聘报告，为管理层提供决策支持。<br>6、跟踪招聘关键指标，如招聘周期、招聘成本、录用率等，提出改进措施。<br>7、完成上级领导交办的其他任务。<br>任职要求：<br>1、本科及以上学历，人力资源、管理学或相关专业，熟悉招聘流程和相关法律法规。<br>2、1-3年技术类招聘相关工作经验，有猎头经验者优先。<br>3、熟练使用招聘管理系统，良好的沟通能力和人际交往能力，能够与候选人和各部门有效沟通。<br>4、较强的组织能力和时间管理能力，能够同时处理多个招聘任务。<br>5、熟练使用办公软件（如Word、Excel、PowerPoint等）。', '北京九州华海科技有限公司是一家专业提供电控系统解决方案的高科技公司，公司成立于2011年。公司致力于为汽车、机械、船舶、航空、教育等行业的用户提供适用于电控系统完整生命周期的解决方案。采用华海科技所提供的解决方案，用户可以快速形成电控开发的能力，显著提高开发效率并大幅降低成本。公司立足于自主研发，在嵌入式开发系统、新能源汽车电控、先进动力总成控制、无人驾驶等领域拥有多项核心自主知识产权。公司拥有10年以上经验的技术研发团队，自成立以来，专注于世界领先的电控开发技术，与清华大学、北京工业大学、江苏大学等知名高校，以及美国RealtimeTechnologies Inc.等国际领先公司深入合作。公司自成立以来，专注于电控开发技术，秉承卓越和创新的精神，凭借不断提升的开发工具、全方位的技术服务与领先的解决方案，赢得了一汽、三一重工、麦格纳斯太尔等客户的一致好评，产品出口远销伊朗等国。我们专注于技术发展和创新，追求卓越的用户体验，倡导平等沟通和团队协作。本公司重点招聘活力充沛、勤奋而有才华的年轻人，目前汇集了来自清华、北理工等国内知名高校毕业生。欢迎加入这样一个年轻富有活力的团队，一同迎接中国汽车行业的发展和挑战，实现自我价值，共同创造美好的未来。', 'https://www.zhaopin.com/jobdetail/CC446840320J40798226508.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4498, '运营助理/专员', '四川恒通动保生物科技有限公司', '7月25日', '4000-6000元·13薪', '内江-市中区', '医药制造,医疗设备/器械,卫生服务,农/林/牧/渔', '500-999人', '未融资', 'CC627667930J40489199003', '岗位职责：<br>1、新门店的开业支持，组织加盟商进行开业前的培训辅导。<br>2、负责组织策划新店开业活动、引流拓客方案，完成开业活动期间公司下达的进货量指标。<br>3、负责策划新店开业的宣传方案，并对方案执行情况进行全程跟进。<br>4、协助门店在收银系统后台做好商品价格调整、品类变更和营销策略调整。<br>5、统计所辖门店的进销存数据，分析门店异常经营情况并及时反馈。<br>6、协助所辖门店做好会员档案管理，定时统计、汇总各门店会员消费信息。<br>7、负责协助加盟商做好门店运营管理，对公司下达的门店月进货量指标负责。<br>8、负责所辖门店的每日货品供应管理，保障门店每日货品准时、准确送达。<br>9、定期对所辖门店进行检查，确保公司要求的各项标准、流程、制度全面有效落地。<br>10、定期对加盟商进行沟通交流，及时了解加盟商运营情况。<br>11、在公司要求的传统节假日期间，统一对所辖门店进行营销活动策划并协助门店执行。<br>任职要求：<br>1、熟练操作office等办公软件<br>2、熟悉市场营销等专业知识和生鲜食品等行业知识<br>3、具备较强的沟通能力和组织协调能力<br>4、两年及以上同行业或相关行业连锁店运营等相关工作经验优先考虑<br>5、可接受相关专业应届大学生', '四川恒通专注于提高动物健康水平，致力促进人类、动物、环境的和谐发展，以“呵护动物健康，共享美好生活”为企业使命，努力打造“畜牧业生产资料及综合信息服务平台”，恒通兽药以其专业技术和产品为各种疾病提供诊疗方案；恒通动保凭借“治未病”现代养殖技术提供规模化养殖的全程“治未病”服务方案；恒通兴牧提供疫苗、养殖设施设备、医疗器械、检验仪器及相关配套服务；2009年评为中国兽药生产企业50强、兽药制剂类30强，是国家高新技术企业、四川省动物保健品协会副会长、中国畜牧兽医学会动物药品分会常务理事长、中兽药技术创新联盟常务理事长单位。公司不断强化企业核心竞争力，以中科院博士为核心，与学术研究、科研机构和国际同行、专业院校合作成立“恒通技术研发中心”，开展独立研发、技术转让，持续改进产品品质和生产工艺，提高产品科技含量；树立了“恒通兽药，贵在品质，节约成本”的品牌形象，拥有国家发明、实用新型专利20余项，“恒通”商标被评为四川省“著名商标”、“恒通动保”评为“中国动物保健影响力品牌”。公司拥有现代化的生产设备、完善的质量管理体系、专业化的生产和质量管理人员、精密的检验仪器以及严格的GMP管理规范，实施并通过CQC国际质量管理体系，保障产品品质过硬，已连续三年被农业部列入地方免检产品企业。按照中国兽药GMP新版标准正在建设的恒通动保新工厂，作为2016年四川省重要产业扩能项目，2017年竣工后将通过欧盟GMP、美国FDA认证，成为行业升级的示范样板工程。公司用富于中国特色的“像军队、像学校、像家庭”的企业文化打造爱岗敬业、积极向上、执行力强的管理、技术、营销服务团队，增强企业生命力、凝聚力；在全国各地广泛开展公益性“MSY养殖降本增效”技术交流活动，积极传播“治未病”科学养殖理念和养殖技术，“快乐养殖工程”荣获中国动物保健“双效方案”；在养殖规模化、专业化，兽药市场规范化、管理法制化的新常态下，作为中国“MSY25养猪增效工程”的首倡者，公司集合国际内有效科研资源,携手广大养殖业主、养殖经理人全面提升投资价值和管理价值,提高养殖整体效益共同努力，推进动物健康、食品安全和人类健康事业。', 'https://www.zhaopin.com/jobdetail/CC627667930J40489199003.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4499, '电话销售', '博岳通信', '6月15日', '8000-12000元', '石家庄-裕华区', '运营商/增值服务,IT服务,通信/网络设备', '10000人以上', NULL, 'CC351377410J40716585501', '【工作时间】<br>1. 9:00-19:00 周末双休，法定节假日休假，月收入7-12k,奖金激励完善<br>2. 工资待遇底薪加提成绩效平均税前工资8k+;<br>3. 企业背景强入职正常缴纳五险一金<br>4.工作地址:博岳大厦6楼<br>5.学历:不限 年龄:38以下<br>想付出跟回报成正比的，想在大平台长期发展的，挣钱欲望强的提前预约联系我。<br>工作内容：<br>1、通过企业系统对精准客户进行外呼沟通贷款营销工作。<br>(都是精准客户沟通)对小微经营、个人消费的客群完成销售工作;<br>任职要求:<br>1、具有信用卡催收、贷款或者电话销售等相关工作经验者优先(具有外呼性质);企业背景强入职正常缴纳五险一金,付出跟回报成正比，带薪培训，婚假，产假，团建活动，月聚餐，节日福利，带薪年假，生日会等。<br>', '河北博岳通信技术股份有限公司是一家大型的电子商务、呼叫中心运营及信息服务供应商，主要从事大数据建模/分析/应用、呼叫中心运营、运营商业务渠道、云服务、网络与信息服务业务。专注于为运营商、电子商务、金融、互联网企业和中小企业提供端到端的运营及服务解决方案。公司现有员工15000名，拥有运营坐席超过16000个，目前在北京、河北、四川、湖南、江西、辽宁、福建、宁夏、贵州、浙江、陕西等多个省市设有分公司和办事处。在大数据应用和呼叫中心运营领域，博岳股份与全国十几个省市通信运营商客户进行了全面合作,包括北京移动、中国移动咪咕公司音乐基地、咪咕动漫、四川移动、河北移动、河北铁通、宁夏移动、卓望信息、辽宁移动、江西移动、陕西移动、湖南电信、贵州联通、虚商迪信通；博岳股份与十几家互联网企业在运营和服务领域进行全方位的合作，包括小米科技、去哪网、多点生活、牛电科技、海选网运营支撑服务；博岳与互联网金融九鼎投资-借贷宝进行了全方位的战略合作，包括人人行客服、人人行催收、人人推和研发合作。博岳股份全面服务于通信运营商、金融、电商及互联网企业，服务用户超过5亿。在云服务领域，基于互联网模式建立了端到端的云客服平台，向互联网企业和各中小企业提供系统平台、数据库、数据建模及分析、物理场所、台席、人员及培训等端到端解决方案；为互联网企业和各中小企业提供快速、便捷、性价比高的优质服务。同时公司根据客户的需求，为客户设计完整的呼叫中心解决方案，并负责呼叫中心的建设、运营与维护，承接客户的对外联络、咨询、投诉、问卷调查、营销、客服等各项工作。作为河北省高科技企业，博岳股份于2016年3月份成功挂牌新三板。公司具备工信部颁发的“中华人民共和国增值电信业务经营许可证（全国呼叫中心业务许可证、河北省因特网信息服务业务许可证）”、“通信信息网络系统集成乙级”及“道路运输经营许可证”等资质，并且通过了ISO9001质量管理体系和ISO14001环境管理体系等权威认证。博岳股份立志发展成为业界一流的信息服务和网络服务提供商，博岳股份全面向世界优秀企业学习。博岳股份吸纳业界优秀人才，聚焦客户、聚焦业务，实现平台化和规模化的管理和运作，公司将秉承“以客户为中心、以贡献者为本、持续艰苦奋斗”的企业核心价值理念，我们相信通过全体员工的不懈努力和追求，一定能够为客户提供最好的解决方案和最优质的服务，并为客户实现商业成功!', 'https://www.zhaopin.com/jobdetail/CC351377410J40716585501.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4500, '总助/CEO助理/董事长助理', '大连金乌扶摇科技有限公司', '7月16日', '6000-8000元', '南京-建邺区', '咨询服务', '20-99人', NULL, 'CCL1495385730J40756685009', '岗位内容：<br>1. 协助公司高层撰写各类文件、报告、决策方案和会议纪要等，负责文件的整理、归档和保管；<br>2. 安排高层的行程、安排会议，协调公司各个部门之间的工作；<br>3. 对公司运营情况及时跟进和提出意见，帮助高层解决问题；<br>4. 协助高层处理公司日常事务，如请假、差旅等；<br>5. 接待客户及来访者，维护公司形象。', NULL, 'https://www.zhaopin.com/jobdetail/CCL1495385730J40756685009.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4501, '法务专员/助理', '焦作友商共联网络科技有限公司', '7月22日', '3000-6000元', '焦作-武陟县', '电子商务', '20-99人', NULL, 'CCL1487562820J40718742210', '法学相关专业，熟悉公司法、知识产权法等相关法律法规，具备合同、诉状等的起草、审查和修改的能力，具备处理诉讼、仲裁等法律纠纷的经验，以及非诉事务的处理能力。从事过知识产权相关业务的优先。', NULL, 'https://www.zhaopin.com/jobdetail/CCL1487562820J40718742210.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4502, '质检员', '江门市希音物流供应链有限公司', '4月18日', '1-1.2万', '佛山-南海区', '货运/物流/仓储', '300-499人', NULL, 'CCL1490664250J40798461508', '7000-8000月的工资等你来拿<br>1.工作主要负责衣服包包鞋子零食化妆品打包分拣之类的<br>工作岗位:上架、分拣、扫描、盘点、打包、质控、退货等<br>2.男女不限，18-45岁，<br>3.工作时间8-10小时，长白班岗位自选两班倒，15天倒一次班，有适应时间<br>4.正式工薪酬福利:计间工资。多劳多得<br>福利待遇：底薪+绩效考核+综合计件+全勤+质量考核+夜班补贴+餐补+高温补贴<br>5、提供食宿，有空调，热水器<br>6、购买五险一金 ，月休息4天，现场排休', NULL, 'https://www.zhaopin.com/jobdetail/CCL1490664250J40798461508.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4503, '项目招投标', '拓达(山东)新材料科技产业集团有限公司', '2025-07-28 00:00:02', '5000-8000元', '济南-历下区', '建材', '100-299人', '未融资', 'CC409302610J40582660206', '公司简介：  成立于2010年，主做灌浆料、防水材料、地坪材料等一系列建筑材料，研发生产销售一体，现已和各大国家单位合作。济南是总部，目前全国有七大工厂和其他分部；  <br>     一、工作内容：', '济南拓达建材有限公司成立于2010年，总公司的办公地址位于济南市高新区三庆联合财富中心1号楼15层，工厂坐落于济南市历城区王舍人工业园，是一家集科研、生产、销售为一体的新型建材企业，公司主要生产高强无收缩灌浆料、特种砂浆以及各种加固修补材料，公司自成立至今已实现材料总产值5000万元，并在广州、江西、河北、山西及山东省内各大城市设立分公司，产品遍布全国各地。企业先后服务于中石油、中石化、中交三航局中交二航局、中铁四局、中铁十四局等多家大型知名企业，产品受到客户的一致好评。公司生产的各类高强无收缩灌浆料具有高强、微膨胀、大流态等特点，其中超早强型灌浆料8h强度>40MPa,早强超大流动度灌浆料的流动度更是达到了420mm，这在灌浆料行业无疑是一个创举，同时也为有特殊需求灌浆料的客户有了强有力的技术保障；拓达TD-C2预应力管（孔）道压浆剂完全满足新桥规“JTG/TF50-2011《公路桥涵施工技术规范》”，具有流动性好、微膨胀、零泌水、耐久性好、高充盈性等优点。拓达建材一直以来坚持以创办国际一流的企业为目标。坚持“哪里有加固材料哪里就有拓达”的原则，以优质的原材料、先进的生产设备、合理的价格、高品质售后服务、为顾客提供各类卓越的工程加固修补产品。同时公司遵循市场规律，不断完善企业的经营管理和优化产品的制作工艺，致力于创建具有自身特色的研产销体系......“做最优秀的加固材料生产企业”是公司始终不渝的目标，相信在中国的加固行业一定会留下灿烂的一笔。公司一直秉承着相信人才，重视人才，培养人才的战略方针，注重人才的选拨培养，拥有着一支优秀的销售团队，提供免费的在职培训，各种晋升机制，为年轻人创造一个广阔的发展平台。年轻人如果你觉得自己很优秀，全世界都可以在你的脚下，那么拓达在这里等你，等你去撬动地球~~~', 'https://www.zhaopin.com/jobdetail/CC409302610J40582660206.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4504, '电话客服', '中国大地财产保险股份有限公司', '8月2日', '4000-8000元', '茂名-茂南区', '保险', '10000人以上', NULL, 'CC145756070J40527019212', '一、工作内容：<br>公司提供车险即将到期的客户名单，通过电话和网络的形式通知车主车险即将到期，将车险的优势介绍给客户, 引导购买就有提成（纯办公室工作环境，无需跑业务,无需自己开发客户，无需轮班）<br>二、任职资格：<br>1、20到40周岁（条件优秀者可放宽），态度端正，品行良好；<br>2、公司注重能力，条件符合中专或高中以上学历；<br>3. 普通话标准，具有一定的表达沟通能力，<br>4. 熟悉电脑 基本操作技能，打字每分钟20字以上；<br>5. 拥有勇于挑战高薪的野心，服从管理。<br>三、工作时间:<br>上午：8：40－12：00 下午：13：40－18：30，月休5天，国家规定节假日全休，每年5-15天的带薪年假。<br>四、福利待遇：<br>1.综合薪资（2700-4700）+业绩提奖（3.4%-30%）+年终奖+销售激励+其他福利（司龄津贴等），收入上不封顶，多劳多得，平均工资6500以上，38%员工月薪过万。<br>2.入职签订正式劳动合同，即缴纳社保（社保包含：养老、医疗、失业、工伤、生育五项保障）<br>3. 员工福利：公司每月组织团建活动，聚餐、旅游、露营、运动会及电竞比赛等等。<br>4.. 每月定期的各种员工激励方案（实物，现金，培训等）<br>5. 提供完善的培训机制：新人培训、岗前培训、在职培训、晋升培训、学历晋升培训，让员工可以充分学习各项工作技能，提升综合能力。<br>6. 返乡政策：入职三个月且达到中级，可优先回老家的大地保险公司任职', '中国大地财产保险股份有限公司（简称“中国大地保险”）于2003年10月20日在上海成立，是经国务院同意，中国保监会批准成立的全国性财产保险公司，是中国再保险（集团）股份有限公司（股票代码：01508.HK）旗下唯一的财险直保公司，注册资本金151.15918986亿元。中国大地保险已设立分公司39家，营业部1家，机构总数超2100家，营业机构覆盖全国各个省份，系统员工人数超5.3万人。“十三五”期间，中国大地保险以“三新三聚焦”战略为引领，坚定推进“三化”能力建设，走“大地特色”的发展道路，保费复合年化增长率达到12.5%，行业地位及市场影响力得到进一步提升。2021年，公司实现保费收入435亿元，业务规模位列全国财产保险业第六位。【承担社会责任】2017年以来，中国大地保险为青海省循化县贫困群众提供保险兜底保障，累计承保风险超90亿元。自2019年起，中国大地保险积极致力于将青海循化的防返贫模式经验推广至全国，为更多的脱贫地区解决因病、因灾、因意外返贫的问题。截止2021年底，已在全国28个省（自治区、直辖市）、203个县（市）、666个乡（镇）落地，为已脱贫地区超408万群众提供了“大地防返贫”风险保障。2021年7月，面对河南暴雨灾情，中国大地保险抽调精干人员组建抢险救灾突击队，为客户提供救援服务，并开辟绿色通道、减免理赔单证，快速支付赔款近亿元。【严守风险底线】中国大地保险认真落实中央关于打好防范化解金融风险攻坚战的战略部署；坚持依法合规经营，稳健均衡发展；持续完善全面风险管理体系建设，偿付能力水平充足，各类风险状况整体可控。2014年至2021年，中国大地保险连续八年获得贝氏评级公司（A.M. Best Co.）“A（优秀）”财务实力评级（FSR）和“a”发行人信用评级（ICR）。【构筑专业优势】中国大地保险是核共体、集成电路共同体成员，中保协、上海航保协会会员单位，拥有一支高素质的专业人才队伍。凭借专业的技术优势、完善的服务网络、完备的产品体系及独立的信息系统支持，中国大地保险累计已为数十家央企客户提供风险保障服务；在农业保险方面，围绕地方特色农产品保险、天气指数保险、价格指数保险、农产品“保险+期货”、收入保险、农业巨灾、碳汇指数以及涉农保险等创新领域，累计开发400多款产品，32家分公司已取得农业保险经营资格，并在全国多地区开展农业保险业务；在健康保险方面，通过与政府医保、民政等部门合作开办各类补充医疗保险业务，与大型企事业单位合作开办员工普通或中高端健康险业务，已累计在全国各地服务人群超1.5亿人次；在安全生产领域，通过“科技+服务”手段，近三年累计为近15万家企业提供超8500亿元的风险保障；在IDI领域，公司参与行业风控标准及规范编制，已在全国多地取得主承资格，累计承保项目超800个，为建设方提供风险保障超600亿元。【打造特色服务】中国大地保险秉持“以客户为中心”的服务理念，致力于服务创新，“大地礼赔”车险理赔品牌服务入选《中国保险报》2019年度中国保险“十大服务创新”项目。公司连续多年获得中国银保监会保险公司服务评价A类评级，2021年保险（车险业务）服务质量指数位列保费前十大公司前三名。“大地礼赔”服务品牌，以礼为核心，以科技和人文为驱动，致力打造简单、人性、有温度的理赔服务。自2019年至今，中国大地保险已连续4年开展理赔“春运暖心”和“高考护航”专项系列服务活动，得到社会广泛好评和客户的一致认可。【推进科技建设】中国大地保险加强科技建设，全面推进线上化、数字化、智能化“三化”项目落地，在经营管理领域顺利上线筋斗云新一代业务核心系统；在客户服务领域创新打造超级APP；在销售赋能领域成功落地“大地行”APP；在财务服务领域成功实现RPA机器人流程自动化，通过科技赋能推动发展模式转型。【强化品牌建设】中国大地保险持续强化品牌建设，连续入选“亚洲品牌500强”“中国企业500强”“上海企业100强”，并先后荣获“2018金牌保险服务方舟奖”“2019金质保险品牌方舟奖”“2020高质量发展保险公司方舟奖”“2020中国保险业抗疫先进事迹方舟奖”“2021优秀社会责任保险公司方舟奖”等奖项，累计荣膺各类品牌荣誉70余项，品牌影响力持续提升，赢得市场广泛认可。进入“十四五”，中国大地保险将坚定不移推进“三新三聚焦”核心战略，坚持“党建引领、回归本源、守正创新、合规经营、科技赋能”的战略方向，守牢风险合规底线，夯实专业经营基础，全面深化结构调整，构建综合经营优势，协调推进生态布局，加快商业模式转型，推动公司实现高质量发展。', 'https://www.zhaopin.com/jobdetail/CC145756070J40527019212.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4505, '项目招投标', '北京筑鹏工程咨询有限公司', '4月7日', '5000-9000元', '北京-大兴区', '咨询服务,咨询服务,专业技术服务,房地产开发', '20-99人', '未融资', 'CC719320430J40786711408', '岗位内容：<br>1、根据法律法规协助经理跟进项目全流程，编制招标文件、 发布招标公告、参与项目开标、评标，发布中标通知书等全过程；  2、准备及提供文件中所需各类资料、信息，及时的与甲方、投标人、协调公司相关事务；', '北京筑鹏工程咨询有限公司是一家专业从事工程咨询、造价管理服务的机构。公司主要为客户提供造价咨询、项目管理、工料测量、成本控制、指标分析、招标代理等服务。公司以专业技能和团队精神为本，竭力为客户提供最优质的服务。我们将以诚信赢得客户的信任，以服务赢得客户的合作，追求与客户建立积极的、长远的战略合作伙伴关系，谋求共同、持续、快速、稳定的发展。公司根据客户的要求，恪守职业道德，严格按照合同的约定，实事求是的完成约定工作。真正站在客户的角度解决问题，做到不推诿，不延迟。专业化、高效率是我们服务的一贯方针，根据不同客户的需求，制定有针对性的服务方案，让客户体验到品质服务的魅力所在。我们注重文化的开放性和多元化，积极为员工营造一个能够学习、提升、发挥、共享及完善自身的工作环境。我们追求和每一个客户和员工建立积极、稳固、长远的合作伙伴关系，共同发展，共同成功。公司注重企业文化的开放性和多元性。公司既要求员工保持严谨、踏实、专业的工作作风，也鼓励员工发挥个人特长，拓展个人兴趣爱好。', 'https://www.zhaopin.com/jobdetail/CC719320430J40786711408.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4506, '销售工程师', '唯万科技有限公司', '7月23日', '7000-10000元', '嘉兴-嘉善县', '橡胶和塑料制品,专业技术服务', '100-299人', NULL, 'CCL1246442380J40760635210', '岗位职责：<br>1. 维护和老客户的关系并建立良好的业务联系，定期给客户最新的产品信息及技术资料；<br>2.向销售经理反馈潜在客户的信息；<br>3.接受客户对产品的技术询问，尽量向客户提供完善的售前技术支持；<br>4.定期编制销售业绩报告及销售计划给销售经理<br>岗位要求：<br>1. 大学本科或以上学历，工科类专业背景的应届毕业生，或者有2-3年相关销售工作经验。<br>2.有气动行业经验优先考虑。<br>3.具有较强的工作上进心及责任感，具有一定的社交沟通能力，有良好的团体合作精神。<br>4.能适应出差；', '唯万科技有限公司（上海唯万科技股份有限公司全资子公司），是一家专业的密封方案供应商，集材料开发，产品设计与生产、方案定制和销售支持于一身，为客户提供全面的密封系统解决方案。针对密封行业的应用特点专注于高分子材料基础理论与实践的研究，自主研发聚氨酯材料TecThane系列开发出一系列适用于液压、气动和相关液力系统的密封件，拥有完整自主知识产权，为包括工程机械、石油化工、汽车、煤机等行业的众多合作伙伴。', 'https://www.zhaopin.com/jobdetail/CCL1246442380J40760635210.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4507, '内容审核', '成都世纪天语科技有限公司', '7月24日', '3000-5000元', '成都-青羊区', '电子商务,互联网', '1000-9999人', '未融资', 'CC694708220J40697748004', '岗位是负责dy平台上的用户审核，室内办公，不销售！不销售！不销售！话<br>接受不经验——接受无经验<br>无销售——无销售——无销售<br>工作时间：8小时工作制，排休<br>五险一金，带薪培训，生日福利等等', '成都世纪天语科技有限公司是国内领先的呼叫中心专业服务提供商。成都世纪天语科技有限公司是一家由具有成熟的、多行业的呼叫中心项目运营管理经验的业内专家组建的呼叫中心运营管理外包公司。在呼叫中心业界具有很好的口碑和品牌形象，具有广泛及深厚的客户资源。世纪天语与国内优秀的通信企业进行战略合作，共同为中国乃至全球外包呼叫客户提供更专业的服务，促进与合作伙伴的品牌和服务在中国外包市场中的影响力和渗透力。', 'https://www.zhaopin.com/jobdetail/CC694708220J40697748004.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4508, '储备经理人', '成都嘉创联和包装制品有限公司', '10月11日', '5000-10000元', '成都-大邑县', '印刷/包装/造纸', '100-299人', '未融资', 'CCL1436492110J40572104312', '岗位要求：<br>1、公司高管与应聘者面谈发现个人特点后从管理、技术两个发展方向培养，给予学习成长锻炼机会，计划3-5年成为公司中高层核心管理人才；<br>2、多部门轮岗实训学习；<br>3、辅助各部门主管处理日常资料、文件；<br>4、在上级的领导和监督下定期完成量化的工作要求，并能独立处理和解决所负责的任务；<br>5、专业免费的培训，不断提升专业知识和技能；<br>6、公平公正的晋升空间，广阔的发展舞台。<br>任职要求：<br>1、专科以上学历，应届或有短期工作经验优先。<br>2、使用办公软件Word，excel、PPT、CAD优先。<br>3、为人诚实，人品正直，做事踏实，主动性强，具有良好的沟通能力；<br>4、愿意从基层岗位做起，具备较强的自我驱动力；<br>5、有志于在印刷/包装行业长期发展，有一定的抗压能力。', '专业酒类精品礼盒生产工⺁，主要服务国内知名一、二线酒企及国内酒类流通大商，公司投资有现代化标准工厂，引进业内先进的进口罗兰8色印刷机组，国内先进的全自动覆膜、全自动烫金、全自动压纹、全自动模切及配套精品盒生产设备，并配置有精品盒组装线7条。公司为员工提供良好的晋升通道及完善的薪酬福利保障制度，尤其是对专业的技术人才提供更多的激励机制促进共同成长。', 'https://www.zhaopin.com/jobdetail/CCL1436492110J40572104312.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4509, '律师', '四川督政律师事务所', '3月7日', '6000-10000元', '成都-锦江区', '法律服务', '20-99人', NULL, 'CC883722750J40722265310', '我们正在寻找一位充满激情、有责任心的事务所律师伙伴，一起为客户提供卓越的法律服务！<br>你的工作将包括法律咨询、合同起草、诉讼代理等，让我们共同为客户解决法律问题。<br>如果你具备以下条件，就赶快加入我们吧！<br>1. 法学本科及以上学历，取得律师执业资格证书；<br>2. 有律师工作经验者优先，但不是必须；<br>3. 善于沟通，能与客户和团队成员愉快合作；<br>4. 责任心强，注重细节，热爱团队工作；<br>5. 熟悉民商事法律法规，能独立处理法律事务。<br>我们期待你的加入，一起为客户提供最佳的法律服务！', '四川督政律师事务所简介本所是经中华人民共和国司法部核准并经四川省司法厅批准成立的一家合伙制综合性大型律师事务所。我们经过多年的发展，现有专家顾问、执业律师、实习律师、行政人员70余人。合伙人普遍具有10年、20年以上执业经历，核心律师团队大部分毕业于北京大学、中国政法大学、西南政法大学、四川大学、西南财经大学等高等学府，全部具有本科以上学历，其中相当一部分律师具有博士、硕士学历，还有相当一部分律师曾担任过银行高管、政府政策法规部门负责人、中级法院基层法院庭长审判长、高校法学教师，具有深厚的法学理论功底、丰富的法律实践经验和社会资源。我所律师忠于宪法，忠于祖国，忠于人民，维护当事人合法权益，维护法律正确实施，维护社会公平正义，恪尽职责，勤勉敬业。曾数百次为困难群众无偿提供法律帮助，多次空军、陆军、武警、军分区，政府机关（包括公安机关）、社会团体提供优质法律服务。为此，我所及律师曾多次受到省、市、区党委、政府、司法行政主管部门、律师协会的好评。我所设置有法律顾问、刑事辩护、公司与证券、金融保险、房地产建筑、知识产权、投资与商务、民事侵权、涉外及行政诉讼等十个专业法律事务部。本所创新的管理模式，不同于通常的部门化管理模式，而是根据事务所执业律师的特长与专研方向划分不同的专业法律服务团队，除了从事该专业领域的法律咨询、法律顾问、诉讼代理等基础法律服务外，更在新技术应用的支持下，为委托人提供行业差异化、内容标准化、互动常态化的优质法律服务。同时，本所律师始终关注行业热点和委托人需求，不断提升自身的业务素质和实践经验，适时调整法律服务团队的设置，并始终贯彻统一的服务质量体系与行为监督体系，以确保切实维护当事人合法权益。我所在多年与企业合作过程中，我们观察到企业在法律需求之外，还存在有资金、人力资源、合理避税等多层次需求却因信息缺乏对称无法及时有效得到响应。因此，本所整合社会资源，联合成都众多成熟的资金服务机构、社会保险代理机构、税务师事务所等中介服务机构，组成庞大的综合服务体系，积极为委托人无偿推荐，实现为委托人的服务需求对接，以此让委托人在接受本所优质的法律服务的同时获得更多的增值服务。我所服务范围涵盖民事、商事、行政、刑事、金融证券、保险、房地产、工程建设、股份公司上市、企业改制、知识产权、国内外贸易、劳动争议等法律服务领域。特别在刑事辩护、民事诉讼、破产重整、项目投资、股份公司上市、房地产、金融证券、国内外贸易等方面拥有丰富的执业经验和广博的社会资源。我所及律师先后为上百家政府机关、军事机关、金融机构、国有企业、外资企业、大中型民营企业、商会、协会等提供法律服务，其中包括但不限：金牛区政府部分职能部门、武侯区政府部分职能部门、眉山市政府、东坡区政府、成都军区联勤部、西部战区空军司令部、内江军分区、成都泸州商会、成都鞋业商会、成都纳溪商会、成都宜宾商会、成都文氏集团、四川华西集团、云图控股（深交所上市公司）、四川国胜建设公司、长城资产管理公司成都办事处、四川港蓉集团、日本小松投资（中国）有限公司、成都古玩城、四川元俊建设机械有限公司、成都自来水公司（沃特公司）、成都信德房产集团、四川三通集团、四川三佳房产开发集团、黄浦小额贷款股份公司、鑫诚鑫融资担保公司、四川恒瑞担保公司、文氏助强担保公司、成都世都担保公司、成都天银制药公司、青岛啤酒西南集团、黄浦集团、中国农业银行四川省分行、中国银行四川省分行、四川大晶公司、四川高建园林建设有限公司广州星火（集团）广告公司、四川睿博工程建筑公司、四川七捷建筑劳务公司、四川嘉祥建筑公司、四川合园水利工程公司、四川高建园林建设有限公司、四川山江建工集团有限公司、喜力啤酒（岳阳）有限公司西南营销中心、四川科泰水利水电建设公司、四川大榆旅游开发有限公司、四川西行驿站文化传播公司、四川瑞辉建设工程公司、四川泓正建筑劳务公司、成都伊藤洋华堂、四川金雨升家具有限公司、成都奇香居现代农业有限公司、成都功夫香餐饮有限公司、成都佳运来公司、四川鼎鸿泰建筑工程公司、四川群雄建筑工程公司、中国文化信息协会文化创意传播工作委员会、四川省文艺传播促进会文化创意专业委员会、中国发布网成都发布中心、四川电视台《筑梦四川》电视栏目、重庆大学城市科技学院、四川天府新区成都管委会基层治理和社会事业局、四川省成都市天府新区万安街道佳苑社区居民委员会、成都中国青年旅行社、四川川投兴川建设有限责任公司、四川川投新区建设有限责任公司、四川川投怡心湖建设有限责任公司、成都易贷网金融信息服务有限责任公司、成都易捷金融服务外包有限公司、四川中商鼎元科技有限公司、信远瑞和（成都）股权投资基金管理有限公司、成都市乾华源资产管理公司、四川美逸佳实业有限公司、四川中联世际信息技术有限公司、四川范思文化传媒有限公司等。我们深知，律师虽不唯诉讼，但', 'https://www.zhaopin.com/jobdetail/CC883722750J40722265310.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4510, '风电工程师', '智网(天津)电力发展有限公司', '7月22日', '8000-12000元', '韶关-浈江区', '新能源', '300-499人', '不需要融资', 'CCL1492156440J40692302912', '一、招聘要求：<br>1、年龄18-28周岁，大专及以上学历（条件优越者可放宽要求）机电一体化、电气自动化等相关专业；<br>2、有进取心，学习能力强，适应能力强，能吃苦耐劳；<br>3、无犯罪不良记录，为人诚实守信，有责任心；  二、薪资待遇：     1、实习期间包食宿，综合补贴4500-5000元；（无证人员公司辅助考证）       2、转正第一阶段5500-6000，第二阶段6500-8000，第三阶段8500到12000，一个阶段一般为半年，经考核定工资，半年考核一次，涨幅300-1200不等（具体以单位实际发放为准），缴纳五险一金；', '本公司是专注于为个人和企业提供风电产业、新能源光伏值班员、电力运维员产业等方向指导服务和专业咨询。公司属天津西青区，与京津冀多家新能源电力企业有深度合作，累计外派人才达到2000人以上，与电力相关企业均有合作。为求职者提供专业求职咨询，为企业提供资源管理一站式专业平台。本公司一直坚持以“至诚、至善、至精、至美而努力奋斗”的企业宗旨，自公司创建以来一直致力于风电产业、新能源产业、光伏、电力等相关产业的人才引进工作，持续为电力行业赋能。企业服务一流，做大做强，成为企业发展的目标。', 'https://www.zhaopin.com/jobdetail/CCL1492156440J40692302912.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4511, '总助/CEO助理/董事长助理', '兴芯社(重庆)电子设备有限公司', '7月2日', '4000-8000元·13薪', '重庆-沙坪坝区', '电子/半导体/集成电路', '20-99人', NULL, 'CCL1471117030J40613179213', '1、协助总经理督促企业具体管理、经营工作的落实与执行；<br>2、协助总经理推动公司市场与销售业务，完成公司整体业务计划;<br>3、负责老客户的维护，进行商务洽谈，负责商务相关资料编制，包括:标书、报价书、项目计划书与合同等;<br>4、做好各类会议的组织工作和会议记录，做好决议、决定等文件的起草、发布;<br>5、负责领导或客户的接待、参观工作，协助总经理与供应商、友商等对外部门建立良好的合作关系;<br>6、完成公司领导交办的其他工作任务； 能够接受出差！', '兴芯社（重庆）电子设备有限公司成立于2023年，是一家以集成电路制造产业一体化技术服务型的高新技术企业。公司致力于推动半导体备件国产化研发。公司以客户需求为导向，公司业务包含代理国内外半导体主设备、翻新维修、耗材备件售卖等服务，产品应用领域包含扩散、光刻、刻蚀、薄膜、量测、清洗、射频、温控等。目前公司与多家品牌客户合作，产品功能全面，技术服务力量雄厚。兴芯社(重庆)科技有限公司将秉持“客户至上”的宗旨，加大研发和市场开发力度，坚定产品质量符合高标准的目标，为业界同仁提供更具竞争力的产品和服务。', 'https://www.zhaopin.com/jobdetail/CCL1471117030J40613179213.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4512, '律师', '河南合而泰律师事务所', '3月14日', '5000-10000元', '郑州-金水区', '法律服务', '20-99人', '不需要融资', 'CCL1357590030J40191980806', '愿意接受律所专业分工和培训，实习律师、授薪律师、提成律师、兼职律师、专业律师均可职位福利：绩效奖金、年终分红、弹性工作、节日福利、周末双休、不加班 <br>', '河南合而泰律师事务所专注于运用法律思维为当事人的商业投资、运营管理、争议提供合规及解决方案的高端法律服务机构。始终秉持专业、勤勉、高效、务实的服务宗旨，提供优质高效的法律服务，律所拥有良好的工作环境。新所伊始，万绪千头，人是根本，诚邀优秀的你加入', 'https://www.zhaopin.com/jobdetail/CCL1357590030J40191980806.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4513, '储备干部', '上海太屋网络科技有限公司', '2月8日', '9000-18000元', '上海-浦东新区', '房地产开发', '1000-9999人', '未融资', 'CC294547880J40359498603', '上海太平洋房屋介绍：', '太屋集团太屋集团始创于上海，是一个以“服务于人类居住”为核心的集团化企业。集团立足于房地产服务行业，历经30年发展，企业从房地产经纪、房地产咨询代理、商业招商等业务模块开始起步，逐步发展出资产管理、供应链金融、地产开发、互联网科技、职业教育等全新业务模块，伴随着20多家子公司和5个子品牌的相继成立，企业开始走向集团化发展的道路。太屋集团一直以来秉承“锐意进取，开拓创新”的发展理念，以品质服务赢得社会各界的广泛认可和客户的高度信赖。多品牌运营，创建地产生态圈太屋集团旗下拥有【太平洋】和【菁英】2大主力地产服务品牌，形成了太平洋经纪、太平洋房屋、太平洋置业、太平洋物业、菁英地产、菁英置业、菁英物业等众多房地产领域的独立企业；同时，还拥有【太屋网】、【菁铧】、【王典】这3大品牌，分别涉足地产网络科技、供应链金融、资产管理等相关行业；集团业务重心始终围绕着“居住产业”，希望通过多元化、产业化、平台化的发展，从房地产一级市场到三级市场，业务扩展到房地产行业全产业链，创建企业化的地产生态圈。【太平洋房屋】1994年成立于上海，集团于2004年接手该企业，成为集团旗下的主力企业之一。太平洋房屋作为上海房地产经纪行业协会的副会长企业之一，伴随着上海房地产市场的发展不断壮大。目前，公司业务范围覆盖全上海13个大区，拥有600家线下门店，10000名专业经纪人，年累积交易金额达5000多亿元，市场市占率稳居上海前二！公司历经30年的发展，100多个业界奖项与殊荣铸就了企业发展的历史，其中，上海市白玉兰纪念奖、蝉联18届“金桥奖”的殊荣等历史荣誉都是太屋人的骄傲。作为行业的领跑者和颠覆者，太屋集团整合旗下地产类各项业务，开创【太屋网】这一全新品牌，以“安心托付，幸福满屋”的经营理念，打造全产业链的房地产服务平台，让集团业务从线下向多元化、产业化、平台化方向发展……企业商学院，孵化企业人才团队随着集团业务规模不断扩大，企业的人才战略将成为决定集团未来发展的重要指标。2019年，上海太屋教育科技有限公司正式成立，我们集团的商学院——“太屋大学”也孕育而生。太屋大学，拥有强大的师资团队，以及由行业翘楚和权威专家组成的客座教授团体；建立了课程培训、名家讲堂、拓展训练、全球游学等科学化系统化的教学培训体系，针对行业的不同岗位和职务，开展有针对性的职业教育与培训，为企业人才赋能，共同创造价值。热心公益，企业向上向善的力量扶危渡厄，使命担当。太屋集团始终以“成就员工以成就企业，成就企业以回报社会”为愿景，时刻肩负着企业的社会责任，积极投身于公益事业。太平洋爱心基金、阳光之家公益活动、环卫工人“爱心接力站”、红马甲社区志愿者、免费社区便民服务、高考加油站、垃圾分类志愿互动……在此次新型管状病毒疫情的抗疫过程中，集团立即组织捐赠大量医疗物资，火线驰援抗战在一线的医疗单位。在点滴的生活中，太屋人始终用一颗向善之心，让世界多一份美好……太屋集团，一个有理想、有信仰、有温度、有情怀、有灵魂的集团企业，期待您的加入！', 'https://www.zhaopin.com/jobdetail/CC294547880J40359498603.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4514, '项目招投标', '中裁(湖北)工程咨询有限公司', '7月17日', '3000-4000元', '武汉-东西湖区', '工程施工', '100-299人', '未融资', 'CCL1437644520J40796827012', '【职位描述】<br>1、准备投标报名资料及领取招标文件等事宜；<br>2、编制资格预审申请文件，投标文件资格审查及商务标部分；<br>3、资审文件及投标文件的打印、胶装、组装、封标、开标等与投标工作相关的事宜。<br> <br>【任职资格】<br>1、本科及以上学历，工程类或计算机，营销管理等相关专业；<br>2、具有良好的沟通、组织协调能力；具有高度敬业精神、团队意识强；<br>3、熟悉运用office、PS等相关专业软件；<br>4、有建设单位、施工单位、造价咨询单位投标工作经验或同行业工作经验者优先。<br> <br>【福利待遇】<br>1、公司为员工缴纳社保；<br>2、妇女节、端午节、儿童节、中秋节、圣诞节、春节（最长20天带薪假期）、员工生日等节假福利；<br>3、工作日5天制，周末双休，享受国家带薪节假日；<br>4、一年一次员工职业通路晋升机会；<br>5、年度优秀员工、团队奖励；<br>6、公司不定期组织党支部、团支部活动。如公司周年庆、月度管理人员聚餐、轰趴、羽毛球、下午茶等活动。', '中裁咨询 Zhongcai Consultants，2014年成立，具有国家建设工程造价、司法鉴定等服务资质。目前是湖北省专业专职且快速解决建设工程造价合同纠纷的服务机构，专职开展全过程造价咨询、法务造价、造价司法鉴定、造价纠纷调解、工程争议评审、专家证人等业务服务。公司注册资本5000万元，目前拥有员工总人数80余人，其中专业技术人员72人，一级造价师21人，专业齐全。一级土建注册造价师15人，一级安装注册造价师4人，一级水利工程造价工程师2人，一级交通运输工程造价工程师2人，注册一级建造师4人，法律顾问3人。公司设有工程造价鉴定中心、工程造价纠纷调解中心、法律咨询事业部、财务部、综合部、法务审计部等。公司拥有较为完善的科学管理制度体系，是一家专业专职且快速解决建设工程造价合同纠纷的服务机构。', 'https://www.zhaopin.com/jobdetail/CCL1437644520J40796827012.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4515, '培训师', '新疆金正大实业集团有限公司', '7月15日', '5000-8000元', '乌鲁木齐-水磨沟区', '计算机软件', '100-299人', NULL, 'CCL1410539800J40757979911', '1.新人制式培训：根据公司实际展业情况，结合实际场景开展新人制式培训工作，助力新人快速进入工作状态达成转正;<br>2.需求培训：根据公司各阶段经营目标，组织开展四地员工有序参加阶段性培训。根据需求制定培训课程，助力员工高效开展工作，提高员工留存率;<br>3.业务话术总结与试讲：根据公司客户痛点问题完成话术的设计，完成部门内部组织开展的话术研讨及试讲通关工作，不断提升及精进培训能力；<br>4.讲师训练营：组织公司中有意向提升演讲能力的个人/团队，开展PTT系列课程将团队中的优秀个人纳入首批讲师训练营，锻炼其表达能力、演讲能力，通过经验萃取形成话术及课程；<br>5.更新板块学习、运营/市场培训：根据板块更新情况，周汇总、月学习，跟进更新内容，与产品及时沟通，及时掌握板块调整后相关功能及深度测试产品流程；<br>6.根据平台板块进行视频工作的分配，包含但不限于：新人课程、培训需求、知识分享、新媒体推广视频的录制；<br>7.根据经营帮--帮助中心的用户需求，培训部需进行帮助中心内容制作与上传，确保内容正确、更新及时；<br>8.根据平台更新情况，及时更新平台使用手册及相关宣传品文案撰写工作，包括：各版块使用手册、品控文稿及视频、培训PPT等资料；<br>9.培训课程开发；<br>10.客户维护:需根据公司来访客户/外培客户进行公司及平台亮点，或辅助相关领导及市场部门进行客户接洽，配合市场运营做好客户维系工作;<br>11.参加各大展览、博览会等讲解工作；<br>12.经营帮平台付费会员客户培训服务及维护。', NULL, 'https://www.zhaopin.com/jobdetail/CCL1410539800J40757979911.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4516, '销售工程师', '福州福光水务科技有限公司', '7月23日', '6000-10000元', '太原-杏花岭区', '仪器仪表制造,环保,电子/半导体/集成电路', '500-999人', '不需要融资', 'CC138229170J40500451205', '岗位职责：', '福光各子公司的理念：希望通过我们每一位福光人的努力，为中国的节能减排与环保事业做出贡献！从而，让中国的水更清、草更绿、天更蓝、空气更清新，做出我们的贡献，并为子孙后代营造更美丽的地球而努力。福州福光水务科技有限公司成立于2000年，是国内集生态环境监测、智慧水务建设、水质监测智能硬件研发于一体的环境与水务行业集成类科技型公司。公司以物联网、大数据、算法模型等科技服务为载体，为行业客户提供“软件+硬件+平台+服务”全方位解决方案。公司立足福州，业务网络遍布全国，致力于为中国节能减排的磅礴事业贡献“福光力量”！概述• 20余年环境监测与水务领域专业沉淀•著作权和专利100+•员工1000+• 2022年合同销售额10亿+• 2021年福建省环保企业年度10强• 2021年福建战略性新兴产业企业100强企业宗旨•为员工创造价值•为客户创造价值•为社会创造价值价值观•以德为本•以信为先•以义为重•以和为贵•以新为生•以勇为荣主营业务•智慧供水集成业务•智慧排水集成业务•城乡供水一体化平台建设•水质监测硬件设备•哈希、西门子等品牌分销业务•生态环境监测工程•环境水务综合运维服务联系地址：福州市仓山区金岩路168号电话：0591-83305857杨女士电子邮箱：hr@fuguang.com（标题请以“姓名+应聘岗位+目前所在地”格式）公司网址：www.fuguang.com(电子)、www.fuguangwater.com（水务）', 'https://www.zhaopin.com/jobdetail/CC138229170J40500451205.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4517, '储备经理人', '北京链家置地房地产经纪有限公司', '7月15日', '9000-12000元', '北京-西城区', '房地产中介,电子商务', '10000人以上', '未融资', 'CC252944430J40372355416', '要求：统招本科学历<br>【工作地点】全北京就近安排<br>【工作任务】<br>1.利用线上链家网or贝壳网获客，为客户提供专业的咨询。<br>2.利用Link房源共享，分析房源利弊，为客户匹配合适房源。<br>3.线下邀约带看，为客户的购房提供全程保障服务。<br>4.房源端开发维护，获得商机展位。<br>【为什么我会选择链家】<br>首先，链家规范了整个行业。链家有着最完整的培训体系，以及最透明的薪资，晋升制度。<br>其次，链家学历要求高，专业素质要求高，提佣也高。在这里，入门提点30%，后期高达70%！现在大力提拔培养新复合型人才，在这里无论你什么专业，都能够有自己的一技之长，有自己的容身之处。<br>最后，链家的团队氛围是无人能比的！不定期的旅游聚餐，开单了团队奖励以及分业绩，合作共赢的公司理念，高度的包容自由，都让你在这里有家的温暖，觉得安心舒适。<br>【薪资待遇】<br>转正前无责任底薪6000元， 转正后有责保障底薪6000-10000元。入职一年后平均薪资8000-10000元，提佣30%-70%上不封顶！！在这里只要你肯努力，就有无限可能。<br>【我们是不是非常累？】<br>外出行程会有，不是单纯坐办公室的工作。但是整体不累，相对自由。<br>【新人都要大量打电话吗？】<br>No!!!每个人都自己的作业方式，我就不提倡打电话，链家全面取消洗盘，接下来的重点在线上流量转化以及线下社区链接。<br>【晋升体系什么样？】<br>分为业务线/管理线两条路晋升。<br>顾名思义，业务线省心，两耳不闻窗外事，一心我只卖房子。提点收入非常可观，入职两年以后年入几十万问题不大。<br>管理线就是经纪人-店长-经理-总监-大部副总-城市总。<br>90后的商圈经理占比三分之一，晋升够快5年做总监不是梦。<br>如果看到这里，你觉得想加入我们。或者依然存在困惑茫然，欢迎与我聊天，开启我们的故事。<br>职位福利：五险一金、绩效奖金、带薪年假、全勤奖、带团队、项目奖金、出差补贴、多次晋升机会 <br>职位亮点：高薪资。完善的培训体系。流畅的晋升渠道', '北京链家成立于2001年，是中国领先的房地产服务企业，业务覆盖二手房、新房、租房等全方位房产交易和居住服务，目前北京链家有1000余家门店。20年来，北京链家致力于提供安全有品质的服务，在行业率先承诺“不吃差价”、首倡“真房源”、推出“交易不成佣金全退”“电话营销扰一赔百”等18项安心服务承诺，与此同时北京链家也在全面推行店面服务升级和经纪人职业素养提升，坚持对客户好，对经纪人好，对社区好，持续推动行业进步，不断提供更有品质的服务。', 'https://www.zhaopin.com/jobdetail/CC252944430J40372355416.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4518, '质检员', '邦尼医疗科技(常州)有限公司', '7月21日', '3000-5000元', '常州-武进区', '医疗设备/器械,医疗设备/器械', '20-99人', '未融资', 'CC821957370J40795410505', '1、进货检验记录、报告、登记表； 2、过程检验（含末道检验、初包装、外包装）相关工作及记录；', '邦尼医疗科技（常州）有限公司成立于2018年，位于江苏省常州市武进区湖塘镇湖塘科技产业园，占地面积2166多平方米，是专注于自动缝合及微创外科产品的研发、生产与销售为一体的医疗器械公司。公司把“更高品质、更好服务”作为我们的使命，为医生和患者提供更高性价比的产品和更优质的服务。在医疗领域我们从“中国制造”向“中国创造”迈进，公司按照YY0287质量管理体系及欧盟CE的要求运营管理。', 'https://www.zhaopin.com/jobdetail/CC821957370J40795410505.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4519, '游戏推广', '菏泽仙女文化传媒有限公司', '6月1日', '5000-10000元', '长沙-开福区', '文化艺术/娱乐,新媒体', '1000-9999人', '不需要融资', 'CCL1331427280J40784120703', '【工作介绍】<br>指定平台开黑玩游戏，接单完成游戏陪陪/陪练，边玩边赚钱【工作内容】<br>1、有手机耳机即可<br>2、陪付费客户打游戏，聊天，唱歌，按时间或局数收费<br>3、有专门组织培训，带你快速人门，赚钱无忧。<br>4、不要求技术【人员要求】<br>1、18-30岁2、<br>会和平精英/绝地求生/英雄联盟/王者荣耀/云顶之弈、其中任意一款游戏<br>3、工作认真负责，积极主动<br>4、良好的沟通能力，性格开朗，喜欢与人交流<br>5、兼职全职均可，不限制在线时间<br>【薪资结算】<br>奖励机制+下单提成，时间充足者每天收入至少200+', '虎牙旗下千万流水钻石公会虎牙交友前三公会旗下几十个专业运营团队！艺人共计5000+陪练师共计10000+集交友、陪玩、颜值、二次元为一体的顶尖经纪公司行业顶尖运营团队，致力打造最优质的品牌公会。', 'https://www.zhaopin.com/jobdetail/CCL1331427280J40784120703.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4520, '总助/CEO助理/董事长助理', '康多乐有限公司', '7月24日', '5000-8000元·13薪', '漳州-长泰区', '日化产品制造,家具/家居/家电', '100-299人', '不需要融资', 'CC338705680J40158686401', '岗位职责：<br>1、协助总经理处理日常事务，确保高效运作；<br>2、新品的收集与联络；<br>3、出货事项跟踪；<br>4、完成总经理交代的其他事项。<br>任职要求：<br>1、本科以上；<br>2、拥有良好的沟通、协调能力；<br>3、能够迅速适应变化，具备解决问题的能力；<br>4、招愿意努力的人，不招只为上班的人。', '康多乐有限公司由日本山崎产业株式会社斥资1840万美金于2014年成立，坐落于漳州市长泰区，毗邻厦门；是一家集研发、自主设计及制造为一体的家居日用品、家用清扫工具、日用塑料制品等生产和销售的企业。公司占地面积3.3万㎡，厂房面积2.2万㎡；现有员工250名，生产工艺流水线数条，年生产能力2100万件（套）。', 'https://www.zhaopin.com/jobdetail/CC338705680J40158686401.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4521, '法务专员/助理', '吉林省科意达科技有限公司', '7月22日', '3000-4000元', '长春-朝阳区', '咨询服务,咨询服务', '20-99人', '未融资', 'CC665793630J40743864201', '岗位内容：<br>1. 负责公司法律事务的日常处理和合规工作。<br>2. 核查、审查合同及其他法律文件，为公司提供法律咨询和防范风险的建议。<br>3. 协助公司内部部门制定、完善公司管理制度、标准合同和各种文件。<br>4. 就公司业务活动涉嫌违法情形给出防范措施以及合规建议。<br>5. 助力并参与公司内部项目的推进和法律风险的管控。<br>任职要求：<br>1. 法律专业或相关专业<br>2. 无论是有经验的专业人士还是毕业生均可。<br>3. 具备出色的沟通、协调、问题解决能力，善于总结和归纳。<br>4. 工作认真负责，注重细节和结果，具备一定的团队协作精神。<br>5. 能熟练使用Office办公软件。大专以上学历且毕业两年内。<br>福利待遇：<br>1.工作时间 8:30～17:30 午休 12:00～13:00<br>2.节假日福利', '北京国瑞精益科技创新有限公司（吉林省分公司）吉林省科意达科技有限公司，是吉林省专业面向各类型企业工程师、企业技师、高校教师、科研院所长期进行创新方法培训、高新技术研发、咨询与推广、知识产权代理等的专业公司。主要公司成员由多名美国麻省理工、日本名古屋大学等国际名校专家、国内知名创新方法专家、高校院所教授、企业行业专家、和多名具有创新理论和方法专长的博士、硕士生组成，这支创新方法专家团队具有十几年的创新理论与方法的研究与推广经历，在国内所服务各个行业的企业近千家，涉及领域包括：高铁动车、汽车、航空航天、船舶重工、鼓风机制造、中国石油、中国电力、新能源、新材料、建筑、冶金、生物医药等领域；业务范围包括：广东省、浙江省、江苏省、湖南省、湖北省、青海省、内蒙古、吉林省、辽宁省、山东省、北京市、上海市、天津市等地区，培养的创新工程师近万人，已取得国家科技部认证资质的创新工程师数千人，积累了大量的创新理论与方法的推广、培训和咨询的经验。本公司在为企业培养大量创新人才的同时，协助企业工程师解决了大量与产品开发、产品制造相关的企业和行业难题，产生了一大批专利，每年为国家大型企业及民营企业，解决多项技术难题，取得了显著的经济效益和社会效益。', 'https://www.zhaopin.com/jobdetail/CC665793630J40743864201.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4522, '销售工程师', '北京申电科技有限公司', '5月27日', '5000-10000元', '南京-栖霞区', '电气机械/电力设备,电气机械/电力设备', '100-299人', '未融资', 'CC132273970J40402807701', '岗位职责：<br>1、熟练掌握产品（直流屏、旁路柜、UPS、EPS等）信息及技术要点，为客户推介合理产品；<br>2、开发新客户的同时，维护现有客户关系，深度挖掘现有客户潜在的需求；<br>3、调研分析客户需求，结合公司产品特点为客户提供解决方案，引导客户对技术和产品进行选择；<br>4、根据市场需求及客户调研情况，向技术部提出新品开发建议；<br>5、跟进客户订单流转发货情况，负责货款及时回笼。<br>任职要求：<br>1、专科及以上学历，电气、机电类专业优先；<br>2、有高低压成套设备领域从业经历者优先考虑；<br>3、良好的语言表达能力和交际能力；<br>4、积极上进，踏实稳定。<br>职位福利：包住、通讯补助、带薪年假、年底双薪、单休、五险  <br>', '北京申电科技有限公司成立于2003年，位于北京副中心通州区佰富苑工业区，占地面积1万平方米，建筑面积3.5万平方米。公司现有员工近200人，90%拥有专科及以上学历，80后、90后已成为公司发展的中坚力量。 2017年底，公司进行资产重组，重组后的北京申电科技有限公司，与北京国电远通电气有限公司、上海赫伊电气科技有限公司、河南申电科技有限责任公司成为青田宇电科技有限公司的子公司，从而形成以北京通州、河南焦作沁阳、浙江丽水青田呈三角形辐射的生产、配送及售后网络，以最快的速度服务于周边省市客户。同时，公司在唐山、长沙、南京、许昌、郑州、上海六地设有销售办事处，旨在为各地用户提供更便捷的服务。作为直流电源行业的知名企业，北京申电科技有限公司致力于GZDW、GZSD系列直流屏、EPS、UPS的研发、生产与销售。公司拥有一支优秀的电气工程师服务队伍,为广大客户提供完善的售前、售后服务。公司一贯坚持“以诚为本、敬人敬业、求实创新、服务用户”的经营理念，倡导“培育精英团队、适应环境变化、创造终身客户”的企业核心理念，营造了良好的企业文化氛围，明确了“6级6等”、“共创共赢”的职业生涯规划路线，并由此构建了企业与员工快速成长和持续发展的强大平台。', 'https://www.zhaopin.com/jobdetail/CC132273970J40402807701.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4523, '销售运营', '河北城与花科技有限公司', '2025-07-27 01:27:37', '4000-8000元', '邯郸-邯山区', '新零售', '100-299人', NULL, 'CCL1495449980J40692530809', '岗位职责：<br>1.负责平台外卖店铺整体运营，完成预设目标；<br>2.分析商家需求，完成不同阶段和鲜花节日的商品营销策划；<br>3.负责店铺日常维护，包括产品更新、订单处理、售后问题解决等；<br>4.负责店铺营销活动、提升店铺竞争力、评分、同商圈排名，并跟进落地执行；<br>5.跟进活动效果，分析数据，复盘优化，提升店铺精准流量及转化。<br>任职要求：<br>1.不限行业，专科及以上学历，21-35岁；<br>2.良好沟通表达能力，逻辑思维清晰，具备一定数据分析能力；<br>3.接纳25届应届生，在校有实习经验，综合素质佳（沟通、逻辑、态度）<br>4.稳定性好-同家公司在职一年以上<br>5.熟悉电商平台规则、操作及营销玩法，有做过外卖运营平台经验者优先；<br>福利待遇：<br>1、底薪+月度绩效+季度绩效+年度奖金+鲜花大促节日奖金，综合月收入5-10k；<br>2、六险（五险+商业险）；带薪年假；<br>3、工龄奖：每满1年每个月加100元补贴；<br>4、生日惊喜礼物+生日会，春节、妇女节、端午节、中秋节等很多节日福利礼品<br>5、鲜花节日管餐食、管住宿、报销打车费，饮料畅饮零食管够；<br>6、工作时间9:00-12:00，13:30-18:30，每周休1天，法定节日按国家规定（遇<br>到鲜花节日进行调休）<br>公司在职人员近200人，年轻人占大多数，工作氛围轻松愉悦<br>公司给每个员工都提供公平公正的晋升机会，期待你的加入。<br>老板事少，同事友好，公司团建活动多到爆！<br>更多员工福利等你来解锁！', '我们公司是做全国新零售平台鲜花类目品牌运营：不限于美团外卖、饿了么、京东到家、阿里口碑、美团团购等，所有全国近50万家线下花店都是我们的客户群体；包括直营门店、私域流量、小程序、抖音直播、鲜花供应链也都是公司覆盖的方向。在新冠肺炎疫情的情况之下，线下流量大幅度缩减，线上平台流量越来越多的趋势下，外卖及零售平台也越来越重要成为花店销售的一个重要渠道和平台。公司致力于打造一个售前服务优质、花材品质高端、花匠创造力、美感和实操能力强、配送售后服务等有保障的高端花店品牌；目前公司在北京、邯郸多地联合办公，拥有专业的招商销售、运营、产品、研发、拍摄团队；目前合作门店数高速增长中，同时也是美团战略合作公司，不管是服务门店数量还是运营效果都是业界的佼佼者，公司规模还在倍增。', 'https://www.zhaopin.com/jobdetail/CCL1495449980J40692530809.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4524, '电话销售', '博岳通信', '5月12日', '1-1.5万', '石家庄-裕华区', '运营商/增值服务,IT服务,通信/网络设备', '10000人以上', NULL, 'CC351377410J40733353601', '归360直接管理<br>岗位职责:<br>1、依托公司资源与客户电话沟通 (无需外出)，完成公司下达的各项销售指标;<br>2、维护客户资源，提供良好的服务，保证客户满意度;<br>任职要求:<br>有团队协助的精神，有强烈挑战高薪的欲望<br>福利待遇:<br>1、薪酬待遇:基本工资+餐补+提成+级别津贴;<br>2、石家庄本地五险一金;<br>3、早九晚六，固定六日双休；', '河北博岳通信技术股份有限公司是一家大型的电子商务、呼叫中心运营及信息服务供应商，主要从事大数据建模/分析/应用、呼叫中心运营、运营商业务渠道、云服务、网络与信息服务业务。专注于为运营商、电子商务、金融、互联网企业和中小企业提供端到端的运营及服务解决方案。公司现有员工15000名，拥有运营坐席超过16000个，目前在北京、河北、四川、湖南、江西、辽宁、福建、宁夏、贵州、浙江、陕西等多个省市设有分公司和办事处。在大数据应用和呼叫中心运营领域，博岳股份与全国十几个省市通信运营商客户进行了全面合作,包括北京移动、中国移动咪咕公司音乐基地、咪咕动漫、四川移动、河北移动、河北铁通、宁夏移动、卓望信息、辽宁移动、江西移动、陕西移动、湖南电信、贵州联通、虚商迪信通；博岳股份与十几家互联网企业在运营和服务领域进行全方位的合作，包括小米科技、去哪网、多点生活、牛电科技、海选网运营支撑服务；博岳与互联网金融九鼎投资-借贷宝进行了全方位的战略合作，包括人人行客服、人人行催收、人人推和研发合作。博岳股份全面服务于通信运营商、金融、电商及互联网企业，服务用户超过5亿。在云服务领域，基于互联网模式建立了端到端的云客服平台，向互联网企业和各中小企业提供系统平台、数据库、数据建模及分析、物理场所、台席、人员及培训等端到端解决方案；为互联网企业和各中小企业提供快速、便捷、性价比高的优质服务。同时公司根据客户的需求，为客户设计完整的呼叫中心解决方案，并负责呼叫中心的建设、运营与维护，承接客户的对外联络、咨询、投诉、问卷调查、营销、客服等各项工作。作为河北省高科技企业，博岳股份于2016年3月份成功挂牌新三板。公司具备工信部颁发的“中华人民共和国增值电信业务经营许可证（全国呼叫中心业务许可证、河北省因特网信息服务业务许可证）”、“通信信息网络系统集成乙级”及“道路运输经营许可证”等资质，并且通过了ISO9001质量管理体系和ISO14001环境管理体系等权威认证。博岳股份立志发展成为业界一流的信息服务和网络服务提供商，博岳股份全面向世界优秀企业学习。博岳股份吸纳业界优秀人才，聚焦客户、聚焦业务，实现平台化和规模化的管理和运作，公司将秉承“以客户为中心、以贡献者为本、持续艰苦奋斗”的企业核心价值理念，我们相信通过全体员工的不懈努力和追求，一定能够为客户提供最好的解决方案和最优质的服务，并为客户实现商业成功!', 'https://www.zhaopin.com/jobdetail/CC351377410J40733353601.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4525, '电话销售', '河北御芝林生物科技有限公司', '7月23日', '5000-8000元', '石家庄-裕华区', '医药制造,零售/批发', '1000-9999人', 'B轮', 'CC221836410J40704581012', '岗位职责：维护老顾客，公司提供有刚需的准客户，二次销售。达成长期合作<br>工作职责：<br>1、跟踪回访维护高品质精准顾客；<br>2、解决顾客所需要的任何咨询；<br>3、协助主管经理帮扶团队员工做好顾客；<br>4、服务周期顾客，达到顾客满意度的情况下达成复购。<br>【你能得到】：<br>1、综合底薪 5000-5500以上+高提成；<br>【任职要求】：<br>1、年满22-45周岁；  2、思维清晰，具有良好的沟通表达能力，头脑灵活，思维敏捷；  <br>  <br>  <br>', '河北御芝林生物科技有限公司创建于2006年5月，总部位于河北省石家庄市高新技术产业开发区昆仑大街海河道168号，是一家集科研、生产、线上线下营销于一体、并通过国家GMP严格认证的综合性现代化中医药企业。企业占地110000平方米，其中办公用面积24000平米，厂区绿化面积36000平米，生产车间50000平米。子公司御芝林药业有限公司，注册资金1600万，位于邢台南和县，占地面积70000平方米，厂区绿化面积29000平米，其中车间面积达15000平米，包括前处理提取车间、固体制剂车间、口服液制剂车间，具备生产颗粒制剂、胶囊制剂、片剂、合剂、酊剂、糖浆剂等全剂型药物能力;全部设备及辅助工程均达到SFDA认证标准，2016年通过国家食品药品监督管理局新版GMP严格认证。产业布局辐射华北、东北、华南、华东、西北、西南全国六大区30多个省份及地区。拥有河北省知名的现代化、规范化的电子商务平台，现有员工1500余人。2020年8月把IT技术团队迁到了北京海淀区中关村附近，80%为本科硕士学历的IT人才。涉及CRM项目、EHR项目、仓储物流项目、BI项目、垂直电商项目等，还有一些商城和小程序、APP等，为公司各部门的业务发展提供了信息化服务。品牌定义：御芝林秉承“做好中药，健康天下”的企业使命，从源头保证产品质量，加强生产过程中的监管和安全性控制，以经典中药名方为基础，通过现代科技确保产品创新。经过数年潜心研发，目前已拥有58件自主研发产品囊括药品、保健食品、食品三大领域，拥有18项国家专利。社会责任：以匠心、诚信诠释企业责任企业文化：企业使命：做好中药健康天下企业愿景：百年御芝林！企业价值观：诚信、上进、乐观、创新。诚信—恪守诚信，不夸大其词上进—追求上进，不安于现状乐观—保持乐观，不惧怕苦难创新—大胆创新，不墨守成规产品观：不出则已，出则必是精品。客户观：用户第一、服务第一；坚持四心原则，以爱心、耐心、孝心、匠心为顾客服务。人才观：以人为本，为每一个心怀梦想的奋斗者提供机会。诚心选才、匠心育才、爱心留才。发展目标：御芝林的发展目标是成为现代中药的领导品牌，铸就百年御芝林', 'https://www.zhaopin.com/jobdetail/CC221836410J40704581012.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4526, '风电工程师', '陕西风新能电力科技有限公司', '7月22日', '6000-12000元', '榆林-榆阳区', '新能源', '20-99人', NULL, 'CCL1483772690J40775931712', '一、电气、机械类相关专业有工作经验(无经验也可以）二、可接受中长期驻外工作；', NULL, 'https://www.zhaopin.com/jobdetail/CCL1483772690J40775931712.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4527, 'APP推广', '成都歪马科技有限公司', '7月23日', '7000-10000元', '佛山-高明区', '电子商务', '1000-9999人', '未融资', 'CCL1492920960J40790004108', '※全城就近安排，全职/兼职均可<br>​<br>【福利待遇】<br>​1、薪资构成：无责底薪+全勤奖+高额提成+补贴等，多劳多得，全职综合薪资7000-10000，兼职综合3000+<br>​2、员工福利：团建聚餐不断，团队氛围好<br>​<br>​【工作内容】<br>​1、负责在门店周边商圈、社区引导客户注册“歪马送酒”公众号<br>​2、根据用户喜好推荐其感兴趣的酒水商品，并引导新用户通过“歪马送酒”小程序领优惠券下单<br>​3、邀请客户添加企微，做好客情维护，推广酒类新品<br>兼职：负责晚高峰酒水送达服务工作，薪酬结构丰富，收入来源多​<br>​<br>​<br>​【晋升发展】<br>​1、全职：店员-储备店长-店长-储备主管-主管-经理，最快2-3个月即可晋升<br>​2、兼职：可转全职，享受全员工晋升待遇', '歪马送酒是美团旗下的酒水即时零售品牌，经营品类涵盖啤酒、白酒、红酒、洋酒四大品类。通过与酒水品牌直接合作，严控供应链，自建配送体系，给前置仓配货，商家在小程序和外卖平台为用户提供平价、保真、平均15分钟送达的酒水及时送服务。歪马送酒在2021年6月23日广东惠州开展单城探索，启动1个城市中心仓+N个前置仓，40天开仓8家，覆盖惠州主要城区。截止2024年7月，歪马送酒在广东地区（深圳、广州、东莞、佛山、惠州、汕头、江门、中山、河源），江苏地区（南京、苏州）、浙江地区（杭州、宁波、温州）北京、上海、杭州、成都、西安、重庆、武汉、福州等22个城市建有直营门店，门店数量超过家。2025年还会入驻青岛、南宁、郑州、合肥、贵阳等城市，预计实现全国省会城市、一线城市全覆盖，门店数量超1000+。', 'https://www.zhaopin.com/jobdetail/CCL1492920960J40790004108.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4528, '总助/CEO助理/董事长助理', '上海幸业货架有限公司', '6月16日', '7000-14000元', '上海-嘉定区', '电子商务,金属制品业', '20-99人', '不需要融资', 'CC408854120J40622692006', '总助/CEO助理/董事长助理/董事长秘书<br>  岗位职责与职内要求：', '上海幸业货架有限公司成立于2010年，总公司位于上海，工厂位于常熟，是目前国内/外领先的阿里巴巴平台源头工厂型公司。我们通过与品牌、平台的紧密合作，始终站在行业前沿，洞悉行业市场变化，在行业领域拥有资深的行业背景和电商实战经验。我们有一支年轻、热烈且有趣的团队，团队大部分都是90/00后，氛围轻松、自由、友爱。热烈欢迎你们的加入～', 'https://www.zhaopin.com/jobdetail/CC408854120J40622692006.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4529, '销售工程师', '南京睿目电子科技有限公司', '2月15日', '7000-14000元', '南京-栖霞区', '电子/半导体/集成电路,通信/网络设备,房地产开发,计算机硬件', '20-99人', '未融资', 'CC405567910J40808484115', '岗位职责：<br>1、负责区域内代理商洽谈、客户开拓及维护；按计划完成区域内季度、年度销售任务；<br>2、维护公司现有销售渠道，拓展开发本区域内客户资源，提高公司产品覆盖率；<br>3、维护客户关系（客户关系数据收集、提高客户增长率、避免客户关系流失等）；<br>4、负责所管辖区内产品推广活动，参与经销商组织的各项活动，发掘潜在客户；<br>5、给客户提供基本的技术支持；协助客户完成项目的投标、签约；<br>6、与合作伙伴建立良好合作关系，维护企业形象；<br>7、热爱并对销售行业有一定兴趣，具备良好的组织、协调及商务沟通交流能力，能够清晰、准确地传递产品信息和客户需求；有良好的团队协作精神，较强的独立分析问题和解决问题的能力。（公司会对员工进行针对性的培训与指导）<br> <br>任职要求：<br>1、在教育系统、政府机关、事业单位、公安部队、文旅娱乐等领域有社会关系者优先考虑；<br>2、大专或本科以上学历，工作经验不限，优秀应届毕业生亦可； 多媒体音频、电子信息等专业；<br>3、具有音响、灯光、会议、音视频行业销售工作经验者优先；有相关分销渠道者优先；有能独立统筹同类项目经验者优先；<br>4、工作仔细认真、责任心强，能够适应短期出差；有优秀业务的素质，能够吃苦耐劳，承受较大工作压力，敢于挑战高薪。<br>5、确保新员工的身体健康，确保其能够适应工作岗位的需求，入职前需提交个人体检证明。<br>职位福利：餐补、交通补助、员工旅游、节日福利、带薪年假、绩效奖金、五险一金', '南京睿目电子科技有限公司成立于2011年，注册资本2500万元；是一家致力于为客户提供音视频产品及智能信息化系统集成整体解决方案的高科技专业公司。自成立以来，公司立足于信息化、智能显示、AV集成等行业、不断增强产品和解决方案研发、工程设计、生产制造、质量管控、客户服务的内在底蕴，不断拓展业务方向、市场营销、对外合作、公司发展稳健，在业内具有良好的公司形象和品牌声誉。公司为“江苏省民营科技企业”，拥有电子与智能化工程专业承包贰级资质、建筑装修装饰工程专业承包贰级资质；连续多年获得“重合同守信用”荣誉称号；并且先后通过了ISO9001质量管理体系认证、ISO14001环境管理体系认证、OHSAS18001职业健康安全管理体系认证、ISO27001信息安全管理体系认证。公司为南京军区物资采购网协议会员单位、南京市教育装备网会员单位、南京市公共资源交易中心会员单位。公司以“潜心为客户创造价值”为经营理念,坚持发展自有核心技术为根本，为客户提供优质的产品而不懈努力。公司高度重视技术创新和产品工程化研发，经过多年的研发积累，已取得多项发明专利及数十项实用新型专利、软件知识著作权等；公司产品涉及LED智能显示，AV音频产品集成；其中LED显示屏产品通过了国家强制性CCC认证、欧盟及美国CE、RoHS、Fcc等一系列产品认证；且产品已列入节能产品政府采购清单，为客户提供高品质高性能的绿色环保节能LED显示产品。而在AV音频产品方面，拥有“EV”(Electro-Voice)、 Lectrosonics、PreSonus等全面的国际知名品牌产品，为众多政府机构、剧院、音乐厅、广播电视台、体育场馆、会议会展中心、酒店、娱乐及演出租赁公司、专业录音棚、高档写字楼提供一站式的整合解决方案。一直以来，睿目服务团队秉持“客户满意就是我们的价值”的企业理念，为客户提供专业、贴心、周到的售后服务。公司将继续响应国家关于绿色环保、节能减排的产业政策，坚持以科技创新为发展根本，以更加优质的集成方案与产品和周到、便捷的服务回报客户！', 'https://www.zhaopin.com/jobdetail/CC405567910J40808484115.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4530, '统计员', '中国人寿保险股份有限公司哈尔滨分公司第二营销服务部', '7月3日', '3000-6000元', '哈尔滨-道里区', '保险,银行', '100-299人', NULL, 'CC466225738J90250004000', '岗位职责：负责文件管理，接打电话，发布招聘信息。<br>任职要求：品貌端正，为人诚恳。<br>职位福利：年终分红、带薪年假、弹性工作、员工旅游、节日福利', '中国人寿保险股份有限公司是国内寿险行业的龙头企业，副部级央企，总部位于北京,注册资本282.65亿元人民币。作为《财富》世界500强和世界品牌500强企业，2017年世界500强排名51位，中国500强排名第4位。中国人寿保险（集团）公司的核心成员，公司以悠久的历史、雄厚的实力、专业领先的竞争优势及世界知名的品牌赢得了社会广泛客户的信赖，始终占据国内保险市场领导者的地位，被誉为中国保险业的“中流砥柱”。', 'https://www.zhaopin.com/jobdetail/CC466225738J90250004000.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4531, '管培生/储备干部', '伊利', '7月24日', '7000-10000元', '成都-邛崃市', '快速消费品,农/林/牧/渔', '10000人以上', '未融资', 'CC000593040J40755885501', '工作职责：为支撑公司战略落地与未来业务发展，在生产领域储备兼具管理能力和专业技能的复合型人才。通过基层多岗位历练，及海外综合历练，积累实战经验，目标3-5年培养成为生产领域关键管理人才或核心专业骨干。 任职要求：', '公司简介：伊利集团稳居全球乳业第一阵营，蝉联亚洲乳业第一，也是中国规模最大、产品品类最全的乳制品企业。同时，伊利还是中国唯一一家符合奥运会标准，为2008年北京奥运会提供服务的乳制品企业；是中国唯一一家符合世博会标准，为2010年上海世博会提供服务的乳制品企业。在发展历程中，伊利始终坚持“国际化”和“创新”两个轮子，固守“质量”和“责任”两个根本，以高品质、高科技含量、高附加值的多元化产品，赢得了消费者的高度信赖。每天，1亿多份伊利产品，到达消费者手中。每年，有将近11亿中国消费者享用到营养美味的伊利产品。', 'https://www.zhaopin.com/jobdetail/CC000593040J40755885501.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4532, '猎头顾问', '广东省国际工程咨询有限公司', '7月17日', '8000-10000元', '海口-龙华区', '咨询服务', '1000-9999人', '已上市', 'CC516805830J40138290305', '1.梳理、汇总国家和相关省市产业政策、投资政策以及行业发展最新动态。<br>2.协助项目经理开展课题、规划、项目可研等业务的资料收集整理、调研、研究、分析、文本撰写等工作。<br>3.与团队和客户进行沟通，能够将所承担工作的研究思路和工作成果清晰的传达给团队及客户。<br>4.对报告进行校对，按时保质保量完成咨询任务。<br>任职要求：<br>1.硕士以上学历，专业要求：经济类、管理类、理工类、工程类相关专业，具备理工+经济类复合专业背景者优先。<br>2.具有良好的语言、文字表达能力及一定的研究能力，有在校参与课题经验者优先；<br>3.具备计算机操作技能，能熟练使用Word,Excel及PPT等办公软件以及数据分析软件；<br>4.具有专业的职业素养，能独立思考，并注重团队合作，工作认真负责，能适应较高工作强度，有创新精神和奋斗精神。<br>职位福利：周末双休、绩效奖金、五险一金、餐补、带薪年假、定期体检、节日福利<br>', '广东广咨国际投资咨询集团股份有限公司（简称广咨国际）成立于1982年，是国有相对控股的北交所上市企业，是中国工程咨询协会副会长单位，资质资信及综合实力位列全国综合咨询机构前列。下设6大事业部、5个子公司、2个专业分公司和多个区域分支机构，业务涵盖投融资咨询、政策咨询、决策咨询、采购咨询、造价咨询、建设咨询，是国家发展改革委、卫健委、国际发展合作署、商务部经合局等部委咨询服务机构，长期为广东以及周边省区的省市发改、财政、工信、住建、教育、卫健、政法、农业等政府部门以及企事业单位、金融机构、社会投资主体提供专业服务。公司完善的人力资源薪酬激励机制和培养发展机制，致力于构建行业内精英人才和专业人才施展才华的发展平台。', 'https://www.zhaopin.com/jobdetail/CC516805830J40138290305.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4533, '网络客服', '新郑市尚念网络科技有限公司', '7月23日', '6000-10000元', '全国-None', '文化艺术/娱乐,在线招聘/求职', '100-299人', '不需要融资', 'CCL1467649290J40755731801', '1.居家办公，男女不限，保底4200<br>2.每天收益日结自提，上不封顶<br>3.每天3-6小时，时间任选，可兼职可全职<br>4.手机就行，不限学历，不要求经验', '公司成立于2023年5月30日办公地址河南省新郑市龙湖镇人力资源。主要经营：抖音线上语音厅主要从事：语音主播和孵化新人主播行业内的各位精英而产生的公司保持‘诚信秉正互利共赢’的理念，以更饱满的热情投入工作，丰富经验和专业实力领路，提供着优质服务原则，专注于抖音方面的语音厅直播，欢迎大家行业精英，前来加入！', 'https://www.zhaopin.com/jobdetail/CCL1467649290J40755731801.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4534, 'BD经理', '台州市海纳信息技术服务有限公司', '7月4日', '1.5-2万', '深圳-罗湖区', '企业服务', '100-299人', NULL, 'CC427996330J40790665212', '入职要求<br>具有1年以上休闲娱乐或医美行业、美食集市、商场、连锁店、跨境等商务工作经验。<br>具有出色的商务谈判技巧与沟通协调能力，能够在复杂的商务环境中灵活应对。', NULL, 'https://www.zhaopin.com/jobdetail/CC427996330J40790665212.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4535, 'APP推广', '福州朴朴电子商务有限公司', '2025-07-27 00:19:41', '8000-16000元', '福州-晋安区', '互联网,新零售', '10000人以上', 'D轮及以上', 'CC408522280J40764836910', '岗位职责:<br>1.负责推广公司产品，吸引新用户下载并使用。<br>2.分析市场趋势，找到合适的推广区域。<br>3.与团队合作，完成推广任务。<br>任职要求：<br>1.具有良好的沟通能力和团队合作精神。<br>2.能够快速适应工作环境，学习新知识。<br>3.对推广工作有热情，能够承受工作压力。', '朴朴是一家30分钟即时配送的移动互联网购物平台。品类包含：水果蔬菜、肉禽蛋奶、粮油调味、酒水饮料、休闲食品、个人护理、化妆品、清洁用品、日用百货等。 2016年6月，朴朴正式在福州成立。带着“让每个平凡的人活得更好”的初心和使命，朴朴开启了自己的新零售即时电商之旅。以高频生鲜作为流量入口，所有日常所需一站式购齐。用户足不出户，只需通过手机端APP或小程序轻松下单，30分钟内，我们为用户将物品配送到家。从福州、厦门、深圳、广州，再到武汉、成都、佛山，朴朴所到之地，皆成平价便利之城，目前员工数已突破60000多人。我们希望以创新的商业模式，高效的仓储配送模式，从用户体验出发，打造新一代B2C即时电商平台，作为潜力无限的新零售黑马，未来可期的互联网新锐，目前已经历七轮融资。公司以技术为核心驱动力，以可靠品质推动中国电商环境改善，同时推动中国食品安全进程，立志成为一家让中国消费者喜欢的即时电商公司。我们希望能寻找到优秀的伙伴，携手共创电商新时代。如果你充满激情、敢于创新、勇于挑战，那么，请加入我们，共写即时零售新篇章！', 'https://www.zhaopin.com/jobdetail/CC408522280J40764836910.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4536, '猎头顾问', '灏信法务咨询(佛山)有限公司', '7月25日', '6000-12000元', '延安-宝塔区', '咨询服务,咨询服务', '100-299人', '未融资', 'CCL1441470070J40782891914', '个人/企业债务领域一站式解决债务问题，给予债务人一个重新履约的机会，具备绝对的市场竞争力，万亿级的蓝海市场，业务覆盖全国范围! 主营业务： 1、各大银行信用卡、信用贷逾期: 停息挂账、避免催收、避免诉讼、停止罚息、违约金等费用，最长可分60期 2、互联网金融/网货平台： 避免催收困扰，高额利息/罚息，减免超出司法保护上限利息 企业以及个人相关法律咨询服务帮扶制度： 1、多维度培训系统：从项目培训到推广和管理，手把手引导新手小白创业/入行 2、一对一帮扶系统：合似人传承制一对一扶持，从小白到大咖的路径扶持 3、纵深服务系统：向下延伸服务，全方位赋能支持 4、售后客服体系：无忧操作，及时解答客户疑问 5、律所法务支持：自家的律所为强大后台，以专业、敬业的态度解决客户问题 6、积极创新能力：持续不断开发新的市场项目，保证业务持续性 岗位要求: 1、性别年龄不限，口齿清晰，语音富有感染力，心态年轻积极健康。 2、可接受无经验（前期有导师培训）有销售经验者优先，无经验者培训上岗。 3、思维清晰，学习能力强，有目标感，能够为达目标善于思考 4、热爱销售行业，善于与人打交道，熟练使用微信及网络 5、深刻领会公司的经营理念，服务理念，并落实到实际工作中 6、勤奋、吃苦耐劳，能承受前期开拓压力，抗得住诱惑，受得了委屈，经得起打击，守得住希望、那么我们的故事就可以开始了！ 7、有过负债经历、有过 POS机、办过信用卡、货款、催收、保险金融、旅游行业、美业、房地产、二手车新车交易、微商小伙、人力资源外包公司相关经历工作的，上手更加容易 工作内容： 1、公司可提供精准优质客户资源，可自身开发，客户意向高，好成交 2、对客户进行整理归类，长期维护好客户关系 工作时间：朝九晚六，午休1.5小时（双休）工作氛围轻松无压力 薪资构成：底薪+高提成+开单奖，综合薪资8000起 1、社保+节假日福利+免费专业知识培训 2、不定期下午茶、定期团建、户外拓展、节日活动； 福利制度： 国家法定节假日心意礼品+每月奖金，冰箱，微波炉，水果，零食下午茶，节日+生日福利+ 不定期团建活动 月度季度年度奖状奖杯奖金', '行业概况：个人/企业债务务领域一站式解决债务问题，给予负债人一个重新履约的机会，具备绝对的市场竞争力，万亿级的蓝海市场，业务覆盖全国范围!主营业务：1、各大银行信用卡、信用贷逾期:停息挂账、避免催收、避免诉讼、停止罚息、违约金等费用，最长可分60期2、互联网金融/网货平台：避免催收困扰，高额利息/罚息，减免超出司法保护上限利息', 'https://www.zhaopin.com/jobdetail/CCL1441470070J40782891914.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4537, '质检员', '河北硕升企业管理有限公司', '7月14日', '7000-9000元', '长春-南关区', '人力资源服务', '20-99人', NULL, 'CCL1502670500J40778217714', '300一天！立即投递！在线咨询！<br>新厂开招！大量招人！全程免费！<br>无需等待即刻入职！入职当天即签订正规合同！<br>请直接点击【立即投递】24小时在线在线咨询回复！！！<br>①：小时工：30/小时，300一天，随走随结，入职7天可预支，包食宿，报销路费<br>②：月薪保底8000+免费包吃住+福利奖金+工价持续上涨！！！！<br>③：班次：长白班居多，个别人员需倒班，倒班人员补贴30/晚，可根据自身意愿选择班次<br>④：招聘要求：16-50周岁，学历不限，经验不限，早报名早赚钱<br>⑤：路费报销：外地来我司工作的人员，工作满一个月全额报销<br>⑥：每月10号准时发放薪资，直发，纯工价<br>小时工：30/小时，300一天，随走随结，可预支，包食宿，报销路费，入职7天既可预支<br>小时工：30/小时，300一天，随走随结，可预支，包食宿，报销路费，入职7天既可预支<br>小时工：30/小时，300一天，随走随结，可预支，包食宿，报销路费，入职7天既可预支<br>【工作岗位】<br>普工/操作工，主要负责做一些简单的手工活，例如：贴标签，检验，测试，组装产品等简单的工作内容<br>质检员：主要负责车间内巡查并监督一线员工规范作业<br>仓库管理员：主要负责出入货物的登记<br>【福利待遇】<br>（1）保险：公司为员工缴纳五险（养老、医疗、失业、工伤、生育）<br>（2）设施：公司生活区设有网吧、超市、美发厅、洗衣房、健身房、球场免费娱乐；<br>（3）娱乐：公司不定期为员工组织聚餐、旅游、多种文艺活动、大型抽奖活动等。<br>（4）节假：享受节假日、婚假、丧假、产假、带薪年假15天<br>（5）年假：过年过节（带薪休假）每次发放800-1500不等的<br>（6）生日：生日福利：生日当天可领取200-400元大红包！<br>【衣食住行】<br>（1）衣：上班不需要穿无尘服<br>（2）食：公司免费提供工早中晚3餐，二荤二素；另提供面食、水果等提供挑选<br>（3）住：公司免费提供住宿，4-6人/间，设施包含空调、独立卫浴、橱柜等，床上用品厂区发放。若员工自己在外租房每人每月补贴500元且有厂车接送<br>（4）行：上下班有厂车接送，公司每周提供班车到购物中心<br>请直接点击下方【立即投递】咨询详谈报名！<br>请直接点击下方【立即投递】咨询详谈报名！<br>请直接点击下方【立即投递】咨询详谈报名！', NULL, 'https://www.zhaopin.com/jobdetail/CCL1502670500J40778217714.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4538, '档案管理', '甘肃华研工程管理咨询有限公司', '7月22日', '4000-5000元', '长春-朝阳区', '新能源', '300-499人', '不需要融资', 'CC542144580J40734599516', '1、熟悉各类办公软件使用、扫描仪、打印机等办公设备使用；  2、工作细心、认真对扫描录入档案认真核对；', '甘肃华研工程管理咨询有限公司隶属中国大唐集团有限公司，由大唐甘肃发电有限公司管理，是专门从事电力工程及工民建项目的工程监理、工程造价咨询、招标代理、工程项目咨询管理、工程技术咨询、工程档案咨询、档案服务等业务的技术服务型企业。公司具有国家建设部颁发的电力工程监理甲级资质、电力工程造价咨询甲级资质、水利水电工程监理乙级、房屋建筑工程监理乙级资质、招标代理乙级,具有ISO9001质量管理、ISO14001环境管理、OHSAS18001职业健康安全管理体系认证。是中国电力建设监理企业协会会员单位，甘肃省建设监理协会会员单位。公司经营业务涉及甘肃、新疆、四川、陕西、青海、江西、辽宁、河南、贵州、西藏、国外——塔吉克斯坦、吉尔吉斯斯坦等地，项目遍布全国21个省市、自治区。其中，国外项目塔吉克斯坦项目和吉尔吉斯斯坦项目均获得“中国电力优质工程（境外）奖”，吉尔吉斯斯坦项目还获得“中国建筑工程鲁班奖”。', 'https://www.zhaopin.com/jobdetail/CC542144580J40734599516.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4539, '法务专员/助理', '北京友财投资管理有限公司', '6月30日', '150-200元/天', '北京-朝阳区', '证券/期货,互联网', '20-99人', NULL, 'CC270584180J40546406808', '岗位职责：<br>1、基础性文件的审阅：份额转让协议、咨询顾问协议、保密协议、行政人事类协议等日常经营性合同；<br>2、法务文件合规管理：分类多形式存档，建立法务文件保管台账； 3、新法新规跟踪，为培训开展、合规自查提供基础支持； <br>4、其他基础性工作。 <br> <br>任职要求：<br> <br>1、法学、金融相关专业，本科及以上学历；<br> <br>2、熟悉相关法律法规及行业监管政策；<br> <br>3、对金融业务、投资投行、基金业务有浓厚兴趣，善于学习、研究；<br> <br>4、具有较强的责任心、执行力、学习能力，具备良好的团队合作精神。<br>', '北京友财投资管理有限公司（以下简称“友财投资”）成立于2015年1月，是在中国证券投资基金业协会登记的私募投资基金管理人（编号P1011170），专业从事私募股权投资等业务，机构股东包括位列中国企业500强的大型产业集团等。核心管理团队来自中金公司、九鼎投资、申万宏源等大型金融机构，投资并参与了数十家企业上市及资产重组工作，在股权投资和资产管理领域经验丰富。友财投资已发行及在设私募股权投资基金20余只，资产管理规模逾30亿元，陆续在新一代信息技术、高端装备、节能环保、新能源新材料、生物医药等领域投资了超过20家企业，如正帆科技、世纪空间、景津环保、桑尼能源、前沿生物等。在众多已投企业中，目前已有1家企业实现主板上市，2家企业在科创板上市，多家企业在IPO排队审核或即将申报材料，基金管理成绩卓著。所获奖项：2017至2019年连续三年获得CLPA“最具LP投资价值GP50强”奖项；第一财经2019年度股权投资价值榜“先进制造与高端装备行业投资机构TOP10”；投中2019年度“中国最佳私募股权投资机构TOP100”；融资中国2020-2021年度“先进制造最佳投资机构TOP20”。友财投资将秉承“诚信、专业、分享、创新、服务”的理念，致力于成为国内最受投资人和企业信赖的精品资产管理公司，以专业化的投资服务为投资者带来优异回报，为企业持续创造价值保驾护航。', 'https://www.zhaopin.com/jobdetail/CC270584180J40546406808.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4540, '总助/CEO助理/董事长助理', '弗斯迈智能科技(江苏)有限公司', '7月16日', '7000-12000元', '常州-武进区', '新能源,新能源', '20-99人', '天使轮', 'CCL1252977170J40753899701', '工作内容：<br>负责总经理的日常事务管理和协调，包括但不限于行程安排、文件管理、会议组织、邮件处理等。<br>主要职责：<br>1.客户、政府、法务、会所、投资机构等第三方部门的对接招待跟进等；<br>2. 负责总经理行程安排，包括机票、酒店预订等工作；<br>3.负责总经理文件的收发、整理和归档，确保文件的及时性和准确性；<br>4.负责总经理会议的预约、组织协调和记录，确保会议的顺利进行；<br>5.负责总经理邮箱的维护和管理，确保邮件的安全和及时性；<br>6.协助总经理处理日常事务性工作，包括但不限于接待来访者、协调各部门之间的工作等。<br>职位要求：<br>1.具备良好的商务礼仪和职业形象，具备一定的政治素养；<br>2. 具备良好的沟通协调能力，善于交际处理外联事务；<br>3.熟练驾驶，能适应出差、商务宴请，弹性工作时间；<br>4.英语六级以上水平（听说读写能力精通）<br>有金融、法务或市场商务，光伏行业从业等相关经验者优先考虑。', '我司成立于 2019年，坐落于国际化“智”造名城—常州市，是一家专注于自动化设备及高端智能装备的科技创新型企业，主要为光伏企业提供钙钛矿、锂电池，氢燃料生产线整体解决方案。公司产品远销印度、越南、土耳其、墨西哥等国家，品质得到了全球客户的广泛认可。使命：钙钛矿光伏整线解决方案先锋愿景：助推新能源产业改革升级，助力碳达峰，碳中和目标实现价值观：专注、聚焦、坚持不懈', 'https://www.zhaopin.com/jobdetail/CCL1252977170J40753899701.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4541, '档案管理', '重庆茗飞工贸有限公司', '3月7日', '3000-4000元', '重庆-渝北区', '电子商务,电子商务', '100-299人', '未融资', 'CCL1305298260J40461777902', '岗位： 关于文书档案的<br>1、档案数字化岗位（档案数字化就是是指利用计算机以及周边设备等技术处理手段将经过鉴选、原本存储于传统载体上的纸质档案信息扫描等技术的处理并加以转换存储、保护、检索利用的系统工程。档案数字化应以档案信息化生命周期保存为主，以共享为基点，以优选为前提，以便于检索、在线利用为发展方向。）<br>2、档案整理  一、对档案进行分类整理;  <br>二、进行扫描;  <br>三、对扫描的电子档进行整理分类;  <br>四、录入到系统中;  <br>五、审核，检索电子档档案是否与原档案相符。  <br>【薪资待遇】： 薪资3500-5000，购买五险（纯计件）  <br>【上班时间】：朝九晚六单休周天，节假日正常休息  <br>【岗位要求】：20-35岁，中专学历以上，有文书档案经验优先', NULL, 'https://www.zhaopin.com/jobdetail/CCL1305298260J40461777902.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4542, '日语翻译', '科聚智科(大连)科技有限公司', '7月14日', '7000-9000元', '成都-武侯区', 'IT服务', '20-99人', NULL, 'CCL1479884500J40756575912', '岗位职责：  1.针对客户的售前售后问题进行处理 ；  <br>2.通过电话形式解决投诉点；  <br>3.提供专业的日语客户服务支持 ；', NULL, 'https://www.zhaopin.com/jobdetail/CCL1479884500J40756575912.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4543, '售后客服', '湖南司柠贸易有限公司', '7月25日', '3000-6000元', '长沙-岳麓区', '电子商务', '20人以下', NULL, 'CCL1505817360J40756298009', '岗位职责​<br>1.负责售后订单跟进，处理退换货、维修等事宜，确保流程顺畅。​<br>2.及时响应客户售后咨询，跟进问题解决进度，反馈处理结果。​<br>3.整理售后数据，记录客户反馈，协助优化售后流程。​<br>4.协调仓库、物流等部门，保障售后事宜高效处理。​<br>任职要求​<br>1.大专及以上学历，有电商售后相关经验者优先。​<br>2.耐心细致，沟通能力强，能妥善处理客户情绪。​<br>3.熟悉电商售后流程及相关工具，执行力强。​<br>4.有责任心，具备团队协作精神，能承受一定工作压力。', NULL, 'https://www.zhaopin.com/jobdetail/CCL1505817360J40756298009.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4544, '广告销售', '柳工', '7月22日', '5000-7000元', '柳州-鱼峰区', '金属制品业,电气机械/电力设备', '1000-9999人', '已上市', 'CC131197048J90252604000', '岗位职责：1、 市场前端与总部职能部门的沟通桥梁<br>2、 经销协议、销售合同、折扣申请、信用申请等文本准备、签署和内部流程操作<br>3、 对于有必要成立项目组协调的大订单或者全球关键客户的订单，进行跟踪及反馈进度<br>4、 对于市场需要专题会议进行协调的重大问题，组织会议并跟踪进度<br>5、 年度、月度销售计划的跟进和落实<br>6、 年度、月度销售资源的协调和获取<br>7、 参加月度工作汇报会，必要时代为汇报销售月度工作报告<br>8、 销售人员不在或公司资源紧缺时代表公司接待来访客户、拜访客户<br>9、 协助合同业务执行进度、技术服务处理、产品供给及开发、物流优化、行政事务等事务<br>10、 临时前往市场配合销售工作的开展<br>11、 其他公司临时工作安排1、 市场前端与总部职能部门的沟通桥梁<br>2、 经销协议、销售合同、折扣申请、信用申请等文本准备、签署和内部流程操作<br>3、 对于有必要成立项目组协调的大订单或者全球关键客户的订单，进行跟踪及反馈进度<br>4、 对于市场需要专题会议进行协调的重大问题，组织会议并跟踪进度<br>5、 年度、月度销售计划的跟进和落实<br>6、 年度、月度销售资源的协调和获取<br>7、 参加月度工作汇报会，必要时代为汇报销售月度工作报告<br>8、 销售人员不在或公司资源紧缺时代表公司接待来访客户、拜访客户<br>9、 协助合同业务执行进度、技术服务处理、产品供给及开发、物流优化、行政事务等事务<br>10、 临时前往市场配合销售工作的开展<br>11、 其他公司临时工作安排<br> <br>任职要求：<br>熟悉国际贸易实务操作，具有１年以上外贸操作经验<br>精通：英文、各种办公软件<br>职位福利：五险一金、带薪年假、定期体检、免费班车、高温补贴、节日福利 <br>', '广西柳工机械股份有限公司（上市公司代码：000528柳工）始创于1958年，前身为从上海华东钢铁建筑厂部分搬迁到柳州而创建的“柳州工程机械厂”，于1993年在深交所上市，成为中国工程机械行业和广西第一家上市公司。公司总部位于历史文化名城-广西柳州，现有员工8000余人，2016年实现销售收入70余亿元，其中海外销售收入占总销售额30%以上。近60年来，柳工一直引领中国重型工程机械制造业，被党和国家领导人誉为“中国装备制造业的示范旗帜”。现代化的研发制造基地和技术领先的产品柳工拥有国家首批企业技术中心，建立了博士后工作站，产品研发水平和技术性能始终保持行业领先地位。柳工在全球拥有20多个现代化的研发制造基地，包括柳州、上海、江苏镇江、无锡、常州、安徽蚌埠等在内的国内制造基地以及印度、波兰和巴西3个海外制造基地。柳工拥有全球领先的产品线，涉及挖掘机械、铲土运输机械、起重机械、工业车辆、压实机械、路面施工与养护机械、桩工机械、工程机械配套件等8大类产品品种，15种整机产品线。主要产品有：装载机、挖掘机、推土机、平地机、摊铺机、铣刨机、滑移装载机、挖掘装载机、压路机、叉车、汽车起重机、履带起重机、吊管机、矿用自卸车、强夯机等。覆盖全球130多个国家的营销网络和2600多个销售网点柳工打造了行业最具竞争力的全球营销和服务配件网络，10家海外子公司均配备了专业的配件仓库，与覆盖全球6大洲130多个国家的300多家经销商，2600多个销售网点为全球客户提供本地化服务和支持。强大的经销商网络，子公司及以客户为导向的企业文化能在全球范围内提供7*24小时专业服务，成为柳工独特的竞争优势。行业领先的自主创新和产品研发实力柳工目前在全球拥有24个研究院所及一支由外籍专家、国务院特殊津贴专家、八桂学者等组成的高水平高素质的千人研发团队；与国内重点高校如浙江大学、吉林大学、华南理工大学、哈尔滨工程大学、兰州理工大学等国内重点高校合作开展前沿技术研究；与国外知名企业联合成立研发团队，共同研发关键核心零部件；引进全球先进的技术管理手段，自主开发覆盖整机、零部件和技术研发的国际化研发流程体系，打造国际化的产品技术研究及管理平台。利用自身的研发能力，柳工还承担了国家级、省部级科研项目和重要课题，建有国家土方机械工程技术研究中心、国家级企业技术中心、国家级博士后工作站、国家工程机械高新技术产业化基地、广西院士工作站、机械工业铲土运输机械工程研究中心等10多个科研平台。柳工珍惜荣誉更关注未来……………………●中国制造业500强●全球工程机械制造商50强●最具全球竞争力中国公司50强●2008年和2014年“全国质量奖”●国家智能制造试点示范（土方机械智能制造）……………………', 'https://www.zhaopin.com/jobdetail/CC131197048J90252604000.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4545, '招聘专员/助理', '吉林省蓝青蛙劳务派遣有限公司', '3月6日', '6000-7000元', '长春-双阳区', '人力资源服务', '100-299人', '未融资', 'CC418019230J40760949503', '2、要求: 18~45岁之间。工作经验 不限、学历不限（本科以上不要）。沟通能力强，身体健康，工作认真负责，心态积极阳光。具有团队合作意识。<br>3、薪资待遇:4000-9000以上(工作能力决定薪资)，不定期团建。节日福利。<br>4、工作时间:8小时。双休，法定假日都休息。(坐班，不跑外)<br>5、工作内容:协助经理工作，工作内容简单，短期即可晋升为经理。<br>6、提供食宿，酒店式公寓', '吉林省蓝青蛙劳务派遣有限公司是由吉林省人社厅批准从事经营劳务派遣、人力资源等服务的企业，公司实缴注册资金200万元，并已通过ISO9001质量管理体系认证,是一家专业为企业提供劳务派遣、劳务外包、人力资源的供应商。蓝青蛙是一家具备现代企业管理制度和服务意识的专业人力资源服务企业。现设有市场运营部、猎头部、人力资源部、办理用工手续、保险缴纳、保险理赔、工社会保障部、综合办公室、财务部等部门，其中汇聚了多名来自省内知名企业、劳动保障部门的资深人力资源管理专家。并在烟台、吉林市、延吉等地设有分公司及办事处。蓝青蛙为企业提供的服务包括：劳务外包、劳务派遣、劳动仲裁委托、社保代缴等人事外包服务。其中所涉及的服务项目包括了：与员工签订劳动合同、资计算发放、退工手续办理等相关的人事服务。', 'https://www.zhaopin.com/jobdetail/CC418019230J40760949503.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4546, '销售运营', '沈阳麦蓝网络科技有限公司', '7月16日', '6000-10000元', '沈阳-沈河区', '电子商务,计算机软件', '300-499人', '不需要融资', 'CCL1340157320J40778669713', '公司以95后为主力军，这里为你提供良好的工作氛围，享受年假！！！<br>岗位职责：<br>1.负责产品运营的维护及市场数据的统计<br>2.根据公司年度发展计划，完成部门任务<br>3.后台客户的管理及维护，前期都是有老人带<br>薪资待遇：<br>1.到手4800+高提成+五险一金<br>2.大额年终奖！！！优秀者能快速晋升，月薪上万及以上不封顶 <br>3.公司提供 清甜可口的水果和小甜品饮料，小惊喜满满<br>4.一年多次晋升机会，每个人在每个阶段都有公平公正的晋升机会<br>职位福利：五险一金，免费住宿，全勤奖，带薪年假，员工旅游，节日福利，多次晋升机会。', '位置座落在沈阳最为繁华地段位于地址:沈阳市沈河区商务总部大厦B座15楼现公司开发新产品急需有志之士的加入，公司带薪培训，入职后定期安排专业知识培训，公司晋升机制完善具有广阔的发展空间（业务员—主管—经理—副总—总经理）只要够努力，一切皆有可能，所有的机会都拼真实力！，期待各位有志之仕的加入！福利：生日奖、团队奖、节假日奖、五险一金、绩效奖金、带薪年假、员工国内外旅游、节日福利、弹性工作、全勤奖、住房补助、 1、能吃苦耐劳，有亲和力；做事认真踏实，为人诚恳，有团队合作意识； 2、目标感强，愿意学习，能侃天侃地、主动和他人沟通交流的小仙女or小少年。3、不限男女欢迎优秀的你们加入我们的大家庭！', 'https://www.zhaopin.com/jobdetail/CCL1340157320J40778669713.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4547, '资料管理', '中国人寿保险股份有限公司天津市和平区支公司', '5月14日', '8000-12000元·13薪', '天津-和平区', '保险', '1000-9999人', '已上市', 'CC467367710J40753926107', '客户资料整理 <br>工作记录与统计 <br>保密与合规 <br>协助与临时工作 <br>客户服务委托对接', '中国人寿保险股份有限公司天津市和平区支公司', 'https://www.zhaopin.com/jobdetail/CC467367710J40753926107.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4548, '招聘专员/助理', '重庆小狼大羊文化传媒有限公司', '7月12日', '3000-5000元', '重庆-九龙坡区', '文化艺术/娱乐', '20-99人', '未融资', 'CCL1475193830J40755536309', '岗位内容：<br>1. 负责编写和发布招聘信息，筛选简历并进行初步面试<br>2. 搜集、整理和分析用人需求和市场薪酬情况<br>3. 协助上级领导做好年度人力资源计划<br>任职要求：<br>1. 本科以上学历，人力资源管理、心理学等相关专业优先考虑<br>2. 具备良好的沟通能力、人际关系处理能力和数据分析能力<br>3. 熟练使用各种招聘平台和工具，熟悉招聘流程和法律法规<br>4. 有较强的组织协调能力和时间管理能力', '公司介绍公司成立于2016年，深耕互联网与自媒体新媒体多年，拥有一流专业的运营团队，拍摄团队，商务团队，策划团队主营业务：传统电商，兴趣电商，直播，短视频，影视动漫宣发与制作，影视投资，商业活动策划，户外广告媒体投放公司目前覆盖，重庆，成都，深圳，上海，杭州，北京，西安均设有分公司，全方位为艺人提供全国性综合艺人经纪服务', 'https://www.zhaopin.com/jobdetail/CCL1475193830J40755536309.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4549, '产品专员/助理', '义乌市微星百货有限公司', '7月24日', '6000-10000元', '金华-义乌市', '贸易/进出口,电子商务', '300-499人', '未融资', 'CC221204030J40156343604', '跨境电商流行语：3分在运营，7分在选品；<br> 公司岗位优势：<br>1.公司有专业的产品研发团队，产品的创新设计能力遥遥领先于同行。产品开发部人员大部分来自一本、211、985院校，团队具有较强的创新研发能力。 行业优秀的行业大咖共事，能力提升空间广阔<br>岗位晋升：产品开发专员、跨境选品专员、产品开发小组负责人、产品主管、产品经理<br>任职要求：（我司有相对成熟的产品开发技术，没有经验可以培养）<br>1 本科，英语4级或以上， 6级优先；<br>2.逻辑思维能力强、一定的数据分析能力、较强的开拓创新能力；<br>3.具有高度责任心和团队合作精神，能承受一定的工作压力。<br>4.熟悉亚马逊、速卖通、TEMU、SHEIN、TIKTOK、shopee等主流平台产品开发优先；<br>职责描述：<br>1、及时了解并能准确预判目前市场的产品流行趋势，能执行有计划的调研，确保产品的超前性、竞争性，并能给出可行性报告；<br>2、负责定期做好产品维护<br>3、协调负责公司新产品的研发，制定进度计划，保证新产品的推出质量及时间； <br>4、定期对销售数据进行分析，调整产品开发策略，提高产品销量;研究竞争对手，市场分析，竟品分析，关键词调研<br>5、负责产品侵权风险把控，有效规避侵权产品上架。', '公司从2006年成立，目前有300多人。我们在全球各大交易平台从事跨境电商电子商务业务。微星的业绩一直保持着惊人的增速，遥遥领先于同行。目前主营产品有DIY装饰品、家居装饰品等，公司自有品牌已在美国、英国、中国注册，品牌在目标市场已成为买家偏好品牌并具一定的影响力，并在行业内有较为领先的领导优势。目前设有11大部门：产品研发部、采购部、跨境运营推广部、外贸运营部、美工文案部、仓储物流部、行政人事部、财务部、扬州运营中心、武汉运营中心、合肥开发中心。企业提倡：我们拥有阳光快乐、松弛有度、融合协作的工作氛围；我们拥抱变化、快速反应，不断学习创新；我们专业执着，全力以赴。公司优势：1.公司有专门的产品研发团队，产品的创新设计领先同行。产品开发部门大部分来自一本、211、985院校，团队具有较强的创新研发能力。2.公司提供领先于市场80%的平均薪资报酬，核心团队有较强的归属感和稳定性。3.公司成立18年左右，开发沉淀了一批优质的供应链。公司现有较强的供应链优势，总成本最低优势。这里没有公司，只有创业平台，成就伙伴的平台！没有老板，只有创业领袖！没有员工，只有创业合伙人！微星也是一个感恩的平台，不管你在微星待多久，感谢你为微星做出的贡献。微星一直愿意让出一部分股份给那些有能力承担责任的、愿意与微星家族共同成长的伙伴们！公司有较为完善的培训、工作流程、绩效管理体系，公平公正公开的清晰的员工职位发展通道（专业成长通道+管理通道）。个人能力价值提升速度快、薪资提升潜力广、职位发展空间大！期待各位伙伴的加入！', 'https://www.zhaopin.com/jobdetail/CC221204030J40156343604.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4550, '内容审核', '万声(临沂)信息技术有限公司', '7月25日', '3000-4000元', '临沂-河东区', '专业技术服务,运营商/增值服务,居民服务,咨询服务', '1000-9999人', '未融资', 'CC839974460J40591685406', '诚邀有激情，有责任心的你加入我们的团队！如果你对工作充满热爱，平时工作生活中认真仔细，那么请继续往下看！！！(小哥哥小姐姐特别多哦)<br>【职位名称】审核标注专员<br>【岗位职责】依据行业规则以及互联网法律法规对送审内容进行审核，其中素材内容涵盖标题、图片、视频、落地页、计划等，审核范围包括图、文、音频、视频等各种形式。拦截涉黄涉暴涉政等不可在平台发布的内容信息，维护前端产品健康，为用户提供良好的平台环境<br>【任职要求】1.大专以上学历（已毕业）<br>2.20-35周岁 有责任心，积极主动，能够承担工作压力<br>【薪资待遇】带薪培训21天，每天60元+5元餐补；薪资：3200-3800，多劳多得，上不封顶<br>【工作时间】8小时工作制，24小时排班，固定双休（轮休）<br>【福利待遇】五险一金，提供住宿，节日福利，高端写字楼办公，环境优雅舒适，中央空调，冬暖夏凉，休息区微波炉，冰箱一应俱全。完善的晋升机制，为你提供广阔的发展空间，轻松愉快的工作氛围，让你在工作中找到乐趣，不定期的团队活动，增进同事间的友谊。<br>如果你对这个职位感兴趣，可以联系我哦，我们将尽快与你取得联系，期待你的加入，共创美好未来！！！', '万声集团创立于1993年，是专业深耕业务流程外包服务（BPO）、信息技术外包服务（ITO）、知识流程外包服务（KPO）、人力资源外包服务（HRO）并涵盖关联业务生态的大型现代服务业集团企业。成立至今，万声专注服务，与公共服务、通信传媒、智能制造、泛金融、交通运输、互联网和电子商务、健康医疗、文教互娱等领域的一流企业及机构建立了持久而稳固的全面战略合作关系，提供呼叫中心运营、客户关系管理、数据分析、IT应用支持、运营咨询、员工健康管理、人力资源管理、信息系统集成及开发等一站式定制化解决方案，以前沿的服务理念和灵活的服务产品，创造卓越的客户体验，为合作伙伴提升竞争优势。2018年11月，万声通讯实业有限公司入驻中关村临沂软件产业基地，职场规模3000余平，旨在打造千人坐席规模的现代化呼叫中心，形成产业标杆。中关村临沂软件产业基地坐落于临沂市开发区，软件园地理位置优越，交通便利，距离全市主要商圈、居民小区较远车程20分钟。', 'https://www.zhaopin.com/jobdetail/CC839974460J40591685406.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4551, 'BD经理', '爱才集团有限公司', '7月4日', '7000-12000元', '南京-建邺区', '人力资源服务', '500-999人', '未融资', 'CCL1246426550J40763352210', '岗位职责<br>1、负责新商户开拓，与商户进行治谈合作与签约，跟进上线流程;<br>2、整合商圈资源，为商户提供整合营销方案;<br>3、根据商户需求制定合理的运营方案，提供促销活动、外卖品设计与运营支持，通过短视频及内容营销进行抖音平台分发，维护客情关系，做好交易额提升优化;<br>岗位基本信息：<br>薪资架构：无责底薪5600+提成gmv*千分之一和千分之三（提成根据团购券的到店总核销量来，在职同学提成高的一个月7~8w，低的小几千，具体需要看个人情况）<br>福利待遇：入职及缴纳六险一金按照当地最高比例12%进行缴纳<br>工作时间：10:00-7:00 周末双休，节假日均正常休息<br>补贴：包三餐，交通补助每月500(实报实销）', '爱才集团总部位于中国杭州国际人力资源服务产业园11-15层，是一家致力于人力资源全产业链深度开发的大型人力资源集团。集团依托全国的服务网络、先进的互联网平台和强大的数据支撑，为市场提供：服务外包、人事服务、猎头招聘、共享平台、产业园运营、职业教育、管理咨询等服务产品。历经多年的创新发展，目前已在杭州、上海、北京、香港等10多个城市设立分支机构，服务网络遍及全国300多个城市，合作院校100多家，招聘网点超过500个，年供应能力10万人以上。', 'https://www.zhaopin.com/jobdetail/CCL1246426550J40763352210.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4552, '律师助理', '辽宁开尔律师事务所', '12月6日', '1000元以下', '大连-甘井子区', '咨询服务,咨询服务', '20-99人', '未融资', 'CC827021140J40661839913', '岗位要求： 1、在校实习生，毕业后可签订劳动合同实习并执业。 2、处理有关法律问题的来信、来访、解答简单的法律询问，代写简单的法律文书；<br>  <br>3、协助律师调查取证、抄写文书、摘录案卷材料、会见被告或当事人，送达文件及办理其他辅助性工作；<br>  <br>4、企业线上法律小组为企业提供咨询及咨询； <br>  <br>5、负责日常律师与客户之间的沟通工作。 <br>  <br>任职资格要求： <br>  <br>1、具有一定的法律基础及文字功底，能够熟练操作各类办公软件；<br>  <br>2、具有良好沟通能力、执行能力、团队协作能力； <br>  <br>3、工作认真细致，踏实肯干，能适应高强度工作且抗压能力强；<br>  <br>4、形象良好，普通话流利。<br>', '辽宁开尔律师事务所（Liaoning Care Law Firm）简称开尔律所，成立于2018年，是一家综合性律师事务所。由一群优秀自身律师及行业精英、专家等60余人组建而成，很多人成员拥有司法、高校、IT、金融、医疗、财税、新媒体运营、新媒体策划等诸多行业复合背景。开尔律所位于大连市高新技术产业园区火炬路32号创业大厦B座15F，办公面积1200余平，包含党建室、图书室、5间会议室、2间洽谈室；此外，开尔律所打造数智化办公间，配备近百个工位，合伙人办公室6间、律师直播套间6间、茶水打印间等设施设备完善，办公室全落地景观，给予成员更多的福利待遇，七险一金、生日福利、工龄奖、年终奖等，尽显开尔理想价值观“别开蹊径，卓尔不群”，让更多的人们生活、事业变得更美好。开尔律所坚定不移拥护党的领导，并设有党建中心，确保开尔律所在执业中政治立场鲜明。2020年-2021、2022年-2023年开尔律所两次获得“大连市优秀律师事务所”2019年-2022年度开尔律所被中共辽宁省律师行业委员会评为“先进基层党组织”开尔律所多名律师获得辽宁省、大连市“优秀律师”开尔律所深耕专业性，让客户更加便捷地获取到适配的问题及解决方案，成立各项目组建立了多元化渠道，线上、线下、律师个人IP等直接触达客户，让更多的人们，可更加便捷地获取到适配的问题及解决方案，通过一案多协同，最大化维护客户权益。', 'https://www.zhaopin.com/jobdetail/CC827021140J40661839913.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4553, '知识产权/专利代理', '路浩集团', '4月11日', '1-2万', '武汉-江夏区', '咨询服务,专利/商标/知识产权', '500-999人', '未融资', 'CC822875230J40326582811', '需求专业：计算机类/通信类/大电学类/机械类<br>工作地点：北京/武汉/广州/保定<br>岗位职责：<br>1、处理国内客户专利申请撰写、OA答复和复审业务；<br>2、处理国内专利无效和诉讼业务；<br>任职要求:<br>1、统招本科及以上学历；<br>2、具有较强的语言表达和沟通能力，能准确理解和把握客户需求；<br>3、具有积极乐观的工作和生活态度，抗压能力强；<br>4、具有代理师资格证、代理行业工作经验者优先。<br>薪酬福利:<br>薪资面议（按专业学历和工作地点面议）<br>福利待遇：<br>1、 基础福利：社保五险、住房公积金、带薪年假、弹性工作、年度体检等；<br>2、激励福利：开发奖、业绩奖、作业奖、年终奖、伯乐奖、学术奖、客评奖等;<br>3、 奖励福利：餐费补贴、全勤补贴、节日礼金、生日会、带薪时假等；<br>4、自选福利：健身房、咖啡厅、保健室、阅读室、专属衣柜等。<br>', '招聘|选择路浩，你不会后悔！良好的发展平台路浩作为行业内创新发展的领军企业，管理系列与业务系列两大晋升路径并行，且股东构成为开放式，可满足不同特质员工发展需要。在路浩，你有希望成长为公司高管或副总级业务骨干，甚至集团股东！丰厚的薪酬待遇路浩崇尚“一流的企业给一流的人才以一流的待遇”理念，施行快速进阶式工资和补贴制度，辅以五险一金、带薪休假和弹性上下班等福利。在路浩，你有可能进阶成高薪酬的佼佼者和高福利的幸运儿！和谐的企业文化路浩司训、路浩哲学与路浩精神等文化理念，倡导诚实守信、尽责求精和协作共进，公司常组织丰富多彩的交流与联谊活动。在路浩，你有机会在协作奉献中得到团队支撑，在敬业进取中实现自我价值！一流的办公条件路浩总部和分部办公处所均为5A级写字楼，交通便利。挑高式前厅大堂豪华气派、花园式办公空间优雅舒适。在路浩，你有权利享用健身房、咖啡厅、保健室和专属衣柜，在优越的环境中获得幸福感！完善的培训保障路浩作为业务板块最为齐全的机构，拥有完善规范的岗前和在岗培训体系，注重员工职业素质、业务能力和管理技能的综合培养。在路浩，你有条件受到最全面的执业培训，被快速地培养成行业大咖！路浩是一家什么样的公司？路浩集团是综合性涉外知识产权服务机构，主要从事专利、商标、著作权等知识产权的申请、维权、咨询、评估、经营和交易服务，总部位于北京，在武汉、上海、广州、深圳、西安、保定、重庆和长沙设有分部，现有员工500余名。路浩是北京市专利代理师协会会长单位，中华全国专利代理师协会副会长单位；连续多年被评为全国最高星级专利代理机构和全球优秀法律服务机构；连续多年位居北京市专利申请代理量第一；主持编著了多部企业教材、行业教材和行业指导标准。路浩完整的组织构架、全面的业务范围、显著的业务特色、优秀的业务团队、广泛的服务对象和骄人的企业荣誉深受社会各界好评。招聘程序简历投递方式1、邮箱投至 hr@cnkip.com方式2、智联搜索“北京路浩”在线投递电话沟通方式1、电话咨询 010-62197905面试笔试远程视频在线答题录用确认公司信息地址北京总部：丰台区万丰路68号银座和谐广场写字楼20、21层武汉分部：东湖高新区光谷大道41号现代光谷世贸中心F栋24楼网站：www.cnkip.com电话：010-62197905', 'https://www.zhaopin.com/jobdetail/CC822875230J40326582811.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4554, '游戏运营', '美潮美家电子商务有限公司', '2025-07-27 01:24:09', '4000-6000元', '沧州-运河区', '电子商务', '100-299人', '不需要融资', 'CC627592680J40817933508', '岗位内容：<br>1. 负责电商平台日常运营，信息填写、标题优化，包括商品上架、价格维护、订单处理等工作；<br>2. 协助上级领导完成某些项目的整体规划、活动策划、营销和推广、及管理等工作；<br>  3.管理店铺后台促销营销玩法工具，设置店铺基础活动，监控库存和销售状况，及时调整并反馈；  <br>4.定期整理检查商品，维护店铺商品和页面的长期跟踪维护；', '河北美潮美家电子商务有限公司始创于2011年，秉承“以美立心、以潮铸魂、以家传情”的企业内涵，专注于居家收纳类产品的整合研发、销售运营，致力于为全球消费者提供品质可靠、价格亲民的家居臻品，助力“让万家灯火更美好”的使命实现。作为集供应链管理、全渠道销售、数字化服务于一体的综合性电商企业，公司始终以消费者满意为核心，持续赋能实业、链接全球资源，矢志成为行业领先的居家收纳品牌。立足华北，辐射全球公司成立于2011年，起步北京，2015年总部定于河北黄骅市，并在沧州（2021年）、天津（2024年）设立分支机构，业务版图覆盖国内外主流电商与新媒体平台，包括天猫、京东、拼多多、亚马逊、TEMU、TIKTOK、抖音、小红书等。凭借不断成熟的管理体系，专业的运营梯队建设，各渠道业务都在有序增长，公司稳居河北省家居电商行业前列。以文化驱动发展，以责任凝聚力量公司坚守“真诚为本、热爱为帆、利他为先”的核心价值观，倡导“敢拼敢闯敢追梦，有情有义有担当”的企业精神，推行“顾客满意、员工幸福、伙伴共赢”的发展理念，并不断践行如下方针：•客户为先：以品质与创新为根基，打造美好生活体验；•员工为本：提供多元化学习资源与职业发展通道，构建温暖成长型团队；•生态共赢：为供应商提供海内外一站式销售解决方案，携手合作伙伴共创价值。未来，美潮美家将继续以“创美好生活，领行业潮流，筑幸福家园”为初心，深耕家居领域，用行动诠释责任，用成果回馈信任，为全球家庭带来更多美好与喜悦。', 'https://www.zhaopin.com/jobdetail/CC627592680J40817933508.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4555, '电话销售', '杭州长贤企服网络科技有限公司', '7月24日', '8000-16000元', '杭州-滨江区', '互联网', '20人以下', NULL, 'CCL1501860780J40935382704', '职位描述：<br>1、负责丁香园旗下医疗行业人力资源服务平台“丁香人才网”的推广和销售；<br>2、对接医院、药企等医疗大健康机构招聘负责人，分析客户需求，为客户提供招聘解决方案；<br>3、建立良好的客户关系，提供涵盖售前、售中、售后的专业服务；<br>4、负责订单、应收账款管理，促进客户续费；<br>5、执行公司各项销售政策，达成业绩目标。<br>（电销为主，网销为辅）<br>任职条件：<br>1、大专以上学历，普通话标准，逻辑清晰表达能力佳；<br>2、热爱销售工作，具有医药、生物专业、网络招聘、或人力资源等相关行业工作经验者业优先；<br>3、对工作需要有很强的责任心，进取心，以及出色的学习能力、抗压能力和团队合作精神；<br>4、熟练应用办公软件。<br>上班时间:周一至周五上班8:30-17:30（午休:12:00），周末双休，国家法定节假日休息<br>薪资待遇:<br>无责底薪5-6K+销售提成+年终奖+新客激励，综合收入8K-1.3W<br>入职缴纳五险一金，入职前两周以培训为主。<br>发展空间:准上市公司，各项竞升机制完善', NULL, 'https://www.zhaopin.com/jobdetail/CCL1501860780J40935382704.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4556, '统计员', '中国人寿保险股份有限公司南京市分公司收展营销服务部', '6月25日', '3000-4000元', '南京-鼓楼区', '保险,保险', '10000人以上', '已上市', 'CC606591220J40713338715', '工作时间：<br>8:30-17:00（午休两小时11.30-13.30）<br>周末双休<br>节假日正常放假<br>工作内容：<br>1，维护招聘网站，筛选合适的简历，邀约面试。<br>2，为入职人员签订合同<br>3，为离职人员签订离职合同<br>任职资格：<br>1，年龄21—40周岁<br>2，会使用基本的Office办公软件<br>3，做事认真负责，有责任心，善于沟通<br>职位福利：定期团建、交通补助、大牛带队、不加班、周末双休、弹性工作、团队气氛活泼、朝九晚五<br>职位亮点：双休，法定假日，', '中国人寿保险（集团）公司是中央管理的国有大型金融保险企业，前身是成立于1949年的原中国人民保险公司。公司已连续20年入选《财富》杂志“世界500强”，2022年位列第40位，较2020年提升5个位次。在此前世界品牌实验室发布的2022年“中国500最具价值品牌”，品牌价值高达人民币4525.39亿元，在中国保险业蝉联第一。中国人寿保险股份有限公司江苏省分公司（简称“江苏国寿”）是中国人寿保险（集团）公司核心成员——中国人寿保险股份有限公司在江苏的分支机构。自1996年产寿险分业经营以来，公司主动融入江苏经济社会发展大局，承载初心使命，一路攻坚克难，始终保持着中国人寿系统、江苏寿险市场“双领先”地位，在服务“强富美高”新江苏建设中积极发挥行业龙头的引领作用。', 'https://www.zhaopin.com/jobdetail/CC606591220J40713338715.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4557, '运营助理/专员', '中科合肥技术创新工程院', '5月14日', '7000-10000元', '合肥-蜀山区', '社团/组织/社会保障', '100-299人', NULL, 'CCL1463592720J40805475208', '2014年6月，合肥市人民政府与中国科学院合肥物质科学研究院合作共建合肥创新院，推进科技成果产业化。<br> 合肥创新院坚持产业链创新链协同发展，努力构建“技术孵化、技术转化、企业孵化、创业投资”四位一体的创新机制，建立起创新链、产业链、人才链、资本链、服务链五大要素紧密融合的“科创+产业”生态体系。<br> 聚焦数字经济和生命健康领域，合肥创新院在智能网联新能源汽车、数字乡村、低空经济、精准肿瘤医疗，中医药现代化等方向重点布局、持续发力，构建产业链创新链协同发展的“创新院模式”。<br>1.岗位名称：运营服务专员<br>2.招录人数：1人<br>3.学历需求：本科及以上学历<br>4.专业要求：企业管理、市场营销、广告学、新闻传播等相关专业本<br>5.岗位职责：<br>1）品牌维护与推广<br>制定SIGMA学院品牌年度、季度推广计划，结合产业热点及流行趋势，动态调整活动方案，优化品牌传播策略。统筹品牌VI设计、宣传语创意及形象定位，输出品牌宣传物料、案例包装等标准化内容；协调跨部门合作，确保品牌宣传内容的一致性；主导新媒体矩阵（公众号、短视频、行业媒体等）优化提升与内容策划、运营，提升品牌行业影响力。<br>2）运营策划与策略<br>负责SIGMA学院系列活动的全流程运营策划、执行与效果跟踪，包括线上线下宣传渠道搭建、活动资源整合、专项活动创意提案策划，活动落地执行、活动效果评估；建立与已落地项目/潜在项目走访计划，参与企业科创服务、项目招引、生态对接等。了解熟悉产业政策、场景服务、科技招商等工作内容等，协助项目落地转化及合作达成。<br>3）战略合作与拓展<br>构建并动态维护第三方资源库，主导SIGMA学院系列品牌服务第三方商务谈判及战略合作协议落地执行，精准匹配品牌资源赋能SIGMA学院学员、落地项目/企业，提升跨界品牌合作效能。<br>4）领导交办的其他工作。<br>6.任职要求：<br>1)年龄不超过35周岁；<br>2)熟练使用Word、Excel、PPT、PS、AI等办公软件；<br>3)工作认真负责，具备优秀的学习能力、逻辑分析能力、组织协调能力和较强的文字功底；有较强的计划、执行、协调及应变能力，团队协作意识强，能适应高强度工作，具有较强的抗压及危机处理能力； <br>4)有3年以上品牌全案策划经验，有成功活动执行案例，4A广告公司或主导大型项目经验者优先。 <br>7.薪资待遇（范围）：7K-10K/月<br>备注：本岗位与安徽中科科创企业管理服务有限公司（中科合肥技术创新工程院全资子公司）签订劳动合同。', NULL, 'https://www.zhaopin.com/jobdetail/CCL1463592720J40805475208.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4558, '猎头顾问', '恒伦口腔医疗科技集团股份有限公司', '7月28日', '4000-8000元', '太原-杏花岭区', '医院,专用设备制造,卫生服务', '1000-9999人', '未融资', 'CC455468430J40801933312', '1、负责患者全流程接待，配合市场部开展市场活动；<br>2、了解患者的就诊情况，与患者进行深入沟通并提供专业服务与咨询；<br>3、具备良好的服务意识和团队合作精神。<br>工作地点：太原市内均可分配<br>职位福利：餐补、带薪年假、节日福利、五险', '精于专业、敢于挑战、乐于服务的您如果您认可“以患者为中心”，如果您希望拥有“安全、专业、舒适”的诊疗氛围，请加入我们，恒伦口腔会让每一个精于专业的您有安心的保障，每一个敢于挑战的您有宽广的舞台，每一个乐于服务的您有应得的回报。长期陪伴的伙伴——稳定的经营是民营医疗机构的生命线，长期以来恒伦稳扎稳打，努力为所有恒伦员工打造长期信赖、依靠的“家”。全国连锁——恒伦是一家全国连锁的口腔医院。总部在质量管控、经营模式、品牌传播等方面持续探索，为旗下每一家机构提供支持。您无需担心单打独斗，还能够拥有丰富的内外部交流机会。产业链完整的口腔产业集团——除了口腔医疗，恒伦还拥有义齿加工、口腔教学培训、科研基地等多元化模块。从总体把控医疗质量，共同探索未来口腔医疗新路径。对您而言，您也将拥有产业链条上的多种资源，帮助您完成职业梦想。', 'https://www.zhaopin.com/jobdetail/CC455468430J40801933312.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4559, 'BD经理', '京东集团', '6月11日', '1-2万', '广州-海珠区', '互联网,电子商务', '10000人以上', '已上市', 'CC192921310J40744375309', '岗位说明：<br>1.负责地区物流市场开拓与销售工作，有仓配业务及大件&amp;快运商品B2C、B2B及整车业务相关经验优先；<br>2.具有方案营销的的工作经历，有成功的行业商家营销案例；<br>3.能与客户保持良好沟通，实时把握客户需求，为客户提供主动、热情、满意、服务，与客户实现共赢；<br>4.根据公司产品、价格及市场策略，独立处置询盘、报价、合同条款的协商及合同签订等事宜。在执行合同过程中，协调并监督公司各职能部门操作，推动合作的进展以及落地；<br>5.具备较强的市场拓展及新客户开发能力，定期向公司提供市场分析报告和个人工作日报及周报。<br>任职资格：<br>1.大专及以上学历，物流、市场营销相关专业优先；<br>2.优秀的沟通和谈判能力，能够和公司外部和内部同事有效协调，沟通；<br>3.市场分析能力，快速准确的定位客户、产品、资源等；<br>4.具备较强的市场拓展及新客户开发能力；<br>5.富有活力和激情，为人开朗热情，能够承受较大的工作压力和销售业绩要求，对项目及工作有责任心。', '京东（JD.COM）是中国领先的技术驱动型电商，并致力于成为领先的以供应链为基础的技术与服务提供商。其尖端的零售基础设施使消费者可以随时随地购买所需的任何商品。京东向合作伙伴、品牌商和多个领域开放了技术和基础设施，作为零售基础设施服务商推动各行各业生产效率的提升和创新。京东也是纳斯达克100指数的一员和财富全球500强企业。', 'https://www.zhaopin.com/jobdetail/CC192921310J40744375309.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4560, '游戏推广', '无锡余音缭绕文化有限公司', '7月23日', '1-1.5万', '齐齐哈尔-建华区', '文化艺术/娱乐', '10000人以上', NULL, 'CCL1385391730J40867679215', '岗位职责：<br>1. 在TT语音平台公会担任游戏嘉宾，进行线上居家办公，提供游戏陪打服务（不露脸）。<br>2. 接客户点单，完成游戏任务，确保服务质量。<br>3. 通过游戏互动过程获取礼物，维护良好的客户关系。<br>岗位要求：<br>1. 年龄18~39周岁，学历不限，工作经验不限。<br>2. 熟悉游戏王者最佳，技术要求低（王者黄金，和平黄金即可）。<br>3. 遵循诚信原则，维护绿色聊天互动环境，不涉及任何低俗内容。<br>薪资待遇：<br>1. 新人一周可达到1200+，老员工熟练后一周可达5000+。<br>2. 薪资周六周日平台自提，每个月15号公会发放工会福利（包括游戏厅时长奖励+礼物情况奖励）。', NULL, 'https://www.zhaopin.com/jobdetail/CCL1385391730J40867679215.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4561, 'BD经理', '爱才集团有限公司', '7月24日', '1-1.5万', '武汉-洪山区', '人力资源服务', '500-999人', '未融资', 'CCL1246426550J40763007510', '岗位职责<br>1、负责新商户开拓，与商户进行治谈合作与签约，跟进上线流程;<br>2、整合商圈资源，为商户提供整合营销方案;<br>3、根据商户需求制定合理的运营方案，提供促销活动、外卖品设计与运营支持，通过短视频及内容营销进行抖音平台分发，维护客情关系，做好交易额提升优化;<br>岗位基本信息：<br>薪资架构：无责底薪4480+提成（提成根据团购券的到店总核销量来，在职同学提成高的一个月7~8w，低的小几千，具体需要看个人情况）<br>福利待遇：入职及缴纳六险一金按照当地最高比例12%进行缴纳<br>工作时间：10:00-19:00 周末双休，节假日均正常休息<br>补贴：餐补每月320，交通补助每月500(实报实销）', '爱才集团总部位于中国杭州国际人力资源服务产业园11-15层，是一家致力于人力资源全产业链深度开发的大型人力资源集团。集团依托全国的服务网络、先进的互联网平台和强大的数据支撑，为市场提供：服务外包、人事服务、猎头招聘、共享平台、产业园运营、职业教育、管理咨询等服务产品。历经多年的创新发展，目前已在杭州、上海、北京、香港等10多个城市设立分支机构，服务网络遍及全国300多个城市，合作院校100多家，招聘网点超过500个，年供应能力10万人以上。', 'https://www.zhaopin.com/jobdetail/CCL1246426550J40763007510.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4562, '售后客服', '中国人寿保险股份有限公司郑州市分公司', '7月19日', '4000-8000元', '郑州-二七区', '保险', '1000-9999人', '已上市', 'CC253842210J40741609302', '符合年龄：20-45岁 大专及以上学历 感兴趣可投递投递简历或者来电话联系<br>待遇：<br>1.薪资=底薪+绩效+津贴，新人平均月薪4000~8000元/月；<br>2.享受国家法定节假日；<br>3.所有员工均有带薪旅游机会；<br>4.公司提供医疗保障、养老保障、意外保障等<br>5.舒适的办公环境，欢快的工作氛围；<br>岗位职责：<br>1.完成公司客户售后服务，加强客户粘性<br>2.服务客户并进行二次拓展<br>3.按照公司活动要求完成客户服务对接，完成各项公司活动要求<br>4.解决客户问题，提高公司对客户的服务质量<br>任职要求：<br>1.熟练运用办公软件；<br>2.勤奋好学、勇于挑战，愿意学习新知识接受新理念；<br>3.优秀毕业亦可。', '中国人寿保险（集团）公司是目前国内最大的综合性保险集团，是国务院100%控股的世界500强副部级央企。下设中国人寿保险股份有限公司、中国人寿资产管理有限公司、中国人寿财产保险股份有限公司、中国人寿养老保险股份有限公司等多家公司和机构，业务范围全面涵盖寿险、财产险、养老保险、资产、实业投资、海外业务等多个领域。中国人寿是中信证券第二大股东、广东发展银行第一大股东、民生银行、中粮期货、南方电网第二大股东。中国人寿郑州市分公司招募首批新型大学生服务团队中国人寿郑州市分公司一直服务于郑州市城乡建设，在郑州市所有县区设立分支机构，在全市80%以上的乡镇设立服务部，目前服务窗口正在向村级延伸。自2001年起，开始陆续为河南省省直机关以及郑州市220万城镇职工、城镇居民提供大额补充医疗服务，具有常年经营意外保险、健康医疗保险以及政府委托经办业务等丰富的管理经验和能力。2011年，在郑州市政府的支持下，中国人寿郑州市分公司创新性地经办了新农合业务，并于2013年开始承办农村居民大病保险业务，服务于430万农村居民，“郑州模式”得到全国广泛关注。', 'https://www.zhaopin.com/jobdetail/CC253842210J40741609302.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4563, '培训师', '成都市全友家私销售有限公司', '7月12日', '5000-9000元', '汕头-潮阳区', '耐用消费品,耐用消费品', '1000-9999人', '未融资', 'CC349356610J40277590812', '职位职责：<br>1、通过分析门店的培训需求，对门店销售人员实施产品知识、销售技巧等培训，并推进训后培训效果的达成，提升销售人员能力；<br>2、根据培训计划，负责组织区域性培训、大型省级培训，完成培训计划的制定和组织，并担任相关授课任务，开展培训效果调研；<br>3、负责对公司的相关政策、模式向终端市场进行培训；<br>4、根据培训需求，开发并更新培训课件，编写培训教材，不断优化课程体系。<br>任职要求：<br>1、22岁以上，男女不限，性格阳光外向，形象气质良好；<br>2、大专及以上学历，有家居建材行业销售、培训或者促销活动经验者优先；<br>3、沟通表达能力出色，有主持及演讲经验优先；<br>4、熟练操作office办公软件，适应能力强，学习能力强。<br>能适应长期出差（广东/海南）。<br>职位福利：绩效奖金、定期体检、五险一金、餐补、房补<br>', '全友，创立于1986年，秉承“创造美好家居生活”的企业使命，致力于为每一位用户提供一站式绿色、健康和个性化的家居生活解决方案，现已成为集研、产、销一体的大型现代化家居企业。公司产品包括全屋定制家具、沙发、床垫、软床、墙面家居、橱柜、卫浴、窗帘和板式套房家具，满足家庭、商用等多种场景的家居需求，赢得“全友家居,一站配齐”的美誉。公司在行业率先打造全流程绿色产业链，拥有成都、潜江和清丰三大智能化生产基地，构建遍布全国的渠道和服务网络，为用户提供高效便捷的家居设计、物流、安装以及售后服务，“幸福服务365”服务品牌深得用户信赖。公司一直坚持绿色经营的发展理念，将绿色经营贯穿于研发、采购、生产、物流和营销等企业全价值链环节，“绿色全友,温馨世界”已经成为全友品牌的价值追求和经营信条。公司践行“鱼水文化”，积极承担社会责任，持之以恒为社区和社会做贡献，生动诠释了“全友是鱼，社会是水，全友感恩、回馈社会而永续”的企业文化内涵。', 'https://www.zhaopin.com/jobdetail/CC349356610J40277590812.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4564, '游戏运营', '成都盛禾嘉诚文化传媒有限公司', '7月21日', '5000-8000元', '成都-青羊区', '文化艺术/娱乐', '20-99人', '不需要融资', 'CCL1501272650J40821862508', '岗位职责： <br>1. 协助运营团队完成日常运营工作，包括数据整理、文档撰写、活动策划等； <br>2. 负责运营相关数据的收集、整理与分析，制作运营报表； <br>3. 协助运营活动的执行与跟进，确保活动顺利进行； <br>4. 与各部门沟通协调，确保运营工作高效推进； <br>5. 维护后台运营数据 追踪时事热点<br>任职要求：<br>1. 学历要求：大专及以上学历，优秀者可放宽到高中学历<br>2. 可接受无经验 <br>3. 熟练使用Office办公软件（如Excel、Word、PPT）<br>薪资范围：4500＋提成 综合可达4-6k <br>工作时间：朝九晚六 周末大小休<br>2. 福利待遇：五险一金、带薪年假、节日福利、定期团建等； <br>3. 晋升空间：完善的晋升机制，提供职业发展机会。', '成立于2025年3月3日，一般项目：组织文化艺术交流活动；技术服务、技术开发、技术咨询、技术交流、技术转让、技术推广；广告制作；广告发布；广告设计、代理；图文设计制作；摄像及视频制作服务；专业设计服务；企业形象策划；知识产权服务（专利代理服务除外）；市场营销策划；互联网数据服务；网络与信息安全软件开发；集成电路设计；软件开发；物联网技术研发；信息系统集成服务；平面设计；摄影扩印服务；其他文化艺术经纪代理。（除依法须经批准的项目外，凭营业执照依法自主开展经营活动）', 'https://www.zhaopin.com/jobdetail/CCL1501272650J40821862508.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4565, '商务专员', '搏世因(北京)高压电气有限公司', '7月1日', '8000-12000元', '北京-密云区', '电气机械/电力设备,工业自动化', '100-299人', '未融资', 'CC218751730J40806038315', '岗位职责及职位要求：<br>1、知识要求：精通投标、客服、市场知识；掌握公司制度、管理体系、财务知识；了解仓储物流知识、电力产品技术标准相关知识、相关法律法规等<br>2、 负责在规定时间内，依据招标技术文件编制标书，跟踪投标、开标、及退还保障金的工作。<br>3、 负责按照客户技术规范要求与技术对接图纸 <br>4、 根据发货时间负责出口报关文件《发票》、《箱单》拟制，负责《原产地证》办理；<br>5、 根据项目要求负责与货代对接出口发货方案<br> 6、其他商务内勤工作<br> 7、硬性条件：英语6级以上，口语交流熟练或者俄语熟练<br>薪资福利：<br>职位福利：8000-12000元；五险一金、年底双薪、包吃（三餐）、带薪年假、节日福利、通讯补助、优秀员工奖金、绩效奖金等', '搏世因（北京）高压电气有限公司是主要从事高压电气、新型材料、绝缘状态在线监测、防火涂料及自动化领域的开发、生产、销售和服务为一体的高新技术企业。公司拥有雄厚的技术力量，先进的生产设备，完备的检测系统，快捷的信息交流，完善的服务体系。公司目前拥有教授级高工、博士、硕士和学士等各类专业人才30余人，具有较强的研发能力。公司生产的产品遍布全国，行业涉及供电、火电、水电、冶金、铁路、石油、石化、水泥、矿山等领域。公司位于北京市中关村产业园密云园三个厂区，公司主营玻璃钢干式套管、油色谱在线监测、GIS局放在线监测、耐火、耐磨、保温材料及防火涂料等产品，自投入运行以来，以运行稳定、可靠性高、免维护等诸多优点，获得广大用户的好评和权威专家的认可，为电力系统向无油化、小型化、免维护及实现智能化操作和监控做出重大贡献。', 'https://www.zhaopin.com/jobdetail/CC218751730J40806038315.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4566, '猎头顾问', '锐识咨询服务(北京)有限公司', '7月18日', '8000-13000元', '北京-海淀区', '证券/期货,咨询服务', '100-299人', '未融资', 'CC322046310J40192401614', 'Responsibilities<br> <br>·       Data analysis<br> <br>·       Background research on companies and sectors<br> <br>·       News / research summaries<br> <br>·       Database creation and maintenance<br> <br>·       Industry / thematic research<br> <br>·       Benchmarking exercises for companies, industries and markets <br> <br>·       Other ad-hoc research tasks <br> <br> <br> <br>Required Background<br> <br>·       Fluent in Japanese<br> <br>·       Strong Excel skill<br> <br>·       Good command of English and financial/accounting experience will be a plus<br> <br>·       A self-starter, highly motivated, detail oriented and willingness to work diligently<br> <br> <br>职位福利：周末双休、加班补助、带薪年假、补充医疗保险<br>', 'Moody\'\'s Analytics Knowledge Services is a wholly-owned subsidiary of Moody\'\'s Corporation(NYSE:MCO), the leading provider of offshore research and analytics services to the global financial and corporate sectors. We have consistently been ranked#1 in our space by multiple independent customer satisfaction surveys. Our clients include leading bulge-bracket financial institutions, Fortune 100 corporations, mid-tier companies, boutique investment banks, and funds.We support over 200 institutional clients through our team of 2500+ employees. Our 9 delivery centers are located close to our clients and in proximity to scalable talent pools. Our clients have saved over USD1.9 billion over the past 12 years, by using our services to enhance front-office efficiency.Please visit our website for more details: http://www.maknowledgeservices.com/', 'https://www.zhaopin.com/jobdetail/CC322046310J40192401614.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4567, '游戏推广', '成都萌小玺文化传媒有限公司', '7月29日', '4000-6000元', '上海-杨浦区', '新媒体', '10000人以上', NULL, 'CCL1486511100J40870368815', '在家上班。不限制位置，不限制英雄，不包技术，目前钻石段位，在家打游戏躺着赚米的工作来啦。不露脸不是直播岗位。', '成都萌小玺文化传媒有限公司，成立于2024年，位于四川省成都市，是一家以从事文化艺术业为主的企业。成都萌小玺文化传媒有限公司，成立于2024年，位于四川省成都市，是一家以从事文化艺术业为主的企业。', 'https://www.zhaopin.com/jobdetail/CCL1486511100J40870368815.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4568, '项目经理/主管', '四川川贝科技有限公司', '2025-07-27 01:13:20', '9000-18000元', '吉安-吉州区', '互联网', '20-99人', '不需要融资', 'CCL1462581080J40775052105', '岗位内容：<br>1. 负责项目从立项到验收的全过程管理，确保项目按时交付、质量达标；<br>2. 制定项目计划和预算，并监督执行情况，及时解决项目中出现的问题；<br>3. 协调内部各部门资源，确保项目进度和质量；<br>4. 与客户沟通协调，及时反馈项目进展和问题。<br>任职要求：<br>1. 能独立承担项目管理任务；<br>2. 熟悉项目管理流程和项目管理工具；<br>3. 拥有良好的沟通、协调能力和团队合作精神；<br>4. 学历不限，相关专业优先考虑。', '四川川贝科技有限公司于2023年3月成立，公司位于四川省成都市，主要从事软件开发，网页开发，app小程序开发，公司致力于产业，切实推进与各大企业、厂家的合资、合作，用产业化发展的思路服务于社会和广大用户。', 'https://www.zhaopin.com/jobdetail/CCL1462581080J40775052105.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4569, '培训师', '广州通用职业技术学校', '6月23日', '4000-6000元', '广州-从化区', '学校/学历教育,学校/学历教育', '1000-9999人', NULL, 'CC427809630J40631499201', '一、招聘条件<br>1、中西面点等相关专业，大专及以上学历。<br>2、负责中西面点专业的相关课程教学。<br>3、具有符合岗位要求的专业技能和工作能力。<br>4、热爱教育事业，有良好的的职业素养，具有较强的表达能力和沟通能力。<br>5、相关经验及持教师资格证者优先。<br>\n<br>二、薪酬福利<br>1、正式工月薪 4000-6000元/月，试用期1个月。（实习生3500-3800元/月）。<br>2、五险一金、双休、带薪寒暑假、节日礼金、生日礼金、房补、交通补贴。<br>3、系统的培训、晋升制度。<br>\n<br>\n<br>学校地址：广州市从化区广从北路483号（广州地铁十四号线“赤草站”C出口，转乘5号公交车至“元洲岗”到达）\n<br>\n<br>欢迎有理想、有能力、有责任感并热衷于教育事业的朋友咨询和投递简历。（直接投递简历即可）<br>职位福利：五险一金、交通补助、周末双休、住房补贴、节日福利、通讯补助  <br>', '广州通用职业技术学校行政隶属广州市教育局，原校址位于天河区龙洞华美路，现在新校区位于广州后花园从都风景区；采用现代化建设风格，科技感十足，引领潮流，走在教育行业的前端。自办学以来，学校以严格的管理、良好的校风、优良的教学质量深受社会好评，多次被上级主管部门评为教育先进单位。学校教学、实操、生活服务设施齐全，校内建有豪华的航空专业机舱实训室、品牌汽车实训室，电子竞技实训室，电梯维护实训室、舞蹈房、琴房、美容实操室和现代化的学生餐厅、标准的体育运动场等，实行现代化的“6S\\\\\"管理。学校十分重视实训教学。投入3000多万建立了“航空服务”、“电子竞技”、“城市轨道”、等五大实训中心，开设航空服务、电子竞技、汽车维修、电梯安装与维修、美容美体、城市轨道交通运营管理、会计等二十几个专业。近几年来学校办学质量不断提高，毕业生就业率达98%以上。同时，我校师生多次在全省乃至全国各种技能比赛中屡次获得优异成绩。学校拥有一支思想政治素质高，教学实践能力强的教师队伍。教职工200余人，并聘有各高校经验丰富的教授任课。学校坚持“开拓创新，服务社会”的办学宗旨，在“博学、慎思、勤勉、奋进”校训鞭策下，不断深化教学体制改革，积极开拓校企业人才培训新途径。', 'https://www.zhaopin.com/jobdetail/CC427809630J40631499201.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4570, '管培生/储备干部', '吉安市新庐陵国有资产经营有限公司', '7月24日', '8000-10000元', '吉安-吉水县', '政府/公共事业', '20-99人', '不需要融资', 'CCL1499336450J40803649608', '1、本科及以上学历应届毕业生，英语六级，市场营销专业者优先；<br>2、具备良好的销售技巧和市场敏锐度，具有较强的沟通、协调能力和抗压能力；<br>3、负责公司销售业务，主要包括与客户沟通，了解客户需求并提供相应的解决方案。', NULL, 'https://www.zhaopin.com/jobdetail/CCL1499336450J40803649608.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4571, '风电工程师', '研能(天津)电力技术有限公司', '7月28日', '8000-12000元·13薪', '合肥-瑶海区', '人力资源服务', '100-299人', NULL, 'CCL1483187040J40804192903', '风电运维工程师', NULL, 'https://www.zhaopin.com/jobdetail/CCL1483187040J40804192903.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4572, '电话销售', '北京融锦信息科技有限公司', '6月19日', '5000-10000元', '石家庄-长安区', '计算机软件,计算机硬件,IT服务,互联网', '20-99人', '未融资', 'CCL1502860780J40776180812', '岗位职责：<br>1、根据企业主营产品在行业市场拓展客户群体，通过挖掘分析客户需求，结合产品，完成月度、季度、年度销售任务  2、通过市场分析，卖点分析，提升销售过程中话术专业度，增强客户信任感。 3、客户关系维护，通过定期回访跟进客户，了解客户需求情况，增加新合作客户，有效提升产品销售。', '1、本公司是一家集软件销售，技术服务于一体的科技企业，成立于2024年1月，行业经验10年以上，目前有几百家合作单位，致力于信息化行业提供数字化产业一站式方案解决商。 2、单位待遇：周末双休，节假日休息，带薪年假，假期礼品，工作时间：冬季9：00-17:30，夏季9:00-18:00，办公环境舒适放松，同事好相处，单位氛围好', 'https://www.zhaopin.com/jobdetail/CCL1502860780J40776180812.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4573, '游戏推广', '无锡余音缭绕文化有限公司', '7月25日', '1-1.3万', '咸宁-崇阳县', '文化艺术/娱乐', '10000人以上', NULL, 'CCL1385391730J40867150315', '岗位职责：<br>1. 在TT语音平台公会担任游戏嘉宾，进行线上居家办公，提供游戏陪打服务（不露脸）。<br>2. 接客户点单，完成游戏任务，确保服务质量。<br>3. 通过游戏互动过程获取礼物，维护良好的客户关系。<br>岗位要求：<br>1. 年龄18~39周岁，学历不限，工作经验不限。<br>2. 熟悉游戏王者最佳，技术要求低（王者黄金，和平黄金即可）。<br>3. 遵循诚信原则，维护绿色聊天互动环境，不涉及任何低俗内容。<br>薪资待遇：<br>1. 新人一周可达到1200+，老员工熟练后一周可达5000+。<br>2. 薪资周六周日平台自提，每个月15号公会发放工会福利（包括游戏厅时长奖励+礼物情况奖励）。', NULL, 'https://www.zhaopin.com/jobdetail/CCL1385391730J40867150315.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4574, '项目经理/主管', '沧州金风企业管理咨询有限公司', '10月17日', '6000-12000元', '沧州-海兴县', '企业服务', '20人以下', '未融资', 'CCL1477327690J40758094515', '任职要求：<br>1. 具备优秀的项目管理和咨询能力，能够独立完成项目管理。<br>2. 具备较强的分析、沟通和协调能力，能够与客户和团队开展有效合作。<br>3. 人才需具备工程施工经验，具备一级、二级建造师。  4.为业主提供工程项目的施工全过程咨询服务。', NULL, 'https://www.zhaopin.com/jobdetail/CCL1477327690J40758094515.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4575, '日语翻译', '上海市创优中小企业人才服务中心', '3月27日', '7000-8000元·13薪', '天津-东丽区', '人力资源服务', '20-99人', NULL, 'CC497244130J40754770512', '24~32岁，大专以上学历（本科以上优先），日语精通，工作经验3年以上优先<br>身体健康，品行端正，无不良嗜好；<br>良好的沟通及表达能力，能以客户服务至上为本，积极进取；<br>做事认真踏实，高度的工作意识与责任感，具有良好的团队精神；农林，生物，环境类专业优先<br>工作内容：1. 根据签约客户的服务内容，现场指导作业者，按照既定方案实施日常监控，据实调整对策布局促进卫生环境效果改善。<br>2. 采集监控点实绩，比对数据库，编制分析报告，与客户讲习交流。<br>福利及休息休假：<br>l 法定福利：用人当地规定(基本)五险一金l 各类补贴：<br>根据级别员工可享受定额的通讯、交通、午餐等补贴<br>l 专业培训：日本研修有薪休假：按国家与地方标准给予<br>地点，天津市河北区海河东路', NULL, 'https://www.zhaopin.com/jobdetail/CC497244130J40754770512.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4576, '网络客服', '安徽医艾康健康科技有限公司', '7月25日', '6000-8000元', '合肥-蜀山区', '电子商务,电子商务', '20-99人', NULL, 'CCL1270426370J40769244610', '岗位职责.<br>1.利用直播客资加微邀约销售;<br>2.负责微信中客户的转化和成交，保持良好的客户关系;<br>3.参与团队会议，分享销售技巧和客户反馈:<br>4.维护和更新客户资料，确保信息的准确性,<br>行政班次，单双休，公司提供客户。', '一、公司简介医艾康旗下全资子公司-杭州美美橙健康科技有限公司，是一家致力于为消费者解决医疗健康问题和提供健康生活方式的的服务机构。公司秉承着打造健康知名品牌的产品理念，和为消费者提供更精确、更透明、更专业的消费医疗服务理念，全力打造出医艾康医疗健康品牌。公司愿景是为消费者营造健康理想生活家，聚焦医疗健康领域，促进健康服务发展，打造医疗健康产品，为消费者提供更美好的生活和精准的医疗健康服务。公司使命是立足于健康领域，以消费者为中心，提供一站式健康生活方式，服务商向社会公众提供全球医疗健康产品及全家医疗健康管理指导，致力于成为领先的健康管理服务供应平台，立志完成“一站式全家健康服务商”的企业使命。最终实现为全国消费者提供健康的生活方式，满足消费者对健康生活方式的追求。公司办公环境舒适，设备优良，软硬件设备齐全，一站式的服务设施，有独立的茶水间、吧台。公司拥有完善的人才培养机制，致力培养专业优秀人才，入职带薪培训。工作时间人性化。公司价值观是成就、分享、尊重、传承。公司以人才作为公司最大的财富。二、公司架构与板块简介公司以扁平化组织结构开展经营协作，以运营、产品为维度分为四大事业部。1、O2O运营事业部在全国范围基于美年、爱康等全国性产品为基础，同时切入区域O2O以名流、普惠等区域性高端产品为填充，开展健康服务新零售O2O业务，依托健康资源实现跨区域的共享配置。目前，以医疗体检为切口，进一步面向医美、口腔、疫苗等医疗服务全品类，2020年单品类扩展有望在一年时间做到品类前三。2、B2C运营事业部以现有市场品牌为切入点，后期将上线“医艾康”品牌，通过传统健康品类B2C运营，打造专属定位的卖场型旗舰及渠道品牌。 3、OTO产品部以医疗体检为切口，面向医美、口腔、疫苗等医疗服务全品牌，围绕扩展全品类为目标开展商务拓展。主要业务为：维护品牌方关系，积极争取政策资源，推动O2O网点的紧密合作与支持；挖掘产品深度与营销卖点；分析该品类的产品趋势及方向，并围绕产品做好内容营销输出。 4、B2C产品部具备电商渠道代理商产品采购部门属性。从品牌商务洽谈、品类拓展、产品梳理、商品管理、采销一体、周转管理整套全链路的大产品部门。主要业务为：持续准确找到需求产品及品牌，为公司实现定位方向范围内的产品需求，最大化击穿价格并争取更好的品牌商政策支持，维护供应商关系形成良性合作，对于产品生命周期负责，形成有效的商品管理台账。', 'https://www.zhaopin.com/jobdetail/CCL1270426370J40769244610.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4577, '资料管理', '博岳通信', '7月21日', '5000-10000元', '西安-雁塔区', '运营商/增值服务,IT服务,通信/网络设备', '10000人以上', NULL, 'CC351377410J40757326201', '档案管理员！ 我们有五险 ，食宿，我们不加班 ，我们有培训！周边环境好，办公氛围好！月入6000+！月入过万不是梦<br>工作内容：对支付宝消费档案进行管理<br>工作时间：早9晚6<br>休息时间：6天 灵活调休<br>薪资：6000-1w<br>福利：五险 + 提供食宿 + 带薪年假<br>1.提供住宿、缴纳社会保险金、食堂、节日福利及带薪年假；<br>2享受节假日三倍工资<br>3.多彩的员工活动：公司不定期举行员工旅游、聚餐、生日会、年会等各类娱乐活动等，团队氛围融洽；', '河北博岳通信技术股份有限公司是一家大型的电子商务、呼叫中心运营及信息服务供应商，主要从事大数据建模/分析/应用、呼叫中心运营、运营商业务渠道、云服务、网络与信息服务业务。专注于为运营商、电子商务、金融、互联网企业和中小企业提供端到端的运营及服务解决方案。公司现有员工15000名，拥有运营坐席超过16000个，目前在北京、河北、四川、湖南、江西、辽宁、福建、宁夏、贵州、浙江、陕西等多个省市设有分公司和办事处。在大数据应用和呼叫中心运营领域，博岳股份与全国十几个省市通信运营商客户进行了全面合作,包括北京移动、中国移动咪咕公司音乐基地、咪咕动漫、四川移动、河北移动、河北铁通、宁夏移动、卓望信息、辽宁移动、江西移动、陕西移动、湖南电信、贵州联通、虚商迪信通；博岳股份与十几家互联网企业在运营和服务领域进行全方位的合作，包括小米科技、去哪网、多点生活、牛电科技、海选网运营支撑服务；博岳与互联网金融九鼎投资-借贷宝进行了全方位的战略合作，包括人人行客服、人人行催收、人人推和研发合作。博岳股份全面服务于通信运营商、金融、电商及互联网企业，服务用户超过5亿。在云服务领域，基于互联网模式建立了端到端的云客服平台，向互联网企业和各中小企业提供系统平台、数据库、数据建模及分析、物理场所、台席、人员及培训等端到端解决方案；为互联网企业和各中小企业提供快速、便捷、性价比高的优质服务。同时公司根据客户的需求，为客户设计完整的呼叫中心解决方案，并负责呼叫中心的建设、运营与维护，承接客户的对外联络、咨询、投诉、问卷调查、营销、客服等各项工作。作为河北省高科技企业，博岳股份于2016年3月份成功挂牌新三板。公司具备工信部颁发的“中华人民共和国增值电信业务经营许可证（全国呼叫中心业务许可证、河北省因特网信息服务业务许可证）”、“通信信息网络系统集成乙级”及“道路运输经营许可证”等资质，并且通过了ISO9001质量管理体系和ISO14001环境管理体系等权威认证。博岳股份立志发展成为业界一流的信息服务和网络服务提供商，博岳股份全面向世界优秀企业学习。博岳股份吸纳业界优秀人才，聚焦客户、聚焦业务，实现平台化和规模化的管理和运作，公司将秉承“以客户为中心、以贡献者为本、持续艰苦奋斗”的企业核心价值理念，我们相信通过全体员工的不懈努力和追求，一定能够为客户提供最好的解决方案和最优质的服务，并为客户实现商业成功!', 'https://www.zhaopin.com/jobdetail/CC351377410J40757326201.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4578, '英语翻译', '山东省庆云县君创锁业有限公司', '6月14日', '6000-10000元', '济南-历下区', '金属制品业,互联网,石油/石化', '100-299人', '未融资', 'CC243958980J40453151206', '一、福利待遇<br>1.【周末双休】国家法定节假日休息，全勤奖，年终奖，带薪年假，国内外旅游，员工体检，节日福利，通讯补助<br>2.上班时间是8：30--5:30<br>3.缴纳五险一金<br>二、岗位职责<br>1.负责公司英语业务翻译，英中互译表达流畅简洁<br>2.负责协助公司业务人员与客户洽谈订单及客户拜访<br>3.根据公司业务发展需要参加国内外会展活动<br>4.具备与客户电话、视频等方式沟通无障碍的能力，交流过程无障碍<br>5.接待国外来访客户，热情解答客户咨询的问题<br>6.完成上级交办的其他工作任务<br>三、任职要求<br>1.具备大学英语八级水平，专业不限，可接受应届生、零经验小白<br>2.熟练运用电脑办公软件，Excel、Word等软件的使用<br>3.具备良好的英语沟通能力和表达能力<br>4.热爱翻译工作，具备快速学习能力和敬业的工作态度<br>5.认真执行公司的各类规章制度，服从公司安排<br>6.优秀的团队合作精神和抗压能力<br>7.口语较好者，薪资可以面议', '山东省庆云县君创锁业有限公司位于山东与京津冀交接的枢纽之城德州市庆云县，公司成立于1990年，2008年正式更名为“君创锁业”，是国内较早专注于铅封锁具和仓储物流终端产品研发的制造企业之一。自创办以来，不断发挥行业领军作用，为安全封条行业以及仓储物流产业、中国智慧物流发展做出了不菲的贡献。企业自建厂房占地面积20000多平方米，设备460多台，员工300余名，高水准的研发团队及高素质的员工队伍。集仪表铅封、一次性封条、高保封、电子智能铅封、塑料扎带、GPS定位封、周转箱等产品的研发、设计、生产、销售为一体。经过十多年的发展，已成为具有规模与影响力的仓储物流终端产品的综合提供企业，企业年产值连续4年超2亿元。了解更多，请登录公司官网http://www.sdjcsy.com/', 'https://www.zhaopin.com/jobdetail/CC243958980J40453151206.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4579, '网络销售', '深圳市乐有家控股集团有限公司', '6月18日', '5000-7000元', '佛山-南海区', '房地产中介,房地产中介,咨询服务', '10000人以上', '未融资', 'CC298754310J40666522102', '【房产经纪销售】<br>除了常规的带薪假外，公司推出员工特享12项福利假期，比如每个月可享有1次“说走就走”的随心假，还有生日假、孝顺假、痛经假、亲子日、家长假、体检假等多个福利假期。<br>薪酬福利：<br>1、 收入自主制，赚多赚少你说了算，入职满1年的经纪人近一年平均月薪22375元，入职满1年的店长近一年平均月薪27978元！<br>①新手培养期：薪酬福利包括底薪、补贴、绩效，入职薪资最高6800元（具体面议）！行业新人享受专属培养期最长3个月!<br>②发展期：薪酬福利包括底薪、补贴、绩效、业绩奖金，发展期初期定岗薪资最高5500元+超高业绩奖核算比例55%-80%。公司提供广阔的发展空间和丰厚的薪酬待遇、业绩奖金无上限！<br>2、更多员工福利：社保、仁杰奖、荣誉奖、授课奖、节日关怀礼、国内外旅游、年假、婚假、产假、陪产假等。<br>秘诀只有一个，加入我们！<br>岗位职责：<br>1. 获取和整合附近社区楼盘及商圈信息，满足客户需求，提供置业前期的信息服务。<br>2. 运用E2E（端到端）理念，用好乐有家APP等数字化大平台，精耕社区，为用户提供“前一公里”到“后一公里”的房产交易服务解决方案。<br>3. 在所居住的或所熟悉的社区及商圈，开展走亲访友式的用户关系维护等工作，团结邻里，服务社区，实地考察房源并提供专业建议，及时促进买卖双方商务谈判。<br>4. 在平台强大支撑下，搭档作业，组团服务，为签约双方降低交易成本，控制交易风险，定制新的置业规划，与客户建立长久友好、良性循环的合作关系。<br>职位福利：五险一金、绩效奖金、年终分红、加班补助、餐补、房补、弹性工作、带薪年假<br>职位亮点：五险一金、带薪培训', '乐有家控股集团为“以房地产经纪为龙头、金融和互联网为两翼”的大型企业集团，成立于2008年，总部位于深圳市，2020年度交易额突破5000亿，在深圳市场占有率稳居行业第一，粤港澳大湾区多个城市市占率稳居行业前列。集团旗下拥有“乐有家”、“顺联担保”、“万顺通资产”、“家家顺物联科技”等优秀品牌，业务涵盖二手房买卖、房屋租赁、项目策划、新房代理、人工智能、资产管理、金融服务等领域，获得“中国十大品牌中介机构”、“全国优秀房地产经纪机构”、“年度最佳雇主”、“最值得信任的地产经纪品牌”、“广东省诚信企业”、“最具影响力雇主”等殊荣。集团始终坚持“真诚正义，先人后己”的核心价值观，积极推行“真服务、真保障”服务战略，为客户提供及时精准、专业可信、高效超值的房产交易全价值链服务。通过运用互联网、人工智能等新技术，打造线上线下一体化的E2E智能生态系统，致力于为客户打造房产交易全过程、全网络、全家庭生命周期的极致服务体验。集团以“立足大深圳、密布珠三角、连锁全中国”为发展战略，有效整合全国各项资源，实现“有家的地方就有乐有家”的宏伟愿景！', 'https://www.zhaopin.com/jobdetail/CC298754310J40666522102.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4580, '项目经理/主管', '宣城托新精密科技有限公司', '6月23日', '1-1.5万', '上海-嘉定区', '汽车零部件', '500-999人', '不需要融资', 'CC634235780J40631352011', '海外留学经历<br>1、负责海外项目从启动到投产整个过程的总协调，主导前期可行性分析，开发过程中的问题点汇总和改善，与客户和供应商保持联络，及时获取信息，确保项目按时通过客户认可程序，致力于客户满意 <br>2、负责制定项目整体进度规划，主导项目组各项工作并协调公司内各方面资源，确保项目严格按照APQP流程开发并按要求做好相关开发记录<br>3、根据项目实施的实际情况和进度要求，及时与客户、供应商和公司内各有关部门沟通、协调，并及时更新、调整工作计划 <br>4、产品投产后，负责总结项目组工作的经验和教训，并将工作移交至负责日常生产的相关部门<br>5、认真执行公司和部门的决议和部署，努力完成领导下达的各项任务和指标；', '上海托新实业有限公司2012年成立于上海，目前员工700人，是一家中高档汽车内外饰设计、研发、制造、装配、销售为一体的零部件制造企业，安徽宣城与扬州高邮均设有制造型工厂，力致于打造智能制造、科技型现代化一流工厂；同时托新在美国底特律、德国斯图加特均设有分公司，主要服务于海外市场海外客户的前期项目研发及销售。托新已与一汽大众、上海大众、美国通用（GM）、长安福特、捷豹路虎等各大主机厂成为长期战略合作伙伴。托新的主要产品工艺包括模具设计与制造、精密注塑、PVD、电镀、喷涂、装配及金属饰件等。', 'https://www.zhaopin.com/jobdetail/CC634235780J40631352011.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4581, '储备干部', '辽宁省超卓网络科技文化有限公司', '6月18日', '6000-8000元', '大连-沙河口区', '广告/营销', NULL, NULL, 'CCL1467816610J40530730808', '岗位职责 <br>1、作为公司的培养对象，在未来发展中承担团队的管理工作<br>2、独立负责工作小组，给其他成员提供指导或支持<br>3、配合上级领导制定公司管理制度并监督执行<br>4、负责领导安排的其他事物<br>任职资格<br>1、大专以上学历，有较强的学习能力<br>2、熟练使用办公软件<br>3、性格开朗，善于合作相处，团队意识强', NULL, 'https://www.zhaopin.com/jobdetail/CCL1467816610J40530730808.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4582, '风电工程师', '北京中联宏运科技开发有限公司菏泽分公司', '7月22日', '9000-10000元', '海东-平安区', '企业服务', '20-99人', '未融资', 'CCL1481025560J40687436901', '岗位要求：<br>1) 年龄：20-45 岁； <br>2) 学历：大专及以上学历人员：具有半年以上风电检修检验； <br>3) 三证齐全：高处作业证+低压电工证 +高压电工证<br>4） 无噪声、高温、高处作业、电工作业等职业健康禁忌症； <br>5） 能够吃苦耐劳，责任心强，有强烈的服务意识、良好的沟通能力，能适应长期风场工作。<br>薪资待遇:<br>基本工资+岗位津贴绩效福利，综合工资8000-10000元，法定节假日三倍薪资;<br>每半年调薪一次，每次调薪500-2000元，运维岗技术员8000-12000元，每季度15-20天带薪休假;高铁二等座报销路费一年五次，节假日三倍工资补助。<br>岗位职责： <br>1) 对风力发电机组进行故障处理、日常检修、日常维护等，保证风电机组安全稳定运行； <br>2) 负责维护过程中相关故障、隐患的排查、整改； <br>3) 对于维护过程中发现的各类安全隐患及时上报和跟进处理； <br>4) 进行风力发电机的技术处理与技术改进，跟踪反馈。', '欢迎有能力创新的有志青年加入给你一展示的平台追求卓越，打造和谐企业文化。追求卓越，打造和谐企业文化。诚信为本，创新为魂，企业文化引领未来。诚信为本，创新为魂，企业文化引领未来。企业文化是企业的灵魂，让我们传承和弘扬健康、积极、向上的价值观，激发团队无限潜能！企业文化是企业的灵魂，让我们传承和弘扬健康、积极、向上的价值观，激发团队无限潜能！', 'https://www.zhaopin.com/jobdetail/CCL1481025560J40687436901.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4583, '游戏运营', '北京陶乐科技有限公司成都分公司', '7月25日', '5000-10000元', '石嘴山-大武口区', '文化艺术/娱乐,游戏', '500-999人', '不需要融资', 'CCL1320297040J40723981609', '工作周期：长期兼职<br>每周工期：5天及以上<br>工作时间：不限<br>工作时段：不限<br>结算方式：周结<br>招聘截止时间：2024-10-05<br>岗位要求:<br>1、20～34周岁以内<br>2、一周任意6天，12:00～24:00自选5小时即可<br>工作内容:<br>跟平台用户玩狼人杀游戏，运营好玩家。<br>薪资提成:<br>1、提成60%（同行业最高）<br>2、基础底薪12～50元/时（周底薪420～1750）<br>ps:每周工作效果决定下周的底薪是升18、25、35、50元每小时。新人综合周工资范围可达1000～2000元，月薪7000+<br>【补充说明】<br>官方直招，不入公会，无押金无费用，不直播不露脸。无需电脑，一部手机即可。有一对一师傅带，欢迎投递。', '总公司成立于2014年03月13日，致力于网络游戏垂直内容领域，创作了大量的原创优秀作品，获得了游戏玩家们的高度认可，是电竞媒体中用户量最多的媒体。公司凭借专业的团队以及丰富的资源，以庞大的用户数量为基础，开展多项新业务，其中包括点点开黑社交产品。北京陶乐科技有限公司成都分公司成立于2021年03月03日，主要负责点点开黑手游业务，目前公司团队规模正在不断扩张。', 'https://www.zhaopin.com/jobdetail/CCL1320297040J40723981609.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4584, '律师助理', '广西万益律师事务所', '7月22日', '2000-3000元', '北海-银海区', '咨询服务', '100-299人', '未融资', 'CC289044580J40152328304', '（一）岗位要求<br>1. 能熟练使用Word、Excel、PPT等常用办公软件；<br>2. 善于对法律问题进行检索、研究和总结；<br>3. 能认真负责的完成各项工作，且有较好的沟通和应对日常问题的能力；<br>4. 身体健康，能细心且耐心的应对日常工作中的各项事务；<br>5. 法学、行政管理、汉语言文学专业；<br>6. 有律所、法院、检察院实习经历者优先。<br>（二）成长机会<br>1.北海市内唯一一家实行公司化管理的律所，博采众长，在团队内合作与成长；<br>2.内外部专业培训机会，快速提升个人专业能力；<br>3.业务范围：诉讼方向；<br>4.律师职级、合伙人晋升机会。<br>（三）薪酬福利待遇<br>1. 除月级别工资外，另有案源奖金、年中奖金、年终奖金；<br>2. 施展才能、实现自我价值的平台；<br>3. 轻松愉快的同事关系与工作环境；<br>4. 年度旅游、无息购车借款、无息购房借款、下午茶等员工福利。<br>职位福利：五险、员工旅游、周末双休、绩效奖金、节日福利  <br>', '一、万益概况广西万益律师事务所成立于1996年1月，在南宁市、来宾市、防城港市、贵港市、北海市、柳州市、新加坡、马来西亚吉隆坡设有办公室。秉承“高效、优质，共建、共享”的理念，万益不断发展壮大，拥有约260名律师及专业人员、7000多平方米的办公面积、一体化的管理制度及软件，为客户提供高效、优质的法律服务。曾十余次荣获全国文明委、中央组织部、司法部、中华全国律师协会表彰。二、万益团队万益组建12个专业部门：房地产和建设工程部、公司业务部、高端民商事争议解决部、刑事辩护部、行政法律部、金融证券部、涉外法律部、家事与财富传承部、综合法律部、案件执行部、破产法律事务部、海商海事部。为保障专业部门作用的有效发挥，万益组建5个专门部门：薪酬委员会、行政部、知识管理部、客户拓展与服务部、财务部。三、万益宗旨客户至上：以客户需求为导向配置资源，以向客户提供高效优质服务为目标。团队合作：秉承专业分工、团队合作的原则，万益致力于建设统一的服务平台，由合伙人牵头，有效配置人力、时间等资源，为客户提供专业化、全方位的法律服务。求新务实：培养、引进优秀人才，及时研究法律和市场变化，开发具有前瞻性及实用性的法律产品，为客户提供建设性的法律解决方案。四、万益文化追求卓越：万益强调律师应是为人正直、甘愿奉献、精益求精、敢于创新、勇于担当、抱负远大的人杰才俊。共建共享：万益注重以人为本，积极营造包容、利他、积极、专业的律所文化，打造员工实现梦想的平台，激发人才的潜能和优势，打开人才成长的天花板，使每个员工都得到尊重和关怀，与事务所共同成长，共享事务所发展成果，从而增加认同感，提升默契度，凝聚思想共鸣，形成发展合力。', 'https://www.zhaopin.com/jobdetail/CC289044580J40152328304.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4585, '风电工程师', '天津畅行高铁运维科技有限公司', '7月25日', '7000-9000元', '长春-宽城区', '客运服务', '10000人以上', NULL, 'CCL1495093740J40791506705', '一、岗位职责：按照风机机组及配套设备的维护技术要求，对其定期巡检、维护、定期检修、故障消除、技术改造等，保障风电机组的安全、稳定运行。<br>二、岗位要求：18-35周岁，中专及以上学历，无恐高、无心脏<br>病、无幽闭恐惧症、色盲等；上岗须持有安监局发放的高低压电工证、登高作业证、（无证人员公司免费考证）；<br>三、薪资待遇：<br>1、试用期每月5000-6500元，工资每三个月到半年调薪500-1500元，工作满一年后工资8000-12000元。享受13薪。<br>2、转正后签订正式劳动合同，缴纳六险一金，常白班，8小时工作制。<br>每工作2-3个月带薪休假10-15天，回家往返路费公司报销3、晋升空间：运维工程师-运维值长-运维场长-项目经理', NULL, 'https://www.zhaopin.com/jobdetail/CCL1495093740J40791506705.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4586, '招聘专员/助理', '圆通速递有限公司', '1月9日', '9000-16000元', '上海-青浦区', '邮政/快递', '10000人以上', '已上市', 'CC138773160J40675518305', '职位名称：招聘专员/招聘高级专员<br>职位地点：上海青浦<br>职位类型：全职 <br>岗位职责： <br>1.人才搜寻与评估： 利用多种渠道（如社交媒体、招聘网站、行业活动等）主动寻找和吸引优秀人才；<br>2.简历筛选： 对收到的简历进行初步筛选，评估候选人资格与公司需求的匹配度；<br>3.面试安排： 组织并协调面试流程，确保面试官与候选人之间的有效沟通； <br>4.候选人管理： 与候选人保持积极沟通，提供反馈并维护良好的候选人体验；<br>5.市场调研： 关注行业动态和人才市场变化，为公司招聘策略提供建议； <br>6.团队合作： 与各部门紧密合作，了解岗位需求，制定招聘计划； <br>7.数据分析： 维护招聘数据，定期分析招聘效果，优化招聘流程。 <br>任职要求： <br>1.统招本科及以上学历，人力资源、心理学、管理等相关专业优先； <br>2.有猎头或招聘相关工作经验优先，熟悉招聘流程和技巧； <br>3.较强的沟通能力和人际交往能力，善于与不同层级的候选人建立关系； <br>4.具备良好的市场洞察力，能够快速适应变化的招聘环境；<br>5.具备团队合作精神，能够在压力下工作，达成招聘目标。', '圆通速递创建于2000年5月28日，已成为一家集速递、航空、电子商务等业务为一体的大型企业集团，形成了集团化、网络化、规模化、品牌化经营的新格局，为客户提供一站式服务。2010年底，成立上海圆通蛟龙投资发展（集团）有限公司，标志着圆通向集团化迈出了更加坚实的一步。公司在网络覆盖、运营能力、业务总量、公众满意度及服务质量、信息化水平、标准化等方面等均走在了行业前列，品牌价值和综合实力名列中国快递行业前三甲。', 'https://www.zhaopin.com/jobdetail/CC138773160J40675518305.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4587, '网络销售', '天津勇林劳务派遣有限公司', '3月7日', '1-2万', '西安-雁塔区', '人力资源服务', '100-299人', NULL, 'CCL1240609760J40709642401', '轻松融洽的工作氛围、绝对公平的激励机制、无限广阔的事业发展机会、轻松助你拿高薪！确定还不来嘛～<br>  职位描述：  <br>1 通过电话/线上APP等多种服务方式，为客户提供咨询和建议  <br>2 维护高净值客户，进行二次客户开发', NULL, 'https://www.zhaopin.com/jobdetail/CCL1240609760J40709642401.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4588, '销售工程师', '江苏合空间环境工程有限公司', '7月19日', '7000-12000元', '南京-江宁区', '装饰装修,装饰装修', '20-99人', '未融资', 'CC692711680J40545757507', '职位描述：', '合空间集团旗下包括江苏合空间环境工程有限公司、江苏勒誉家具装饰设计有限公司、江苏南京科善家具有限公司，成立于2008年2月27日，注册资金1000万，并于2008年到至今与全球最大办公家具品牌HermanMiller携手，在国内推广其品牌及产品，历经十年的累积与沉淀，合空间团队汲取国际品牌的先进设计理念及高端家具生产经验，创造更美好的生活及有激情的办公环境。HermanMiller旗下品牌有1、HermanMiller,成立于1905年，是一家百年历史的美国企业。2、Geiger成立于1964年，于1999年被赫曼米勒收购3、美国医疗家具品牌Nemschoff,成立于1950年，收购于2009年。4、英国显示器支架品牌CBS，成立于1990年，收购于2010年。5、posh,香港办公品牌，成立于1959年，收购于2012年。6、美国纺织巨头Maharam,成立于1902年，收购于2013年。7、美国现在家具零售商Design Within,成立于1998年，收购于2014年，8、英国家具品牌Naughtone成立于2005年，收购于2016年。9、荷兰隔断品牌Maars,成立于1964年，收购于2018年。10、丹麦家具品牌HAY，成立于2002年，收购于2018年。11、芬兰隔音亭品牌FRAMERY，成立于2010年，收购于2018年。赫曼米勒在不断的壮大，合空间正是这样的理念，合作共赢。抢占国内精英层的办工家具市场，打造最专业最高端的办公环境配置。', 'https://www.zhaopin.com/jobdetail/CC692711680J40545757507.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4589, '招聘专员/助理', '衡阳酃湖万达广场商业管理有限公司', '7月17日', '4000-5000元·15薪', '衡阳-None', '快速消费品', '20-99人', '未融资', 'CCL1246423370J40052213807', '衡阳万达商管集团急招人事行政助理 <br> <br>主要负责人员招聘、档案管理、账务报销、会议记录等等。 <br> <br>要求熟悉劳动法规及用人政策，熟练操作办公软件，具备公文写作知识 <br> <br>男女不限，大专学历以上，年龄20-30岁 <br> <br>双休+法定节假日+五险一金+包工作餐+年底双薪 <br> <br>任职要求： <br> <br>1、本科以上学历； <br> <br>2、具备一年以上人事行政工作经验，有一定的文字写作特长； <br> <br>3、熟练使用WORD、EXCEL、PPT等办公软件，性格开朗，思维敏捷，有责任心。<br>职位福利：五险一金、绩效奖金、餐补、带薪年假、周末双休、年底双薪<br>', '万达商业管理有限公司系大连万达集团的核心子公司之一，也是全国性连锁商业经营管理企业，拥有一支近万人的商业管理团队，主要负责经营管理万达商业地产公司开发的大型商业购物中心以及住宅、公寓和写字楼等多种类型物业项目。万达商业管理公司拥有丰富的商业资源，强大的运营管理能力，物业管理面积已超过1000万平方米，已成为万达商业地产的核心竞争优势之一。“万达广场就是城市中心”——万达期待您的加入！有意向可拨打电话：0734-2889333杨女士', 'https://www.zhaopin.com/jobdetail/CCL1246423370J40052213807.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4590, '储备干部', '中国人寿保险股份有限公司深圳市分公司', '7月2日', '9000-18000元', '深圳-龙华区', '保险,银行,保险', '10000人以上', '已上市', 'CC135627160J40495290011', '一、【职位介绍】<br>本岗位是公司专门培训未来金融业务精英和团队主管而设置的，寻求愿意与公司一起成长的有识之士，通过公司的培训与管理，因材施教，根据精英人员不同的优势能力，向不同的方向晋级晋升。<br>二、【具体的部门和岗位】<br>虽涉及一些销售，但本部门不是传统的电销或者营销部门，是中国人寿的综合金融收展发展部，本部门为提高公司服务品质，扩大售后服务团队，提供优质的客户资源，在服务的基础上给客户进行整体资产的配置，现需要一批高学历高素质的年轻有上进心的有恒心的优秀人才加入。<br>本部门精英未来发展方向如下：培训讲师、综合金融主管、理财规划师等，这里晋升公平、公正、公开！根据北京总部的基本法规定，每三个月有一次晋升的机会！<br>三、【岗位职责】<br>1. 主要负责服务对接公司现存有效保单客户，协助公司提醒客户续期缴费，帮助客户办理保单受益人指定、生存金、满期金的领取、理赔等保全服务；<br>2. 除基础服务外，公司会从大健康、大养老、大资管层面提供给客户增值服务，根据客户需求，通知客户参与增值服务的活动；  3. 在客户有需求的情况下，帮助客户做合理的专业的家庭理财规划及风险保障方案，协助客户办理加保手续，业务范围包含：寿险、财产险、团体险、银行的产品；  <br>4. 日常客户经营维护，借助公司提供的客户资源，获取转介绍客户资源，扩大和提升自己的人际关系圈层；  <br>5. 参与公司培训，不断提升自我综合能力，并组建团队，最快一个季度成长为一名合格的主管，并不断晋升。  <br>  <br>四、【职位要求】  <br>1. 年龄22～45周岁；  <br>2. 自律性较强，有较好的自我管理能力；  <br>3. 学历大专及以上或有相关工作经验人才，（特别优秀的人才通过特殊申请可适当放宽条件）；  <br>4. 有卓越的目标，具备一定的竞争意识，勇于挑战自我；  <br>5. 良好的人格和品行，优异的学习力，执行力，适应能力；  <br>6. 有上进心，有团队管理，独立创业经验者优先，有金融、管理、保险、销售、人力资源等行业从业经验者优先。  <br>  <br>  <br>五、【相关体系】  <br>1. 提供从基础岗位至区域总监整个过程的完善培训体系；  <br>2. 公平公正公开的职级晋升平台；  <br>3. 顺畅的晋升渠道，无发展瓶颈；  <br>4. 完善系统的晋升培训体系；  <br>5. 各种能力拓展训练、素质提升培训、法商课程培训、团队管理培训。  <br>  <br>六、【理想的职业是怎样的？】  <br>职业特征：  <br>1. 晋升的机会可以自己把握  <br>2. 公平公正公开和谐的工作氛围  <br>3. 随着工作年资的增加，市场身价不断提高  <br>4. 不断学习新知识、不断接触新事物  <br>5. 工作中可以有更多的自主性和创造性  <br>6. 工作中能够结识更多的朋友和人脉  <br>7. 能帮助别人，成就自己，获得荣誉  <br>  <br>选择大于努力，选对事业是关键  <br>有这样一份事业，你会选择吗？  <br>前途性——行业未来具有良好的发展潜力、朝阳产业  <br>晋升性——个人的晋升在于自己的能力，不受人际关系和年资的影响  <br>收入性——个人能力、工作时间的投入与收获成正比  <br>成长性——能接受完整的培训系统，并不断地激发自身的潜能  <br>快乐性——工作有意义，乐在其中，并能不断成长  <br>', '中国人寿保险（集团）公司属国家大型金融保险企业。2019年，集团公司合并营业收入9067亿元；合并保费收入6977亿元；合并总资产超4.5万亿元。中国人寿保险（集团）公司已连续18年入选《财富》世界500强企业，排名由2003年的290位跃升为2020年的45位；连续14年入选世界品牌500强，2020年品牌价值达人民币4158.61亿元；所属中国人寿保险股份有限公司继2003年12月在纽约、香港两地同步上市之后，又于2007年1月回归境内A股市场，成为全球第一家在纽约、香港和上海三地上市的保险公司。中国人寿保险（集团）公司的前身是诞生于1949年的原中国人民保险公司，1996年分设为中保人寿保险有限公司，1999年更名为中国人寿保险公司。2003年，经国务院和中国保险监督管理委员会批准，原中国人寿保险公司进行重组改制，变更为中国人寿保险（集团）公司，并独家发起设立中国人寿保险股份有限公司。目前，集团公司下设中国人寿保险股份有限公司、中国人寿资产管理有限公司、中国人寿财产保险股份有限公司、中国人寿养老保险股份有限公司、中国人寿电子商务有限公司、中国人寿保险（海外）股份有限公司、国寿投资控股有限公司、国寿健康产业投资有限公司以及保险职业学院等多家公司和机构。2016年，中国人寿入主广发银行，开启保险、投资、银行三大板块协同发展新格局。中国人寿秉持“成己为人成人达己”的企业文化核心理念，坚持稳中求进工作总基调，坚持高质量发展，扎实推进保险主业价值和规模协调发展，努力提升投资板块贡献，积极做好银行金融服务，有序开展综合化经营、科技化创新、国际化布局，全面推进国际一流金融保险集团建设。', 'https://www.zhaopin.com/jobdetail/CC135627160J40495290011.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4591, '质量管理/测试', '圆通速递有限公司', '3月4日', '9000-13000元', '无锡-惠山区', '邮政/快递', '10000人以上', '已上市', 'CC138773160J40745751105', '三大指数管控：、<br>负责分析菜鸟指数、中心服务质量、网点KPI三大指数管控得分、同行得分对比并提出改善方案<br>服务质量监控：<br>1、负责时效监控、服务监控、质量监控等工作；<br>2、负责通过菜鸟、驾驶舱、金刚等信息化工具对中心和网点时效服务质量工作进行监控，及时发现问题找到解决办法；<br>3、负责中心时效及质量数据分析工作统筹，推动中心各项业务标准落地，监督中心各项质量考核工作的有效性；<br>4、对各类质量数据进行跟踪分析，督促相关部门进行整改；<br>5、针对本中心的服务质量，定期开展相关培训工作，提升专业能力及业务素养； <br>质量管理工作：<br>1、监督一线的操作规范执行情况及中心问题件、无着件、破损件的处理监督；<br>2、监控全链路疑似遗失及待仲裁遗失数据的逐票跟单；<br>3、中心时效、质量类指标的数据分析，找出问题点，制定解决方案并与领导沟通确认；<br>4、负责协调遗失处理、先行赔付遗失处理、投诉处理(普通投诉、升级投诉、投诉罚款、异常工单)；<br>5、中心质量例会和阶段性培训、考试的开展；<br>6、对于异常情况与中心内各班组之间的横向沟通及网点、省区、总部职能部门的纵向沟通。', '圆通速递创建于2000年5月28日，已成为一家集速递、航空、电子商务等业务为一体的大型企业集团，形成了集团化、网络化、规模化、品牌化经营的新格局，为客户提供一站式服务。2010年底，成立上海圆通蛟龙投资发展（集团）有限公司，标志着圆通向集团化迈出了更加坚实的一步。公司在网络覆盖、运营能力、业务总量、公众满意度及服务质量、信息化水平、标准化等方面等均走在了行业前列，品牌价值和综合实力名列中国快递行业前三甲。', 'https://www.zhaopin.com/jobdetail/CC138773160J40745751105.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4592, '资料管理', '三亚新澳投资置业有限公司', '7月24日', '5000-7000元', '三亚-吉阳区', '房地产开发', '100-299人', NULL, 'CC350665120J40572482409', '岗位内容：<br>1. 负责制定和实施档案管理规定、政策和标准，确保文件资料正确清晰、准确无误<br>2. 管理公司所有档案文件、资料的收集、整理、存储和使用，维护档案管理系统的有效性和规范性<br>3. 及时回答各部门档案问题并提供支持；处理涉及机密文件的申请和管理<br>4. 组织开展档案借阅、调阅工作，协调处理异常情况<br>任职要求：<br>1. 有相关工作经验，熟悉档案管理规定、流程及国家档案管理制度<br>2. 具备良好的组织协调能力、口头及书面表达能力，良好的团队合作能力<br>3. 熟悉文献检索、档案鉴定等相关专业知识技能，了解档案数字化技术<br>4. 良好的服务意识和责任心，对工作有耐心和细致认真，能在压力下工作', '公司简介一、公司简介：三亚新澳投资置业有限公司开发的澳洲城项目位于三亚城市中轴迎宾路中段（万科湖畔斜对面），地处未来三亚的新城中心，是三亚目前主要的重点区域。该区域作为三亚的新城中心，总规划面积约300亩，将结合自身的自然资源优势打造风情特色旅游为先导，集旅游休闲、康体养生、生态居住功能为一体的城市旅游生活区。该项目紧挨全球最大的千古情大剧院、音乐厅、主题公园、特色美食商业街、高端度假酒店、龙泉谷高尔夫球场、妇幼保健院、三亚最大的星际农贸市场等等，且坐拥空港、高铁、高速、城市干道的立体交通网络，生活相当便捷，且区位的潜质升值能力巨大。公司目前拥有一批优秀的管理团队，研究生4人，大专及以上学历23人，中高级以上职称11人。二、地理位置：三亚澳洲城项目位于三亚市吉阳区，这里拥有世界一流的空气质量，白沙细浪、海天湛蓝，犹如一个巨大扇贝，三亚澳洲城就像是这贝壳孕育出的一颗璀璨明珠，只有独具慧眼的人，才能真正发现其内在的价值。往来小区交通便利，迎宾大道、西线公路、西线高速公路、环岛高铁环伺左右、天涯海角、凤凰机场旋即可至，18洞高尔夫球场紧邻其后，全球最大的千古情大剧院、音乐厅，立体交通畅游三亚，到市中心只需10分钟车程。该地区环境优美，交通顺畅通达，十分便利，周遍配套设施完善，区域优势明显，交通便宜，赋予了本项目先天的不可多得的品质和很强的产品竞争力。项目简介：澳洲城项目共占地300亩，预计分两期分批建成，房屋类型分高层住宅、LOFT公寓、沿街商铺和地下停车库共9栋房屋建筑（其中8栋18层住宅楼，1栋10层LOFT住宅楼，地下车库一层）。欢迎有志之士加入这个年轻有为的团队。我们给您足够的发展平台，自信成就未来，\\\\\"新澳\\\\\"愿与你携手共进。', 'https://www.zhaopin.com/jobdetail/CC350665120J40572482409.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4593, '销售运营', '西安正义合信息科技有限公司', '7月8日', '6000-7000元', '西安-未央区', '运营商/增值服务', '20-99人', '未融资', 'CCL1493385740J40747668309', '一、薪资待遇：<br>1、 试用期：无责底薪4650+500绩效+奖金，平均工资6000；<br>2、 转正后：6000—8000/月，不封顶！<br>3、 公司提供一年四次总部带薪进修学习或赴国内其他公司学习交流。<br>4、 公司每周有聚餐，每季度组织国内著名景区旅游。<br>5、 公司每年对优秀员工提供2-4次旅游培训机会。<br>6、 对申请需要住宿的人员提供住宿。<br>二、岗位职责：<br>1.负责公司产品运营协助主管做好产品品牌运维推广等，团队管理经营方面，前期和公司主管学习，协助主管处理事务<br>2.和商户品牌渠道这边沟通面谈协调，协助主管处理商户问题.<br>3.依据团队成员情况，有针对性的制定训练培训计划并组织实施<br>4.现场指导团队成员工作，进行团队目标过程管理<br>5.不用担心工作做不好、不好做，有人带、有培训（有无经验均可，提供带薪培训，完善的培训，帮助更快提升）<br>三、任职要求：<br>1.经验不限 18-25岁之间 阳光心态 吃苦耐劳 善于学习<br>2.善于与人沟通 对市场反应敏锐；细致 勤奋 具有团队合作精神<br>3.有责任心 积极主动，性格开朗 敢于挑战自我 有艺术细胞的优先!!!! 选择文件: 未选择任何文件', '简介：西安正义合信息科技有限公司成立于2024年11月19日，注册地位于陕西省西安市经济技术开发区凤城二路第五国际A座1306室，法定代表人为罗旭。经营范围包括一般项目：物联网技术服务；通讯设备销售；移动通信设备销售；通信设备销售；光通信设备销售；5G通信技术服务；互联网数据服务；信息系统运行维护服务；信息技术咨询服务；信息系统集成服务；人工智能行业应用系统集成服务；数字视频监控系统销售；互联网设备销售；计算机及通讯设备租赁；网络技术服务；大数据服务；计算机系统服务；计算机软硬件及辅助设备零售；通讯设备修理；通用设备修理；市场调查（不含涉外调查）；信息咨询服务（不含许可类信息咨询服务）；技术服务、技术开发、技术咨询、技术交流、技术转让、技术推广；网络设备销售；销售代理；移动终端设备销售；人工智能公共服务平台技术咨询服务；云计算装备技术服务；互联网销售（除销售需要许可的商品）；电子产品销售；租赁服务（不含许可类租赁服务）。(除依法须经批准的项目外，凭营业执照依法自主开展经营活动)', 'https://www.zhaopin.com/jobdetail/CCL1493385740J40747668309.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4594, '律师', '邦唐邦(北京)知识产权服务有限公司重庆分公司', '7月7日', '8000-12000元', '重庆-江北区', '专利/商标/知识产权,专利/商标/知识产权,法律服务,咨询服务', '100-299人', '未融资', 'CC543447920J40769573007', '岗位职责：<br>1、法律顾问，诉讼代理，日常咨询；<br>2、可以转所；<br>3、模式：无需坐班，工作时间灵活，自带案源即可开展业务；<br>4、薪资面试详谈，月结；<br>注：灵活发展，适合希望自主规划执业方向、积累案源的律师，无需受固定坐班限制', '邦唐邦（北京）知识产权服务有限公司（以下简称唐邦）旗下包括邦唐邦（北京）知识产权服务有限公司重庆分公司、四川唐邦知识产权代理有限公司、邦唐邦（北京）知识产权服务有限公司广州分公司、邦唐邦（北京）知识产权服务有限公司保定分公司。唐邦总部设在北京，是一家综合性法律服务公司，致力于建设全国性知识产权服务体系，并逐步打造成一家为客户提供一站式综合性知识产权服务平台，现已在河北、重庆、成都和广州等地设立知识产权分公司。唐邦以“专业、诚信、尊重、阳光”为企业理念，在迅猛发展的过程中，一直注重团队自身专业素质的提升和客户服务质量的增强，主要代理事务包括：商标、版权、海关备案、品牌策划、项目申报、高新认定等事务。凭借着过硬的专业素质和服务质量，经过艰苦奋斗和创新开拓，为企业提供了专业的知识产权服务，并建立了完善的知识产权体系。唐邦属于国家工商总局商标局合法备案机构，并荣膺中华商标协会会员单位。', 'https://www.zhaopin.com/jobdetail/CC543447920J40769573007.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4595, '广告销售', '五常市顺泽米业有限公司', '7月4日', '5000-9000元', '哈尔滨-南岗区', '农/林/牧/渔,农/林/牧/渔', '100-299人', '未融资', 'CC370993220J40750612601', '岗位内容：<br>1. 负责协助上级领导做好销售日常运营工作，如订单处理、物流跟踪、售后服务账款分析、回款跟踪等。<br>2. 协助销售部门完成销售计划对接，保证项目高效顺利实施。<br>3. 负责销售数据统计、分析、销售订单报价、销售合同跟进等工作。<br>4. 参与市场调研、分析行业数据并给出建议。  5.协助领导做好客户接待工作。  <br>  <br>任职要求：  <br>1. 专科及以上学历，市场营销、食品、贸易等相关专业优先；  <br>2. 具备较高的工作热情，较好的执行能力；  <br>3. 具备良好的客户服务意识，善于解决问题；  <br>4. 具备出色的表达能力和谈判能力，能接受偶尔短期出差优先。     5.有粮油、快消行业销售内勤或业务经验优先', '五常市顺泽米业有限公司位于中国优质大米之乡—黑龙江省五常市。我公司所处地理环境优越，U型的地貌被群山环绕，蓄水量达到2亿立方的龙凤山水库为水稻的生长提供了优质的水源，肥沃的土壤突显龙江的特色，常年积温2900度，质朴的稻农沿用传统的种植方式。天然的优势环境，让顺泽品牌大米有着原生态的品质。公司以诚信为本，坚持品牌化道路，为客户提供一个多品种的采购平台。同时完善和促进与稻农的鱼水关系，为稻农提供专业的技术服务。在这块具有独特地理优势的黑土地上，让其资源优势得以升华，全面提升产品品质，增强公司核心竟争力。最后，竭诚欢迎广大经销商、消费团体前来我公司洽谈合作事宜。我公司全体员工愿为您提供最理想的产品，最真诚的服务。', 'https://www.zhaopin.com/jobdetail/CC370993220J40750612601.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4596, '社区运营', '中国平安', '7月24日', '面议', '石家庄-新华区', '保险,保险', '10000人以上', '已上市', 'CC000204810J40800457212', '职责 1) 根据公司客户划分，需完成负责区域内客户售后服务响应、服务活动完成；<br>2) 负责区域内客户建联，通过企业微信等做好客户日常经营；如热点话题、健康养生、生活小细节等，提升客户活跃度； <br>3) 依托公司内外部资源，打造个人IP“做客户保险小帮手、生活小助手”，进行产品销售； <br>4) 客户原保单的续收提醒，具备基础的保险专业知识；<br>5) 通过系统的培训学习，不断提升自身服务水平及综合解决各类产品营销的能力； <br>职位优势<br>1) 优质客户资源提供，解决了销售的核心痛点，做好客户服务<br>2) 工作以面访服务、客户经营为基础进行产品营销；<br>福利待遇<br>工作时间:<br>早上:9:00-18:00，6小时工作制，午休两个小时。绝不加班。<br>周末双休。带薪年假，年底双薪，法定节假日带薪休假+带薪158天产假', '中国平安致力于成为国际领先的科技型个人金融生活服务集团。2019年，中国平安深入推进\\\\\"金融+科技\\\\\"、\\\\\"金融+生态\\\\\"战略转型，持续提升数据化经营能力，整体业绩及核心金融业务持续稳健增长，科技赋能成效显著，生态赋能效果初显，综合金融用户数、客户数、客均合同、客均利润均有明显增长。公司实现营业收入同比增长19.7%至11,688.67亿元。截至2019年底，公司个人客户数首次突破两亿，互联网用户量达5.16亿，全年新增客户数3,657万，其中40.7%来自集团五大生态圈的互联网用户。中国平安始终践行\\\\\"金融为实体经济服务\\\\\"的精神，坚持把实体经济服务作为出发点和落脚点，通过旗下的保险、银行、信托、金融科技等业务，把逾4万亿金融资源配置到经济社会发展的重点领域和薄弱环节，包括通过保险保障、提供贷款、债权股权计划、普惠金融等多种方式，全面助力实体经济发展。凭借全球领先的创新科技，中国平安将科技深度运用于金融主业中，助力降本增效、风险管控，打造优质产品和极致服务体验，提升客户口碑。与此同时，平安将领先科技广泛应用在金融、医疗及智慧城市等领域，全面支撑\\\\\"金融服务、医疗健康、汽车服务、房产服务、智慧城市\\\\\"五大生态圈建设。在企业社会责任方面，平安深化可持续发展理念，MSCI ESG评级连续两次调高至A级，打造AI-ESG平台赋能责任投资，截至2019年12月末，公司责任投资规模达9,544.49亿元，可持续保险金额达121.21万亿元，绿色信贷年度授信总额590.56亿元。同时，平安积极响应国家脱贫攻坚战的号召，推进\\\\\"三村扶贫工程\\\\\"项目，累计提供专项扶贫资金249.05亿元。面对新冠肺炎疫情，平安第一时间推出保险保障、医疗支持、对外捐赠等多重支持举措，提供的物资及现金捐赠总额超1.75亿元。2020年，中国平安品牌价值持续提升，名列美国《财富》“世界500强企业”第21位，居全球金融企业第2位，《福布斯》全球上市公司2000强第7位，BrandZ™全球品牌价值100强第38位，蝉联全球保险品牌第1位。', 'https://www.zhaopin.com/jobdetail/CC000204810J40800457212.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4597, '知识产权/专利代理', '企知道大数据科技有限公司', '5月15日', '5000-9000元', '南京-秦淮区', '专业技术服务,企业服务', '1000-9999人', 'A轮', 'CCL1464680980J40797100608', '岗位职责:<br>1.与客户进行技术交流，理解并分析客户的技术需求和创新点；<br>2.撰写专利申请文件，覆盖客户的技术领域，机械、电学、生化等；<br>3.处理专利申请过程中的文件补正和审查意见；<br>4.担任企业专利顾问，为企业解决专利相关问题；<br>5.持续跟踪客户需求，提供专业的专利解决方案。<br>任职要求：<br>1.具备出色的沟通能力和分析能力，能够有效地与客户建立良好的工作关系；<br>2.对专利撰写和知识产权管理有深入理解；<br>3.能够独立处理和解决专利相关问题；<br>4.具有较强的组织能力和团队合作精神；<br>5.对技术细节有敏锐的洞察力，能够捕捉并利用这些细节为企业创造价值。', '企知道集团是中国科创企业全要素资源搜索、匹配、管理、运营服务商，国家高新技术企业、专精特新企业，被国家工信部认定为全国唯一的科创服务类大数据产业发展试点示范项目。公司独创“4+”服务模式和“4x5”服务能力，并通过全国60多家分子公司，为20多个省市的政府部门和千万企业提供服务。公司旗下“企知道”科创服务大数据平台，汇集了全球6.9亿家企业数据4.8亿期刊论文数据、1.78亿专利数据、4700多万产业政策数据、900多万技术成果数据和200多万科研专家数据，公司汇集、治理全球科创数据，构建AI模型，加速创新要素向企业集聚，致力打造中国第一、国际一流的科创服务大数据基础设施。', 'https://www.zhaopin.com/jobdetail/CCL1464680980J40797100608.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4598, '统计员', '江苏佳燃厨房设备工程有限公司南京分公司', '4月20日', '5000-7000元', '南京-栖霞区', '仪器仪表制造,通用设备制造', '20-99人', '未融资', 'CCL1296326790J40429117206', '1、招标信息的收集，根据招标信息确定商务和技术判断是否投标；', NULL, 'https://www.zhaopin.com/jobdetail/CCL1296326790J40429117206.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4599, '招聘专员/助理', '众德(北京)机械设备有限公司', '7月25日', '7000-10000元', '北京-海淀区', '橡胶和塑料制品,日化产品制造', '100-299人', '未融资', 'CC655569920J40759320701', '岗位职责<br>  与各部门沟通，了解招聘需求，明确岗位职责和任职要求。根据公司战略和业务发展，制定招聘计划并执行。<br>  根据岗位要求筛选简历，进行初步电话沟通，评估候选人匹配<br>  安排面试时间，协调面试官和候选人的时间，确保面试流程顺利进行。<br>  与候选人保持良好的沟通，及时反馈面试结果，提升候选人体验。<br>  任职要求<br>  本科及以上学历，人力资源相关专业<br>  有经验者优先<br> 注意：岗位单休，介意者勿投，法定节假日正常享有<br>', '众德（北京）机械设备有限公司是一家集科研开发与专业生产为一体的高科技生产型出口企业，目前公司产品和服务已覆盖全球70多个国家和地区。生产设备齐全，检测手段完善，在生产标准及产品执行标准上已经通过ISO国际认证、SGS国际认证、德国莱茵公司的欧盟准入认证。主要产品有橡胶制品系列、塑料制品系列、机械配件，农机配件等。公司多次引进国际先进水平全自动生产设备及技术，降低生产成本的同时使公司产品在国际市场上更具竞争力，被国内外重点企业广泛认可，深受广大用户青睐。公司技术部位于深圳龙华区；国际运营部及销售1部设在北京海淀区--众德（北京）机械设备有限公司；销售2/3/4部位于省会石家庄--河北匠智机械设备有限公司，其中销售2部位于石家庄裕华区，销售3部位于石家庄长安区，销售4部位于石家庄新华区；生产部坐落于河北衡水--河北匠德机械设备有限公司；四公司分工明确、统一管理。公司有世界一流的机械设备、专业的研发团队、尖端的国际运营团队以及高效的销售团队，欢迎各界精英加入！', 'https://www.zhaopin.com/jobdetail/CC655569920J40759320701.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4600, '统计员', '吉林省蓝青蛙劳务派遣有限公司', '5月26日', '4000-6000元', '长春-绿园区', '人力资源服务', '100-299人', '未融资', 'CC418019230J40793647603', '工作内容：负责公司人员招聘，候选人面试的安排及跟进工作。<br>要求：熟练使用各类招聘、办公软件，服从公司管理，踏实肯干。<br>薪资待遇：无责底薪+绩效+提成<br>工作时间：早9~晚6，有休息、法定假日休息！<br>有相关招聘经验者优先<br>报名方式请直接来电咨询报名！或向我投递简历<br>急招！投简历！投简历！！投简历！！！', '吉林省蓝青蛙劳务派遣有限公司是由吉林省人社厅批准从事经营劳务派遣、人力资源等服务的企业，公司实缴注册资金200万元，并已通过ISO9001质量管理体系认证,是一家专业为企业提供劳务派遣、劳务外包、人力资源的供应商。蓝青蛙是一家具备现代企业管理制度和服务意识的专业人力资源服务企业。现设有市场运营部、猎头部、人力资源部、办理用工手续、保险缴纳、保险理赔、工社会保障部、综合办公室、财务部等部门，其中汇聚了多名来自省内知名企业、劳动保障部门的资深人力资源管理专家。并在烟台、吉林市、延吉等地设有分公司及办事处。蓝青蛙为企业提供的服务包括：劳务外包、劳务派遣、劳动仲裁委托、社保代缴等人事外包服务。其中所涉及的服务项目包括了：与员工签订劳动合同、资计算发放、退工手续办理等相关的人事服务。', 'https://www.zhaopin.com/jobdetail/CC418019230J40793647603.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4901, '资料管理', '清华海峡研究院(厦门)', '7月26日', '100-150元/天', '厦门-湖里区', '零售/批发,互联网', '100-299人', '未融资', 'CC808477970J40570538113', '一、岗位职责  1. 负责各类文档的整理、归档和分类，确保文档的系统性和易于查找。例如：将项目文档按照项目名称、时间顺序进行整理。', '清华海峡研究院于2015年4月17日成立，是由厦门市人民政府、两岸清华大学共同成立的按企业方式运作的事业单位；同时也是北京清华大学继深圳、北京、河北、浙江之后与地方共建的第五个地方研究院。清华海峡研究院依托两岸清华大学技术、人才，充分发挥三方优势，服务于加快海峡西岸经济区和“一带一路”核心区建设，打造创新创业生态圈，积极支持福建省及厦门市快速发展，促进海峡两岸融合，推动福建自贸区的发展，努力将自身建成国际一流的科技创新、高技术产业化和人才培养基地。', 'https://www.zhaopin.com/jobdetail/CC808477970J40570538113.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4902, '总助/CEO助理/董事长助理', '平凉市一鑫商贸有限责任公司', '7月17日', '6000-12000元·13薪', '平凉-崆峒区', '零售/批发', '20人以下', NULL, 'CC617232730J40660637916', '岗位职责：   客户接待与咨询：通过抖音直播间沟通有意向的顾客，促成顾客添加管理微信，热情、专业地解答客户的咨询，提供产品/服务信息，处理客户疑虑。了解客户需求，推荐合适的产品或服务方案，促进销售成交。  市场信息收集：关注市场动态，收集竞争对手信息，为公司的市场策略提供数据支持。  数据整理：协助管理完成相关表单的数据收集与整理  其他：完成管理交代的其他工作 工作要求   教育背景：高中及以上学历，商务经济、工商管理、市场营销、会计等相关专业优先。  工作经验：抗压能力强，能接受全国出差，有销售、客服、直播运营工作经验者优先，优秀应届毕业生亦可考虑。  沟通能力：具备出色的沟通能力和服务意识，能够耐心、细致地解答客户问题。  学习能力：快速学习新产品知识，适应公司文化及工作流程。  技能要求：PPT制作精良，熟悉会议纪要梳理方式方法，熟练基础的办公软件操作，如飞书。 我们提供：   竞争性的薪资待遇，包括基本工资+绩效奖金+提成+年终奖。熟悉工作2-3个月后年薪范围在10万-30万之间，具体视个人能力和贡献而定。  专业1对1的培训体系，助力个人成长。  舒适的工作环境，和谐的工作氛围。  丰富多彩的团队建设活动及员工福利。  每年享有12次晋升机会等。  提供年终奖。 6. 团队氛围   我们是一支年轻、活力四射的团队，倡导开放、包容的企业文化。在这里，您可以享受到轻松愉悦的工作氛围，与一群志同道合的伙伴共同成长。', NULL, 'https://www.zhaopin.com/jobdetail/CC617232730J40660637916.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4903, '质量管理/测试', '哈尔滨达生肉类制品有限公司', '7月22日', '4000-6000元', '哈尔滨-香坊区', '食品/饮料', '100-299人', '未融资', 'CC240267530J40761068411', '岗位职责：<br>1.负责产品检验规范、品质管理文件等的编制，申报责任部门发放，并培训部门内部及相关岗位遵守品质文件要求<br>2.负责产品实现过程品质控制，编制检验指导书，做好进料、过程、成品的检验和验证并保持记录<br>3.负责监视和测量设备的管理，编制年度校准计划并执行校准或检定，负责对偏离校准状态时的追踪处理<br>4.负责不合格品判定，组织相应部门进行处置，当产品出现质量问题时，组织对其进行追溯，参与制订相应纠正预防和改进措施，并进行跟踪和验证； <br>5.负责内部和外部质量反馈信息的分析、传递、处理<br> 接受小白 有人带 <br>单休 法休 五险免费食堂 节日福利', '哈尔滨达生食品成立于1978年，两代达生人三十年来夜以继日致力于生产与研发老式新派哈尔滨红肠，以匠心诚意守护冰城独具一格的红肠文化，沿袭与传承着东方小巴黎最具俄式风情的餐桌文明。公司主打俄罗斯欧式系列红肠及传统酱卤制品，全品系列口味精细，照顾到哈尔滨冗杂的多民族饮食特性，如口感多样化，盐适度不同，尽量满足不同消费群体的需求，真正遵循引领哈尔滨红肠文化渗透普及的历史使命。达生曾被评为“黑龙江省著名商标”、“哈尔滨市著名商标”“哈尔滨老字号”“黑龙江省食品安全示范单位”“诚信经营示范企业”等荣誉，生产团队也被省工会评为“工人先锋号”。达生主要经营渠道为线下直营、线上运营、社区团购、线下直营店以嵩山总店、革新商场店、花园街店、秋林商场店、奋斗副食店为主，线上运营主要以天猫旗舰店为主，近年来，主播带货渠道也加强，2020年-2022年，多次与辛巴团队，薇娅团队合作直播带货，销量可观。达生对于代加工业务的承载力的变革只是达生公司在制作精品红肠，带动哈尔滨红肠文化发展中的左膀，随着代加工客户对特有风味与品质要求的需求量加大，创意与研发团队，成为达生尽行业先驱义务的右臂。公司现已创建休闲车间，不断研发休闲类产品，支持代加工、私人定制业务，为客户带来更好的服务体验。', 'https://www.zhaopin.com/jobdetail/CC240267530J40761068411.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4904, '管培生/储备干部', '牧原股份', '7月22日', '1.5-2.5万', '天津-和平区', '农/林/牧/渔', '10000人以上', '已上市', 'CC495147320J40737580911', '一、岗位职责：<br>1、市场分析与规划：收集并分析市场、渠道、客户与产品信息，制定渠道与客户的开发策略；<br>2、客户开发：明确客户需求，挖掘潜在销售机会，协调资源为客户提供极致的产品与服务，为客户创造实实在在的价值，达成合作；<br>3、客户管理：深化客户关系，解决客户难题，提升客户满意度，构建互信双赢的伙伴关系；<br>4、销售管理：协同生产、运营作战，进行每日价格监测、促销、售后、回款等管理，与客户共同挖掘增长机会，提升销售份额。<br>二、任职要求<br>1、本科以上学历，专业不限；<br>2、素质能力：责任心强，目标感强，热爱销售，具有良好的分析和解决问题的能力；<br>3、实践经历：有校园学生会、社团经验、社会实践经验者优先；<br>4、热爱销售工作，愿意长期发展；<br>5、地点：东北、华北、华东、华中、西南、广东等，视意愿就近分配。<br>6、有驾照会开车<br>', '牧原集团位于河南省南阳市，始创于1992年，历经32年发展，现已形成集饲料加工、生猪育种、生猪养殖、屠宰加工为一体的猪肉产业链，主要产品有商品猪、种猪、仔猪和猪肉。目前集团总资产2100亿元，员工14万人，旗下牧原食品股份有限公司于2014年上市，养猪业务遍及全国24省（区）103市217县（区），2023年出栏生猪6382万头。2019年，成立牧原肉食品有限公司，现已成立26家屠宰子公司，发展布局11省22市26县，投产10个屠宰厂，产能2900万头，猪肉销售覆盖20省67市，2023年屠宰生猪1326万头。牧原始终秉承“让人们吃上放心猪肉”的美好愿景，科技赋能养猪产业，致力于打造安全、美味、健康、环保的高品质猪肉，让人们享受丰盛人生。我们为员工提供：企业文化管理及培训、师徒传帮带、高管培养、人才特训营、素质拓展平台、e-Learning平台、国内外交流与咨询。“管理与技术双通道模式”的晋升路径管的宽自封官，敢于担当权无边；能力强自封王，少年将军挑大梁。企业文化：身份：高品质猪肉的生产者；社会进步的推动者。使命：为大众生产安全健康的猪肉食品；推进行业健康发展。愿景：让人们吃上放心猪肉，享受丰盛人生。让公司成为一家受人尊重的企业；核心价值观：创造价值，服务社会；内方外正，推进社会进步。加入牧原，与技术大牛共事，与行业精英一同成长。', 'https://www.zhaopin.com/jobdetail/CC495147320J40737580911.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4905, '储备经理人', '浙江康华眼镜有限公司', '7月17日', '6000-12000元', '台州-None', '金属制品业,金属制品业,电气机械/电力设备', '500-999人', '不需要融资', 'CC248863910J40852951915', '【岗位职责】：<br>1、质量管理；  2、车间产品检验        【任职资格】：    <br>1.本科及以上学历；', '浙江康华眼镜有限公司创建于1978年，位于经济发达的浙江省玉环经济开发区，占地70余亩。公司经过40多年的发展，已成为国内眼镜配件制造行业中的龙头企业之一，是中国眼镜协会副理事长单位。公司以满足顾客需求为己任，秉承“为顾客利益服务”的企业使命，奉行“诚信敬业友善互惠”的企业价值观，逐步实现繁荣“共享”的企业愿景。公司本着坚持“以奋斗者为本、争创卓越康华”的科学管理理念，以“学习创新”为核心竞争力，坚持引进和培养努力奋斗的高水平人才，公司目前有500多名员工，拥有大学学历的近100人，中高级职称近20人。同时成立了玉环市康华教育基金会，为教育事业的发展贡献自己的力量。公司目前主要生产各种金属材料的眼镜配件和饰品，旗下有三家子公司，分别从事合金材料研发和生产、自动化设备研发和生产、进出口贸易，为未来做强做大打下坚实的基础。公司始终坚持“一切为了顾客满意”的管理方针和“追求安全、环保、品质无缺点”的管理目标，通过了市政府质量奖评审、 QES管理体系认证。公司信息化快速发展，先后引进了SAP、西门子PLM、泛微OA、智思云HR和MOM制造运营管理系统等先进管理软件，同时构建了康华云计算平台，有力地提升了康华的信息化管理水平。公司先后荣获行业创新贡献奖、浙江省重合同守信用先进单位、台州市科技进步奖、台州市文明单位、台州市名牌产品、台州市两化融合示范企业、玉环市百强企业、玉环市质量奖和纳税大户等荣誉称号。虚位以待，招聘精英，欢迎有志之士加入我们！！！', 'https://www.zhaopin.com/jobdetail/CC248863910J40852951915.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4906, '资料管理', '哈尔滨市南岗区占金档案管理工作室(个体工商户)', '7月23日', '2000-4000元', '哈尔滨-南岗区', 'IT服务', '20-99人', NULL, 'CCL1486623140J40856960715', '任职要求： 1.具备电脑基础操作能力，会用excel、word等办公软件', NULL, 'https://www.zhaopin.com/jobdetail/CCL1486623140J40856960715.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4907, '日语翻译', '辽宁政通对外劳务经济合作有限公司广州分公司', '7月15日', '1.1-1.5万·14薪', '天津-和平区', '咨询服务,培训/辅导服务', '20-99人', NULL, 'CC815079210J40560431707', '工作内容:<br>1）企划：规划和执行改善方案，店铺运营，商品销售等企划的制定 <br>2）事务：来客接待，员工考勤和管理，制定企划书等文件 <br>3）通信营业：运营促销等活动<br>招聘条件: <br>1.男女不限，面貌端正。 <br>2. 日语N2水平，日常会话流利水平，无证书可<br>3. 吃苦耐劳，有团队合作精神，有一定应变能力。<br>年龄以及学历要求：<br>1）40岁以下 <br>2）大专以上学历工作时间: 每周工作5天，每天工作8小时。<br>薪资待遇: <br>1）月：212000-300000日元<br>2）每年2次加薪（4月/10月），奖金每年2次（8月、1月）<br>3）交通补贴，加班补贴，出差补贴都有 <br>4）提供住宿签证类型：技术人文知识与国际业务', '新干线教育集团旗下子公司，提供境外就业信息、咨询、中介服务,隶属新干线教育集团。新干线教育集团创立于2005年，系沈阳市教育局批准的专门从事语言培训、出国留学、海外就业、境内境外游的综合性集团，目前拥有沈阳新干线外国语培训学校、沈阳政通佳益教育咨询有限公司、沈阳二十一世纪佳益出国留学服务有限公司、辽宁政通对外劳务经济合作有限公司、辽宁政通国际旅行社有限公司，以“培训、留学、就业、旅游”四大模块，全程一站式服务于广大学员。就业模块辽宁政通旗下，先后成立了:辽宁政通对外劳务经济合作有限公司广州分公司、四川分公司，大连分公司，杭州分公司以及日本东京分公司等。多年来，公司一直积极投身于国际文化交流，致力于涉外人才输出。和日本的新干线一样，新干线教育集团以安全、正确、舒适、快速的服务每年向世界各一线学府及涉外工作岗位输送大量优秀人才，为学员走出国门搭建起坚实的桥梁。在市委、市政府领导的关怀下，在国家有关部门的大力支持下，新干线教育集团凭借着贴心的服务、先进的教学理念和完善的海外服务，在培训及人才输出领域脱颖而出，赢得了学员的口碑、市场的青睐，已经成为东北地区语言培训及涉外留学、就业领域的一面旗帜。未来，集团还将一如既往的以诚载信，积极投身于国际文化教育与交流事业，见证更多学员的成长与美好未来，为实现“促进国际交流，铸就百年品牌”的目标而不懈努力。新干线教育集团旗下子公司辽宁政通对外劳务经济合作有限公司，是经中华人民共和国商务部批准并授权颁发《对外劳务合作经营资格证书》[证书编号：LW210020120008],拥有正规资质的境外就业服务机构。公司先后与日本、美国、澳大利亚、新西兰、韩国、新加坡、加拿大、俄罗斯等10余个国家的院校建立了的长期的合作关系，送出去的留学生达数千人。为广大莘莘学子架起了通往成功道路的桥梁。友情提醒：办理出国劳务请选择国家商务部正规资质公司，以防上当受骗，请勿贪图便宜选择那些费用低，待遇高的出国项目，办理前一定要核实中介公司的商务部资质，所有正规的商务部资质公司，注册抵押金均已更改为600万人民币！或登录国家商务部官方网站自行查询~~出国劳务陷阱多，请谨慎选择办理！联系方式：微信公众号：lnzhengtong（出国就业吧）公司网站：www.nhk360.com微信/电信：13889814653新干线李老师公司地址：成都市武侯区科华北路62号力宝大厦1001座机：028-62788831广州市天河区体育西路57号红盾大厦5A26室座机：020-28821709沈阳市沈河区北站路53号财富中心B座15楼座机：024-22523845日本分公司：东京都涩谷区道玄坂2-16-2', 'https://www.zhaopin.com/jobdetail/CC815079210J40560431707.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4908, '储备干部', '中国人寿保险股份有限公司兰州市分公司城关第三营销服务部', '7月19日', '3000-5000元', '兰州-城关区', '保险', '10000人以上', '已上市', 'CC254915630J40799049003', '岗位内容：<br>1、负责招聘工作，应聘人员的预约，接待及面试； 2、员工入职手续办理，员工劳动合同的签订、续签与管理； 3、负责部门一些日常行政事务，配合上级做好行政人事方面的工作；4、作为售后服务部成员，公司下发孤单客户，进行电话邀约，进行后续服务，不强制出外勤；5、工作时间早上8：30-12：00 下午14：00-17：30<br>任职要求：<br>1. 熟悉企业管理优化流程，有较强的战略规划、组织架构设计能力；<br>2.较好的沟通、协作和领导能力；<br>3. 具备一定的财务、市场、人力资源等方面的知识背景。', '中国人寿保险（集团）公司是国有特大型金融保险企业，总部设在北京，世界500强企业、中国品牌500强。中国人寿保险（集团）公司，业务范围全面涵盖寿险、财产险、养老保险（企业年金）、资产管理、另类投资、海外业务、电子商务等多个领域，并通过资本运作参股了多家银行、证券公司等其他金融和非金融机构。中国人寿保险（集团）公司及其子公司构成了我国最大的国有金融保险集团。2013年，总保费收入达3868亿元，境内寿险业务市场份额为31.6%，总资产达24071亿元，是我国资本市场最大的机构投资者之一。连续13年入选《财富》全球500强，排名第94位；连续7年入选世界品牌500强，入选《中国品牌价值研究院》中国品牌500强，位列第15位。是内地资本市场���保险第一股”和全球第一家在纽约、香港和上海三地上市的保险公司，并已成为全球市值最大的上市寿险公司', 'https://www.zhaopin.com/jobdetail/CC254915630J40799049003.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4909, '质检员', '北京华孚聚能科技有限公司', '5月29日', '6000-10000元·13薪', '廊坊-三河市', '电力/水利/热力/燃气,环保', '100-299人', 'B轮', 'CC328575220J40804890215', '岗位职责<br>严格按照部门内各《检验标准书》及《工作流程》完成以下工作：<br>1 负责原材料的入厂检验及记录<br>2 负责半成品及成品的出厂检验及记录<br>3 检验过程中对发现的不合格品给出明确的处理意见并做好相应记录<br>4 负责客户现场备件的提供并做好相应记录<br>5 负责现场返回故障件的检测及维修并做好相应记录<br>6 工作区域的5S管理<br>7 协助领导完成部门内的其它工作', '北京华孚聚能科技有限公司成立于2010年，是一家以电力系统配套设备为主要产品的科技公司，总部位于海淀区中关村上地信息产业基地科技园内，生产基地位于燕郊迎宾路百世金谷产业园内。华孚聚能以电力自动化技术为核心自主研发、生产、销售和服务。企业产品覆盖了电力系统发、输、配、用等各个领域，广泛应用于全国各级电力调度中心、集控中心、发电厂、变电站及大型生产企业。企业自成立以来，依靠高端的技术人才及雄厚的技术力量，追随科技动态，注重科技创新，适应市场需求，研制生产的产品得到广大用户的高度好评。华孚聚能顺利通过ISO9001质量保证体系认证，始终坚持“稳定可靠、持续改进、质量第一”的质量方针，倡导“以人为本、求学、求新、求和、诚信共享、实现共同成长”的企业文化，聚一流人才，做一流产品，以高科技的自动化产品提升电力自动化水平和电力系统的可靠性。公司的主导产品包括:HF-PLC变压器智能风冷控制系统、HF-BP金属波纹式储油柜、HF-PQM电能质量分析仪、HF-ZK开关柜智能操控装置、HF-WXX微机消谐装置。公司网址：www.bjhfjn.com', 'https://www.zhaopin.com/jobdetail/CC328575220J40804890215.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4910, '法务专员/助理', '坂田种苗(苏州)有限公司', '7月1日', '6000-7000元', '苏州-太仓市', '农/林/牧/渔', '20-99人', NULL, 'CC325406010J40693214014', '岗位职责：1.起草、审查各类合同等法律文件，出具相关法律意见<br>          2.为公司日常运营中的各类问题提供法律咨询意见，提示法律合规风险<br>          3.总结工作过程中遇到的问题和经验，制定完善标准化工作内容和流程<br>           4.参与业务模块中法律合规要点的梳理评价、出具法律风险合规建议，促进法律风险管控措施落地<br>          5.提供其他法务支持相关工作，开展法治文化建设和法律培训，提高业务人员法律风险意识<br>            6.领导交办的其他工作<br>岗位要求：1.法律相关专业，本科及以上，通过司法考试优先考虑<br>          2.有较强的责任心、踏实、稳重、认真、严谨，有较好的沟通能力<br>          3.处理问题果断，专业性强<br>          4.英语6级以上者优先考虑', '坂田种苗（苏州）有限公司是由日本坂田种苗株式会社投资的一家中外合资企业。于1998年在中国江苏省太仓市（临近上海）成立。主要从事蔬菜及花卉种子的市场推广和销售管理。坂田中国公司成立十多年来，一直致力于中国农业及园艺事业的发展，积极开发推广适合中国各地的气候条件下的品种，并把世界上最新的优质品种以最快的速度推广到中国。“品质·诚实·奉仕”是我们公司的宗旨，“三方（农民·种子代理商·坂田公司）共赢”是我们的经营理念，提供高品质的种子是我们自始至终都坚持的根本原则。种苗行业的市场规模在不断变大，作为种子行业的我们所担当的职责也在倍增，希望通过我们和您的共同努力，可以为中国的农业以及园艺作出贡献。', 'https://www.zhaopin.com/jobdetail/CC325406010J40693214014.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4911, '档案管理', '成都要得商务信息咨询有限公司', '6月15日', '4000-7000元', '成都-锦江区', '互联网金融/小额贷款', '100-299人', NULL, 'CCL1487547130J40747324611', '岗位职责：<br>每天审核登记客户信息，确认准确性，填写表格，转交给下个部门。每天客户审核20-30个客户 工作内容轻松 <br>上班时间：早上9点半，到下午5点40 就下班<br>午休1个半小时 <br>岗位限制：19-30岁<br>薪资待遇：综合待遇5k<br>工作氛围良好，同事相处和谐，可以一起工作玩耍，经常会进行各种活动，聚餐，都是美女帅哥，年轻同事！', '1、公司氛围很好公司年轻人多，扁平化管理，类似外企的工作氛围1️⃣公司氛围很好，大家都是平等的交流，没有上下级的距离感。在同一桌吃饭的可能有：基层员工、主管、经理、总监等等，在公司也是非常随和。2️⃣工作大多是任务制，领导不会每天盯着你在干什么，只要把安排下去的工作做完就好。3️⃣不加班，工作做完及时走人。没有加班文化，不会为了“努力工作”而加班。有时候我们还在公司，领导就已经走人了；有时候领导没走，我们走了，经过他旁边还会say bye！2、部门氛围很好，相处起来很轻松1️⃣同事的之间都很友好，有问必答不藏私，乐于助人。2️⃣办公室的氛围很好，我们每天都会分享蛋糕、零食和水果。人手一份，你有我有大家有。我们上司有吃的必给我们带一份，我们有吃的也一定会跟他分享。3️⃣同事之间互帮互助、和谐友好、轻松愉快的工作氛围能够帮人更快地熟悉工作任务，适应新环境。', 'https://www.zhaopin.com/jobdetail/CCL1487547130J40747324611.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4912, '储备经理人', '北京链家置地房地产经纪有限公司', '3月17日', '9000-10000元', '北京-海淀区', '房地产中介,电子商务', '10000人以上', '未融资', 'CC252944430J40283822816', '职位描述】：  <br>北京链家，成立于2001年，是以数据驱动的全价值链房产服务平台。上市公司高薪招聘，有能力拼搏的你有时候缺的只是一个好的平台！没有经验也没有关系，只要你肯学肯做我们就愿意教，师傅一对一的教学！  <br>【薪酬福利】：  <br>1. 转正前是试用期：毕业生无责底薪6000元/月（大四实习生无责底薪4500元/月） 转正后：A0入职12个月内是有1年的保障，综合考核（分边和业绩）两个维度取对应最高薪资发放员工，宫格绩效保障薪资范围6000-10000元/4500-10000元不等 ,高提佣30%-90%按阶梯提（计算出综合提点），工作一年后月均薪8000-15000元，提佣上不封顶  <br>2. 五险一金+商业保险；  <br>3. 国家传统节日发放丰厚物资福利，带薪年假及公休假，内部员工租房、购房优惠；月度聚餐及周边游；开单赢大奖免费出国游，年度精英社奖金奖品加免费出国游，赢亲情带家人在人民大会堂奖励大会及国宴；  <br>4. 实习学生可以享受最长3个月的论文答辩假（4月—6月期间）。  <br>【职业发展】:  <br>1、经纪人---店经理---商圈经理---区域总监---异地分公司总经理  <br>2、经纪人---职能专员---职能主管---部门经理---中心总监---副总裁  <br>3、经纪人---分公司/事业部  <br>链家是一个非常年轻的团队，90后00后的加入为链家注入了更多的青春和活力。越来越多的年轻人走上领奖台，接受公司授予的荣誉和使命。  <br>【岗位职责】：  <br>1. 新员工入店，熟悉了解所在商圈；  <br>【不必乘车东奔西走，因为我们的商圈与门店在一起】；  <br>2. 积累客户信息与房源资源；  <br>【店内系统里大量的积累和完善的盘源信息，助您完成前期积累】；  <br>3. 负责客户的接待、咨询，帮助客户完成房屋交易、租赁、资产管理等业务；  <br>【不知如何开口？不必担心，有详细的文字资料教给您】；  <br>4. 详细了解客户的需求，做好信息的合理匹配，提供合适购买方案；  <br>5. 根据客户意向，带客户看房并进行周边环境介绍；  <br>6. 进行商务谈判，促成房产经纪买卖和租赁业务成交；  <br>【从带看到成交，师傅一对一帮扶，带您成功挖掘第一桶金】；  <br>7. 负责业务跟进、客户信息登记及客户关系维护等后续工作；  <br>8. 为客户提供良好的服务，与客户建立良好的业务协作关系；  <br>【服务客户为第一要旨，源源不断的老客户介绍也将接踵而来】  <br>【任职要求】：  <br>统招本科及以上学历，专业不限；  <br>阳光、踏实、务实、拼搏进取；  <br>沟通表达能力强，较强的团队意识和协作精神；  <br>能承受较强的工作压力,且有强烈的上进心。', '北京链家成立于2001年，是中国领先的房地产服务企业，业务覆盖二手房、新房、租房等全方位房产交易和居住服务，目前北京链家有1000余家门店。20年来，北京链家致力于提供安全有品质的服务，在行业率先承诺“不吃差价”、首倡“真房源”、推出“交易不成佣金全退”“电话营销扰一赔百”等18项安心服务承诺，与此同时北京链家也在全面推行店面服务升级和经纪人职业素养提升，坚持对客户好，对经纪人好，对社区好，持续推动行业进步，不断提供更有品质的服务。', 'https://www.zhaopin.com/jobdetail/CC252944430J40283822816.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4913, 'APP推广', '徐州恒盛智谷科技发展有限公司', '7月26日', '3000-6000元', '徐州-云龙区', '企业服务', '20-99人', '未融资', 'CC846231190J40777361907', '如果你想摆脱固定坐班的束缚，又想靠能力赚高薪，那这个岗位超适合你！<br>岗位基本信息：<br>岗位名称：app推广业务经理（小红书）<br>年龄要求：20-35岁，男女不限,高中以上学历<br>薪资待遇：有责底薪+提成，月综合收入3000-8000（业绩优秀者不封顶）或面谈，试用期1-3个月<br>工作模式：无需坐班，灵活安排工作时间，定期线下统一复盘<br>岗位职责： <br>1. 负责线下为主线上为辅助推广小红书指定app业务；<br>2. 结合平台特点制定推广策略，挖掘目标用户；<br>3. 跟踪推广数据，分析效果并及时调整策略，确保推广目标达成；<br>4. 收集用户反馈和平台动态，为团队优化推广方案提供参考。 <br>如果你有一定的沟通和推广意识，愿意为了高薪主动出击，那就赶紧联系我们吧！企业联系方式（同V）1捌01240⑥383，备注“小红书推广+姓名”即可。', '徐州恒盛智谷科技园是由徐州恒盛智谷科技发展有限公司开发运营的徐州市综合型科技园区。坐落于徐州潘安湖科教创新区徐贾快速路旁，江苏师范大学科文学院西侧，星光大道东侧，湖南路北侧。项目周边不仅有科文学院、生物工程学院等多所高校，还有中昂、中钰、大华、融创等优质住宅项目，更有潘安湖、解忧湖等生态景观。结合园区运营理念高度契合科教创新区的区位定位，致力于成为潘安湖科教创新区双创发展的重要载体，提升当地院校创业、就业成功率。徐州恒盛智谷科技园项目占地约150亩，总建筑面积20.6万平方米，是集科技企业孵化基地、中小企业创业基地、服务外包基地、总部基地、高端配套及先进制造基地、文化创意等现代服务业基地为一体的综合型科技园区。', 'https://www.zhaopin.com/jobdetail/CC846231190J40777361907.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4914, '管培生/储备干部', '欣和企业', '7月25日', '8000-10000元', '烟台-福山区', '快速消费品,餐饮服务', '1000-9999人', '未融资', 'CC268650920J40744209310', '欣和期望您的到来，加入我们您将会在总部学习，根据岗位的具体要求完成相关专业知识的系统培训学习，根据其学习及工作表现进行轮岗培养。<br>一、你会拥有多样的发展机会：<br>区域及部门内，渠道销售职能岗位，不同城市的轮岗机会，销售总监为你的发展成长护航。<br>二、你将会有丰富的实践历程：<br>1、了解“六月鲜” “味达美”“葱伴侣”等品牌的销售业务流程、渠道和客户；<br>2、短期进驻公司重点市场，进行经销商与终端门店的维护，完成总体销售目标；<br>3、有效计划行市路线及拜访活动，根据业务需要规划执行各项销售促销活动。<br>三、你将有3-5年的发展空间:<br>3-5年内成长为合格的未来区域销售精英或部门专家!<br>任职资格：<br>1、2023-2025届毕业生，专业不限；<br>2、充满激情，乐于挑战，具有团队合作精神；渴望实现自我，充满正能量；<br>3、沟通能力良好，善于与人交际；<br>4、掌握excel，PPT、word等基本工具，并能熟练呈现、分析<br>我们秉持朝气这种精神，充满信心，充满活力，乐观进取，始终以一种饱满的激情投入到每天的工作之中，永远保持一颗年轻的心，成为一支团结和谐、值得信赖的团队。<br>备注：入职地点是烟台总部，入职后在烟台总部培训轮岗1-2周，然后到不同部门及岗位进行轮岗3个月左右，之后返回区域，需接受省内调动', '欣和创建于1992年，从创建之初开始，就以「家」做事业的核心载体，欣和线下第一款产品——酱，是餐桌上的常客。“我们自己不吃的东西，就不要卖给消费者”是欣和始终秉承的产品质量标准。20年来，欣和从当初的一袋酱，发展成为拥有众多产品的食品企业，欣和业务遍及国内大规模的原酿酱、高品质的高盐稀态酱油、美味方便的花生、辣椒制品、有机食品、味噌等产品的生产销售及餐饮整体解决方案和服务，建立了高效的物流销售服务体系，坚持用高标准打造涉及饮食生态各个环节的产品和服务。目前欣和旗下拥有七大调味品品牌：葱伴侣、味达美、禾然有机、六月鲜、竹笙、有所思、遵循自然。休闲食品品牌：黄飞红。饮用醋品牌：醯官醋、醯子。农业种植品牌：旭耕。欣和作为中国食品行业的先锋企业，以其高标准的产品品质，赢得国内外消费者的信赖。欣和产品的足迹已经遍布全球60多个国家，超过4000万家庭在使用欣和产品。目前欣和旗下拥有七大调味品品牌：葱伴侣、味达美、禾然有机、六月鲜、竹笙、有所思、遵循自然。休闲食品品牌：黄飞红。饮用醋品牌：醯官醋、醯子。农业种植品牌：旭耕。欣和作为中国食品行业的先锋企业，以其高标准的产品品质，赢得国内外消费者的信赖。欣和产品的足迹已经遍布全球60多个国家，超过4000万家庭在使用欣和产品。欣和立志成为能代表中国领先食品的企业，为中国食品行业建立新的标杆，并将可信赖的中国美食带给全世界。欣和上下都在努力践行这份愿景，推动健康生活新浪潮，树立行业新标杆，赢得全球家庭信赖。我们始终带着诚信和责任意识，脚踏实地，携手每一位伙伴共同努力。', 'https://www.zhaopin.com/jobdetail/CC268650920J40744209310.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4915, '售后客服', '速聘无忧(山东)网络科技有限公司', '7月23日', '1.3-2万·13薪', '北京-朝阳区', '企业服务', '100-299人', NULL, 'CCL1504310400J40697205306', '针对客户提出的售后问题，进行快速准确的分析、判断，并给予有效的解决方案与意见<br> 早九晚五 周末双休 法定正常休', NULL, 'https://www.zhaopin.com/jobdetail/CCL1504310400J40697205306.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4916, '内容审核', '石家庄阅准科技有限公司', '7月14日', '4000-5000元·13薪', '洛阳-涧西区', '互联网', '300-499人', '不需要融资', 'CCL1501008410J40731966116', '职位描述1. 负责内容质量评估工作，按照规范的操作流程和标准，及时、准确地完成文字、图片、视频、音频等形式内容的校准和确认，对产品内容安全和质量负责； <br>2. 根据评估标准，识别并处理不符合要求的内容、保证内容安全评估的准确性和时效性，达成相应指标要求； <br>3. 对内容质量运营过程中发现的问题及时反馈，提出合理建议。', NULL, 'https://www.zhaopin.com/jobdetail/CCL1501008410J40731966116.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4917, '广告销售', '睿能科技', '9月5日', '5000-7000元·14薪', '福州-鼓楼区', '电子/半导体/集成电路,IT服务,计算机硬件,计算机软件', '500-999人', '已上市', 'CC652063720J40554832115', '工作职责：<br>1.负责订单跟踪&amp;出货管理<br>2.合同管理<br>3.签收单管理<br>4.协助应收款管理<br>任职要求：<br>1.良好的沟通能力，包括书面和口头表达，能够有效地与内外部客户沟通协调；<br>2.外贸、物流管理、商务相关等专业优先，具备一定的英语能力，英语四级以上<br>3熟练掌握办公软件；<br>4.较强的责任心和团队合作精神，应变能力及抗压能力；<br>工作地点：福州', '睿能科技（股票代码：603933）成立于 2007年，总部位于福州软件园，是专业从事针纺电控、纺织伺服驱动器、智能照明电源的研发、生产及销售的高新技术企业。旗下子公司业务涉及针织行业应用软件研发、IC产品分销、工业电气自动化产品分销及系统集成等。公司自成立以来一直专注于针织横机电控系统的研发、生产和销售，通过多年的沉淀，形成了一批具有国内领先水平的核心技术，拥有多项国家专利和软件著作权。公司研发中心被认定为“中国纺织机械行业电脑横机智能控制系统产品研发中心”、“福建省纺织设备智能控制企业工程技术研究中心”和“福建省省级企业技术中心”，通过持续的自主研发和技术创新，公司横机电控产品性能、品质及良好的服务得到了客户的广泛认可，市场份额位居行业前列。公司始终坚持自主创新，为针织行业提供高品质、智能化的电控产品和先进的针织工艺软件、制版软件及横机联网管理等解决方案，推动传统针织行业的智能化进展，逐步实现从订单、设计到生产的柔性制造，进一步推动中国针织工业的转型升级。公司IC产品分销业务专注于智能电表、电机控制、智能照明、安防监控、医疗电子、工业自动化、变频家电、消费级无人机、可穿戴设备和汽车电子等细分市场的开拓和挖掘，拥有专业的技术支持团队和完善的营销网络，凭借强大的技术支持能力和优秀的市场拓展能力，公司在 IC分销行业中建立了良好的市场地位，赢得了良好的声誉，在中国 IC产品分销领域有着较高市场知名度和美誉度，已成为国内专业的 IC产品授权分销商。同时，公司积极布局发展工业自动化业务，通过发展工业电气自动化产品分销业务以拓展工业自动化领域的系统集成业务。公司将利用自身在自动化控制技术、驱动技术的积累，加强应用研发，坚持专业化方向，聚焦冶金、电力、纺织机械等重点行业市场，提升公司在工业电气自动化领域的竞争力。公司秉承“诚信合作、开放创新、成就客户、共同成长”的经营理念，把握“中国制造 2025”提供的良好发展机遇，坚持以客户需求为导向，持续为客户创造价值，实现企业价值与客户价值共同成长。', 'https://www.zhaopin.com/jobdetail/CC652063720J40554832115.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4918, '律师助理', '北京大成律师事务所', '7月5日', '20-50元/天', '银川-金凤区', '咨询服务,法律服务', '1000-9999人', '未融资', 'CC157836920J40783793012', '实习补助：80-100元/天（包午餐/不包住宿）<br>工作地点：银川市金凤区宁安大街64号德丰大厦22层<br>  职位要求  <br>职位描述:  <br>（1）协助律师完成OA系统工作;  <br>（2）协助律师审查合同/文件;  <br>（3）协助律师起草律师文书;  <br>（4）协助律师办理诉讼仲裁案件;  <br>（5）整理装订业务卷宗；  <br>（6）参与各种会议和拜访/培训活动。  <br>任职要求:  <br>（1）五院四系法学/法律专业本科二年级（研究生一年级）以上;  <br>（2）实习时长两个月或以上;  <br>（3）严谨细致、表达力强、有责任心。', '北京大成律师事务所成立于1992年，是中国成立最早、规模最大的合伙制律师事务所之一。秉承“志存高远，海纳百川，跬步千里，共铸大成”的文化核心理念以及“全球资源、本土智慧”的开放式发展战略，大成始终致力于为国内外客户提供专业、全面、及时、优质、高效的法律服务。经过三十余年的发展，大成已经成为在中国境内拥有超过50家办公室，服务范围覆盖国内全部省、自治区和直辖市，并且与在世界范围内80余个国家及地区设有160多个办公室的Dentons律师事务所拥有优先合作关系的专业化、规模化、国际化、一体化、数字化、平台化、生态化、品牌化的大型综合性律师事务所。', 'https://www.zhaopin.com/jobdetail/CC157836920J40783793012.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4919, '律师助理', '辽宁云拓律师事务所', '7月18日', '2000-3000元', '沈阳-沈河区', '法律服务', '20-99人', NULL, 'CCL1453630830J40737608614', '岗位内容：<br>1. 协助律师处理诉讼案件相关工作，包括法律文书起草，证据材料的整理，庭前准备工作，调查取证工作等诉讼程序相关的工作。<br>2. 辅助执业律师与客户进行案件相关的沟通工作。<br>3. 辅助执业律师积极，快速，准确的进行客户维护。<br>4.辅助执业律师反馈客户问题，有效解决问题。<br>任职要求：<br>1.通过司法考试，取得律师实习证。<br>2.具备法学相关专业背景，主动积极、熟练运用各种办公软件工具；<br>3.具有优秀的沟通表达、协调能力、认真执行工作任务；<br>4.对法律事务有浓厚兴趣，具备较强的学习能力和逻辑思维能力。', '辽宁云拓律师事务所，位于沈河区旭辉中心大厦，是一家由辽宁省司法厅批准设立的合伙制综合性律师事务所。辽宁云拓律师事务所崇尚团队合作的理念和文化，既为当事人提供专业的法律服务，同时也服务于本所全部从业人员。在保留传统律所优秀品质的同时更兼顾律所从业人员的职业规划和收入情况，实现真正的协同办公，共同富裕。辽宁云拓律师事务所欢迎全国各地，志同道合的法律从业者加入，共同开启辽宁地区法律服务从业者2.0时代。', 'https://www.zhaopin.com/jobdetail/CCL1453630830J40737608614.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4920, '商务专员', '杭州宏信进出口有限公司', '1月17日', '8000-15000元', '杭州-余杭区', '贸易/进出口', '20人以下', NULL, 'CC583263480J40801658015', '岗位内容：<br>1. 负责商务部门的日常运营工作，如订单处理、物流跟踪、售后服务等。<br>2. 协助对接合作公司。<br>3. 日常翻译工作含文件、会议等;<br>任职要求：<br>1. 本科及以上学历，市场营销、国际贸易等相关专业优先；<br>2. 具备葡萄牙语听、读、写精通,能日常流利交流(如同时具备英语能力优先)；<br>3. 具备良好的客户服务意识，善于解决问题；<br>4. 具备出色的表达能力和谈判能力。  5、能出差,能接受外派,派驻国:巴西', NULL, 'https://www.zhaopin.com/jobdetail/CC583263480J40801658015.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4921, '知识产权/专利代理', '北京律盟知识产权代理有限责任公司', '5月30日', '6000-9000元·13薪', '北京-东城区', '咨询服务,房地产中介', '100-299人', NULL, 'CC156762725J90250081000', '招聘要求：<br>1、 国家正规院校本科以上学历毕业，专业不限； <br> 2、 要求具有大学英语四级/六级及以上水平； <br>3、 做事认真细致、耐心踏实，责任心强； <br>4、 北京生源优先考虑。 <br>职位福利：五险一金、十三薪、加班补助、带薪年假、补充医疗保险、定期体检、周末双休，年终奖', '北京律盟知识产权代理有限责任公司是一家经国家知识产权局和国家工商行政管理总局指定并授权的涉外专利、商标代理机构。公司的宗旨是因应大中华经济圈的形成和发展，为本地、港台及外国客户提供更加广泛、便捷、有效和高质量的专业知识产权代理服务。', 'https://www.zhaopin.com/jobdetail/CC156762725J90250081000.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4922, '知识产权/专利代理', '深圳市威世博知识产权代理事务所(普通合伙)', '7月22日', '6000-10000元·13薪', '南通-崇川区', '专利/商标/知识产权,专利/商标/知识产权,法律服务,互联网', '100-299人', '不需要融资', 'CC429909110J40180599505', '专利工程师<br>岗位职责：<br>1. 负责专利申请文件的撰写及修改；<br>2. 国内专利代理业务，包括专利文件复审、无效，与专利有关的法律诉讼等；<br>3. 及时与客户沟通，并积极配合客户做好相关专利撰写工作；<br>4. 配合与协助业务人员与客户谈判专利业务，解决客户专利方面的问题。<br>任职要求：<br>1. 正规院校，本科及以上学历；<br>2. 专业为：<br>A.电子信息工程、计算机、通讯工程、应用数学、物理学、 光学、电学、自动化等；<br>B. 机械设计及制造、机械工程、电子类等专业；<br>3. 英语4级以上，或相当于4级水平，有第二外语优先；<br>4. 有相关研发经验人才优先。<br>5. 良好的逻辑分析能力和清晰的文字表达能力；<br>6. 工作认真负责，有耐心，能够配合客户做好专利撰写工作，具有团队协作精神。<br>职位福利：周末双休、五险一金、年底双薪、弹性工作、员工旅游、带薪年假<br>', '企业简介：深圳市威世博知识产权代理事务所成立于2008年，是一家高端专业的知识产权代理机构。荣获国家知识产权局首批知识产权分析评议示范机构（全国仅15家、广东省仅1家）深圳市知识产权优势企业三星级知识产权代理机构全国十佳知识产权代理机构服务队伍由80人以上的专利代理人/分析师（包含13名从业10年以上资深专利代理人）和10位专职软件系统架构与程序人员构成。分支机构郑州、南通、苏州、武汉、西安、美国（办事处），我们立足于深圳、进一步辐射全国。我所是志存知识产权领域，潜心筑梦人实现理想和抱负的优质平台！威世博的人才战略，与大多数专利机构孤军作战、经验闭塞不分享的态度有着显著的差异，我所十分重视充分发挥相互分享、相互协作、相互进步的团队合作精神，且相当重视内部培训，培训主要包含以下几大部分：公司网址：www.weishibo.cn公众号：扫码开启知产新世界（专利那点事儿）', 'https://www.zhaopin.com/jobdetail/CC429909110J40180599505.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4923, '培训师', '广东省广商控股集团有限公司', '7月23日', '4000-8000元', '广州-花都区', '培训/辅导服务,学校/学历教育', '100-299人', '未融资', 'CCL1452100860J40934753504', '岗位职责： <br>1. 承担专业课程教学任务，包括： <br>▶ 专业基础课程： <br>- 生理学基础 <br>- 病理学基础 <br>- 中医学基础 <br>- 中药学 <br>- 健康管理学 <br>- 基础营养学 <br>- 医学心理学 <br>▶ 专业技能课程： <br>- 中药鉴定技术 <br>- 中医药膳学 <br>- 方剂与中成药 <br>- 膳食调查与营养配餐 <br>- 中医养生与亚健康调理 <br>- 中药营销学 <br>- 健康管理师（考证课程） <br>- 中医美容学 <br>- 药事管理与法规 <br>- 商务礼仪 <br>2. 负责班级日常管理及学生健康教育工作 <br>3. 参与中医药特色课程开发与教学改革 <br>4. 完成与中医药健康服务相关的其他教学任务', '广东省广商教育投资有限公司成立于2013-05-13，法定代表人为黄喆诚，注册资本为1000万元人民币，统一社会信用代码为914401140681686863，企业地址位于广州市花都区狮岭南环路28号第2综合楼302-303房，所属行业为商务服务业，经营范围包含：票务代理服务;知识产权服务;软件开发;信息系统集成服务;工业设计服务;网络技术服务;技术服务、技术开发、技术咨询、技术交流、技术转让、技术推广;自然科学研究和试验发展;互联网销售（除销售需要许可的商品）;日用百货销售;社会经济咨询服务;创业空间服务;融资咨询服务;信息咨询服务（不含许可类信息咨询服务）;教育咨询服务（不含涉许可审批的教育培训活动）;组织文化艺术交流活动;商务代理代办服务;科技中介服务;物业管理;企业管理;房地产咨询;市场营销策划;会议及展览服务;个人商务服务;品牌管理;广告发布（非广播电台、电视台、报刊出版单位）;广告设计、代理;人力资源服务（不含职业中介活动、劳务派遣服务）;劳务服务（不含劳务派遣）;从事科技培训的营利性民办培训机构（除面向中小学生开展的学科类、语言类文化教育培训）;企业形象策划;餐饮管理;非居住房地产租赁;居民日常生活服务。广东省广商教育投资有限公司目前的经营状态为在营（开业）企业。', 'https://www.zhaopin.com/jobdetail/CCL1452100860J40934753504.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4924, '销售工程师', '俐凯(上海)智能设备有限公司', '7月21日', '6000-9000元', '上海-闵行区', '通用设备制造,通用设备制造,电气机械/电力设备,专用设备制造', '20-99人', '未融资', 'CC891814120J40696392306', '岗位内容：<br>1.帮助销售人员规划客户拜访计划，跟进客户信息，并完成订单等之后续工作；<br>2. 搜集、整理行业资料；<br>  3. 负责日常客户服务及售前支持，解答客户问题并推荐产品；  <br>3. 协助完成货款回收等事宜，并及时反馈情况；  <br>4. 参与销售活动和宣传方案的实施。  <br>任职要求：  <br>1. 有较强的沟通能力和协调能力，主动思考，做事认真负责；  <br>2. 熟练使用office软件，具备基本的销售知识，了解市场营销相关知识；  <br>3. 具备团队合作精神，勇于承担压力，能够适应出差和加班；', '我司成立于2019年，为外商独资企业，非常希望您能够加入我们这个大家庭。', 'https://www.zhaopin.com/jobdetail/CC891814120J40696392306.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4925, '管培生/储备干部', '禾丰食品股份有限公司', '7月22日', '5000-8000元', '开封-祥符区', '农副产品加工制造,互联网,农/林/牧/渔', '10000人以上', '已上市', 'CC131932530J40798664712', '岗位职责<br>1. 深入了解市场需求，精准推荐产品：<br>经常走访客户，了解他们对肉鸡分割品的具体需求，比如口感、质量、用途（烹饪、加工等）和价格敏感度。<br>根据客户反馈，向生产团队提出改进建议，如调整分割方式、提高肉质口感等，以满足市场需求。<br>2. 制定实际销售策略，提升销售业绩：<br>分析销售数据，找出热销产品和滞销产品，根据库存，确保热销产品畅销，滞销产品找到新渠道。<br>策划促销活动，如限时折扣、买赠活动，吸引客户购买，提高销量。<br>利用社交媒体和线下活动，宣传产品特点，吸引新客户，同时维护老客户，提高客户复购率。<br>3. 建立良好客户关系，提供优质服务：<br>定期与客户沟通，及时解决客户在使用产品过程中遇到的问题。<br>为客户提供产品销售建议，如渠道、烹饪技巧、保存方法等，提高客户对产品的满意度。<br>4. 关注市场动态，及时调整销售策略：<br>密切关注竞争对手的动态，如价格调整、新品推出等，及时调整自己的销售策略。<br>关注行业趋势，了解新技术、新工艺在肉鸡分割皮领域的应用，为公司的产品创新提供建议。<br>5. 拓展销售渠道，增加市场份额：<br>开拓新的销售渠道，增加产品的曝光度和销售量。<br>与潜在客户进行深入沟通，了解他们的需求，提供定制化的解决方案，争取合作机会。<br>任职资格： 1、统招本科及以上学历，动物营养与饲料科学、畜牧兽医、水产养殖等相关专业优先。985/211院校优先考虑。<br>2、责任心强，目标感强，热爱销售，有较好的语言表达能力、较强的逻辑思维和解决问题的能力。<br>3、有校园学生会、社团经验、社会实践经验者优先。<br>4、热爱销售工作，愿意长期发展。<br>本岗位优点：<br>1、新人友好保护期<br>2、实打实的薪酬<br>3、为新人在家门口提供好岗位', '禾丰食品股份有限公司创立于1995年4月，经过不懈奋斗，已发展成为在全球畜牧业舞台上颇具影响力的大型农牧食品企业。公司拥有饲料及饲料原料贸易、肉禽产业化、生猪养殖三大核心业务，同时涉猎动物药品、养殖设备、国际事业、宠物诊疗及食品加工等相关领域。目前拥有200余家下属企业，产品覆盖32个省市，并在尼泊尔、印尼、菲律宾、俄罗斯等国家设有工厂。2006年10月，拥有百年历史的荷兰饲料企业——皇家De Heus公司与禾丰成为战略合作伙伴，在增强禾丰技术研发实力、丰富禾丰管理经验的同时使禾丰始终拥有国际化视野、享有国际化发展资源。 2014年8月8日，禾丰股份于上海证券交易所成功上市。禾丰股份从零起步，2022年合并范围销售收入328.12亿元。28年快速发展，上市9年以来保持业绩持续增长。更多招聘动态，请关注禾丰股份招聘公众号：hfjtzp。', 'https://www.zhaopin.com/jobdetail/CC131932530J40798664712.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4926, '网络客服', '武汉坎伯韦尔科技有限公司', '7月21日', '5000-6000元', '武汉-江汉区', '电子商务,新零售', '20-99人', '未融资', 'CCL1433649550J40664502001', '专注电商15年,跨境电商天花板,私域生态领航者! <br>自家店铺稳居 湖北TOP1,全国TOP10！ <br>加入我们，让你成为更好的自己！职位描述：  <br>  <br>1、公司微信客户群维护；  <br>  <br>2、群内售后问题解答；  <br>  <br>3、与供货商对接，确定售后问题解决方案；  <br>  <br>4、将售后问题解决方案反馈给客户。  <br>  <br>  <br>职位要求：  <br>  <br>1、打字速度1分钟45字以上；  <br>  <br>2、学习能力强、抗压力强；  <br>  <br>3、有无相关工作经验均可。  <br>  <br>职位福利：大小休，五险、带薪年假、绩效奖金 、下午茶', '本公司成立于2012年；公司在澳大利亚墨尔本和中国武汉建有两大总部；长达近十年时间的深耕细作，成为一家规模较大的外贸公司；阿里巴巴旗下澳新联盟商会成员之一；多平台多商城一站式购物服务公司严格考察筛选数千合作代理，坚持诚信经营及优质服务；公司于21年入驻拼多多旗下社群团购平台，蝉联湖北省TOP1，全国TOP13的团长称号；团队朝气蓬勃勇于开拓热情活力公司创始人年轻有为、善于分享、敢于开拓；公司管理层全部由高学历、高素质经验丰富的人才组成，发挥青年人的热情与活力立志成为全球海外商品消费服务业最优电商品牌！公司的用人理念是：招人、用人、育人、成就人。公司的服务宗旨是：让客户拥有愉悦的购物体验。公司的发展愿景是：我们心无旁骛、全心全意地做海外全球商品的“搬运工”并致力于成为商品最纯正、价格最实惠、服务最优质的电商品牌。', 'https://www.zhaopin.com/jobdetail/CCL1433649550J40664502001.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4927, '产品专员/助理', '丝丽控股集团有限公司', '7月11日', '5000-7000元·13薪', '济南-历城区', '医美/健康服务', '300-499人', '不需要融资', 'CCL1474903470J40772993607', '工作描述<br>1.配合产品经理进行医美和化妆品的市场调研、竞品分析、新品开发策划;<br>2. 配合产品经理进行新品配方开发到生产上市的实现;<br>3.负责产品流程审核、配方测试对接等工作;<br>4. 配合产品经理进行产品上市前临床测试、上市后宣传资料输出、售后技术支持<br>等，功效验证等;<br>5.跟进产品生产进度;<br>6.负责包材的筛选、储备与管理等工作;<br>7.领导交代的其它工作；<br>8.公众号运营，展会策划等工作；<br>任职资格：<br>1.化妆品、精细化工、生物化工、化学等相关专业，本科及以上学历，;<br>2.热爱研究化妆品；<br>3.积极主动，工作认真，责任心强，学习能力强；<br>4.较好的沟通能力、口头表达能力、PPT制作能力;<br>福利待遇：五险一金、带薪年假、周末双休、交通补助、话费补助、免费体检等', '公司简介：丝丽控股集团有限公司是一家专注于医美领域的集团性公司，正式成立于2023年5月。团队成员自2018年开始承接REVITACARE旗下产品在中国境内的销售和服务工作（通过国内代理商），2024年丝丽控股成为REVITACARE亚洲区独家代理，运营REVITACARE旗下头部医美产品HAIRCARE丝丽小红帽及面部医美CYTOCARE动能素系列产品，并倾力布局亚太区市场。公司目前共有员工300余人，在国内各地有长期合作的代理商40多家，覆盖终端机构超过2000家。实现年销售收入约3亿元人民币，净利润在7000万元左右。产品简介： 2003年，法国细胞学生物技术研发专家Martine Buzon教授创立REVITACARE实验室，旨在为现代女性提供精准、有效的系列年轻化方案，解决消费者面色暗沉、细纹皱纹、皮肤干燥等衰老问题。实验室出品的CYTOCARE丝丽动能素516及532，于2008年获得欧洲CE安全认证，截止到目前，这两种产品在欧洲已有13年的临床应用历史，并且在肌肤年轻化领域中屡获行业大奖，行销全球40多个国家。丝丽动能素的产品核心力在于“CT50”及“SRN”技术，这也是一直无法被同行超越的关键所在。“CT50”指的是透明质酸+50种活性成分，包括21种氨基酸、11种维生素、14种矿物质、2种核酸、1种辅酶及1种抗氧化物，它们以科学精准地配比协同存在，达到改善肤质，健康养护肌肤的目的。“SRN”缓释网格技术，则是通过技术手段延长活性物质在皮肤中的释放速度，使得效果维持时间更加持久。在“CT50”及“SRN”技术赋能下，临床应用数据显示丝丽动能素具有减少细纹和皱纹、优化肤质、提高肌肤水合力的作用。', 'https://www.zhaopin.com/jobdetail/CCL1474903470J40772993607.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4928, '售后客服', '北京泰达盛凯企业管理有限公司', '7月23日', '7000-10000元', '北京-通州区', '人力资源服务,企业服务,人力资源服务,汽车研发/制造', '300-499人', '未融资', 'CC668182130J40696956406', '早9--晚6 中午管吃<br>薪资：7000—10000面议<br>入职购买五险一金<br>要求：形象气质佳<br>男女不限<br>统招大专 年龄：23---25<br>统招本科 年龄：25——30<br>入职缴纳：五险一金<br>岗位：航天售后<br>（维护客户）<br>不含销售性质<br>主要负责：客户维护<br>1、客户关系维护：通过电话、微信等渠道与客户保持联系，定期更新客户档案，策划并执行客情维护方案，如节日问候、活动邀约等，以提升客户黏性与满意度。<br>2、产品信息传达：精准向客户传达公司产品或服务信息，解答客户关于产品的疑问，帮助客户更好地了解和使用产品。<br>3、需求协调解决：跟进项目，协调公司内部资源，解决客户在产品使用过程中遇到的问题，确保客户需求得到及时处理。<br>4、协助商务环节：参与商务洽谈及接待，协助完成合同签订等关键环节，为客户提供顺畅的合作体验。<br>后续有想挑战高薪者可转销售   投递简历请附带照片', '经营范围：求职、用人登记、用人推荐；介绍地区之间、单位之间的劳务输出与输入、介绍家政服务人员；专业承包；劳务分包；劳务派遣；互北京泰达盛凯企业管理有限公司成立于2018年03月15日，注册地位于北京市北京经济技术开发区科创十三街29号院一区2号楼8层802-03-04，法定代表人为王建。经营范围包括一般项目：企业管理；企业管理咨询；物业管理；人力资源服务（不含职业中介活动、劳务派遣服务）；劳务服务（不含劳务派遣）；安全咨询服务；社会经济咨询服务；建筑物清洁服务；会议及展览服务；组织文化艺术交流活动；广告发布；广告设计、代理；广告制作；建筑装饰材料销售；专业设计服务；日用杂品销售；日用百货销售；软件销售；计算机软硬件及辅助设备零售。（除依法须经批准的项目外，凭营业执照依法自主开展经营活动）许可项目：职业中介活动；建设工程施工；建筑劳务分包；劳务派遣服务。（依法须经批准的项目，经相关部门批准后方可开展经营活动，具体经营项目以相关部门批准文件或许可证件为准）（不得从事国家和本市产业政策禁止和限制类项目的经营活动。）北京泰达盛凯企业管理有限公司具有2处分支机构。收起联网信息服务；城市垃圾清扫、收集；物业管理；企业管理；', 'https://www.zhaopin.com/jobdetail/CC668182130J40696956406.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4929, '内容审核', '徐州通途人力资源有限公司', '2025-07-27 02:00:57', '3000-6000元', '徐州-贾汪区', '咨询服务,人力资源服务', '20-99人', '未融资', 'CC478479510J40860331115', '岗位：电话审核<br>工作内容:打电话核实商家信息是否正确并按要求如实登记。<br>岗位要求:<br>1、普通话标准，头脑清晰，思维敏捷，有良好的人际沟通能力;<br>2、具有较强的学习能力，工作认真负责，心细;<br>3、熟练电脑操作:有打字要求<br>4、有过客服工作经验的可优先考虑;<br>5、大专及以上学历年纪35岁以内<br>薪资待遇：3000-6000元，缴纳五险一金<br>上班时间：早九晚六，午休一个小时，每周排班双休<br>公司地址：徐州东区金龙湖明阳广场附近', '通途人力简介徐州通途人力资源有限公司成立于2012年，系江苏英才控股集团旗下的人力资源企业。公司营业收入过亿，连续四年被评为江苏省级诚信人力资源服务机构，徐州人力资源行业协会常务副会长单位。公司主营业务包括：委托招聘、社保公积金代理、薪资代发、劳务外包、劳务派遣。公司以具有专业禀赋的灵活性和高效率，众多企事业提供了全方位的、专业的人力资源服务。我司荣誉江苏股权交易中心挂牌企业徐州人力资源行业协会副会长单位连续四年江苏省级诚信人力资源服务机构徐州市劳动保障等级评价AAA级单位（最高等级）江苏省人力资源服务机构信用等级评价AAAAA级单位', 'https://www.zhaopin.com/jobdetail/CC478479510J40860331115.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4930, '商务专员', '苍鹭科技(河南)有限公司', '6月18日', '4000-8000元', '郑州-中原区', '人工智能,零售/批发,云计算/大数据,科学技术推广', '20人以下', '未融资', 'CCL1243446420J40671908906', 'DJI 大疆创新成立于2006年，以“ 未来无所不能 ”为主旨理念，在无人机系统、手持影像系统已成为全球领先品牌，以一流的技术产品重新定义了“中国制造”的创新内涵。  <br> DJI大疆行业应用以“重塑生产力”为使命，致力于为政府、公共事业机构及企业客户提供以无人机飞行平台、多样 化负载、专业软件、售后服务与飞行培训为一体的无人机行业解决方案与定制化服务。并以“无人机+”的理念不断 革新、开放技术，与合作伙伴、开发者共同将无人机应用引入工作流中，助力实现产业生态智能化升级。  <br> 苍鹭科技(河南)有限公司是一家专注无人机行业应用的创新型高新技术企业，公司提供包括无人机飞行平台、多样化负载、专业软件、售后服务与飞行培训为一体的无人机行业应用解决方案，并以“行业+无人机”的理念不断革新、开放技术，助力实现产业生态智能化升级。  <br>', '苍鹭科技(河南)有限公司是一家专注无人机行业应用的创新型高新企业，公司提供包括无人机飞行平台、多样化负载、专业软件、售后服务与飞行培训为一体的无人机行业应用解决方案，并以“行业+无人机”的理念不断革新、开放技术，助力实现产业生态智能化升级。DJI大疆创新成立于2006年，以“未来无所不能”为主旨理念，在无人机系统、手持影像系统已成为全球领先品牌，以一流的技术产品重新定义了“中国制造”的创新内涵。 DJI大疆行业应用以“重塑生产力”为使命，致力于为政府、公共事业机构及企业客户提供以无人机飞行平台、多样化负载、专业软件、售后服务与飞行培训为一体的无人机行业解决方案与定制化服务。并以“无人机+”的理念不断革新、开放技术，与合作伙伴、开发者共同将无人机应用引入工作流中，助力实现产业生态智能化升级。苍鹭科技(河南)有限公司作为大疆河南区域的专业服务商，致力于为政府、公共事业机构及企业客户呈现更加智能、高效、安全的全新智能化无人机行业应用场景。我公司的无人机行业应用解决方案已经在测绘、国土、生态环境、公共安全、矿产、林业、水利、应急、电力能源、农业、建筑、基础设施等多个领域得到广泛应用。我公司致力于成为专业的无人机行业应用解决方案供应商，力争把最先进的技术推广至各行各业，改变传统的工作方式，让用户的空间信息数据发挥最大的价值，提升各行业的生产力和经济效益。苍鹭科技(河南)有限公司倡导“诚信、高效、专业”的价值服务理念，发扬“团结、严谨、务实、创新”的企业精神，坚持“以质量夺信誉、以技术求发展、以管理创效益”的经营方针，致力于空间信息数字化，在激烈的市场竞争中勇于挑战自我，不断变革创新，用现代化经营理念，先进的科技手段，为服务型政府的高效管理及科学快速决策提供有力的技术保障，为客户提供一流的专业服务和解决方案。如果你志存高远、怀揣梦想，决心踏实做事、创造价值，那就加入我们吧！在这里，分享属于创新者的快乐，与志同道合者同行，遇见更好的自己！', 'https://www.zhaopin.com/jobdetail/CCL1243446420J40671908906.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4931, '网络销售', '西安意申新能源汽车销售有限公司', '7月21日', '8000-11000元', '西安-未央区', '汽车研发/制造', '20-99人', NULL, 'CCL1460256440J40520508116', '网销专员职责<br>1、为本月呼入来电、网络接洽总量负责;<br>2、对本店网络留资数据具有直接责任;<br>3、与销售部实时沟通，适时掌管活动信息、商务政策<br>信息、资源信息;<br>4、专心学习产品学识、竞品学识、销售流程学识与销<br>售参谋掌管同样话术;<br>5、务必与汽车垂直网站举行深度合作;<br>6、对各汽车网站保持至少每天发布厂家要求数量的软<br>文;<br>7、负责各网站的编辑，页面更新;<br>8、(收集)周边同品牌的网上报价信息;<br>9、收集全体留资信息并转交电话呼入、呼出专员;<br>10、回复客户在线提出的全体疑问。', '西安意申新能源汽车销售有限公司成立于2022年5月，注册资金1000万，占地1000多平方米，坐落于陕西省西安市沣东新城西部车城内。是集维修、汽车配件销售、汽车装璜、美容于一体的四星级维修企业。公司主营比亚迪新能源汽车。汇集整车销售(sale)、零配件(sparepart)、售后服务(service)、信息反馈(survey)四方面为一体的标准化汽车4S服务店。公司拥有宽敞豪华的展厅、优雅休闲一体化的客户休息室，先进专业的汽车保养、维修设备(如双柱举升机、环保烤漆房、四轮定位仪)、充足的原厂优质零配件，高效率的通讯电脑网络系统。公司拥有一批高素质的汽车维修工程师、技师和具有现代化管理理念的中高级管理人员，维修队伍经过专业化的培训，“专业服务每位顾客”是我们的服务理念。我们的宗旨致力为每位员工提供舒适、优良、健康的工作环境，让员工的工作热情最大化；我们致力与客户之间的无界线沟通，为客户提供最诚信、平等、快捷、优质、尊贵的服务。顾客的满意是我们不懈的追求。西安意申全体员工热忱为您提供价值最大化的全面服务！', 'https://www.zhaopin.com/jobdetail/CCL1460256440J40520508116.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4932, '社区运营', '中国平安人寿保险股份有限公司赣鄱支公司', '7月26日', '1.1-1.8万·13薪', '南昌-西湖区', '保险,证券/期货', '10000人以上', '已上市', 'CC326736230J40636125316', '为响应\\\\\"积极应对人口老龄化\\\\\"的国家战略，支持老龄事业发展，满足人民群众多样化的养老需求，2022年9月23日，中国平安(下称\\\\\"平安\\\\\"或\\\\\"公司\\\\\")召开居家养老服务品牌\\\\\"平安管家\\\\\"发布会，重磅发布居家养老服务品牌\\\\\"平安管家\\\\\"。平安人寿党委书记、董事长杨铮在发布会上表示，养老是一项需要长期、专注投入的事业，平安人寿将怀抱敬畏之，以工匠精神，践行\\\\\"专业，让生活更简单\\\\\"的承诺，做专业的养老管家。<br>岗位职责:<br>1.与各大社区居委会合作，做贴心活动<br>2.社区法律免费讲座，普及遗嘱与传承<br>3.宣传公益，中老年投资以安全为主<br>4.推广平安的居家养老项目<br>5.让老人放心，子女安心，管家专心6.通过对多次的服务，打造个人IP<br>7.养老行业任重而道远，非长期主义勿扰<br>任职要求:<br>1、具备出色的沟通技巧和商务谈判能力<br>2、能够独立完成销售任务，具有较强的市场分析和客户管理能力<br>3、对大健康医疗养老行业有热情，能够积极面对挑战，具备良好的团队合作精神', '中国平安保险（集团）股份有限公司于1988年诞生于深圳蛇口，是中国第一家股份制保险企业，至今已发展成为融保险、银行、投资三大主营业务为一体、核心金融与互联网金融业务并行发展的个人金融生活服务集团之一。中国平安在2016年《福布斯》“全球上市公司2000强”中名列第20位；美国《财富》杂志“全球领先企业500强”名列第41位，并蝉联中国内地非国有企业第一。中国平安财产保险股份有限公司是中国平安保险集团长期以来经营和发展的基础，28年来，平安产险业务规模逐年攀升，业务发展稳健。经营区域覆盖全国，在国内各省市、自治区设有42家分公司，2100多个营业网点；此外，还在世界150个国家和地区的近400个城市设立了查勘代理网点。2015年公司整体保费收入突破1600亿，已拥有中国第一大车险品牌，是全国第二大财产保险公司。中国平安财产保险有限公司江西分公司是直属总公司的二级机构，自1993年3月16日成立以来，始终坚守“差异、专业、领先、长远”的经营理念，各项业务规模逐年攀升。是江西省第二大财产保险公司，下辖11家中心支公司，72家分支机构遍布全省大部分县域地区。2016年，公司保费收入将超过24亿元。', 'https://www.zhaopin.com/jobdetail/CC326736230J40636125316.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4933, '广告销售', '上海国际企业商务咨询服务有限公司', '3月14日', '120-150元/天', '上海-黄浦区', '咨询服务,企业服务', '20-99人', '未融资', 'CC303334610J40649895106', '工作内容：<br>1.协助团队进行保险方案的制作、续保、理赔等； <br>2.协助团队向保险公司询价； <br>3.陪同销售人员拜访客户并为其提供多家保司的对比方案； <br>4.负责业务登记及档案留底； <br> 5.上级分配的其他任务。', '上海国际企业商务咨询服务有限公司（简称SIBCO）成立于1999年。作为一家专业的涉外服务型公司，SIBCO主要为外商企业、代表机构及相关外籍人士提供一站式的综合服务，包括人力资源外包与人力资源管理服务，外籍人士证件与陪同服务，财税咨询以及法律支持。多年来，SIBCO在为上千家企业、国外政府机构以及外商行业协会等非营利性机构提供各项服务的历程中，积累了丰富的经验，谙熟中国特色的政策、法规，与政府部门建立友好的合作关系。人事、财税、商务与法务，是每个实体都将面临的实际问题，它们各有专业特点，却往往紧密相连。SIBCO各个部门通力合作，在专业知识的基础上，结合实际操作以及客户需求，为客户提供有特色的综合或专项服务。以专业为基础，以内部合作为优势，SIBCO为您提供专业、周到而贴心的服务。', 'https://www.zhaopin.com/jobdetail/CC303334610J40649895106.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4934, '法务专员/助理', '海南银侨投资有限公司', '7月24日', '4000-6000元', '郑州-金水区', '投资/融资,企业服务,投资/融资,法律服务', '100-299人', '不需要融资', 'CCL1477183290J40867774615', '岗位职责：<br>1.参与非诉讼业务的处理，包括起草管辖权异议申请书、答辩状、上诉状等，具备一定的法律检索能力；<br>2.负责日常与客户之间的沟通工作； <br>3.及时跟踪案件进展；<br>任职要求：<br>1.法学本科学历（能力优秀者法律专科学历也可），熟悉诉讼流程，有从业经验者优先；<br>2.有较强的沟通能力，应变能力，口头及书面表达能力；<br>3.性格稳重，做事认真细致，抗压能力强，具备良好的学习能力和团队合作精神；', NULL, 'https://www.zhaopin.com/jobdetail/CCL1477183290J40867774615.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4935, 'APP推广', '北京烽阳科技有限公司', '7月4日', '1.2-1.8万', '北京-朝阳区', '互联网,互联网', '100-299人', '不需要融资', 'CCL1501322420J40763309510', '岗位职责：<br>1. 通过地推、陌拜等方式开拓新商户，推广商户收款码（聚合收款码牌）。<br>2. 推荐、协助商户完成APP内产品功能的首次体验，手机操作，简单方便。<br>3. 维护并建立良好的商户合作关系，及时反馈处理商户的问题或咨询。<br>任职要求：<br>1. 有自驱力，有赚钱欲望，执行力强，有较强的目标感。<br>2. 吃苦耐劳，沟通能力强，有服务意识，有执行力和抗压力。<br>3. 有地推、陌拜相关经验者优先，直接投递简历即可。<br>薪资福利：<br>1. 无责底薪3000+城市补贴2000+提成+奖金+团建+法休+晋升+老人带教+节日福利。入职缴纳社保！入职缴纳社保！入职缴纳社保！<br>2. 综合1.2万-1.8万，认真做薪资可达2万+。<br>3. 入职签合同，每月16号准时发工资。', NULL, 'https://www.zhaopin.com/jobdetail/CCL1501322420J40763309510.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4936, '律师', '天津瀚海企业管理集团有限公司', '3月28日', '7000-11000元', '天津-西青区', '咨询服务', '100-299人', '未融资', 'CC859803980J40706999111', '一、岗位职责<br>公司提供案源，案源充足，无论是企业法务需求，还是个人纠纷委托，都能精准对接，拓展业务版图。<br>全程负责案件办理，从前期咨询、合同签订，到诉讼、调解等各环节，凭借专业能力为客户提供优质法律服务，维护客户合法权益。<br>建立并维护良好的客户关系，定期回访，及时响应客户法律疑问，凭借专业与服务，打造超高客户口碑，实现业务持续增长。<br>积极参与律所组织的各类业务交流活动，分享成功案例与实务经验，携手团队共同进步。二、任职要求 <br>持有律师执业证，法律功底深厚，通过国家法律职业资格考试 A 证是基本要求。 <br>具备丰富的客户资源与市场开拓能力，能主动出击，将业务机会转化为实际业绩，过往有亮眼业务拓展成果者优先。 <br>擅长各类诉讼与非诉讼业务，熟悉法律实务流程 <br>拥有出色的沟通谈判技巧，能在客户、司法机关等多方之间游刃有余地交流，精准传递法律意见。 <br>高度认同律所文化与价值观，注重团队协作，虽以提成模式工作，但也愿为律所整体发展贡献力量。', '走进瀚海·瀚海简介瀚海企业管理集团（简称“瀚海集团”）秉承“提升企业，分享成功”的经营理念，将二十多年的行业深耕和资源积累服务于社会各业精英企业，以精细化、集约化、个性化的管理模式，满足企业投资，项目开发以及人、财、物等资源的合理配置的需求，为企业的决策、风险管理和发展战略提供可靠的保障。业务领域覆盖审计服务、会计服务、法律服务、税务服务、投资管理咨询、资产评估、房地产评估、资产管理等众多领域。瀚海企业管理集团培育多点支撑的业务增长格局，拥有高水平的管理咨询团队，系统化的培训指导体系，对内定期针对旗下专业公司的发展需求进行相适应的专业指导，技术培训并提供技术支持,持续提升各专业公司的发展能力和价值创造能力,致力于将各专业公司打造成为业内最具潜力的成长型与价值创造型企业。对外整合法律、管理、财税等领域专业，可以为企业客户提供优质、专业、高端的企业内训服务。开放融通，共创共享，瀚海企业管理集团提倡分享机制，集团旗下各专业公司依托集团长期积累的客户资源、业务资源和信息资源，优势互补，共享共赢，从而形成了一个全维度高品质生态服务圈，具备为中央及地方企业集团、上市公司及拟上市公司、金融机构、大型工程业主公司、政府经济主管（监督）部门等服务的能力。践行企业社会责任，瀚海企业管理集团不仅广纳具备专业能力的行业精英，组建系列具备专业服务能力的专业公司，更积极响应国家鼓励支持大学生、退伍军人创业就业的相关政策，为其提供相关的创业就业培训、创业指导及创业支持，以服务社会，回报社会。瀚漫山岳，海纳百川，瀚海企业管理集团以“协同耕植，创享价值”为使命，致力于打造多个具有领先地位的产业发展平台，成为优秀的创享型企业管理集团。', 'https://www.zhaopin.com/jobdetail/CC859803980J40706999111.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4937, '律师助理', '黑龙江大地律师事务所', '3月20日', '3000-4000元', '哈尔滨-南岗区', '咨询服务', '100-299人', '不需要融资', 'CC494186030J40492546710', '工作内容：<br> 1、 掌握法律基础， 辅助团队领导做好案件资料整理;<br> 2、依法依规协助执业律师开展相关的法律事务； 收 发， 整理和保管文件档案资料； <br> 3、处理有关法律问题的来信、来访，解答简单的法律 询问。 协助整理、起草相关文书材料；<br> 4、协助律师调查取证， 抄写文书， 摘录案卷材料等； 积极完成领导交代的其他工作。<br>岗位要求：<br>1、法律类相关专业，本科（含研3学生）以上学历； <br>2、需通过司法考试；<br>3、必须具备较强执行能力和责任心；<br>4、形象佳，思维缜密、沟通表达逻辑清晰；<br>福利待遇：<br>根据工作能力、项目贡献等指标评定：2500元 至8000元/月不等；具备项目独立工作能力后， 年收 入10万元起。 <br>工作时间： 9:00-18:00，提供午餐，双休，法休。<br> 团队有活力，成熟，有稳定的案源， 领导大方，期待 有斗志乐于学习，不甘于平庸的你的加入 <br>PS：请有考公或并未笃定从事律师行业者勿投简历。', '黑龙江大地律师事务所创建于1983年，是我国恢复律师制度以来最早组建的律师事务所之一，2000年顺利完成转型，正式由国有律师事务所成功改制为合伙制律师事务所。黑龙江大地律师事务所以创建法律服务专业化和律师团队规模化为宗旨，凭借一批具有优良职业素质、完整知识结构、朝气蓬勃、锐意进取的中青年律师，多次获得先进律师事务所、司法行政系统迎评工作先进单位等荣誉称号。秉承“守德、求真、务实、敬业”的执业精神和“追求卓越，不负重托”的服务理念，大地律师事务所已发展成为法律服务遍及黑龙江省内各地、市的综合性律师事务所。先后为黑龙江省人力资源和社会保障厅、哈尔滨市道外区人民政府、道外区民政局、平房区人民政府、哈尔滨市松北区土地局、哈尔滨市归国华侨联合会、五常市政法委、哈尔滨电视台、中国银行黑龙江省分行、黑龙江省移动公司、哈尔滨市工业投资集团公司、哈投供热、哈尔滨电厂、哈尔滨电缆厂等近百家机关、事业单位和国企、民企提供法律服务保障，受到客户的一致好评。随着依法治国的深入，律师在构建和谐社会及法治社会中作用的提升，2016年大地律师事务所率先被黑龙江省总工会批准成立“黑龙江省职工法律服务工作站”和“农民工法律服务站”，并积极组织律师开展涉及职工和农民工合法权益保护的宣传和维权行动。路漫漫其修远兮，吾将上下而求索。致力于为客户提供专业、全面、及时、优质、高效的法律服务，是我们不懈努力的追求！', 'https://www.zhaopin.com/jobdetail/CC494186030J40492546710.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4938, '质量管理/测试', '中国标准化研究院', '3月13日', '1.2-1.5万', '北京-海淀区', '学术/科研,社团/组织/社会保障', '500-999人', '未融资', 'CC131321010J40708376009', '一、岗位职责 开展质量工程技术方法研究及推广；质量管理模式研究及我国质量管理经验提炼总结，企业质量管理评估等工作。', '中国标准化研究院（初名国家科委标准化综合研究所）始建于1963年，是直属于国家质量监督检验检疫总局，从事标准化研究的国家级社会公益类科研机构，主要针对我国国民经济和社会发展中全局性、战略性和综合性的标准化问题进行研究。全院现有职工500余人，包括研究员30名、博士及博士后80名，主要开展标准化发展战略、基础理论、原理方法和标准体系研究。承担节能减排、质量管理、国际贸易便利化、视觉健康与安全防护、现代服务、公共安全、公共管理与政务信息化、信息分类编码、人类工效、食品感官分析等领域标准化研究及相关标准的制修订工作。承担相关领域的全国专业标准化技术委员会、分技术委员会秘书处工作。承担相关标准科学实验、测试等研发及科研成果的推广与应用工作。组织开展能效标识、顾客满意度测评工作，承担地理标志产品保护研究及技术支持工作。负责标准文献资源建设与社会化服务工作，承担国家标准文献共享服务平台运行和标准化基础科学数据资源建设与应用工作。同时，我院的工作直接支撑着国家质量监督检验检疫总局以及国家标准化管理委员会的相关管理职能，包括我国缺陷产品召回管理、国家标准技术审查、全国工业产品、食品生产许可证审查等。作为国家级社会公益类科研机构，中国标准化研究院一直致力于积极参与并主导国际组织活动，维护国家利益，承担了国际地理标志网络组织（ORIGIN）副主席职务，承担了国际标准化组织(ISO)的技术委员会副主席、秘书等13个关键职务，主持制定ISO标准20项。在国家质量监督检验检疫总局党组和国家标准化管理委员会党组的坚强领导下，中国标准化研究院紧密围绕中心任务加强党建、廉政建设和精神文明建设，实现常态化、规范化和制度化，采取灵活多样的学习教育方法，开展丰富多彩的文体活动，坚持思想政治工作理论研讨和论文评选活动，连续九年获得中央国家机关文明单位和首都文明单位荣誉称号。', 'https://www.zhaopin.com/jobdetail/CC131321010J40708376009.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4939, '质量管理/测试', '诺博汽车零部件(张家港)有限公司', '7月8日', '6000-8000元·14薪', '苏州-张家港市', '汽车零部件', '500-999人', '已上市', 'CCL1272019250J40453479703', '岗位职责：  1、制定产品质量方面的检验和控制文件；', '诺博汽车零部件（张家港）有限公司隶属于长城汽车下属全资子公司，已于2020年7月注册成立，规划投资11.2亿元，占地5.1万平方米。建设有四大车间，内饰车间、外饰车间、座椅车间、橡胶车间，主要生产门板、仪表板、保险杠、座椅、地毯、顶棚、密封条、减震等产品，包含注塑、喷涂、组装、包吸覆、骨架焊接、座椅发泡、座椅组装、顶棚生产线、地毯生产线、水切割、橡胶炼胶、挤出、结合、组装等全工艺。投产后内外饰、座椅品类产能可达16万台套；橡胶密封条、减震品类产能可达56万台套。', 'https://www.zhaopin.com/jobdetail/CCL1272019250J40453479703.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4940, '内容审核', '石家庄阅准科技有限公司', '7月19日', '4000-6000元·13薪', '石家庄-裕华区', '互联网', '300-499人', '不需要融资', 'CCL1501008410J40727753516', '信息审核<br>负责对可颂app用户提交的机位共建补充信息进行全面审核，依据既定的审核标准，判断其是否符合提升信息丰富度的要求，确保补充信息准确、有效、合规，不包含虚假、侵权或违反平台规则的内容。<br>信息编辑<br>对机位名称进行基础信息命名规范。对可颂app站内信息如机位成图、步导信息、拍摄构图、拍摄建议内容进行站内信息清洗。', NULL, 'https://www.zhaopin.com/jobdetail/CCL1501008410J40727753516.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4941, '电话客服', '哈尔滨博馨康生物科技有限公司', '6月25日', '8000-10000元', '哈尔滨-南岗区', '医药制造', '20人以下', '未融资', 'CC509934430J40111370714', '岗位职责：<br>1、根据公司提供的客户电话，向客户推广公司的产品服务；<br>2、负责接听客户热线，为客户讲解、推广产品；<br>3、通过电话负责客户的约访工作；<br>4、协助配合销售团队，创造销售业绩。<br>任职资格：<br>1、声音甜美，普通话标准，沟通表达能力佳；<br>2、熟练操作办公自动化设备及OFFICE软件；<br>3、良好的执行力和团队合作精神；<br>4、熟悉电话销售或客户服务的业务模式，有电话销售经验者优先。<br>职位福利：项目奖金、带薪年假、补充医疗保险、节日福利、不加班、定期团建、绩效奖金、鼓励内部创新', '哈尔滨博馨康生物科技有限公司创立于2014年，是一家集生物技术开发、药品开发、食品经营、保健用品、医疗机械等于一体的生物科技有限公司。旗下拥有部门：博馨康招商部、博馨康电子商务部、博馨康微营部等多个部门。销售网络覆盖全国各地，即将在哈市启动大型实体连锁。拥有现代化的网络办公，实现企业管理标准化、流程化、数据化。公司工作环境优良，内部管理规范，注重企业文化建设和人力资源培训与开发，能够为员工提供良好的展示自我、实现个人价值的广阔平台。为加速提升企业综合实力，适应企业面临的市场新的发展机遇和挑战，我公司竭诚欢迎有识之士的加入，共同创造哈尔滨博馨康生物科技有限公司美好的明天。', 'https://www.zhaopin.com/jobdetail/CC509934430J40111370714.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4942, '质检员', '沈阳东管电力科技集团股份有限公司', '4月11日', '4000-6000元', '沈阳-铁西区', '专用设备制造,石油/石化,金属制品业,电气机械/电力设备', '300-499人', '已上市', 'CC189169110J40506742001', '岗位分别有材料检验、机加件检验、焊接检验、综合检验，根据个人工作经历匹配岗位', '沈阳东管电力科技集团股份有限公司（以下简称“东管科技”），拥有东管重工（沈阳）有限公司、东管核电新能源装备（沈阳）有限公司等四个子公司），主要从事锅炉、压力容器、高温高压管件、管道系统模块化产品的研发、设计和制造，是高新技术企业。产品主要应用于石油、化工、煤化工、高效火电、核电、天然气发电等能源领域。东管科技位于沈阳经济技术开发区沈西三东路33号，注册资本1.43亿元，现有员工380余人。目前已经获得沈阳市财政局下“恒西创投”总额6,000万股权投资，持有公司11.92%的股份，辽宁省产业创业投资引导基金对集团下属子公司东管核电新能源装备（沈阳）有限公司投资2600万元，实现初步的混合所有制经济形式。2015年12月29日，东管科技在北京新三板正式挂牌上市。2019年东管科技被评为国家级“专精特新”小巨人企业。东管科技厂区占地面积360亩，分二期建设。其中一期工程建筑面积78500㎡已全部投入使用。主厂房为六连跨结构（63800㎡），包含1）压力容器生产车间、2）管件（弯管）生产车间、3）配管车间、4）锅炉生产车间、5）成品、原材料储存仓库，以及与其配套的相关设施如酸洗间、变电所、焊材库、油漆库、检测中心等。一期工程还建设了办公辅楼4000㎡、食堂5000㎡、职工宿舍5700㎡。东管科技拥有压力容器（A1、A2级）制造及设计许可证、锅炉（A级）制造许可证、压力管道元件（A(1)(3)级、B级、B1(2)级）制造许可证，美国机械工程师协会（ASME）颁发的压力容器（U）、锅炉（S）、压力管道（PP）的授权钢印和证书，还通过了ISO质量、环境及职业健康体系认证。公司锅炉、容器类产品包括：电力锅炉类：过热器、再热器、省煤器、低低温省煤器、环形集箱、集箱、布风板等；电力容器类：高压加热器（U型管式、蛇型管式）、低压加热器、除氧器、热网加热器、辅气联箱、耦合器、闭式水换热器、定期排污扩容器，连续排污扩容器、分汽缸、压缩空气储罐等；石化容器类：高温高压单层容器、管壳式热交换器（固定管板，浮头式，U型管式），特殊换热器（高通量管换热器，波节管换热器，螺旋折流板换热器，折流杆换热器，余热回收器，翅片管换热器）、中压汽包、塔器、反应器、反应釜、储罐等。东管集团主要业绩1、石油化工领域：东管集团作为石化设备的设计和制造商，为国内外石化项目提供高品质压力容器设备，主要客户业绩包括：1)中石化：一级供应商，为中科炼化、镇海炼化、燕山石化、沧州石化等项目长期提供换热器、储罐等产品，与中石化洛阳院、上海院、SEI等有长期合同关系，为中科炼化等项目供应加氢裂化高端重型装置。2)中海油：为中海壳牌惠州项目提供P91等高材质管件。3)中国化工集团：为昌邑石化等提供换热器等装置。4)中国化学集团：为中国成达公司的印尼芝拉扎、拉布湾等项目提供管材等产品。5)神华集团：为新疆化工等项目供应高通量管、螺旋折流板换热器等高难度设备。6)大唐集团：为大唐阜新煤制气、克什克腾煤制气、多伦煤化工等项目提供产品。7)阳煤集团：为其下属的昔阳化工、平定化工等项目提供换热器、储罐等产品。8)中粮集团：为其下属的中粮生物化学项目提供管材管件产品。9)地方化工项目：为多家化工企业，如恒力石化、宝泰隆煤化工、唐山金坤化工、盘锦宝来、陕西龙门化工、江西晶昊等化工企业提供反应装置所用容器等设备。10)造纸行业：为晨鸣纸业、玖龙纸业等造纸企业供应管道管件等产品。11)宝泰隆煤化工项目：国内首台波节管重叠式循环气换热器。12)出口项目：为伊朗化肥项目等提供换热设备。2、火电、核电、天然气发电领域：作为电力管道系统及锅炉设备的设计和制造商，为国内外多个火电、核电、天然气发电项目提供服务，核心业绩包括：1）世界首台1350MW超超临界二次再热机组工程——申能安徽平山电厂二期四大管道、管件及工厂化配管供应商2）国内首个1000MW、660MW超超临界火电机组四大管道总承包商,首次引进火电超超临界机组用A335P92钢材。2004年集团中标中国首个1000MW级超超临界火电机组项目——华能玉环电厂（4×1000MW）；2005年中标中国首个600MW级超超临界机组项目——华能营口电厂（2×600MW），成为其四大管道、管件、工厂化加工总承包商。依托这两个项目，东管集团首次引进A335P92管材、管件、焊材应用于国内超超临界火电机组，开创国内A335P92钢使用之先河。3）在行业中率先通过P92钢材焊接性能鉴定。为了适应我国超超临界火电机组的发展需要，填补国内P92新型钢种的焊接工艺的空白。', 'https://www.zhaopin.com/jobdetail/CC189169110J40506742001.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4943, '项目专员/助理', '南京胜德金属装备有限公司', '7月12日', '5000-8000元', '南京-高淳区', '专用设备制造,金属制品业,通用设备制造', '100-299人', '不需要融资', 'CC656116680J40244701504', '岗位职责<br>1、负责压力容器国内/国际订单项目的执行；<br>2、负责订单在企业内部计划、制造、检验、运输等过程的跟踪;<br>3、负责国外客户、第三方监检与生产部门的协调工作；<br>4、完成上级安排的其他工作。<br>岗位要求：<br>1、 热爱制造业，责任心强，积极主动。<br>2、 机械相关专业知识扎实。<br>3、 英语6级，优秀的听、说、读、写能力。（如达不到请勿投递）<br>4、 应、往届毕业生皆可。<br>职位福利：五险一金、年底双薪、包住、包吃、员工旅游、节日福利、健身俱乐部、带薪年假', '南京胜德金属装备有限公司位于南京市高淳经济技术开发区，是专业从事镍基合金、钛合金、铜合金、锆合金、钽合金、高级不锈钢及其复合材料压力容器非标设备设计与制造的国家级高新技术企业。公司主要产品包括反应器、换热器、分离器、储存容器等，广泛用于石化、化工、轻工、制药、冶金、电力、电子、海洋工程及环境保护等领域。胜德金属装备为全球化工50强客户、国内国际工程公司、行业终端用户提供设计及制造方案、产品与服务，产品远销欧洲、美洲、东南亚国家和地区。公司现有压力容器制造厂房15000m2，并配有专用于有色金属焊接的洁净厂房1000 m2。胜德装备拥有中华人民共和国特种设备制造许可证、ASME U钢印及证书、NB钢印及证书和PED证书。公司秉持“质量为本、科学管理、持续改进、客户满意”的质量方针，建立了完善的质量保证体系，并通过美国船级社ABS认证的ISO9001:2015质量管理体系、ISO14001：2015环境管理体系、ISO45001:2018职业健康与安全管理体系认证。我们是一个朝气蓬勃的企业，我们笃信以优制胜、尚德为先的经营理念，我们秉持精工细造、客户至上的服务宗旨；我们欣赏踏实肯干、积极进取的工作态度；我们赞同多劳多得、优绩优酬的努力回报；我们实施人才培养计划，为您量身定制职业规划。如果您和我们一样，想一起并肩于世界的最前沿；如果您和我们一样，怀揣着梦想与激情；请加入我们，和我们一起！我们，虚席以待……', 'https://www.zhaopin.com/jobdetail/CC656116680J40244701504.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4944, '销售助理', '深圳市神州动力数码有限公司', '6月12日', '6000-7000元', '深圳-南山区', 'IT服务,计算机硬件,通信/网络设备', '300-499人', '未融资', 'CC145341820J40493782713', '综合支持部商务助理', '深圳市神州动力数码有限公司成立于2000年5月，华南地区著名的IT领域整合服务商，专注于为行业大客户提供IT整体解决方案的咨询、建设和运维等全方位服务。注册资金3500万元，年营业额4.2亿元，国家高新技术、深圳市高新技术企业，软件企业；百余项IT行业资质齐全。拥有十多项IT专利技术及几十项软件产品著作权。主要与金融、政府、医疗、教育、公共事业、大型企业等数千家行业大客户建立了IT战略合作伙伴关系。公司总部位于深圳市南山区侨香路香年广场，自购写字楼。设有专业数据中心，在广州、珠海、佛山、惠州设有分公司。建有独立的数据实验中心，可搭建各类典型IT应用环境和各类IT方案测试、内部员工日常培训和实验。也可在紧急情况下提供备机使用。现有员工近400人，技术工程师150余人、客户经理100余人。各体系基于实际工作情景构建了完善的培训提升机制。所有员工入职后均需通过对应培训考核，以确保为合作伙伴提供更加专业的服务。主营业务：一、IT系统集成业务：提供从PC等终端到网络、服务器、存储、安全、机房建设、智能建筑等IT基础架构整体解决方案；二、云计算业务：与阿里云及私有云主流云厂商合作，为客户提供混合云和大数据等解决方案。三、IT服务业务：提供桌面、数据中心代维及数据中心维保；弱电工程技术咨询、监理和软件外包。四、软件开发业务：基于客户自身业务或运维服务需要，提供各类定制化软件，如：管理类软件（ERP、客户管理、薪酬、绩效等），大客户运维软件（ITSM、运维监控等），行业软件（病案、档案管理等），以及其他定制开发软件。', 'https://www.zhaopin.com/jobdetail/CC145341820J40493782713.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4945, '销售助理', '江苏快达农化股份有限公司', '7月17日', '7000-10000元', '南通-如东县', '化工', '500-999人', '已上市', 'CC433808310J40701467116', '1、专业要求：化学工程与工艺、应化等化工、市场营销等专业；  2、负责客户的管理，与客户维持健康、良好的商业合作关系 ；  <br>3、整理理货台帐及周、月、年统计，产品包装和运输协调，负责海关加工贸易、贯标及相关内勤工作；  <br>4、协助理货工作，负责取样，发货（分析单），开票及相关数据的统计等；  <br>5、搜集有关市场动态信息资料，预测市场销量，适时调整销售策略；  <br>6、负责相关方信息反馈的记录、统计、分析和处理，接受客户投诉并处理与之有关事宜；  <br>7、其他临时交办的工作任务。  <br>', '江苏快达农化股份有限公司系综合性大型农药化工企业，国内农药生产骨干企业，光气定点生产企业，系原国有如东农药厂整体改制而成，现为利尔化学股份有限公司（股票代码002258）控股51的股份制公司。企业占地面积 75万平方米，其中，洋口化工园区新区 55万平方米，现有农药产品除草剂、杀虫剂、杀菌剂三大系列五十多个品种和酰氯系列、光气化产品等农药、医药、染料化工中间体80多个品种。“快达”商标为中国驰名商标，“银海”商标为江苏省著名商标。快达农化是江苏省高新技术企业，江苏省企业院士中心，公司技术中心为省级技术中心。在立足自主开发的同时，与国内著名大专院校、科研院所加强联合，联手开发高新技术产品。公司现有国家级新产品8个，国家博览会金奖产品3个，江苏省金牛奖产品7个。其中：苄嘧磺隆（稻璑草）、苯磺隆、异菌脲为江苏省名牌产品。快达农化注重企业管理，特别是产品质量管理、安全环境管理、职业健康管理，已通过ISO9001质量体系认证、ISO14001环境体系认证、OHSAS18001职业健康安全管理体系认证和江苏省安全标准化二级企业。快达公司全体员工秉承“诚信、创新、团结、拼搏”的企业精神，与您携手并进，共创美好未来。', 'https://www.zhaopin.com/jobdetail/CC433808310J40701467116.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4946, '产品专员/助理', '贵州珍酒酿酒有限公司', '7月24日', '6000-8000元', '遵义-汇川区', '快速消费品,烟草/酒业', '1000-9999人', '已上市', 'CC553892720J40918113404', '珍酒产品研发人员补充及储备：<br>一、工作内容：<br>1、负责公司产品研发相关工作对接协调；<br>2、负责产品设计、打样、封样工作；<br>3、负责设计公司、供应商产品进度与调整跟进，公司产品评审，并跟踪评审意见及调整进度；<br>4、负责产品管理相关事宜；<br>5、产品名称商标、外观专利审核申请事宜；<br>6、部门日常工作及公司领导交代事宜。<br>二、要求：<br>性别：不限 <br>年龄：30周岁以下<br>学历 ：本科及以上<br>专业要求：艺术设计、美术类相关专业<br>经验要求 ：不限<br>三、其他要求 <br>1、插画能力强者优先；<br>2、设计及包装材料相关专业知识；<br>3、设计软件熟练操作；<br>4、有责任心，能吃苦耐劳，抗压能力强；<br>5、具备优秀的沟通、协调、设计能力。', '贵州珍酒因一代伟人万吨夙愿，创建于1975年，在中国名优白酒中独具传奇色彩，产品多次荣获国内外大奖，是贵州最大民营酒企、贵州三大酱香品牌和中国四大酱酒企业。1986年，根据“酒中珍品”题词定名珍酒。1988年，获国家质量奖优质奖，入选招待外国领导人宴会用酒。2009年，企业成功改制，投入超120亿元增产扩能，产能规模2022年位列贵州酒企前三。2023年，珍酒李渡集团在香港主板上市，成为港股白酒第一股。2024年，产能达4.4万吨，基酒储量10万吨，不断向世界一流酿酒企业迈进。珍酒品牌持续升级，业务快速发展，现面向社会广纳贤才，诚邀您的加入！', 'https://www.zhaopin.com/jobdetail/CC553892720J40918113404.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4947, '质量管理/测试', '常熟华隆人力资源有限公司', '7月22日', '5000-8000元', '苏州-常熟市', '人力资源服务', '20-99人', NULL, 'CC457986230J40777118302', '工作时间：白班:8:00~20:00 工作日根据当日工作是可下五点周六日根据情况上班 薪资待遇：具体薪资面议', NULL, 'https://www.zhaopin.com/jobdetail/CC457986230J40777118302.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4948, '电话销售', '石家庄广利新能源科技有限公司', '6月19日', '7000-10000元', '石家庄-裕华区', '新能源,零售/批发', '20-99人', '未融资', 'CC528552930J40395701008', '岗位职责：<br>1、公司给提供客户资源，不需要自己寻找，精准意向客户；<br>2、根据公司提供的客户资源联系维护客户，不需要出差；<br>3、站在客户角度为其提供优质的服务，耐心，细心为客户讲解公司产品；<br>4、新员工入组前专业培训老员工带，不怕不会，好上手。<br>任职资格：<br>1、学历不限，我们注重的是能力；<br>2、有客服经验优先考虑；<br>3、您是公司的一面镜子，我们时刻都需要微笑接打每一个客户；<br>3、应变、沟通能力要强，日积月累的工作可以使得自己各方面能力得以提升；<br>4、优良的团队合作精神，自律性强。<br>薪金待遇：<br>1、7000-10000+<br>2、入司前有专业老师带你进入岗位，并且带薪；<br>3、年底超长带薪年假，各种节假日福利，团建旅游一年两次。<br>工作时间：<br>长白班9:00--12:00；13:30--18:00，节假日休息；<br>2021年极地新能成立，我们寻求稳定发展，给每一位勤恳的伙伴不仅带来的是经济上的增长，更是心灵和家庭的共同稳定。<br>职位福利：不加班、带团队、定期团建、五险一金、绩效奖金、带薪年假、多次晋升机会<br>职位亮点：工作环境优越，氛围轻松', '石家庄广利新能源科技有限公司，成立的的极地新能品牌创立于2013年，10年的发展历程中，极地新能一直遵循创新并且持续创新的理念，专注新能源电采暖科技领域，致力于为客户提供“安全，智能，环保，健康，节能，舒适”的新能源电采暖产品及全屋智能采暖定制系统解决方案。', 'https://www.zhaopin.com/jobdetail/CC528552930J40395701008.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4949, '英语翻译', '广州欢创信息咨询有限公司', '7月22日', '1-1.3万', '大连-中山区', '人力资源服务,咨询服务,专业技术服务,人力资源服务', '100-299人', '未融资', 'CC531289680J40759103709', '薪资福利：  <br>1、综合：10120—13120，基本工资7000+ 岗位津贴 3000/6000+网络补贴120  <br>2、法定节假日休息  <br>3、五险一金', '广州欢创信息咨询有限公司是一家全国性集团公司，以技术驱动的整体人·财解决方案服务商，全国80+自营分公司，500+服务网点，公司拥有人社局颁发的劳务经营许可、人力资源服务许可等相关行业资质，已获得行业门槛较高的《增值电信业务经营许可证》，同时是众多大型企业的呼叫中心外包服务商。已顺利通过IS09001质量管理体系认证，荣获第七届世界军人运动会后勤保障突出贡献奖、美的集团优秀人才供应商、58集团颁发中国卓越雇主奖、招商银行薪酬福利典范企业，是行业规模、专业素质和客户满意度方面均位居前列的人力资源、税务筹划综合服务商。', 'https://www.zhaopin.com/jobdetail/CC531289680J40759103709.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4950, '销售助理', '佛山市润梦医疗科技有限公司', '5月28日', '6000-12000元', '佛山-禅城区', '医疗设备/器械,医院,医药制造', '20-99人', '未融资', 'CCL1365251300J40765458503', '销售 任职要求：想学习，想赚钱，想发展的。想找个有发展空间的平台的。 <br>录用了都有优秀主管一对一培训，免费提供住宿，公司的氛围生活中像兄弟姐妹一样，工作中都会相互学习和分享，公司的晋升空间很明确，每个人只要达到了晋升的标准就直接晋升职位福利：创业公司', '佛山市润梦医疗科技有限公司是一家互联网医疗健康服务平台，由中润集团联合广东省国资委企业省卫生发展总公司共同开发；是一个致力于把值得信赖的“私人医生”带入中国千家万户的互联网医疗健康服务平台。结合电子商务平台及实体店线下终端市场与青年中医学研究院共同实现线上线下相结合。青年中医学研究院是中国中医科学院培训中心青年中医培训班运营单位，广东省健康管理发展促进会中医药专业委员会会长单位，广东省中医院技术支持合作单位，广东省中医药学会非物质文化遗产委员会单位，广州中医大学技术合作单位，目前已发展为集医学研究、技术交流与培训、中医诊所等一体化医学科研机构。在科研、教学、产业等方面呈迅猛发展势头，在全国有50余家分支机构。', 'https://www.zhaopin.com/jobdetail/CCL1365251300J40765458503.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4951, '储备经理人', '重庆颢气运晟科技有限公司', '7月12日', '6000-12000元', '重庆-渝中区', '零售/批发,企业服务', '20-99人', '未融资', 'CCL1255104680J40445615816', '【任职要求】', '重庆颢气运晟电子科技有限公司,位于重庆渝中区长江一路5号，地铁两路口站附近，交通便利。公司以服务终端市场为主，电子商务和实体店经营为辅。目前已培养出一批成功的创业型企业家。业务涵盖：电子产品、珠宝饰品、百货礼品等多个领域。企业注重以人为本，鼓励每位创业伙伴参与到企业中，“以企为家、以企为荣”努力挖掘个人潜能，在提高生活品质的同事，实现人生价值。在企业远见的经营思路和积极和谐的企业文化氛围中，吸引众多的管理、营销、培训等业界精英。企业文化：合一：学会接纳、学会融合；共赢：互相借力、团队协作；参与：让企业成为“每个人”而非“某个人”的；平等：尊重畅所欲言、共同进取；挖掘：把思考变成习惯、把思路变成实践；卓越：永无止境的追求；发现：让每个“金子”都能发光；栽培：提供让所有“种子”成长的土壤和营养。经营理念及架构： 1.线上电商+线下实体O2O模式：线上商城、官网、微商城、淘宝店、微博的宣传互动和线下实体店的体验，通过遍布全国各大城市地面营销团队的主动宣传业务实现线上线下的对接。 2.经营理念：A.终端市场为导向：“得终端者得市场”对于大多数百货礼品而言，更是如此。 B.优化核心竞争力：我们持续培育企业核心竞争能力——优秀经理人，专注发展自主品牌。在核心竞争力不断优化的基础上，带动企业品牌发展，再稳健发展相关多元业务。 C.整合资源：以战略营销服务平台为依托，通过线上线下的O2O模式，建立企业、品牌的集成平台，利用地面营销团队，实现信息资源的整合，达到资源供需，实现双赢。 D.服务优先：服务优先一切以消费者为先，持续为消费者提供超越其期望的产品和服务，是我们经营行为的首要准则。', 'https://www.zhaopin.com/jobdetail/CCL1255104680J40445615816.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4952, '律师', '北京双北律师事务所', '2月7日', '1-1.5万', '北京-海淀区', '法律服务,法律服务', '20人以下', NULL, 'CC526243730J40546028703', '任职要求：<br>', '北京双北律师事务所成立于2005年，创始合伙人来自法学最高学府的中国政法大学和优秀的部队转业军官。双北律所自成立以来，依托中国政法大学的教育科研背景和学术优势，传承中国人民解放军“招之即来、来之能战、战之必胜”的优秀作风，立足号称“宇宙中心”的中关村核心办公区，秉承“泰来、明法、兢诚、向善”的双北精神，为客户提供专业、精深、高效、贴心的个性化服务，随时可以组织重大、疑难复杂案件的论证。双北律所属于综合性的律师事务所，在民商事代理、刑事辩护、企业常年法律顾问服务等方面均具有专业优势。中国政法大学庞大、优质的国内外校友资源，为双北律师提供了良好的社会沟通渠道，为双北律师与各级各地的国家党政机关、公安、检察院、法院等司法部门以及学术界保持良好的关系提供了便利。在双北，我们注重团队合作和业务研讨交流，鼓励和提倡律师以案件为连接，互相学习和支持。在双北，我们不定期举办各类活动和节日团建，倡导律师不但要专注工作，更要热爱生活，提升律所的文化理念和归属感。我们坚信：每个人，都自带光芒，加入双北，我们帮你光芒万丈。我们聚在一起，定会成为最耀眼的光亮！双北律所，等你来。', 'https://www.zhaopin.com/jobdetail/CC526243730J40546028703.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4953, '质量管理/测试', '京东方科技集团股份有限公司', '3月11日', '1.3-1.7万', '深圳-南山区', '电子/半导体/集成电路,物联网', '10000人以上', '已上市', 'CC161678510J40728163114', '工作职责<br>1. 统筹供应商准入管理，主导或参与新供应商工厂品质审核、产品认证、合同签署<br>2. 组织建立和完善整机TPC结构件一二级供应商资源池，制定材料导入流程和导入规范<br>3. 统筹供应商年度审核计划的制定，联合现地SQA进行品质审核、认证、辅导等工作<br>4. 统筹建立和完善整机TPC结构件供应商品质管控体系，含供应商导入门槛、工艺管控规范、审核checklist等品质相关文件<br>5. 负责整机结构件供应商重大质量问题的分析、改善、拉通<br>6. 华南地区主要结构件供应商季度质量绩效评价、评估、驻厂辅导、处罚，并督促供应商持续改善<br>任职资格<br>教育程度:大专和专科学校<br>工作经历:<br>3年工作经历及以上，有平板电脑SQE结构件相关工作经验优先<br>所需专业:不限<br>其他要求:具有一定的表达能力、统筹能力、执行力<br>语言要求:英语四级通过', '京东方科技集团股份有限公司（BOE）创立于1993年4月，是一家领先的物联网创新企业，为信息交互和人类健康提供智慧端口产品和专业服务，形成了以半导体显示为核心，物联网创新、传感器及解决方案、MLED、智慧医工融合发展的“1+4+N+生态链”业务架构。作为全球半导体显示产业龙头企业，BOE（京东方）带领中国显示产业实现了从无到有、从有到大、从大到强。目前全球每四个智能终端就有一块显示屏来自BOE（京东方），其超高清、柔性、微显示等解决方案已广泛应用于国内外知名品牌。全球市场调研机构Omdia数据显示，2023年前三季度BOE（京东方）在智能手机、平板电脑、笔记本电脑、显示器、电视等五大应用领域液晶显示屏出货量均位列全球第一。', 'https://www.zhaopin.com/jobdetail/CC161678510J40728163114.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4954, '咨询顾问', '深圳加达移民留学顾问有限公司营口分公司', '2025-07-28 00:08:21', '4000-8000元', '营口-站前区', '咨询服务', '20-99人', '未融资', 'CC437796230J40927073004', '高提成的销售我们招了！<br>不画饼，团队年轻有活力，公司靠谱稳定，加达移民留学公司成立10年有余，稳步发展中。公司为每一位员工提供高薪，优越的办公环境和正能量的团队氛围等待遇，期待每一位新同事的加入。<br>【福利待遇】：<br>①新人享带薪培训：入职即享带薪培训，安排1对1师傅代教，手把手带你上岗<br>②底薪+提成+夜班补助，多劳多得，上不封顶。固定时间开工资，只提前不压资。<br>③每周休息一天，丰富的团队活动（定期团建+年度旅游）<br>④公司提供充足的成长空间和资源支持，晋升空间透明且公平<br>⑤舒适专业的办公环境，团队氛围活跃，没有复杂的人际关系，同事之间不抢单。<br>⑥国家法定假日，五险一金<br>【岗位描述和要求】：<br>①<br>大专及以上学历（信任/应届生可培养）<br>②有自己的想法，具备良好沟通、理解能力与服务意识，有客服或销售经验者优先<br>③坐班，不需要自己去找客户，资源公司提供。<br>④用心，想赚钱，有责任心。', '深圳加达移民留学顾问有限公司营口分公司成立于2014年，已经在行业内稳步向上发展10年有余，现处于行业龙头地位，具有很高的市场占有率。现有员工50余人，公司以办理加拿大等五眼联盟国的旅游，留学业务为主。现正处于高速增长期，信赖源于专业，服务提升价值是我们的服务宗旨。我们期待有梦想、有激情的年轻人加入！公司为每一位员工提供优渥的福利待遇，底薪、绩效及额外的红包奖励，多劳多得，上不封顶，不压资。还有定期的旅行计划和团建，有五险一金、年底双薪、法定节假日、节日福利等。', 'https://www.zhaopin.com/jobdetail/CC437796230J40927073004.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4955, '网络销售', '西安赛扬生物科技有限公司', '7月25日', '5000-10000元', '西安-雁塔区', '食品/饮料,电子商务,贸易/进出口,会议/展览', '20-99人', '未融资', 'CC614696220J40820951308', '职位描述：', '西安赛扬生物科技有限公司，坐落于中国自由贸易试验区陕西省西安市高新技术产业开发区，是一家卓力于天然植物萃取有效成分以及天然果蔬粉的研发，生产及销售为一体的高新技术企业。公司目前拥有的果蔬粉果蔬复合粉生产线3条，植物萃取物生产线1条，年产能3000吨左右。在天然植物萃取领域，公司主要以天然植物为原料，采用现代高新技术与传统工艺相结合，专业化开发多种天然植物提取物，采用现代化的结构，为天然产物，健康食品，化妆品等行业提供产品和技术服务。在天然果蔬原粉领域，公司拥有近10年果蔬制品的行业经验，引进国际先进的设备，充分结合优势原料资源，研发生产优质果蔬粉，广泛的应用于各大食品及饮料等生产企业，在产品安全性和稳定性方面，我们严格执行原料谨慎选择，检测设备，检测技术不断提升的理念。我们坚信好的品质肯定有好的的市场，近年来由于公司规模的不断扩大，效益的不断增长，我们也加快了与更多国内外知名公司的合作步伐，力求共赢。已出口到欧美，俄罗斯，东南亚等国家及地区，以优质的产品质量和服务赢得海内外客户青睐。公司一贯秉承“质量为本，诚信经营，客户至上”的宗旨，竭诚希望与海内外各企业建立双赢的合作关系，携手开创美好未来！Xi\'\'an Saiyang Biotechnology Co., Ltd. It is located in Xi\'\'an High-tech Industrial Development Zone, Shaanxi Province, China Free Trade Zone. It is a high-tech company that develops, produces and sells natural plant extract active ingredients and natural fruit and vegetable powder. Currently,our company has 3 fruit and vegetable powder, fruit and vegetable composite powder production lines and 1 line plant extract production with an annual production capacity of 3,000 tons. In the field of natural plant extraction, our company mainly uses natural plants as raw materials, combines modern high-tech with traditional techniques, specializes in the development of a variety of natural plant extracts, and adopts modern structures to provide products for natural products, health foods, cosmetics and other industries Product and technical services. In the field of natural fruit and vegetable powder, our company has nearly 10 years of experience in fruit and vegetable products, introduces internationally advanced equipment, fully combines superior raw material resources, researches and produces high-quality fruit and vegetable powder, and is widely used in various food and beverage production enterprises.', 'https://www.zhaopin.com/jobdetail/CC614696220J40820951308.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4956, '电话销售', '北京互联众信网络技术有限公司', '7月25日', '8000-15000元·13薪', '武汉-洪山区', '电子商务,运营商/增值服务', '500-999人', 'B轮', 'CCL1492585570J40760623509', '公司直招 室内办公不外出行政班<br>园区食堂，无经验要求，<br>这是一份可以稳定发展，平台大，晋升完善明确的岗位~<br>工作内容:后台业务的办理，工作简单，流程性工作 不需要外出<br>薪资：底薪7k，员工综合薪资水平8000-9000； 大部分1W+; 绩优的月入2W+<br>每天吹着空调舒舒服服，室内坐着办公，每周休息2天，法休节假日休，晋升快<br>坐在电脑面前，冬暖夏凉，办公环境优越，一人一台电脑<br>福利：五险一金，满一年有5天带薪年假，每年都会组织国内旅游或者国外游，待遇和福利都不差！<br>内容100％真实有效，绝对不是挂羊头卖狗肉，公司直招，非中介。注意注意!!!集团公司直招!直招!不是中介。<br> <br>三、其他福利:<br>1、公司有食堂，菜品丰富，每月有生日会，部门聚餐，节日福利，开门红餐补，带薪婚假，带薪产假，带薪陪产假，带薪病假等等，公司环境氛围超级好，轻松无压力哦!!!<br>2、入职签订劳动合同，购买五险一金<br>3、公司有冰箱、餐厅、微波炉，可带餐来公司<br>4、每2个月一次晋升机会，晋升发展空间大，管理岗均从内部选拔，可内部晋升可转岗，注重多元化发展', '互联众信是一家大型电子商务、人工智能及数据服务供应商，主要从事大数据、云计算、渠道运营、电子商务、云服务、人工智能AI及信息服务业务，供应链相关软件研发与服务、电商服务运营、企业战略规划及培训和自主平台运营等领域。公司在武汉、天津、广州、深圳、佛山、合肥、宁波、石家庄、西安等地设立运营团队。公司坚持\\\\\"成就客户在互联网领域的新发展、新成功\\\\\"为己任，致力于成为\\\\\"让全世界的生意人和消费者都爱上我们的产品和服务\\\\\"的新一代电子商务人工智能企业。成为国内服务品牌数量最多、服务体系最完善、售后服务人员最多的线上品牌服务商之一。公司汇集了大量行业精英，已组成专业化的市场调研、分析、推广和客户服务团队，同时公司专注于技术实力的投资，以打造全国一流的电商平台公司以着眼于世界领先的融合科技，与国际国内知名企业建立长期战略合作关系，以产、学、研一体化模式。展望未来，公司坚持以市场为导向，以服务抢先机，在未来两年内，公司将实施一体化的分布式战略，努力构筑在电子商务领域最大的资源供应平台，并结合传统与现代的方式，走向世界开辟条全新的道路。企业的文化：我们的理念：一切服从于市场，一切源于客户我们的精神：创新、务实，合作，共赢', 'https://www.zhaopin.com/jobdetail/CCL1492585570J40760623509.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4957, '律师', '北京力同律师事务所', '7月7日', '1-1.5万', '北京-通州区', '法律服务,法律服务', '20-99人', '未融资', 'CCL1300251690J40752163311', '岗位内容：<br>1. 代表客户出庭应诉，审理各类涉诉案件；<br>2. 撰写法律文件，如起诉状、答辩状、申诉状等；<br>3. 参与法律事务的谈判、调解等工作；<br>4. 对相关法律政策进行深入研究和分析，为客户提供咨询意见；  5.为顾问单位进行合同审查、法律文书起草。  <br>  <br>任职要求：  <br>1. 具有扎实的法律基础知识，熟悉相关法律法规；  <br>2. 具备出色的口头表达和书面表达能力，能够撰写高质量的法律文件；  <br>3. 具备良好的分析问题和解决问题的能力，能够沉着应对各种复杂情况；  <br>4. 具备团队合作精神，能够协同其他团队成员共同完成任务。', '一、力同所成立于2015年，主营业务为案件代理、顾问单位日常法律服务。二、目前规模：律师加行政共计9人。三、我们希望您： 1、根据国家有关法律、法规以及律师职业道德和执业纪律，协助执业律师开展相关的法律事务： 2、收发、整理和保管文件档案资料； 3、处理有关法律问题的来信、来访，解答简单的法律询问。协助律师整理、起草相关文书材料； 4、协助律师调查取证，抄写文书、摘录案卷材料等； 5、在得到律师所指派和当事人授权情况下，可以协助律师接收、送达有关诉讼文书； 6、独立审查、起草合同、协议等材料；7、联系沟通律所顾问单位，及时、高效处理相关法律问题； 8、办理律师事务所或律师交办的其他辅助性法律事务。', 'https://www.zhaopin.com/jobdetail/CCL1300251690J40752163311.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4958, '律师助理', '泰和泰律师事务所', '5月19日', '5000-10000元', '杭州-滨江区', '咨询服务', '1000-9999人', '不需要融资', 'CC120880440J40475286716', '◆法律相关专业学士或以上教育背景，本科及以上学历；<br>◆取得国家法律职业资格考试A证，有相关实习经验者优先；<br>◆具备扎实的法律专业知识，较强的文字功底、逻辑思维能力和语言表达能力；<br>◆沟通能力强，具有强烈的责任心及团队协作能力；<br>◆热爱或有志在律师行业长期发展，抗压力强，喜欢有挑战性的工作；<br>◆认同律所管理模式和文化理念，能与律所共同发展。', '泰和泰律师事务所成立于2000年5月25日，系中国领先的大型综合性律师事务所。泰和泰崛起于西部，目前，已在北京、成都、重庆、贵阳、济南、昆明、拉萨、深圳、上海、天津、香港、西安、华盛顿、首尔、釜山等地开设了办公室。太原和悉尼办公室正在筹设中。具有深厚理论基础和丰富实践经验的律师是泰和泰发展的基石。泰和泰注重律师职业发展规划，建立科学的人才机制使泰和泰拥有合伙人230多名、700多名执业律师、千名员工。大多律师毕业于国内外著名法学院，数十名律师具有博士学位及海外留学经历，拥有证券从业、国有资产产权界定、注册会计师、注册税务及专利代理等专业资格。知识管理和专业领域的研究促进了泰和泰专业化的发展。泰和泰成立了近二十余个专业部门，由具有专业特长的合伙人领衔专业律师专注于特定专业领域的深耕和业务拓展，在各个传统业务领域与新兴业务领域，均形成了成熟的法律服务产品；泰和泰设立了专门的业务研究部门作为知识管理平台，专注于各个专业知识的积累和整理，并促进知识在律师团队的交换与使用，以确保泰和泰整体服务水准的不断提升。广泛而优质的客户群体激发了泰和泰服务领域的不断延伸。十多年来，泰和泰在全国范围内积累了长期稳定的客户群体，涉及政府、金融、地产、航空、高端制造、环保、能源、医疗、商业、旅游、文化等各个领域。为满足客户业务扩张对法律服务需求的延展，泰和泰在全球范围内与各类中介机构、行业协会建立了紧密的合作伙伴关系。', 'https://www.zhaopin.com/jobdetail/CC120880440J40475286716.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4959, '管培生/储备干部', '河北水帘农业科技有限公司', '6月19日', '8000-15000元', '石家庄-新华区', '农/林/牧/渔', '20-99人', '未融资', 'CCL1309896060J40814877908', '我公司是一家集滴灌系统生产、设计，安装、水肥一体化技术实践于一体的“服务型”加工企业。每年进行大量的客户回访和对比试验。将滴灌及水肥一体化技术在具体实施中发现的问题及好的做法进行整理并与广大种植业主分享，践行服务至上的企业文化。 就业，较关键的是选对一个有前景的行业，一个可持续发展的公司。 十几年来几亿人口从农村涌向城市，农村现在空出大量土地，国家政策鼓励土地流转及规模化种植，为这些土地服务，将是一个黄金机会！！ 水是农业种植较关键的一环，我们节水灌溉领域就是彻底解决种植用水的问题！投资少，省人工，需求井喷！也切切实实能为种植大户增产增收。目前的需求远大于供给，每年春季、秋季都卖到断货。朝阳行业，选择大于努力，欢迎你的加入！！ 公司团队正在构建中，诚意聘请优秀人才。为以后中层管理者储备人才。<br>我们能提供给新员工的：<br>1、一对一提供专业的岗前技术培训。<br>2、一对一提供专业的销售技能培训。<br>3、一对一提供专业的说话办事技能培训。<br>4、提供一部分客户资源，以便快速适应工作。<br>5、提供稳定的入职期工资保障（早期没有业绩也有丰厚的保障）。<br>6、每个新员工，有专人带领。<br>7、提供宽松愉快、互帮互助、满满正能量的工作环境。（敬告：勾心斗角，心地不善的人不要来应聘）<br>十几年的城镇化，农村很多都成了空心村。全国土地确权已经基本完毕，规模农业势在必行！智慧无人灌溉是*选择。因为地块整合越来越大，干农活的工人越来越少是不可逆的趋势。滴灌技术，让一个工人一天能浇几百亩地成为现实。我们的产品已经成为必需品。<br>另外，我们所面对的客户，是非常朴实的农民，非常容易交往，成单率很高。国家政策也大力扶持！<br>趋势没问题，行业没问题，公司没问题，只缺敢于奋斗的你！欢迎加入我们。<br>岗位职责：<br>1.负责公司客户前期沟通、做预算、做图纸。<br>2.维护好新老客户，拓客，根据客户需求，帮助客户解决技术问题，做好技术指导。<br>3.完成部门领导交代的的其他工作。<br>任职要求：<br>1.本科及以上学历，应届毕业生优先；<br>2. 爱学习，心地善良，善于沟通，工作执行力强；<br>3.表达能力强，有亲和力，有较强的沟通和表达能力；<br>4.office办公软件熟练应用；<br>5.驾驶技术熟练，未发生过重大事故；<br>6.身体健康，能适应偶尔出差；<br>7.征信无不良记录 ；<br>8.农业相关专业优先；<br>作息时间：<br>8:30—12:00；13:30—18:00，<br>8个小时工作日，人性化管理。<br>试用期：3500元+全勤+提成+免费午餐+话补+意外险<br>转正后：10000元/月以上！上不封顶，半年月入轻松过万<br>公司定期组织团建、发放过节福利、不定期旅游<br>职位福利：绩效奖金、月奖励、季度奖励、年底分红、全勤奖、通讯补助、节日福利、生日蛋糕、定期团建<br>我负责引路，你负责赚钱！', '我公司是一家集滴灌系统生产、设计，安装、水肥一体化技术实践于一体的“服务型”加工企业。公司以服务广大农户为核心价值输出，以过硬的产品质量为根基，注重细节，勤于收集，热爱钻研，乐于分享。每年进行大量的客户回访和对比试验。将滴灌及水肥一体化技术在具体实施中发现的问题及好的做法进行整理并与广大种植业主分享，践行服务至上的企业文化。就业，较关键的是选对一个有前景的行业，一个可持续发展的公司。十几年来几亿人口从农村涌向城市，农村现在空出大量土地，国家政策鼓励土地流转及规模化种植，为这些土地服务，将是一个黄金机会！！水是农业种植较关键的一环，我们节水灌溉领域就是彻底解决种植用水的问题！投资少，省人工，需求井喷！也切切实实能为种植大户增产增收。目前的需求远大于供给，每年春季、秋季都卖到断货。这是一个朝阳行业，欢迎你的加入！！公司团队正在构建中，诚意聘请优秀人才。为以后中层管理者储备人才。', 'https://www.zhaopin.com/jobdetail/CCL1309896060J40814877908.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4960, '销售工程师', '石家庄爱科特科技开发有限公司', '7月23日', '5000-10000元', '石家庄-裕华区', '电子/半导体/集成电路,仪器仪表制造,电力/水利/热力/燃气,IT服务', '20-99人', '未融资', 'CC176822420J40615074206', '岗位职责：  <br>', '石家庄爱科特科技开发有限公司成立于2002年4月，是一家集技术开发、产品生产和销售为一体的高新技术企业。公司奉行“团结、敬业、务实、创新”的企业精神，始终贯彻“市场为导向、技术为基础、质量为生命”的企业方针，建立起一支实力雄厚的技术开发团队和一套完善的质量管理体系，并为用户提供全面的服务。公司成立以来，致力于智能电气及自动控制产品的研制开发，产品涵盖智能电气、自动化仪表、无线传感器及配套软件。已研制成功并推广应用的主要有高低压开关柜、RCC系列高低压智能无功补偿控制装置，ACT变频调速系统等。爱科特科技坚持以人为本的人才理念，视员工为企业的最大财富。我们为每位员工提供广阔的发展平台，为每位员工制定科学的职业规划，为每位员工提供有竞争力的薪资待遇、人性化的福利项目、各种文化活动等，期待您的加入！联系电话：0311-87319863武女士', 'https://www.zhaopin.com/jobdetail/CC176822420J40615074206.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4961, '法务专员/助理', '寒锐钴业', '6月16日', '6000-10000元·13薪', '济南-历城区', '石油/石化,矿产/采掘', '1000-9999人', '已上市', 'CC120922560J40753698110', '先期到南京总部培训学习3个月后，随时接受外派国外（非洲、东南亚等）<br>国内6-10K/月，国外20-30万/年<br>岗位职责：<br>1、协助处理海外合规、知识产权等法律事务，配合业务部门进行基础风险识别，在指导下完成合规方案执行。<br>2、协助维护海外律所资源库，监测不同司法区域的合规政策及典型诉讼判例。<br>3、协助收集整理海外商品合规、知识产权保护、广告营销等政策法规更新，建立政策法规知识库。<br>4、参与案件跟进及流程记录，协助完善风险预防措施。<br>任职要求：<br>1、2025届本科或硕士及以上学历，法学/国际法等相关专业；<br>2、具备基础法律英语或法语听说读写能力；<br>3、熟悉Office办公软件，具有基础法律文书撰写能力；<br>4、有学习热情，有志于涉外法务领域发展；<br>5、具备良好的学习能力、沟通协调能力和团队合作精神。<br>', '南京寒锐钴业股份有限公司(Nanjing Hanrui Cobalt Co., Ltd股票代码：300618)创立于1997年，总部位于南京市江宁开发区。经过近二十五年的发展，寒锐钴业已成为拥有十四家分子公司的跨国企业集团，分别是南京寒锐钴业股份有限公司、寒锐金属（刚果）有限公司、刚果迈特矿业有限公司、寒锐地质勘探工程有限公司、安徽寒锐新材料有限公司、江苏润捷新材料有限公司、南京齐傲化工有限公司、赣州寒锐新能源科技有限公司、南京寒锐钴业（香港）有限公司、寒锐钴业（新加坡）有限公司、寒锐投资（南京）有限公司、寒锐钴业（海南）有限公司、海南寒锐私募基金管理有限公司、香港寒锐新能源科技有限公司，企业员工总数1500余人。集团业务涵盖钴铜矿山勘探运作、矿石开采、选矿、冶炼、新能源、新材料，以及铜钴系列产品的生产和销售，具有自主研发和创新能力，并持有自主品牌的高新技术企业。寒锐钴业积极践行“走出去”的国家战略，2007年在非洲刚果(金)投资设立了迈特矿业子公司，从事钴、铜矿资源的开发和产品深加工，形成了从矿产开发、冶炼，直至钴中间产品和钴粉生产的完整产业链，保证了寒锐钴业稳定的原料保障和极具竞争力的产品优势!钴是制造高温合金、硬质合金、金刚石工具、电池材料、防腐材料、磁性材料等的重要原料，广泛应用于航空、航天、电子电器、机械制造、汽车、化工、农业和陶瓷等领域。公司在包括韩国、日本、德国、瑞士、以色列、印度、美国等多个国家和地区建立了营销网络，自主商标在全球16个主要工业国家注册，已经成为中国和世界钴粉产品的主要供应商之一。公司秉承“向世界提供一流钴产品”的企业宗旨和“以品质创品牌，以信誉求发展”的核心价值观，先后通过了ISO9001产品质量管理体系认证、ISO14001环境管理体系认证和OHSAS18001职业健康管理体系认证。寒锐钴业一贯坚持：以钴粉为核心产品，以客户需求为导向，持续为客户提供高质量的产品定制方案;以技术研发创新为龙头，以完整产品产业链为优势，致力于为合作伙伴创造共赢的增值空间!', 'https://www.zhaopin.com/jobdetail/CC120922560J40753698110.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4962, '律师', '河北时代经典律师事务所', '12月16日', '8000-10000元', '石家庄-桥西区', '法律服务,法律服务', '100-299人', '不需要融资', 'CC660319420J40787510915', '岗位职责1.独立处理诉讼案件，并有效推进案件进程；2.掌握法院办案程序，把控案件关键问题，能高效解决诉讼过程中的障碍及不利因素，提升结案质量和效率；3.按律所工作流程.进度节点开展工作并及时上报；4.完成律所及团队分派的其他工作。任职要求1.法律类专业本科以上学历，有律师执业证，硕士优先；2.具有一定的诉讼律师和非诉讼工作经验，熟悉资产重组.企业上市等工作优先；3.可熟练操作各类办公软件，中文写作功底深厚；4.语言表达能力.执行力.人际协调能力强，服从律所和团队管理并承受一定的工作压力；5.具有较强的自我驱动力.强烈的好奇心和良好的道德修养；6.认同专业化.团队化管理.运作模式，具有良好的合作精神。', '河北时代经典律师事务所成立于2002年1月，直属于河北省司法厅，在现有执业律师、律师助理及行政人员共计百余人。在20余年的发展历程中，始终坚持‘’’党建领所、制度立所、人才兴所、文化强所‘’的发展理念。本所自购办公楼位于石家庄市桥西区友谊大街尚峰汇A座13层，拥有办公面积2000余平方米。配置独立办公室25间，工位百余个，另设有党员活动室、会议室、接待室、茶水间、休闲区等。立时代潮头、创经典律所！本所秉持德才并重选聘理念，期待年轻律师的加入，在为个人打下良好律师执业基础的前提下，为我国的法治建设做出应有贡献。', 'https://www.zhaopin.com/jobdetail/CC660319420J40787510915.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4963, '律师', '北京宗帜律师事务所', '7月9日', '6000-8000元', '北京-朝阳区', '法律服务', '20-99人', '不需要融资', 'CCL1487158990J40678695806', '1、不限工作经验；<br>2、认可律所发展理念，愿意和律所共同发展；<br>3、人品好，无任何不良记录和处罚、能吃苦、爱学习；<br>4、入职后由本所各位主任带教，实施定制化培养方案；<br>5、业务类型较多，各类案件都能实际接触并代理，更利于学习；<br>6、同时作为律所的储备干部培养；<br>7、弹性工作制；<br>8、薪资构成基础薪资加提成，高额提成，面谈。', NULL, 'https://www.zhaopin.com/jobdetail/CCL1487158990J40678695806.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4964, '质量管理/测试', '四川福进门人才服务有限公司', '7月25日', '6000-7000元', '成都-温江区', '人力资源服务,企业服务', '20人以下', '未融资', 'CCL1291072470J40735944416', '工作内容：食品品控检测<br>招聘要求：年龄35岁以下，身体健康，无传染病，大专及以上学历。<br>工作时间：8:00-20:00部分夜班<br>薪资待遇：18元/小时+夜班1元/小时+2元/小时（稳岗补贴）<br>所有岗位稳岗补贴需做到中秋节令结束（9月30号左右）享有，节日结束统一补贴。<br>工作期间包工作餐，提供住宿。<br>工作地址：武侯区', '四川福进门人才服务有限公司(以下简称:福进门)，成立于2020年10月是一家经四川省工商局及成都市人力资源和社会保障局批准成立的综合型人力资源公司，为省内大中小企业、外商投资企业、民营企业以及其它用人单位提供:灵活用工、劳务派遣、劳务外包、岗位外包、社会保险代理、代理招聘等相关服务，获得了社会各界的好评和政府劳动人事部门的支持。公司秉承“诚信高效、友好热情、团队协作、执行细节”的服务精神，以客户需求为导向，为用人单位提供有效的人力资源配送服务方案和最优质的服务。', 'https://www.zhaopin.com/jobdetail/CCL1291072470J40735944416.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4965, '知识产权/专利代理', '北京中博世达专利商标代理有限公司', '7月21日', '4000-7000元·13薪', '太原-小店区', '专利/商标/知识产权,法律服务,咨询服务,翻译服务', '300-499人', '不需要融资', 'CC139801890J40710978209', '1.职位要求         1.1统招本科及以上学历，机械相关专业；', '北京中博世达专利商标代理有限公司成立于2003年，20年以来，中博世达以“用优秀的品质为客户提供有价值的服务”为宗旨，以“诚信、勤勉、高效”为发展理念，在业内以服务质量赢得客户信任和好评。中博世达总部位于北京，在国内8个城市设有分公司，目前拥有专业人员400余名，其中：专利代理师78名、律师5名、专利工程师185名，其余为管理、商标、流程及辅助人员。工作语言为：中文、英语、日语、韩语等。中博世达除代理国内外企业和自然人的专利、商标申请及版权登记外，还提供不正当竞争、商业秘密保护、知识产权海关备案、侵权诉讼以及其他知识产权相关事务的代理与咨询服务。中博世达擅长通讯、计算机、电子、物理、机械、自动化、化学等技术领域的专利代理及相关延伸服务，服务对象包括华为、京东方科技、联想集团、海信集团、中国联通、国家电网、海康威视、中国银行、长江存储、本田、佛吉亚等国内外知名企业。中博世达成立以来积极参与多个国内和国际知识产权协会的活动，是国际保护知识产权协会（AIPPI）、国际商标协会(INTA)、中华全国专利代理师协会（ACPAA）、北京知识产权研究会（BIPS）、日本知识产权协会（JIPA）等国内、国际组织的会员。中博世达提供系统化专业培训体系，为优秀专利代理人、专利律师提供广阔的职业发展平台和发展空间！热诚欢迎优秀的您加入我们的团队，共创辉煌！', 'https://www.zhaopin.com/jobdetail/CC139801890J40710978209.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4966, '律师助理', '四川恒和信律师事务所', '7月16日', '90-100元/天', '成都-武侯区', '咨询服务,法律服务', '500-999人', '不需要融资', 'CC130708500J40932430504', '一、职位职责：<br>1.主要协助律师办理破产案件及其相关法律服务；<br>2.协助律师接待破产债权人进行债权申报工作；<br>3.律师、律所交办的其他辅助性法律工作。<br>二、任职要求：<br>1.本科及以上学历，通过法律职业资格考试优先；<br>2.初步掌握法律基础知识，有良好的文字写作能力与口头沟通能力；<br>3.工作认真负责、具有团队合作精神；<br>4.能熟练使用office等办公软件。<br>三、福利待遇：<br>1.工资每月2000元/月+项目提供午餐；<br>2.免费提供工作餐。<br>工作地点：律所内部和成都破产项目<br>实习期限：2个月以上', '一、恒和信概况四川恒和信律师事务所成立于2001年，总部位于四川成都，执业律师及工作人员近500人，同时具有律师事务所资质、证券法律服务资质、专利代理资质。恒和信获得全国律师行业先进基层党组织、全国优秀律师事务所荣誉称号，多次荣登《亚洲法律杂志》ALB中国法律大奖《钱伯斯》大中华区法律指南等国际性榜单，已成为党建引领、服务专业、人才精英、管理规范的全国知名大型律师事务所。恒和信律师在各个专业领域均具有典型成功案例，多次入选最高人民法院公报案例、四川省高级人民法院典型案例、四川省律师十佳辩护词和十佳代理词。二、恒和信文化恒和信取义于“恒力尚法，和美信达”。恒和信律师始终坚持信仰法律，初心不改，和谐幸福，惟愿所及的理念。其中，恒力表示初心不改，牢记使命；尙法表示信仰法律，尊崇法律，践行法律，维护法律；和美表示促进社会和谐平和，保障家和万事兴；信达表示通达事理，见识高远，惟愿所及。恒和信律师坚持专业、责任、价值、奋进的价值观。崇尚法律秉持着对法律的信仰，全身心投入的使命感对客户负责，保护当事人的利益，保守当事人秘密，尽最大的努力为当事人创造价值。对国家负责：将职业责任与社会责任相结合，助力国家法治建设，密切关注人民的法律权益。价值:继责任之上，创造价值。奋进：以学无止境为核心；以学以致用为中心；以精益求精为决心。三、恒和信荣誉（一）国际性荣誉 2021、2022、2023、2024年，四川恒和信律师事务所连续四年荣登《钱伯斯大中华区法律指南》公司商事领域榜单。2023、2024年四川恒和信律师事务所荣登《钱伯斯大中华区指南2023》破产重组领域榜单。2021、2022、2024年，四川恒和信律师事务所多次入围ALB中国法律大奖年度西部律师事务所。2024年04月，四川恒和信律师事务所荣获“2024 ALB China年度雇主”。（二）国家级荣誉 2021年07月，中共四川恒和信律师事务所支部委员会被全国律师行业党委评为“律师行业先进基层党组织”。 2011年12月，四川恒和信律师事务所被中华全国律师协会授予“全国优秀律师事务所”。（三）省市级荣誉 2023年12月，四川恒和信律师事务所党委“未成年人法治教育童谣绘本项目”获“成都市律师行业第二届党建创新项目”。2023年7月，四川恒和信律师事务所《国家级储备油库重大建设项目专项法律服务》获评“四川省律师行业服务重大项目十佳典型案例”。2023年3月，四川恒和信律师事务所党委党员活动阵地被中共成都市律师行业委员会授予“第一届成都市律师行业示范党员活动阵地”。2022年12月，四川恒和信律师事务所被四川省律师协会授予“四川省青年律师培养示范基地”。2022年06月，中共四川恒和信律师事务所委员会第一党支部获评四川省律师行业“十个标准化”品牌党支部。2020年06月，中共四川恒和信律师事务所支部委员会入选四川省律师行业“党建标准化律师事务所党组织”。2019年06月，中共四川恒和信律师事务所支部委员会被中共四川省律师行业委员会授予四川省律师行业“先进党组织”称号。2019年04月，四川恒和信律师事务所被成都市律师协会授予“2017-2018年度成都市优秀律师事务所”。2018年01月，四川恒和信律师事务所被四川省司法厅、四川省律协授予“四川优秀律师事务所”。2017年11月，四川恒和信律师事务所被中共四川省委统战部、省司法厅、省教育厅、省财政厅、省人力资源和社会保障厅、省国税局、省地税局授予“四川同心·服务团活动先进集体”。2016年06月，中共四川恒和信律师事务所支部委员会被中共成都市律师协会委员会授予“先进基层党组织”。2015年07月，四川恒和信律师事务所被四川省司法厅、四川省律师协会授予“四川省优秀律师事务所”。2014年09月，四川恒和信律师事务所被成都市司法局、成都市律师协会授予“2011年-2014年成都市优秀律师事务所”。2013年12月，四川恒和信律师事务所被四川省律师协会授予“四川省优秀律师事务所”。2013年01月，四川恒和信律师事务所被四川省司法厅、四川省人社厅授予“司法行政系统先进集体”。2012年03月，四川恒和信律师事务所被四川省司法厅授予“四川群众喜爱的优秀律师事务所”。 2011年06月，中共四川恒和信律师事务所支部委员会被中共四川省司法厅委员会授予“先进律协党组织”。 2010年05月，四川恒和信律师事务所被四川省司法厅、四川省律师协会授予“四川省优秀律师事务所”。', 'https://www.zhaopin.com/jobdetail/CC130708500J40932430504.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4967, '管培生/储备干部', '深圳市乐有家控股集团有限公司', '7月25日', '9000-11000元', '深圳-宝安区', '房地产中介,房地产中介,咨询服务', '10000人以上', '未融资', 'CC381381910J40797130205', NULL, '乐有家控股集团为“以房地产经纪为龙头、金融和互联网为两翼”的大型企业集团，成立于2008年，总部位于深圳市，以“立足大深圳、密布珠三角、服务全中国”为发展战略，在深圳二手房市场占有率稳居行业第一，粤港澳大湾区多个城市市占率稳居行业前列。集团旗下拥有“乐有家”、“顺联担保”、“万顺通资产”、“家家顺物联科技”等优秀品牌，业务涵盖二手房买卖、房屋租赁、项目策划、新房代理、人工智能、资产管理、金融服务等领域，获得“中国十大品牌中介机构”、“全国优秀房地产经纪机构”、“年度最佳雇主”、“最值得信任的地产经纪品牌”、“广东省诚信企业”、“最具影响力雇主”等殊荣。集团始终坚持“真诚正义，先人后己”的核心价值观，积极推行“真服务、真保障”服务战略，为客户提供及时精准、专业可信、高效超值的房产交易全价值链服务。通过运用互联网、人工智能等新技术，打造线上线下一体化的E2E智能生态系统，致力于为客户打造房产交易全过程、全网络、全家庭生命周期的极致服务体验。集团以“立足大深圳、密布珠三角、连锁全中国”为发展战略，有效整合全国各项资源，实现“有家的地方就有乐有家”的宏伟愿景！', 'https://www.zhaopin.com/jobdetail/CC381381910J40797130205.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4968, '项目经理/主管', '广大住品科技发展有限公司', '7月25日', '6000-10000元', '秦皇岛-海港区', '工业自动化', '100-299人', NULL, 'CCL1289781180J40791854805', '岗位职责：  项目前期规划  <br>1.明确项目目标、范围、时间节点和预算，制定详细的项目计划。  <br>2.识别项目风险，制定风险应对策略，提前规避或降低潜在问题的影响。  <br>3.管理项目团队，明确各成员职责，协调资源分配。', '河北广大保雅装饰工程有限公司成立于1994年, 2017年12月设立独资子公司广大住品科技发展有限公司。广大公司成立至今始终秉承“赋能绿色装配，装配绿色家园”的宗旨，致力于成为装配式装修集部品研发、设计、生产、施工于一体的专业化公司。目前公司已拥有装配式装修部品发明和实用新型技术等专利70余项。公司在医院、康养、商品住宅、办公楼等装配式装修项目的设计、施工方面具有领先优势。先后承接和信办公楼内外装修项目、秦皇岛市天秦装备制造办公楼改造项目、九里桃源地产项目、秦皇岛金色年华普惠养老项目、秦皇岛市第一医院综合门诊楼改扩建项目、北京大学第三医院崇礼院区项目、首都医科大学北京朝阳医院东院区建设工程项目及江苏省康复医院装配式装修课题样板间项目。在学术研究方面我司也致知力行、踵事增华，曾先后参与《居住建筑装配式内装性能评价与认证标准》、《箱板钢结构装配式住宅技术标准》、《住宅装配化装修主要部品部件尺寸指南》、《装配化装修地面部品设计与施工技术》、《装配化装修墙面部品设计与施工技术》、《装配化装修集成卫生间部品设计与施工技术》、《医院建筑装配式装修技术标准》、《装配式装修技术体系应用》等多项行业相关标准的编制工作。作为“中国绿色节能协会绿色医院专委会常务理事单位”，“全国卫生产业企业管理协会医院建筑工程装备分会常务理事会员”，公司三次参加由住建部产业中心主办的北京住博会，会上所展示样板间也连续三年被评为“中国明日之家”展厅。公司还先后被评为“河北省工业企业研发中心”、“河北省中小型科技创新企业”、“国家级高新技术企业”。', 'https://www.zhaopin.com/jobdetail/CCL1289781180J40791854805.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4969, '管培生/储备干部', '焦作汉河电缆有限公司', '7月22日', '5000-8000元', '焦作-修武县', '电气机械/电力设备', '300-499人', '不需要融资', 'CC479265620J40757874601', '1.本科以上学历，理工科，电气工程及其相关专业  2.为公司后续发展提供动力', '焦作汉河电缆有限公司(前身为青岛汉缆股份有限公司焦作分公司)成立于2005年，是焦作市政府招商引资，青岛汉缆股份有限公司全资收购河南金龙电缆有限责任公司超高压交联电缆项目所组建的以电线电缆制造为主的高新技术企业，是焦作市十八家高成长性企业之一。公司注册资本为3.1亿元，占地143亩，厂房总建筑面积6.3万平方米，公司总资产近9.5亿元，现有员工500人。2009年焦作汉河电缆有限公司被授予“中国成长性企业100强”荣誉称号，先后被焦作市政府授予“三十强企业”、“优秀民营企业”、“诚信示范单位”、“重合同守信用企业”、“优秀高成长型企业”、“诚信纳税企业”、“A级纳税信用等级企业”、“纳税突出贡献企业”等荣誉称号。公司拥有三条引进芬兰NOKIA、德国TROESTER国际先进水平的超高压立式交联电缆生产线以及两条悬链式交联电缆生产线、架空绞线等数十台套先进水平的生产、检测装备。可生产500KV及以下交联电力电缆、35KV及以下架空绝缘电缆、3.6/6KV及以下塑力缆、塑料绝缘控制电缆、各种阻燃耐火电线电缆、架空绞线等几十种系列、上万余种规格型号的高、中、低压电线电缆产品。公司自成立当年即从事220KV、110KV电缆的生产，先后为北京、上海、江苏、浙江、湖北、江西、河南、陕西等电力公司和南方电网生产了大量的220KV、110KV电缆，截止2013年年底累计生产220KV、110KV电缆6000余公里，具有良好的运行记录，创造了很好的经济和社会效益。公司中低压及各种特种电缆的销售快速增长，先后为国网河南省公司、郑州祥和集团、多氟多化工股份、河南豫光金铅、中国铝业中州分公司、洛阳升龙广场、南水北调中线工程、郑州精益达汽车扩产项目、武汉通用汽车新建项目、南京华恒输变电有限公司、江苏电力设计院、陕西众源实业发展有限公司、宝鸡能源物资有限公司、焦作光源电力、焦作迈科冶金机械等工程项目和客户提供了各种中低压电缆产品，得到用户的良好评价。公司以市场需求为导向，以开拓创新为动力，以技术过硬为目标，以诚信务实为准则，以客户满意为关注焦点，努力为客户提供质优的产品和服务。', 'https://www.zhaopin.com/jobdetail/CC479265620J40757874601.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4970, '风电工程师', '河北金巽源科技有限公司', '7月26日', '5000-10000元', '锡林郭勒盟-太仆寺旗', '新能源', '100-299人', '未融资', 'CCL1292118440J40676947306', '岗位职责：<br>风力发电机日常巡检、保养维护、设备维修、技术改造等<br>文件资料填写、存档备查。<br>其他现场事务及领导安排事项<br>要求：<br>高压电工证、低压电工证、高处作业证（低压+高处作业为最基础要求 无证者勿扰）。<br>大专以上学历，新能源、风电、机电类相关专业。<br>可接受应届毕业生，年龄无经验30岁以下，有经验40岁以下；<br>福利：六险一金（薪资依据个人技能水平面议）', '河北金巽源科技有限公司位于美丽的海滨城市河北省秦皇岛市，是一家集新能源技术推广、风力发电运维、技改服务、发电机维修、电气设备安装及调试施工与售后服务于一体的综合性现代化公司。公司注册资金5000万元，员工人数180人，其中高、中级技术人员为156名，公司已通过ISO9001-2016质量管理体系认证，并取得了四级承装(修、试)电力设施许可证。公司积极推行现代化管理，重视科技进步，全面推行全面质量管理，在强化安全、服务、质量的同时，最大化满足客户对工程的需求。我们将继续秉承“竣工一项工程、树立一个标杆、交往一方朋友、开拓一片市场”的理念，加强工程全过程管理，努力建设精品工程，服务业主。', 'https://www.zhaopin.com/jobdetail/CCL1292118440J40676947306.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4971, '销售工程师', '苏州伊欧陆系统集成有限公司', '7月22日', '1.5-3万', '广州-海珠区', '电子/半导体/集成电路,通信/网络设备', '100-299人', '未融资', 'CC676206020J40776501614', '岗位职责：<br>1. 熟悉设备原理和专业知识产品的售前技术讲解；<br>2. 了解客户需求， 整理和维护目标区域内已有的客户资源，挖掘目标区域内的潜在客户资源；<br>3. 产品的电话和现场售后服务；<br>4. 负责跟新销售订单，促成订单的生成，分解和完成目标区域内的销售任务（可借助公司各部门的资源和力量）；<br>5. 协助服务工程师完成项目的验收；<br>6. 开发客户资源。<br>任职要求：<br>1. 本科及以上学历，985高校优先考虑；<br>2. 市场营销、微电子、物理学、半导体、机械、电气等相关专业；<br>3. 熟悉半导体知识，熟悉晶圆在片测试测量的优先；<br>4. 能接受出差;<br>5. 中国共产党员优先考虑。<br>福利待遇：<br>1. 五险一金；<br>2. 工作满一年有带薪年假；<br>3. 每年一次境外游，不定期的国内各地旅游（年均2-3次）；<br>4. 广阔的晋升平台和成长空间（不看资历，只看能力）；<br>5. 不同阶段全方位的员工培训（专业技术知识培训、技能培训等）；<br>6. 丰富的休闲生活（每周1-2次篮球、羽毛球、素拓活动）。', '苏州伊欧陆系统集成有限公司是一家集研发、制造、销售、服务于一体的半导体晶圆在片测试测量的高科技公司。总部位于苏州工业园区，目前伊欧陆已在深圳成立了分公司，并在北京、上海、石家庄、成都、厦门、武汉、昆明成立了7个办事处。公司拥有大量的高科技人才，在半导体和光电测试领域有着丰富的经验，目前为客户完成的在片测试测量解决方案已超过500个。Eoulu所提供的产品主要应用于国内大中型科技企业、Fab厂以及各大院校的重点工程中，在国内市场中享有良好的声誉和极高的客户服务满意度。通过在国内市场的长期发展，Eoulu不仅得到一大批全球各大半导体，光电领域的知名公司的全力支持，也在众多客户中树立起了良好的口碑。我们真心希望通过我们长期积累的市场经验和技术经验，为我们的客户提供可信赖的高效的晶圆在片测试测量服务。我们的主营业务如下：自主研发领域内的器件部件和整机设备、提供晶圆级测试整合方案、晶圆级探针台测试测量系统、自主研发future系列半导体测试系统集成软件。其中，公司自主研发的Eoulu F1探针平台系统，是世界上第一台可进化、且具有自主学习能力的探针平台系统，基于专利技术设计的全新数字化3.0系统架构，并采用世界体积最小的12寸探针台，让机台变得更简单、更轻巧。公司现已认定为国家高新技术企业、江苏省瞪羚企业、江苏省民营科技型企业、苏州工业园区专精特新“小巨人”企业，苏州上市苗圃企业、苏州工业园区科技领军人才（成长型项目）、江苏省专精特新企业、苏州市企业工程技术研究中心。Eoulu始终坚持以高质量的服务为核心，与客户共同发展。公司有着完善的技术管理体制和培训考核机制，确保每一位员工都能够与公司共同进步。', 'https://www.zhaopin.com/jobdetail/CC676206020J40776501614.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4972, '销售助理', '成都鑫首创科技有限公司', '7月20日', '5000-7000元', '成都-武侯区', '互联网,IT服务,计算机软件', '100-299人', '未融资', 'CC455149310J40789603013', '任职资格：<br>1、具备一定的售后服务知识，熟悉客诉处理流程，熟练进行计算机操作；<br>2、工作认真负责、积极主动、思路清晰、有较强的学习能力和理解能力、踏实认真；<br>3、掌握一定的数据分析、统计能力；<br>4、具备一定的沟通能力及公文写作能力。<br>岗位职责：<br>1、派工时效:每天清理派工平台，及时处理异常订单，异地订单人工下单<br>2、负责进行新增合作网点系统上架及登记、存档；<br>3、负责服务费用统计及结算处理工作；<br>4、负责服务评价追踪工作；<br>5、负责服务订单质检工作；<br>6、负责公司业务数据整理；<br>7、其他上级安排工作。<br>上班时间：9:00-18:00<br>上班地址：银泰in99<br>职位亮点：提供晋升空间，换岗机会<br>周末双休，节假日同国家<br>职位福利：入职购买五险一金、绩效奖金、加班补助、带薪年假、节日福利、多次晋升机会、出差补贴、话费补助', '鑫首创科技有限公司是蜜蜂智行集团旗下子公司，是一家定位于计算机软件、硬件的研发和计算机、互联网、大数据的技术应用和推广的高科技公司。公司拥有《机动车年检平台》的自主知识产权并运营该平台。机动车年检平台以“政策性，职业性，专业性，创新性，可靠性”为要求为广大车主提供年检咨询，年检预约和各类年检代办服务，同时还经营汽车相关产品。机动车年检平台始终秉承着“服务民众，高效便捷”的理念，旨在为广大的车主提供高效便捷的年检服务。公司没有电销！没有电销！没有电销！', 'https://www.zhaopin.com/jobdetail/CC455149310J40789603013.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4973, '日语翻译', '烟台赛思汇译翻译有限公司', '2月12日', '10-100元/天', '烟台-莱山区', '专业技术服务,IT服务,计算机软件,互联网', '100-299人', '未融资', 'CC310256230J40645217516', '职位描述', 'SuccessGlo Inc. is a translation and localization company created by a group of veteran language professionals. We love meeting the challenges of localization, and we take pride in delivering quality language services to make cross-border communication easier. Our client list boasts some of the largest organizations in the world, including many Fortune 500 companies. SuccessGlo Inc.专注于提供高质量的技术和市场材料翻译、软件本地化与网站本地化服务，帮助客户消除各种语言障碍，助力其在全球的业务发展。我们服务的客户包括全球 500强企业、大型国际组织、各类政府机构等。公司总部位于新加坡，在北京、烟台、济南、越南河内和日本东京设有分公司。Mission使命At SuccessGlo, we live by the value of collaboration while working to create a Localization World Without Walls. To this end, we offer customized translation and localization services to companies across industries to help their businesses grow and glow in global markets.为客户提供定制的行业语言解决方案，帮助客户在全球市场的成功发展。Services服务·Content Translation(General, Industry-specific,Technical, Non-technical)内容翻译·Software and Website Localization/Testing软件和网站本地化/测试·Translation Review- LQA翻译评估·Post-Editing for Machine Translation机器翻译后编辑·Language Assets Management语言资产管理·Desktop Publishing桌面排版', 'https://www.zhaopin.com/jobdetail/CC310256230J40645217516.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4974, '网络客服', '呼和浩特市东大肛肠医院有限责任公司', '7月17日', '4000-6000元', '呼和浩特-玉泉区', '卫生服务,医院', '20-99人', '未融资', 'CC667891820J40013878803', '呼和浩特东大肛肠医院诚聘网络咨询员<br>岗位职责： <br>1、负责网络在线患者的沟通； <br>2、负责患者咨询就诊预约统计及医院开展医疗项目的介绍； <br>3、负责患者咨询的问题解答； <br>4、负责患者咨询所需医疗服务的流程跟进； <br>5、负责领导安排的其他工作。 <br>任职资格： <br>1、在民营医疗机构做过网络咨询者优先。 <br>2、临床医学、中西医结合、药学、护理学等医药相关专业毕业； <br>3、具有丰富的医学常识，能做健康状况的诊断和判定； <br>4、熟悉使用计算机，有电子商务等相关知识； <br>职位福利：包吃、包住、绩效奖金', '呼和浩特东大肛肠医院是一所集医疗、预防、科研、保健、体检、康复于一体，以中西医结合、专病专治为特色的肛肠病专科医院。医院地处玉泉区石羊桥南路鄂尔多斯大街相接，交通便利，环境幽雅，是经呼和浩特市审批局批准的一家肛肠专科医院。我院本着“解决群众肛肠疾苦，促进我市卫生事业发展”的宗旨，汇聚了众多国内肛肠界的权威专家，积极聘请北京各大医院知名专家担任学科带头人，形成了“重点科室突出，特色科室鲜明”的医疗模式。医院先后与北京市肛肠医院、北京东大肛肠医院、北京丰益肛肠医院、北医大附属医院、解放军二炮医院建立了长期广泛的技术合作和学术交流机制，让青城百姓足不出市也能享受到媲美北京的医疗服务。呼和浩特东大肛肠医院多年来重视高、精、尖现代检查、治疗、康复设备的引进及应用，特约中华中医药学会（肛肠）委员，北京市肛肠医院肛肠科主任医师、肛肠科董平专家。除此之外，还拥有当地内蒙古自治区人民医院肛肠科麻书文主任每周一、三、五、坐诊；每周一上午内蒙古自治区人民医院消化内科秦二平主任坐诊；姜国军、焦建国、曲延辉、李永丽、等一大有着丰富临床经验的医生十余位，让青城百姓享受内蒙古自治区人民医院专家的精准诊疗。呼和浩特东大肛肠医院针对痔疮、肛裂、肛瘘、便秘、肠炎及结直肠肿瘤，所采用的肛泰疗法在PPH吻合术、TST选择性切除术、COOK套扎术、HCPT消融术、痔动脉结扎及内镜下治疗等微创诊疗技术的基础上，全面融合中医药治疗，具有痛苦小，创伤小，恢复快等优势，大大降低了患者的身体负担和经济负担。呼和浩特东大肛肠医院率先在呼市实行“男女分诊”制度，本着“尊重女性隐私，呵护女性健康”的宗旨，实现接诊、看病都由女医生完成的诊治方式，避免了以往男医生看病时的尴尬，加强了病人与医生之间的沟通。呼和浩特东大肛肠医院是内蒙古自治区医疗定点服务机构、呼和浩特市城镇职工、城乡居民定点医疗服务机构。多年来，秉承服务于当地百姓的一家肛肠专科医院，欢迎有志同道合优秀人才加入。', 'https://www.zhaopin.com/jobdetail/CC667891820J40013878803.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4975, '销售助理', '河北极正药房连锁有限公司', '5月26日', '3000-5000元', '石家庄-正定县', '医药制造', '20-99人', NULL, 'CCL1267126010J40557221006', '工作时间：8:30-18:00 中午午休一个半小时<br>岗位职责：<br>1、协调各个部门工作<br>2、整理和收集各类文件信息资料<br>职位要求：<br>1、20-25岁之间 实习生实习期需超过三个月<br>2、大专及以上学历<br>3、沟通能力较强，逻辑性好<br>4、熟练应用各类办公软件即设备<br>5、工作仔细认真，责任心强<br>薪资待遇：<br>1、薪资范围：3000-4000<br>2、包住宿，包员工餐', NULL, 'https://www.zhaopin.com/jobdetail/CCL1267126010J40557221006.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4976, '销售运营', '丽水中广未来城商业管理有限公司', '7月24日', '4000-6000元·15薪', '丽水-莲都区', '景区/商业/市场等综合管理', '20-99人', '未融资', 'CCL1474401070J40515673101', '1 、负责所辖区域经营销售指标达成（租金 、物业费 、水电能耗等其他费用）；<br>2 、负责品牌商户联系 、接待 、项目介绍 、洽谈 、签约等工作；<br>3 、负责准备招商相关资料， 掌握招商相关知识， 熟悉招商业务流程；<br>4 、负责收集市场信息，掌握同行业发展动态， 协助主管制制定招商营运计划和实施方案；<br>5 、完成领导交代的其他任务。', '水未来城由中广集团董事长投资，广场将以独有的主力店品牌组合优势，集合各服饰类品牌旗舰店、精品店的形象商品优势,丰富的国内外特色餐饮、服饰、文化、儿童体验业态为主等生活精品业态，再推出网红餐饮街区、24小时不夜城等新型业态，满足聚客、稳场的经营需求，打造品质、创新的商业新地标。', 'https://www.zhaopin.com/jobdetail/CCL1474401070J40515673101.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4977, '电话销售', '上海格思培训学校有限公司', '7月17日', '1.5-3万', '上海-闵行区', '培训/辅导服务', '100-299人', '不需要融资', 'CC485714830J40688909602', '1.为初高中学生制定个性化学习方案，进行1对1、1对 3、小班教学；<br>2.帮助学生提高学习兴趣，养成良好的学习方法及习惯;<br>3.为学生查缺补漏，帮助学生尽快提高学习成绩; <br>4.参加学科教研、学习活动，提高教学水平；<br>岗位要求: <br>1.统招本科学历以上，有教师资格证优先考虑；<br>2.热爱教育教学工作，热爱学生；<br>3.讲课条理清晰、风趣幽默、能够因材施教、启发教学；<br>4.责任心、执行力强；<br>职位福利：<br>定期团建、弹性工作、绩效奖金、五险一金、公费差旅、优秀员工奖金、鼓励内部创新、多次晋升机会。<br>职位亮点：<br>良好的职业生涯发展通道，助你成就事业梦想。', '上海格思教育培训学校是一所专门针对高中学生各科课外补习的专业化培训学校，学校有着独特、过硬的核心教学力量团队。学校以“做最专业化、精细化、深入化的课外培训”为基本理念，聚集各科中最优秀最专业的老师，全心全力打造上海最专业的课外辅导学校，为学生提供最专业的课外辅导。学校拥有成熟的教学理念、专业的师资团队、良好的学习环境，最优的课程配置，教师们兢兢业业，踏实肯干，将自己独有的教学方法和模式传授给学生们。在老师的启发下掌握适合自己的学习方法，从而提高对科目的兴趣！', 'https://www.zhaopin.com/jobdetail/CC485714830J40688909602.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4978, '项目专员/助理', '上海千崖康药生物科技有限公司', '7月8日', '7000-8000元', '上海-浦东新区', '医药制造,医药制造,生物工程', '20人以下', '天使轮', 'CCL1369987710J40786064703', '岗位职责：<br>1. 协助领导进行项目管理和协调工作<br>2. 项目录入及跟踪项目进度，及时汇报项目状态<br>3. 协助处理项目中的问题，确保项目顺利进行<br>岗位要求：<br>1.本科及以上学历，医学、动物医学、兽医等相关专业优先<br>2. 具备良好的沟通和协调能力<br>3. 有较强的学习和适应能力，能快速掌握项目相关业务知识<br>4. 具备良好的时间管理能力，能按时完成工作任务<br>5. 熟练使用办公软件，如Word、Excel、PowerPoint等', '公司成立于2021年，是一家创业型公司。致力于临床前CRO和实验动物服务行业的发展。公司技术优势：手术动物模型及实验动物服务。希望能遇到志同道合的伙伴，在生物医药行业高速发展的现在，一起努力。千崖康药是一家专注于人类疾病动物模型研发、饲养繁育和分析检测的生物科技公司，为医药研发提供临床前药效、药代动力学和安全性评价的技术企业。服务内容包括动物模型、替代性模型构建、药理药效研究、药代动力学研究、安全性评价研究服务等。为更多创新药企业提供专业的、高效率的技术服务。', 'https://www.zhaopin.com/jobdetail/CCL1369987710J40786064703.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4979, '律师', '四川恒和信律师事务所', '2月10日', '6-10万', '成都-武侯区', '咨询服务,法律服务', '500-999人', '不需要融资', 'CC130708500J40448438404', '一、合作优势<br>1.合伙人之间案源合作，共同开发案源；<br>2.免费提供独立办公室或工位；<br>3.免费提供会议室、接待室，不收取任何办公用品费用；<br>4.共享知识成果，为业务拓展提供支持；<br>5.开展各类培训讲座和业务交流，实现律所二级市场，帮助律师提高议价能力及获客能力；<br>6.管理费合理，控制律师执业风险。<br>二、合作条件<br>1.取得律师执业证，在执业期间无任何处罚及不良记录；<br>2.人品端正、诚信、奋进并有集体荣誉感。', '一、恒和信概况四川恒和信律师事务所成立于2001年，总部位于四川成都，执业律师及工作人员近500人，同时具有律师事务所资质、证券法律服务资质、专利代理资质。恒和信获得全国律师行业先进基层党组织、全国优秀律师事务所荣誉称号，多次荣登《亚洲法律杂志》ALB中国法律大奖《钱伯斯》大中华区法律指南等国际性榜单，已成为党建引领、服务专业、人才精英、管理规范的全国知名大型律师事务所。恒和信律师在各个专业领域均具有典型成功案例，多次入选最高人民法院公报案例、四川省高级人民法院典型案例、四川省律师十佳辩护词和十佳代理词。二、恒和信文化恒和信取义于“恒力尚法，和美信达”。恒和信律师始终坚持信仰法律，初心不改，和谐幸福，惟愿所及的理念。其中，恒力表示初心不改，牢记使命；尙法表示信仰法律，尊崇法律，践行法律，维护法律；和美表示促进社会和谐平和，保障家和万事兴；信达表示通达事理，见识高远，惟愿所及。恒和信律师坚持专业、责任、价值、奋进的价值观。崇尚法律秉持着对法律的信仰，全身心投入的使命感对客户负责，保护当事人的利益，保守当事人秘密，尽最大的努力为当事人创造价值。对国家负责：将职业责任与社会责任相结合，助力国家法治建设，密切关注人民的法律权益。价值:继责任之上，创造价值。奋进：以学无止境为核心；以学以致用为中心；以精益求精为决心。三、恒和信荣誉（一）国际性荣誉 2021、2022、2023、2024年，四川恒和信律师事务所连续四年荣登《钱伯斯大中华区法律指南》公司商事领域榜单。2023、2024年四川恒和信律师事务所荣登《钱伯斯大中华区指南2023》破产重组领域榜单。2021、2022、2024年，四川恒和信律师事务所多次入围ALB中国法律大奖年度西部律师事务所。2024年04月，四川恒和信律师事务所荣获“2024 ALB China年度雇主”。（二）国家级荣誉 2021年07月，中共四川恒和信律师事务所支部委员会被全国律师行业党委评为“律师行业先进基层党组织”。 2011年12月，四川恒和信律师事务所被中华全国律师协会授予“全国优秀律师事务所”。（三）省市级荣誉 2023年12月，四川恒和信律师事务所党委“未成年人法治教育童谣绘本项目”获“成都市律师行业第二届党建创新项目”。2023年7月，四川恒和信律师事务所《国家级储备油库重大建设项目专项法律服务》获评“四川省律师行业服务重大项目十佳典型案例”。2023年3月，四川恒和信律师事务所党委党员活动阵地被中共成都市律师行业委员会授予“第一届成都市律师行业示范党员活动阵地”。2022年12月，四川恒和信律师事务所被四川省律师协会授予“四川省青年律师培养示范基地”。2022年06月，中共四川恒和信律师事务所委员会第一党支部获评四川省律师行业“十个标准化”品牌党支部。2020年06月，中共四川恒和信律师事务所支部委员会入选四川省律师行业“党建标准化律师事务所党组织”。2019年06月，中共四川恒和信律师事务所支部委员会被中共四川省律师行业委员会授予四川省律师行业“先进党组织”称号。2019年04月，四川恒和信律师事务所被成都市律师协会授予“2017-2018年度成都市优秀律师事务所”。2018年01月，四川恒和信律师事务所被四川省司法厅、四川省律协授予“四川优秀律师事务所”。2017年11月，四川恒和信律师事务所被中共四川省委统战部、省司法厅、省教育厅、省财政厅、省人力资源和社会保障厅、省国税局、省地税局授予“四川同心·服务团活动先进集体”。2016年06月，中共四川恒和信律师事务所支部委员会被中共成都市律师协会委员会授予“先进基层党组织”。2015年07月，四川恒和信律师事务所被四川省司法厅、四川省律师协会授予“四川省优秀律师事务所”。2014年09月，四川恒和信律师事务所被成都市司法局、成都市律师协会授予“2011年-2014年成都市优秀律师事务所”。2013年12月，四川恒和信律师事务所被四川省律师协会授予“四川省优秀律师事务所”。2013年01月，四川恒和信律师事务所被四川省司法厅、四川省人社厅授予“司法行政系统先进集体”。2012年03月，四川恒和信律师事务所被四川省司法厅授予“四川群众喜爱的优秀律师事务所”。 2011年06月，中共四川恒和信律师事务所支部委员会被中共四川省司法厅委员会授予“先进律协党组织”。 2010年05月，四川恒和信律师事务所被四川省司法厅、四川省律师协会授予“四川省优秀律师事务所”。', 'https://www.zhaopin.com/jobdetail/CC130708500J40448438404.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4980, 'APP推广', '成都歪马科技有限公司', '7月15日', '7000-10000元', '南京-鼓楼区', '电子商务', '1000-9999人', '未融资', 'CCL1492920960J40790073708', '全城可就近安排！！！<br>全职/兼职都招<br>全职：负责门店内商品的陈列摆放，促销推广，本店酒水送达，付出有绝对的回报，招两名靠谱小伙伴亲自带~~详情点我头像咨询~~~<br>月综合7000~10000<br>兼职：白天有工作，晚上有时间可以做兼职，兼职薪资是全职的一半左右，每天上5小时，兼职只送酒<br>工作要求：<br>1、有电动车或提供门店提供租车渠道（可租）<br>2、有无经验均可，新人有师傅带有专人培训<br>3、全国上千家门店，各区都可以就近安排', '歪马送酒是美团旗下的酒水即时零售品牌，经营品类涵盖啤酒、白酒、红酒、洋酒四大品类。通过与酒水品牌直接合作，严控供应链，自建配送体系，给前置仓配货，商家在小程序和外卖平台为用户提供平价、保真、平均15分钟送达的酒水及时送服务。歪马送酒在2021年6月23日广东惠州开展单城探索，启动1个城市中心仓+N个前置仓，40天开仓8家，覆盖惠州主要城区。截止2024年7月，歪马送酒在广东地区（深圳、广州、东莞、佛山、惠州、汕头、江门、中山、河源），江苏地区（南京、苏州）、浙江地区（杭州、宁波、温州）北京、上海、杭州、成都、西安、重庆、武汉、福州等22个城市建有直营门店，门店数量超过家。2025年还会入驻青岛、南宁、郑州、合肥、贵阳等城市，预计实现全国省会城市、一线城市全覆盖，门店数量超1000+。', 'https://www.zhaopin.com/jobdetail/CCL1492920960J40790073708.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4981, '销售助理', '长春海谱润斯科技股份有限公司', '7月15日', '4000-5000元', '长春-宽城区', '化学原料/化学制品,化学原料/化学制品', '100-299人', 'B轮', 'CC286607230J40861707915', '工作内容：  1、订单全流程统筹：负责接受客户订单需求，统筹制定包装排期计划与执行方案；', '长春海谱润斯科技股份有限公司成立于2015年，位于长春新区，是一家致力于有机电致发光材料(OLED材料)的技术研发、生产、销售及技术服务的高新技术企业。产品包括空穴功能层材料、电子功能层材料、光提取功能层材料、电极功能层材料等OLED发光材料。目前已授权发明专利201项，在审发明专利200余项。产品均来自自主知识产权转化，产品已在不同时段对国外材料进行了国产化替代，并广泛应用于华为、苹果、VIVO、OPPO等手机及穿戴产品。合作客户包括京东方集团、天马集团以及和辉光电、华星光电等国内知名面板企业，并与其建立了长期稳定的合作关系。公司是最早给国内量产柔性六代线供货、也是第一家进入华为、苹果生产线的国产OLED材料供应商。截止2024年累计营收18亿元。自成立以来，先后获得国家重点“小巨人”、国家级专精特新“小巨人”、第八届中国创新创业大赛二等奖、国家高新技术企业、国家知识产权优势企业、省级科技型小巨人企业等二十余项荣誉称号。', 'https://www.zhaopin.com/jobdetail/CC286607230J40861707915.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4982, '储备干部', '深圳市乐有家控股集团有限公司', '6月13日', '9000-14000元', '深圳-龙岗区', '房地产中介,房地产中介,咨询服务', '10000人以上', '未融资', 'CC381381910J40564116705', '我们是最不像销售的销售团队！！！<br>为什么我们最不像销售，一共4个特点，也是求职者最关注的4个点<br>特点一：薪酬，我们的收入是82分布，老销售是28分布。80%入职一年以上的人月收入在2万以上；入职的大学应届生，高底薪，本科月均到手7935元，大专月均到手6884元！<br>特点二：环境氛围，我们团队氛围已经完成职场整顿！我们是完成了职场整顿的新营销团队，平时销售团队吃吃喝喝在所难免，而我们这边不用阿谀奉承，不用溜须拍马，不用喝酒应酬，一共有三不用，同时我们还有三反对，反对官僚主义，反对形式主义，反对职场PUA。<br>特点三：能力/实力上，我们的市占率和人均收入同步遥遥领先<br>特点四：发展空间，可以实现零成本内部创业<br>【薪酬待遇】<br>经纪人收入自主制，薪酬福利包括底薪、各项补贴和奖金，超高业绩奖核算比例55%-80%：<br>本科薪酬9000元（底薪5000+行动量化绩效1000+职务绩效3000）<br>大专薪酬8000元（底薪4000+行动量化绩效1000+职务绩效3000）<br>高中薪酬7000元（底薪3000+行动量化绩效1000+职务绩效3000）<br>更多员工福利：五险一金、节日关怀礼、年假、婚假、产假等。<br>【工作的具体内容】<br>1、通过小红书、抖音、安居客、乐有家网等渠道，开发和维护房源/客源；<br>2、熟练掌握区域楼盘详细情况，实地勘察物业状况，确认权属，对物业进行专业评估，签订业务委托书，收取钥匙；<br>3、接待客户，提供业务咨询，带客看房、跟进磋商、谈判签约、跟进售后处理；<br>【优质福利等着你】<br>1.基本福利----五险一金、提供住宿<br>2.有薪休假----年休假、产假、婚假、丧假等有薪休假；<br>3.其他福利----团体娱乐健身活动、过节礼品、生日庆贺等福利<br>【工作地点】<br>全国150个城市，总部在深圳，投递简历给你安排', '乐有家控股集团为“以房地产经纪为龙头、金融和互联网为两翼”的大型企业集团，成立于2008年，总部位于深圳市，以“立足大深圳、密布珠三角、服务全中国”为发展战略，在深圳二手房市场占有率稳居行业第一，粤港澳大湾区多个城市市占率稳居行业前列。集团旗下拥有“乐有家”、“顺联担保”、“万顺通资产”、“家家顺物联科技”等优秀品牌，业务涵盖二手房买卖、房屋租赁、项目策划、新房代理、人工智能、资产管理、金融服务等领域，获得“中国十大品牌中介机构”、“全国优秀房地产经纪机构”、“年度最佳雇主”、“最值得信任的地产经纪品牌”、“广东省诚信企业”、“最具影响力雇主”等殊荣。集团始终坚持“真诚正义，先人后己”的核心价值观，积极推行“真服务、真保障”服务战略，为客户提供及时精准、专业可信、高效超值的房产交易全价值链服务。通过运用互联网、人工智能等新技术，打造线上线下一体化的E2E智能生态系统，致力于为客户打造房产交易全过程、全网络、全家庭生命周期的极致服务体验。集团以“立足大深圳、密布珠三角、连锁全中国”为发展战略，有效整合全国各项资源，实现“有家的地方就有乐有家”的宏伟愿景！', 'https://www.zhaopin.com/jobdetail/CC381381910J40564116705.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4983, '统计员', '石家庄萌祺电子科技有限公司', '7月2日', '5000-8000元', '石家庄-桥西区', '互联网,电子商务,计算机软件,IT服务', '20-99人', '未融资', 'CCL1484270300J40772987214', '毕业生看过来！无需经验，我们带你从职场小白变身全能达人！ 来者不拒，拒绝销售，拒绝内卷，公司氛围轻松愉快~', '石家庄萌祺电子科技致力于互联网行业的深耕与发展，已经具备了成熟的技术与团队，完整的公司体系，在市场中有很大的竞争优势，在石家庄各区都有团队，具备了相当的规模。道具商城公司从老板到员工都是由95后与00后组成，整体氛围轻松愉快，具备良好的工作氛围。公司注重人才培养，人才扶持，以人为本，欢迎各大英才的加入哦~', 'https://www.zhaopin.com/jobdetail/CCL1484270300J40772987214.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4984, '猎头顾问', '河南壹众律师事务所', '7月17日', '1-1.5万', '郑州-金水区', '法律服务', '100-299人', '未融资', 'CCL1416970240J40765811910', '牛人请注意<br>1：岗位介绍都是真实有效的<br>2：专业知识带薪培训（接受无经验，但必须要踏实，有业务经验是加分项）<br>3：本工作可以学习法律知识、交通事故方向专业知识、接触法律方面的同事及律师，是一个长期发展的好平台。<br>工作内容：<br>1：律所根据个人情况，分配所属区域的业务范围，开展工作。<br>2：负责追踪，洽谈客户，签订合同协议。<br>3：沟通，整理材料，协助律师处理案件完成工作。<br>4：晋升空间较大，律所会根据个人工作的能力晋升职位，薪资高。<br>5：晋升渠道：见习—正式—高级—储备主管—主管—经理—分部总经理<br>岗位要求：<br>1：长期稳定！（短期勿扰）<br>2：沟通能力强、抗压能力强、有挣钱欲望<br>3: 学习能力强，大专及以上学历（有能力者学历可根据情况放宽）<br>4：有空杯心态、态度真诚、有正义感、有正能量、对法律行业感兴趣<br>5：有团队合作精神与集体荣誉感！<br>一，薪酬：<br>无责任底薪+提成+月度奖金+补贴+团队激励+年终奖，稳定员工1w+<br>二，培训福利<br>员工可享受免费专业人员的入职培训、业务培训、进阶培训、管理培训，一切教会为止。<br>三，保险福利（五险一金）<br>四：福利待遇优厚：各种节假日正常休、慰问福利，组织团建旅游等各项福利政策', '壹众律所专业、稳健、与时俱进！壹心为您，依法为众!河南壹众律师事务所全体工作人员期待与您合作。①河南壹众律师事务所是经河南省司法厅批准成立的律师执业机构，律所执业证号为31410000MD02582016。律所现办公地点位于郑州市CBD核心商务区楼、地理位置优越。律所现办公面积1000余平方米，并配备有多媒体会议室、独立接待室、律师活动中心、展览区等设备设施，办公条件优越。②本所现有资深执业律师、实习律师及行政管理人员共计90余人，大部分律师毕业于中国知名院校法学院，具备丰富的法律从业经验，其中获得硕士、博士学位的高学历优秀人才10余人；另拥有注册会计师、资产评估师资格的多样化人才数人。③本所始终坚持“专业、崇德、协同、共进”的经营理念，积极响应客户法律服务需求，在专业领域为客户提供优质高效的法律解决方案，力求用服务为客户创造更大价值。④本所实行团队化的工作方式，建立了标准化的业务程序。律所内部各部门间合作有序，精于效率，力求将法律问题的解决落实于生活实际，以最优质的处理方案让客户的法律问题得到最高效的解决。⑤壹众律所始终坚持与时代同步，在前进中不断更新理论知识，及时跟踪最新立法、司法动向。对于新的法律、法规及司法解释，律所都会及时组织全所律师学习研究，深入理解司法判例及司法解释的法理和政策基础。⑥壹众律所精英律师汇集，在各专业领域取得了优异的成绩，赢得了良好的口碑，获得了广大客户的认可与信任。我们本着广交朋友、服务社会的决心，认真履行社会责任，并与社会各界相关机构建立了良好的合作关系，力求共同进步、同谋发展。', 'https://www.zhaopin.com/jobdetail/CCL1416970240J40765811910.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4985, '网络客服', '长沙市愿达信息科技有限公司', '7月25日', '5000-8000元', '长沙-望城区', '电子商务', '20-99人', NULL, 'CCL1367432820J40821365808', '【工作内容】<br>负责回复线上客户咨询信息,售前售后为客户解答疑问、促成交易。不用外出也不用打电话，无销售，无业绩考核，办公室办公。<br>实行三班制，八小时工作制，早、中、晚班轮班制。<br>【任职资格】<br>1、能熟练打字,与客户进行良好沟通,有清晰逻辑思维，语言沟通能力强<br>2、性格活泼开朗,待人和善,脾气好。工作认真细致，能承受一定的工作压力。<br>3、具有优秀的团队合作精神，优秀的客户服务意识，有责任感<br>【福利待遇】<br>1、4500无责底薪＋全勤奖金+夜班补贴+提成＋每周下午茶。公司提供餐补。<br>2、购买五险一金，每月任意休息4天<br>3、提供公平、公开、公正的晋升平台。晋升制度：<br>电商客服一客服主管一运营主管一公司经理<br>4、重大节假日福利+年终奖+优秀员工奖励', '【工作内容】负责回复线上客户咨询信息,售前售后为客户解答疑问、促成交易。不用外出也不用打电话，无销售，无业绩考核，办公室办公。实行三班制，八小时工作制，早、中、晚班轮班制。【任职资格】1、能熟练打字,与客户进行良好沟通,有清晰逻辑思维，语言沟通能力强2、性格活泼开朗,待人和善,脾气好。工作认真细致，能承受一定的工作压力。3、具有优秀的团队合作精神，优秀的客户服务意识，有责任感【福利待遇】1、4500无责底薪＋全勤奖金+夜班补贴+提成＋每周下午茶。公司提供餐补。2、购买五险一金，每月任意休息4天3、提供公平、公开、公正的晋升平台。晋升制度：电商客服一客服主管一运营主管一公司经理4、重大节假日福利+年终奖+优秀员工奖励', 'https://www.zhaopin.com/jobdetail/CCL1367432820J40821365808.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4986, '项目经理/主管', '河北云启科创企业服务有限公司', '7月18日', '6000-10000元', '北京-昌平区', '人力资源服务', '20-99人', NULL, 'CCL1484110930J40779257614', '岗位职责：​​<br>项目全流程管理：负责人力资源服务项目的整体规划、执行与交付，确保项目按时保质完成<br>客户关系维护：对接客户需求，协调内外部资源，提升客户满意度，建立长期合作关系<br>风险管控：识别项目潜在风险，制定预防及应对措施，降低业务运营风险；<br>仲裁案件处理：协助处理劳动仲裁、合同纠纷等法律事务，协调法务团队推进案件解决<br>团队协作：与招聘、培训、薪酬等部门协同，优化项目流程，提升服务效率。<br> <br>任职要求：本科及以上学历，人力资源行业项目管理经验，熟悉劳动法规及仲裁流程优先；<br> <br>薪资范围：6K-8K（根据经验能力面议）+项目奖金<br>​<br>工作时间：周一至周五 9:00-18:00，周末双休​<br> <br>福利待遇：入职即缴纳五险一金，带薪年假，节日福利，定期团建​​<br> <br>工作地点：昌平区珠江摩尔国际大厦', NULL, 'https://www.zhaopin.com/jobdetail/CCL1484110930J40779257614.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4987, '档案管理', '英才无忧(山东)网络科技有限公司', '7月23日', '7000-8000元', '北京-朝阳区', '人力资源服务', '20-99人', NULL, 'CCL1504310520J40697442506', '工作内容:<br>主要就是负责公司日常事务的处理和协调<br>包括文件归档，整理材料，会议安排<br>年龄24~45<br>周末双休，早九晚六，法定正常休息<br>带薪年假，节日礼品都有<br>岗位要求:<br>大专及以上<br>细心，耐心，责任心强', NULL, 'https://www.zhaopin.com/jobdetail/CCL1504310520J40697442506.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4988, '运营助理/专员', '万星在线科技', '4月21日', '5000-6000元', '郑州-二七区', '培训/辅导服务,在线教育', '100-299人', '未融资', 'CCL1492002630J40730052302', '1、调研用户需求，运营培训课程产品 2、整合资源，跨部门项目的沟通合作推进', '万星在线科技（天津）有限公司2015年成立，隶属于北京万星在线科技有限公司，公司坐落于空港经济区金融中心。专注于K12领域的教育、教研产品，目前已有10多款产品投入市场。我们以专业的教研、开发水准赢得了行业内的高度认可，产品覆盖全国。拥有强大的研发及教研团队。我公司是教材研发、软件研发中心，为全国几千家机构提供英语教材、教学软件、教研输出、教师培训的服务。有完整的软件研发、教材研发及销售团队，有固定的客户群体，在业内口碑佳。公司经营稳定，稳步扩张，希望优秀的你加入我们，在这个平台尽情施展~~~', 'https://www.zhaopin.com/jobdetail/CCL1492002630J40730052302.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4989, '储备干部', '福州鼓楼区夏宁商务服务有限公司', '4月17日', '9000-15000元', '福州-鼓楼区', '互联网金融/小额贷款', '20-99人', NULL, 'CCL1500423320J40740477407', '岗位职责：  1.通过电话销售方式获客，为客户提供金融咨询服务；', NULL, 'https://www.zhaopin.com/jobdetail/CCL1500423320J40740477407.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4990, '档案管理', '济宁红火蚁信息科技有限公司', '2025-07-27 01:17:33', '5000-8000元', '济宁-任城区', '文化艺术/娱乐', '20-99人', NULL, 'CC833318180J40698167406', '工作内容：<br>1、负责通过线上短视频渠道收集意向客户资料<br>2、确保客户资料的准确性和完整性，便于查询和使用；<br>3、维护客户的关系。<br>岗位要求：<br>1、具备聊天沟通知识和技能（非打电话）；<br>2、能够独立完成客户档案任务；<br>3、注重细节，有良好的组织和分类能力。', NULL, 'https://www.zhaopin.com/jobdetail/CC833318180J40698167406.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4991, '管培生/储备干部', '福建省一苇投资咨询有限公司', '7月28日', '4000-5000元', '泉州-丰泽区', '新媒体', '20-99人', NULL, 'CCL1449878430J40689789806', '哈喽，同学你好！我们正在招募金融管培生，这不是传统的‘岗位招聘’，而是为未来 2-3年储备核心人才的‘加速培养计划’。如果你是金融、经济、数学等专业，有扎实的专业基础，更有‘想在金融行业快速成长’的野心，这个机会绝对适合你 —— 毕竟，不是每个管培生都能一毕业就站在行业资源的中心。”<br>以下就是对于这份岗位的要求说明，欢迎你投递简历，期待你的加入！<br>岗位要求：1、统招本科（含）以上学历，年龄20-26岁之间，经管、数学系、统计学系专业应届毕业生优先；2、证券从业、基金从业、银行从业等有考过经管类相关的考试合格成绩等可放宽条件。3、对金融经济知识，金融市场、A股等有浓厚的兴趣，并且有实践过；4、具有良好的学习能力与团队精神，果断、自信、接受新鲜事物能力强；5、人品端正，具有良好的职业操守，有强烈的责任感，敢于面对挑战，可承受较大心理压力<br>福利待遇：1、享有节假日正常放假+员工拓展团建机制+下午茶等；2、薪资架构：无责底薪+五险一金<br>3、上班时间：8:25-11:50、13:25-18:00 周末双休 ；4、岗前系统化培训课程、二级市场等技能，理论、实战结合~带薪培训 新人座谈会、分享会等 5、公司工作环境优美、氛围好、同事关系融洽、无办公室政治<br>“今天的介绍就到这里。无论你是否选择我们，都希望你能找到真正匹配自己职业野心的平台 —— 毕竟，好的工作不是‘将就’，而是‘彼此成就’。<br>如果你对管培生计划还有细节疑问，可投递简历联系HR，HR会为你解答，期待在面试环节看到你的‘独特性’—— 毕竟，我们找的不是‘符合标准的人’，而是‘能打破标准的潜力者’。祝各位前程似锦，我们面试见！”', NULL, 'https://www.zhaopin.com/jobdetail/CCL1449878430J40689789806.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4992, '知识产权/专利代理', '北京柏杉松知识产权代理事务所(普通合伙)', '9月2日', '2-3.5万', '西安-雁塔区', '专利/商标/知识产权,专利/商标/知识产权,法律服务,专业技术服务', '100-299人', '未融资', 'CC519504120J40212031716', '岗位职责：<br>1、翻译、校对涉外专利申请文件；<br>2、处理涉外案件审查意见；<br>3、处理复审、无效、专利诉讼案件；<br>4、专利分析、专利检索、专利预警等工作。<br>任职要求：<br>1、国家正规院校化学化工或生物类专业、硕士及以上学历；<br>2、英语CET-6级及以上，英语能作为工作语言；<br>3、有良好的沟通能力和团队合作精神；<br>4、具有两年以上研发经历或知识产权相关工作经验者优先；<br>5、具有专利代理师资格证或执业证者优先。<br>职位福利：五险一金、加班补助、餐补、交通补助、带薪年假、员工旅游、定期体检、节日福利<br>', '北京柏杉松知识产权代理事务所（普通合伙）（机构代码11413）成立于2012年，总部设在北京，并在合肥、西安、大连、天津、福州设有分所，现有员工230余人，目前是北京市十大领军机构之一、5A级专利代理机构、北京民营企业文化产业百强、IAM全球TOP1000专利事务所，已经发展为国内外知名事务所。柏杉松在欧美日韩等主要知识产权国家建立了全球知识产权合作网络，致力于为客户提供专业的一站式国内外知识产权服务，目前服务的客户多为各领域一流企业。同时，事务所拥有完善的培训机制和晋升机制，为全体员工提供良好的发展平台和优厚的薪酬待遇。欢迎有志于知识产权事业的优秀人才加入柏杉松。', 'https://www.zhaopin.com/jobdetail/CC519504120J40212031716.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4993, '项目专员/助理', '铁骑力士食品有限责任公司', '7月26日', '5000-8000元', '绵阳-涪城区', '农/林/牧/渔,食品/饮料', '10000人以上', '未融资', 'CCL1312731970J40631978111', '岗位内容：<br>1. 协助项目经理完成项目计划和进度安排，跟踪项目执行情况并进行记录；<br>2. 收集、整理和分析项目相关数据，汇总报告并撰写总结分析；<br>3. 参与编制项目立项申请、招投标文件及合同等文档；<br>4. 协助组织项目会议、培训与沟通等工作；<br>5. 监督项目现场施工的进展和质量，并及时协调解决问题。<br>任职要求：<br>1. 具有较好的团队协作能力和沟通能力，能够积极主动解决问题；<br>2. 熟练掌握办公自动化软件，具备较强的数据分析和撰写技能；<br>3. 具备一定的项目管理知识和方法论基础，熟悉项目管理流程和工具；<br>4. 有较强的责任心和抗压能力，能够承受项目压力和工作压力；<br>5. 有相关行业从业背景或相关项目工作经验者优先考虑。', '铁骑力士集团生猪产业集育种、繁育、养殖、屠宰、加工到品牌销售为一体。在全国建有30余个现代化生猪繁育养殖基地，年可提供优质商品仔猪300万头；是农业部首批国家生猪核心育种场，国家现代生猪产业技术体系综合试验站单位，中国动物疫病净化创建场，拥有60余年丰富的育种管理经验，种猪连续多年获得四川省种猪性能测定中心第一，先后从美国、加拿大引进优质种源，并与加拿大加裕公司达成战略合作，实现育种技术和国际同步。公司具备雄厚的技术研发实力。依托国家级企业技术中心冯光德实验室，先后参与完成了218项科研项目,荣获“国家科技进步二等奖”、“全国优秀养猪企业”、“全国养猪行业百强企业”等荣誉称号，拥有“天府肉猪、川藏黑猪”两大生猪配套系新品种，被称为川猪振兴的两大芯片，并牵头制定“天府肉猪”农业行业标准。近年来，公司不断加速产业战略布局。在四川凉山、黑龙江、江油等地快速布局，大力发展。其中“三台县百万健康猪业智慧农业示范园区”项目为全产业链和一二三产业深度融合发展的智慧农业园区,为国家现代农业标杆。现铁骑力士种猪、生猪销售遍布全国，未来3-5年，将实现出栏生猪1000万头，持续发挥生猪全产业链优势，打造优质种猪、品牌肉猪及千万头生猪产业规模，实现种猪、川藏黑猪运营中国第一，成为生猪全产业链品牌化经营引领者！', 'https://www.zhaopin.com/jobdetail/CCL1312731970J40631978111.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4994, '法务专员/助理', '深圳市聚睿信息科技有限公司', '7月28日', '4000-6000元', '重庆-渝北区', '互联网金融/小额贷款', '500-999人', NULL, 'CCL1443760520J40701554616', '岗位描述：<br>1、通过已生效的法律文书整理好在线上向各地中院申请执行<br>2、对发生逾期的债务人通过电话在案件全流程进行触达调解<br>3、整理文书材料进行邮寄<br>4、电话或微信沟通法院立案进展<br>5、特定对公客户（公检法机构）的运营，客情维护<br>6、执行案件相关法律文书起草<br>7、电话或微信沟通法院立案进展<br>8、跟进法院了解执行情况<br>岗位要求：<br>1、大专学历以上，有金融纠纷法务、法院工作、调解相关经历等从业经验者优先且可放宽学历要求；有法院执行局工作经验、批量案件处理工作经验、催收调解经验者优先<br>2、有突破精神、良好的沟通能力及敬业精神，工作过程会与法官及债务人电话接触<br>3、无不良从业记录，抗压能力强<br>4、能严格执行工作要求，态度端正<br>5、征信报告无不良逾期记录<br>6、无犯罪记录<br>7、会标准普通话', '聚睿信息主营业务包括联合仲裁委机构、自营调解中心，法院特邀调解中心等组建核心资产运营团队，AI调解平台，基于调解文化为不同的金融提供零售信贷纠纷多元解决方案。始终致力于构建高效、专业的调解平台，为金融行业提供多元化的纠纷解决方案。拥有600人的专业团队，并在全国范围内设立了11家职场，包括深圳总部以及东莞、重庆、江津、银川、中卫、天津、宝鸡、淮南、岳阳等城市，形成了广泛的服务网络。主营业务与核心优势我们的主营业务涵盖联合仲裁委机构、自营调解中心、法院特邀调解中心等核心资产运营，专业的运营团队，打造AI调解平台，为金融机构提供零售信贷纠纷的多元化解决方案。我们基于调解文化，结合互联网服务，积极践行国家关于非诉讼纠纷解决机制的重要指示精神，立志从源头上减少金融纠纷的诉讼增量。在核心优势方面，我们目前建立有自己的多元化金融调解中心，同时有合作的金融调解中心，分别是天津自贸区多元化金融调解中心、宝鸡市渭滨区正信民商事调解中心、毛集试验区聚兴金融调解中心、重庆市渝中区诚渝商事调解中心、岳阳市君山区华律金融商事纠纷调解中心等，这些调解中心在行业内具有广泛的影响力。同时，我们还拥有独立的律所——权晔律所，该律所拥有专业的律师团队和合法的执业牌照，为我们的调解工作提供了坚实的法律支持。行业背景与发展趋势随着金融科技的飞速发展和金融产品的不断创新，金融纠纷的复杂性和多样性日益增加。调解作为一种灵活、高效的解决方式，逐渐成为未来市场的首选。近年来，国家出台了一系列政策文件，鼓励金融机构和消费者通过调解方式解决纠纷。随着金融市场的不断规范和完善，调解机制已成为解决金融纠纷的重要手段。同时，调解手段也在不断创新，如在线调解、智能调解等，这些新型调解方式推动了金融调解行业的快速发展。通过提高信贷金融案件的合法权益保护水平，防范化解金融风险，仲裁调解、金融调解司法解决方案等得到了广泛应用。这些措施不仅提高了资金利用率，还减少了信贷不良带来的过多负担，促进了信贷业务的可持续发展。人才与文化随着调解文化的普及和发展，具备调解能力和调解思维的人才将更加受到市场的青睐。我们公司作为首批实力持牌调解中心，致力于打造一支具备专业素养和调解技能的优秀团队。我们期待有志之士加入我们，共同为推动金融调解事业的发展贡献力量。在这里，您将有机会与行业内顶尖的专业团队合作，共同面对金融纠纷调解的挑战与机遇。我们提供完善的培训体系、广阔的发展空间以及具有竞争力的薪酬福利，期待您的加入！', 'https://www.zhaopin.com/jobdetail/CCL1443760520J40701554616.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4995, '培训师', '石家庄冀中医学中等专业学校', '7月23日', '4000-5000元', '石家庄-鹿泉区', '学校/学历教育', '100-299人', '不需要融资', 'CC709950720J40768180814', '专科及以上学历，相关专业毕业；<br>有相关专业教学工作经验或临床工作经验者优先录用。<br>热爱教育事业，身体健康，能够胜任本学科理论教学和技能实训指导工作', '石家庄冀中医学中等专业学校是经河北省教育厅卫生厅。民政厅批准成立的一所全日制医学类中等专业学校开设护理，中医康复保健、口腔、药剂、中药、医学检验医学影像，眼视光与配镜等热门专业、同时举办342大专班和对口升学班。自建校以来，学校始终乘承“厚德载医，明辨笃行”校训，强化基础知识和基本技能的训练与培养突出医学专业特色，以“管理严格，教学质量一流，专业性强，就业率高”的办学特色享誉社会，办学30多年来为社会输送了大量口腔、护理等优秀人才，受到家长、用人单位和社会各界的广泛好评，学校先后被评为“国内重点口腔人才教育基地”、“河北省重点中等职业学校”“全国百余家解放军武警医院护士培养基地”“河北省中医药管理局指定中医药人才教育中学校位于河北省省会石家庄市后花园-鹿泉区，南邻植物园、千年古刹毗户寺、西依大行山，东临石津运河，占地有窗，建筑面税3万多平方米，学校拥有独立的教学楼。实训楼宿舍楼。图书馆、电教室、多功能厅、运动场、餐厅、医务室、浴池、超市等教学，文体、生活设施，校园安静、环境优美，是革萃学子修业进学的理想园地。', 'https://www.zhaopin.com/jobdetail/CC709950720J40768180814.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4996, 'BD经理', '位来小猎(宁波)信息技术有限公司', '7月11日', '8000-13000元', '广州-海珠区', '计算机软件,专业技术服务', '100-299人', 'A轮', 'CCL1320375780J40772845507', '福利:六险一金+早十晚七工作+周末法定正常休息+高薪补贴+快速晋升<br>岗位优势:<br>1.抖音正式编制岗位(工作长期稳定、福利待遇好);<br>2.抖音商家团购板块，全品类类目都可做，目前不饱和度高且商家对抖音认可度高，好做(其他团购平台依然可以免费入驻);<br>3.长期存量商家，越久薪资越高;<br>4.六险正常底薪基数+公积金最高比例缴纳;<br>5.1-2周培训，第一天开始就正常发放薪资。<br>岗位职责:<br>1.对于本地商家全品类BD邀请入驻:<br>2.已邀请商家运营工作(帮助推广、安排引流等)。<br>任职资格<br>1.学信网可查本科及以上，有相关销售经验优先<br>2.具备较强的销售能力、客情维护能力、谈判能力、问题解决能力;<br>薪资待遇：<br>底薪+320餐补+500交通补贴+提成 入职六险一金<br>工作时间：<br>早10 晚7 周末双休 法定休息 城市就近分配', '位来小猎成立于2018年1月，2019年6月完成A轮融资；聚焦行业精华，利用后发优势，在1年以内成为行业黑马公司。核心团队成员均有十年以上的人力资源经验，具备丰富的人力资源专业知识和项目实践，服务众多500强企业和知名互联网公司。位来小猎掌握专业领域核心资源，团队迅速扩张，以北京为中心，在全国建立了10家分公司及办事处，业务覆盖全国。现有300+名员工，派遣、外包员工10000+名；服务客户包括国家体育总局，百度，网易，物美多点，美团，字节跳动，喜马拉雅，作业帮，得物，VIPKID，瓜子，京东，拼多多，喜茶，中国人保等。位来小猎以互联网为载体，依托于位来小猎平台、微信公众号、入职有赏微信小程序上活跃的海量求职者资源，核心业务包括人才外包、专业招聘、业务外包、转编服务和灵活用工等。服务行业涉及全国各领域，其中包括社交电商，旅游酒店，互联网（教育），新零售，金融和国家单位等。位来小猎以“把求职者的未来当做自己的未来”为核心价值，希望通过我们专业的服务和不懈的努力，帮助求职者找到更合适、更有发展前景的工作，破冰职场迷茫，为未来指引方向。一直以来，位来小猎秉承以专业诚信为核心，在专注人力资源服务的同时，为众多求职者解决就业问题，优质、用心的服务赢得了众多用户的好评与信赖。除此之外，公司还建立了完善的服务体系，为求职者在工作中遇到的所有问题和困难提供指导帮助。我们相信，通过我们的不断努力和追求，一定能够创造我们和求职者更好的未来！', 'https://www.zhaopin.com/jobdetail/CCL1320375780J40772845507.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4997, '律师助理', '河南审鉴律师事务所', '7月25日', '3000-6000元', '郑州-管城回族区', '法律服务,法律服务,咨询服务', '20人以下', '不需要融资', 'CCL1486833210J40673605001', '我们正在寻找一批具有梦想、热情、才华横溢的朋友加入我们的团队，共同创造更加美好的未来，如果你满腹理想，缺少一个施展的平台，这里或许是个不错的选择。<br> <br>律所简介<br> <br>河南审鉴律师事务所是经河南省司法厅批准成立的综合性律师事务所，“审思明辨、鉴往知来”是律所名称由来，“审思明辨守正义、鉴往知来踏征程”是律所不变的追求，现因发展需要，诚邀你的参与，拟打造“人和”型律所，打造成内部团结，对外专业的律师团队。<br> <br>审鉴所位于在管城区航海东路491号院（紫荆山路航海路交叉口）108号商铺1-2层，门前停车方便，向东150米是南五里堡地铁站（2号线和5号线换乘站），新郑机场、郑州东站、郑州航空港站可地铁直达，门前为航海路紫荆山路公交站，亦有多条公交线路，交通便利。<br> <br>招聘岗位：【律师助理（案源方向）】<br> <br>岗位要求<br> <br>1、大专以上学历，专业不限；<br> <br>2、形象良好，普通话标准；<br> <br>3、思维敏捷，具有一定的语言组织能力和沟通、协调能力；<br> <br>4、工作积极热情，认真负责，具备良好的心理素质；<br> <br>5、学习能力、执行能力强，具有团队合作精神和强烈的上进心；<br> <br>6、能较好的操作办公自动化软件。有工作经验者优先。<br>', '河南审鉴律师事务所简介河南审鉴律师事务所秉承“审思明辨，鉴往知来”的理念，致力于为客户提供专业、高效、全面的法律服务。我们以严谨的态度、专业的素养和丰富的经验，帮助客户在复杂的法律环境中维护自身权益，实现合法目标。一、律所概况河南审鉴律师事务所成立于河南省郑州市，是一家综合性律师事务所。律所依托深厚的法律专业知识和丰富的实践经验，专注于为客户提供高质量的法律服务，涵盖诉讼与非诉业务，服务领域广泛。二、核心业务领域1.民商事诉讼与仲裁代理合同纠纷、公司股权纠纷、债权债务纠纷等民商事案件，为客户提供专业的诉讼与仲裁服务。2.刑事辩护为犯罪嫌疑人或被告人提供刑事辩护，保障当事人的合法权益，确保司法公正。3.公司法律事务为企业提供常年法律顾问服务，包括合同审查、公司治理、劳动法咨询、股权设计等，助力企业合规经营。4.知识产权提供商标、专利、著作权等知识产权的申请、保护及维权服务，帮助客户维护创新成果。5.房地产与建筑工程处理房地产开发、建筑工程合同纠纷、土地使用权争议等法律事务，为客户提供专业的法律支持。6.婚姻家庭与继承代理婚姻家庭纠纷、遗产继承等案件，为客户提供人性化、专业化的法律服务。7.行政诉讼代理政府机关、企事业单位及个人处理行政诉讼案件，维护客户的合法权益。三、专业团队河南审鉴律师事务所拥有一支经验丰富、专业素质过硬的律师团队。团队成员均毕业于国内外知名法学院校，具备扎实的法律理论基础和丰富的实践经验。我们注重团队协作，确保每个案件都能得到全面、细致的处理。四、服务理念专业：以扎实的法律知识和丰富的实践经验为基础，为客户提供专业的法律服务。诚信：秉持诚实守信的原则，与客户建立长期信任关系。高效：注重效率，确保客户的需求得到及时响应和解决。责任：以客户利益为中心，全力以赴维护客户的合法权益。五、社会责任河南审鉴律师事务所不仅专注于业务发展，还积极履行社会责任，参与法律援助、普法宣传等公益活动，致力于推动法治社会的建设。六、联系我们地址：河南省郑州市管城回族区航海东路491号附108号电话：13298351505邮箱：hnsjlsyx@163.com七、未来展望河南审鉴律师事务所将继续秉持“审思明辨，鉴往知来”的理念，不断提升服务质量，拓展业务领域，力争成为河南省乃至全国范围内具有影响力的律师事务所，为客户提供更加优质的法律服务。', 'https://www.zhaopin.com/jobdetail/CCL1486833210J40673605001.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4998, '咨询顾问', '天津松山环保科技有限公司', '6月10日', '5000-8000元', '天津-滨海新区', '环保', '20-99人', '未融资', 'CC513708980J40772370712', '1.协助主管领导对接工业企业领域的环境咨询项目工作； <br>2.协助主管领导完成负责项目实施和报告的编制；<br>3.协助主管领导开展项目推进工作，做好与客户沟通，收集编制报告所需基础资料； <br>4.协助主管领导负责与项目相关方的技术沟通、协调工作、技术实施， 能够与政府环保主管部门及评审专家讨论沟通和协调问题；<br>5.项目完成后相关资料收集、整理、及时归档。<br>任职要求：<br>1.环境科学与工程、资源循环科学与工程、生态学、地下水科学与工程、土壤学、资源环境与地理信息系统等相关专业<br>2.很强的全局意识和团队合作意识<br>3.较强的抗压、承受能力<br>4.会开车，责任心强<br>5.党员、学生会干部优先', '天津松山环保科技有限公司是国家级高新技术企业、天津市“专精特新”中小企业，专注于为工业企业提供环保政策合规咨询、有机废气全产业链服务、节能降碳改造及绿色投资一体化解决方案，并提供综合能源管理、环保管家以及企业级数据全生命周期治理与服务，多角度提升企业能源效率，解决环保管理难题，助力企业实现环保管理智能化。公司拥有建筑总承包三级、环保二级、机电安装二级资质，业务覆盖全国，服务行业包括石油化工、汽车制造、制药、纺织等，是您身边绿色低碳转型、降本增效与可持续发展的战略合作伙伴。', 'https://www.zhaopin.com/jobdetail/CC513708980J40772370712.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (4999, '猎头顾问', '天津尘时科技有限责任公司', '6月11日', '5000-10000元', '天津-和平区', 'IT服务,咨询服务', '500-999人', '未融资', 'CCL1252029180J40787530513', '【岗位职责】 1、根据要求制定目标寻访公司并制定目标候选人寻访方案； 2、实施电话寻访，对候选人做出初步评价和筛选； 3、沟通协调面试安排，跟进面试的进展和反馈及后续谈薪、offer发放、入离职办理等节点； 4、完成leader的事务性工作安排。 【职位要求】 1、24/25届统招本科以上学历； 2、自驱力、执行力强。', '始建于2003年，是一家全国领先的人力资源咨询集团。时值中国改革开放25年，两位创始人作为第一批外资企业的中方高级管理人员，带着外资企业十几年的人力资源管理经验创立了公司，致力于用自己的知识和经验帮助更多的企业，获得高效而务实的人力资源解决方案。', 'https://www.zhaopin.com/jobdetail/CCL1252029180J40787530513.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5000, '运营助理/专员', '北京同仁堂健康药业股份有限公司', '6月17日', '6000-7000元', '济南-历下区', '医药制造,零售/批发,快速消费品,食品/饮料', '1000-9999人', '未融资', 'CC120885640J40785809305', NULL, '北京同仁堂始创于1669年（清康熙八年），1723年（雍正元年）开始供奉御药，历经八朝188年。历代同仁堂人始终恪守“炮制虽繁必不敢省人工，品味虽贵必不敢减物力”的古训，打造了中国中医药史上的金字招牌。如今，北京同仁堂已经发展成为一家集现代制药工业、零售医药商业和医疗服务为一体的现代化综合健康产业集团，产品行销至40多个国家和地区。同仁堂健康药业集团（以下简称同仁堂健康）成立于1992年，是同仁堂集团的六大二级子集团之一，属于同仁堂集团大健康产业的业务板块。主营健康食品、保健食品、药品及健康服务，是一家集研发、生产、物流、销售为一体，聚中华养生文化与现代高科技于一身的现代化企业。作为一家大型国有控股的中外合资企业，同仁堂健康在全国近1600家门店，覆盖全国30个省份，240多个城市，员工1万余人。公司以“集百草而香天下，普健康而惠众生”为愿景，以“让世界更健康，为人们提供最优质的健康产品和服务”为使命，将传统与现代先进技术进行创新性结合，率先引入数字管理系统。集团在新的发展战略中明确指出：“建立以人才科技为支撑的智能管理体系，打造智慧型同仁堂健康，从以产品为导向的企业向以服务为导向的企业战略转型”。基于打造大健康生态的新业务模式，集团将通过产品、品牌、渠道方面的全力创新，致力于在生命健康领域打造属于同仁堂的下一个百年全新事业。', 'https://www.zhaopin.com/jobdetail/CC120885640J40785809305.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5001, '统计员', '中伦律师事务所', '7月23日', '1-1.5万·13薪', '上海-浦东新区', '咨询服务,互联网', '1000-9999人', '未融资', 'CC000400350J40249657616', '岗位职责：<br> <br>1. 根据合伙人指示，负责合伙人日常工作/行程/会议安排工作；<br>2. 根据合伙人指示，完成对外联系/沟通工作；<br>3. 根据合伙人指示及事务所规定，负责团队内部行政/后勤/事务性工作以及与事务所其他团队的沟通工作；<br>4. 配合合伙人和团队律师完成日常工作（包括立案、归档、账单制作和其他对外文件制作等）；<br>5. 合伙人安排的其他工作。<br> <br>岗位要求： <br>1. 本科及以上学历，秘书、中文、英文等相关专业优先； <br>2. 熟练掌握电脑操作和Microsoft Office办公软件，具有优秀的文书写作能力；<br>3. 通过CET-4，有良好的英文听说读写能力；<br>4. 形象良好，性格开朗，理解能力强，善于沟通协调，具备较强的语言表达能力；<br>5. 具有服务理念和团队合作精神；<br>6. 做事积极主动、严谨细致，有责任心，适应能力和学习能力强；<br> <br>职位福利：五险一金、加班补助、交通补助、通讯补助、餐补、带薪年假、员工旅游、弹性工作  <br>', '中伦律师事务所创立于1993年，是中国司法部最早批准设立的合伙制律师事务所之一。经过数年快速、稳健的发展壮大，中伦已成为中国规模最大的综合性律师事务所之一。如今，中伦拥有310多名合伙人以及超过2100名专业人士，办公室分布在北京、上海、深圳、广州、武汉、成都、重庆、青岛、杭州、南京、海口、东京、香港、伦敦、纽约、洛杉矶、旧金山及阿拉木图18个城市，业务范围遍及全球60多个国家和地区。通过合理的专业分工和紧密的团队合作，中伦有能力在各个领域为客户提供市场领先的高质量法律服务。', 'https://www.zhaopin.com/jobdetail/CC000400350J40249657616.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5002, '招聘专员/助理', '中国人寿保险股份有限公司石家庄市桥西支公司', '7月3日', '4000-8000元', '石家庄-桥西区', '保险,银行', '100-299人', '不需要融资', 'CC507454320J40738343314', '不加班，纯文职，不轮岗，无套路，真诚招聘人事招聘', '中国人寿保险（集团）公司属于国有（副部级央企）特大型金融保险企业，由财政部100%控股，业务范围全面涵盖保险、投资、银行三大板块。2016年，中国人寿收购广发银行36.48亿股，持股比例将由20%增至43.686%，成为其单一最大股东。中国人寿在全国拥有20000多家分支机构及网点、近100万员工和销售人员、4000多家客户服务中心，连续22年入选《财富》世界500强，2024年位列第59位，品牌价值高达人民币5019.85亿元，持续领跑中国金融保险企业。被誉保险业的“中流砥柱”。', 'https://www.zhaopin.com/jobdetail/CC507454320J40738343314.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5003, 'BD经理', '北京三快在线科技有限公司', '6月27日', '面议', '常德-None', '互联网', '1000-9999人', '已上市', 'CC383625320J40665659309', '美团优选立足生鲜零售业务，是美团具有重要战略性的新业务领域之一。美团优选采取“预购+自提“的模式，为社区家庭用户精选高性价比的商品。我们建立有全国范围内的物流配送体系，在上游对接产地和供货商，引进质优价廉的生鲜食材及日用品，为消费者提供更方便的购物体验。美团优选也始终致力于实现社会价值。近年来，我们开展“农鲜直采”计划，与全国多个地方政府建立合作，加速优质农产品从原产地直达社区，助力乡村振兴；同时，我们还积极培养农村电商人才，拉动千万就业，助力地方扶贫。 这里是一片充满收获和成长的广袤天地，有完善的社招、校招人才选拔及培养体系，一切蓄势待发，只等你来！<br>岗位职责<br>1.负责常德市地区美团优选业务合伙人的招募。<br>2.主动寻找并建立与地面商户的合作关系，提升美团优选的市场份额。<br>3.负责与合伙人进行业务洽谈，了解需求，提供专业的解决方案并达成合作。<br>4.跟进合作项目的执行过程，与内部团队协作，确保项目的顺利推进及达成商业目标。<br>5.持续跟踪市场动态和竞争对手的情况，及时调整招商策略，提高地面商户拓展效率。<br>岗位基本需求<br>1.专科及以上学历，具备良好的商务谈判和沟通能力。<br>2.对地面商户拓展有一定的理解和经验，熟悉常德市地区商圈和商户资源。<br>3.具备较强的市场分析和判断能力，能够准确把握市场需求和商户的潜在机会。<br>4.具备较强的应变能力和抗压能力，能够在复杂环境下有效开展工作。<br>5.具备较强的团队合作精神和协调能力，能够与内部团队紧密配合，共同完成目标。<br>岗位亮点<br>1.作为美团优选招商顾问，将有机会参与到常德市、岳阳市地区的合伙人招募项目，为美团优选的业务发展做出贡献。<br>2.可以通过与合伙人的合作，提升自身的业务开发能力和谈判技巧，拓宽职业发展的空间。<br>3.与内部团队协作密切，参与项目的推进过程，有机会获得全面的职业成长和发展机会。', '美团是一家科技零售公司。美团以“零售+科技”的战略践行“帮大家吃得更好，生活更好”的公司使命。自2010年3月成立以来，美团持续推动服务零售和商品零售在需求侧和供给侧的数字化升级，和广大合作伙伴一起努力为消费者提供品质服务。2018年9月20日，美团在港交所挂牌上市。美团始终以客户为中心，不断加大在新技术上的研发投入。美团会和大家一起努力，更好承担社会责任，更多创造社会价值。', 'https://www.zhaopin.com/jobdetail/CC383625320J40665659309.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5004, '网络客服', '成都萌小玺文化传媒有限公司', '2025-07-27 02:01:14', '100-150元/天', '全国-None', '新媒体', '10000人以上', NULL, 'CCL1486511100J40866112915', '1.有无经验均可！<br>2.工资每天自提<br>3.没有设备要求，手机+耳机就可以！<br>4.全程不收取任何费用！<br>5.对声音没要求', '成都萌小玺文化传媒有限公司，成立于2024年，位于四川省成都市，是一家以从事文化艺术业为主的企业。成都萌小玺文化传媒有限公司，成立于2024年，位于四川省成都市，是一家以从事文化艺术业为主的企业。', 'https://www.zhaopin.com/jobdetail/CCL1486511100J40866112915.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5005, '律师助理', '北京大成律师事务所', '11月18日', '6000-8000元', '深圳-None', '咨询服务,法律服务', '1000-9999人', '未融资', 'CC157836920J40491334912', '具有本科学历，法学学位，知名法学院校优先考虑，工作日到派驻地点为深圳市某局，位于福田区，交通方便，待遇从优。', '北京大成律师事务所成立于1992年，是中国成立最早、规模最大的合伙制律师事务所之一。秉承“志存高远，海纳百川，跬步千里，共铸大成”的文化核心理念以及“全球资源、本土智慧”的开放式发展战略，大成始终致力于为国内外客户提供专业、全面、及时、优质、高效的法律服务。经过三十余年的发展，大成已经成为在中国境内拥有超过50家办公室，服务范围覆盖国内全部省、自治区和直辖市，并且与在世界范围内80余个国家及地区设有160多个办公室的Dentons律师事务所拥有优先合作关系的专业化、规模化、国际化、一体化、数字化、平台化、生态化、品牌化的大型综合性律师事务所。', 'https://www.zhaopin.com/jobdetail/CC157836920J40491334912.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5006, '大客户代表', '合肥上雅电子科技有限公司', '7月22日', '7000-14000元', '合肥-蜀山区', '计算机硬件,IT服务', '20-99人', '未融资', 'CC280521430J40578343009', '岗位:联想安徽战区政企业务群销售代表<br>岗位职责:<br>1、负责联想政企企业群全系列智能终端产品及数据中心方案的销售工作;<br>2、根据公司政策，制定和实施销售计划，完成销售任务;3、负责所辖区域分析，把握区域发展动态，收集、分析、整理、归档客户需求;<br>4、负责客户关系维护，对区域客户进行开拓，实现多产品销售;<br>5、对区域信息及友商动态，保持敏捷的洞察力，项目信息资源获取。<br>任职要求:<br>1、本科及以上学历;<br>2、有电脑、大屏、服务器及软件方案等销售工作经验者最佳<br>3、具有较强的沟通协调能力，能够独立运作项目和商务谈判<br>4、具有较强的应变能力和学习能力，敏锐的洞察力:<br>5、富有激情，团队意识强，善于与人合作，乐观进取，勤奋务实，愿意尝试挑战', '合肥上雅科技，成立于2007年，旗下包括合肥上雅电子科技有限公司和合肥金四达科技有限公司。我公司从事计算机软硬件、系统集成、网络工程及IT产品的研发与销售。坚持诚信为本、用户至上、开拓创新的原则，致力于为客户提供最优质的硬件产品、最专业的技术解决方案和完善快速的售后服务。我公司长期服务于电信、移动、联通、邮政、银行、企业、石油等各行各业，为客户提供专业的网络应用解决方案及设备，产品广泛应用。上雅科技是联想安徽省的直签伙伴，全面销售联想桌面级、企业级、外设等全系列产品。多年来，上雅科技提供了大量优质的硬件产品、成功的解决方案和完善快速的售后服务。', 'https://www.zhaopin.com/jobdetail/CC280521430J40578343009.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5007, '销售工程师', '武汉爱基百客生物科技有限公司', '7月9日', '9000-13000元·13薪', '厦门-翔安区', '专业技术服务,农/林/牧/渔,科学技术推广,学术/科研', '100-299人', '未融资', 'CC405964330J40776852212', '岗位职责：<br>1. 开展分子生物科学技术推广和潜在客户挖掘工作，处理客户的咨询工作，反馈市场信息；<br>2. 完成本区域内技术服务产品和服务的销售任务和回款任务；<br>3. 根据市场情况和项目的具体情况，制定、实施相应的项目销售策略；<br>4. 了解客户需求，建立各级***档案，定期维护客户关系，保持与客户之间良好沟通；<br>5. 负责宣传文案和资料的整理和撰写工作，配合市场推广活动、学术产品讲座等工作；<br>6. 按时完成公司分派的各项工作。<br>任职要求：<br>1. 开展分子生物科学技术推广和潜在客户挖掘工作，处理客户的咨询工作，反馈市场信息；<br>2. 完成本区域内技术服务产品和服务的销售任务和回款任务；<br>3. 根据市场情况和项目的具体情况，制定、实施相应的项目销售策略；<br>4. 了解客户需求，建立各级***档案，定期维护客户关系，保持与客户之间良好沟通；<br>5. 负责宣传文案和资料的整理和撰写工作，配合市场推广活动、学术产品讲座等工作；<br>6. 按时完成公司分派的各项工作。<br>职位福利：五险一金、绩效奖金、交通补助、带薪年假、员工旅游、节日福利、周末双休、定期体检', '武汉爱基百客生物科技有限公司位于武汉国家生物产业基地——光谷生物城，是一家专业提供表观组学技术服务与表观组学生物信息分析的新型生物科技服务企业。爱基百客整合了上海基益生物技术有限公司华中实验平台、销售平台，同时引入具有领先表观组学技术的实验室，致力于提供领先的表观组学技术服务。爱基百客已经以多种形式先后与国内著名高校和科研机构展开了合作，合作伙伴包括中国科学院部分研究所、中国农科院部分研究所、中国农业大学、湖北省农科院、河南农业大学、湖南农业大学、西藏农牧科学院、武汉同济医院、武汉中南医院、湖北省人民医院、湘雅医院、山西医科大学、广东医学院等。“为广大科研工作者提供专业的表观组学技术服务”是爱基百客的使命。我们期望与各领域的专家合作，提供专业、快速的表观组学技术服务，促进科研项目顺利、高效完成。企业文化专心—我们专注于表观组学领域技术开发，脚踏实地做好专业专业—我们坚持标准流程，使用专业仪器、标准试剂，提供最可靠的实验结果舒心—我们的员工工作开心、敬业、充满责任感，为客户创造最好的体验创新—我们锐意研发，持续创造全新的技术和产品，为客户提供更多全新的应用企业愿景成为领先的表观组学技术服务供应商', 'https://www.zhaopin.com/jobdetail/CC405964330J40776852212.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5008, '销售运营', '海口万达广场商业管理有限公司', '6月13日', '4000-5000元·16薪', '海口-秀英区', '物业管理', '100-299人', '已上市', 'CC312341930J40622861205', '1.协助营运主管完成部门下达的工作任务和指标<br>2.负责管辖区域的各项工作，及时上交各种报表<br>了.协调与各品牌的关系，及时与品牌沟通<br>4.督促各品牌店长的工作，将每日各品牌的信息整理上报。<br>任职要求:<br>1.应届毕业生优先，有话剧表演经验，表演专业毕业的优先;<br>2.沟通能力强，执行力强:<br>3.熟练使用办公软件<br>4.认同万达企业文化，具有较强的工作责任心。', '万达集团股份有限公司创立于1988年，形成商业、文化、网络、金融四大产业集团，2017年位列《财富》世界500强380名。2017年万达集团总资产8826.4亿元。万达商管集团是全球领先的商业物业持有及管理运营企业。截至2017年底，已在全国开业北京CBD、上海五角场、成都金牛、昆明西山等235座万达广场，持有物业面积3151万平方米，年客流31.9亿人次。2018年计划开业52个万达广场。目前，万达集团已经在广东地区布局白云万达、番禺万达、增城万达、萝岗万达、南沙万达、佛山南海万达、佛山三水万达、江门万达、东莞东城万达、东莞长安万达、东莞厚街万达、东莞虎门万达、湛江万达、梅州万达、海口万达、清远万达等22项目。根据集团战略规划，未来3-5年，万达集团将在广东地区布局超过30个以上项目。', 'https://www.zhaopin.com/jobdetail/CC312341930J40622861205.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5009, '储备干部', '天津肯德基有限公司', '7月25日', '4000-6000元', '廊坊-三河市', '餐饮服务', '10000人以上', NULL, 'CC134529310J40613754101', '【职位介绍】 <br>主要从事餐厅值班管理、订货管理、排班管理、利润管理、人力资源管理、营业额建设等餐厅营运管理工作。<br>具有完善的培训体系和快速的职业发展：储备经理入职最快18个月晋升至餐厅经理，成为独当一面的职业经理人。<br>【基本要求】20~28周岁，专科及专科以上学历，能够适应早晚班，高效的工作模式，愿意从事餐饮服务行业。<br>【薪资】基本薪资+季度奖金，入职6个月后调薪；每年享受绩效调薪<br>【福利】入职首月享受5险1金+雇主责任险+商业医疗保险+全家保险计划+免费年度体检<br>【长期激励】晋升餐厅经理后年薪10万以上，晋升满1年享股权激励，晋升满2年享家庭福利计划，晋升满3年享购房贷款/贴息<br>【合同】入职即签订3年正式劳动合同（4个月试用期，薪资100%发放）<br>【假期】10-20天带薪年假、5-10天全薪病假<br>【休息】每周上5休2 <br>【加班费】节假日若加班，享受额外3倍薪资补贴<br>【工作时间】因餐饮行业的特殊性，我们的工作时间属于倒班制，每月由餐厅经理排定班表，请您结合自身情况考虑是否能够适应以下班次。<br>月度排班，每天一个班次，早中晚三班各占1/3<br>【必胜客】<br>7:00-16:00；9:00-18:00；15:00-24:00<br>每周双休（不固定休息六日，也不一定能够连续两天休息），法定假日排班享受三倍工资，依据餐厅营运需求进行排班。<br>【工作地点分配原则】<br>-根据家庭住址就近分配；<br>-餐厅培训状况及水平<br>Q&amp;A：<br>Q1：储备经理是服务员吗？具体工作有哪些？<br>A1：不是服务员，储备经理是餐厅的管理人员，大部分时间的工作是在餐厅楼面进行值班管理，与餐厅伙伴并肩战斗在一线，共同服务顾客。刚步入职场的你，将逐步学习和负责餐厅的值班管理工作，确保值班期间餐厅的正常运营。<br> 随着学习的深入及职级的快速晋升，您将学习到订存货管理、排班管理、利润管理、餐厅营销等经营一家餐厅的各项技能。<br>Q2：没有相关的工作经验，专业又不相关，会不会对面试有影响呢？<br> A2：这点不用担心，餐厅针对所有员工的培训都是从0开始的，入职后餐厅将制定详细的培训计划，安排1对1的培训，高效的培训也是百胜的优势。<br> <br> <br>职位福利：五险一金、绩效奖金、带薪年假、补充医疗保险、节日福利、双休、晋升快、平台大  <br>', '百胜中国控股有限公司是中国领先的餐饮公司，致力于让生活更有滋味。自从1987年第一家餐厅开业以来，百胜中国今天在大陆的足迹遍布所有省市自治区，在1,100多个城市拥有超过7,500家餐厅。百胜中国从Yum! Brands（纽约证券交易所代码：YUM）分拆出来之后，于2016年11月1日独立在纽约证券交易所上市，股票代码为YUMC。百胜中国在中国市场拥有肯德基、必胜客和塔可贝尔三个品牌的独家运营和授权经营权，并完全拥有东方既白和小肥羊连锁餐厅。经过三十年的发展，百胜中国不仅在店面数量，而且在品牌知名度、社交及数字媒体营销和传播、全国供应链管理、产品质量、以及创新方面都已经成为了一家中国领先的餐饮企业。百胜中国42余万的员工是其发展的支柱，与此同时，在百胜积累了经验丰富的管理团队和全情投入的前线伙伴也正在继续引领发展活力充沛、直面机遇和充满欢乐的企业文化。在包括风靡全球的肯德基原味炸鸡等产品的基础上，百胜中过还不断开发符合当地口味的产品，从而建立起强有力的顾客忠诚度。每一个品牌都有其专属产品，很多都是中国本土创新，同时公司也研发出众多独有产品与调味产品，为消费者提供美味便捷并且高品质的食物。通过在中国多年的发展与积累，已拥有深厚的消费者知识与忠诚度，各品牌的产品也已成功融入流行文化与消费者的日常生活之中。百胜中国将通过创新产品、提升就餐体验、增强移动连接、以及持续创造价值来满足消费者不断改变的需求。百胜中国对于未来长期的发展充满信心。', 'https://www.zhaopin.com/jobdetail/CC134529310J40613754101.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5010, '总助/CEO助理/董事长助理', '成都阳光铝制品有限公司', '2025-07-27 01:21:41', '4000-6000元', '眉山-东坡区', '电气机械/电力设备,金属制品业', '1000-9999人', '未融资', 'CC236648410J40397251108', '负责落实生产总监的各项工作，落实各车间的周总结月总结报告，编制周总结月总结报总经办，组织制造中心生产会议，督查各车间生产，成本，制度的落实。<br>职位福利：提供吃住、购买五险、带薪年假 <br>', '成都阳光铝制品有限公司创建于1998年，产品涵盖铝合金门、窗型材、幕墙型材、装饰型材、工业型材、汽车型材、塑钢型材、全铝家居等。现有员工3000余人。在习总书记引领的新时代，实现了一次次产业大升级，从绿色型材到低碳生活，阳光铝业以一流品性塑造一流工匠，现已形成集研发、生产、销售为一体的西南大型型材基地。公司先后与碧桂园、雅居乐、绿地、万科等知名地产公司形成长期战略合作。现已完成世界最大摄电望远镜——天眼的铝合金供材，完成了成都环球中心、阿里巴巴西部基地、欧盟大厦、世界最大电子竞技馆等供材。做中国最好但不是最贵的铝合金型材！阳光铝业，百年企业，强企强民！', 'https://www.zhaopin.com/jobdetail/CC236648410J40397251108.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5011, '销售工程师', '吉林隆华', '7月16日', '3000-4000元', '长春-南关区', '金属制品业,仪器仪表制造,电气机械/电力设备', '100-299人', '未融资', 'CC153565010J40800205313', '一、 岗位职责​', '吉林省隆华测控设备制造有限公司是专业从事工业监测、监控仪器仪表的开发、制造、销售及服务的高新技术企业。公司成立于2003年，坐落于环境优美的长春市净月经济开发区，占地面积两万余平方米，厂房建筑面积近万平方米。公司综合实力雄厚，是吉林省守合同重信用AAA级单位、吉林省高新技术企业、长春市专利示范企业，具有锅炉安全附件制造资质和计量器具制造等资质。公司拥有先进的制造、检测设备，完善的生产工艺，专业的生产、检验人员，并通过了ISO9001：2008国际质量体系认证，为生产组织及质量控制提供可靠保障。公司为国内十多家大中型锅炉、辅机、汽轮机制造企业提供配套服务，产品用户近千家，覆盖全国电力、石油、化工、钢铁等领域，并出口至马来西亚、印度、印尼、约旦、巴西、阿塞拜疆等国家。', 'https://www.zhaopin.com/jobdetail/CC153565010J40800205313.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5012, '销售运营', '中国平安', '7月25日', '面议', '上海-浦东新区', '保险,保险', '10000人以上', '已上市', 'CC000204810J40771284112', 'o(^▽^)o不加班，不电销<br>(^○^)企业文化:<br>我们固定早九晚六周末双休我们绝对不加班，下班就走，我们适合喜欢做服务，而又不想有太多工作压力的人(不打电话不电销)同时对于有晋升欲望、有赚钱欲望的人，我们也给予充足的空间。人性化工作时间+周末双休不加班!<br>●福利待遇：<br>工资构成:<br>1、基础无责底薪+职级津贴+岗位津贴+绩效，综合薪资7-25k<br>2、缴纳社保:医疗保险，意外医疗、疾病医疗、生育险、失业保险+企业保险+住房公积金。<br>●工作时间:<br>早上:09:00-18:00，7小时工作制，午休两个小时。绝不加班。<br>周末双休。带薪年假，年底双薪，法定节假日带薪休假+带薪158天产假<br>●发展空间:<br>需要锻炼自己、提升自己，那么平台就很重要，上市公司五百强晋升培养机制完善，管理岗位需求大，对于有晋升意愿的伙伴提供职位直升扶持!<br>绝对的公平公正公开，全靠实力，全是实力派。<br>●培训<br>不用担心自己不会哦<br>1、新人入职了解公司、熟悉产品、超简单、这么聪明的你肯定没问题。也有平安大学做后盾<br>2、培训结束，公司分配师傅、组长、团队主管手把手教<br>●工作环境:<br>1、5A级舒适的办公环境(氛围融洽友好，团队年轻而富有活力)<br>2、员工旅游+员工生日会+发放丰厚的奖励，优秀员工每月有表彰(超多惊喜等你一起)<br>3、每年5-15天带薪年假(幸福感超足哦)<br>4、享受国家法定婚假产假以及陪产假等(一起见证你人生的每一个重大时刻)<br>5、琳琅满目的零食、咖啡、饮料、下午茶(工作的同时放松一下)<br>6、丰富的企业活动，团建聚餐等<br>●●●员工关怀<br>1.为员工提供多途径反馈工作、生活中遇到的问题困难，通过面对面圆桌会，线上答疑等方式给予解助<br>2.为家庭特别困难员工提供帮助，领导可爱同事暖心', '中国平安致力于成为国际领先的科技型个人金融生活服务集团。2019年，中国平安深入推进\\\\\"金融+科技\\\\\"、\\\\\"金融+生态\\\\\"战略转型，持续提升数据化经营能力，整体业绩及核心金融业务持续稳健增长，科技赋能成效显著，生态赋能效果初显，综合金融用户数、客户数、客均合同、客均利润均有明显增长。公司实现营业收入同比增长19.7%至11,688.67亿元。截至2019年底，公司个人客户数首次突破两亿，互联网用户量达5.16亿，全年新增客户数3,657万，其中40.7%来自集团五大生态圈的互联网用户。中国平安始终践行\\\\\"金融为实体经济服务\\\\\"的精神，坚持把实体经济服务作为出发点和落脚点，通过旗下的保险、银行、信托、金融科技等业务，把逾4万亿金融资源配置到经济社会发展的重点领域和薄弱环节，包括通过保险保障、提供贷款、债权股权计划、普惠金融等多种方式，全面助力实体经济发展。凭借全球领先的创新科技，中国平安将科技深度运用于金融主业中，助力降本增效、风险管控，打造优质产品和极致服务体验，提升客户口碑。与此同时，平安将领先科技广泛应用在金融、医疗及智慧城市等领域，全面支撑\\\\\"金融服务、医疗健康、汽车服务、房产服务、智慧城市\\\\\"五大生态圈建设。在企业社会责任方面，平安深化可持续发展理念，MSCI ESG评级连续两次调高至A级，打造AI-ESG平台赋能责任投资，截至2019年12月末，公司责任投资规模达9,544.49亿元，可持续保险金额达121.21万亿元，绿色信贷年度授信总额590.56亿元。同时，平安积极响应国家脱贫攻坚战的号召，推进\\\\\"三村扶贫工程\\\\\"项目，累计提供专项扶贫资金249.05亿元。面对新冠肺炎疫情，平安第一时间推出保险保障、医疗支持、对外捐赠等多重支持举措，提供的物资及现金捐赠总额超1.75亿元。2020年，中国平安品牌价值持续提升，名列美国《财富》“世界500强企业”第21位，居全球金融企业第2位，《福布斯》全球上市公司2000强第7位，BrandZ™全球品牌价值100强第38位，蝉联全球保险品牌第1位。', 'https://www.zhaopin.com/jobdetail/CC000204810J40771284112.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5013, '英语翻译', '广州可酷动漫科技有限公司', '7月5日', '8000-16000元', '广州-番禺区', '文化艺术/娱乐,贸易/进出口,金属制品业', '20-99人', '不需要融资', 'CC410673580J40752352301', '岗位职责：<br>1、负责国际市场对外联络业务，向国外客商推广公司娃娃机、扭蛋机产品，开发市场，及时处理客人的询盘及各种需求。为客户提供主动、热情、满意、周到的服务；<br>2、不断开发、维护新老客户，推荐产品方案、促进交易达成；<br>3、负责信息搜集、整理，包括市场信息、客户信息、合作伙伴信息等;<br>4、收集一线市场信息、用户意见、同行业业态信息、友商信息，反馈至公司，对公司市场开发、售后服务、产品质量、新产品开发等提供参考；<br>5、完成上级安排的其他工作.<br>任职资格：<br>1、大专以上学历，国际贸易或英语专业；<br>2、热情、积极向上，喜欢交际，服从管理，懂得团队协作；<br>福利待遇：<br>1、15-25k（含基本底薪、提成收入、差价收入等），提供卫生健康的工作午餐＋晚餐，不定期组织员工聚餐或拓展活动，丰富员工生活；<br>2、环境超好的员工宿舍。每月下午茶；<br>3、不定期专业知识培训，不定期外贸知识培训等；<br>4、上班时间：朝九晚六.', '公司简介：广州可酷动漫科技有限公司，简称可酷科技KEKUTECH。自创立之初就确立了以自主设计、研发为基础，服务和运营为中心的发展方向，专注于移动互联网礼品机、订制网红娃娃机、高端彩票机、儿童扭蛋机、等新款游戏机娱乐设备的深度发展。公司核心团队成立于2008年，公司正式注册于2015年，总部位于广东省广州市番禺区星力动漫产业园VR小镇55号(1-4层)。成立至今荣获广东省守合同重信用企业，13项国家专利，14个注册商标。公司总占地面积1500平方米，员工总人数80人，其中研发团队11人。平均年龄26岁，相当于早晨8点钟的太阳。是一个年轻有朝气、有干劲、有冲劲的团队！我们秉承“可酷科技，激活人生”的企业思想，运用“专注、创新、高效、品质、共赢”的发展理念，致力于打造领先的智慧商业服务提供商。自主研发已成为可酷科技建立长期可持续竞争优势的源泉，未来将继续以自主研发为先导，以全新面貌、全新理念、全新模式运营，着力打造专业电玩设备品牌及研发、服务、运营一体化产业，坚持互利合作，共赢互存，为全球消费者创造高品质的娱乐体验。公司主要服务客户有：肯德基、美肤宝、爱奇艺、万达影城、普思资本、熊本熊、哈喽菜菜、中影国际影城、大玩家、夹机占、泡泡马特等国内外知名品牌。产品销往全国三十多个省市、自治区。产品还出口到美国、澳大利亚、法国、俄罗斯、马来西亚、巴西、哈萨克斯坦、等几十个国家，并得到用户的一致好评。福利介绍：1、写字楼办公，公寓式员工宿舍；2、公司专业食堂，干净、卫生又营养!（中餐、晚餐吃得好很重要，饭后不定期水果、下午茶，吃货公司就是任性）；3、运动使人变好看，每周五运动日，全员动起来！工作健身两不误；4、一年两次旅游、不定期聚餐、员工生日会、各节假日礼物，丰富多彩的员工活动；5、百善孝为先，重大节日公司代送礼物给优秀员工的家人；6、重点是有公平公正的竞争平台、晋升机会，享有公司内部的系统培训、外送培训机会等。物质和精神收获必须同时拥有。心动了吧？这个必须的，我们的福利远远不止这些，随时欢迎年轻活泼的你加入我们！发送简历至邮箱：2849696069@qq.com联系方式：13826011743（微信同号）联系人：张先生工作地址：广东省广州市番禺区迎新东路VR小镇55号（1-4层）附近车站：龙美村（迎新路）：番27路，番73路、番7路', 'https://www.zhaopin.com/jobdetail/CC410673580J40752352301.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5014, '管培生/储备干部', '江苏沃得集团', '7月25日', '7000-12000元', '镇江-丹阳市', '专用设备制造,通用设备制造', '10000人以上', '未融资', 'CC212856610J40521430508', '位职责<br>1、负责公司产品在国外地区市场的开拓，推广及售后；<br>2、负责公司市场策略及政策在海外的落实；<br>3、能够独立调研当地市场并对当地市场开发提出可行性建议；<br>4、代表公司参加国内、外展会，洽谈业务，会后跟进客户，将目标客户转化成实际订单；并深入发掘客户的需求。<br>5、积极主动完成领导委派的其他事务性工作<br>任职要求<br>1、本科以上学历，专业不限；<br>2、抗压能力强，能够适应国内外出差；<br>3、性格开朗，形象气质佳，熟悉商务礼仪，具备良好的沟通、协调及执行能力；<br>  入职培训：提供系统培训，一对一带教计划。试用周期6个月。', '沃得集团创立于1988年，专注于农业机械、锻压机械、园林机械、工程机械及汽车零部件等领域。目前沃得集团有员工15000余人，在全国有五大生产基地，在全球有三家海外子公司，业务覆盖全球100多个国家和地区。沃得集团秉承“诚实”企业文化，强调‘对企业忠诚、对同事坦诚、对客户真诚；基础要夯实、工作要踏实、做人要老实’。沃得集团一直倡导工匠精神，关注员工成长，不断提升产品品质；致力于全产业链经营，为客户提供全面解决方案。沃得集团被评为国家级企业博士后科研工作站，旗下五家子公司被认定为国家高新技术企业，连续多年入选中国民营企业500强，多次获得江苏省百强工业企业、省创新型领军企业、“江苏省明星企业”等荣誉。更多信息请直接登陆集团网站 www.worldgroup.com.cn', 'https://www.zhaopin.com/jobdetail/CC212856610J40521430508.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5015, '档案管理', '千缘婚恋服务有限公司', '7月24日', '2000-3000元', '襄阳-樊城区', '咨询服务', '20-99人', '未融资', 'CCL1487642810J40676443810', '岗位内容：<br> 进行档案数字化化、电子化工作，构建信息化档案管理系统<br>1.档案整理及扫描对数字化档案进行数字化前的整理工作，对材料进行分类整理，标写页码，根据整理好的档案实体，录入卷内目录和案卷目录。按照整理好的档案实体顺序进行扫描，确保图像清晰、页码连贯。<br>2.图像处理<br>对扫描图像进行纠偏、去污、去黑边等处理，确保图像质量。<br>3.档案装订<br>数字化加工完成后，打印新的卷内目录，并依据规范装订成卷，对案卷进行还原。', '我司是世纪佳缘百合网南阳分公司。世纪佳缘，中国领先的婚恋交友平台，由龚海燕女士2003年10月8日创立于中国上海。自创立以来，世纪佳缘致力为用户提供全方位的在线婚恋交友服务。2011年5月11日，世纪佳缘登陆美国纳斯达克股票市场，成为国内首家上市的在线婚恋交友平台。至2016年7月，世纪佳缘的用户注册总数就已超1.7亿。世纪佳缘自2013年起大力推进公司主营业务从PC端向移动端转移，并在移动端进行多品牌的战略布局。2014年更是加速布局移动端，当年5月推出爱真心App后，同年12月世纪佳缘新版App也正式上线。2016年至2017年世纪佳缘移动端陆续推出么么答、佳缘直播等产品，给予用户更好的互动体验，月活跃用户高达500万。世纪佳缘线下一对一红娘业务也保持着稳步提升，并于2015年7月推出红娘经纪人业务。截至2017年4月，线下一对一红娘业务已经覆盖全国71个主要城市，107家线下实体店，红娘经纪人人数超过15000人。同时，世纪佳缘还将线上线下业务成功结合，曾成功举办中国首届爱情运动会、多场万人相亲大会和集体婚礼。2017年9月，世纪佳缘与百合网正式完成合并，新公司正式更名为“百合佳缘网络集团股份有限公司”。目前百合佳缘集团已触达中国4亿消费者，成就1620万人的美好爱情。', 'https://www.zhaopin.com/jobdetail/CCL1487642810J40676443810.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5016, '销售运营', '上海建发致新医疗科技集团股份有限公司', '3月24日', '4000-7000元', '郑州-金水区', '医疗设备/器械,货运/物流/仓储,医疗设备/器械', '1000-9999人', '未融资', 'CC843428170J40891360604', '职位描述', '上海建发致新医疗科技集团股份有限公司（以下简称“建发致新”）创立于2010年，作为全国性的高值医疗器械流通商，主要从事医疗器械直销及分销业务，并为终端医院提供医用耗材集约化运营（SPD）等服务。2019年，厦门建发医疗健康投资公司正式控股建发致新，成为建发集团成员企业。依托建发集团对资源的整合和调配能力、丰富的服务经验与运营规划能力、富有竞争力的供应链管理服务保障，建发致新完成“全国管理一体化”以及“供应链+衍生服务”核心竞争力的构建，为客户提供全流程供应链管理服务。建发致新相继在全国31个省（市区）成立65家控股子公司、10家分公司，建立全国一体化运营体系网络，总部位于上海，员工一千余人，服务2200余家公立医院，三甲医院覆盖率达55%，服务厂家1100余家，2021年实现年配送总额达100亿元。未来，建发致新将继续深耕中国医疗器械的渠道模式，逐步探索出更加高效、有序的道路，积极搭建开放合作共赢的医疗器械产业生态圈，持续为客户创造价值。', 'https://www.zhaopin.com/jobdetail/CC843428170J40891360604.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5017, '风电工程师', '陕西梓骆电力科技有限公司', '7月18日', '5000-10000元', '哈尔滨-南岗区', '新能源,新能源', '100-299人', '不需要融资', 'CCL1485552460J40577748616', '任职要求： <br>1、电气、机械类相关专业有工作经验(无经验也可以） <br>2、可接受中长期驻外工作； <br>3、持有安监局下发的特种电工证 <br>工作地点：根据籍贯就近分配（全国都可分配） <br>岗位职责：按照风机机组及配套设备的维护技术要求，对其定期巡检、维护、定期检修、故障消除、技术改造等，保障风电机组的安全、稳定运行。 <br>四、薪资： <br>1、工资：第一年：每月5000-6500元，；工资每3个月或半年考核一次，考核通过，调薪500-1500元。工作满1年以后 工资8000-12000元（岗位等级不同薪资待遇不同） <br>每工作2-3个月带薪休假10-15天，回家往返路费公司报销，1000公里以下，高铁二等座，1000公里报销飞机票二等座。 <br>职位福利：交通补助、高温补贴、六险一金、包住、加班补助、多次晋升机会、 <br>', '陕西梓骆电力科技有限公司成立于2024年04月07日，注册地位于陕西省西安市未央区凤城三路巍然大厦6楼604，法定代表人为常杰。经营范围包括一般项目：风力发电技术服务；信息咨询服务（不含许可类信息咨询服务）；光伏发电设备租赁；太阳能发电技术服务；电力设施器材销售；先进电力电子装置销售；电力电子元器件销售；电气设备销售；机械电气设备销售；电气设备修理；技术服务、技术开发、技术咨询、技术交流、技术转让、技术推广；工程技术服务（规划管理、勘察、设计、监理除外）；业务培训（不含教育培训、职业技能培训等需取得许可的培训）；特种作业人员安全技术培训；劳务服务（不含劳务派遣）；人力资源服务（不含职业中介活动、劳务派遣服务）；对外承包工程。（除依法须经批准的项目外，凭营业执照依法自主开展经营活动）许可项目：发电业务、输电业务、供（配）电业务；输电、供电、受电电力设施的安装、维修和试验；', 'https://www.zhaopin.com/jobdetail/CCL1485552460J40577748616.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5018, '法务专员/助理', '深圳瑞捷技术股份有限公司', '7月3日', '200-250元/天', '深圳-龙岗区', '专业技术服务,咨询服务,工程技术与设计服务', '1000-9999人', '已上市', 'CC460318410J40773462614', '岗位职责：<br>1、合同质控法律审核；<br>2、集团法律纠纷案件办理；<br>3、开展普法、廉洁文化推广与宣传等工作；<br>4、参与各业务部门法律咨询与解答<br>5、法律课题研究；<br>6、其他法律事务工作。<br>任职资格：<br>1、本科及以上在校生，法学、民商法、经济法等法学专业优先；<br>2、 参加并通过国家法律职业资格考试者优先；<br>3、法律文书、新闻稿、推广文案写作能力强；<br>4、责任心强、做事细心、谨慎；<br>5、思维清晰、沟通能力、观察及应变能力较强；<br>6、能实习6个月以上者优先。', '深圳瑞捷技术股份有限公司（简称：深圳瑞捷，股票代码：300977）2010年成立，专业从事建设工程第三方评估、驻场管理和咨询服务，接受客户委托对建设工程进行工程实体及管理行为评估，以及针对性咨询服务，协助客户实现从发现问题到提出方案建议到解决问题的闭环。目前，旗下拥有深圳瑞生工程研究院有限公司（简称\\\\\"瑞生工程研究院\\\\\"）、广东瑞诚工程科技有限公司(简称:广东瑞诚)、武汉瑞云捷工程管理有限公司（简称\\\\\"瑞云捷\\\\\"）、深圳捷安工程科技有限公司（简称：捷安）等多个分子公司。瑞生工程研究院专注于批量精装修项目管理、一户一验、驻场咨询等第三方项目管理咨询服务，帮助客户减少质量缺陷，提升一次性到场交付率。捷安科技坚持“以人为本”，为施工企业提供“质量安全评价、质量安全培训、整体质量安全解决方案”等一站式的质量安全管理服务。广东瑞诚工程科技有限公司(简称:广东瑞诚)是深圳瑞捷全资子公司。广东瑞诚专注于工程保险领域的风险管理、技术咨询、保险产品及其相应服务产品开发与推广、保险服务信息化等相关业务，为保险客户提供工程类保险承保前咨询、承保后风险管理、理赔阶段咨询及公估等全流程解决方案。', 'https://www.zhaopin.com/jobdetail/CC460318410J40773462614.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5019, '产品专员/助理', '湖北聚广盛互联网科技有限公司', '7月7日', '6000-8000元', '武汉-武昌区', '通信/网络设备,通信/网络设备,运营商/增值服务', '100-299人', '不需要融资', 'CCL1472640150J40729841916', '一【岗位职责】<br>1、学习产品的专业知识以及内容策划引流。<br>2、逐步熟悉分公司的全部工作流程，配合主管做好公司日常管理培训工作，为日后独挡一面进行全方面的学习；<br>3、学习团队运营管理，提供可行性建议，展开培训工作；<br>4、初步了解人事管理的工作，熟悉公司文化及价值观，成为公司管理人才；<br>二【福利待遇】<br>1、职位底薪5000，能力决定收入，实习生根据个人岗位表现每个月可以拿到1000—2000的绩效，综合薪资可以达到5000—10000.<br>2、公司提供免费住宿，距离公司5分钟路程，设备齐全；<br>3、公司每年提供四次国内外度假机会，三到四次的国内定期举办庆功会等活动；<br>4、推行内部优先晋升制，管理层不外聘，不空降；<br>5、公司拥有成熟的培训体制和公平公开的晋升平台。<br>培训制度：助理-主管-高级主管-准副理-副理-经理<br>三【任职要求】<br>1、大专学历及以上，有无经验均可，27岁以下，愿意从基层做起，了解企业文化，学习成长自己；<br>2、善于沟通交流，表达能力强，有独立的思维见地；<br>3、能够独立处理紧急事件，具有一定的企图心；<br>4、意志坚定，能够融入团队，发挥应有的才能；<br>5、为人正直、热忱，具备良好的团队协作能力。<br>四招聘流程：<br>初试-复试<br>郑重承诺：公司不收任何费用，无需经验，实行带薪培训。一经录用提供员工住宿，为员工提供很好的发展平台与晋升机会。<br>公司地址：湖北省武汉市武昌区中南路中建广场B座17楼17K室', '湖北聚广盛互联网科技有限公司隶属于集团旗下武汉第三家分公司，是一家综合性企业，同时也是一个内部创业型平台，企业中高层管理都由基层开始选拔、培养、晋升，在行业内有近二十年的经营经验。企业1981年开始学习国外先进理念，1999年先后在北京、广州等地区建立子公司，2005年以郑州为中心发展华中区域。为了进一步拓展华东市场2023年在武汉成立武汉三公司并设为华中运营中心负责华中区域运营。业务涵盖批发、零售、投资、咨询、管理等。依托集团强大的规模体系，携于移动、电信、联通等多家运营商联手共同打造5G人工智能，涵盖5G网络运营、套餐办理、iptv、拉新、宽带办理、预存话费、存量客户、积分兑换、携号转网等。自合作以来，受到了各合作商的认可，为接下来的合作打下了坚实的基础。集团一直秉承做实，做强，做大的原则，立足当下，展望未来，聚焦5G，持续践行“服务力”，让科技照进现实。人工智能、移动医疗、物联网等领域的进一步发展，所需的技术要依托5G来实现。集团将紧跟现代信息通信技术的发展，推动5G生态创新，成功融合5G产品，做行业的服务领航者，秉承“科技造就时代、5G创新生活”的观念始终服务于大众，打造智慧5G便捷生活。我们始终相信，员工的成长等于企业的成长。公司提供公平、公正、公开的晋升制度，系统化的培训，轻松的工作环境和氛围，提供职工公寓，一年有三到五次旅游团建活动，以及多劳多得的绩效考核制度。', 'https://www.zhaopin.com/jobdetail/CCL1472640150J40729841916.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5020, '总助/CEO助理/董事长助理', '郑州百壹源信息科技有限公司', '6月23日', '8000-15000元', '郑州-金水区', '快速消费品,零售/批发', '100-299人', '未融资', 'CC823714350J40713770802', '岗位职责：<br>1. 前两个月跟着经理外出学习工作模式，主管一对一带着外跑对接商户商家，锤炼待人接物能力<br>2. 负责经理的日程安排、日常事务处理、决策信息的传达，并及时提醒完成<br>3. 负责经理所需重要文件的起草与修订，及时传达经理的各项指示安排<br>4. 协助经理处理外部公共关系，接待访问总经理的重要来宾等<br>5. 完成经理交代的其他事项<br>岗位要求：<br>1. 20-45岁，不看学历只看能力<br>2. 形象好气质佳、沟通能力强、悟性高、职业素养高<br>3.1-2年工作经验，学校社团干部优先录取 <br>薪资待遇：<br>1. 试用期两个月，无责底薪4000+4000绩效，综合工资8000+上不封顶（看个人野心）<br>2. 公司提供住宿，有餐补，带薪年假，节日福利<br>3. 公司不定期组织聚餐、团建、户外旅游活动等<br>4. 入职即签合同', '公司简章郑州百壹源信息科技有限公司目前是做中小微商户推广银行聚合收单支付等多项业务。业务开展两年多以来，市场不断扩大，现因业务需要，扩招人才。招聘职位：经理助理(管理层方向培养)：5000—10000+提成+奖金+年终奖市场推广专员：6000—15000+提成+年终奖实习生/储备干部（两个月后转正）：3000—5000+奖金+年终奖福利待遇：工作环境优越，工作氛围融洽和谐，帅哥美女多，成长发展空间大公司地址：河南省郑州市金水区郑东新区绿地原盛国际3C', 'https://www.zhaopin.com/jobdetail/CC823714350J40713770802.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5021, '统计员', '聚赢(沈阳)企业管理信息咨询服务有限公司', '6月30日', '7000-11000元', '沈阳-沈河区', '咨询服务', '100-299人', '未融资', 'CCL1447983430J40833897715', '招聘要求：<br>1、教育背景：大专及上学历（法学、财务、税务、法律、理工等相关专业背景优先）。<br>2、专业技能：具备良好的沟通、分析、学习和抗压能力。熟练使用办公软件，如Word、Excel、PowerPoint等。<br>3、工作经验：认可助贷行业，具有一定的沟通能力，及学习能力。<br>4、个人素质：热爱金融工作，具有较强的团队合作精神和服务意识；积极主动的工作态度和良好的责任心，出色的逻辑分析能力与沟通能力；能够适应长期的项目现场支持，可接受长期出差驻场（东三省）。 5、工作内容：客户审核，风控，银行做件。 <br>福利待遇： <br>薪资：无责底薪7K——8K+业务提成 <br>福利：五险双休法休 <br>外派时公司提供住房或承担房租；', '聚赢（沈阳）企业管理信息咨询服务有限公司（简称聚赢金服）是一家为客户提供助贷服务的专业性平台，坐落于辽宁省沈阳市商会总部大厦B座26层。公司建立了全面，系统的咨询与服务平台。致力于为客户提供高效、快捷的融资服务体验，坚持提供高品质的产品、贴心的服务。为中小企业及个人堤供专属的私人订制融资方案。', 'https://www.zhaopin.com/jobdetail/CCL1447983430J40833897715.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5022, '总助/CEO助理/董事长助理', '四川弘迈电力设计有限公司', '6月25日', '4000-8000元', '成都-武侯区', '电力/水利/热力/燃气', '20-99人', NULL, 'CCL1319510450J40684593406', '岗位职责：<br>1、协助经理安排日程、会议及差旅行程。<br>2、协助经理进行项目管理；<br>3、跟进会议决议及项目进度，协调跨部门协作。<br>4、完成经理交办的临时性任务。 <br>任职要求：<br>1. 本科及以上学历，电力相关专业，优秀应届毕业生亦可； <br>2. 具备优秀的沟通协调能力，分析和解决问题的能力；； <br>3. 具备一定的驾驶技能；', '四川弘迈电力设计有限公司，成立于2015年9月，注册资金叁佰陆拾万元人民币，公司具有四川省住房和城乡建设厅颁发的电力行业（新能源发电、送电工程、变电工程）专业乙级、工程勘察专业类（工程测量）乙级、工程咨询（火电、水电、核电、新能源）资质。公司通过了ISO19001质量管理体系、ISO14001环境管理体系、ISO45001职业健康安全管理体系认证并且获得了企业资信等级AAA证书、企业信用等级AAA证书。可承担电力系统规划设计、风电、光伏发电等新能源项目以及220kV及以下输变电工程、通讯工程等项目的咨询、勘测设计、EPC总承包、专题研究等业务。具备承接电力系统规划设计、220kV及以下输变电工程以及风电、光伏发电等新能源项目、通讯工程等项目的咨询、勘测设计、EPC总承包、专题研究等业务能力。公司主要为国家电网公司、南方电网公司以及各大发电企业提供全方位服务，业务范围覆盖四川、贵州、重庆等区域。经营范围：电力工程、送变电工程、新能源发电、风力发电工程、工程造价、建设工程等设计、勘察及咨询，工程管理、设计和技术服务，储能技术服务。技术力量：公司拥有一支富有朝气、团结向上、专业素质高的员工队伍，公司总人数46人。其中国家级专家1人，教授级高级工程师2人，高级工程师3人，工程师25人；其中注册电气工程师（发输电）4人，一级注册结构师1人，二级注册结构师2人，一级注册建造师5人，二级注册建造师3人，注册咨询工程师（投资决策）2人，二级注册建筑师2人，注册造价工程师2人，注册公用设备师1人；硕士3人，本科28人。涵盖变电（一次、二次）、线路、配电、结构、土建、测量、技经、其他辅助（总图、给排水）等各专业。公司坚持“致力细节、精心设计、诚信服务、品质至上”的设计理念服务于电网建设、服务客户，并赢得业界和客户的一致信任和好评。', 'https://www.zhaopin.com/jobdetail/CCL1319510450J40684593406.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5023, 'BD经理', '广州物金通信科技有限公司', '7月14日', '6000-12000元', '广州-白云区', '通信/网络设备', '20-99人', NULL, 'CCL1495603250J40776851603', '工作内容：<br>1、负责辖区中国移动相关业务(开卡、携转宽带、流量卡、提速包、智能产品等等，移动全业务)推广，及销售活动的开展执行(包括派发宣传单，社区摆摊促销宣传)，并上门或者现场帮客户办理业务，在对应区域开展社区移动业务开拓新客户；<br>2、做好客情服务，维护现有客户；<br>3、在移动公司指定地点进行移动宽带业务宣传，包括发放宣传单，展示台宣传等；<br>4、通过陌拜、地推等方式带动移动周边产品销售；<br>5、按质按量完成个人每月业绩目标，并配合区域总监完成月度团队指标;<br>6、完成公司及相关负责人安排的临时性工作。客户可以不断累计，老客户介绍客户，我们提成按单计算，每个业务20-600元不等<br>任职要求：<br>1、有地推或市场推广等相关工作经验优选；<br>2、勤快、有责任心及团队精神，有赚钱欲望；<br>3、具有较强的沟通能力和服务意识。<br>公司优势：<br>1、公司资源优越，容易开单；<br>2、新人有人带教，迅速上手；<br>3、团队有专车共用；<br>4、不用回公司，工作比较自由。<br>PS:我们是中国移动旗下联名服务商之一，合作客户覆盖全广州!<br>欢迎有拼搏进取心、赚钱欲望强、想要刚出社会后工作稳速发展的人才进入我们这个大家庭!!!!<br>【薪酬福利】：无责底薪3000+提成，提成上不封顶 <br>【面试地址】：广州越秀区北京路3号港汇大厦12楼12C<br>【上班时间】：10:30 - 19:30 月休6天<br>【上班地址】：就近分配： <br>白云区（金沙洲，石门，石井，松洲，同德，新市，三元里，云城，鹤龙，黄石，棠景，景泰，江高，人和，钟落潭，白云湖，嘉禾，永平，京溪，同和）<br>海珠区（东晓南、凤阳、龙凤、赤岗、瑞宝、琶洲、南洲、黄埔村、江海、官洲、华洲、南石头、沙园、昌岗、滨江、南华西、新港、素社、江南中）', NULL, 'https://www.zhaopin.com/jobdetail/CCL1495603250J40776851603.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5024, '猎头顾问', '保定吉聚知识产权服务有限公司', '7月15日', '7000-10000元', '保定-竞秀区', '法律服务,专利/商标/知识产权', '1000-9999人', '未融资', 'CCL1288337930J40755506601', '咱们是做知识产权的，公司提供客户资源，咱们负责对接客户', '高沃是专业从事知识产权代理业务的法律服务机构，旗下包含北京高沃律师事务所、北京高沃国际知识产权代理有限公司，业务主要涉及商标、专利、著作权的基础申请和维权诉讼等事宜。高沃自进入知识产权代理行业，经过多年的发展，已经拥有多名商标代理人和一批长期从事知识产权维权的专业律师，高沃律所拥有多名专利代理人，商标代理人，成为全国较为大型的代理机构之一。高沃自成立以来一直与世界知识产权组织（WIPO）有密切的联系。目前是国际保护知识产权协会会员（AIPPI）、国际商标协会会员(INTA)、中国知识产权研究会会员（CIPS）。当前“高沃”与亚洲、欧洲、美洲等168个国家的多家知识产权律师事务所达成合作伙伴关系。', 'https://www.zhaopin.com/jobdetail/CCL1288337930J40755506601.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5025, '游戏运营', '辽宁雷德科技有限公司', '4月8日', '100-200元/天', '沈阳-和平区', 'IT服务,IT服务', '20-99人', '未融资', 'CC207516210J40684850112', '岗位内容：<br>1. 策划和执行短视频推广活动，并提高品牌曝光度和用户粘性。<br>2. 监控竞争对手的市场活动和行业趋势，提供有效且准确的解决方案。<br>3. 协调内部资源，完成视频拍摄、制作和发布等工作。<br>任职要求：<br>1. 掌握短视频推广技巧，有成功的短视频推广案例。<br>2. 具备优秀的项目管理能力和市场分析能力。<br>3. 有一定的视频拍摄和编辑经验，熟悉视频制作流程。', '雷德科技公司简介辽宁雷德科技有限公司成立于2006年后更名为雷德科技发展股份有限公司，简称雷德科技。公司主营安防智能化产品：2008年是德国博世（BOSCH）安保系统有限公司代理商，在博世安保系统代理中名列前茅。主要代理德国博世门禁系统，监控系统，公共广播系统。 2014年和美国BOSE音响签订代理协议，打造专业扩声系统。 2019年和华为公司签订安防、视频会议、网络通信等产品合作协议。完善雷德科技在智能领域的产品线，同时和多个世界500百强及世界高科技企业合作确定了雷德科技在行业内的地位。雷德科技成为德国博世BOSCH、美国博士BOSE、中国华为HUAWEI在中国东北、华北地区的指定代理商，其主要代理区域覆盖了黑龙江省、吉林省、辽宁省、即将进入北京市。目前，公司已在中国东北建立一流的科技技术、销售服务、系统设计中心。秉承雷德科技有限公司先进的管理经验和技术业务水平，并拥有来自社会雄厚财力和德国博世BOSCH、美国博士BOSE、中国华为HUAWEI公司的强力支持，公司为客户提供所有产品及其配套设施，包括选型指导、技术咨询和优质的售后服务等。目前提供与支持安保系统各种行业的经典案例和优秀工程，其中包括：所有这些产品可应用于包括公路、铁路、港口、机场、水利水电、矿山、城市环卫建设、石油化工、航海业、农业、道路运输、邮电通信业以及楼宇建筑等行业。雷德科技的愿景是为我们所有的利益相关者创造并提供卓越价值包括我们的员工、客户、股东和社会。为了满足中国不断增长的高级管理人才、高级职业技术人员的需求，雷德科技对新员工进行职业技术培训和实践经验的培养。凭借雷德科技在其行业多年的成功经验和经典案例，目标是成为科技公司的运营者和管理者。公司筹建新的团队，欢迎有志之士加入！', 'https://www.zhaopin.com/jobdetail/CC207516210J40684850112.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5026, '社区运营', '上海擎浩医院管理有限公司南京分公司', '7月10日', '7000-10000元', '南京-玄武区', '卫生服务,卫生服务', '1000-9999人', '未融资', 'CC239981220J40798218713', '岗位内容：<br>1. 拓展社区，搜集用户在居家养老照护家政护理与医疗健康方向的需求信息。<br>2. 拓展社区渠道，策划社区活动实现用户增长和品牌宣传。<br>3. 分析用户数据和市场趋势，了解用户需求和偏好，为用户提供更好的服务和体验，及时响应用户需求。<br>4. 维护和管理社区沟通平台，建立社群沟通管道及时解决用户问题和反馈，维护用户客情关系，深耕用户长期服务需求。<br>任职要求：<br>1.具备基本的医疗照护与健康管理知识与技能;<br>2.具备良好的沟通能力和团队合作精神，开拓精神，积极主动，注重细节；<br>3. 对社区运营和社交媒体有一定的认识和理解，能够独立进行社区管理；<br>4. 从事养老社工，社区团购，本地生活，保险保障，家政，老年大学，康养旅游，宝妈，陪诊师经验者优先;<br>5.持证优先:老年人能力评估师，社群健康助理。', '上海擎浩医院管理有限公司成立于2003年，是一家业内公认的专业陪护服务企业，也是拥有国内最大自主知识产权的陪护平台。公司愿景为：做中国专业、优质的护理服务产业公司。目前，公司业务分布上海、北京、江苏、浙江、山东、安徽、湖北、广东、四川、重庆等多个省、市（直辖），为数百家医院（其中三甲医院占一半以上）和数千万家庭提供了生活护理服务。在护理配套服务行业中有着良好的社会美誉和市场口碑。公司员工由具有丰富经验的具备中高级专业技术职称的管理人员和掌握医疗护理服务内涵和流程的专业人员组成；他们谙熟医疗护理服务的各项管理流程，管理精准，持续创新，致力推动“擎浩”快速走上规范化、专业化发展道路。公司长期和职业技能培训学校进行校企合作，每年培训人次达10万人次以上，培养和选拔了一批批应用型、技能型照护人才队伍，为服务医院高质量发展、服务政府、服务社区、服务百姓提供了坚实的技能人才支撑。目前公司已拥有一批稳定的专科护理员队伍和优秀的星级护理员队伍。经过20年的奋斗，上海擎浩医院管理有限公司以其专业化团队和优良的人力资源体系、信息化体系、培训体系、质控体系凸显出自身的特色和优势。未来，公司将持续以其标准化、规范化、智能化、品质化的服务和管理守正创新、锐意进取，不断推动公司向前发展。上海擎浩南京分公司成立于2008年，目前已与40多家医院建立了合作关系。公司致力于各类护理服务，除了院内服务外，陆续开展了社区护理站、护士上门、居家养老、养老机构和日间照料中心托管等业务，并在国内率先通过“病患陪护及质控管理”ISO9001质量体系认证。公司注重企业文化建设，重合作守信用，积极营造和谐的劳动关系，并获得江苏省家庭服务业百强单位、南京市和谐劳动关系示范企业等荣誉。', 'https://www.zhaopin.com/jobdetail/CC239981220J40798218713.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5027, 'APP推广', '北京三快在线科技有限公司', '7月12日', '面议', '佛山-禅城区', '互联网', '1000-9999人', '已上市', 'CC383625320J40659198109', '💸 薪资结构：<br>✔ 无责底薪2400-3200元<br>✔ 200元全勤奖<br>✔ 5-15元/单配送提成<br>✔ 2-60元/单推广奖励<br>💼 工作内容：<br>✔ 驻店配送酒水，仅送 固定门店3公里内订单<br>✔ 晚班为主，白天轻松，不晒不累<br>🚀 岗位亮点：<br>✔ 0费用入职，无需健康证<br>✔ 就近分配，不跑长途<br>✔ 晋升快：店员→店长→主管，发展空间大！', '美团是一家科技零售公司。美团以“零售+科技”的战略践行“帮大家吃得更好，生活更好”的公司使命。自2010年3月成立以来，美团持续推动服务零售和商品零售在需求侧和供给侧的数字化升级，和广大合作伙伴一起努力为消费者提供品质服务。2018年9月20日，美团在港交所挂牌上市。美团始终以客户为中心，不断加大在新技术上的研发投入。美团会和大家一起努力，更好承担社会责任，更多创造社会价值。', 'https://www.zhaopin.com/jobdetail/CC383625320J40659198109.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5028, '大客户代表', '上海微谱检测科技集团股份有限公司', '7月25日', '1-2万·13薪', '杭州-滨江区', '检测/认证,检测/认证,医疗检测,化工', '1000-9999人', 'C轮', 'CC383669810J40753252605', '【工作内容】<br>1、负责公司业务拓展。老客户的维护和跟踪，新客户的开发； 2、主要对接客户是医药/医疗器械研发企业，负责医药/医疗器械研发全生命周期涉及的检测服务对接，入职会有专业培训；', '微谱，大型研究型检测机构。始于2008年，公司总部位于上海，在广州、深圳、北京、青岛、济南、苏州、南京、杭州、宁波、成都、武汉和长沙等地设立有分子公司，拥有化学、材料、机械物理、可靠性、食品、环境、医药、微生物、动物安评、化妆品功效评价等多个专业实验室。微谱具备市场监督管理局授权的CMA资质和中国合格评定认可委员会认可的CNAS资质，被认定为国家中小企业公共服务示范平台、高新技术企业、院士专家工作站等。基于十多年的专业技术积累和遍布全国的服务网络，微谱每年出具近十万份技术报告，累计服务客户八万多家，其中世界五百强客户近百家。微谱始终秉承“服务，不止于检测！”的服务理念，为客户提供专业的分析、检测、测试、研究开发、法规咨询等技术服务：工业技术领域：高分子材料及精细化学品：成分分析、结构解析、异物分析、失效分析、理化性能测试及可靠性检测等；汽车零部件及材料，电子通讯产品，轨交交通及工程，航空航天领域：环境可靠性能检测、失效分析、机械物理性能检测等；有害物质检测：RoHS、REACH、SVHC、VOC检测及气味评价与溯源等；金属材料牌号鉴定、失效分析、机械物理性能检测等；油品及润滑产品：理化性能检测、油液监测等；农药/兽药：理化检测、原料杂质研究、制剂全组分研究、晶型、交叉污染等研究性检测……生态环境领域：二噁英专项检测及减排技术咨询；土壤、地下水及场地调查检测；危废专项检测；非标方法开发与验证；……化妆品及消毒产品领域：化妆品及原料成分分析、禁限用物质检测；护肤品、口腔产品、发用产品及防晒产品的人体/体外功效评价、安全性评价；进口/国产化妆品、特殊化妆品、非特化妆品、消毒剂的备案及法规服务；多国化妆品法规准入咨询；……食品、农产品及畜牧领域：食品安全检测：农残、重金属、兽残、微生物、抗生素、真菌毒素、二噁英等有毒有害物质检测；食品及特殊食品营养成分检测、功效成分检测、风味物质研究；饲料检测，食品接触材料检测，植物油的鉴别分析，食品违禁物质筛查，食品添加剂成分分析；……生物医药领域：药品接触材料及药物与包材相容性研究，包材密封性完整性研究；基因毒、残留溶剂、元素等药品杂质的研究及分析测试；化学药特性鉴定，结构确证，辅料全检，微生物测试；原研制剂逆向工程研究；生物大分子结构确证及分析检测；医疗器械领域：研发材料测试、化学表征、可沥滤物研究、毒理学风险评估、体外降解实验、动物实验；……', 'https://www.zhaopin.com/jobdetail/CC383669810J40753252605.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5029, '日语翻译', '天津才智企业管理咨询有限责任公司', '7月14日', '8000-10000元', '天津-滨海新区', '电子商务', '100-299人', NULL, 'CC486767080J40827016915', '一、岗位描述：<br>1.通过接听电话，解决日本地区顾客或卖家的相关问题（售后/物流/订单），向客户提供支持及解决方案；<br>2.收集客户投诉以及意见，并及时回复投诉问题，并向上级主管汇报客户意见；<br>3.对应上级主管安排的其他业务。<br>二、职位要求：<br>1.具有较强的日语沟通能力，N1或同等水平，听说读写流利，无明显口音；<br>2.掌握敬语、商务日语，具备以日语为工作语言的能力；<br>3.可接受应届毕业生，有客服行业经验或留日经验优先。<br>福 利：提供宿舍、五险一金、晚班补贴、带薪培训、餐补、年假、节假日福利、定期团建。', NULL, 'https://www.zhaopin.com/jobdetail/CC486767080J40827016915.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5030, '招聘专员/助理', '常州捷登人力资源有限公司', '6月17日', '1.1-1.4万', '苏州-吴中区', '人力资源服务', '20-99人', NULL, 'CCL1481302610J40681175606', '工作内容<br>在58.BOSS上发布招聘信息，打电话邀约面试<br>1.底薪4000+房补1000+餐补800+全勤500+10%-20%提成综合6300+<br>2.50%提成<br>提成综合薪资6000-15000以上<br>每月底发工资。<br>2、工作时间8:30~-18：00<br>做六休一，正常节假日都放假', '内容：郑重声明入职绝无任何费用请放心报名本公司当天面试当天安排住宿加班费：正常工作时间（8小时/日）以外的劳动时间均算加班时间。每月10号准时发工资【招聘要求】4、面试时必须要有身份证原件【伙食及住宿】1、伙食：提供一日三餐，四菜一汤、米饭、，另有水饺、拉面、砂锅、油饼、面包、鸡蛋2、住宿：提供4-6人间宿舍，配备独立卫生间、空调、、网线、衣柜、、24小时热水、洗衣房等一应俱全', 'https://www.zhaopin.com/jobdetail/CCL1481302610J40681175606.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5031, '售后客服', '艾斯欧艾斯信息科技有限公司河北分公司', '7月11日', '6000-8000元', '石家庄-桥西区', '运营商/增值服务,运营商/增值服务', '100-299人', '已上市', 'CC856020830J40579352104', '工作内容：针对在水滴平台的客户，加企业微信做后援增值服务，发线上产品资料做产品推广，电话或者微信协助客户购买，产品升级  薪资：实习无责3000+绩效提奖', '艾斯欧艾斯信息科技有限公司，于2016年03月02日注册，注册资本5000万，是一家通过卫星通信，互联网，电话，短信，APP，微信等多种技术手段利用云平台为用户提供医疗，汽车，安全，互助，金融，生活等方面国内，国际全方位紧急救援服务的高新技术企业。我们的服务理念：“关注随时随地，满意无处不在，SOS您的守护人”通过“smiley(微笑)、sincere(诚挚)、s pecialized(专业)、speedy(快速)、satisfied（满意）和superior（卓越）”为我们客户提供一流的救援服务。艾斯欧艾斯秉承的文化“服务、高效、责任、诚信、创新、专业、感恩、共赢”。具体为：服务-服务别人，造就自己，高效-节约时间等于创造财富，责任-是使命、是担当、是付出、是能力；诚信-以诚待人、以信取人，创新-学习、积累、突破；专业-因为专一所以专注,因为专注所以专业；感恩-感恩于心、从我做起；回报于行、从小事做起；共赢-合作共赢、开放智慧、相互扶持、团结协作、创造未来。', 'https://www.zhaopin.com/jobdetail/CC856020830J40579352104.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5032, '商务专员', '吉林健坤通讯设备有限公司', '7月14日', '3000-4000元', '长春-朝阳区', '通信/网络设备', '20-99人', NULL, 'CCL1484332260J40686656512', '工作内容：<br>1. 商品出库入库；<br>2. 商品价格表、利润表及库存表整理。<br>3. 物流跟踪到货；<br>4. 沟通门店库存，安排商品门店分配；<br>5. 监控门店间调货；<br>6.外部客户结算回款；<br>7.线上系统下单，沟通财务打款；<br>8.领导安排的其他工作。<br>任职要求：<br>1. 工作积极主动，认真负责；<br>2. 充满正能量；<br>3. 沟通表达能力强；<br>4. 五官端正。<br>工作时间：9:00-17:30<br>工作地点：人民广场安华大厦<br>薪资待遇：试用期1-3个月3500元，转正后基本工资3300+（300-500）奖金', NULL, 'https://www.zhaopin.com/jobdetail/CCL1484332260J40686656512.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5033, '风电工程师', '深圳市创世纪科技发展有限公司', '7月24日', '1-1.4万·13薪', '阳江-阳东区', '计算机软件,IT服务,互联网,计算机硬件', '300-499人', '未融资', 'CC321869010J40803928413', '职责：  1、根据项目经理室统一安排，进行阳江帆石一海上风电项目风机吊装施工工作；  <br>2、施工过程中组织上游单位进行相关质量点见证和验收。  <br>3、相关会议材料、纪要、公文撰写；  <br>4、工作范围内施工安全管控；  <br>5、领导安排的其他工作', '深圳市创世纪科技发展有限公司是一个专门从事企业信息化工程建设应用软件开发、集成技术；社区、楼宇智能化工程服务供应商。公司拥有一支从事软件开发10多年，作风过硬、素质优秀、技术精湛、经验丰富的软件开发和系统集成队伍。公司注重：“具有行业特色；满足个性化需求；适应企业文化、资源和持续发展”的企业信息化目标产品的研究。现已为多家企业开发出具有行业特色的软件；在企业的信息管理系统上具有丰富的经验。同时，我公司对工业生产数据具有较强的处理能力，善于整合离散的工业数据，对数据进行分析处理；为企业的生产过程提供决策支持和控制，提高企业的生产能力。对在线系统运行分析，积累了丰富的经验。近几年来，公司在智能化系统工程、计算机网络通讯、工业自动化控制、通信技术也积累的丰富的实践经验。依托现有的人才与先进技术，以及与知名地产开发商的合作关系等综合优势，积累了专业施工管理经验，结合小区智能化，智能大厦，计算机网络系统，在建设数字化社区方面取得了长足的进步。随着公司业务的调整和发展，我们长期向一些集团公司提供软件技术支持，项目建设，企业信息中长期规划与咨询等业务。所聘相关职位，会提供您中长期的职业规划机会，并提供足够发展空间,欢迎优秀人才加入。', 'https://www.zhaopin.com/jobdetail/CC321869010J40803928413.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5034, '培训师', '石家庄法商中等专业学校', '6月29日', '4000-8000元', '石家庄-桥西区', '学校/学历教育', '100-299人', '不需要融资', 'CC300846410J40771876414', '建筑任课教师<br>一、岗位要求<br>1、热爱教育工作，具有良好的思想道德素质和团队协作精神。有较强的教育工作能力、教学能力与科研能力。<br>2、本科及以上学历。<br>3、专业要求：建筑相关专业，能胜任建筑等相关专业课程的讲授。<br>4、熟悉对口升学相关知识的优先。<br>二、工作职责<br>1、遵守国家法律法规和学校的各项规章制度，遵守教学工作纪律和教学管理规范，服从工作安排;<br>2、服从学校安排，完成学校分配的各项任务:<br>3、掌握教学需要的专业理论、基础知识和基本技能:<br>4、能够指导学生参加各类技能比赛，积极参加各种教学比赛和技能竞赛;<br>5、热爱学生，诲人不倦，关心学生全面发展，为人师表，教书育人;', '学校概况石家庄法商中等专业学校隶属于法商教育集团，其前身是河北工程技术学院（原石家庄法商职业学院）中专部，２００７年经石家庄市教育局批准设立为的全日制中等专业学校，毕业后还可获得岗位职业证书和通过职教高考取得高等教育学校学历证书。学校秉承“以人为本，关爱学生，培养学生，发展学生”的办学宗旨，在“崇德、尚能、求实、创新”的校训指导下，全体师生践行着“理论为精、实践为重、技能为先、人格为本”的办学理念，明确了“以服务为宗旨，以就业为导向”的发展方向，从而逐渐形成了适合我校的“办学以市场为中心，教育以学生为中心，教学以质量为中心，工作以绩效为中心”的独特发展思路。学校发展强化三个重点：学生管理以“被受管理向自主管理转型”为重点，教学模式改革以“依托专业办产业、依托产业促专业”为重点，学生就业以“送得出，用得上，稳得住”高对口性就业为重点。经过全体法商人的不懈努力，学校无论是在办学规模、办学条件、还是师资力量、管理水平，都取得了优异的成绩，受到了各级教育部门的高度认可，在河北省均名列前茅，为学校实现更大的发展奠定了良好的基础。2014年，学校被河北省教育厅评为河北省重点中职学校，被河北省民政厅评为国家“5A级社会组织”单位。学校还被评为石家庄市十大品牌学校，石家庄市优秀学校。学校发展迅速，目前已拥有四个校区，校区总占地面计400余亩，拥有专兼职教师350余人，其中双师型教师占比31%，在校学生8000余人。近年来，学校为进一步提升教育教学质量，根据专业设置累计投资2000余万元，建立了校内三大教学实训中心：以计算机网络中心、电子竞技实训室、客房实训室、餐饮实训室、会计实训室、建筑实训室组成的第一实训中心；以数控金工实训室、汽修综合实训室、建筑模拟项目部、无人机模拟实训室组成的第二实训中心；以蒙台梭利、奥尔夫音乐活动室、形体实训室、声乐实训室、钢琴实训室、美工实训室、数字电钢琴实训室、美容美体实训室、航空实训室组成的第��实训中心。标准化塑胶运动场、篮球场、羽毛球场和乒乓球台等体育设施齐全。为适应职业教育发展的需要，根据国家深化产教融合、校企合作的要求，结合职业教育的办学特点，学校以“依托专业办产业、依托产业促专业”的原则，通过“外引内投”的方式，创建教育教学实训基地。学校投资创办了“6所贝斯特双语幼儿园”、“贝斯特国际早教中心”“斯麦尔时尚快捷酒店”“石家庄昆仑汽车服务有限公司”等实习实训基地。', 'https://www.zhaopin.com/jobdetail/CC300846410J40771876414.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5035, '广告销售', '青岛辉科胜邦自动化装备有限公司', '7月24日', '4000-5000元', '青岛-李沧区', '仪器仪表制造,工业自动化', '20-99人', '未融资', 'CC878745430J00169652010', '岗位职责：', '青岛辉科胜邦自动化装备有限公司位于山东省经济发展龙头地位的海滨城市青岛，是一家专业致力于机、电、液等传动工控产品的生产、销售为一体的专业技术型公司，是一家集工业自动化产品代理销售、系统集成、技术咨询、产品维修、工程实施的专业公司。可为客户提供一体化的解决方案。我公司是深圳市汇川技术股份有限公司（股票代码：300124）山东地区一级核心代理商，代理汇川技术旗下变频器、伺服、PLC、HIM、直驱电机、电液伺服等全系产品，为中国境内的企业提高自动化装备水平，节能降耗,工程改造服务，深受广大用户好评和肯定。', 'https://www.zhaopin.com/jobdetail/CC878745430J00169652010.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5036, '律师助理', '北京允安律师事务所', '7月8日', '4000-5000元', '北京-朝阳区', '法律服务', '20-99人', '不需要融资', 'CC428850830J40638092902', '岗位职责： 1、民商事领域案件，整理谈话笔录、业务资料、文书证据等开庭前诉讼材料; <br>2、跟进案件，辅助律师开庭，协助建立客户档案、整理案卷资料并完成已结案件的装卷等工作; <br>3、非诉业务的准备工作，包含但不限于文书、合同等编写及审核工作; <br>4、部门内部的部分内业工作; <br>5、部分客户线索跟进，协助促成成交。', '北京允安律师事务所成立于2015年，位于北京市朝阳区。律所宗旨：“求实、敬业、优质、高效”，以专业化、现代化及协作精神作为发展的基础；贯彻忠实于当事人委托、全面维护当事人合法权益的执业理念，确保法律的公正实施。', 'https://www.zhaopin.com/jobdetail/CC428850830J40638092902.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5037, '电话销售', '作业帮', '7月25日', '1-1.5万', '郑州-金水区', '互联网,互联网', '10000人以上', 'D轮及以上', 'CC287198080J40780722214', '【最真实的薪资情況】：<br>试用期和转正薪资一样！没有差别！<br>无责5950，底薪4500（含500餐补）+培训150×3+新人保底绩效1000（前俩月），底薪餐补一直有不受绩效影响<br>带班后50%以上的薪资在12000左右，上不封顶<br>超长年假！法定节假日正常休，下班企业滴滴每天最高可支付打车65元，无需报销直接支付。', '作业帮成立于2015年，作为“数字教育的开拓者”，以“科技为人、成就非凡”为使命，致力于用科技手段助力教育普惠。作业帮始终坚持“教育+科技”双引擎战略，在学习工具产品、智能硬件、智能图书等业务领域深入布局。作业帮是“国家高新技术企业”、教育部认定的“中国暨中关村独角兽企业”、德勤“高科技高成长中国50强”、“全球独角兽企业500强”，入选“福布斯中国最具创新力企业榜”。', 'https://www.zhaopin.com/jobdetail/CC287198080J40780722214.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5038, '项目专员/助理', '西安慧澜语言科技有限公司', '7月22日', '6000-8000元', '北京-海淀区', '人工智能,翻译服务', '100-299人', '未融资', 'CCL1486546170J40773849202', '岗位职责：<br>1.项目全流程管理：覆盖售前、售中、售后阶段，把控项目关键节点，跟进计划落实，处理延迟及风险，确保按时保质交付。<br>2.客户支持与维护：理解客户需求，负责试标、大项目启动管理，收集反馈并处理投诉，维护客户关系，保持与大客户的紧密沟通。<br>3.业务推进：推动业务高效运转，分析项目数据挖掘改进空间<br>4.质量保障与改进：进行质量检查与抽检，分析质量数据，推动流程优化和持续改进。<br>5.前后端的沟通配合：合理调配项目经理，保证项目交付质量和时间。<br>6.数据分析：分析下单、签单、试标等运营数据，通过数据呈现识别潜在风险并预警，为业务决策提供支持。<br>岗位要求：<br>1、本科及以上学历，英语相关专业或英语六级及以上；<br>2、工作态度认真负责，能够随时响应部门需要；<br>3、热爱翻译/出版行业，且职业规划与此相符；<br>4、工作细心、服从上级领导安排，自驱力强；<br>5、熟悉office办公软件的使用，对数据敏感，逻辑思维强', '慧澜国际是一家一站式综合性解决方案提供商，公司成立于2021年，立足于语言服务产业，多元化经营发展，目前服务内容已经涉猎翻译服务、数据服务、出版服务、职教出海四大板块业务，且经过多年发展已经在国际工程、智能制造、国防军工、生命科学、文化出版、科技互联网等多个行业领域中形成了完备的一站式数据+语言+出版+出海的解决方案。公司秉承着“以客户为中心”的核心价值观，“自驱型奋斗者”的用人理念，“高效感，充实感，危机感”的三感发展文化，“利他精神，达人成己”的团队协作精神，经过近几年的快速发展，目前规模已经达到1家总公司，3家分公司，6个海外交付中心的规模，国内外员工数百人，近千人的行业专家库，累计服务客户数量已经超过1500家。“始于翻译，不止于翻译！”是公司的经营理念，“千里之行始于足下”未来的慧澜国际将一如既往的发扬艰苦奋斗精神，努力争先，持续深化产品服务结构，深入拓展行业解决方案能力，为政府机构，社会组织，企事业单位的AI应用发展与全球化发展保驾护航！公司处于高速发展阶段，诚邀优秀人才加入！公司官网 https://www.intelwave.cn/', 'https://www.zhaopin.com/jobdetail/CCL1486546170J40773849202.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5039, '游戏运营', '恒安集团', '7月25日', '4000-6000元·13薪', '郑州-金水区', '快速消费品', '10000人以上', '已上市', 'CC000405330J40740778205', '【岗位职责】：', '恒安集团创立于1985年，目前是国内最大的卫生巾、纸尿裤和生活用纸生产企业，拥有总资产115多亿元，员工两万余人。在全国14个省、市拥有30余家生产公司，200多家商贸经营部/办事处，销售和分销网络覆盖全国。在2009年《亚洲周刊》公布的全球华商排名1000强名单中，恒安集团排名第129位，并入选“2006CCTV中国年度最佳雇主”第22强、2007年度福布斯杂志评选的“亚洲中小企业上市前十强”。恒安国际集团有限公司于1998年在香港成功上市（代码：1044.HK）。恒安集团以多个家喻户晓的品牌商标“安尔乐”，以及“安乐”、“安儿乐”、“安而康”“心相印”等著名品牌为依托，生产与销售100多个规格、品种的妇女卫生巾、婴儿纸尿裤和成人纸尿裤及“心相印”高级纸巾系列。“安乐”、“安尔乐”卫生巾，“安儿乐”婴儿纸尿裤，“心相印”纸巾三大系列产品市场占有率连续多年居全国同行第一。2002年，“安乐”、“安尔乐”系列产品被国家质量监督检验检疫总局授予“国家免检产品”称号。恒安集团的主要生产设施和产品均已获得ISO9002质量体系和产品质量认证。2001年，恒安巨资聘请世界著名的管理咨询公司——美国汤姆斯（THOMAS GROUP）集团进驻企业，引进世界先进管理经验，在人力资源、市场营销、供应链管理、财务管理等进行深层次、全方位推进企业管理和变革，以适应新形势竞争的需要，建设真正以消费者和市场为导向的公司，同时，坚持“以人为本、德才兼备”的用人理念，以“诚信、拼搏、创新、奉献”的企业精神为指引，迈出打造“百年恒安”的坚实步伐。目前，恒安集团在山东、晋江等地总投资近20亿人民币的几个大项目正在紧锣密鼓地进行。恒安在发展过程中，始终不忘企业对社会的责任，累计捐款数千万元，积极参与社会公益事业，回报社会的关心和支持。加盟恒安，您将和我们一起学习世界先进的管理理念！一起体验成长的喜悦！一起分享成功的果实！', 'https://www.zhaopin.com/jobdetail/CC000405330J40740778205.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5040, '电话客服', '湖南基数电子商务有限公司', '7月18日', '4000-8000元', '长沙-岳麓区', '互联网,IT服务', '100-299人', '未融资', 'CC268210630J40275015502', '工作内容：', '湖南基数电子商务有限公司简介：公司于2015年在长沙注册成立，是一家以运营商5G业务为核心的互联网企业。公司分为三大业务模块：1.移动、联通、电信的存量经营，客服外包号码承销，手机包销业务。建有多个呼叫中心，职场面积超千平米，坐席超200人。2.电商代运营：公司是京东授权服务商，主要为企业在京东开展业务提供店铺代运营，供应链金融服务。3.软件系统开发与运营：公司拥有成熟的软件开发团队，自主开发“异业联盟系统”为同城企业实现异业联盟，联合促销，提供解决方案及系统支持公司愿景：创新商业模式，构建立体化营销服务能力，让品牌与消费者共舞。核心价值观：以贡献价值为核心，员工价值优先于企业实现，客户价值优先于企业实现，合作伙伴价值优先于企业实现。公司福利：五险、法定带薪休假、餐补、包住、生日礼品或礼金、团建活动等。', 'https://www.zhaopin.com/jobdetail/CC268210630J40275015502.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5041, '总助/CEO助理/董事长助理', '浙江瑷尔德投资管理有限公司', '5月21日', '7000-10000元', '青岛-市南区', '证券/期货', '20-99人', '不需要融资', 'CC313780630J40851814104', '1.参与与券商合作的尽调报告撰写<br>2.执行公司产品的推介、发行等工作<br>3.掌握基金结构、法律合规等方面知识<br>4.领导交办的其他工作任务。<br>职位要求：<br>1.熟练掌握WPS office等办公软件<br>2.须考取基金从业资格证书<br>3.稳重、做事认真有责任心。<br>4.适应出差应酬，对酒量有一定的要求。', '浙江瑷尔德投资管理有限公司（简称“瑷尔德”）是一家专业的私募基金机构，基金业协会登记编码P1025781。公司成立于2015年9月25日，注册资本1000万，实缴资本1000万，旗下基金：30只，目前管理规模6个亿左右。致力于在ETF市场寻求稳健投资机会，业务涉及ETF高频套利、ETF复合量化、ETF量化权益等各类业务。', 'https://www.zhaopin.com/jobdetail/CC313780630J40851814104.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5042, '广告销售', '苏州顺康鑫智能装备有限公司', '6月27日', '4000-8000元', '苏州-吴中区', '环保,专用设备制造', '20-99人', '未融资', 'CC379001810J40750608809', '岗位内容：', '我们是一家集产品智能制造、项目投资建设为一体的企业。从事的业务包括两个板块：能源板块：天然气项目的投资、建设、运营，氢能装备的制造及天燃气掺氢项目投资建设；厨安板块：为厨房安全提供整体解决方案，解决方案包括厨房自动灭火装置、蔬果农残降解机、餐具去油污机、灭菌餐盘的研发、生产、销售、售后。我们团队平均年龄38岁，大专以上学历占比75%，我们拥有专业的技术研发团队及售后维护团队，可以为客户提供专业的定制化服务，同时在服务的过程中始终以客户需求为导向，不断优化、升级我们的产品，为客户创造价值是我们一贯的方针和原则。我们拥有标准化的厂房，并获得了安全标准化生产三级证书；作为江苏省认定的科技型民营企业，我们始终将技术创新作为核心驱动力，我们拥有厨房灭火设备及净化器的多个发明专利及实用新型专利，获得江苏省科技型民营企业的殊荣，拥有燃气工程总承包资质及压力管道GB1、GC2证书；同时我们获得了质量体系认证、环境体系认证及职业健康体系认证。', 'https://www.zhaopin.com/jobdetail/CC379001810J40750608809.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5043, '律师助理', '新疆赛天君祥法律咨询服务有限公司', '6月24日', '3000-6000元', '乌鲁木齐-新市区', '法律服务,企业服务', '20-99人', '不需要融资', 'CCL1241617910J40570998601', '职位描述', '赛天赔偿法律服务团队专注于交通事故赔偿、保险赔偿、工伤赔偿、人身损害赔偿，有疑难、复杂、重大交通事故办案经验。在新疆乌鲁木齐、喀什、甘肃兰州、四川成都设立赔偿团队。公司、律所有最佳的办公环境、良好的工作氛围、丰富的业务知识培训，诚邀有志之士的加入！赛天赔偿法律服务团队打破传统律师打官司环节为重心客户服务痛点，努力实现案件最大利益化，根据案件需要在团队中设置事故专员，解决事故责任划分专业化；设置鉴定专员，解决伤残鉴定专业化；案管专员、案管客服、执行专员等多对一服务模式，在批量案件中案件流程化、专业化；实现高效、高质量法律服务。赛天赔偿法律服务团队依托法律咨询服务有限公司、律师事务所共同完成案件服务，创造人身赔偿法律服务新模式。赛天法律服务赔偿团队愿景文化：爱心责任心同情心赛天法律服务赔偿团队愿景：聚焦专业法律服务赛天法律服务赔偿团队使命：让每一位受害人都能有尊严的拿到赔偿款。网址：www.xjls122.com www.xjbxls.com www.xjjtsg.com公众号：新疆交通事故律师新疆专业保险理赔律师小程序：新疆专业交通事故团队公司地址：新疆赛天君祥法律咨询服务有限公司新疆乌鲁木齐新市区苏州路568号金邦大厦 18楼赛天君祥法律咨询服务有限公司成都分公司成都市青羊区温哥华广场1402赛天君祥法律咨询服务有限公司兰州分公司甘肃省兰州市城关区东岗东路2704号万商国际A塔10层1009室', 'https://www.zhaopin.com/jobdetail/CCL1241617910J40570998601.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5044, '招聘专员/助理', '吉林省蓝青蛙劳务派遣有限公司', '4月10日', '5000-8000元', '长春-榆树市', '人力资源服务', '100-299人', '未融资', 'CC418019230J40776224103', '工作地点在长春， 工作内容：联系主动投递简历的求职者，介绍工作内容 工作时间：8小时，双休 薪资：日结+提成+满勤+绩效+补助=7000-8000', '吉林省蓝青蛙劳务派遣有限公司是由吉林省人社厅批准从事经营劳务派遣、人力资源等服务的企业，公司实缴注册资金200万元，并已通过ISO9001质量管理体系认证,是一家专业为企业提供劳务派遣、劳务外包、人力资源的供应商。蓝青蛙是一家具备现代企业管理制度和服务意识的专业人力资源服务企业。现设有市场运营部、猎头部、人力资源部、办理用工手续、保险缴纳、保险理赔、工社会保障部、综合办公室、财务部等部门，其中汇聚了多名来自省内知名企业、劳动保障部门的资深人力资源管理专家。并在烟台、吉林市、延吉等地设有分公司及办事处。蓝青蛙为企业提供的服务包括：劳务外包、劳务派遣、劳动仲裁委托、社保代缴等人事外包服务。其中所涉及的服务项目包括了：与员工签订劳动合同、资计算发放、退工手续办理等相关的人事服务。', 'https://www.zhaopin.com/jobdetail/CC418019230J40776224103.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5045, '储备经理人', '中国平安人寿保险股份有限公司兴安盟中心支公司', '7月25日', '8000-16000元', '兴安盟-乌兰浩特市', '保险', '100-299人', NULL, 'CC560508220J40784984612', '嘿，未来的管理者！我们正在找你！<br>想要了解公司的每一个角落，每一个团队如何协同工作吗？作为储备经理人，你将有机会深入体验并学习！<br>你的冒险包括：<br>- 轮岗实习，探索不同的部门；<br>- 与大咖管理团队面对面交流；<br>- 实战参与项目，感受团队的力量；<br>- 参加超酷的培训，技能up up！<br>如果你：<br>- 是本科及以上学历的小伙伴；<br>- 善于沟通和组织；<br>- 热爱学习，有责任心；<br>- 对管理有着浓厚的兴趣；<br>那么，别犹豫，加入我们吧！', NULL, 'https://www.zhaopin.com/jobdetail/CC560508220J40784984612.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5046, '储备干部', '百胜餐饮(武汉)有限公司', '7月26日', '3000-4000元', '黄冈-黄梅县', '快速消费品,餐饮服务', '10000人以上', '已上市', 'CC191713920J40735618701', '工作内容：<br>1、餐厅轮岗学习：顾客服务、产品制作等。时长：2月。<br>2、楼面管理：生产管理、品质管理、收货管理、服务管理。时长：2月。<br>任职条件：<br>1、乐于从事餐饮服务工作，并有意愿成为连锁零售行业管理者；<br>2、①沟通表达：有谈吐，不怯场 ②组织协调：员工关系处理 ③适应抗压：三班倒，早起晚归 ④服务意识：以顾客为中心<br>⑤领导力：能服众，有个人魅力<br>3、大专或以上学历；<br>4、更倾向于20-28岁的伙伴。<br>5、无论是否拥有餐饮工作经验，均可投递简历；<br>百胜的优势：<br>【公司介绍：稳定】全国超1万家门店，门店数量、岗位需求持续增加，无晋升天花板；<br>【社保福利：完善】入职就交6险1金，带薪年假10天起步，享有覆盖本人及子女的商业医疗保险；<br>【规范用工：双休】每周双休（轮休制），每天工作8小时，早中晚轮班，工作时间灵活；<br>【发展晋升：公平】储备经理—副经理—资深副经理—餐厅经理—区经理—区域经理；<br>【学历提升：方便】在职员工即可加入开放大学计划，提升学历，注重员工个人持续性发展；<br>【工作环境：温馨】餐厅空调、微波炉、无线Wifi、员工休息室，让工作环境更温馨；<br>【团队活动：丰富】餐厅团建、品牌年会、公司尾牙等活动让企业文化更浓郁；<br>【工作薪酬：准时】综合月薪3400元/月+季度奖金，国家法定节假日额外3倍工资。<br>【个人及职业发展】：<br>1、 储备经理是向餐厅经理快速发展的基础职级。通过体系化技能培养以及入职后一对一导师辅导能力提升，每年多次晋升考核机会，100%内部晋升机制，从而独立管理一家百胜餐厅。<br>2、职位晋升路径：储备经理—副经理—资深副经理—餐厅经理—区经理—区域经理<br>3、通过不断地培养和学习，未来你将能够在品牌经营、品牌创新、利润管理、绩效管理等商业经营核心能力上，具备行业领先的经验及能力。<br>4、年轻的工作伙伴，轻松自在的团队氛围，没有距离感的管理风格，能够让你在百胜大家庭快乐成长。', '百胜中国控股有限公司致力于成为全球餐饮先锋。自从1987年第一家餐厅开业以来，截至2019年9月底，百胜中国在大陆的足迹遍布所有省市自治区，在1300多座城镇经营着8900余家餐厅。百胜中国从Yum! Brands（纽约证券交易所代码：YUM）分拆出来之后，于2016年11月1日独立在纽约证券交易所上市，股票代码为YUMC。百胜中国在中国市场拥有肯德基、必胜客和塔可贝尔三个品牌的独家运营和授权经营权，并完全拥有东方既白、小肥羊和COFFii& JOY连锁餐厅品牌。经过三十年的发展，我们不仅在店面数量，而且在品牌知名度、社交及数字媒体营销和传播、全国供应链管理、产品质量、以及创新方面都已经成为了一家中国优秀餐饮企业。百胜中国超过45万的员工是我们发展的支柱，与此同时，在百胜积累了经验丰富的管理团队和全情投入的前线伙伴也正在续引领发展活力充沛、直面机遇、和充满欢乐的企业文化。在肯德基原味炸鸡等产品的基础上，我们还不断开发符合当地口味的产品，从而建立起强有力的顾客忠诚度。我们每一个品牌都有其专属产品，很多都是中国本土创新，同时我们也研发出众多独有产品与调味产品，为消费者提供美味便捷并且高品质的食物。通过在中国多年的发展与积累，我们已拥有深厚的消费者知识与忠诚度，各品牌的产品也已成功融入流行文化与消费者的日常生活之中。我们将通过创新产品、提升就餐体验、增强移动连接、以及持续创造价值来满足消费者不断改变的需求。百胜中国对于未来长期的发展充满信心。', 'https://www.zhaopin.com/jobdetail/CC191713920J40735618701.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5047, '销售工程师', '哈尔滨现岱智能装备制造有限公司', '7月24日', '5000-10000元', '哈尔滨-松北区', '专用设备制造,电气机械/电力设备,通用设备制造,仪器仪表制造', '100-299人', '未融资', 'CCL1276253170J40152867613', '任职资格<br>  <br>年龄：40岁以下<br>  <br>专业要求：热能，机电一体化、锅炉等相关专业，能适应经常出差，有良好的沟通谈判能力，学习能力及执行力较强，抗压性强<br>', '哈尔滨现岱智能装备制造有限公司位于哈尔滨市松北区智谷大街288号深圳（哈尔滨）产业园区科创总部1号楼，厂房地址为哈尔滨市松北区智谷大街4509号4号厂房，厂房面积7100余平方米，成立于2020年7月28日，其前身是哈尔滨现代吹灰技术有限公司成立于2001年，是一家致力于各种锅炉吹灰领域的研发、生产、销售的高科技企业——脉冲燃气吹灰器的专业生产厂家，公司成立二十余年来，产品遍布全国各地，在国内同行业中位居前列。市场成熟，口碑极佳。公司集科研、生产、销售于一体，有宽广的生产厂房及办公楼，规范的管理体系、守信的高科技民营企业。公司为新员工提供带薪培训。公司的目标是不断超越已有的成绩，为员工搭建高层次的发展平台，做员工坚实的后盾，是公司的每位员工都有归属感和成就感。成为公司的一员定是你不悔的选择。为员工提供可晋升的薪酬待遇以及五险、双休、法休、通勤车、午餐等。由于公司已扩大生产规模，诚聘以下人员：', 'https://www.zhaopin.com/jobdetail/CCL1276253170J40152867613.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5048, '日语翻译', '新宇智慧', '7月23日', '1.5-3万·13薪', '上海-徐汇区', '互联网,学术/科研,咨询服务,培训/辅导服务', '100-299人', '未融资', 'CC227023580J40867656215', '岗位职责: 1.负责制定并执行销售目标及策略，完成年度、季度销售业绩目标；', '深圳新宇智慧科技有限公司，前身为深圳市立创翻译有限公司。是翻译行业领先的语言技术解决方案的供应商。我们为国际化公司、政府、个人提供全方位的多语言服务以及相关的技术解决方案和服务。帮助客户在国际市场上获得成功。我们以客户的需求为导向，聚焦在语言领域不断创新，精益求精，使公司始终处于行业前沿。公司总部设在具有中国珠三角“曼哈顿”美称的深圳前海经济开发区，在合肥设有制作中心，北京、香港设有分公司，同时在上海、剑桥设有办事处。深圳市立创信息系统有限公司（公司网址：http://www.hkgsl.com)公司福利：周末双休，带薪年假，五险一金，节日福利，专业培训，立即上岗，弹性工作，员工旅游，英语角等公司理念：“客户为先、员工为本、精诚服务、追求卓越”公司愿景：“客户全球化最佳合作伙伴”', 'https://www.zhaopin.com/jobdetail/CC227023580J40867656215.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5049, '售后客服', '中国人寿保险股份有限公司佛山市西樵支公司', '3月4日', '6000-12000元', '佛山-禅城区', '保险', '1000-9999人', '已上市', 'CC277461080J40713556005', '1、上班时间：8:30-10:30，10:30后时间自由安排，方便照顾家庭，宝妈也有自主赚钱机会！！<br>2、经验不限，公司有大量资源和系统培训，可以把新手迅速培养成赚钱高手。<br>3、入司即开设养老金账户，每月按个人、公司1:1比例缴存，全透明的晋升机制和提成规则，人人平等，多劳多得，能者晋升，不设封。<br>4、中专高中学历：服务津贴3000+新人津贴+佣金+奖励<br>大学大专以上：服务津贴4000+新人津贴+佣金+奖励，轻松月入过万', '感恩，自律，创新，超越', 'https://www.zhaopin.com/jobdetail/CC277461080J40713556005.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5050, '法务专员/助理', '正德人力资源股份有限公司', '7月28日', '7000-9000元', '合肥-蜀山区', '互联网', '10000人以上', '未融资', 'CC202766620J40783642614', '工作内容<br>1、审阅、起草、修订劳动合同等文件<br>2、建立健全劳动合同管理<br>3、为公司的合法用工提供法律意见或建议职位要求 <br>1、能接受出差 <br>2、需要善于沟通协调', '正德成立于2004年，截止到2019年底，在全国设立了11家子公司，168家分公司，256家办事机构。目前拥有自有员工30000多名，核心业务包括业务外包服务、灵活经营平台、教育培训服务、一站式就业服务、人力资源咨询服务、人事管理服务等，是一家互联网时代的新型服务企业，目前服务的客户包括中国移动、中移铁通、顺丰速运、中国邮政、伊利股份、百世快递、科大讯飞、中煤、北纬通信等国有企业、上市公司.正德公司从事BPO行业十余年，目前在合肥（蜀山电子商务产业园）投资5000余万元建成呼叫物理坐席3000+，并在安徽阜阳、六安、蚌埠、滁州、池州、淮北、淮南、浙江嘉兴、湖州、山西太原、湖北武汉等地区建设分职场，公司运营呼叫坐席累计6000+，公司与安徽移动客服中心、浙江移动客服中心、湖北移动客服中心、新疆移动客服中心、百世快递客服中心、顺丰速运客服中心合作开展中国移动10086纯接听客服、百世快递纯接听客服、顺丰快递纯接听客服及移动外呼等业务。自合作以来，项目一直围绕质量第一、客户至上的原则，秉承一跟到底，事情到我为止的服务宗旨，各项考核数据优异，获得客户方的高度认可。正德全力打造上海运营总部、合肥生产总部两大中心；深耕三大区域中心：长三角、中原、西南，建立强大的服务外包网络、移动互联网络、实体店网络、灵活经营平台，逐步形成“慧联、无界”的融合营销模式，能够实现移动互联网时代对营销模式创新的要求，也能够适应新时代消费者的个性化需求。', 'https://www.zhaopin.com/jobdetail/CC202766620J40783642614.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5051, '律师助理', '北京德恒(福州)律师事务所', '4月24日', '100-200元/天', '福州-台江区', '法律服务,企业服务,专利/商标/知识产权', '20-99人', '未融资', 'CC663925522J00251179201', '北京德恒（福州）律师事务所（以下简称“德恒福州”）是德恒着眼于法律服务本地化的战略，于2012年在福建省福州市设立的直属分支机构。德恒福州纳入德恒全球法律服务网络，接受德恒总所的一体化管理和业务指导、协作。德恒福州成立10余年来，遵循打造高端法律服务综合律所的定位，专注于资本与证券、创投与私募基金、政府与公司事务、工程建设与房地产、金融与保险、并购与重组、企业拯救与破产、诉讼与仲裁、刑事辩护与刑民交叉等法律服务领域。经过多年积淀，德恒福州已成为具有多个核心竞争力业务品牌，管理有序、信誉良好，具有一定影响力和知名度的律师事务所。<br>  <br>', '德恒律师事务所原名中国律师事务中心，1993年1月经中华人民共和国司法部批准创建于北京，1995年更名为德恒律师事务所。德恒在全球设有46个分支机构，拥有160多个境外合作机构，全球员工逾3000人，是一家大型综合性律师事务所。北京德恒（福州）律师事务所是德恒于2012年1月在福建省福州市设立的直属分支机构，现有人员逾70人。德恒福州遵循打造高端法律服务综合型律所的战略定位，经过多年积淀，已成为具有多个核心竞争力业务品牌，管理有序、信誉良好，具有一定影响力和知名度的律师事务所。先后获评“2017-2018年度福建省优秀律师事务所”、“2018-2019年度先进党支部”、\\\\\"2017—2018年度福州市优秀律师事务所\\\\\"等诸多奖项。', 'https://www.zhaopin.com/jobdetail/CC663925522J00251179201.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5052, '培训师', '深圳市冠领月嫂服务有限公司', '2025年07月28日', '1-2万', '东莞-None', '家政服务', '300-499人', '不需要融资', 'CCL1491884630J40797568612', '岗位内容：<br>1. 设计和开发培训课程，包括教材、课件和其他培训材料<br>2. 开展组织内部的员工培训课程，确保培训质量和效果<br>3. 进行培训需求分析和培训评估，不断提高培训质量与效果<br>4. 管理培训计划和预算，并与管理层协调工作<br>任职要求：<br>1. 在人力资源或培训相关领域拥有至少3年工作经验<br>2. 精通培训设计、开发和实施的相关知识和技能<br>3. 能够熟练使用各种培训工具和技术，如在线学习平台等<br>4. 具备团队合作精神和协作能力，良好的沟通能力和解决问题的能力', '我们是一个培训、就业一体的家政公司，负责给年纪大没有学历的哥哥姐姐们赋予专业技能知识，和就业，我们是一个服务平台，我们希望每一个人都有自己的一份工作，有一份自己的收入，我们公司的初衷就是为了给就业困难的人一个工作的机会，期待你的加入', 'https://www.zhaopin.com/jobdetail/CCL1491884630J40797568612.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5053, '项目专员/助理', '广州市凯泽利科技有限公司', '7月23日', '130-150元/天', '广州-花都区', '汽车研发/制造,汽车研发/制造', '100-299人', '未融资', 'CC823999070J40867908315', '凯泽利招聘项目助理（实习生）<br>我们正在寻找一名优秀的项目助理实习生加入凯泽利团队，如果你是本科大四在读学生，渴望在实际工作中积累经验、提升能力，那么这个机会不容错过！<br>岗位基本信息<br>招招聘人数：1 人<br>·      实习性质：全职实习，至少 6 个月以上，一年最好<br>，工作表现好可以转正。<br>岗位要求<br>1.  学历本科，大四在读，熟悉 Office 办公软件，尤其擅长<br>Excel 等工作文档的操作；会开车者优先，男女不限。<br> 工作态度认真负责，积极主动，执行力强，形象良好，且具有强烈的责任心。3. <br>具备较强的逻辑性、沟通表达能力、人际关系处理能力以及突发事件应变能力。<br>4. <br>为人有担当，拥有较好的亲和力，抗压性强，具备良好的团队合作精神。<br>岗位职责<br>1.  负责团队人员考勤、工时、报销等各项数据的整理与核对工作，确保数据准确无误。<br>2. <br>承担团队成员的日常管理工作，保障团队日常运转有序。<br>3. <br>处理团队人员进离场材料、流程等相关事项，同时配合其他部门的工作，以及完成领导交办的其他任务。<br>工作相关信息<br>·       <br>工作时间：早九晚六，中午休息一个半小时，双休，工作生活平衡有保障。<br>·       <br>工作地点：广州市花都区风神大道<br>15 号联友科技有限公司广州分公司，临近地铁站 9 号线花都汽车城 A 口，步行仅 380 米，交通十分便捷。<br>·       <br>薪资待遇：实习工资 3000 元 / 月，另有交通补贴 500 元 / 月，为你的实习生活提供坚实保障。<br>我们期待你的加入，与凯泽利共同成长！', '广州市凯泽利科技有限公司，坐落于广州市天河区，是一家集整车开发与产品设计研发经验于一身的技术服务型企业。公司致力于为客户提供全方位的软件测试流程一站式服务，涵盖汽车技术支持、软件测试委外服务、测试自动化解决方案、嵌入式技术支持、软件开发项目承接、测试辅助工具开发、自动驾驶数据标注、汽车信息安全测试、汽车设计、运营与项目管理、专业培训及工具代理等多个关键领域。在产品研发方面，凯泽利科技自创立之初，便专注于汽车软件测试自动化平台的研发，并成功自主研发出了一款自动化测试平台。该平台采用先进的Web服务器架构，支持Web和Windows两大客户端，具备远程执行测试与监控结果的功能，并实现脚本的云同步。通过该平台，用户可以在办公室内远程操控实验室内的多个台架，全面支持IVI的所有输入输出，能够覆盖90%以上的测试用例。此外，平台还具备集中管理测试脚本和测试报告的功能，极大地方便了脚本的共享与报告的分析，是汽车软件测试工作中不可或缺的得力助手。在企业资质上，凯泽利科技荣获多项殊荣，包括国家高新技术企业、专精特新企业、中等规模以上企业、科技型中小企业以及创新型中小企业等称号。此外，公司还荣获了广东省守合同重信用企业称号，并通过了ISO9001认证和信息安全管理认证，在技术创新方面，凯泽利科技同样表现出强大的研发实力。目前，公司正在申请的国家发明专利已有10余项，并成功获得了10项国家发明专利授权和19项软件著作权授权。目前，凯泽利科技的主要客户包括广汽研究院、深圳联友科技、小鹏汽车、江铃汽车、马瑞利、广汽丰田、广汽能源、岚图汽车、广汽埃安、东风日产、星河智联、南方试验场、立昇科技、祺迹汽车科技、比亚迪、合创汽车、广州优尼冲压等知名企业。', 'https://www.zhaopin.com/jobdetail/CC823999070J40867908315.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5054, '商务专员', '中钰建设(南京)有限公司', '4月14日', '50-100元/天', '南京-江宁区', '建筑设备安装,装饰装修,工程施工', '20-99人', '未融资', 'CCL1234452740J40558477304', '岗位内容：<br>1. 协助编写、审核和修改项目招投标文件，确保符合招投标要求和规范。<br>2. 搜集和分析相关市场信息，进行招投标前期准备和竞争对手分析。<br>3. 协调内部各部门、外部供应商及顾问的工作，确保招投标程序按时、高效地推进。<br>4. 参与商务谈判、合同签订和履行过程中的问题解决和协调处理；  5、学习资质维护相关工作；  <br>  <br>任职要求：  <br>1. 专科以上学历，管理、经济、法律、工程等相关专业；  <br>2.实习岗位，实习合格优先录用；  <br>3.服务领导安排；  <br>4. 具有优秀的沟通、协调和组织能力，较强的抗压能力和团队精神；', '中钰建设（南京）有限公司，座落于人杰地灵的六朝古都南京，公司成立于2019年，注册资本金5000万元。目前拥有市政公用工程总承包叁级、建筑施工总承包叁级等多项资质。主营业务：市政工程、房屋建设工程、公路工程、水利工程、电力工程、环保工程、隧道和桥梁工程、机电安装工程、钢结构施工工程、园林绿化工程、装饰装修工程、提供建筑劳务服务、机械租赁、信息咨询等。公司现有员工83人，其中国家注册一、二级建造师、注册造价师17人，中、高级工程师39人。公司自成立以来，秉承“大中至正、钰汝于成”的经营理念，先后承建了大量的市政道路、桥梁、园林、管网等工程，在城市建设中屡获殊荣。雄关漫道真如铁，而今迈步从头越，面向未来，中钰建设将不断锐意进取，努力打造更多精品工程。', 'https://www.zhaopin.com/jobdetail/CCL1234452740J40558477304.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5055, '律师', '北京市雄志律师事务所', '6月22日', '1.1-1.2万', '北京-西城区', '咨询服务,咨询服务', '20-99人', '未融资', 'CC120871103J00041120909', '1.本所接受多家保险公司的委托，负责办理各类保险案件；<br>2.本所提供大量法援案件及每天12348法律热线值班机会；<br>现急需招聘法律援助中心12348法律热线值班答疑律师和办理法援案件及其他保险案件的律师。<br>任职要求： <br>1、热爱公益法律服务，持有北京市律师执业证；<br>2、恪守律师职业道德和执业纪律，人品端正、有责任感；<br>3、能够独立办案；<br>4、行业内无不良纪录，具有律师团队合作精神。', '北京市雄志律师事务所（以下简称雄志所）是经北京市司法局批准成立的的大型综合性律师事务所，地处北三环中路马甸桥东北侧北环中心A座811室(5A智能化高级写字楼)，交通便利，办公面积充足，谈案环境较好。雄志所现有律师、实习律师五十余名，其中博士学历律师三名，海外留学归来律师三名，硕士以上学历律师十余名。雄志所经《中国法院网》(最高人民法院主办)严格挑选,正式取得了《中国法院网》“律师在线答疑”栏目的常年承办资格；雄志所经《中国律师网》(中华全国律师协会主办)核准,正式成为《中国律师网》的协办单位（全国排名第三）；并取得北京市市级行政事业单位2015-2016年度法律定点服务单位资格。雄志所在业务发展中与国内外律师同仁、学术专家、政府部门和专业机构建立了密切的联系与合作，形成了定期交流制度。雄志律师事务所还组建了一个由法学专家、离任法官及政府官员组成的顾问班子，对雄志律师事务所的业务提供咨询，对事务所的发展与建设提供指导。雄志所的发展思路是：立足北京，融入北京，辐射全国，面向国际。雄志所的办所宗旨是：想客户之所想，急客户之所急，为客户提供优质、高效的法律服务，最大限度地维护客户的合法权益。雄志所最大的特点和优点在于：高度的团结，大力的协作，快速的反应。本所实行主任负责制，在主任的统一领导和协调下，根据业务的特点和需要，能迅速地组成一个强劲的律师团，以集体的智慧和力量向客户提供合法、有效的法律服务和援助。', 'https://www.zhaopin.com/jobdetail/CC120871103J00041120909.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5056, '大客户代表', '北京精金石知识产权代理有限公司', '6月16日', '5000-10000元', '南京-江宁区', '咨询服务,咨询服务', '20-99人', '未融资', 'CC678561320J40480343401', '岗位职责：<br>1、通过市场会议、电话、面谈等方式挖掘潜在客户；<br>2、为客户提供专利业务咨询，为客户制定知识产权规划方案；<br>3、负责与客户谈判和签订合同，完成个人和团队目标；<br>4、与客户建立长期良好合作关系，为客户提供知识产权顾问式服务。<br>任职要求：<br>1、统招本科以上学历，有销售工作经验者优先；<br>2、口齿清晰，灵活性强，抗压能力强；<br>3、热爱并看好知识产权行业的发展前景，有志于在本行业长期发展；<br>4、有上进心，富有不断进取的精神和良好的团队合作意识；<br>5、有敏锐的市场洞察力，有强烈的事业心、责任心和积极的工作态度。<br>薪酬福利<br>1、高额薪酬：底薪+绩效+全勤+提成+五险一金+补充商业保险（入职满两年购买）；<br>2、专业培训: 导师带教，一对一指导；<br>3、周末双休：五天工作制，8:30-5:00，午休1.5小时；<br>4、带薪休假：享受国家法定节假日、每月0.5天带薪事假、婚假、产假、带薪病假、年假等；<br>5、公司活动：定期团建、聚餐、生日会、员工旅游、下午茶等；<br>6、其他福利：入职体检、节假日礼品发放、免费零食饮品等。', '北京精金石知识产权代理有限公司成立于2014年4月，是经国家知识产权局批准设立（机构代码：11470），专业从事国内外专利、商标和版权代理及相关咨询的一站式知识产权服务机构。自成立以来，精金石坚持聚焦于客户需求，以打造核心业务为制高点，不断摸索和提升，已逐步建立起了一支专业化的服务团队，核心成员包含拥有10多年专利审查经验的三级审查员。专利代理师和专利工程师中，95%以上均为全日制理工科硕士研究生毕业，专业领域覆盖化学化工、生物医药、新材料、食品化妆品、机械控制、电学通讯等领域。优势业务主要有：3-4个月发明专利授权（快速预审）专业的中国专利奖申报辅导9-12个月发明限期授权（优审）应客户需求量身定做专利布局专利侵权分析；风险排查等精金石除北京总部外，目前已在青岛、苏州、南京、广州和肇庆等地设有分公司，承担随时响应的客户服务职能。精金石代理的无效案件，胜诉率超过50%；为数家上市公司、央企和拟上市公司提供高质量风险排查和侵权分析服务；与超过5家集团性质公司签订了年度知识产权顾问服务协议，提供立体式知识产权服务。成就客户是精金石一贯坚持和提升的核心目标，并以此作为衡量初心是否坚持的基准线以及实现成为卓有声誉的知识产权咨询公司的愿景的唯一方式。在未来的时间里，精金石将持续追逐帮助客户实现更高成就的使命，并坚定的与优质客户共同前行，不断提升。', 'https://www.zhaopin.com/jobdetail/CC678561320J40480343401.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5057, '网络客服', '晋州市荣杰纸箱包装厂', '5月3日', '4000-8000元', '石家庄-裕华区', '印刷/包装/造纸', '20-99人', '不需要融资', 'CCL1475473940J40719617001', '岗位职责<br>1、负责拼多多等平台店铺的售前、售中在线咨询<br>2、解答关于产品信息、尺寸、材质等相关咨询<br>3、根据客户需求和偏好推荐相关产品<br>4、处理订单相关问题，确保客户满意度<br>任职要求<br>1、打字速度40/分，能熟练操作电脑<br>2、具备良好的沟通技巧和客户服务意识<br>3、善于学习和反馈，具有团队合作精神，有问题能及时沟通解决<br>4、有无经验均可', NULL, 'https://www.zhaopin.com/jobdetail/CCL1475473940J40719617001.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5058, '质检员', '苏州艾伦特劳务派遣有限公司', '2025年07月29日', '6000-7000元', '苏州-虎丘区', '人力资源服务', '100-299人', '未融资', 'CCL1253075150J40802999503', '费用入职!当天安排住宿!包吃包住!本公司郑重承诺:本公司办理入职是在厂区面试[招聘要求]<br>1、年龄要求16-45周岁<br>2、身体健康，能吃苦耐劳、服从领导安排、做事认真负责<br>3、不限学历，不限经验，坐着上班，生熟手均可，无需考试，活轻松容易一看就会。[招募岗位]<br>1、普工.<br>2、所有岗位统一面试、无须经验、简单易操作、无任何辐射、危险性、不穿无尘服[福利待遇]<br>1、住宿:厂区宿舍4-6人间;空调，桌子，衣柜，独立卫生间，洗衣机等设施设备齐全;<br>2、吃饭:提供一日三餐，米饭套餐、面条、水饺、馒头、面包牛奶等，供员工自助选择;', '劳务派遣经营；以承接服务外包方式从事企业生产线工段的外包服务；房产中介；人力资源服务；人力搬运装卸服务；普通货物分拣及仓储服务；保洁服务、家政服务；产品外包装服务；销售：办公用品、劳保用品、五金交电、机电设备；物业管理；绿化养护服务。（依法须经批准的项目,经相关部门批准后方可开展经营活动）', 'https://www.zhaopin.com/jobdetail/CCL1253075150J40802999503.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5059, 'BD经理', '特变电工沈阳变压器集团有限公司', '3月11日', '6000-8000元', '沈阳-铁西区', '电气机械/电力设备,专用设备制造', '1000-9999人', '已上市', 'CC131909900J40237910105', '岗位职责:<br>1.落实海外市场销售计划，完成公司的销售任务；<br>2.与当地国别电力部门建立良好的长期联系；<br>3.策划本区域的公关活动，报批、组织实施；<br>4.组织建立健全客户档案，分析市场需求；<br>5.寻找合适的长期代理商，对代理商进行评价和管理；<br>6.建立并提供完整客户档案，完成相关营销表单、报告；<br>7.跟踪、调查和研究所在国家或地区的大型电力项目，并及时向单位报告；<br>8.完成上级领导临时交办的工作任务。<br> <br>任职资格:<br>1.硕士研究生，本科毕业生，优秀海外留学生，电气类工科专业以及法语、西班牙语、英语等语言类专业；<br>2.品行良好，学习成绩优秀；<br>3.非外语类专业毕业生，要求外语水平达到国家四级水平；外语类专业毕业生，要求外语水平达到专业四级水平；接受长期驻外；<br>4.在校期间担任学生干部、获奖学金及学生党员者优先考虑。<br>职位福利：五险一金、餐补、采暖补贴、免费班车 <br>', '特变电工沈阳变压器集团有限公司是中国重大装备制造业核心骨干企业，始建于1938年，是中国变压器行业历史最长、规模最大、技术实力最强的研发、制造基地，是中国变压器行业技术发展的引领者、标准制定者、行业人才培养的摇篮。公司占地面积约72万平方米，是目前世界电压等级最高、质量保障体系最健全，试验装备、生产设备、生产环境领先的世界级特高压交、直流输变电科技产业园，是中国特高压、大容量、直流输电产品的重要研发基地，全面掌握了火电、水电、核电产品的核心技术。公司先后通过了ISO9001、ISO14001、OHSAS18000、核电体系HAF003、可靠性、美国FMRC、俄罗斯GOST、荷兰KEMA、德国TUV、欧盟CE、意大利CESI、ISO3830焊接等理体系认证，变压器单厂产能超过1.2亿kVA，居世界首位。截止目前，公司已累计开发世界级新产品146种，创造了62项世界第一；拥有各类自主知识产权的专利技术316件，参与国内外85项行业标准的制订，荣获国家科技进步奖6项，其中特等奖2项、一等奖2项、二等奖6项；中国单项冠军奖1项；中国机械工业进步奖、省、市科技进步奖180余项，并被授予“中国工业大奖”、“国家高新技术企业”、“全国工人先锋号”、“中国名牌产品”、“全国五一劳动奖状”、“全国企业文化建设优秀单位”等诸多荣誉称号。公司大力推动生产自动化、产品智能化、管理和服务信息化建设，全面承接了国家重大装备制造业振兴国产首台（套）产品的研制任务，成功实现特高压交流1000kV、直流±1100kV变压器产品、±800kV特高压干式直流套管投运，攻克国家核心技术卡脖子工程，开启了特高压输电技术发展的新纪元，进一步增强了公司在输变电领域的核心竞争力和国际影响力。同时，公司自主研制的世界首台发送端±1100kV高端直流换流变压器，作为唯一一件变压器代表展品永久入藏中国共产党建党百年历史展馆。为保障国家产业安全，公司致力于解决重大装备“空心化”问题，全面替代进口，完成了互感器、高压套管、二次控制设备及集成技术的产业整合，大力推进了现代物流、变压器修试等制造服务业务，形成了较为完善的输变电产品上下游产业链，具有强有力的输变电成套工程承接能力。在国家“走出去”及“一带一路”倡议下，公司积极推动“电力丝绸之路”和世界能源互联网建设。目前已在世界八大区域设立33个海外办事处，产品销往30余个国家和地区，实现高端产品向美国、加拿大、俄罗斯等国的批量出口。同时依靠领先的输变电产品研发、制造、资源整合及融资能力，公司可提供海外750kV及以下所有电压等级的变电站及输变电线路的勘探、设计、施工、安装、调试、运行、维护及培训一体化的“交钥匙”工程服务，同时可从事火电、水电等领域投融资项目的开发与实施。目前已承接印度、巴基斯坦、菲律宾、尼日尔、蒙古、巴布亚新几内亚等国家重点工程项目十余个，服务网络覆盖六十余个国家和地区，实现了从“装备中国”到“装备世界”的飞跃。“十四五”期间，公司将紧紧围绕“双轮驱动、转型升级”总战略，进一步聚焦现有产业布局做强、做优，全面实施“一可、二高、三核”发展战略，打造输变电行业产业布局好、创新能力强、盈利能力佳、体系保障优、受人尊重的百亿企业集团、全球信赖的电气服务商。', 'https://www.zhaopin.com/jobdetail/CC131909900J40237910105.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5060, '网络客服', '九州通医药集团股份有限公司', '7月22日', '4000-5000元', '成都-双流区', '医药制造,互联网,零售/批发', '10000人以上', '已上市', 'CC121098980J40768138010', '岗位职责：', '九州通发轫于改革开放之初的1985年，成立于民营资本允许进入医药流通领域的1999年，2010年11月在上海证券交易所挂牌上市，现已发展成为科技驱动型的全链医药行业综合服务商。九州通是国内最大的民营医药商业企业，位列中国医药商业企业第四位，是行业内唯一获评全国十大“国家智能化仓储物流示范基地”的企业，位列2023年《财富》“中国企业500强”第171位、“中国民营企业500强”第57位。九州通专注于医药商业、医药物流及大健康产业，以西药、中药、器械等为主要经营产品，为个人和机构提供专业的健康管理服务，在全国设立了31个省级与110个地市级物流中心，下属公司548家，营销网络覆盖了全国96%以上的行政区域。九州通积极拓展医院、总代总销、医药分销、数字零售（万店加盟）、医疗器械、中医药、健康管理与技术增值服务等战略业务，利用互联网和数字化工具，建立了服务上下游客户、高效协同、行业领先的医药供应链和大健康综合服务平台。面向未来，九州通将持续推进“三新两化”战略——通过新产品战略构建公司产品竞争力，提升公司的盈利水平；通过新零售、新医疗战略触达C端，构建C端服务能力；通过数字化、智能化战略实现公司整体经营管理水平的提升；通过不动产证券化（REITs）战略实现轻资产轻运营，进一步提升公司股东权益增值回报。同时，公司也将加大对人才的引进力度，坚持长期主义，打造“百年老店”，构建更稳健、更健康、更可持续发展的企业。', 'https://www.zhaopin.com/jobdetail/CC121098980J40768138010.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5061, '游戏运营', '上海太屋网络科技有限公司', '7月23日', '1.5-2.5万', '上海-浦东新区', '房地产开发', '1000-9999人', '未融资', 'CC294547880J40502355503', '薪资待遇：', '太屋集团太屋集团始创于上海，是一个以“服务于人类居住”为核心的集团化企业。集团立足于房地产服务行业，历经30年发展，企业从房地产经纪、房地产咨询代理、商业招商等业务模块开始起步，逐步发展出资产管理、供应链金融、地产开发、互联网科技、职业教育等全新业务模块，伴随着20多家子公司和5个子品牌的相继成立，企业开始走向集团化发展的道路。太屋集团一直以来秉承“锐意进取，开拓创新”的发展理念，以品质服务赢得社会各界的广泛认可和客户的高度信赖。多品牌运营，创建地产生态圈太屋集团旗下拥有【太平洋】和【菁英】2大主力地产服务品牌，形成了太平洋经纪、太平洋房屋、太平洋置业、太平洋物业、菁英地产、菁英置业、菁英物业等众多房地产领域的独立企业；同时，还拥有【太屋网】、【菁铧】、【王典】这3大品牌，分别涉足地产网络科技、供应链金融、资产管理等相关行业；集团业务重心始终围绕着“居住产业”，希望通过多元化、产业化、平台化的发展，从房地产一级市场到三级市场，业务扩展到房地产行业全产业链，创建企业化的地产生态圈。【太平洋房屋】1994年成立于上海，集团于2004年接手该企业，成为集团旗下的主力企业之一。太平洋房屋作为上海房地产经纪行业协会的副会长企业之一，伴随着上海房地产市场的发展不断壮大。目前，公司业务范围覆盖全上海13个大区，拥有600家线下门店，10000名专业经纪人，年累积交易金额达5000多亿元，市场市占率稳居上海前二！公司历经30年的发展，100多个业界奖项与殊荣铸就了企业发展的历史，其中，上海市白玉兰纪念奖、蝉联18届“金桥奖”的殊荣等历史荣誉都是太屋人的骄傲。作为行业的领跑者和颠覆者，太屋集团整合旗下地产类各项业务，开创【太屋网】这一全新品牌，以“安心托付，幸福满屋”的经营理念，打造全产业链的房地产服务平台，让集团业务从线下向多元化、产业化、平台化方向发展……企业商学院，孵化企业人才团队随着集团业务规模不断扩大，企业的人才战略将成为决定集团未来发展的重要指标。2019年，上海太屋教育科技有限公司正式成立，我们集团的商学院——“太屋大学”也孕育而生。太屋大学，拥有强大的师资团队，以及由行业翘楚和权威专家组成的客座教授团体；建立了课程培训、名家讲堂、拓展训练、全球游学等科学化系统化的教学培训体系，针对行业的不同岗位和职务，开展有针对性的职业教育与培训，为企业人才赋能，共同创造价值。热心公益，企业向上向善的力量扶危渡厄，使命担当。太屋集团始终以“成就员工以成就企业，成就企业以回报社会”为愿景，时刻肩负着企业的社会责任，积极投身于公益事业。太平洋爱心基金、阳光之家公益活动、环卫工人“爱心接力站”、红马甲社区志愿者、免费社区便民服务、高考加油站、垃圾分类志愿互动……在此次新型管状病毒疫情的抗疫过程中，集团立即组织捐赠大量医疗物资，火线驰援抗战在一线的医疗单位。在点滴的生活中，太屋人始终用一颗向善之心，让世界多一份美好……太屋集团，一个有理想、有信仰、有温度、有情怀、有灵魂的集团企业，期待您的加入！', 'https://www.zhaopin.com/jobdetail/CC294547880J40502355503.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5062, '内容审核', '天津人瑞网络科技有限公司', '7月2日', '8000-9000元', '成都-武侯区', '人力资源服务', '100-299人', NULL, 'CCL1426706820J40763026302', '工作内容<br>1、对游戏的违规言论、语音及图片等进行处理<br>2、解答和处理用户反馈的问题，准确审核用户提供的文字、图片及语音等信息<br>3、及时反馈和协助处理异常状况，并做好沟通<br>4、对工作或产品问题进行反馈并提出改进建议<br>薪资福利:底薪4.4k起面试定薪+绩效+餐补300元+车补200元<br>任职要求<br>1、大专及以上学历，专业不限，熟练使用office相关软件<br>2、有较强的逻辑思维能力和问题分析能力<br>3、优秀的团队合作精神，善于沟通，具有亲和力<br>4、具备良好的服务意识，做五休二<br>5、熟悉不同类型游戏，对游戏语言环境熟悉者优先。', NULL, 'https://www.zhaopin.com/jobdetail/CCL1426706820J40763026302.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5063, '律师', '北京市中润律师事务所', '7月25日', '5000-8000元', '北京-朝阳区', '咨询服务,咨询服务', '20-99人', '未融资', 'CC000586518J90250086000', '岗位职责：<br>1. 协助合伙人处理诉法律事务 <br>2. 指导当事人搜集相关庭审证据及其他有关法律方面的工作； <br>3. 独立负责案件文书、立案、保全、开庭、调解等工作； <br>4. 整理案卷档案资料； <br>5. 完成合伙人交办的其他事务。 <br> <br>任职要求： <br>1. 法学专业本科及以上学历，通过法考，有法务经验者优先； <br>2. 具有较好的文字功底； <br>3. 法学基础扎实，沟通能力强，具有独立的法律思维； <br>4. 无行政处罚及不良从业记录.<br> <br>待遇：<br>1、工资面议 五险；<br>2、本着长期合作原则，为实习律师提供培养发展平台；<br>3、周六日双休，享受国家法定假期；<br>4、工作时间：9：00--18:00。<br>职位亮点：办公氛围轻松  <br>', '北京中润律师事务所是经国家司法机关批准成立的大型综合性律师事务所，严格按照国际律师事务所模式组建，始终致力于建立优秀专业人才队伍和提供优质尽责的法律服务。中润律所位于北京中央商务区（CBD）核心钻石地带，西邻国贸中心，东接华贸地带，一流的商境、高素质的人才队伍，打造出中润律师事务所这一卓越法律服务品牌。中润律所作为一家大型综合性知名律师事务所，成功服务于社会的各行各业，法律服务范围涉及知识产权、涉外业务、金融、证券、房地产、企业破产、融资、投资、IT、互联网、电子商务、法律顾问等各个领域、投资、IT、互联网、电子商务、法律顾问等各个领域。另外，中润律所始终注重与立法、行政、司法等政府部门和研究机构建立密切的联系，并保持着长期稳定的合作关系。中润律所汇集了海内外各大知名院校培养的专业人才，并有多名律师具有硕士以上学位，可以用英文进行工作。他们不仅是各个专业领域的法律专家，而且具有丰富的实务经验，能够针对客户的具体需要、为其提供量身定做的法律解决方案。中润律师具有较高的职业素质和服务意识，强调团队合作精神，竭诚以全所共同的力量为每一位客户提供全面、专业、优质、高效的法律服务。', 'https://www.zhaopin.com/jobdetail/CC000586518J90250086000.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5064, '游戏运营', '河南墨徊网络科技有限公司', '7月23日', '8000-11000元', '深圳-宝安区', '游戏', '20-99人', NULL, 'CCL1506194460J40777990902', '招线上游戏打手，精通三角洲，原神，崩铁，鸣潮，燕云其中一款即刻。 工作时间自由，没有工作量要求', NULL, 'https://www.zhaopin.com/jobdetail/CCL1506194460J40777990902.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5065, '风电工程师', '天津畅行高铁运维科技有限公司', '7月21日', '8000-12000元', '杭州-西湖区', '客运服务', '10000人以上', NULL, 'CCL1495093740J40795521105', '一、岗位职责：按照风机机组及配套设备的维护技术要求，对其定期巡检、维护、定期检修、故障消除、技术改造等，保障风电机组的安全、稳定运行。<br>二、岗位要求：18-35周岁，中专及以上学历，无恐高、无心脏病、无幽闭恐惧症、色盲等；上岗须持有安监局发放的高低压电工证、登高作业证、（无证人员公司免费考证）；<br>三、薪资待遇：<br>1、试用期每月5000-6500元，工资每三个月到半年调薪500-1500元，工作满一年后工资8000-12000元。享受13薪。<br>2、转正后签订正式劳动合同，缴纳六险一金，常白班，8小时工作制。<br>每工作2-3个月带薪休假10-15天，回家往返路费公司报销3、晋升空间：运维工程师-运维值长-运维场长-项目经理', NULL, 'https://www.zhaopin.com/jobdetail/CCL1495093740J40795521105.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5066, '销售工程师', '青岛默森制造技术有限公司', '7月22日', '5000-10000元', '石家庄-裕华区', '专用设备制造,通用设备制造,工业自动化,专用设备制造', '100-299人', 'A轮', 'CC306972930J40798898112', '岗位职责：', '青岛默森制造技术有限公司，初创于2013年，公司位于青岛经济技术开发区，是一家专业从事智能生产线设计与制造，机器人系统集成及自动化技术应用、高端数控机床销售及售后服务为一体的企业，公司致力于提供先进的智能制造解决方案，智能自动化加工线改造、精密检测线系统方案；公司设计制造的桁架机器人生产线、工业机器人上下料系统广泛应用于汽车行业。公司自成立已来已申请发明专利5项，实用新型专利近40余项，在国内重要期刊发表论文十余篇。已合作的客户有中国兵器一机集团、北汽福田、潍柴动力、重庆机电集团、滨州活塞、湖南江滨、仪征双环、佛山中南、济南一机、韩国三星、韩国现代汽车等国内外众多知名企业。', 'https://www.zhaopin.com/jobdetail/CC306972930J40798898112.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5067, '英语翻译', '昌利数控设备(深圳)有限公司', '4月2日', '6000-12000元·13薪', '深圳-宝安区', '电气机械/电力设备,仪器仪表制造', '20-99人', '未融资', 'CC229757410J40184051813', '岗位职责  1、配合工程师与海外客户进行远程交流沟通；', '昌利数控设备（深圳）有限公司（以下简称：昌利公司）成立于2008年，总部位于深圳宝安石岩，是一家致力于自动化数控设备解决方案的高新技术企业。由于国内、外市场的快速发展，公司先后在香港、沈阳、墨西哥成立了分、子公司。公司自成立以来，专注于刀模制作行业，成功开发出了具有自主知识产权的畅产品，主要有：电脑自动弯刀机，电脑自动切刀机，平模数控切割机，圆模数控切割机，Future CAM系列软件等。在短短的几年中，昌利公司的全球经营战略不断深化，目前与亚洲、欧洲、北美洲、南美洲、澳洲和非洲的众多用户建立长期稳固的合作伙伴关系。昌利公司的产品以精度高、效率高、品质高的“三高”特点，获得了业界的专业认可以及竞争对手的敬重，成为全自动电脑弯刀机行业的领航者。昌利公司拥有世界一流的科研开发技术，两位创始人江先生和伍先生分别在刀模制造业和电脑自动化工业拥有20年以上的经验，2011年开始，公司再加入了国内刀模行业知名的企业家李先生，为公司的发展带来新的机遇。公司汇集了从事刀模行业最顶尖人才，整合形成研发设计、生产销售、客户服务等多个专项精英团队，这些也是昌利迅速发展成为行业佼佼者的最大资本。正是源于我们对行业深度的了解，对品质的不懈追求，打造出世界一流刀模品牌产品。以推动整个刀模行业不断前行的使命和责任感，成为行业的领航者。带动引领刀模行业的快速发展。昌利人始终秉承认真，严谨，谦逊，高效的做事态度，努力攀登，追求卓越。用专业成就你我，用创造书写未来。我们提供：1.有竞争力的薪酬除基本工资外公司会为每位员工提供表现奖、绩效奖金、机台奖金、年底花红及补贴2.保险公司为每位员工购买社会保险和住房公积金，经常出差的员工还会购买人生意外保险，让每位员工无后顾之忧3.娱乐活动公司会不定期的组织员工聚餐，每年会有一次旅游4.办公环境舒适的办公环境，和谐愉快的工作氛围公司网址：www.richlytop.com', 'https://www.zhaopin.com/jobdetail/CC229757410J40184051813.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5068, '质量管理/测试', '温州市志信标准件有限公司', '5月30日', '4000-5000元', '温州-瓯海区', '金属制品业', '20-99人', NULL, 'CC309598530J40760615614', '工作内容：<br>1.进行产品质量检查，包括原材料检验、生产过程检验和最终产品检验等。<br>2.分析质量问题和非合格品，确定根本原因并提出改进措施。<br>3.设计和实施质量控制计划，确保产品符合质量标准和客户要求。<br>4.协助制定技术规范和标准，确保生产过程符合行业要求和安全标准。<br>5.解决质量问题和投诉，并提供相应的解决方案。<br>6.参与新产品开发过程，提供质量方面的技术支持和建议。', NULL, 'https://www.zhaopin.com/jobdetail/CC309598530J40760615614.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5069, '商务专员', '贵州维讯信息技术有限公司', '3月26日', '4000-6000元', '贵阳-观山湖区', 'IT服务,计算机软件,计算机硬件,通信/网络设备', '20-99人', NULL, 'CC359085110J40341436613', '职位要求:<br>1、必须了解招投标基础知识;了解合同相关的基础法律法规知识。<br>2、有无经验均可；计算机/通信/市场营销相关专业或具有计算机相关行业工作经验优先；<br>3、做事灵活、有条理，具备流畅的口头及书面表达能力;<br>4、熟悉Word/Excel/PPT使用，会使用Photoshop工具；<br>5、具备良好的敬业精神和职业素养；有较强的责任心和团队协作精神。岗位职责<br>1、 项目招投标：参与IT招投标项目的标书制作及投标准备事务；<br>2、合同签订：负责合同的起草、签订等工作；<br>3、 合同跟踪：负责合同执行跟踪、合同付款跟踪等工作；<br>4、 商务信息管理：负责日常商务信息收集、统计、整理等工作；<br>5、项目质量管理：配合协调管理项目服务交付进度、资源、成本、质量、客户满意度等。<br>根据商务助理能力评估，具备条件者可发展成为客户专员。<br>主要工作职责：<br>1、 跟进项目质量管理工作；<br>2、 挖掘用户需求，协调其他部门提出技术解决方案。<br>职位福利：五险一金、加班补助、带薪年假、定期体检、员工旅游、绩效奖金', '贵州维讯信息技术有限公司（Guizhou Vision IT Co.,Ltd.）于2002年11月根据中国公司法注册成立。2003年经国家科技部批准为贵州省高新技术企业，2013年获得计算机信息系统集成三级资质，服务涵盖计算信息系统的核心数据库、网络及安全的系统集成和整体运维，自主知识产权的软件研发。【企业愿景】为社会创造并维持完美的计算系统。【企业定位】信息系统安全互联服务专家。【运营思想】全球化技术、本地化服务。【我们的福利】◆体现岗位价值的薪资体系，年终奖及年底双薪。◆完善的晋升体系，季度加薪机会。◆健全的培训体系。◆双休制，享有国家法定假日及带薪年假。◆正式员工享有“五险一金”（养老、医疗、失业、工伤和生育保险）。◆每年定期体检。现因公司业务发展需要，面向社会招聘贤才，真诚期待您的加入...', 'https://www.zhaopin.com/jobdetail/CC359085110J40341436613.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5070, '质量管理/测试', '江苏恬一食品科技有限公司', '4月17日', '5000-8000元', '扬州-高邮市', '食品/饮料', '20-99人', '不需要融资', 'CCL1444266550J40738952210', '岗位职责：<br>1. 执行来料抽样频次<br>2. 跟进供应商改善追溯<br>3. 有效执行过程巡回检验<br>4. 高效监控检品中心的顺序<br>5. 负责新产品导入、新同事加入的质量模块培训与检查<br>岗位要求：<br>1. 大专及以上学历<br>2. 食品行业优先<br>3. 愿意接受企业安排的《轮岗学习实操》制度<br>4. 三观正，实事求是<br>5. 具备一定的抗压心态<br>（未包含薪资待遇相关内容，故不输出“薪资待遇”部分。）', '江苏恬一成立于2022年，历经数年专业深耕，恬一业务已覆盖全国各地，累计合作客户数万，是优秀的盒马等大型超市供应商之一，感受有温度的品牌服务：·工作氛围超nice，能力提升UP UP·绩效奖金拿到手软，每一分付出都能看见回报…我们期待：驰骋多年身经百战的你；初出茅庐充满干劲的你；寻求转型渴望突破的你；让千里马和伯乐，不再千载难逢；恬一食品，更懂你的价值！恬一的明天，由你创造！', 'https://www.zhaopin.com/jobdetail/CCL1444266550J40738952210.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5071, '日语翻译', '辽宁政通对外劳务经济合作有限公司广州分公司', '2025年07月29日', '1.2-1.5万·14薪', '南京-浦口区', '咨询服务,培训/辅导服务', '20-99人', NULL, 'CC815079210J40562447407', '招聘岗位：<br>  <br>1）企划:改善案企划·执行、店铺经营、商品销售等企划制定<br>2）事务:接待访客、职员工作管理、企划书制作等<br>  <br>3）店铺运营:手机网络营业 签约售后，店铺运营，促销等活动<br>应聘条件：<br>1.日语N2级以上，日常会话流利水平，可以无证书。<br>2.有团队合作能力，有适应能力。<br>3有日语基础者 大欢迎。男女不限。<br>工作时间:<br>每周工作5天，每天8小时。<br>  <br>薪资待遇:<br>1）月薪:12000-15000元 人民币<br>2）每年加薪2次（4月/10月），奖金每年2次（8月、1月）<br>3）有交通津贴、加班津贴、出差津贴。<br>4）提供住宿<br>工作地点：日本全国 可以选择 总部在东京<br>签证类型：<br>技术人文与国际业务，可带家属，可永住。<br>大手上市公司正社员采用。<br>其他福利：<br>五险一金、绩效奖金、年终分红、全勤奖、员工旅游、每年多次调薪、股票期权、交通补助、食宿补助。~gj<br>  <br> <br>', '新干线教育集团旗下子公司，提供境外就业信息、咨询、中介服务,隶属新干线教育集团。新干线教育集团创立于2005年，系沈阳市教育局批准的专门从事语言培训、出国留学、海外就业、境内境外游的综合性集团，目前拥有沈阳新干线外国语培训学校、沈阳政通佳益教育咨询有限公司、沈阳二十一世纪佳益出国留学服务有限公司、辽宁政通对外劳务经济合作有限公司、辽宁政通国际旅行社有限公司，以“培训、留学、就业、旅游”四大模块，全程一站式服务于广大学员。就业模块辽宁政通旗下，先后成立了:辽宁政通对外劳务经济合作有限公司广州分公司、四川分公司，大连分公司，杭州分公司以及日本东京分公司等。多年来，公司一直积极投身于国际文化交流，致力于涉外人才输出。和日本的新干线一样，新干线教育集团以安全、正确、舒适、快速的服务每年向世界各一线学府及涉外工作岗位输送大量优秀人才，为学员走出国门搭建起坚实的桥梁。在市委、市政府领导的关怀下，在国家有关部门的大力支持下，新干线教育集团凭借着贴心的服务、先进的教学理念和完善的海外服务，在培训及人才输出领域脱颖而出，赢得了学员的口碑、市场的青睐，已经成为东北地区语言培训及涉外留学、就业领域的一面旗帜。未来，集团还将一如既往的以诚载信，积极投身于国际文化教育与交流事业，见证更多学员的成长与美好未来，为实现“促进国际交流，铸就百年品牌”的目标而不懈努力。新干线教育集团旗下子公司辽宁政通对外劳务经济合作有限公司，是经中华人民共和国商务部批准并授权颁发《对外劳务合作经营资格证书》[证书编号：LW210020120008],拥有正规资质的境外就业服务机构。公司先后与日本、美国、澳大利亚、新西兰、韩国、新加坡、加拿大、俄罗斯等10余个国家的院校建立了的长期的合作关系，送出去的留学生达数千人。为广大莘莘学子架起了通往成功道路的桥梁。友情提醒：办理出国劳务请选择国家商务部正规资质公司，以防上当受骗，请勿贪图便宜选择那些费用低，待遇高的出国项目，办理前一定要核实中介公司的商务部资质，所有正规的商务部资质公司，注册抵押金均已更改为600万人民币！或登录国家商务部官方网站自行查询~~出国劳务陷阱多，请谨慎选择办理！联系方式：微信公众号：lnzhengtong（出国就业吧）公司网站：www.nhk360.com微信/电信：13889814653新干线李老师公司地址：成都市武侯区科华北路62号力宝大厦1001座机：028-62788831广州市天河区体育西路57号红盾大厦5A26室座机：020-28821709沈阳市沈河区北站路53号财富中心B座15楼座机：024-22523845日本分公司：东京都涩谷区道玄坂2-16-2', 'https://www.zhaopin.com/jobdetail/CC815079210J40562447407.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5072, '电话销售', '北京中民瑞康健康科技有限公司石家庄第二分公司', '2月24日', '6000-12000元', '石家庄-桥西区', '企业服务', '20-99人', '未融资', 'CCL1480996740J40878122404', '岗位职责：<br>1、公司提供有效客户信息，负责电话或微信进行沟通； 2、了解客户需求, 寻找销售机会并完成销售业绩；', '北京中民瑞康健康科技有限公司石家庄第二分公司成立于2023年3月6日，主营技术开发、技术服务、医学研究和试验发展，健康咨询服务（不含诊疗服务），企业形象策划等业务，总部成立于2017年，位于北京市，是一家以从事研究和试验发展为主的企业，公司注重锐意革新，始终秉承诚信、客户至上的原则，提供最贴近用户需要的服务，公司正以坚实、稳健的步伐，朝着规模化、产业化的方向发展。', 'https://www.zhaopin.com/jobdetail/CCL1480996740J40878122404.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5073, '运营助理/专员', '万达商业管理集团有限公司济南分公司', '7月25日', '4000-5000元·15薪', '枣庄-滕州市', '物业管理', '10000人以上', '已上市', 'CC327764380J40292495104', '岗位职责：<br>1. 协助营运主管完成部门下达的工作任务和指标；<br>2. 负责管辖区域的各项工作，及时上交各种报表；<br>3. 协调与各品牌的关系，及时与品牌沟通；<br>4. 督促各品牌店长的工作，将每日各品牌的信息整理上报。<br>任职要求：<br>1. 本科及以上学历，1年以上大、中型商业企业工作经验，或优秀的25届应届毕业生；<br>2. 沟通能力强，执行力强；<br>3. 熟练使用办公软件；<br>4. 认同万达企业文化，具有较强的工作责任心。<br>职位福利：五险一金、包吃、节日福利、轮休、定期体检、高温补贴、带薪年假', '万达集团：万达集团创立于1988年，已发展成为以现代服务业为主的大型企业集团，旗下包括商管集团、文化集团、投资集团，其中商业中心、影视、体育、儿童产业等处于世界行业领先地位。万达商管集团：万达商业管理集团成立于2002年，是全球领先的商业运营管理企业，万达广场是中国著名品牌，已发展成为集社交、文化、旅游、美食、娱乐、购物于一体的第四代万达广场，成为人们美好生活中心。截止上半年已在全国227座城市开业484座万达广场，管理的商业面积超6700万㎡，是全球最大的商业不动产管理企业。济南城市公司：万达商管集团济南城市公司作为万达商管集团重点管理区域之一，下辖20家万达广场，分布在济南、济宁、东营、泰安、德州、滨州、枣庄、菏泽、临沂、聊城、淄博等11城。管理商业面积超 243万㎡，（约4500个商铺），年客流量超 1.6亿人次，年销售超 150亿元。', 'https://www.zhaopin.com/jobdetail/CC327764380J40292495104.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5074, 'APP推广', '成都歪马科技有限公司', '7月25日', '8000-12000元', '石家庄-长安区', '电子商务', '1000-9999人', '未融资', 'CCL1492920960J40826487208', '【工作内容】<br> 快速响应，让顾客喝上酒（高效服务）。<br> 看管好前置仓的酒，确保下单准确，简单做做促销。<br> 推广咱们“歪马送酒”APP/小程序。<br>【收入可观】<br>无责底薪保底 + 全勤奖励 + 提成丰厚 + 补贴多多，综合月入9000+很常见！<br>【门槛不高】<br>18-45岁（能力突出年龄不是问题），男女都行，自带两轮电动车。<br>【晋升神速】<br>清晰路径：员工→店长→主管→经理！能力说话，最快2-3个月晋升，薪资福利UP! UP!<br>30+门店覆盖，找离家超近的！马上咨询匹配你的理想门店~', '歪马送酒是美团旗下的酒水即时零售品牌，经营品类涵盖啤酒、白酒、红酒、洋酒四大品类。通过与酒水品牌直接合作，严控供应链，自建配送体系，给前置仓配货，商家在小程序和外卖平台为用户提供平价、保真、平均15分钟送达的酒水及时送服务。歪马送酒在2021年6月23日广东惠州开展单城探索，启动1个城市中心仓+N个前置仓，40天开仓8家，覆盖惠州主要城区。截止2024年7月，歪马送酒在广东地区（深圳、广州、东莞、佛山、惠州、汕头、江门、中山、河源），江苏地区（南京、苏州）、浙江地区（杭州、宁波、温州）北京、上海、杭州、成都、西安、重庆、武汉、福州等22个城市建有直营门店，门店数量超过家。2025年还会入驻青岛、南宁、郑州、合肥、贵阳等城市，预计实现全国省会城市、一线城市全覆盖，门店数量超1000+。', 'https://www.zhaopin.com/jobdetail/CCL1492920960J40826487208.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5075, '总助/CEO助理/董事长助理', '辽宁省大连市伟超健康养生科技有限公司', '7月23日', '8000-10000元·14薪', '大连-甘井子区', '物联网', '300-499人', '不需要融资', 'CCL1432452810J40300615004', '1、负责对外联络、接待，做好公司会议纪要、备忘录及其它⽂件的整理；<br>　　2、协助董事长对重要业务资料进⾏档案管理；<br>　　3、负责及时传达董事长的各项指⽰安排，起草董事长交办的信函、报告、⽂件等各类⽂件；<br>　　4、负责董事长的⽇常⾏程安排；<br>　　5、根据董事长要求，跟踪决议事项的推进；<br>　　6、负责董事长办公室和公司客户的接待⼯作；<br>　　7、完成董事长交办的其他⼯作的督办、协调及落实任务。<br>　　职位福利：五险一金、年底双薪、周末双休、无试用期、14薪、带薪年假、定期体检、节日福利 <br>', '是一家专业从事健康科技领域内的技术开发、技术转让、技术服务综合性企业。并同时自主研发、生产、销售光波房的大型综合性企业；同时具有进出口权限的公司，产品远销欧洲、南非、北美、澳大利亚等地。', 'https://www.zhaopin.com/jobdetail/CCL1432452810J40300615004.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5076, '项目专员/助理', '北京新致君阳信息技术有限公司', '7月2日', '5000-6000元', '武汉-洪山区', '计算机软件,IT服务,保险,证券/期货', '1000-9999人', '已上市', 'CC404581310J40790071705', '工作内容<br>1、协助运营专员，完成公司业务数据的跟踪、统计和分析工作；<br>2、协助运营专员，完成公司的项目过程管理工作；<br>3、完成领导交待的其他任务；<br> <br>任职要求<br>硬性条件<br>1.学历专业：<br>统招本科及以上学历，统计学、数学、经济学、会计学、计算机等相关专业优先；<br>应届生或毕业1年内候选人优先。<br>2.技能要求：<br>熟悉Excel（数据透视表、VLOOKUP/XLOOKUP、SUMIFS等函数、基础VBA等）；<br>具备良好的数学基础、逻辑思维能力及数据敏感度，能快速理解业务需求；<br> <br>软性素质<br>1.严谨细致：对数据准确性有极高要求，能发现数据异常并追溯根源；<br>2.学习能力：能快速掌握新工具及业务知识；<br>3.责任心：对交付结果负责，能承受短期高强度工作压力；<br>4.沟通意识：性格开朗，乐于沟通，能主动对接需求，清晰反馈问题。<br> <br>优先考虑条件<br>1. 有数据分析、电商/互联网运营相关实习经验；<br>2. 参与过数学建模、统计建模大赛或学术研究项目；<br>3. 擅用AI工具突破传统办公效能瓶颈。<br>4. GPA 3.3以上。', '1994年6月，新致创立于中国上海。公司主营业务包括：行业解决方案、相关软件产品、平台及服务等。目前，公司拥有员工4000余位。公司总部位于上海，在中国建立了北京、大连、西安、苏州、杭州5个国内分支机构；在海外已设有日本东京、日本关西、美国费城、法国巴黎4个子公司。新致以“日新以致远”作为公司的核心理念和品牌承诺。作为一家以软件技术为核心的公司，新致通过合作创新、有效管理、人才发展等战略的实施，持续提升公司的核心竞争力，不断为客户创造价值，为员工创造机会，从而实现对社会的积极贡献。新致致力于成为全球最优秀的IT解决方案与服务供应商，并通过组织与过程的持续改进，使公司成为最受社会、客户、股东、员工所推崇的“百年企业”，为人们的工作和生活带来积极的改进。', 'https://www.zhaopin.com/jobdetail/CC404581310J40790071705.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5077, '网络客服', '成都萌小玺文化传媒有限公司', '7月23日', '7000-14000元', '全国-None', '新媒体', '10000人以上', NULL, 'CCL1486511100J40861591315', '办公方式：线上办公（可居家）<br> 结算方式：日结', '成都萌小玺文化传媒有限公司，成立于2024年，位于四川省成都市，是一家以从事文化艺术业为主的企业。成都萌小玺文化传媒有限公司，成立于2024年，位于四川省成都市，是一家以从事文化艺术业为主的企业。', 'https://www.zhaopin.com/jobdetail/CCL1486511100J40861591315.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5078, '质检员', '广州科迅企业管理服务有限公司', '4月21日', '7000-10000元', '佛山-三水区', '电子设备制造,咨询服务', '500-999人', '未融资', 'CC592846420J40745943614', '当天安排宿舍，长白班、质检员 QC<br>生熟手均可，有人带培训<br>不用体检。全部长白班，没有夜班，工时作‬间：9--22点<br>岗要位‬求:<br>1、高中‬及以上学历，认识26个文英‬字母，无色色盲‬弱，懂础基‬电脑操作（复制，粘贴，截图，当场测试）<br>2、有任责‬心、有学提习‬升意识及行动，有一定通沟‬表达能力，服安从‬排<br>3、希音自离及黑名单不行<br>前3天理论培训学习，第4天考试，专业质检流程实操考核（必须要考试合格）否则不能进仓。<br>转正后：底薪2100➕绩效525+计件+餐补8元/餐+其他补贴，综合薪资6500--9000，每周可以申请预支<br>岗位：质检员<br>工作内容：<br>1.对衣成‬的款式、颜色、材做质‬工、外观、尺码、清度洁‬等全检，掌执握‬行质检环标节‬准<br>2.站岗为主，旁边配有小凳子，需要久盯电脑屏幕<br>3.月休4天左右<br>另外还招聘质检储备人才，志于培养改变物流前景的新星力量，要求：25年毕业的应届毕业生，大专及本科以上学历。薪资待遇及招聘费用一致，大专额外补贴500元/月，本科额外补贴700元/月，', '广州科迅企业管理服务有限公司（科迅人力）成立于2013年，注册资金500万元，是经工商管理部门注册，由人力资源和社会保障部门备案,具有劳务派遣资质的人力资源服务供应商，是华南地区最专业的人事外包服务企业之一。服务范围涵盖人事代理（全国）、劳务派遣、岗位外包、培训拓展、校企合作、大中专毕业生就业（实习）推荐和指导等，是珠三角地区企事业及政府机构人力资源专业服务的首选战略合作伙伴。目前，我们已经服务了超80家5000人以上的大客户，业务范围10个省份近20个城市，有专业的招聘团队和规范标准的项目管理团队，年度输送人数逾十万人次，输送能力在华南地区名列前茅。', 'https://www.zhaopin.com/jobdetail/CC592846420J40745943614.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5079, '风电工程师', '陕西风新能电力科技有限公司', '6月28日', '6000-12000元', '宝鸡-金台区', '新能源', '20-99人', NULL, 'CCL1483772690J40775931812', '一、电气、机械类相关专业有工作经验(无经验也可以）二、可接受中长期驻外工作；', NULL, 'https://www.zhaopin.com/jobdetail/CCL1483772690J40775931812.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5080, '网络销售', '北京我爱我家房地产经纪有限公司', '7月16日', '1.1-2.2万', '北京-昌平区', '房地产中介', '10000人以上', '已上市', 'CC156263720J40757909307', '公司是一个没有天花板的舞台；没有任何空降兵；所有人才公司自主培养<br>Hello!~北京我爱我家正迅速扩张版图，高薪、住宿、晋升，通通等你来感受!<br>( 快来点击“立即沟通”与我在线沟通呀 随时欢迎 )<br>在北京市场占有率，全北京700家门店每个区域都有门店，当天安排工作与住宿。<br>-----------------------------------------------------------------------------------------------------------------------<br>同是异乡打工人，我们懂你！！在这里，我们可以给你(公司提供住宿，做房产，不用担心住！)<br>1、新人试用期：我们试用期5-8K，转正~平均可以拿到1-2万行业内到手较高提成:统提，平均提成率30%-75%，销售靠自己付多劳多得。上不封顶~<br>2、没有经验要求!欢迎小白~我们有高级的APP培训就像养成类的游戏一样，有趣的视频课程，线上线下相互结合! 店长1对1指导，只要你肯学，一周就上手。<br>3、北京是一线城市，几千万的外地小伙伴来打拼，刚需就是租房! 公司租房+卖房---没有经验一个月也能租出去两三套房子。<br>4、公司很多经理都是90后，不看资历看能力! 靠自身实力公平发展，这里没有“关系户”<br>我们的要求:<br>1、热爱销售，喜欢与人沟通，敢于挑战，渴望提高自己个人能力。<br>2、您是诚心找工作，执行力强，认真负责!<br>3、具备良好的个人品格，善良、正直、能热情真诚对待客户。<br>工作内容:<br>1、门店接待客户+公司官网在线沟通邀约客户。<br>2、邀请客户来门店看房，做面对面沟通。<br>3、带客户实地看房。<br>4、谈价格，签合同，拿提成。<br>-----------------------------------------------------------------------------------------------------------------------<br>这是一份可以用自己的能力去买房买车的工作，加入我们一起在北京奋斗，不忘初心，共赢!<br>(快来点击“立即沟通”与我在线沟通呀 随时欢迎 )<br>8只要你有能力 我们提供一个没有天花板的舞台<br>4、具备良好的个人品格，善良、正直，能与同事友好相处，能热情真诚对待客户。<br>为什么我们接受无经验小白我爱我家学院(简称“家学院”)拥有独立的培训教学楼，从新人进公司，培训便一直伴随您成长。<br>T计划:经纪人新人-高级经纪人系列培训;M计划:管理层进阶-高级管理层系列培训<br>教会徒弟，师傅才可得到晋升，真正意义上的一对一带教，只要你愿意学习就能把你培养成一名合格、优秀的我爱我家房产经纪人!', '我爱我家控股集团股份有限公司（证券代码：000560），是国内首家成功登陆A股主板市场的房地产经纪企业。集团旗下拥有我爱我家、相寓、昆百大、伟业顾问、汇金行和我爱我家海外等多个在行业内知名的专业业务品牌，面向政府、投资机构、金融机构、学术研究机构、房地产开发企业，以及广大个人消费者，提供线上线下一体化的数据顾问、楼盘代理、新房交易、二手房经纪、房屋租赁、住宅资产管理、商业地产运营管理和海外房产交易等房地产全产业链居家综合服务。截止2017年底，集团国内业务覆盖北京、上海、杭州、南京、天津、苏州、太原、长沙、郑州、无锡、成都、武汉、南宁、青岛、南昌等15个大中型城市，拥有深入社区的连锁门店3300余家，专业的房产置业顾问服务团队5.5万余人，近三年实现房屋销售总额破万亿，营业收入逾200亿元，企业规模位居国内房地产经纪行业前列。集团旗下专业房屋资产管理品牌——相寓，作为中国经营时间最长的房屋资产管理服务商，全国在管租赁房屋套数27万套，55万间，物业资产管理规模逾5000亿元，稳居行业第一。在中国经济和房地产市场发展的新时代，我爱我家集团将坚持开放、共享的理念，携手同业，与更多的合作伙伴一起创造更多合作共赢的契机，为社会带来更多的就业机会，承担更多的社会责任；共同为广大客户提供更加优质的专业服务；为广大员工提供更加广阔的个人展业平台；一起推动房地产经纪行业的规范、健康、可持续发展，共同构建开放、共享、共赢的行业和谐生态圈，让居住更美好。', 'https://www.zhaopin.com/jobdetail/CC156263720J40757909307.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5081, '电话客服', '深圳骅富商务咨询有限公司广州分公司', '7月24日', '6000-11000元', '广州-越秀区', '互联网金融/小额贷款', '500-999人', '不需要融资', 'CCL1330667440J40565022611', '岗位职责：<br>1、主要通过短信、电话、信函通知等方式与相关客户联络，提醒客户及时还款；<br>2、负责逾期账户管理，及时掌握各客户的欠款情况并做好登记；<br>3、登记好沟通中遇到的情况，获取、更新逾期客户的资料信息；<br>4、完成其他相关工作，完成部门领导交办其他事项。<br>', '专业银行风险控制提供商集团总部位于深圳，现已在长沙，广州，合肥，济南，南海等城市设立分公司，业务范围已覆盖全国主要城市。广州骅富是一家持有全国呼叫中心牌照，一家专业处理银行以及小额贷款公司外包业务的公司。主要工作内容为通过电话、短信、信函提醒客户及时处理逾期；帮助客户解决还款问题。我们渴望优秀人才加入骅富的团队，为团队注入新鲜血液，骅富将为您提供广阔的发展空间、具竞争力的待遇及福利和完善的培训，为骅富美好的明天而共同努力。', 'https://www.zhaopin.com/jobdetail/CCL1330667440J40565022611.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5082, '电话销售', '北京金杉知识产权代理有限公司石家庄分公司', '5月27日', '8000-16000元', '石家庄-长安区', '专利/商标/知识产权,专利/商标/知识产权', '100-299人', '未融资', 'CCL1478809650J40598680109', '我公司是做知识产权、商标专利以及版权类的业务', '北京金杉知识产权代理有限公司河北分公司成立于2021-12-22,注册地址：河北省石家庄市裕华区槐安东路123号石家庄裕华万达广场商务综合楼2-1413-1经营范围：商务代理代办服务。商标转让与代理服务；版权转让与代理服务；企业管理咨询；企业策划（不含中介服务）；软件开发；翻译服务；电脑动画设计；设计、制作、代理、发布广告；市场调查；承办展览展示；会议服务；基础软件服务；应用软件服务（不含医用软件）；专利代理。（依法须经批准的项目，经相关部门批准后方可开展经营活动）', 'https://www.zhaopin.com/jobdetail/CCL1478809650J40598680109.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5083, '咨询顾问', '广东省国际工程咨询有限公司', '7月10日', '1.5-2万', '海口-龙华区', '咨询服务', '1000-9999人', '已上市', 'CC516805830J40138281805', '1.掌握分析公用建筑、市政工程、信息化、战略新兴产业、民生行业等社会经济各领域的最新政策、发展动态和特点；熟悉各领域建设标准、建设规范、行业规则等，掌握不同项目的评估评审、评价要点和方法。<br>2.协助完成各类财政资金支持项目的评审、绩效评价工作，包括项目调研、政策研究、数据分析和整理、文本撰写、会议组织等。<br>3.协助开展项目可行性研究策划，完成项目建议书、可行性研究报告、资金申请报告等各类工程咨询报告的撰写工作，协助解决工作中出现的问题。<br>4.与客户和团队进行沟通，准确理解把握客户需求，将工作思路和成果清晰的传达给团队及客户。<br>5.协助项目经理维护客户资源，开拓相关市场业务。<br>6.对报告进行校对，按时保质保量完成咨询任务。<br>任职要求：<br>1.学历要求：研究生及以上学历。<br>2.专业要求：经济类、管理类、理工类和工程类相关专业，具备理工+经济类复合专业背景者优先。（评估及项目咨询师助理岗位侧重工程类相关专业）<br>3.综合能力：掌握规范和系统的科学研究方法；具备快速学习分析能力、较强的语言表达和文字撰写能力；能独立思考，并注重团队合作，工作认真负责，能适应较高工作强度，有创新精神和奋斗精神。<br>4.计算机操作技能：精通Word、Excel和PPT等办公软件，掌握1-2种数据分析软件。<br>5.实践要求：具有在本公司一定时期实习经验者或具有相关工作经验者优先。<br>职位福利：周末双休、绩效奖金、五险一金、餐补、带薪年假、定期体检、节日福利<br>', '广东广咨国际投资咨询集团股份有限公司（简称广咨国际）成立于1982年，是国有相对控股的北交所上市企业，是中国工程咨询协会副会长单位，资质资信及综合实力位列全国综合咨询机构前列。下设6大事业部、5个子公司、2个专业分公司和多个区域分支机构，业务涵盖投融资咨询、政策咨询、决策咨询、采购咨询、造价咨询、建设咨询，是国家发展改革委、卫健委、国际发展合作署、商务部经合局等部委咨询服务机构，长期为广东以及周边省区的省市发改、财政、工信、住建、教育、卫健、政法、农业等政府部门以及企事业单位、金融机构、社会投资主体提供专业服务。公司完善的人力资源薪酬激励机制和培养发展机制，致力于构建行业内精英人才和专业人才施展才华的发展平台。', 'https://www.zhaopin.com/jobdetail/CC516805830J40138281805.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5084, '咨询顾问', '深圳平安融易投资咨询有限公司合肥平安大厦分公司', '4月24日', '4000-8000元', '合肥-包河区', '互联网金融/小额贷款,互联网金融/小额贷款', '1000-9999人', '未融资', 'CC409191880J40029180407', '职位描述<br>借款咨询服务<br>岗位职责:<br>1.向客户宣传，介绍公司产品，为客户提供咨询服务并促成成交，达成任务<br>2.收集反馈时长信息、客户建议<br>3.客户关系维护<br>4.参加公司组织的各项业务活动<br>5.遵守公司各项规章制度<br>应聘要求<br>1大专及以上学历<br>2:金融从业经历，营销工作经验者优先，有客户资源者优先<br>说明:薪资范围为公司对应岗位多数员工大致的实际薪酬，供参考/企业提供有竞争力的薪资标准，具体薪酬情况以当面沟通为准。<br>职位福利：五险一金、节日福利、定期团建、绩效奖金、年终分红、弹性工作、补充医疗保险、定期体检', '陆金所控股有限公司（LU.N；06623.HK）是中国领先的小微企业主金融服务赋能机构，是中国平安集团的联营公司，已在纽交所及港交所双重上市，为小微企业主提供获取普惠型产品和服务的便捷渠道，并赋能机构合作伙伴，落实普惠金融，支持实体经济。', 'https://www.zhaopin.com/jobdetail/CC409191880J40029180407.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5085, '统计员', '民生人寿保险股份有限公司', '5月13日', '5000-8000元', '石家庄-桥西区', '保险,互联网', '10000人以上', '未融资', 'CC121019160J40720644711', '职位描述：<br>1、高效处理日常事务，独立完成上级日常行程安排等工作；<br>2、按上级要求组织安排会议，及时更新日历；<br>3、谨慎处理流程性邮件、转发传达、签收登记、分类归档；<br>4、文件处理、文档处理排版，确保内容条理清晰，账单处理； <br>5、负责完成上级指派的其他工作。<br>任职要求：<br>1，形象气质佳，有驾驶经验者优先；<br>2、本科以上学历优先，秘书、中文、英文等相关专业优先；<br>3、熟练掌握电脑操作及办公软件；<br>4、理解能力强，善于沟通协调，具备较强的文字表达能力；<br>5、具有服务理念和团队合作精神；<br>6、细心、踏实，勤奋、做事积极主动，有一定抗压适应能力和学习能力强；', '民生人寿保险股份有限公司（简称“民生保险”）2003年6月18日正式开业，注册资本金60亿元，总部位于上海，建立了覆盖全国重点省市区域的机构服务网络，拥有26家分公司、近600个服务网点、近1.5万名高素质专业人员，累计服务用户超1064万人，支付理赔款总额超81亿元。截至2023年底，公司综合实力稳步提升，实现原保险保费收入119.61亿元，总资产1268.04亿元，累计十三年盈利；偿付能力充足稳定，综合偿付能力充足率202%，核心偿付能力充足率143%；监管体系评价结果稳步提升，风险综合评级四个季度均维持在BBB级。近年来，公司在立足发展保险主业的基础上，从用户多方位金融需求出发，积极稳妥布局资产管理、康养旅、基金管理及支付服务等相关领域，拥有民生通惠资产管理有限公司、通惠康养旅股份公司、通联支付网络服务股份有限公司等子公司，逐步构建具有民生特色的“保险+能源”模式。', 'https://www.zhaopin.com/jobdetail/CC121019160J40720644711.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5086, '项目招投标', '禄英达(北京)建筑装饰材料有限责任公司', '2月19日', '6000-9000元', '北京-房山区', '建材', '20人以下', '未融资', 'CCL1359793090J40702345301', '1：负责云筑网上搜集招投标信息收集； 2：跟项目对接人联系沟通 确定项目可投性及投标文件制作；', '禄英达(北京)建筑装饰材料有限责任公司成立于2021年,是一家专注于建筑材料生产及销售的企业，工厂地址位于河北省邢台，并在武汉咸阳、河北献县有自己供货商库。公司自成立以来在建跟执行项目：中建三局61个项目、中建四局10余个项目、中建五局5个项目等国家型大型项目的供货。荣获连续三年中建三局电缆、止水材料、洗车机、雾炮机集采供应商。连续两年中建四局电缆电线、配电箱集采供应商。公司主营：电缆电线、止水材料、五金制品、配电箱、瓷砖、冬施物资暖风机、洗车机、雾炮机等产品。其中2023年度电缆供货520万止水材料供货490万。公司总部位于北京市房山区天星街绿地城。', 'https://www.zhaopin.com/jobdetail/CCL1359793090J40702345301.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5087, '储备经理人', '中国平安人寿保险股份有限公司天津分公司(锦鲤团队)', '11月5日', '1.1-2.2万', '天津-武清区', '保险', '1000-9999人', NULL, 'CCL1491815770J40680012507', '集团多岗位招聘，具体如下：<br>1、【急聘人事助理】：2名，大专及以上学历，负责团队招聘和日常工作，没有销售任务，团队日常事务处理等，底薪2500元+奖金，综合薪资：4000-8000。<br>2、储备主管：3名，大专及以上学历，25岁--40岁，保底工资2000元+有责底薪+综合提成+管理收入，综合薪资：8000-2万，具体内容细节详谈。<br>3、售后/销售专员：5名，中专或高中及以上学历，23岁-45岁，保底工资2000元+有责底薪+综合提成，综合薪资：6000-1.5万。<br>4、银行客户经理：5名，大专及以上学历，25-40岁，集团有综合银行业务，存款，理财，贷款，信用卡，证券，信托等业务，有相关业务经验者优先，综合薪资：8000-1.5万。<br>5、信用卡专员：信用卡业务推广，底薪2000元+高提成+综合收入，综合薪资：7000-2万，推荐奖：200元/张起。<br>6、贷款专员：平安银行和平安普惠贷款，大专及以上学历，25-40岁，均可以直接做，底薪2000元+高提成+高奖金，综合薪资：7000-2万。<br>7、岗位福利：公司上保险，双休、法定节假日休， 年终奖金，季度定期旅游，国内外旅游活动，以及各种物资福利。<br>有意向者，欢迎投递，具体工作内容，薪资待遇详谈。', NULL, 'https://www.zhaopin.com/jobdetail/CCL1491815770J40680012507.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5088, '储备经理人', '华峰集团', '7月21日', '7000-12000元', '重庆-涪陵区', '石油/石化,零售/批发,信托,贸易/进出口', '10000人以上', '已上市', 'CC131591860J40424914407', '岗位职责：<br>1、作为储备人才跟随领导学习与成长，根据专业进行定向培养；<br>2、提高自身能力，接受公司文化，在自己的岗位上逐渐成长。<br>任职要求：<br>1、教育背景：25届或者26届本科及以上学历；<br>2、专业要求：高分子、化学工程与工艺、纺织工程、轻化工程等相关专业。<br>职位福利：五险一金、绩效奖金、带薪年假、加班补助、餐补、员工食堂、多次晋升机会、转岗/轮岗机会  <br>', '【企业简介】华峰集团创办于1991年，总部位于浙江省温州瑞安，是一家以化工新材料为主业的中国500强企业。目前集团旗下拥有50多家全资及控股公司，3家上市公司，6大产业基地。产业涉足“聚氨酯、聚酰胺、铝箔材料、可降解塑料”四大先进制造和“智能家居、数字经济、LNG”三大战略新兴产业以及物流、金融、贸易等服务领域。目前拥有员工16000余名，集团2021年全年营收680.64亿元，是国内新材料行业领军企业。', 'https://www.zhaopin.com/jobdetail/CC131591860J40424914407.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5089, 'BD经理', '浙江恒逸集团有限公司', '6月30日', '8000-14000元', '温州-瑞安市', '石油/石化,化学纤维制造业', '10000人以上', '已上市', 'CC140408290J40819144508', '岗位职责:<br>1. 通过面谈、拜访等方式深入社区，了解居民的回收需求、习惯和意见，收集相关数据。<br>2. 进行社区内废旧纺织品及废旧服装回收点位的推广覆盖，包含菜鸟驿站，社区商超等多种形态，完成签约。<br>3. 利用线上渠道，如社区微信群、站长微信等，进行回收业务的推广和宣传，吸引更多居民参与回收。<br>4. 有较好的社区站点攻坚能力，能够综合数据分析、并促成不同条件的站长参与回收。<br>5.对接公司已有合作渠道，完成渠日常运营和已有网点的维护、保障回收量提升，维护好合作关系。<br>6.公司和上级交予的其他工作任务。<br> <br>任职要求:<br>1.大专及以上学历，专业不限，市场营销类优先。<br>2.两年以上商户告拓展、品牌运营、营销策划经验，备本地生活服务类或O2O平台的经验优先，具备社区团购经验者优先。<br>3. 有较强的学习力、逻辑思维能力、数据分析能力及整合营销、谈判能力。<br>4. 对工作认真负责，吃苦耐劳，具有较强的团队合作意识<br>5.对从事地推、渠道开发工作有高度的热情，适应武汉市内长期性外勤和户外工作。<br>6.持有驾照和车辆者优先。', '浙江恒逸集团有限公司是一家专业从事石油化工与化纤原料生产的现代大型民营企业，总部位于杭州萧山，其前身为1974年创办的萧山县衙前公社针织厂，1994年正式组建集团公司。集团名列2022年《财富》世界500强榜单第264位（2021年度名列第309位），连续19年上榜中国企业500强（2022年度名列第82位），连续18年跻身中国民营企业500强榜单前50强（2022年度名列第17位）。2022年度实现营收3856.61亿元、同比增长18.21%。集团坚持以“让中国悠久的纺织历史在我们这一代人身上再次闪射耀眼的光芒”为初心，以“建百年长青基业，立世界名企之林”为使命，按照后向一体化发展路径，确立了石化产业、石化贸易、石化金融、石化物流的“石化+”战略思想，先后在全国民营企业当中率先成功涉足聚酯熔体直纺和PTA项目，与中国石化共建的己内酰胺项目被赞为混合所有制改革的样板，“一带一路”重点项目——恒逸文莱炼化项目被誉为中文两国旗舰合作项目，其中一期项目于2019年11月全面建成投产，彻底打通全产业链一体化经营的“最后一公里”。目前，集团形成了富有竞争力的涤锦“双纶”驱动模式和“柱状型”产业结构，已拥有800万吨/年炼油加工能力、2200万吨/年PTA产能和1200万吨/年涤纶及锦纶产能，成为全球最大的PTA-聚酯和己内酰胺-锦纶双产业链化纤生产商。控股企业恒逸石化股份有限公司于2011年6月在深交所整体资产上市，股票代码：000703.SZ。参股企业浙商银行股份有限公司于2016年3月在香港联交所上市（股票代码：HK02016），2019年11月在上交所上市（股票代码：601916.SH），成为A股第5家“A+H”上市股份行。在双循环新发展格局下，恒逸集团以跻身世界500强为契机，以更加积极主动的姿态融入全球产业链、供应链，努力实现上下游协同、境内外联动、软硬件配套，阔步向着国际一流石化产业集团之一的愿景前进。', 'https://www.zhaopin.com/jobdetail/CC140408290J40819144508.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5090, '广告销售', '北京天川科技发展有限公司', '7月18日', '5000-6000元', '北京-海淀区', '房地产开发,科学技术推广', '20-99人', '未融资', 'CC000619510J40759222411', '岗位职责：', '天川公司创建于1996年,主要以:智能大厦弱电系统,电视监控系统,防火防盗报警系统,出入口监控系统,公安道路监控管理系统等系统的设计.安装.调试.服务为主的高科技实体.天川公司使命:为中国智能建筑电子行业走向世界筑路领航.天川公司承接了百余项大型及国家重点工程项目:(1)弱电系统清华大学,北京大学,国家电信总局,北京军区,中央广播电视塔,国家财政部办公大楼,中国储备粮总公司等数十项弱电系统工程.(2)安防监控系统湖北公安交警大队指挥中心,北京政法大学,首都经贸大学,北京第二外国语学院.北京科技大学等数十项安防监控系统工程. 2011年,天川公司面临前所未有的市场机遇,公司进行战略性的部署,并计划以北京为中心开始大规模的启动全国市场,真诚邀请行业内外的精英及有识之士的加盟.只要付出，就有对辛苦的回报', 'https://www.zhaopin.com/jobdetail/CC000619510J40759222411.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5091, '内容审核', '沈阳阅准科技有限公司', '5月20日', '5000-6000元·13薪', '沈阳-皇姑区', '互联网', '500-999人', NULL, 'CCL1486992640J40712185616', '职位描述', NULL, 'https://www.zhaopin.com/jobdetail/CCL1486992640J40712185616.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5092, '销售工程师', 'SEW-传动设备(武汉)有限公司南昌分公司', '7月24日', '1-1.5万', '南昌-西湖区', '通用设备制造,工业自动化', '100-299人', NULL, 'CC174677720J40344219305', '德国SEW-EURODRIVE集团公司成立于1931年，是专业生产传动及变频控制设备的知名企业，当前，我们在全世界51个国家中建立了由15个生产工厂和77个驱动中心组成的庞大网络。这一数字还在不断增加。SEW-传动设备(武汉)有限公司是SEW公司的独资组装厂， 一期投资超过一千二百万美元。座落在武汉经济技术开发区的SEW-传动设备(武汉)有限公司已于2008年3月正式投产，SEW-武汉公司占地面积约四万平方米，它是SEW在中国华中地区的装配服务中心。', '德国SEW传动设备公司成立于1931年，是专业生产系列电机、减速机和变频器控制设备的跨国性国际集团，在国际动力传输领域举世闻名。SEW总部设在德国巴符州的布鲁克塞尔，在全球范围内拥有10个制造厂、56个组装厂和200多个销售服务办事处，遍步世界五大洲和几乎所有的工业国家。1997年SEW德国总部完成SEW集团在亚太地区的制造中心的筹建——SEW-传动设备（天津）有限公司。随之迅速发展：在苏州建有德国独资SEW-电机（苏州）有限公司，在沈阳、天津、苏州、广州、武汉、西安均建有SEW传动设备装配厂。在减速机行业内，SEW在中国的投资力度、发展速度、市场占有率均位于行业领导者之席。SEW减速机作为公司完美的企业形象和无瑕的商品形象的使者，为诸多国内外重大项目提供了关键设备。如：2008北京奥运会唯一传动设备（含变频器）供应商，“神州”系列卫星火箭头吊装传动设备，上海磁悬浮列车工程，三峡工程启闭机驱动，人民大、小会堂的舞台设备、中华世纪坛的坛体驱动，世界上海拨最高的西藏拉萨水泥厂球磨机，以及世界最先进的长廊皮带机——天津港焦炭码头煤炭长廊皮带机等。', 'https://www.zhaopin.com/jobdetail/CC174677720J40344219305.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5093, '律师', '山西亨昇律师事务所', '7月23日', '5000-8000元·13薪', '太原-万柏林区', '法律服务', '20-99人', '未融资', 'CCL1485138020J40712991902', '【授薪律师】【主要职责】​<br>1.法律事务处理​ <br>负责处理各类诉讼与非诉讼法律事务，负责起草各类法律文书，确保文书内容准确、逻辑清晰、格式规范，并根据案件进展及时调整策略。​ <br>负责收集、整理和分析案件证据，与客户、司法机关及其他相关方保持良好沟通，确保案件处理的顺利进行。​ <br>2.客户服务与沟通​ <br>与客户建立并保持良好的沟通关系，及时了解客户需求，为客户提供专业、准确的法律咨询和建议。​ <br>定期向客户汇报案件进展情况，解答客户疑问，确保客户对法律服务的满意度。​ <br>协助合伙人或团队负责人拓展客户资源，参与客户关系维护活动，提升律所品牌形象和市场竞争力。​ <br>3.团队协作与支持​ <br>积极配合合伙人或团队负责人开展工作，与团队成员密切协作，共同完成团队的业务目标。​ <br>参与律所组织的各项活动，促进团队内部的信息共享和经验交流。​ <br>【任职要求​】 <br>1.正规院校法学专业本科及以上学历。 <br>2.持有律师执业证书。 <br>3.精通民商事、刑事、行政等领域的法律法规，熟悉各类诉讼和非诉讼业务流程；具备优秀的法律文书写作能力；熟练使用办公软件和法律检索工具，能够高效地进行法律资料收集和整理。​ <br>4.具备一定的沟通协调能力，能够与客户、司法机关、团队成员及其他相关方进行有效的沟通交流。 <br>5.工作认真负责，严谨细致，具有高度的敬业精神和职业道德；能够承受较大的工作压力，具备良好的时间管理能力和工作效率。​ <br>6.其他要求​ <br>具有良好的学习能力和自我提升意识，能够不断适应法律行业的发展变化；有较强的保密意识，妥善保管客户和律所的机密信息。​ <br>【薪资福利​】 <br>具体薪资面议', NULL, 'https://www.zhaopin.com/jobdetail/CCL1485138020J40712991902.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5094, '猎头顾问', '锐仕方达人才科技集团有限公司', '6月23日', '6000-10000元', '青岛-市北区', '人力资源服务', '1000-9999人', '不需要融资', 'CCL1236606730J40701619514', '【工作职责】  1、为客户企业招聘年薪几十上百万的高端人才，与行业内成功人士打交道；', '锐仕方达人才科技集团有限公司（简称“锐仕方达”），2008年在北京创立，是以技术驱动的一站式人力资源解决方案供应商，也是AAAA级人力资源服务机构。目前，锐仕方达在中国、英国伦敦、柬埔寨金边、日本、新加坡等全球70多座城市设有170余家分公司，拥有5000余名员工，为客户提供核心人才招聘、人才测评、校园招聘、RPO、背景调查等全方位人力资源服务。锐仕方达独创的“CPM合伙人机制”（Risfond Cross-Partner Models）成为人力资源服务行业极具竞争优势的利益分配模式。锐仕方达自主研发的“RNSS系统”（Risfond Network Search System）已成为业内领先的IT信息管理系统。截至目前，已有超过50000家国内外知名企业选择锐仕方达招募精英，助力70000+海内外人才职业成长。作为中国人力资源服务行业第一家利用互联网思维来经营人力资源服务业务的创新型企业，锐仕方达致力于通过IT信息技术的不断创新和运用，努力创建业内更加透明和高效的人力资源生态服务机构，助力中国企业拓展全球业务市场，加入全球人才竞争格局之中是锐仕方达不变的初衷。', 'https://www.zhaopin.com/jobdetail/CCL1236606730J40701619514.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5095, '档案管理', '河北云启科创企业服务有限公司', '7月25日', '3000-4000元', '乌鲁木齐-天山区', '人力资源服务', '20-99人', NULL, 'CCL1484110930J40782158114', '薪资待遇：160/天，每周五结算上周<br>工作时间：9:00-20:00 午休一小时<br>工作内容：主要负责档案整理数字化、信息录入等工作<br>工作要求：20-38岁之间，男女不限，有档案整理工作经验，最少做4个月<br>工作位置：新疆乌鲁木齐天山区红雁池公交站附近', NULL, 'https://www.zhaopin.com/jobdetail/CCL1484110930J40782158114.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5096, '商务专员', '沈阳东大知识产权代理有限公司', '4月8日', '6000-12000元', '沈阳-和平区', '咨询服务', '20-99人', NULL, 'CC670250220J40729730210', '岗位内容： <br>', '知识产权代理公司主要任务是为企业和社会提供知识产权法律服务。资深代理人荟萃、长期服务于大学的经验累积是我们的优势；以人为本、与客户共同发展是我们的经营理念；真诚、信誉、责任、效率是我们的服务宗旨；沈阳东大知识产权代理有限公司愿以高质量的知识产权专业服务奉献给企业、高校和社会。我公司是由中华人民共和国国家知识产权局正式注册的知识产权代理机构。本代理机构是根据国务院文件规定，由原东北大学专利事务所改制而成立的，是我国专利法实施以后首批成立的专利事务所。多年来面向社会，重点服务企业和大学，从事专利咨询、专利代理、技术中介、专利诉讼、企业专利战略策划、商标注册、软件登记等服务，赢得了社会各界广泛的认可和赞同。多次获得冶金部、辽宁省、沈阳市“专利工作先进集体”荣誉称号。自专利法实施以来，为辽沈地区高等学校、科研院所、企事业单位和广大发明人代理申请专利数千项，向社会各界广泛宣传专利法，为大学生开设知识产权课程，为企业担任专利顾问。本公司还将推广专利技术，促进专利技术实施作为自己义不容辞的义务，在发明人同投资方之间架起桥梁，力促专利技术产业化，有的已经形成集团公司，为社会带来了明显的经济效益和社会效益。本公司成立至今，成绩斐然。已有多项经本所代理的专利获国家优秀发明奖。在我们代理服务过的发明人中有科学院院士、工程院院士，还有两千多名教授、副教授，近千名博士，硕士通过本公司代理申请专利，经本公司代理的专利侵权诉讼，纷纷胜诉。本公司还为一些企业成功地做了专利战略策划。本公司现有多位专利代理人，毕业于冶金材料、工业自动化、仪器仪表、电子技术、计算机、化工、机械、生物医学等学科专业，他们精通业务，有敬业精神，全心全意替委托人着想，为发明人服务，依据专利法，全力维护委托人的利益。本公司的服务宗旨是：真诚、信誉、责任、效率。在知识产权保护领域，可以为客户提供高适量的专业服务。', 'https://www.zhaopin.com/jobdetail/CC670250220J40729730210.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5097, '律师', '广东春霆律师事务所', '7月22日', '1-2万', '深圳-罗湖区', '法律服务,法律服务', '20人以下', '不需要融资', 'CCL1411132890J40331134512', '（1）法学本科以上学历，已取得律师执业资格；', '广东春霆律师事务所是经广东省司法厅批准设立的、实行公司化管理的新型律师事务所。有各类资深律师、专业律师及专业辅助人员，致力于为公司、公司股东及高管等客户提供最优质的法律服务。我们期待：驰骋多年身经百战的你；初出茅庐充满干劲的你；寻求转型渴望突破的你；让千里马和伯乐，不再千载难逢；春霆的明天，由你创造！', 'https://www.zhaopin.com/jobdetail/CCL1411132890J40331134512.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5098, '招聘专员/助理', '南方新华', '5月8日', '4000-6000元', '重庆-沙坪坝区', '人力资源服务,咨询服务,人力资源服务', '100-299人', '未融资', 'CC346219280J40732820311', '岗位职责：<br> <br>1、根据年度人力资源规划，做好人才引进与配置；<br> <br>2、发布职位信息，筛选简历，联系优质候选人参加面试；<br> <br>3、为每一位候选人提供专业的面试，做好人才评估和筛选；<br> <br>4、办理入职手续，完成薪酬谈判，offer发放背景调查等入职流程；<br> <br>5、维护智联、BOSS、猎聘等常规招聘渠道，拓展新渠道；<br> <br>6、积极完成学习成长任务，1.5倍速向着专业人力资源工作者前进。<br> <br> <br> <br>任职要求：<br> <br>1、本科及以上学历，性别不限，有招聘相关经验优先考虑；<br> <br>2、人力资源、工商管理、心理学等相关专业优先；<br> <br>3、具有亲和力，出色的沟通、协调、团队合作协调能力；责任心强，能够适应公司快速发展的工作节奏；<br> <br>4、熟练使用Office办公软件,熟悉各类招聘网站。<br> <br> <br> <br>福利待遇：<br> <br>福利：六险一金、双休、下午茶、生日福利等等。<br> <br>补贴：入职重庆大学城办公区的，安家住房补贴共计6000元。在校期间是党员、党员且班长（不含副）、党员且校学生会正副主席职务的，入职首年额外加6000-1.2万补贴。<br> <br>工作时间：8:45-18:15 中午11:45-13:15休息<br>', '南方新华，大型管理咨询型高端猎头机构，拥有近1000名猎头及高级咨询师，在北京、上海、广州、深圳、杭州、重庆、南宁、南昌等城市设有服务中心。专注于为企业提供人力资源管理咨询、猎头服务、人才测评等一流的人力资源服务。擅长互联网、财务和金融类、智能制造业、房地产、医药健康等领域的RPO及高级人才招聘咨询服务。南方新华拥有较强管理咨询基因的创始团队。创始人之一张勇毕业于中国人民大学，后留学法国，曾任职博鳌亚洲论坛副理事长蒋晓松助理，担任过北大纵横管理咨询集团人力资源咨询中心总监，曾任500强上市公司正邦集团总裁高级秘书及人力资源总监等职务。另外几位核心创始人，分别毕业于清华大学、北京大学、上海交大等名牌学校，并拥有麦肯锡、德勤等全球知名的管理咨询公司工作经历。南方新华国内首创24小时极速交付，以招聘结果为导向，为客户提供优质和高效人才招聘服务。员工多毕业于国内知名院校，具有丰富的行业中高层管理工作经验，规模国内领先，拥有著名管理咨询公司提供的咨询技术背景支持。此外，南方新华还拥有5000多万高级人才联合数据库，能够迅速匹配高端招聘岗位，平均15天招聘到位。目前，已有超过4万家多企业选用南方新华人力咨询服务。南方新华的快速发展同时也得到了社会各界的认可。2015年南方新华成为猎聘网全国优秀合作伙伴；2016年“重庆十大优秀人力资源服务机构”同年，南方新华创始人张勇获得中国人民大学校友创业大赛十大优秀创业者称号；2017年，南方新华被评选为“全国十大非凡猎头公司”；2017年，南方新华被评选为“重庆最具幸福感的企业”之一；2018年，南方新华获得重庆市教学成果奖二等奖。同年，南方新华创始人张勇获选“重庆市十大双创明星”称号。2021年，南方新华创始人张勇当选教育部全国高校毕业生就业指导委员会委员。展望未来，新华人将始终践行的核心价值理念，致力于为企业提供最高效、最专业、最有保障的招聘和管理咨询服务。我们正朝着更远大的“百千万工程”目标乘风破浪，努力实现“成为高级招聘服务领域的引领者”企业愿景，以百倍努力来回报客户的信任与支持。', 'https://www.zhaopin.com/jobdetail/CC346219280J40732820311.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5099, '社区运营', '中国平安', '7月27日', '面议', '廊坊-广阳区', '保险,保险', '10000人以上', '已上市', 'CC000204810J40800809212', '●岗位急招 招满即停(可接受无经验小白)<br>●企业文化:<br>我们固定早九晚六周末双休我们绝对不加班，下班就走，我们适合喜欢做服务，而又不想有太多工作压力的人同时对于有晋升欲望、有赚钱欲望的人，我们也给予充足的空间。人性化工作时间+周末双休不加班!<br>●福利待遇：<br>工资构成:<br>1、基础无责底薪+岗位津贴+绩效奖+季度奖+新人津贴(有金融从业经验者薪资面议)，入职半年以上收入8k+，一年以上15k+(上不封顶)<br>2、缴纳社保:养老保险。医疗保险，意外医疗、疾病医疗、生育险、失业保险+企业保险+住房公积金。<br>●工作时间:<br>早上:9:00-18:00，6小时工作制，午休两个小时。绝不加班。<br>周末双休。带薪年假，年底双薪，法定节假日带薪休假+带薪158天产假<br>●发展空间:<br>需要锻炼自己、提升自己，那么平台就很重要，上市公司五百强晋升培养机制完善，管理岗位需求大，对于有晋升意愿的伙伴提供职位直升扶持!<br>绝对的公平公正公开，全靠实力，全是实力派。<br>●培训<br>不用担心自己不会哦<br>1、新人入职了解公司、熟悉产品、超简单、这么聪明的你肯定没问题。也有平安大学做后盾<br>2、培训结束，公司分配师傅、组长、团队主管手把手教<br>●工作环境:<br>1、5A级舒适的办公环境(氛围融洽友好，团队年轻而富有活力)<br>2、员工旅游+员工生日会+发放丰厚的奖励，优秀员工每月有表彰(超多惊喜等你一起)<br>3、每年5-15天带薪年假(幸福感超足哦)<br>4、享受国家法定婚假产假以及陪产假等(一起见证你人生的每一个重大时刻)<br>5、琳琅满目的零食、咖啡、饮料、下午茶(工作的同时放松一下)<br>6、丰富的企业活动，团建聚餐等<br>●●●员工关怀<br>1.为员工提供多途径反馈工作、生活中遇到的问题困难，通过面对面圆桌会，线上答疑等方式给予解助<br>2.为家庭特别困难员工提供帮助，领导可爱同事暖心', '中国平安致力于成为国际领先的科技型个人金融生活服务集团。2019年，中国平安深入推进\\\\\"金融+科技\\\\\"、\\\\\"金融+生态\\\\\"战略转型，持续提升数据化经营能力，整体业绩及核心金融业务持续稳健增长，科技赋能成效显著，生态赋能效果初显，综合金融用户数、客户数、客均合同、客均利润均有明显增长。公司实现营业收入同比增长19.7%至11,688.67亿元。截至2019年底，公司个人客户数首次突破两亿，互联网用户量达5.16亿，全年新增客户数3,657万，其中40.7%来自集团五大生态圈的互联网用户。中国平安始终践行\\\\\"金融为实体经济服务\\\\\"的精神，坚持把实体经济服务作为出发点和落脚点，通过旗下的保险、银行、信托、金融科技等业务，把逾4万亿金融资源配置到经济社会发展的重点领域和薄弱环节，包括通过保险保障、提供贷款、债权股权计划、普惠金融等多种方式，全面助力实体经济发展。凭借全球领先的创新科技，中国平安将科技深度运用于金融主业中，助力降本增效、风险管控，打造优质产品和极致服务体验，提升客户口碑。与此同时，平安将领先科技广泛应用在金融、医疗及智慧城市等领域，全面支撑\\\\\"金融服务、医疗健康、汽车服务、房产服务、智慧城市\\\\\"五大生态圈建设。在企业社会责任方面，平安深化可持续发展理念，MSCI ESG评级连续两次调高至A级，打造AI-ESG平台赋能责任投资，截至2019年12月末，公司责任投资规模达9,544.49亿元，可持续保险金额达121.21万亿元，绿色信贷年度授信总额590.56亿元。同时，平安积极响应国家脱贫攻坚战的号召，推进\\\\\"三村扶贫工程\\\\\"项目，累计提供专项扶贫资金249.05亿元。面对新冠肺炎疫情，平安第一时间推出保险保障、医疗支持、对外捐赠等多重支持举措，提供的物资及现金捐赠总额超1.75亿元。2020年，中国平安品牌价值持续提升，名列美国《财富》“世界500强企业”第21位，居全球金融企业第2位，《福布斯》全球上市公司2000强第7位，BrandZ™全球品牌价值100强第38位，蝉联全球保险品牌第1位。', 'https://www.zhaopin.com/jobdetail/CC000204810J40800809212.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (5100, 'APP推广', '深圳南区人瑞人力资源服务有限公司', '7月17日', '1-2万', '中山-None', '企业服务', '10000人以上', '已上市', 'CCL1289361510J40753649501', '美团小象超市开城急招！！！<br>新城新站可就近安排，绝佳机会不容错过！<br>一、岗位详情<br>1. 作为小象超市的推广先锋，你将肩负起线下推广小象超市app的重任，不断拉新用户，并全力维护用户复购，让更多人体验到小象超市的便捷与优质。<br>2. 摆点、散推、扫楼扫店……地面推广形式任你选择，充分发挥你的创意与能力 ，开拓市场。<br>3. 我们的目标客户群体极为广泛，就像河马、叮咚等生鲜超市一样，所有人都有可能成为小象超市的忠实用户，市场潜力无限。<br>二、薪资待遇<br>1. 综合底薪+首单提成+复购提成，收入上不封顶；<br>综合底薪3200元+全勤400元，+首单提成+首单GMV提点+复购提成；综合薪资10 - 20K+ 。<br>2. 入职即缴纳六险一金，<br>3. 多劳多得，你的付出与收获成正比。<br>三、上班时间<br>时间自由、弹性打卡，自己的时间自己安排 <br>如果你渴望挑战自我，追求高收入；如果你热爱销售，善于与人沟通；如果你想加入互联网大厂，在新零售领域大展宏图，那就不要犹豫，速来加入我们', '人瑞是中国领先的综合人力资源解决方案提供商数字化时代，人才供应链必须契合企业数字化战略下的业务发展需要人力资源管理的使命，在于构建人才管理数字化与企业战略、业务数字化的连接和应用人瑞坚持以效果为导向的人力资源服务模式，依靠技术驱动人力资源的服务能力，通过强执行力的组织体系与专业团队,为客户提供满意的、适应数字化需求的人力资源一体化服务！', 'https://www.zhaopin.com/jobdetail/CCL1289361510J40753649501.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8901, '内容审核', '广州欢创信息咨询有限公司', '7月7日', '4000-5000元·13薪', '石家庄-裕华区', '人力资源服务,咨询服务,专业技术服务,人力资源服务', '100-299人', '未融资', 'CC531289680J40753648409', '工作内容：<br>主要负责对平台上用户发布的图片、机位进行评分、审核<br>  薪资：综合4500-5000，入职六险一金  <br>  <br>', '广州欢创信息咨询有限公司是一家全国性集团公司，以技术驱动的整体人·财解决方案服务商，全国80+自营分公司，500+服务网点，公司拥有人社局颁发的劳务经营许可、人力资源服务许可等相关行业资质，已获得行业门槛较高的《增值电信业务经营许可证》，同时是众多大型企业的呼叫中心外包服务商。已顺利通过IS09001质量管理体系认证，荣获第七届世界军人运动会后勤保障突出贡献奖、美的集团优秀人才供应商、58集团颁发中国卓越雇主奖、招商银行薪酬福利典范企业，是行业规模、专业素质和客户满意度方面均位居前列的人力资源、税务筹划综合服务商。', 'https://www.zhaopin.com/jobdetail/CC531289680J40753648409.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8902, 'BD经理', '达能(中国)食品饮料有限公司', '2025-07-27 00:30:40', '5000-7000元', '苏州-None', '快速消费品', '1000-9999人', '已上市', 'CC141296830J40730333016', '发展管辖范围内的销售利润，提升潜力门店的执行（A/B/C类）<br>1. 每日晨会与SV回顾关键KPI达成。<br>2. 根据SV等上级要求每周参加周培训。<br>3. 每日按路线100%完成客户拜访并按要求合规提交各类材料（包括但不限于店内执行/IR拍照/库存检查/促销沟通/活动管理/费用兑付等），保证提交材料的真实性及客观性（包括但不限于向材料涉及各方核实等），发现（含间接了解）对接、跟进的各类BP/DP、批发及终端门店有违规、违约或不符合公司政策要求之行为时及时指出，同时书面上报相关情况，禁止任何默许、甚至参与违规违纪事项之行为；订单闭环确认，开发新潜力售点，推动Blue Sky 达成和提升。<br>4. 门店季度签约，核查并上报签约内容在门店的落地执行。<br>5. 月度拜访BP/DT，提升配送服务（包括但不限于回顾闭环确认/价格管理/SKU管理等）；定期（月度及年度）进行库存及库龄盘点，核查BP/DP的库存/库存天数/货龄等，并向公司上报真实、准确的数据。<br>6. 区域内主数据管理，新开及关闭相应客户，不断优化线路客户质量。<br>7. 依据达能WISE要求，遵守安全条例，确保在安全的环境下工作。发生安全情况时，应该按WISE规定的申报方式、途径、时间要求等流程进行如实申报。<br>8. 根据公司要求妥善保管和使用公司分配给个人的设备和工作账号，包括但不限于公司手机、企业微信账号、*******系统账号、工作邮箱等均只能本人使用，严禁擅自外借设备或向他人泄露工作账号密码。<br>9. 对本人经办业务的工作合规情况（包括但不限于开设的业务合作伙伴档案、上传的销售数据、签署的业务文件、日常销售工作【含费用兑付、终端商业信息/联系方式、真实收货微信情况等】、各类费用报销等）真实性负责，并通过官方途径等多渠道进行核实（如公开企业信息平台、国家税务系统、公司销售系统、业务合伙伙伴系统、相关业务往来材料【微信、手机号等联系方式】等）。<br>10. 高中及以上学历；<br>11. 有销售一线工作经验者优先；<br>12. 肯实干，有韧性，积极乐观；<br>13. 总是想办法，让事情发生；还能影响他人，实现共赢！', '达能集团达能集团是世界500强企业，也是全球最成功的健康食品企业之一。达能以\\\\\"通过食品，为尽可能多的人带来健康\\\\\"作为企业使命，履行这一使命为达能实现持续强劲增长做出了重大贡献。达能集团的业务遍及全球五大洲120多个国家和地区，拥有184家工厂和约101,000名员工。2010年，达能实现的销售额达170亿欧元。达能在健康食品的四个领域占据领先地位：鲜乳制品（全球第一）、饮用水（包装水市场全球第二）、婴儿营养品（全球第二）和临床营养品。达能集团在巴黎的欧洲交易所（Euronext）上市，同时公司也被纳入反映社会责任的主要指数，例如：道琼斯可持续发展全球指数（STOXX and World指数），ASPI Eurozone指数, Ethibel可持续发展指数等。这体现了达能的商业模式，即，不仅为股东创造价值，还考虑到员工、商业伙伴、公共当局和当地社区在内的所有相关利益。达能集团于上世纪80年代进入中国发展业务，目前在所经营的四大核心业务领域获得了领先地位,同时拥有包括脉动、多美滋、贝乐嘉、纽康特、碧悠等知名品牌。达能中国饮料达能（中国）食品饮料有限公司（简称“达能中国饮料”）是达能下属企业，在快消领域处于领先地位。达能中国饮料管理总部于2008年11月在广州成立，员工约7000名。公司以“致力于给各个年龄层和场合的消费者提供愉悦与健康的饮用体验”为愿景，深耕中国饮用水和饮料市场。在中国，达能中国饮料拥有脉动维生素饮料、脉动新产品能量饮料、极境之兰饮用天然泉水等产品，近年来，随着脉动的快速发展，它已经成为中国饮料市场的一个知名品牌。关注职业发展达能中国饮料的业务文化为“敢精神”，提倡敢卓越、敢创新、敢合作助力业务发展。公司高度关注员工安全、健康和发展，有一系列的人才发展计划，支持员工成就职业追求。我们注重集体影响力和团队协作，在活力而创意十足的工作氛围中，在授权与开放的领导力风格影响下，每个人能够释放潜力，拥有职业发展。在达能，我们相信，创建包容性和多元化的团队是达能未来的核心之一。所有符合条件的申请人都将得到平等的对待，我们不以应聘人员的年龄、种族、民族、肤色、宗教信仰、国籍、性别、性取向、退伍军人身份、遗传信息或残疾状况等作为是否招聘的依据。践行社会责任一直以来，达能中国饮料以实践企业社会责任为己任，对水源保护、生态恢复、气候变化、社区共享价值、可持续农业和可持续包装进行大力投入。在这里，你也可以为改善社会做出贡献。', 'https://www.zhaopin.com/jobdetail/CC141296830J40730333016.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8903, '资料管理', '合肥泓泉档案信息科技有限公司', '7月23日', '2000-3000元', '合肥-蜀山区', '计算机软件,印刷/包装/造纸,广播/影视', '100-299人', '未融资', 'CC272043380J40758143711', '工作内容：主要负责各类型档案整理、分类、编码、扫描、著录，打孔、装订（分工协作）<br>岗位职责：工作态度端正，有责任心，应变能力强，打字速度快，具备良好的团队合作精神，服从公司安排。', '合肥泓泉档案信息科技有限公司，2015年03月12日成立，位于合肥市黄山路时代数码港，经营范围包括软件的研发及销售，档案规范化及信息化服务，档案整理、扫描、备份、缩微、存储服务，档案用品及设备、档案盒、档案密集柜、防磁柜、光盘柜销售，网络安全用品、家具、设备计算机、扫描仪的销售，安防设备的销售与安装，人力资源咨询服务等。', 'https://www.zhaopin.com/jobdetail/CC272043380J40758143711.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8904, '电话客服', '鑫车投资(上海)有限公司', '6月23日', '90-100元/天', '上海-长宁区', '汽车金融', '1000-9999人', '已上市', 'CC441584130J40528874416', '岗位职责:<br>【工作职责】<br>1.外呼任务，去电联系公众号中奖客户，协助礼品邮寄等事宜；<br>2.质检客服录音，对客服电话录音进行评估，帮助客服人员提高服务水平；<br>3.质检账务勾稽，根据标准勾稽流程反查账务组人员的勾稽操作是否规范。<br> <br>任职要求:<br>任职资格：<br>1.大专以上在读生，每周能够出勤五天优先；<br>2.性格开朗，良好的沟通能力，应变能力；<br>3.熟练使用办公软件。', '易鑫（02858.HK）是一家 AI驱动的金融科技平台，成立于 2014年 8月，2017年 11月在香港联交所上市。公司以科技驱动业务创新，致力于为消费者提供普惠、便捷的汽车融资及增值服务，并通过 AI驱动、科技赋能，为汽车金融产业链合作伙伴提供完整高效的金融科技解决方案。', 'https://www.zhaopin.com/jobdetail/CC441584130J40528874416.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8905, '储备干部', '中国人寿保险股份有限公司郑州市分公司', '6月3日', '8000-14000元', '郑州-金水区', '保险', '1000-9999人', '已上市', 'CC253842210J40744171802', '岗位内容：<br>1. 参与公司核心业务、关键项目的策划与推进；<br>2. 负责产品市场调研、推广以及销售渠道的拓展工作；<br>3. 制定并执行品牌宣传计划，提升公司品牌形象和知名度；<br>4. 辅助主管工作<br>任职要求：<br>1. 专科及以上学历，储备经理人工作经验；<br>2. 精通市场营销理论，对于大数据、数字化运营等有很好的敏感度；<br>3. 具备良好的语言表达、文字撰写与演讲能力；<br>4. 具有商业敏锐度和逻辑思维能力，善于团队协作。<br>晋升空间大，福利待遇好', '中国人寿保险（集团）公司是目前国内最大的综合性保险集团，是国务院100%控股的世界500强副部级央企。下设中国人寿保险股份有限公司、中国人寿资产管理有限公司、中国人寿财产保险股份有限公司、中国人寿养老保险股份有限公司等多家公司和机构，业务范围全面涵盖寿险、财产险、养老保险、资产、实业投资、海外业务等多个领域。中国人寿是中信证券第二大股东、广东发展银行第一大股东、民生银行、中粮期货、南方电网第二大股东。中国人寿郑州市分公司招募首批新型大学生服务团队中国人寿郑州市分公司一直服务于郑州市城乡建设，在郑州市所有县区设立分支机构，在全市80%以上的乡镇设立服务部，目前服务窗口正在向村级延伸。自2001年起，开始陆续为河南省省直机关以及郑州市220万城镇职工、城镇居民提供大额补充医疗服务，具有常年经营意外保险、健康医疗保险以及政府委托经办业务等丰富的管理经验和能力。2011年，在郑州市政府的支持下，中国人寿郑州市分公司创新性地经办了新农合业务，并于2013年开始承办农村居民大病保险业务，服务于430万农村居民，“郑州模式”得到全国广泛关注。', 'https://www.zhaopin.com/jobdetail/CC253842210J40744171802.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8906, '英语翻译', '邦壮电子材料有限公司', '7月27日', '8000-9000元', '廊坊-霸州市', '金属制品业', '100-299人', '不需要融资', 'CC293336580J40584729208', '岗位职责：<br>1.负责公司日常英语及商务合同的资料翻译，包括客户接待和现场翻译；<br>2.翻译资料的整理和归档保存，以及参与部门内的专业培训与交流，以提高翻译的专业水平。<br>3.负责国外客户的来访接待工作，包括沟通、交流及公司高层管理人员与外商谈判的翻译。<br>4.协助其他部门完成所需的翻译工作，如生产资料的中外文互译。<br>5.国外客户及相关订单对接厂内生产部门，异常反馈、客户返款跟踪。<br>6.日常负责国外客户项目的业务跟单工作。<br>任职要求：<br>1.要求口语交流无障碍，可翻译合同、文件，与外国客户沟通<br>2.可接受应届生<br>3.25周岁-50周岁<br>4.大专及以上，商务英语或英语翻译类专业优先', '邦壮电子材料有限公司是生产电子焊接材料的专业公司，成立于1986年，占地39221.6平方米，总资产3.2亿元，公司主要产品有半导体引线框架、焊锡膏、BGA焊球、焊环、焊片、焊带、焊丝、阳极球、无铅焊料、铜粒、玻璃珠等产品。本公司始终秉持着“以客户为中心，以奋斗者为本”，竭力满足客户的需求；给公司员工以最大的发挥空间。我司经过了近30年的发展，2023年度公司销售收入38000万元，其中引线框架销售收入36000万元。主要客户日月光半导体、捷敏电子、通富微电子、威世半导体、台湾强茂电子、达尔、长电、捷捷微电子、无锡新洁能、固鍀电子、虹扬、扬杰、芯诺电子等。2020年我司投资2亿元，在霸州新区征地35000M2,目前土地已经落实正在办理规划、环保、建设等手续，项目一期于2021年10月份投产。', 'https://www.zhaopin.com/jobdetail/CC293336580J40584729208.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8907, '售后客服', '中国人寿保险股份有限公司南京市分公司收展营销服务部', '7月9日', '6000-12000元', '南京-鼓楼区', '保险,保险', '10000人以上', '已上市', 'CC606591220J40702262015', '工作内容：<br>1.vip客户礼品发放<br>2.vip客户资料变更入档<br>3.理赔办理<br>4.缴费告知<br>5.为vip客户提供售后服务<br>6.活动通知 客户二次开发<br>7.投诉处理<br>办公室坐班<br>正常工作制<br>全职工作<br>不是营销部门，不要买保险<br>职位要求:<br>1.年龄21周岁~45周岁，大专以上学历<br>2.熟悉办公软件<br>3.做事细心谨慎<br>工作时间:<br>8:30-11:30 14:00-17:00双休 不加班 法定节假日带薪休假', '中国人寿保险（集团）公司是中央管理的国有大型金融保险企业，前身是成立于1949年的原中国人民保险公司。公司已连续20年入选《财富》杂志“世界500强”，2022年位列第40位，较2020年提升5个位次。在此前世界品牌实验室发布的2022年“中国500最具价值品牌”，品牌价值高达人民币4525.39亿元，在中国保险业蝉联第一。中国人寿保险股份有限公司江苏省分公司（简称“江苏国寿”）是中国人寿保险（集团）公司核心成员——中国人寿保险股份有限公司在江苏的分支机构。自1996年产寿险分业经营以来，公司主动融入江苏经济社会发展大局，承载初心使命，一路攻坚克难，始终保持着中国人寿系统、江苏寿险市场“双领先”地位，在服务“强富美高”新江苏建设中积极发挥行业龙头的引领作用。', 'https://www.zhaopin.com/jobdetail/CC606591220J40702262015.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8908, '网络销售', '深圳市华达佳科技有限公司', '7月25日', '5000-8000元', '深圳-南山区', '计算机硬件,计算机软件', '20-99人', '未融资', 'CC418164328J00382960501', '线上平台销售<br>岗位要求<br>1. 计算机及机械自动化专业优先考虑；<br>2. 及时掌握公司的产品和推广策略及其他销售工作要求；<br>3. 在部门经理的带领下，实现个人业绩目标；<br>4. 与其他部门同事协作，充分把握客户需求，完成售前服务，跟进售后服务；<br>5. 根据客户需求和市场变化，对公司的产品和服务提出改进建议。<br>6. 管理和协调能力强，有上进心的应届毕业生优先。<br>其他待遇和要求：<br>1. 有一定的网络平台销售经验优先（如天猫，京东），善于与人沟通；<br>2. 能承受销售压力，有拼搏精神，完成公司，部门制定的销售任务；<br>3. 亲和力好，有团队荣誉感，热爱销售工作；<br>4. 心态积极向上，阳光、有朝气、有激情；<br>5. 有清晰的职业生涯规划，目标明确；<br>薪酬福利：<br>1、基本工资（5000-8000） + 绩效提成；<br>2、转正后：五险一金 ；定期体检；年度旅游；带薪年假；交通补贴；节日补贴<br>3、工作时间：双休 5*8小时<br>4、广阔的职业发展空间和晋升通道； 丰富的培训资源及学习机会<br>职位福利：五险一金、绩效奖金、全勤奖、带薪年假、节日福利、定期体检、员工旅游、交通补助<br>', '深圳市华达佳科技有限公司创办于2009年，自创立以来一直致力于工业计算机、测量、自动化控制及机器视觉等领域的产品研发生产、技术整合与创新。持续为智能制造、人工智能、半导体、汽车电子、医疗、物联网、电子警察、智能交通和电力等行业客户提供高品质一站式服务，以及优异性价比的硬件系统解决方案。', 'https://www.zhaopin.com/jobdetail/CC418164328J00382960501.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8909, '销售助理', '中船汉光科技股份有限公司', '7月1日', '2000-4000元', '邯郸-丛台区', '专用设备制造,专用设备制造,印刷/包装/造纸', '100-299人', '已上市', 'CC559481620J40751458509', '岗位职责： 1、负责和客户相关的一切事务，包括建立客户档案、跟单发货、信用管理、对账、跟催帐款、开具发票等工作；', '中船汉光科技股份有限公司成立于2000年，是为建设国家“863”计划的重大项目“OPC鼓产业化项目”，由河北汉光重工有限责任公司、中国科学院化学研究所等多家单位共同出资组建。2020年公司在深圳证券交易所创业板上市，股票代码300847。公司主要从事打印复印静电成像耗材及成像设备的研发、生产和销售，主要产品为墨粉、OPC鼓、信息安全复印机、特种精密加工产品，其中墨粉和OPC鼓是打印机、复印机、多功能一体机的核心消耗材料。公司是国内既有多功能复合机整机生产，又能大规模生产墨粉和OPC鼓等办公设备耗材的企业，是国内打印复印静电成像耗材主要生产厂商之一。', 'https://www.zhaopin.com/jobdetail/CC559481620J40751458509.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8910, '网络客服', '博岳通信', '7月6日', '6000-8000元', '石家庄-裕华区', '运营商/增值服务,IT服务,通信/网络设备', '10000人以上', NULL, 'CC351377410J40752512801', '【工作亮点】不加班、带薪年假，工龄工资，节假日三倍薪资；提供住宿、接受应届生、能开实习证明，带薪年假。<br>【工作内容】<br>代表抖音官方审核用户的订单，根据用户发起的仲裁问题进行判责处理<br>【任职要求】<br>1、男女不限<br>2、20--35周岁，沟通无障碍；掌握基本的电脑操作；<br>【上班时间】<br>固定长白班早九晚六 不加班！<br>【薪资福利】<br>试用期收入：5000左右；转正后：6000-10000+', '河北博岳通信技术股份有限公司是一家大型的电子商务、呼叫中心运营及信息服务供应商，主要从事大数据建模/分析/应用、呼叫中心运营、运营商业务渠道、云服务、网络与信息服务业务。专注于为运营商、电子商务、金融、互联网企业和中小企业提供端到端的运营及服务解决方案。公司现有员工15000名，拥有运营坐席超过16000个，目前在北京、河北、四川、湖南、江西、辽宁、福建、宁夏、贵州、浙江、陕西等多个省市设有分公司和办事处。在大数据应用和呼叫中心运营领域，博岳股份与全国十几个省市通信运营商客户进行了全面合作,包括北京移动、中国移动咪咕公司音乐基地、咪咕动漫、四川移动、河北移动、河北铁通、宁夏移动、卓望信息、辽宁移动、江西移动、陕西移动、湖南电信、贵州联通、虚商迪信通；博岳股份与十几家互联网企业在运营和服务领域进行全方位的合作，包括小米科技、去哪网、多点生活、牛电科技、海选网运营支撑服务；博岳与互联网金融九鼎投资-借贷宝进行了全方位的战略合作，包括人人行客服、人人行催收、人人推和研发合作。博岳股份全面服务于通信运营商、金融、电商及互联网企业，服务用户超过5亿。在云服务领域，基于互联网模式建立了端到端的云客服平台，向互联网企业和各中小企业提供系统平台、数据库、数据建模及分析、物理场所、台席、人员及培训等端到端解决方案；为互联网企业和各中小企业提供快速、便捷、性价比高的优质服务。同时公司根据客户的需求，为客户设计完整的呼叫中心解决方案，并负责呼叫中心的建设、运营与维护，承接客户的对外联络、咨询、投诉、问卷调查、营销、客服等各项工作。作为河北省高科技企业，博岳股份于2016年3月份成功挂牌新三板。公司具备工信部颁发的“中华人民共和国增值电信业务经营许可证（全国呼叫中心业务许可证、河北省因特网信息服务业务许可证）”、“通信信息网络系统集成乙级”及“道路运输经营许可证”等资质，并且通过了ISO9001质量管理体系和ISO14001环境管理体系等权威认证。博岳股份立志发展成为业界一流的信息服务和网络服务提供商，博岳股份全面向世界优秀企业学习。博岳股份吸纳业界优秀人才，聚焦客户、聚焦业务，实现平台化和规模化的管理和运作，公司将秉承“以客户为中心、以贡献者为本、持续艰苦奋斗”的企业核心价值理念，我们相信通过全体员工的不懈努力和追求，一定能够为客户提供最好的解决方案和最优质的服务，并为客户实现商业成功!', 'https://www.zhaopin.com/jobdetail/CC351377410J40752512801.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8911, '咨询顾问', '平安融易(黑龙江)信息服务有限公司南京山西路分公司', '8月13日', '1.2-2.3万', '南京-鼓楼区', '互联网金融/小额贷款', '10000人以上', '未融资', 'CC503380330J40546521004', '岗位职责：<br>1.向客户宣传、介绍公司产品，为客户提供咨询服务并促成成交，达成任务；<br>2.客户关系维护；<br>3.参加公司组织的各项业务活动；<br>4.遵守公司各项规章制度。<br>任职要求：<br>1.大专及以上学历；<br>2.有金融、房产、汽车销售从业经历优先考虑；<br>3.较强的市场开拓能力、良好的沟通能力；<br>薪酬福利与晋升发展<br>1.底薪+提成，六险一金；<br>2.带薪假期：享受婚嫁、产假、病假、丧假、年假等；<br>3.节假贺礼：生日福利/重大节日福利/礼品/礼金等；<br>4.公司活动：工会活动、绩优员工激励等；', '陆金所控股有限公司是中国领先的小微企业主金融服务赋能机构，是中国平安集团的子公司。陆金所控股为小微企业主提供普惠型产品和服务，并赋能机构合作伙伴，落实普惠金融，支持实体经济。陆金所控股在美国纽约证券交易所、香港联合交易所两地上市。', 'https://www.zhaopin.com/jobdetail/CC503380330J40546521004.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8912, '储备经理人', '杭州诺文品牌策划有限公司', '12月10日', '5000-10000元', '杭州-萧山区', '耐用消费品,家具制造,贸易/进出口,互联网', '20-99人', NULL, 'CC328245031J90250020000', '任职条件：<br>1、大专或以上学历，应届毕业生亦可； <br>2、年龄22周岁 以上； <br>3、有较好的沟通能力和亲合力；<br>4、愿从基层做起，能承受一定的工作压力，愿意挑战高薪，挑战自己；<br>5、有团队组建或管理经验者优先。 <br>6.正式员工交五险<br>7.业务+提成+年终奖,带薪年假<br>8.国家假期正常放假<br>职位福利：五险一金、绩效奖金、带薪年假、加班补助<br>', '诺文机构:上海诺文服饰有限公司杭州诺文品牌策划有限公司福建石狮诺文服装辅料厂杭州诺文品牌策划有限公司是诺文机构旗下杭州公司，本公司专业致力于服装辅料设计，研发，生产，销售，为广大服装企业提供一站辅料解决方案.公司拥有一支多年行业工作经验的核心团队，能与时俱进，不断开发，创新，能够更好的服务于广大服装企业为广大客户提供时尚、前沿、新颖、专业的产品，合理节省成本，提高价格优势，更好的提升品牌价值，提高市场占有率。主营产品：吊牌、吊粒，商标织唛、织带，纽扣、五金配件户外服装配件，拉头，皮标，滴塑标，包装印刷产品等', 'https://www.zhaopin.com/jobdetail/CC328245031J90250020000.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8913, '律师助理', '北京树成律师事务所', '7月25日', '8000-12000元·13薪', '北京-朝阳区', '法律服务', '100-299人', '不需要融资', 'CCL1280910500J40283749314', '【岗位职责】<br> <br>1.协助团队开展具体的法律服务工作；<br>2.负责法律法规等信息资料的检索、收集和整理工作；<br>3.负责起草所承办业务的各类法律文书；<br>4.完成由业务延伸的其他工作。<br> <br>【任职资格】<br> <br>1.法学专业本科及以上学历；<br>2.通过法律职业资格考试取得A证；<br>3.认同律所一体化的管理理念；<br>4.法学理论功底扎实；<br>5.具备较强的语言表达能力、逻辑分析能力和文书写作能力；<br>6.工作踏实认真，有较强的抗压能力和责任心。<br>', '树人律师事务所是成立于2003年5月的一体化律所，以根据客户需求来组建与案件需求最为匹配的专业律师团队为服务模式，为客户提供最及时和优质的服务，目前树人所已经在西宁、北京、成都设有办公室，业务遍及20多个省份，树人所曾荣获“全国优秀律师事务所”、“全国律师行业先进党组织”、“全国优秀法律顾问”称号，并连续两年荣登“钱伯斯”（Chambers）榜单。律所核心聚焦在矿产资源、金融证券两大行业，以高端民商事诉讼、并购重组为核心优势，同时为大中型企业、政府部门、事业单位提供专业的常年法律顾问。我们的使命是做一家百年律所，用行业领先的专业法律服务能力，助力与成就每一个客户。', 'https://www.zhaopin.com/jobdetail/CCL1280910500J40283749314.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8914, '广告销售', '西安盛极通数据信息科技有限公司', '7月22日', '4000-7000元', '西安-未央区', '休闲/娱乐,在线生活服务（O2O）', '20人以下', NULL, 'CCL1502330140J40744465010', '主要职责：  <br> <br>1、进行市场调研，了解行业动态、竞争对手情况以及市场需求；<br> <br>2、分析市场数据，预测市场趋势，为企业的战略决策提供数据支持；<br> <br>3、建立和维护客户关系，包括新客户开发和老客户维护。。协调处理客户问题，提高客户满意度和忠诚度；<br> <br>4、定期与客户沟通，了解客户需求变化，提供定制化服务方案；<br> <br>5、拓展商务合作伙伴，建立长期合作关系；<br> <br>6、参与商务谈判，争取最有利的合作条件和条款，跟踪合作项目的执行情况，确保合作顺利进行；<br> <br>7、收集和分析商务数据，如销售数据、客户数据等；<br> <br>8、定期向管理层汇报商务数据和分析结果；<br> <br>9、与销售、市场、产品等部门密切合作，共同推动业务发展，协调内部资源，确保商务工作的顺利进行；<br> <br>10、积极参与团队建设活动，提高团队凝聚力和协作能力；<br> <br>11、熟练掌握、了解我司产品包含各类项目及权益，明确清楚各项权益的使用方法；<br> <br>12、具有良好的沟通交流能力，解答，宣传产品上清晰准确；<br> <br>13、配合公司团队完成所有市场营销活动，包括但不限于临时外出；<br> <br>14、及时完成领导交办的临时性工作。<br>', '盛极通成立之前，主营河北数字文旅一卡通，该卡是由省厅推出以及当地城市文旅局合作的数字景区年票卡。现资源整合，凭借对数字文旅产业的深刻理解和丰富的运营经验，主营文旅卡以及大数据信息收集，做本地生活服务商家合作以及文旅惠民卡的推广。布局广泛，分布西安、石家庄、保定、承德。', 'https://www.zhaopin.com/jobdetail/CCL1502330140J40744465010.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8915, '档案管理', '郑州市天明质量认证咨询有限公司', '3月20日', '5000-9000元', '郑州-金水区', '检测/认证,咨询服务,培训/辅导服务', '100-299人', '未融资', 'CC358552229J90250003000', '郑州市天明质量认证咨询有限公司成立于2010年4月，是根据中华人民共和国有关法律法规，经中国认证认可协会批准备案（批准号：CCAA-ZX-2016-008），在郑州市工商局登记注册，具有独立法人资格的认证咨询机构。<br>现根据企业发展需要，聘如下岗位：<br>办公室文员<br>主要岗位职责：<br>1、编辑与审核日常信息稿件；<br>2、单位信息的挖掘和采写；<br>3、舆情信息的收集、编辑和报送；<br>4、基本信息宣传材料的编辑整理；<br>5、参与单位重要材料撰写；<br>6、会议与培训、业务与科研；<br>7、完成领导交办的其他工作。<br>任职条件：<br>1、大学本科毕业优先。<br>2、热爱认证工作，具有较强的责任心和使命感，作风正派，公正廉洁，坚持原则，顾全大局，乐于奉献；<br>3、较强的团结协作精神和良好的沟通与协调能力；<br>4、身体健康，能适应本岗位工作要求。<br>福利待遇： <br>1、基本工资+绩效+全勤+福利+保险； <br>2、带薪培训：公司免费为每个新入职的职工提供带薪岗前培训，有无经验均可; <br>3、晋升渠道：公司提供完善的晋升体制，晋升空间大，待遇丰厚； <br>4、上班时间（冬令时）：上午8:30-12:00，下午13:30-18:00；<br>上班时间（夏令时）：上午8:00-12:00，下午14:00-18:00；<br>做六休一，国家法定节假日正常休息。 <br>企业官网：http://www.hntmrz.com<br>诚挚欢迎您的到来！真诚期待相互共赢！', '郑州市天明质量认证咨询有限公司，成立于2003年1月，是根据中华人民共和国有关法律、法规，经国家认证认可协会批准备案(批准号：CCAA-ZX-2016-008)，在郑州市工商局登记注册，具有独立法人资格的认证咨询机构。公司业务范围包括：ISO9001质量体系认证、ISO14001环境体系认证、ISO45001职业健康安全体系认证、HACCP/ISO22000食品卫生安全体系认证、IATF16949汽车行业体系认证、有机产品认证、ISO27001信息安全体系认证、ISO20000 IT服务体系认证、ISO13485医疗管理体系认证、诚信管理体系认证、能源管理体系认证、QC080000认证、SA8000认证、ROHS认证、HSE石油行业健康安全环境认证、GAP农业良好操作规范、CE产品认证、森林体系认证、高新技术科技企业、商标专利、知识产权管理体系认证、碳足迹排放认证、AAA信用评级以及审核员培训的服务。通过本公司咨询而获得的认证，是被广泛认可的，是全球多边承认的。本公司与多家国内权威机构建立了良好的合作关系。专业涉及冶金、机械、电子、电力、交通服务、通讯服务、行政管理服务、机关服务、化工、采矿、建筑、建材、纺织、汽车、餐饮/食品、批发零售、饭店管理、房地产、教育等行业领域，取得了骄人的业绩。迄今，本公司负责咨询的4000多家企业100%通过了认证。公司所聘人员大部分为国家注册高级咨询师、评审员和各类专业高级职称人员。公司共有员工50余名，全部大专以上学历，其中咨询老师20余名，博士两名，硕士10名，具备高级职称的5名，满足了不同行业的咨询要求。公司严格要求咨询程序，工作规范、科学、专人全程辅导，咨询小组集体配合，根据企业的实际情况进行调研诊断、体系策划、标准培训、文件编写、指导运行、内部审核、管理评审等工作。工作人员均具有丰富的质量管理知识和认证及评审实践与经验，在经咨询过的企业中留下了良好的声誉。公司全体员工,坚定信心、开拓创新、真诚合作、乘胜前进，以更昂扬的斗志，更积极的姿态，更坚实的步伐，继续做好认证服务，帮助更多的企业实现他们的中原梦、中国梦，为社会经济发展和中原崛起做出更大贡献！', 'https://www.zhaopin.com/jobdetail/CC358552229J90250003000.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8916, '大客户代表', '安徽合凯电气科技股份有限公司', '7月11日', '1-1.5万', '合肥-长丰县', '电气机械/电力设备', '100-299人', '已上市', 'CC289232030J40604050216', '岗位职责:<br>1.承担公司产品及系统销售任务;<br>2.分析区域市场内的行业特性，深挖行业客户，完成业绩指标任务;<br>3.负责辖区内市场信息的收集及竞争对手的分析:<br>4.负责经销商、项目信息收集和设计院跟踪;<br>5.配合市场部及技术人员做好项目前期准备工作及后期项目验收工作:<br>6.跟踪项目执行情况，及时协调解决项目过程中出现的问题:<br>7.现场踏勘整理方案资料，完成项目需求方案;:<br>任职要求:<br>1.专科及以上学历，优秀者放宽学历;<br>2.通信、计算机、电力、电气、自动化、物联网、营销等相关专业毕业;<br>3.具有敏锐的市场洞察力和客户分析能力:<br>4、性格沉稳开朗、热爱销售、富有挑战意识、有较好的口头及书面表达能力，有较强的沟通谈判能力和关系建立能<br>力:<br>5.同行业有客户、渠道资源的优先考虑。', '安徽合凯电力科技股份公司（原上海合凯电力保护设备有限公司）是专业从事各种过电压保护设备的研发、设计、生产、销售于一体的高新技术企业。公司下辖安徽国科电力设备有限公司。公司严格执行ISO9001/14000/18000“三标一体化”国际质量体系的各项标准，体系覆盖产品研发、设计、生产、销售、物流和售后服务等过程。公司注重研发新产品，汇聚了一批行业专家、学者、工程师，并与国内外多所著名大学以及国家级科研院所结成战略合作伙伴关系。公司在加大研发设施投入的同时并引进先进的生产设备，建立了在全国具有影响力的电力系统过电压试验中心。中心的建立不仅加速了企业科技创新成果的产生及转化，也为全国同行提供检测服务。目前，公司拥有30项专利技术，其中4项产品为国家重点新产品，7项产品为省级新产品，8项产品被认定为高新技术产品。公司被公认为是过电压保护行业的领袖企业。主要产品有：自脱离、大容量、免维护三相组合式过电压保护装置（SHK-BOD）、三相组合式过电压保护器（SHK-TBP）、开关消弧（SHK-KX）、消弧/消谐/选线及过电压保护装置（SHK-XHG）、大容量高速开关装置（SHK-FSR）、智能开关装置、高压限流熔断器组合保护装置（SHK-FUR）、同步发电机转子灭磁及过电压保护装置（SHK-FMB）、电流互感器二次过电压保护器（SHK-CTB）等。产品主要应用于发电、供电、石油、化工、冶金、水泥、钢铁、煤炭等行业。目前，这些行业中有80%以上的企业都使用了“上合凯”、“SHK”品牌的产品。产品覆盖国内近三十个省市、自治区、直辖市，还远销中东、东南亚等国家和地区。公司参与了众多国家重点项目的建设：如三峡电站项目、南水北调项目、中国石油、石化扩建项目、神华集团投资项目、宝钢、首钢、莱钢投资项目、大唐电力风电项目、首都国际机场的改扩建项目等几万个重点项目。此外，还与厦门ABB、上海通用广电、西门子、施耐德、德力西、天水长城、正泰等千家以上的开关厂配套，“上合凯”稳定的产品质量和超值的售后服务赢得了客户的一致好评。上海合凯电力保护设备有限公司将一如既往、奋进不息，坚持品牌决胜未来的发展战略，致力于以领先的技术和完善的服务创造更美好的生活。“上合凯”--“保护电力，不遗余力”！', 'https://www.zhaopin.com/jobdetail/CC289232030J40604050216.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8917, '网络销售', '悠派才选(上海)人力资源有限公司', '7月25日', '4000-8000元', '合肥-瑶海区', '人力资源服务', '500-999人', '未融资', 'CCL1264621710J40804502213', '薪资待遇：前两个月4-6k，转正后6-8k起，薪资上不封顶，入职缴纳五险一金<br>工作时间：9：30-19：00(午休12：00-13：30)，周末双休<br>入职要求：<br>1、统招大专及以上学历<br>2、有销售相关经验，有电销、代运营和餐饮行业相关经验优先<br>工作内容：<br>1、以电话沟通形式和商家建联，后期通过电话和企业微信方式和商家沟通；<br>2、负责商家整体运营，策划，活动制定，日常维护管理等系统性工作;<br>3、负责商家店铺装修，菜品定价，活动搭配，营销推广，充分利用美团的各种资源<br>4、负责商家促销活动，关联销售等策划，流量引入，提升店铺转化率，点击率和浏览量，把握美团平台活动节奏，活动后总结复盘；<br>5、商家日常运营，商品上新和维护，活动更新及页面调整，售后问题处理；', '卡思优派人力资源集团，成立于2007年。集团运行上海和无锡双总部模式，是国内屈指可数的业务涵盖高端猎头服务，白领招聘及外包服务，蓝领外包服务及薪酬、人事相关外包、代理服务的综合性人力资源服务机构。现旗下拥有卡思猎头、优派外包、优派好工作求职连锁吧等品牌，是长三角区域品牌影响力最广、客户数量最多、团队规模最大的人力资源服务机构之一。公司使命致力于“放大人的价值”，愿景是“成为人才驱动，数据驱动，产品驱动，技术驱动的面向客户的令人敬仰的组织”，成为中国招聘与外包领域领先的人力资源服务商。', 'https://www.zhaopin.com/jobdetail/CCL1264621710J40804502213.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8918, '运营助理/专员', '中国平安', '7月25日', '面议', '黄山-屯溪区', '保险,保险', '10000人以上', '已上市', 'CC000204810J40763724512', '●●岗位急招 招满即停<br>●企业文化:<br>我们固定早九晚六周末双休我们绝对不加班，下班就走，我们适合喜欢做服务，而又不想有太多工作压力的人同时对于有晋升欲望、有赚钱欲望的人，我们也给予充足的空间。人性化工作时间+周末双休不加班!<br>●福利待遇：<br>工资构成:<br>1、基础无责底薪+职级津贴+岗位津贴+绩效，综合薪资7-25k<br>2、缴纳社保:医疗保险，意外医疗、疾病医疗、生育险、失业保险+企业保险+住房公积金。<br>●工作时间:<br>早上:09:00-17:00，7小时工作制，午休两个小时。绝不加班。<br>周末双休。带薪年假，年底双薪，法定节假日带薪休假+带薪158天产假<br>●发展空间:<br>需要锻炼自己、提升自己，那么平台就很重要，上市公司五百强晋升培养机制完善，管理岗位需求大，对于有晋升意愿的伙伴提供职位直升扶持!<br>绝对的公平公正公开，全靠实力，全是实力派。<br>●培训<br>不用担心自己不会哦<br>1、新人入职了解公司、熟悉产品、超简单、这么聪明的你肯定没问题。也有平安大学做后盾<br>2、培训结束，公司分配师傅、组长、团队主管手把手教<br>●工作环境:<br>1、5A级舒适的办公环境(氛围融洽友好，团队年轻而富有活力)<br>2、员工旅游+员工生日会+发放丰厚的奖励，优秀员工每月有表彰(超多惊喜等你一起)<br>3、每年5-15天带薪年假(幸福感超足哦)<br>4、享受国家法定婚假产假以及陪产假等(一起见证你人生的每一个重大时刻)<br>5、琳琅满目的零食、咖啡、饮料、下午茶(工作的同时放松一下)<br>6、丰富的企业活动<br>●●●员工关怀<br>1.为员工提供多途径反馈工作、生活中遇到的问题困难，通过面对面圆桌会，线上答疑等方式给予解助<br>2.为家庭特别困难员工提供帮助，领导可爱同事暖心', '中国平安致力于成为国际领先的科技型个人金融生活服务集团。2019年，中国平安深入推进\\\\\"金融+科技\\\\\"、\\\\\"金融+生态\\\\\"战略转型，持续提升数据化经营能力，整体业绩及核心金融业务持续稳健增长，科技赋能成效显著，生态赋能效果初显，综合金融用户数、客户数、客均合同、客均利润均有明显增长。公司实现营业收入同比增长19.7%至11,688.67亿元。截至2019年底，公司个人客户数首次突破两亿，互联网用户量达5.16亿，全年新增客户数3,657万，其中40.7%来自集团五大生态圈的互联网用户。中国平安始终践行\\\\\"金融为实体经济服务\\\\\"的精神，坚持把实体经济服务作为出发点和落脚点，通过旗下的保险、银行、信托、金融科技等业务，把逾4万亿金融资源配置到经济社会发展的重点领域和薄弱环节，包括通过保险保障、提供贷款、债权股权计划、普惠金融等多种方式，全面助力实体经济发展。凭借全球领先的创新科技，中国平安将科技深度运用于金融主业中，助力降本增效、风险管控，打造优质产品和极致服务体验，提升客户口碑。与此同时，平安将领先科技广泛应用在金融、医疗及智慧城市等领域，全面支撑\\\\\"金融服务、医疗健康、汽车服务、房产服务、智慧城市\\\\\"五大生态圈建设。在企业社会责任方面，平安深化可持续发展理念，MSCI ESG评级连续两次调高至A级，打造AI-ESG平台赋能责任投资，截至2019年12月末，公司责任投资规模达9,544.49亿元，可持续保险金额达121.21万亿元，绿色信贷年度授信总额590.56亿元。同时，平安积极响应国家脱贫攻坚战的号召，推进\\\\\"三村扶贫工程\\\\\"项目，累计提供专项扶贫资金249.05亿元。面对新冠肺炎疫情，平安第一时间推出保险保障、医疗支持、对外捐赠等多重支持举措，提供的物资及现金捐赠总额超1.75亿元。2020年，中国平安品牌价值持续提升，名列美国《财富》“世界500强企业”第21位，居全球金融企业第2位，《福布斯》全球上市公司2000强第7位，BrandZ™全球品牌价值100强第38位，蝉联全球保险品牌第1位。', 'https://www.zhaopin.com/jobdetail/CC000204810J40763724512.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8919, '销售运营', '派普集团', '5月12日', '3000-4000元', '郑州-管城回族区', '建筑设备安装,工程施工,互联网,快速消费品', '100-299人', '不需要融资', 'CC551973080J40571950005', '岗位职责<br>1、负责社群、微信等社交平台进行用户维护和关系管理，建立并维护用户数据库，进行用户调研和沟通，回应用户留言和提问，与用户进行互动，增强用户黏性和忠诚度;<br>2、根据运营策略，组织和执行各类线上线下活动，创建话题内容，撰写和发布吸引用户的内容提升用户参与度、群成员活跃度和留存率，并开展裂变;<br>3、负责组织和执行线下活动，活动流程设计，活动物料准备，积极组织用户参与活动，提升活动效果;捕捉线下活动高光时刻和活动亮点，拍摄剪辑照片/视频，作为后续宣传物料;<br>4、负责社群、微信等社交平台，完善社群运营规则，及时跟进社群中用户的负面言论和投诉，快速响应，解决问题并控制危机扩散;<br>5、对社群平台的数据监测和分析，定期生成运营报告，为运营决策提供支持;任职要求:<br>1、统招大专学历，有用户运营/社群运营半年及以上经验，优先考虑 2023、2024年优秀毕业生2、熟悉微信、微博、QQ社区、百度和各大平台，有线上/线下活动策划运营经验者优先考虑;<br>3、具备较强的学习能力和适应能力，能够不断学习和掌握新的运营知识和技能;<br>4、性格外向，具备优秀的沟通表达能力、团队意识及跨团队协作能力。', '河南派普集团成立于1999年，是以建筑施工为基础，集互联网科技平台、食品生产研发与销售、沥青混凝土等多元化产业经营于一体的综合型现代化企业。互联网板块：是一家高新技术企业。公司以创新为驱动，在互联网领域不断开拓进取。公司致力于打造基于信用管理的互联网社交平台，主打陌生社交零距离，让你的生活更加丰富多彩！公司拥有一支高素质、富有创造力的专业团队，技术研发人员不断探索前沿技术，为平台的稳定运行和持续创新提供坚实保障；产品设计人员深入了解用户需求，打造出人性化、便捷性的产品界面和功能；市场营销人员积极拓展市场，让更多的用户了解和使用公司的产品。食品板块：2014年成立，建有生产厂房、综合办公楼、研发实验室及生活服务楼，是一家集研发、生产、销售为一体的企业。公司产品素云耳低GI蛋白餐，主打健康食材，低GI高蛋白，健康轻脂无负担。沥青混凝土板块：主要经营沥青、混凝土、水泥稳定碎石加工与销售，及基础设施建设、市政工程、公路工程施工。河南派普集团始终牢记“愿我们的创造，给世界带来更多美好!”的企业使命。在企业实现跨越发展的同时，积极践行社会责任，积极探索高科技产业腾飞及传统产业升华相融合的发展新思路、新模式，为行业发展进步做出更大的贡献！', 'https://www.zhaopin.com/jobdetail/CC551973080J40571950005.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8920, '档案管理', '中国人寿保险股份有限公司济南市槐荫区支公司', '7月20日', '4000-8000元', '济南-历下区', '保险', '1000-9999人', '已上市', 'CC255618930J40771073502', '【工作内容】1.VIP客户礼品发放', '成立时间：1996年12月05日。-业务范围​-寿险：涵盖健康险、医疗险、意外险、养老险及理财险等，为个人和家庭提供风险保障与财富规划。-财险：包括车险、家财险、雇主责任险、工程险等，为财产损失及责任风险提供保障。-团险：如员工意外险等，满足企业员工福利与风险保障需求。-其他业务：因广发银行隶属于中国人寿集团，还可开展广发银行的信用卡和贷款等业务。​-企业文化​-核心理念：成己为人，成人达己，体现了“己”与“人”相互成就的哲学观念。-企业愿景：建设国际一流金融保险集团。-企业精神：守纪律有激情，在状态抓执行。-品牌口号：相知多年值得托付，要投就投中国人寿。-经营理念：依法合规、创新驱动、价值优先、协同发展。-服务理念：诚实守信、专业高效、客户至上、体验一流。', 'https://www.zhaopin.com/jobdetail/CC255618930J40771073502.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8921, '大客户代表', '北京三维天地科技股份有限公司', '5月1日', '1-2万', '济南-历城区', '计算机软件,互联网,IT服务', '1000-9999人', 'D轮及以上', 'CC000573220J40206215313', '工作职责', '北京三维天地科技股份有限公司成立于1995年，是国内知名的检验检测信息化和数据资产管理领域的软件开发服务商，致力于为客户提供信息化整体解决方案及相关软件产品与服务，于2022年1月7日登陆深交所创业板。公司不断追求产品技术先进性和应用服务个性化，拥有多项自主知识产权及自主研发核心技术，产品广泛应用于政府机构、大型央企及世界知名企业，为其提供优秀的产品和服务。公司业务覆盖全国三十余个省及直辖市，目前公司在香港、海南、东莞、广西设有4家子公司，在厦门、上海、广州、深圳、重庆、西安、武汉、成都、济南、南京、贵阳、杭州、长沙、郑州、合肥、沈阳、乌鲁木齐等地区设有17家分公司，在石家庄等地区设立了多家办事处，有效实现了对不同区域、不同行业、不同规模企业组织的营销覆盖，构建了成熟、稳定、多层次的营销、交付以及运维服务体系。作为多个国家标准的工作组成员单位、起草单位，三维天地公司是产品质量大数据国家高新技术产品标准化试点单位，致力于国家质量基础设施（NQI）信息化实施服务，并参与起草了一系列数据管理相关的国家标准，在数据标准化与质量大数据相关领域，始终作为国内具有竞争力的技术先行者。今后，公司的发展战略重心将紧紧围绕政府关注，定制开发自主可控的数字化产品，支撑经济社会高质量发展。', 'https://www.zhaopin.com/jobdetail/CC000573220J40206215313.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8922, '知识产权/专利代理', '重庆翰凯建筑工程咨询有限公司', '5月6日', '6000-12000元', '重庆-江北区', '工程施工', '20-99人', '未融资', 'CC833430830J40664625006', '岗位职责： 1、学习掌握知识产权相关知识；； <br>2、熟悉知晓客户知识产权需求，为客户提供专业的知识产权服务； <br>3、掌握专业技能，开发现有客户资源并开拓新市场；。 <br>4、定期与合作客户进行沟通，建立良好的长期合作关系； <br>5、对接其他部门，处理好客户的委托案件。 <br>岗位要求： <br>1、不限制专业；年龄22-45岁，男女不限。 <br>2、沟通灵活、有一定抗压能力，做过电销优先； <br>3、积极而富有责任心，具有良好的职业素养，性格外向； <br>4、看好知识产权行业且想长期发展； <br>5、熟练使用office办公软件； <br>福利： <br>五险、双休、法定假日、年休假、生日礼金、季度福利、年底双薪、定期每月团建、旅游等等。 <br> <br>', '重庆翰凯建筑工程咨询有限公司成立于2018年9月20日，是一家专业从事房地产、建筑施工、勘察设计、造价咨询、招标代理、监理、工程检测、各行业协会等相关企业的资质新办、升级、分立、合并、跨省迁移、资质托管、股权转让、股权求购、猎头服务、代理记账、工商代办等服务的公司。。客户的满意是我们永远的追求。我们用企业化运作的经营模式、专家级的服务团队、一对一的一站式贴心服务，为客户提供全新的行业资讯和超值的增值服务。', 'https://www.zhaopin.com/jobdetail/CC833430830J40664625006.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8923, '游戏运营', '成都萌小玺文化传媒有限公司', '7月26日', '5000-7000元', '岳阳-云溪区', '新媒体', '10000人以上', NULL, 'CCL1486511100J40861310615', '在家上班。不限制位置，不限制英雄，不包技术，目前钻石段位，在家打游戏躺着赚米的工作来啦。职位详情：<br>1、负责和客户一起开黑玩游戏，主要是手游（王者荣耀）同时会别的更好。<br>2、主打陪伴，给客户提供情绪价值；<br>3、正规平台，不涉黄涉政涉赌，薪资按时到账，<br>不压工资，离职没有任何限制。任职要求：<br>1、男女不限，18-30岁（硬性条件）<br>2、王者荣耀目前达到钻石及以上<br>3、学历不限<br>4、普通话比较标准<br>5、接受开麦交流（硬性条件）<br>6、能满足一周七天有六天能够在线4小时（硬性条件）<br>8、愿意开口聊天，性格活泼，能提供较高情绪价值（加分项）', '成都萌小玺文化传媒有限公司，成立于2024年，位于四川省成都市，是一家以从事文化艺术业为主的企业。成都萌小玺文化传媒有限公司，成立于2024年，位于四川省成都市，是一家以从事文化艺术业为主的企业。', 'https://www.zhaopin.com/jobdetail/CCL1486511100J40861310615.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8924, '管培生/储备干部', '北京链家置地房地产经纪有限公司', '7月28日', '6000-12000元', '北京-海淀区', '房地产中介,电子商务', '10000人以上', '未融资', 'CC252944430J40292261216', '北京链家是一家集房产交易服务、资产管理服务为一体以数据驱动的价值链房产服务平台，北京市场领先的房地产服务企业，门店数量超过1700家，经纪人超过两万五千名，覆盖5000个社区和500万个家庭，拥有全面真实的房源信息，以及VR看房、房屋估价、智能推荐等业界创新的技术，以为2亿家庭提供品质居住服务为愿景。业务涉及二手房、新房、租房、旅居、商业办公、家装等，为消费者带来多元专业的服务，全面满足消费者的居住需求。8月13日贝壳集团在纽交所上市，目前市值已超过3000亿！作为中国居住服务第一股！链家，连接每个家的故事。<br>【招聘岗位】<br>房产经纪人-置业顾问(新房/二手房/海外/旅居/万链综合业务方向)<br>【岗位描述】<br>1、商圈社区专家：收集社区楼盘及相关商圈生活配套信息，提供相关咨询和解决方案；<br>2、资产管理顾问：收集、分析和匹配、维护并推广相关房产信息，提供相关资产管理方案；<br>3、房产法律咨询顾问：提供相关房产法律咨询；<br>4、社区公益者：关爱社区中需要帮助的邻里。<br>【工作职责】<br>1、Online负责线上渠道的房产信息推广及维护，打造专业的个人品牌<br>2、Offline负责客户接待，咨询工作，为客户提供专业的房地产置业咨询服务<br>3、了解客户需求，提供合适房源，进行商务谈判<br>4、陪同客户看房，促成二手房买卖和租赁业务<br>5、负责公司房源开发与积累，并与业主建立良好的业务协作关系<br>职位福利：五险一金、带薪年假、员工旅游、节日福利 <br>', '北京链家成立于2001年，是中国领先的房地产服务企业，业务覆盖二手房、新房、租房等全方位房产交易和居住服务，目前北京链家有1000余家门店。20年来，北京链家致力于提供安全有品质的服务，在行业率先承诺“不吃差价”、首倡“真房源”、推出“交易不成佣金全退”“电话营销扰一赔百”等18项安心服务承诺，与此同时北京链家也在全面推行店面服务升级和经纪人职业素养提升，坚持对客户好，对经纪人好，对社区好，持续推动行业进步，不断提供更有品质的服务。', 'https://www.zhaopin.com/jobdetail/CC252944430J40292261216.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8925, '项目专员/助理', '中国环球广播电视有限公司', '5月2日', '1-1.5万', '北京-朝阳区', '广播/影视,广播/影视', '1000-9999人', '未融资', 'CC465656530J40781482908', '岗位职责<br>1. 项目统筹、 协调对接等工作；<br>2.协调重大项目规划、 立项申报、 结项评估等相关工作；<br>3.项目进度跟踪，统筹项目季报、效果数据、情况说明等动态材料；<br>4. 联络上级单位和台内相关职能单位；<br>5.上级交办的其他临时性任务。 <br>任职资格<br>1.具有大学本科及以上学历和相应学位， 国际传播、 国际关系或金融经济相关专业背景；<br>2.了解国际传播工作方针政策， 拥有相关工作经验优先；<br>3.可靠， 品行端正，具备良好的团队合作能力和沟通协调能力，具备较强的工作责任心与稳定性。', '2017年3月9日，中国环球广播电视有限公司正式成立，旨在通过公司机制、市场方式，按照国际化运作要求开展内容制作、媒体合作、专业人才引进、海外公司建设、海外落地推广等业务。', 'https://www.zhaopin.com/jobdetail/CC465656530J40781482908.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8926, '猎头顾问', '南宁市卓天恒企业管理咨询有限公司', '7月1日', '3000-4000元', '南宁-江南区', '计算机软件,互联网', '100-299人', NULL, 'CC842888370J40819361508', '岗位职责:<br>1、理解客户的职位需求，在TL带领下，通过各种招聘途径(内部资源库、招聘网站、社交<br>网站、候选人转介绍等)完成人才搜索和寻访工作;<br>2、沟通潜在候选人，全方位了解候选人的基本信息如薪资、真实想法等，判断候选人与职<br>位的匹配度。<br>3、推荐合适候选人给客户，并根据要求制作推荐报告;<br>4、推进项目进展，提供面试安排、结果反馈、背景调查及后续跟踪服务，做好候选人与企<br>业协调沟通工作;<br>5、与入职候选人及潜在候选人保持良好的沟通;<br>6、项目空闲时间收集、分析所在行业市场信息，总结明细目标<br>公司组织架构，做深入Full-Mapping工作;<br>7、猎头项目的具体推进、执行，完成年度业绩指标。<br>任职要求:<br>1、大专以上学历；<br>2、具有猎头行业、人力资源或电话销售相关行业从业经验者优先;<br>3、具备独立的发现、分析及解决问题的能力;<br>4、工作效率高，执行力强，沟通协调能力强;<br>5、能承受工作压力，善于学习。', '南宁市卓天恒企业管理咨询有限公司为深圳市智友咨询管理有限公司在南宁战略性设立的新型互联网平台猎头公司，位于南宁市江南经济开发区国家级创业孵化基地联讯U谷。公司业务范围涵盖北上广深、武汉、西安、成都等全国二十多个城市100多家企业。公司提供主要业务领域包括：中高端人才招聘、人才信息咨询、人力资源管理与咨询、流程优化与设计，为企业提供全方位的人力资源招聘解决方案以及企业管理咨询服务。公司长期立足于IT互联网、金融行业，辐射高新技术研发、消费电子及特殊专业领域等行业。依托丰富的人才库资源，专业的猎头顾问团队，简化高效的服务意识，公司已为100多家企业提供了高效优质的人才寻猎服务，积累了丰富的多行业人才资源以及与多家企业建立了长期合作伙伴关系。卓天恒（Jobten）主要业务模式为“线上互联网平台为主+线下客户为辅”，依托公司庞大的互联网人才库资源，以及与外部线上平台客户建立的稳健合作关系，我们将为客户提供稳定高质量的人才输出，为员工创造另一个幸福的家！欢迎精英人才加入我们！', 'https://www.zhaopin.com/jobdetail/CC842888370J40819361508.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8927, '英语翻译', '深圳市华钜翻译有限公司西安分公司', '7月25日', '4000-8000元', '长沙-芙蓉区', '咨询服务,咨询服务', '20-99人', '未融资', 'CC450498430J40771683802', '岗位描述：<br>1.翻译香港 IPO，年报， 通函，公告等财经法律上市文件；<br>2.负责项目的翻译审校并配合团队工作；<br>3.确保高水准的译文质量按时交付客户；<br>职位要求：<br>1. 本科以上学历，不限专业，中英文表达流畅；<br>2. 对财经翻译有认识和一定的知识积累，中英文翻译基础扎实；<br>3. 拥有3年以上翻译审校经验，各种翻译领域均可,如金融、市场、财经、IT，医疗、法律、通用、专利等；<br>4. 翻译审校速度快且质量高；文字敏感度高；<br>5. 高度责任心，善于沟通，组织能力强。', '华钜翻译有限公司是一家专业性多语言翻译服务提供商，公司成立于2002年，总部位于深圳，旗下设有西安分公司。公司现有员工50余人，其中专职译员40人，另有500余名各语种兼I职译员组成强大后备队伍。公司于2010年通过ISO 9001:2008质量认证。目前是中国翻译协会(TAC)和美国翻译协会(ATA)的会员单位。自成立以来，华钜翻译始终秉承“质量第一、服务一流”的理念，致力于提供优质、专业的多语言服务，积累了丰富的实践翻译经验和扎实的专业服务技能。公司主营业务范围包括笔译、本地化、转录、编辑、校对、桌面排版(DTP)、口译、配音等，涉及金融、法律、软件、IT、半导体、电子、医学、机械、汽车、能源、航空、农业、艺术等众多专业领域。十多年来，公司依托快速的响应机制、严格的质量控制流程、按时的交付保障、贴心的售后服务，赢得中外客户的一致赞誉，成为值得信赖的专业翻译服务提供商，与客户建立了长期稳定的合作关系，累计翻译各类文档逾数千万字。从2011年起，公司重点专注于财经、法律翻译，为多家国际知名银行、金融机构、律师事务所、印刷商和科技公司提供专业的财经法律翻译服务。财经翻译涵盖招股书、公司章程、年报、中报、季报、通函、公告、计划书、研究报告、专利资料等。法律翻译涉及政策法规、合约、章程、协议、条款、规范、诉状等各类法律法规文档。华钜翻译还与全球多家翻译机构和本地化公司建立了长期的合作伙伴关系，为他们提供技术类和本地化多语言翻译。我们曾经服务或仍在服务的直接或间接客户有：招商证券、普华永道、摩根大通、摩根史丹利、毕马威律所事务所、安联投资、美国美银美林银行、英国标准人寿保险公司、华为、中兴、金蝶、腾讯、艾默生、比亚迪、证监会、广东核电、西门子、壳牌、香格里拉、莱尔德、IBM、HP、Dell、Google、HTC、Cucci、DHL、Saxo Bank、Omega、Tiffany、Wacker、Samsung、Scania、Lamborghini、Volvo、Delaval、FedEx、Ferretti、Eaton、Longchamp、Louis Vuitton、Intel、Nvidia及众多中小型公司和机构。华钜翻译的语言专家，专业基础知识过硬，翻译技能扎实，实践经验丰富。我们坚持实行“译、审、校”翻译流程，严格把控翻译质量，精益求精，力争做到最好。凭借高素质的专职团队和来自本国及其它国家的500名多语兼I职译员，我们可满足客户对全球各语种的语言需求，包括简体和繁体中文、日语、韩语、马来西亚语、印度尼西亚语、越南语、泰语、英语、法语、德语、意大利语、西班牙语、葡萄牙语、丹麦语、荷兰语、瑞典语、俄语、波兰语、阿拉伯语等等。作为一家以客户为中心、视质量如生命的语言服务提供商，华钜翻译注重倾听客户的需求，确保为客户量身定制，打造专业化、个性化的服务，并保证及时按量交付。', 'https://www.zhaopin.com/jobdetail/CC450498430J40771683802.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8928, '储备干部', '东莞市易顺经济信息咨询有限公司湖南分公司', '2月6日', '4000-8000元', '长沙-开福区', '银行,信托,互联网金融/小额贷款', '300-499人', '未融资', 'CCL1370563400J40471076803', '1、了解、熟悉公司相关业务；  2、熟练操作界面系统；', '易顺集团经济信息咨询有限公司是鉴于全国性清收业务发展的需要以及合规需求而设立的股份有限公司。公司注册资金1000万元，总部位于广东省东莞市，并分别在湖南长沙、广东惠州、广东中山、广西南宁、广西柳州、贵州遵义、辽宁沈阳等地设立10多家分公司，总办公面积超2000平米。公司经过近几年来的高速发展，凭借一整套完备的管理制度和催收业务流程、对清收业绩进行有效管控的体制，以专业、高效、合规、优质的服务优势所取得的个贷及信用卡清收业绩，得到了金融机构的认可，现已成为国内个贷与信用卡清收知名度较高、具有一定影响力的金融外包服务商。曾获得中信银行信用卡中心广东省总行、湖南省分行等分别颁发的“卓越贡献奖”、“精诚合作奖”、“业绩杰出奖”、“突出贡献奖”、“催收优胜奖”和、“业绩先锋奖”；公司是中信银行的战略合作伙伴，连续4年获该行颁发的嘉奖函、“战略合作伙伴”、“全辖业绩先锋奖”、“卓越合作伙伴”、“最佳执行奖”、“业绩优异奖”、“特殊贡献奖”、“优秀分部奖”等奖项。公司下设人力资源部、品管部、资讯科技部、信控业务部、财务部、行政客服部、市场部、法务部，对整个外包服务流程及清收作业业绩进行管控和指导。公司相比同业，还具有以下优势：自2014年组建不良个贷及信用卡透支清收团队至今已7年，是行业中较早从事该项业务的外包机构，积累了丰富的经验；招聘并培养了一批毕业于西南，中南政法大学、广东司法警官职业学院等院校的清收及管理人员，他们法律知识全面、清收用语规范严谨，善于查找债务人的信息和其关联户的信息，带领团队努力实现债权回收率的最大化；针对法律专业的员工，公司勉励他们工作学习两者兼顾，对取得司法资格的员工，主动推荐进入律师行业。公司在继续发挥已有优势的前提下，全面提升办公软件、硬件，加强对案件的系统管理做到精耕细作，根据业务的发展陆续在全国各省会、直辖市完成对分公司的设立，目标是将公司的清收业务覆盖至全国的各地区。公司与湖南电子科技大学已合作三年，是电科的金牌实习基地，欢迎热情、有冲劲、勇于接受挑战、德才兼备的优秀精英人才加盟，共创美好未来。', 'https://www.zhaopin.com/jobdetail/CCL1370563400J40471076803.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8929, '网络销售', '佛山市百分之八网络科技有限责任公司', '12月5日', '5000-9000元', '佛山-禅城区', '零售/批发', '20-99人', '不需要融资', 'CCL1485955700J40604655803', '岗位内容：<br>1. 负责公司线上产品销售，完成销售目标；<br>2. 维护公司平台产品品牌形象和推广；<br>3. 客户沟通和跟进，处理售后服务；<br>4. 分析销售数据和市场变化，制定相应的销售策略；<br>5. 持续改进销售流程和方法，优化销售表现。<br>任职要求：<br>1. 经验不限，学历不限；<br>2. 具备良好的语言表达能力、沟通能力和销售技巧；<br>3. 熟悉网络销售，了解网络营销流程的有限考虑；<br>年轻化公司，发展前景大，定期团建活动，节日福利等等;<br>欢迎有梦想的你加入~', '【任职资格】1.热爱销售，具备团队合作精神，服从安排；2.沟通能力佳，具有服务意识，有责任心；3.性格开朗，诚实，有礼貌。4.年龄24-55岁(经验不限，公司提供带薪培训，后期有师父一对一带上岗）5.逻辑清晰，思维开阔,有较强的沟通表达能力，拥有良好的职业素养，工作积极有责任心6.推广员一推广组长—推广经理—事业部负责人公司实行人性化管理，氛围好，重视每一位员工的付出!工作时间：9:00-17:00买五险，福利奖金公司每年国内游学双休，双休，双休！不加班，不加班，不加班！你有梦想，我们有舞台!欢迎有梦想的你！', 'https://www.zhaopin.com/jobdetail/CCL1485955700J40604655803.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8930, '英语翻译', '西安漫鸥出入境咨询有限责任公司', '7月23日', '5000-6000元', '西安-雁塔区', '贸易/进出口,投资/融资', '20-99人', '未融资', 'CCL1473668800J40934717604', '1. 翻译公司移民和跨境电商 Amazon 英文资料。<br>2. 确保翻译准确、通顺。<br>3. 与团队紧密合作。<br>4. 持续提高翻译技能。<br>感兴趣联系我，欢迎加入我们的团队！', '‌主营业务：跨境电商 Amazon卖家和广告咨询。商品资产‌：中资美元债，伊拉克，卡塔尔，石油等。提供对冲通货膨胀工具.‌‌互认基金‌：香港和内地互相认可的基金。‌‌保险‌：香港和美国的保险产品。‌外汇‌：直接购买美元、英镑、欧元，换汇业务等。‌‌沪港通或‌深港通‌：用人民币参与海外市场。‌‌美股账户‌：通过美国证券经纪商开立账户。新加坡移民业务。', 'https://www.zhaopin.com/jobdetail/CCL1473668800J40934717604.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8931, '总助/CEO助理/董事长助理', '河南卓盈科技有限公司', '2月22日', '6000-8000元', '郑州-荥阳市', '通用设备制造,通用设备制造', '20-99人', NULL, 'CCL1478946430J40508976902', '招聘要求：', '离心泵行业创新者，河南卓盈科技诚邀英才，共绘智造蓝图！河南卓盈科技是一家专注于高效、智能离心泵及智能控制系统研发、生产、销售与服务一体的现代化企业，为矿山、油田、市政工程等复杂工况提供高效的流体解决方案。为什么选择卓盈？1、站在技术前沿，深耕核心领域：✷依托国内顶尖高校及科研机构，共建研产基地，汇聚专业力量；✷核心聚焦高效多级离心泵、特殊工矿浆料泵、同步自吸泵、智能控制系统及能效管理系统的研发与制造；2、现代化智造基地，匠心品质保障：✷拥有配备先进立式卧式加工中心、高精度数控设备、10KV配电测试中心等的环保车间；✷构建涵盖原材料、工艺、性能的360°全流程质控体系；✷产品通过煤安认证、ISO三体系认证；3、“没有天花板的平台”，赋能人才成长：✷坚信人才是核心驱动力！奉行“激励+成长”的人才理念；✷多维度的发展路径、规范的管理制度、明确的团队目标；✷只要您有激情、有梦想、有目标、懂坚持，卓盈将为您提供尽情施展才华、实现价值的广阔舞台！您的价值创造将获得公司加倍的回馈；我们寻找这样的伙伴：✮有目标感、责任心和持续学习能力；✮渴望在一个快速成长、尊重技术、重视人才的平台上实现个人价值；加入我们，与创新者同行，共创美好明天！', 'https://www.zhaopin.com/jobdetail/CCL1478946430J40508976902.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8932, '档案管理', '重庆耀迅海科技有限公司', '3月17日', '6000-7000元', '重庆-江北区', '网络/信息安全', '100-299人', '未融资', 'CCL1479994680J40543197110', '职位详情<br>包住宿近轻轨办公室办公不外出早九晚六<br>这个岗位偏文职，你要付出的是时间和耐心，反复的做同一件事情，要接受工作的枯燥。不找客户、不电销、不催收。对客户主动提交的数据资料进行及时筛选管理处理<br>此岗位非销售岗<br>福利:包住、节假日福利，员工聚餐，三个月一次的晋升机会', '经营范围一般项目:科技中介服务;技术服务、技术开发、技术咨询、技术交流、技术转让、技术推广;企业管理;企业管理咨询;信息系统集成服务;信息技术咨询服务;个人商务服务;工程管理服务;会议及展览服务;非融资担保服务;环保咨询服务;接受金融机构委托', 'https://www.zhaopin.com/jobdetail/CCL1479994680J40543197110.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8933, '培训师', '大家好(山东)电子商务有限公司', '5月25日', '5000-10000元', '潍坊-奎文区', '互联网,电子商务', '20-99人', '未融资', 'CC385030030J40476013906', '培训讲师<br>岗位职责：<br>1、负责公司各类参观讲解、现场客户答疑等客户参观流程服务；<br>2、组织市场各类宣讲会议，并根据各市场情况需求开展工作；<br>3、负责部门内外部培训，做好公司及新产品的培训及技能技巧的辅导；<br>4、负责公司讲座、项目路演会议、行业分析说明会、客户联谊活动和沙龙讲座的主持及讲解工作。<br>5、根据公司的发展需求及经营策略，制定并落实培训计划和内容。<br>岗位要求：<br>1、专科以上学历，医学类相关专业毕业优先，拥有较好的形象气质；<br>2、熟悉相关业务，熟练使用现代培训工具，具有较强的课程开发能力，良好的演讲能力；<br>3、富有激情，较强的亲和力和感染力，良好的语言表达能力，思维敏捷；<br>4、熟练使用办公软件，可独立制作PPT课件；<br>5、有路演经验和成交技巧者优先录用。', '山东果然电子商务有限公司成立于2014年，致力于帮助企业客户构建以顾客为中心的有效营销服务体系。多年来，山东果然凭借创新的营销理念，卓越的服务能力，受到企业和社会的广泛认可。目前公司业务包括“V臣”B端企服平台和“果然有惊喜”C端活动平台。“V臣”，是企业活动营销落地服务提供商，是“超值企业礼品＋有效营销工具＋实操落地方案”的创新营销模式开创者。是以实体经济和顾客消费需求为出发点，最大程度的整合资源，联合全国知名商家、服务机构，创立的一站式企业营销服务品牌。“V臣”依托山东果然多年供应链体系沉淀的“产品供应链、仓储物流供应链和互联网技术”三大核心资源，构建了一个帮助客户打造数据驱动、引领创新的活动营销平台。“果然有惊喜”，是一个以旅游为基础，带动吃喝玩乐，以活动为入口，带动本地消费，以服务商家为支撑，服务个人用户的社交型活动平台。“果然有惊喜”通过活动帮助商家解决“引流,截流,回流,现金流”四大难题，服务宣传宗旨是“让生活动起来，让消费有惊喜”，力争让用户的每一次消费都变得简单又充满期待，即有实实在在的优惠又有意想不到的惊喜。【企业愿景】成为世界一流的企业服务公司。', 'https://www.zhaopin.com/jobdetail/CC385030030J40476013906.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8934, '售后客服', '中国人寿保险股份有限公司深圳市分公司', '7月4日', '8000-15000元·13薪', '深圳-龙华区', '保险,银行,保险', '10000人以上', '已上市', 'CC135627160J40705972611', '岗位职责: <br>1.客户家庭保单整理、保单缺口提醒; <br>2.客户生日祝福、节日温馨祝福; <br>3.客户缴费、续费提醒; <br>4.客户保单领取年金满期金养老金提醒; <br>5.客户信息完善; <br>6.保险理赔报案受理、理赔办理、理赔款到账提醒; <br>7.公司最新资讯、福利权益活动以及财富沙龙活动的告知; <br>8.通过公司划分的老客户经营，逐步了解清楚客户的客户画像，并作相应的需求分析(二次资源开发)。', '中国人寿保险（集团）公司属国家大型金融保险企业。2019年，集团公司合并营业收入9067亿元；合并保费收入6977亿元；合并总资产超4.5万亿元。中国人寿保险（集团）公司已连续18年入选《财富》世界500强企业，排名由2003年的290位跃升为2020年的45位；连续14年入选世界品牌500强，2020年品牌价值达人民币4158.61亿元；所属中国人寿保险股份有限公司继2003年12月在纽约、香港两地同步上市之后，又于2007年1月回归境内A股市场，成为全球第一家在纽约、香港和上海三地上市的保险公司。中国人寿保险（集团）公司的前身是诞生于1949年的原中国人民保险公司，1996年分设为中保人寿保险有限公司，1999年更名为中国人寿保险公司。2003年，经国务院和中国保险监督管理委员会批准，原中国人寿保险公司进行重组改制，变更为中国人寿保险（集团）公司，并独家发起设立中国人寿保险股份有限公司。目前，集团公司下设中国人寿保险股份有限公司、中国人寿资产管理有限公司、中国人寿财产保险股份有限公司、中国人寿养老保险股份有限公司、中国人寿电子商务有限公司、中国人寿保险（海外）股份有限公司、国寿投资控股有限公司、国寿健康产业投资有限公司以及保险职业学院等多家公司和机构。2016年，中国人寿入主广发银行，开启保险、投资、银行三大板块协同发展新格局。中国人寿秉持“成己为人成人达己”的企业文化核心理念，坚持稳中求进工作总基调，坚持高质量发展，扎实推进保险主业价值和规模协调发展，努力提升投资板块贡献，积极做好银行金融服务，有序开展综合化经营、科技化创新、国际化布局，全面推进国际一流金融保险集团建设。', 'https://www.zhaopin.com/jobdetail/CC135627160J40705972611.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8935, '质检员', '北京泰达盛凯企业管理有限公司', '7月15日', '5000-6000元', '沈阳-铁西区', '人力资源服务,企业服务,人力资源服务,汽车研发/制造', '300-499人', '未融资', 'CC668182130J40693743606', '铁西宝马质检员<br>工作轻松！班车接送！<br>【岗位职责】质检岗位及一些辅助工作！简单容易上手！<br>【岗位要求】男女不限，18-40周岁<br>【薪资待遇】19每小时，周结工资，周结工资，压入职前3天<br>【工作时间】早班，6-16 晚班，16-2（忙的阶段存在加班）<br>加班必须配合加班，<br>也可能12小时两个班倒。一周一倒班<br>月休4天左右！<br>【工作地址】：华晨宝马铁西工厂', '经营范围：求职、用人登记、用人推荐；介绍地区之间、单位之间的劳务输出与输入、介绍家政服务人员；专业承包；劳务分包；劳务派遣；互北京泰达盛凯企业管理有限公司成立于2018年03月15日，注册地位于北京市北京经济技术开发区科创十三街29号院一区2号楼8层802-03-04，法定代表人为王建。经营范围包括一般项目：企业管理；企业管理咨询；物业管理；人力资源服务（不含职业中介活动、劳务派遣服务）；劳务服务（不含劳务派遣）；安全咨询服务；社会经济咨询服务；建筑物清洁服务；会议及展览服务；组织文化艺术交流活动；广告发布；广告设计、代理；广告制作；建筑装饰材料销售；专业设计服务；日用杂品销售；日用百货销售；软件销售；计算机软硬件及辅助设备零售。（除依法须经批准的项目外，凭营业执照依法自主开展经营活动）许可项目：职业中介活动；建设工程施工；建筑劳务分包；劳务派遣服务。（依法须经批准的项目，经相关部门批准后方可开展经营活动，具体经营项目以相关部门批准文件或许可证件为准）（不得从事国家和本市产业政策禁止和限制类项目的经营活动。）北京泰达盛凯企业管理有限公司具有2处分支机构。收起联网信息服务；城市垃圾清扫、收集；物业管理；企业管理；', 'https://www.zhaopin.com/jobdetail/CC668182130J40693743606.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8936, '律师助理', '盈科外服(武汉)企业管理有限公司', '7月13日', '2000-3000元', '武汉-武昌区', '咨询服务', '20人以下', NULL, 'CCL1313879700J40356318007', '1、全流程参与案件（从接待当事人到案件办结）；<br>2、全方面专业学习，可参与各类案件（民、商、刑事）和非诉业务；<br>3、团队化办案，高效协作，合众为一；<br>4、定期内部专业培训（由原法官、合伙人律师、心理学老师主讲）；<br>5、完善的晋升机制：实习律师 — 授薪律师 — 授薪合伙人 — 合伙人。<br>在昊程昊，每一位伙伴的闪光点都会被发掘，每一份心声都会被倾听。<br>我们建立了完善的晋升通道和丰富的培养机制，帮助支持每一位伙伴在专业上不断深入，我们期待专业上出类拔萃、具有优秀职业素养的你，与我们共同携手不断开创法律服务行业新格局。<br>任职要求：<br>1、已通过司法考试，硕士，本硕均为法学专业，条件优秀可放宽；<br>2、品行端正，有志于长期从事律师事业，有责任心和责任感；<br>3、工作勤勉尽责、优质高效，适应能力强，具有良好的法律分析能力和职业道德；<br>4、具有良好的沟通能力和团队合作精神。<br>如果你正在寻找一个纯粹、严谨、高效、团结、富有创新精神的律师事务所，欢迎加入我们！<br>职位福利：周末双休、大牛带队、交通补助、弹性工作、多次晋升机会、出差补贴', NULL, 'https://www.zhaopin.com/jobdetail/CCL1313879700J40356318007.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8937, '质检员', '苏州利欣尔科技有限公司', '6月30日', '6000-8000元', '苏州-昆山市', '金属制品业,电子设备制造', '20-99人', '未融资', 'CC580333080J40527200213', '岗位内容：<br>1. 对生产线上的产品进行全过程质量监管，确保提供符合企业内部标准和客户需求的优质产品；<br>2. 根据相关的检验标准进行检验和测试，<br>3. 检验产品外观、尺寸、刮毛刺<br>任职要求：<br>1. 年龄18-40岁、<br>2. 具备亲和力、耐心细致、认真负责的工作态度；<br>3. 具备较强的动手能力和学习能力，<br>4. 配合产线加班', '公司成立2013年，主要从事五金模具、五金冲压、CNC机加工为主。公司主营汽车零部件生产制造组装，5G盖板，滤波器，电通电气生产等。公司设备齐全技术成熟，拥有从原材料加工，模具设计，备料，线割，组立，冲压等一条龙服务能力。在加工周期以及时间的控制上有着绝对的优势。秉着客户至上，诚信为本的理念，致力打造智能制造，全自动检测的一流科技企业，竭诚为客户提供优质完善的服务。', 'https://www.zhaopin.com/jobdetail/CC580333080J40527200213.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8938, '销售运营', '北方华创', '7月24日', '6000-12000元', '武汉-江夏区', '电子/半导体/集成电路,计算机软件,电气机械/电力设备,仪器仪表制造', '1000-9999人', '已上市', 'CC135196350J40792458812', '岗位职责：', '北京北方华创微电子装备有限公司（以下简称：北方华创）是A股上市公司北方华创科技集团股份有限公司（002371.SZ以下简称：集团）的全资子公司。北方华创是国内少有的覆盖领域广泛、产品种类众多、技术水平领先/先进、综合实力强劲的半导体装备旗舰平台。北方华创作为高端半导体工艺装备及核心零部件行业的知名供应商，主要产品涵盖等离子体刻蚀机、物理气相沉积设备（PVD）、化学气相沉积设备（CVD）、氧化/扩散设备、清洗机等半导体工艺装备，平板显示制造装备和气体质量流量控制器等核心零部件。北方华创的产品广泛应用于集成电路（芯片制造）、先进封装、半导体照明（LED）、微机电系统（MEMS）、电力电子、光伏太阳能、平板显示等半导体相关领域，与包括台湾、韩国、欧美大厂在内的国内外行业主流客户形成了长期友好的合作关系，在多款核心产品上实现了国产替代。公司在北京、上海、台湾新竹、西安、合肥、韩国、日本、美国等地拥有多个研发、制造及服务中心，营销服务体系覆盖欧、美、亚等全球主要国家和地区。在北方华创的产品蓝图中，新技术、新产品、新工艺代代更迭、生生不息，正如“北方华创”品牌的英文名称——“NAURA”所寓意的，我们的明星产品如浩瀚星辰般在半导体宇宙中璀璨闪耀同时，北方华创不断加大资源投入培育高质量人才队伍，通过建立与世界接轨的人才引进和激励机制，与国内外知名高校共同努力，不断壮大人才队伍。未来，北方华创将持续为人才赋能，培育创新文化土壤，打造高端人才“引力场”！公司网址：www.naura.com公司地址：北京市大兴区亦庄文昌大道8号', 'https://www.zhaopin.com/jobdetail/CC135196350J40792458812.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8939, '内容审核', '首聘(北京)科技有限公司', '7月21日', '5000-6000元', '成都-双流区', '企业服务,电子商务', '1000-9999人', '未融资', 'CCL1272782040J40781017614', '1、八小时工作 双休不加班<br>2、五险一金 待遇好 晋升空间大<br>3、工作位置 - 成都中冶天府大厦<br>4、审核平台图文、视频、音频等是否合法合规', '首聘(北京)科技有限公司成立于2015年08月31日，注册地位于北京市朝阳区霄云路40号院1号楼12层。经营范围包括一般项目：技术服务、技术开发、技术咨询、技术交流、技术转让、技术推广；企业管理咨询；社会经济咨询服务；软件开发；市场调查（不含涉外调查）；计算机系统服务；电子产品销售；通讯设备销售；计算机软硬件及辅助设备批发；计算机软硬件及辅助设备零售；人力资源服务（不含职业中介活动、劳务派遣服务）；外卖递送服务；物业管理；园林绿化工程施工；城市绿化管理；电子、机械设备维护（不含特种设备）；电气设备修理；通用设备修理；专用设备修理；停车场服务。（除依法须经批准的项目外，凭营业执照依法自主开展经营活动）许可项目：建筑劳务分包；第二类增值电信业务；测绘服务；劳务派遣服务；食品销售。（依法须经批准的项目，经相关部门批准后方可开展经营活动，具体经营项目以相关部门批准文件或许可证件为准）（不得从事国家和本市产业政策禁止和限制类项目的经营活动。）首聘(北京)科技有限公司对外投资12家公司，具有17处分支机构', 'https://www.zhaopin.com/jobdetail/CCL1272782040J40781017614.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8940, '运营助理/专员', '成都市面包路餐饮管理有限公司', '7月25日', '4000-5000元', '绵阳-涪城区', '餐饮服务,快速消费品,食品/饮料,零售/批发', '100-299人', '未融资', 'CC232962880J40588282002', '1.负责公司品牌运营基础工作执行；', '面包路起源在法国南部城市Cavaillon，这里有一个远近闻名的面包小镇，在这个小镇古老的街道上有许多经营了几百年的家族式面包作坊，面包的烘焙与鉴赏在这里被奉为神圣，如同一门宗教。随着社会变迁，城市发展，人们已经渐渐遗忘了那条街道的名字，而习惯称之为“面包路。”面包路自2013年6月首家店铺开业以来，所到之处，都能掀起一股无添加面包的风潮，店内总是簇拥着爱好健康烘培的粉丝和追随者。凭借自身的积累和发展，面包路在全川已经开设了13+家门店。他们都位于快速发展的商业中心，以及高品质生活区内等人流聚集的黄金口岸。目前面包路已入四川、重庆、贵州各地市繁华商圈，以自己独特的口味和健康的食材赢得了广大消费者的认同。集团管理中心地址：绵阳市涪城区毅德商贸城13区2栋成都面试地址：四川省成都市武侯区高升桥北街1号附17号(高升桥地铁站F口步行290米)', 'https://www.zhaopin.com/jobdetail/CC232962880J40588282002.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8941, '统计员', '中道数链(大连)数据信息技术有限公司', '7月15日', '4000-5000元', '大连-中山区', '互联网', '100-299人', NULL, 'CCL1419885890J40672148213', '1.协助上级完成审核、修订行政管理规章制度<br>2.考核和指导行政部工作人员的工作<br>3.负责各类会务的安排<br>4.完成上级交给的其他事务性工作', NULL, 'https://www.zhaopin.com/jobdetail/CCL1419885890J40672148213.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8942, '游戏推广', '萌拓文化传播', '2025-07-28 01:43:56', '4000-6000元', '西安-新城区', '文化艺术/娱乐,文化艺术/娱乐', '100-299人', '未融资', 'CCL1229164200J40791103912', '在家上班。不限制英雄，不包技术，目前钻石段位，不露脸不是直播岗位。<br>职位详情：<br>1、负责和客户一起开黑玩游戏，主要是手游(王者荣耀)同时会别的更好。<br>2、主打陪伴，给客户提供情绪价值;<br>3、正规平台，不涉黄涉政涉赌，薪资按时到账，离职没有任何限制。<br>任职要求: <br>1、男女不限，18-30岁(硬性条件) <br>2、王者荣耀目前达到钻石及以上 <br>3、学历不限 <br>4、普通话比较标准 <br>5、接受开麦交流(硬性条件) <br>6、能满足一周七天有六天能够在线4小时(硬性条件)', '一、我们是谁成都萌拓文化传播有限公司成立于2019年11月，与十多个知名平台有着深度合作。公司坐落于人杰地灵的天府之国，是一家以艺人培训、网络直播、艺人经纪、增值服务等业务为主的文化传播机构。目前已发展为大中华区知名的在线演艺经纪公司，拥有丰富的演艺资源与发展机会。二、我们需要优质人才萌拓文化作为一家正处于蓬勃发展的新公司，事业正在不断扩张，并在逐步探索更符合市场发展方向的经营模式，形成自己的品牌营销模式，完善公司的商业模式和盈利模式中。大厦落成绝非一人之力，同样公司的发展和建设也需要众人的努力。因此我们需要大量优质人才的加入与我们一同奋斗！三、加入我们你可以得到1、配备全国一流的直播设备公司将会为你提供全亚洲一流的直播设备，让你的工作如虎添翼。2、科学完善的培训我们将为艺人提供全方面的培训课程，不仅培养艺人的唱跳才艺表演，还包括礼仪培训、说话技巧、形体规范等内在修养，提升艺人的气质、心态和目标。通过培训课的训练，放大艺人的优势，缩小并修正艺人的不足。3、全方位的推广与包装公司将从艺人的挖掘、培养、签约、包装、宣传、推广、维护等一条龙规划到位。公司还采用互联网时代艺人经纪“020”模式，充分利用线上线下资源为签约艺人提供全方位的培训以及一流的包装推广，真正做到为广大怀揣明星梦的“草根一族“实现梦想。4、定制的发展路线公司将会根据艺人的自身条件、特点、潜力由业界资深演艺经纪人结合当下演艺市场需求为艺人制定独特的符合当下演艺市场需求的发展规划。5、不断拓宽的演艺事业在公司全力发展线上直播平台的同时，已经开始策划执行自己的直播平台。同时公司还将把艺人从网络直播间带往更广阔的发展平台，带领艺人涉足商演、代言、影视剧、微电影和综艺等多种领域，以此来增加艺人的知名度', 'https://www.zhaopin.com/jobdetail/CCL1229164200J40791103912.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8943, '网络客服', '金慧科技', '7月25日', '5000-7000元', '大连-中山区', '互联网,企业服务', '10000人以上', '已上市', 'CC612833320J40758473001', '【岗位内容】在线打字处理APP用户账号问题（被封被盗），入职后有带薪培训；<br>【工作时间】8小时工作制，周休2天；<br>【工资福利】综合5000-7000；<br>【内部晋升】入职满三个月有内部晋升，专员-组长-主管-经理；<br>带薪年假，周休两天，八小时工作制，有补助，节假日福利生日会等', '金慧科技（HK08295）于 2013年 11月在大连创立，是一家提供互联网营销推广、客户服务运营及信息技术服务的中国企业。公司在国内 25个城市设有超 40个服务基地和分子公司，已建成超 16000席服务规模，逾 15000名员工，业务覆盖全国。公司致力于“成为企业卓越成长的最佳陪伴者”，坚持“服务客户满意、员工快乐工作、合作伙伴信任、公司健康成长”的服务宗旨，面向互联网、金融、制造、运营商、政府等众多行业领域，与国内多家头部互联网知名企业和通讯运营商，各大银行，金融机构，证券机构等 200余家国内外知名企业开展丰富业务合作。公司通过服务创新和卓越运营的持续改进，在软件研发、过程改进、项目交付及运营管理能力均已获相关领域的国际权威认可，获得“大连市市长质量奖提名奖”。公司连续多年保持快速增长，是国内企业服务的龙头企业，辽宁软件产业 20年优秀企业，入选“中国数字服务暨服务外包领军企业”（中国国际投资促进会），并多次荣获客户服务行业和互联网营销推广领域的重量级奖项。', 'https://www.zhaopin.com/jobdetail/CC612833320J40758473001.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8944, '律师', '尔华法律咨询(广东)有限公司', '7月23日', '1-1.5万', '开封-龙亭区', '法律服务', '20-99人', '不需要融资', 'CCL1484598560J40622278206', '负责办理各类案件的办理。', '本公司为律师提供营销服务，案源推广+客户咨询+邀约到所。采用分成模式收取营销服务费。无前期费用。合作对象：执业律师。合作费用：客户缴费后分成。', 'https://www.zhaopin.com/jobdetail/CCL1484598560J40622278206.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8945, '资料管理', '上海奏裳网络科技有限公司', '7月17日', '7000-10000元', '佛山-顺德区', '云计算/大数据', '20-99人', NULL, 'CCL1506628370J40933001904', '岗位内容：<br>1. 负责建立和管理公司文档、企业文件、纪录档案等信息资源的分类、整理、归档工作<br>2. 管理文件借阅、销毁、流转等事项，并保障信息的安全性和完整性<br>3. 进行档案数字化化、电子化工作，构建信息化档案管理系统<br>4. 协助编制出资料归档、档案分类、信息检索、档案鉴定、保密审查等各项规章制度<br>任职要求：<br>1. 具有相关学科背景，如档案学、图书馆学等本科及以上学历<br>2. 精通文件管理、文献检索、档案鉴定等知识和技能，熟悉档案数字化技术<br>3. 热爱档案工作，具备较强的沟通、协调和组织管理能力<br>4. 有责任心和敬业精神，具备一定的主动性和创新意识', NULL, 'https://www.zhaopin.com/jobdetail/CCL1506628370J40933001904.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8946, '广告销售', '惠州市卓能会计服务有限公司', '7月8日', '4000-8000元', '惠州-惠城区', '企业服务', '20-99人', '未融资', 'CC240348930J40791525612', '岗位职责：<br>1.办理公司注册、变更、注销的业务<br>任职资格：（要有相关经验的）<br>1.勤劳刻苦、思维敏捷、可以随机应变突发情况、有较强的抗压能力。<br>2.有经验优先<br>3.会电动车<br>4.打字效率快<br>5.完成件越多，底薪越高', '惠州市卓能会计服务有限公司（卓能财税）——深耕财税服务领域11年，是经惠州市财政局批准注册登记、具有法人资格的专业财税代理机构。作为全国连锁品牌“多有米”惠州城市合伙人、守合同重信用企业及诚信企业，公司凭借卓越实力成为惠州市代理记账协会理事单位、河南岸商会理事单位及特聘服务机构，并入选惠州市网商会、直播协会会员单位，同时是代理记账行业《诚信公约》签署单位，彰显行业权威性与社会公信力。公司以“让创业者更省心”为使命，秉持“以德而立，客户第一，服务至上”的核心原则，依托专业的税务知识、高效的团队协作及优质的工商服务，累计为5000+企业主提供高性价比财税解决方案，始终践行“在乎客户的每一分钱”。未来，卓能财税将继续发挥“专业、诚信、高效”的竞争优势，为中小微企业成长发展保驾护航，持续传递“发挥自己、影响他人、成就更多”的价值观。多有米是深圳市中小企业公共服务示范平台；深圳市服务专精特新”中小企业公共服务示范平台““国家中小企业公共服务示范平台”；是腾讯、深圳国资委投资的深圳市专精特新企业，国家高新技术企业，深耕财税服务领域10数年，公司是以工商注册、记账报税为基础，致力于为创业者提供优质服务的互联网财税服务平台。目前，多有米集团已经在深圳、广州、惠州、上海、重庆、成都、杭州、合肥、昆明、西安、南宁、西宁、拉萨等20多个城市建立了运营中心，城市合伙人服务网络遍布全国各市，为20多万全国创业者持续提供优质的创业服务。', 'https://www.zhaopin.com/jobdetail/CC240348930J40791525612.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8947, '销售工程师', '青岛东软载波智能电子有限公司', '7月3日', '5000-9000元', '青岛-市北区', '电子/半导体/集成电路,电子/半导体/集成电路,物联网,智能硬件', '500-999人', '已上市', 'CC190493620J40786958213', '一、岗位职责', '青岛东软载波智能电子有限公司成立于2013年，为青岛东软载波科技股份有限公司全资子公司（股票代码300183）。公司研发、销售中心位于青岛市市北区上清路16号甲，东软载波信息产业园生产基地位于青岛市胶州市创新大道17号，总建筑面积17万平方米，项目总投资超过10亿元。公司目前拥有研发人员100+人，硕士及本科以上学历约占95%，提供智慧园区、智慧校园、智慧医院和智慧社区等解决方案，推动应用场景数字化转型，助力实现绿色低碳、安全高效、舒适便捷的目标。东软载波率先实现了电力线载波通信技术在数智化领域的创新应用,从“芯”开始,融合蓝牙、RF、Wi-Fi、5G等多种通信方式,运用云计算、大数据、物联网、A1、区块链、数字孪生等前沿技术,搭建“AI+零碳”数智化平台,构建数智化全面赋能的智慧园区、智慧社区、智慧医院、智慧校园等应用场景,重点打造智能照明、智能空调、楼宇智控、能源管理等数智化系统,为客户提供高效、智能、节能的数智化解决方案。在智能照明领域,公司推出的“灯具+控制器+智能控制箱+管理平台”全链产品，成功应用于工业照明、轨道交通、楼宇建筑等多个场景,通过人工智能算法优化与设备升级，可实现综合节能20%-75%，管理效率提升35%，为客户带来了显著的节能效益与管理效能提升。', 'https://www.zhaopin.com/jobdetail/CC190493620J40786958213.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8948, '销售助理', '山西力德福科技有限公司', '6月14日', '3000-5000元', '太原-小店区', '专用设备制造,专用设备制造,工程技术与设计服务,专业技术服务', '20-99人', '天使轮', 'CCL1227253280J40342379705', '岗位职责：<br>1、负责销售数据统计、报表制作及等资料整理；<br>2、协助销售经理做好客户来访接待，日常工作协助、支持；<br>3、负责客户信息的收集，协助销售经理完成电销工作，包括新客户开发、客户回访。配合销售经理完成销售任务；<br>4、协助销售经理完成实验设备操作；<br>5、协助市场推广工作，负责展会物料库存管理工作。<br>任职要求：<br>1、要求大专及以上学历；<br>2、有敏锐的销售意识，有销售经验者优先，对销售工作感兴趣愿意尝试也可培养；<br>3、可熟练使用word、Excel、PPT等办公软件；<br>4、品行端正、为人正直、热情大方，具有良好的沟通能力、团队协作能力；<br>5、会开车有驾照优先。<br>', '山西力德福科技有限公司为国家高新技术企业、山西省民营科技型企业、山西省“专精特新”企业。公司定位于科技创新型和生产服务型企业，成为继西班牙NC Hyperbaric公司、美国AvureTechnologies公司之后，全球成为能够自主开发规模化生产超高压设备的公司之一。山西力德福科技有限公司致力于超高压HPP技术和设备的研发、设计、制造和销售，主营「三水河·力德福」超高压HPP非热杀菌设备、超高压HPP果蔬加工设备、超高压工程技术与装备以及项目服务。公司核心团队经过15年的自主研发，掌握核心技术，并以归国留学人员为领军打造创新型公司，不断探索新型商业模式，以实现“设备+产业+服务”的全产业布局，服务客户，在创新驱动、转型发展中形成中国名片、引领行业示范发展。公司使命：让超高压技术造福人类生活公司精神：专注、高效、超越、毅力公司愿景：成为最受尊敬的超高压设备制造及服务企业', 'https://www.zhaopin.com/jobdetail/CCL1227253280J40342379705.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8949, '风电工程师', '河南凯沧能源科技有限公司', '7月19日', '7000-9000元', '固原-原州区', '电力/水利/热力/燃气,新能源', '20-99人', '不需要融资', 'CCL1463070120J40776138914', '工作职责：<br>1、负责对风电机组定期维护、检修工作，保障风电机组安全、稳定运行；<br>2、负责日常维护过程中相关故障的处理，隐患的排查、整改，及相关信息、资料的记录和收集工作；<br>3、积极落实现场负责人的工作安排并及时汇报工作进展；<br>4、按时完成规定的工作报表和报告等；<br>5、完成现场负责人交办的其他工作。<br>岗位要求：<br>1、大专及以上学历，机械制造类、机电一体化或自动化控制、电气自动化类、机械工程及自动化、风电类、电力工程类等相关专业；可接受应届毕业生（有毕业证）。<br>2、有风电相关工作经验的优先考虑，需要持低压电工证，登高证<br>3、身体健康，不恐高，无不良嗜好；有艰苦拼搏精神。<br>4、听从领导安排，敢于挑战，可适应长期驻外的工作性质', '河南凯沧能源科技有限公司是一家致力于风力发电及光伏行业售后服务，专业推广新能源技术的企业。公司主营业务有风力发电运维的机组的运维、检修、调试、技改、大部件更换及风机整装业务等。我司目前业务覆盖片区为：西北、华东、华南、西南、华北、东北片区，基本实现了业务全国覆盖。', 'https://www.zhaopin.com/jobdetail/CCL1463070120J40776138914.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8950, '产品专员/助理', '常熟卓辉光电科技股份有限公司', '6月17日', '50-100元/天', '苏州-常熟市', '电子/半导体/集成电路,仪器仪表制造,学术/科研,通信/网络设备', '20-99人', NULL, 'CC354781220J40789723813', '岗位内容：<br>1. 协助工程师，开发新产品或对现有产品进行改进 <br>2. 根据用户需求和市场反馈，整理产品需求文档，并协调相关团队推动项目进展 <br>3. 跟进产品生命周期，对产品进行数据分析、优化和风险控制 <br>4. 参与产品培训和推广方案的制定 <br>任职要求：<br>1. 本科，大学四年级，电气或电子工程相关专业 <br>2. 有明确的科研课题和就业方向<br>3. 熟练使用制图软件，能看懂基本电路图 <br>4. 具备良好的沟通、协作能力和商业敏感度', '常熟卓辉光电是专业从事绿色照明产品研发和生产的高新技术企业，凭借对电光源技术的深刻理解和卓越的技术研发能力，致力于推动照明行业的技术进步。公司在江苏苏州设立了苏州工业照明工程技术研究中心，在日本东京设立了日本固体照明应用技术研究所，与国内外多所大学和研究机构建立了技术合作关系，承担多项国家和省级科研项目，是江苏省民营科技企业、江苏省高新技术企业、江苏省知识产权管理标准化示范企业，是国家标准的制定者和国际洁净室照明技术的领导者。公司是新型洁净室灯具的首创者，也是洁净室工业照公司是美国GE、日本岩崎电气、星和电机等国际工业照明品牌的中国合作方。', 'https://www.zhaopin.com/jobdetail/CC354781220J40789723813.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8951, '游戏运营', '中节能环境管理服务有限公司', '4月17日', '4000-7000元', '北京-朝阳区', '环保,环保', '100-299人', '未融资', 'CC564511880J40835587915', '1.根据公司经营发展计划，分解落实公司年度经营指标，定期跟踪检查、统计分析经营指标完成情况；<br>2.收集、整理公司各项目经营数据报表，做好季度、年度经营分析与预测，及时发现经营管理中的问题，提出改进建议和方案；<br>3.配合市场部参与公司拟投资项目的调研，并根据项目实际经营数据，提出项目投资意见；<br>4.配合财务管理部参与公司全面预算管理工作；<br>5.根据部门财务预算，监督和控制部门费用支出。', '中节能环服公司于2016年成立，是中国节能旗下唯一一家以环卫一体化及环境综合服务为主业的全资子公司，服务内容包含垃圾分类、清扫保洁、垃圾收转运、公厕运维、扫雪除冰、转运站投建运、飞灰填埋场投建运等，业务范围已辐射全国10省，可协助政府打破环卫二元结构，以\\\\\"智慧环卫\\\\\"理念创新运营管理模式，全面致力于城市综合环境提升。', 'https://www.zhaopin.com/jobdetail/CC564511880J40835587915.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8952, '质量管理/测试', '富士康新事业发展集团有限公司武汉分公司', '7月23日', '6000-7000元', '深圳-宝安区', '电子/半导体/集成电路', '10000人以上', NULL, 'CCL1483145000J40759310409', '工作内容：<br>1.进行产品质量检查，包括原材料检验、生产过程检验和最终产品检验等。<br>2.分析质量问题和非合格品，确定根本原因并提出改进措施。<br>3.设计和实施质量控制计划，确保产品符合质量标准和客户要求。<br>4.协助制定技术规范和标准，确保生产过程符合行业要求和安全标准。<br>5.解决质量问题和投诉，并提供相应的解决方案。<br>6.参与新产品开发过程，提供质量方面的技术支持和建议。', '富士康科技集团1974年在台湾地区肇基，1988年投资中国大陆，目前在大陆拥有40余个园区，高峰期拥有百万员工，产品范围涵盖消费性电子产品、云端网络产品、电脑终端产品、元器件及其他四大领域，是全球最大的电子科技智造服务商。2022年，集团营收约1.49万亿元人民币，较上年度增长约10%;集团进口总额约5400亿元人民币，占中国大陆进口总额的3.0%;出口总额约8490亿元人民币，占中国大陆出口总额的3.5%。2023年位居《财富》全球500强第27位。', 'https://www.zhaopin.com/jobdetail/CCL1483145000J40759310409.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8953, 'BD经理', '北京亦庄人才服务', '7月23日', '1.2-1.6万', '北京-大兴区', '人力资源服务,咨询服务,专业技术服务,会议/展览', '20-99人', '未融资', 'CCL1305257680J40736969009', '岗位职责：<br>1. 挖掘潜在客户，通过拜访、会议、提案等方式促成合作。 <br>推广公司服务产品销售指标。 <br>2. 维护现有客户关系，定期回访并挖掘二次合作机会，提高客户满意度。协调内部交付团队，确保服务质量。 <br>3. 分析行业趋势、竞争对手动态，制定针对性销售策略，参与行业活动（展会、论坛等），提升公司品牌影响力。 <br>4. 与市场、产品团队协作，反馈客户需求以优化服务方案。 定期提交销售报告，跟踪项目进展及回款情况。 <br> <br>任职要求：<br>1. 本科及以上学历，专业不限。<br>2. 有商业服务业相关工作经验，或者有政府服务经验，熟悉政府工作模式。 <br>4. 出色的沟通能力、谈判技巧及商务能力，形象气质俱佳。<br>5. 热爱销售工作，结果导向，能承受业绩压力，适应高频客户拜访。', '北京亦庄人才服务有限公司，成立于2020年12月15日，是一家专业从事人才服务与开发的综合服务商。主要提供大健康管理、出行综合服务、人才评价、政策咨询辅导等人才服务业务和人才引进交流、人事代理、劳务派遣等人力资源服务业务。通过建立人才数据库、企业数据库、渠道资源数据库，逐步将自身打造成为集供需平台管理商、数据服务商等功能于一体的数字化综合再服务平台。', 'https://www.zhaopin.com/jobdetail/CCL1305257680J40736969009.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8954, '运营助理/专员', '派普集团', '6月24日', '80-130元/天', '郑州-管城回族区', '建筑设备安装,工程施工,互联网,快速消费品', '100-299人', '不需要融资', 'CC551973080J40753883305', '工作职责：<br>1、学习公司的互联网产品知识，了解公司的各个岗位的流程及内容；<br>2、基础拍摄剪辑工作、社群运营、短视频达人、新媒体运营方向的岗位，根据个人技能、意愿、面试评估分配岗位；<br>3、领导交待的其他事项。<br>岗位要求：<br>1、统招大专及以上学历，专业不限，可接受暑假实习 大三大四实习，在校大学生/应届生（26/27年毕业生 可按照每天薪资80-130核算）优先考虑，拍剪方向需要熟练使用PR、AE、PS等软件；<br>2、拥有正确的价值观，有一定的组织能力，学生干部优先考虑；<br>3、不惧挑战、积极抗压，有责任心、追求个人价值实现；<br>4、善于学习，熟练运用人工智能工具的，如元宝、豆包、deepseek等；<br>5、能配合公司各项工作开展，服从公司管理，切实维护公司利益。<br>薪酬福利:<br>1、法定节假日、带薪年假、提供午餐；<br>2、工作时间:<br>每周实习5.5天<br>周一至周五：早上8:30--12:00 13:30--17:30<br>周六：早上8:30--12:00<br>如果你拥有一颗互联网人的炙热之心、并且怀揣自己的梦想，那么河南派普欢迎你的加入！', '河南派普集团成立于1999年，是以建筑施工为基础，集互联网科技平台、食品生产研发与销售、沥青混凝土等多元化产业经营于一体的综合型现代化企业。互联网板块：是一家高新技术企业。公司以创新为驱动，在互联网领域不断开拓进取。公司致力于打造基于信用管理的互联网社交平台，主打陌生社交零距离，让你的生活更加丰富多彩！公司拥有一支高素质、富有创造力的专业团队，技术研发人员不断探索前沿技术，为平台的稳定运行和持续创新提供坚实保障；产品设计人员深入了解用户需求，打造出人性化、便捷性的产品界面和功能；市场营销人员积极拓展市场，让更多的用户了解和使用公司的产品。食品板块：2014年成立，建有生产厂房、综合办公楼、研发实验室及生活服务楼，是一家集研发、生产、销售为一体的企业。公司产品素云耳低GI蛋白餐，主打健康食材，低GI高蛋白，健康轻脂无负担。沥青混凝土板块：主要经营沥青、混凝土、水泥稳定碎石加工与销售，及基础设施建设、市政工程、公路工程施工。河南派普集团始终牢记“愿我们的创造，给世界带来更多美好!”的企业使命。在企业实现跨越发展的同时，积极践行社会责任，积极探索高科技产业腾飞及传统产业升华相融合的发展新思路、新模式，为行业发展进步做出更大的贡献！', 'https://www.zhaopin.com/jobdetail/CC551973080J40753883305.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8955, '售后客服', '中国平安人寿保险股份有限公司安徽分公司直属展业服务第二营销服务部', '11月18日', '6000-10000元', '合肥-包河区', '保险', '100-299人', '未融资', 'CCL1296782090J40689621914', '招聘售后客服，主要负责服务公司老客户，帮助客户解答问题，寄送礼品等售后工作，前期综合薪资在4.5k～6k之间，8个月固定时间任命主管以后6000底薪➕管理津贴➕岗位津贴，综合薪资在1.2W➕ 上班时间早8点30～下午5点，周末双休，招聘售后客服[庆祝]具体工作职责如下👇🏻👇🏻👇🏻<br>1、生日节假日送祝福，寄送公司给老客户的各种礼品<br>2、在线解答客户的各种售后问题<br>3、根据客户需求为客户制定合理的家庭资产配置', '中国平安是国内金融牌照最齐全、业务范围最广泛、控股关系最紧密的个人综合金融服务集团。截至2014年6月30日，平安集团旗下共有24家子公司，具体包括平安寿险、平安产险、平安养老险、平安健康险、平安银行、平安证券、平安信托，平安大华基金等，涵盖金融业各个领域，已发展成为中国少数能为客户同时提供保险、银行及投资等全方位金融产品和服务的金融企业之一。此外，在非传统业务方面，集团已布局了陆金所、万里通、车市、房市、支付、移动社交金融门户等业务。2014年，中国平安互联网金融持续创新，规模与用户数显著增长。中国平安相信，非传统业务在取得良好发展的同时，也将为传统金融业务创造新的增长空间。', 'https://www.zhaopin.com/jobdetail/CCL1296782090J40689621914.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8956, '总助/CEO助理/董事长助理', '湖南卓越未来智能科技有限公司', '12月2日', '3000-6000元', '长沙-芙蓉区', '消费电子产品,电子/半导体/集成电路,通信/网络设备,IT服务', '20人以下', NULL, 'CC453000610J40540031808', '1、完全没有任何基础的：2000元，三个月后转正，转正后底薪3000-4500元+业务提成利润部分35%。\n2、有相关行业类似工作经验有一定渠道的：底薪4000元+业务提成35%-50%。\n4、公司提供中餐及住宿，外地施工吃住全报销。\n5、春节9天带薪年假，全体购买意外险，年底达成公司销售任务及回款额享有年终奖金。<br>6.有长期共同发展愿景，且能胜任本职工作的可提供社保。\n【任职岗位要求】\n1. 会开车，有较丰富的销售技巧经验和产品专业知识（无经验实习生也可）\n2、有强烈的责任心及上进心，有不断提升能力和学习的心态，能承受一定的工作压力。\n3、 目标明确，行动积极，团队意识和沟通能力一定要很强，并且能够服从团队的合理安排和指导。', '湖南卓越未来智能科技有限公司是一个充满创新精神的智能安防音视频系统解决方案的提供商，亦是一站式集成采购供应商。秉承一站式品牌服务理念！现已成为湖南地区安防与安保，视频监控、防盗报警、可视对讲、门禁控制、楼宇集成，会议系统、公共广播、专业舞台灯光音响等杰出音视频集成工程公司。公司拥有广博全面的产品线，可为多种应用场合提供一流产品及服务，目前代理的核心产品有：美国JBL音响，英国玛田音响，LAX，SONY，DETON，HDL.....公司业务涵盖政府工程，企业单位，星级酒店，学校，剧院，大型KTV，酒吧娱乐场所等。因公司业务扩大，我们着力组建一支高素质的团队，欢迎各位精英人士加盟，与公司共创美好未来，实现共赢！', 'https://www.zhaopin.com/jobdetail/CC453000610J40540031808.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8957, '法务专员/助理', '安徽英科医疗用品有限公司', '7月22日', '8000-15000元', '淮北-濉溪县', '医疗设备/器械', '1000-9999人', '已上市', 'CC608962630J40721161302', '职位描述： 1、协助处理诉讼、仲裁等法务工作；', '英科医疗(股票代码300677)是一家致力于医疗器械耗材研发、生产、营销的高科技制造企业,于2017年7月在深圳证券交易所创业板上市。历经近30年的蓬勃发展，英科医疗在全球已拥有25家（分）子公司，在上海、淄博、青州、镇江、淮北、九江、安庆、岳阳等地设立生产基地，业务涵盖医疗耗材,康养器械,理疗护理等系列产品，产品远销美洲、亚洲、非洲和大洋洲的120余个国家和地区，正在为全球10000+家客户提供着实用的产品和优质的服务。安徽英科医疗用品有限公司是英科医疗全资子公司，位于安徽省淮北市濉溪县濉芜产业园海棠南路6号，主要从事一次性医用手套及其他医疗产品的生产和销售。公司计划投入近逾百亿元，建成世界领先的一次性医用手套生产基地。英科医疗一直致力于优秀人才的引进和发展培养，并为员工提供丰厚的薪酬待遇和完善的职业晋升发展通道，现面向社会招贤纳士，共创英科未来!', 'https://www.zhaopin.com/jobdetail/CC608962630J40721161302.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8958, '日语翻译', '惠州市安必昇人力资源有限公司', '12月12日', '8000-10000元·13薪', '东莞-None', '房地产中介,专业技术服务', '20-99人', NULL, 'CC389642320J40502524510', '●专科以上学历<br>●日语流利<br>●有制造型工厂日语翻译经验优先<br>●性格开朗、有较强的沟通能力<br>【工作内容】<br>●负责生产技术部门日本人的翻译工作<br>●部门之间的会议翻译<br>●口译70%，笔译30%', '安必昇人力资源公司最早于1999年成立，是由惠州市工商行政管理部门验证、注册登记的正规、合法的人才资源服务机构，公司致力于华南地区企业提供专门的人力资源信息咨询、猎头、中高级人才供求信息服务、企业管理、外包服务及劳务派遣的综合型人力资源服务公司。公司奉行：“创新、诚信、友善、公正、文明、和谐、专业、高效”的经营理念；以市场需求和客户需要为导向，构筑专业的人力资源服务体系，为企业提高核心竞争力和企业人力资源最优化配置提供专业、高效的人力资源方案服务.公司凭借丰富的人力资源储备为广大客户提供优质服务。公司拥有专业且经验丰富的顾问团队，全心全意的服务精神，致力于企业和人才的需要，以为企业提供优秀人才，为人才提供更好的就业环境为目标。公司与时倶进，积极创新中国现代人力资源管理模式，为企业提供高效、专业的人力资源服务。', 'https://www.zhaopin.com/jobdetail/CC389642320J40502524510.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8959, '网络销售', '山西弘诚文化传媒有限公司', '7月4日', '5000-10000元', '太原-万柏林区', '新闻/出版', '20-99人', '未融资', 'CCL1485752590J40670559708', '待遇：有责底薪3000+全勤200+餐补200+提成。3个月过试用期转岗后交社保。<br>工作内容：网络推广+办公服务。<br>挣多挣少自己努力说了算！', NULL, 'https://www.zhaopin.com/jobdetail/CCL1485752590J40670559708.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8960, '售后客服', '英才无忧(山东)网络科技有限公司', '7月23日', '8000-15000元', '南京-建邺区', '人力资源服务', '20-99人', NULL, 'CCL1504310520J40697448206', '岗位内容： <br>1. 负责售后服务，包括但不限于电话/在线咨询解答、问题排查分析和处理、客户关系维护等工作。<br>2. 收集并记录客户反馈信息，及时向相关部门反映并跟进处理情况。<br>3. 协助团队完成售后产品质量管理、售后流程优化等工作。<br>任职要求： <br>1. 具有良好的沟通能力及团队合作精神，能够独立处理客户问题。<br>2. 熟悉常用办公软件，具备基本的计算机操作能力。 <br>3. 拥有一年以上售后服务相关经验，了解售后服务流程者优先。', NULL, 'https://www.zhaopin.com/jobdetail/CCL1504310520J40697448206.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8961, '招聘专员/助理', '辽宁省臻至人力资源服务有限公司', '7月7日', '4000-8000元', '沈阳-和平区', '人力资源服务,人力资源服务', '20-99人', '不需要融资', 'CCL1464522540J40701443510', '老板嘎嘎好，办公室氛围佳！<br>月薪4000-6000<br>【岗位职责】<br>1. 负责发布信息，回复信息。<br>2. 负责沟通新信息和渠道 ！<br>3.负责招聘蓝领普工<br>【职责要求】<br>沟通能力强，有耐心讲解工作<br>【工资待遇】<br>薪资面议 五险➕双休<br>【工作时间】8.00-17.00。<br>要求有同行业经验<br>入职会有人带<br>177<br>4009<br>2387', '辽宁省臻至人力资源服务有限公司是一家集劳务派遣、代理招聘、岗位外包、人事代理为主营业务的综合型人力资源公司。公司长期专注于人力资源服务领域，凭借专业的服务、高效的团队，来促进人才职业发展，以实现企业的高效用工。公司的专业人员实时同步最新政策法规变化，帮助企业提前洞察人才管理方面的政策法规，未雨绸缪，帮助企业赢在起跑线。所以，我们一直致力于开发更多人力资源，通过对人才信息资源的全方位整合，建立社会人才和毕业人才的信息库，长期为众多优秀企业提供更优秀、更完善的服务！', 'https://www.zhaopin.com/jobdetail/CCL1464522540J40701443510.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8962, '管培生/储备干部', '郑州新捞派餐饮管理有限公司郑州第一分公司', '7月26日', '7000-8000元', '蚌埠-蚌山区', '餐饮服务', '10000人以上', '已上市', 'CCL1360672810J40714373316', '一、【招聘岗位】<br>  <br>门店管培生<br>  <br>  <br>二、【职位要求】<br>  <br>1.双一流本科及以上学历；<br>  <br>2.身体状况符合国家餐饮行业标准要求；<br>  <br>3.无不良记录和嗜好；<br>  <br>4.有较好的沟通表达能力以及创新能力；富有团队合作精神和管理潜质；具备较强的文字撰写能力；<br>  <br>5.工作有条理，细致、认真、有责任心，办事严谨；<br>  <br>6.熟练电脑操作及Office办公软件，具备基本的互联网操作要求；<br>  <br>7.性格开朗乐观，有亲和力并对服务行业充满热情，抗压能力强；<br>  <br>8.吃苦耐劳，有敬业精神，愿从基层做起。<br>  <br>  <br>三、【薪资标准】<br>  <br>薪酬：实习期薪资6000元—9000元/月； 转正后综合薪资10000元—20000元/月，特别优秀者另行商议。<br>  <br>  <br>四、【福利待遇】<br>  <br>1.实习期福利：<br>  <br>包食宿。表现优异者，毕业后可继续留任成为公司正式员工。<br>  <br>2.正式工/实习生转正后福利：<br>  <br>（1）员工可享受带薪年休假；<br>  <br>（2）正式员工可享受五险一金；<br>  <br>（3）包吃住；<br>  <br>（4）符合条件的员工（夫妻双职工、店经理等）可享有公司提供的住房补贴；<br>  <br>（5）凡在公司工作满三年的员工其子女可享受 2000-5000 元/年不等的教育补贴；<br>  <br>（6）大堂经理级别员工父母可享受 400 元/月的父母补贴；店经理级别父母可享受 1600 元/月的父母补贴；<br>  <br>（7）上述福利待遇的享受条件和适用范围以公司福利制度为准。<br>  <br>  <br>五、【发展途径】（经竞聘考核后可入职）<br>  <br>途径一：门店管培生--大堂/后堂/值班经理--店经理--区域经理；<br>  <br>途径二：门店管培生--大堂/后堂/值班经理--店经理--职能部门（人力资源部、信息科技部、会员运营部、公共事务部等）。<br>  <br>  <br>六、【注意事项】<br>  <br>面试需提供个人身份证原件或身份证明材料。<br>  <br>  <br>七、【面试地址及乘车路线】<br>  <br>添加招聘老师预约面试<br>', '海底捞火锅品牌创立于1994年，是一家以经营川味火锅为主，融汇各地火锅特色于一体的大型跨国直营餐饮民营企业。公司始终秉承“服务至上、顾客至上”的理念，以创新为核心，改变传统的标准化、单一化的服务，提倡个性化的特色服务，致力于为顾客愉悦的用餐服务；在管理上，倡导“双手改变命运”的价值观，为员工创建公平公正的工作环境，实施人性化和亲情化的管理模式，提升员工价值。二十多年来，公司已在北京、上海、西安、郑州、沈阳、南京、天津、杭州、深圳、武汉、苏州等400多个城市拥有多家直营餐厅。', 'https://www.zhaopin.com/jobdetail/CCL1360672810J40714373316.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8963, '项目招投标', '黑龙江省洁源检测技术有限公司', '11月7日', '2000-4000元', '哈尔滨-道里区', '环保', '20-99人', NULL, 'CC388863787J90250113000', '岗位职责：<br>负责编制资格审查文件，组织资格预审的评审工作；<br>负责协调相关部门提供标底等工作；<br>负责编制招标文件，组织开标、评标、定标等工作；<br>负责组织对投标单位的考察工作；<br>负责办理招标手续等相关工作。<br>2、职责表述：<br>建立各类台账、市场询价、提供经验数据、招投标资料移交<br>负责建立招投标相关台账；<br>负责整理、编制招标文件、评标办法、合同文件等的示范文本；<br>负责编制和不断完善成本控制管理的工作程序。<br>负责在招标工作全部完成后移交相关招投标资料。<br>3、负责配合其他相关部门完成其他与招投标有关的工作。<br>职位福利：五险一金、节日福利、周末双休<br>', '黑龙江省洁源检测技术有限公司成立于2015年，注册资金1000万元，办公地点位于哈尔滨市道里区群力大道3517号星光耀广场写字楼B座19层，使用面积1100m2。洁源检测是具有黑龙江省质量技术监督局颁发的CMA检验检测资质的“第三方检测技术服务机构”。主要从事环境领域的检测技术服务，服务项目涵盖水和废水、生活饮用水、环境空气和废气、噪声及振动、污泥土壤和沉积物、固体废物、公共场所、室内环境、民用建筑工程室内污染、洁净室、电离辐射、油气回收检测共计11大类495项检测项目；公司拥有国内外高端精密仪器设，拥有实验室管理系统（P.T LIMS软件），拥有国内科研院校顶尖团队的技术支持，可向社会提供科学、合理、公正权威的检测数据。现因公司发展需要，诚聘下列英才，一经录用，待遇优厚；我司交通便利、办公环境优良、工作氛围和谐、业余活动丰富；提供五险一金、绩效奖金、节假日福利、免费午餐、车补话补等；并且为员工提供广阔的发展空间和晋升渠道；有意者请及时投递电子简历，莫失良机。', 'https://www.zhaopin.com/jobdetail/CC388863787J90250113000.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8964, '招聘专员/助理', '上海立可飞劳务派遣有限公司', '4月8日', '120-150元/天', '北京-朝阳区', '人力资源服务', '20-99人', NULL, 'CCL1469169640J40614428501', '工作职责:<br>1.候选人简历编辑及数据系统录入;<br>2.候选人面试安排;<br>3.电话联系候选人收集简历<br>4.完成上级交付的其他事务。<br>  任职要求  <br>1.25年本科或研究生应届毕业生 <br>2.英文CET4及以上水平;  <br>3.熟练操作办公软件;  <br>4.具备良好人际关系与团队合作精神;  <br>5.对零售奢侈品行业感兴趣。', NULL, 'https://www.zhaopin.com/jobdetail/CCL1469169640J40614428501.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8965, '律师助理', '辽宁君玺律师事务所', '7月15日', '2000-3000元', '沈阳-和平区', '法律服务', '20-99人', '不需要融资', 'CCL1453403220J40712676111', '【岗位要求】：<br>1. 协助律师办理各类刑事、民商事类诉讼案件；<br>2. 负责书写法律文书，出具法律意见，合同审查等工作；<br>3. 协助律师与当事人沟通案件及进展情况。<br>【任职条件】：<br>1. 法学本科及以上学历，通过国家统一法律职业资格考试（A证）；<br>2. 熟练使用办公软件，具有扎实的文字功底和写作水平；<br>3. 具有较强的责任心和团队合作意识。<br>【工作待遇】：<br>1. 试用期1个月工资2000，转正办理实习证工资2500，党员+200（需关系转入）；<br>2. 拿到实习证，所里安排一对一指导老师并提供实践案例；<br>3. 实习期间能力突出者转执业后，优先聘用为所里授薪律师。<br>【工作时间】：<br>周一至周五早8:30-17:00，11:30-13:00午休，周末双休、法休。', '辽宁君玺律师事务所经辽宁省司法厅批准成立，执业许可证号：31210000MD03159589，位于辽宁省沈阳市和平区太原北街12号华鹏商务大厦二楼，拥有近20名执业律师及相关专业人员。所内大部分律师都是辽宁省沈阳市的资深律师，强强联合打造优秀律师团队。本所律师均受过正规高等法学教育，使本所能发挥学科团体优势，为社会各界提供更多优质高效的法律服务。君玺律所是一家综合性、专业化的法律服务机构。组建了具备法学专业背景的律师为核心的精英团队。能够在刑事诉讼、民商事诉讼、行政诉讼、金融、法律顾问等多个领域提供专业、高效、优质的法律服务。', 'https://www.zhaopin.com/jobdetail/CCL1453403220J40712676111.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8966, '销售助理', '无锡鑫巨宏智能科技股份有限公司', '6月7日', '5000-8000元', '无锡-新吴区', '金属制品业,金属制品业', '1000-9999人', 'C轮', 'CC519645230J40786155213', '【工作内容】<br>- 协助销售团队进行客户关系管理，通过电话、邮件、微信或线上工具与客户保持日常沟通，维护现有客户关系及开发潜在客户资源。<br>- 负责销售数据的收集、整理与分析，为销售策略的制定提供依据。<br>- 协同销售团队完成销售合同的准备、签订及后续跟进工作。<br>- 协助对接各部门，跟进订单出货情况及回款情况。<br>- 定期向上级汇报销售进度及客户需求变化情况。<br>-协助销售展销会活动策划和市场推广。<br>【任职要求】<br>- 本科及以上学历，英语、国际贸易、市场营销、商务管理等相关专业，英语、越南语熟练优先。<br>-具备良好的沟通能力和团队合作精神，能够与不同部门有效协作。<br>- 熟练使用办公软件（如Excel、PPT等），具备一定的数据分析能力。<br>- 工作态度积极主动，具备较强的学习能力和适应能力，能够快速掌握相关业务知识。<br>- 不限工作经验，欢迎应届毕业生加入我们的团队。对销售业务感兴趣或有相关实习经验者优先考虑。', '无锡鑫巨宏智能科技股份有限公司成立于2013年1月，现有厂房面积36000平方米，新建厂房达32000平方米，员工规模约2000人。历经数载发展，公司相继创立紧固件事业部、半导体热沉事业部、微纳光学事业部、新材料MIM事业部、光互联事业部及机器人事业部。鑫巨宏建有完备的生产线和专业的检测、开发实验室，拥有CNC加工中心、精密光学注塑设备、光学镀膜设备、MIM生产线、全自动组装线、机器人零部件产线。', 'https://www.zhaopin.com/jobdetail/CC519645230J40786155213.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8967, '储备干部', '天津肯德基有限公司', '7月25日', '3000-5000元', '保定-涞水县', '餐饮服务', '10000人以上', NULL, 'CC134529310J40637086401', '【公司介绍】<br>百胜中国控股有限公司（NYSE: YUMC及HKEX: 9987）是中国领先的餐饮公司，致力于成为全球最创新的餐饮先锋。自从1987年第一家餐厅开业以来，截至2021年12月底，百胜中国在中国的足迹遍布所有省市自治区（港澳台除外），在1600多座城镇经营着11,788家餐厅。2021年，百胜中国位列《财富》美国500强排行榜第363位。并于2021年入选时代百大最具影响力公司。百胜中国被评为2020年道琼斯可持续发展指数餐饮和休闲行业领导者。在2022年，百胜中国连续四年入选彭博两性平等指数，并连续四年荣获中国杰出雇主认证。<br>百胜中国从Yum! Brands分拆出来之后，于2016年11月1日独立在纽约证券交易所上市，股票代码为YUMC。百胜中国于2020年9月10日在香港联合交易所主板正式挂牌上市，股票代码为9987。百胜中国在中国市场拥有肯德基、必胜客和塔可贝尔三个品牌的独家运营和授权经营权，并完全拥有东方既白、小肥羊、黄记煌和COFFii &amp; JOY连锁餐厅品牌。百胜中国亦与Lavazza合作，于中国探索及开发Lavazza咖啡店品牌概念。<br>【基本要求】<br>20~28周岁，统招专科及专科以上学历，能够适应早晚班，高效的工作模式，愿意从事餐饮服务行业。<br>【职位介绍】 <br>主要从事餐厅值班管理、订货管理、排班管理、利润管理、人力资源管理、营业额建设等餐厅营运管理工作。<br>具有完善的培训体系和快速的职业发展：必胜客具有业界知名的人才培养体系-必胜客管理学院；采用333晋升机制，储备经理入职最快12个月晋升至餐厅经理，成为独当一面的职业经理人。<br>【薪资】基本薪资+季度奖金，入职6个月后调薪；每年享受绩效调薪<br>【福利】入职首月享受5险1金+雇主责任险+商业医疗保险+全家保险计划+免费年度体检<br>【长期激励】晋升餐厅经理后年薪10万以上，晋升满1年享股权激励，晋升满2年享家庭福利计划，晋升满3年享购房贷款/贴息<br>【合同】入职即签订3年正式劳动合同（4个月试用期，薪资100%发放）<br>【假期】10-20天带薪年假、5-10天全薪病假<br>【休息】每周上5休2 <br>【加班费】节假日若加班，享受额外3倍薪资补贴<br>【工作时间】因餐饮行业的特殊性，我们的工作时间属于倒班制，每月由餐厅经理排定班表，请您结合自身情况考虑是否能够适应以下班次。<br>月度排班，每天一个班次，早中晚三班各占1/3<br>【肯德基】<br>5:00-14:00；9:00-18:00；15:00-24:00<br>【必胜客】<br>7:00-16:00；9:00-18:00；15:00-24:00<br>每周双休（不固定休息六日，也不一定能够连续两天休息），法定假日排班享受三倍工资，依据餐厅营运需求进行排班。<br>【工作地点分配原则】<br>-根据家庭住址就近分配；<br>-餐厅培训状况及水平<br>Q&amp;A：<br>Q1：储备经理是服务员吗？具体工作有哪些？<br>A1：不是服务员，储备经理是餐厅的管理人员，大部分时间的工作是在餐厅楼面进行值班管理，与餐厅伙伴并肩战斗在一线，共同服务顾客。刚步入职场的你，将逐步学习和负责餐厅的值班管理工作，确保值班期间餐厅的正常运营。<br>随着学习的深入及职级的快速晋升，您将学习到订存货管理、排班管理、利润管理、餐厅营销等经营一家餐厅的各项技能。<br>Q2：没有相关的工作经验，专业又不相关，会不会对面试有影响呢？<br>A2：这点不用担心，餐厅针对所有员工的培训都是从0开始的，入职后餐厅将制定详细的培训计划，安排1对1的培训，高效的培训也是百胜的优势。', '百胜中国控股有限公司是中国领先的餐饮公司，致力于让生活更有滋味。自从1987年第一家餐厅开业以来，百胜中国今天在大陆的足迹遍布所有省市自治区，在1,100多个城市拥有超过7,500家餐厅。百胜中国从Yum! Brands（纽约证券交易所代码：YUM）分拆出来之后，于2016年11月1日独立在纽约证券交易所上市，股票代码为YUMC。百胜中国在中国市场拥有肯德基、必胜客和塔可贝尔三个品牌的独家运营和授权经营权，并完全拥有东方既白和小肥羊连锁餐厅。经过三十年的发展，百胜中国不仅在店面数量，而且在品牌知名度、社交及数字媒体营销和传播、全国供应链管理、产品质量、以及创新方面都已经成为了一家中国领先的餐饮企业。百胜中国42余万的员工是其发展的支柱，与此同时，在百胜积累了经验丰富的管理团队和全情投入的前线伙伴也正在继续引领发展活力充沛、直面机遇和充满欢乐的企业文化。在包括风靡全球的肯德基原味炸鸡等产品的基础上，百胜中过还不断开发符合当地口味的产品，从而建立起强有力的顾客忠诚度。每一个品牌都有其专属产品，很多都是中国本土创新，同时公司也研发出众多独有产品与调味产品，为消费者提供美味便捷并且高品质的食物。通过在中国多年的发展与积累，已拥有深厚的消费者知识与忠诚度，各品牌的产品也已成功融入流行文化与消费者的日常生活之中。百胜中国将通过创新产品、提升就餐体验、增强移动连接、以及持续创造价值来满足消费者不断改变的需求。百胜中国对于未来长期的发展充满信心。', 'https://www.zhaopin.com/jobdetail/CC134529310J40637086401.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8968, '风电工程师', '智网(天津)电力发展有限公司', '5月30日', '8000-12000元', '贵阳-南明区', '新能源', '300-499人', '不需要融资', 'CCL1492156440J40692463912', '一、招聘要求：', '本公司是专注于为个人和企业提供风电产业、新能源光伏值班员、电力运维员产业等方向指导服务和专业咨询。公司属天津西青区，与京津冀多家新能源电力企业有深度合作，累计外派人才达到2000人以上，与电力相关企业均有合作。为求职者提供专业求职咨询，为企业提供资源管理一站式专业平台。本公司一直坚持以“至诚、至善、至精、至美而努力奋斗”的企业宗旨，自公司创建以来一直致力于风电产业、新能源产业、光伏、电力等相关产业的人才引进工作，持续为电力行业赋能。企业服务一流，做大做强，成为企业发展的目标。', 'https://www.zhaopin.com/jobdetail/CCL1492156440J40692463912.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8969, '风电工程师', '陕西风新能电力科技有限公司', '6月23日', '6000-12000元·14薪', '凉山-昭觉县', '新能源', '20-99人', NULL, 'CCL1483772690J40754250712', '一、任职要求：  1、电气、机械类相关专业有工作经验；', NULL, 'https://www.zhaopin.com/jobdetail/CCL1483772690J40754250712.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8970, '统计员', '山西龙城金服企业服务有限公司', '7月24日', '4000-8000元', '太原-小店区', '企业服务,企业服务,银行,咨询服务', '20-99人', NULL, 'CCL1477120860J40497685616', '温馨提示：岗位职责和要求及薪资待遇都有详细说明，如符合您的求职预期请及时联系或投递简历，不经常在线，消息回复不及时请留言，忙完会及时回复大家！如果合适会尽快安排入职，谢谢！预祝大家工作愉快！<br>一、职位描述：<br>1、接听来访电话、客户接待、邮寄快件等日常行政事务；<br>2、办公用品等采买和管控，各类资产的建档、维护管理；<br>3、高效处理日常事务，独立完成上级日常行程安排等工作；<br>4、文件处理、文档处理排版，确保内容条理清晰，账单处理；<br>5、人员的考勤管理和月考勤统计，完成领导交办的其他工作。<br>6、辅助销售主管做前期客户简单筛选沟通处理，归集信息，符合意向客户转到下一个环节转办。<br>7、主管交办的其他办公室辅助工作.<br>二、任职要求：<br>1，形象气质佳，大专以上学历，秘书、中文、英文等相关专业优先；<br>2、熟练掌握电脑操作及办公软件；<br>3、理解能力强，善于沟通协调，具备较强的文字表达能力；<br>4、具有服务理念和团队合作精神；<br>5、细心、踏实，勤奋、做事积极主动，有一定抗压适应能力和学习能力强；<br>三，福利待遇：<br>1、综合薪资4000-6500+(底薪+全勤+绩效+提成+年终...)单休无责3000双休无责2500.单双休可以自己选。<br>2、定期团建丰富员工生活；定期培训提供良好发展空间<br>3、月、季度、年度，不定时针对个人成长的培训机会；<br>4、公司有五险一金，但不是立刻马上，需要结合员工能力表现综合评定后上，具体面谈<br>5、 公司目前发展阶段，有良好的职业发展空间，业绩优秀且具备管理能力者，公司给予晋升机会学习带领团队经验，向管理层迈进。<br>6.大牛带队，年轻团队，团队气氛活泼，凝聚力大，晋升空间大，有梦想人的齐聚地<br>工作时间： 上午9:00-12:00 下午14:00-18:30 双休(部分单休) 节假日正常<br>地址:山西省太原市小店坞城路昌盛街锡和大厦5层，公交836、839、G6在【龙盛街唐明路口】下车即到(太原市住房公积金管理中心城南分理处、交通银行太原综改区支行同楼5层)到了楼下找不到可以随时电话或视频连线引导(来时尽量提前预约，以免耽误大家时间)<br>四、员工福利：五险，全勤奖，绩效奖金，年终奖，团队项目分红，小零食，生日福利、婚嫁福利、节日福利、每月团建活动；节假日正常休息；完善的晋升机制！、每年调薪、定期团建、优秀者晋升管理享受绩优分红。<br>五、其他福利待遇及相关可及时沟通也可直接到公司面谈 ，以上招聘信息如有不明确的地方请大家直接与人事沟通，尽量加上人事直接语音连线，咨询人员比较多，打字回复比较慢，直接语音连线沟通效率高一点，感谢理解！<br>六、温馨提示：①上述招聘要求及待遇基本一致②如符合大家的求职预期可进一步语音连线确定细节③符合后请及时发送简历并安排远程视频面试④视频面试沟通满意后再线下公司面谈.... 以免大家来回奔波浪费大家的宝贵求职时间。<br>七、欢迎踏实肯干的勤奋精英，真正想通过自己的努力付出获得相应收获的精英，非诚勿扰，感谢大家理解！祝大家都能找到诚心如意的工作', '山西龙城金服成立于2022年5月，主要经营范围：一般项目：企业管理咨询；财务咨询；税务服务；社会经济咨询服务；企业信用管理咨询服务；个人信用修复服务；企业信用修复服务；企业信用评级服务；企业信用调查和评估；商务代理代办服务；报检业务；票据信息咨询服务；政策法规课题研究；政府采购代理服务；法律咨询（不含依法须律师事务所执业许可的业务）；项目策划与公关服务；会议及展览服务；工程管理服务；互联网销售（除销售需要许可的商品）；商标代理；组织文化艺术交流活动；计算机软硬件及辅助设备零售；计算机系统服务；网络设备销售；计算机及通讯设备租赁；软件销售；技术服务、技术开发、技术咨询、技术交流、技术转让、技术推广；网络与信息安全软件开发；专业设计服务；广告设计、代理；广告制作；广告发布；平面设计；文艺创作；图文设计制作；日用品批发；户外用品销售；信息咨询服务（不含许可类信息咨询服务）；健康咨询服务（不含诊疗服务）；科技中介服务；企业形象策划；市场营销策划；教育咨询服务（不含涉许可审批的教育培训活动）；消防技术服务；网络技术服务；数字技术服务；信息技术咨询服务；软件外包服务。（除依法须经批准的项目外，凭营业执照依法自主开展经营活动）', 'https://www.zhaopin.com/jobdetail/CCL1477120860J40497685616.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8971, 'APP推广', '成都歪马科技有限公司', '7月28日', '9000-14000元', '上海-徐汇区', '电子商务', '1000-9999人', '未融资', 'CCL1492920960J40827049008', '核心优势<br>  💰 高薪无忧：综合薪资9000起！ 优秀店员轻松破万！兼职也能月入4000+！多劳多得，上不封顶！<br>  🏠 就近安排： 工作地点按你住址就近分配，通勤省时省力！<br>  🛡️ 收入保障：无责底薪 + 全勤奖 + 配送费（5.8-15元/单）！<br>  🚫 拒绝压力：无超时扣款！ 告别罚款焦虑，安心跑单！<br>  🎯 额外暴利：推广歪马APP，提成高达1-200元/单！ 轻松赚取额外高收入！<br>工作内容<br>  🍺 固定门店酒水配送： 只需服务固定一家门店，配送范围小（1-4公里），单量稳定有保障！<br>  📱 高提成推广： 利用空闲时间推广歪马送酒APP，每成功一单提成1-200元，操作简单，收益可观！<br>', '歪马送酒是美团旗下的酒水即时零售品牌，经营品类涵盖啤酒、白酒、红酒、洋酒四大品类。通过与酒水品牌直接合作，严控供应链，自建配送体系，给前置仓配货，商家在小程序和外卖平台为用户提供平价、保真、平均15分钟送达的酒水及时送服务。歪马送酒在2021年6月23日广东惠州开展单城探索，启动1个城市中心仓+N个前置仓，40天开仓8家，覆盖惠州主要城区。截止2024年7月，歪马送酒在广东地区（深圳、广州、东莞、佛山、惠州、汕头、江门、中山、河源），江苏地区（南京、苏州）、浙江地区（杭州、宁波、温州）北京、上海、杭州、成都、西安、重庆、武汉、福州等22个城市建有直营门店，门店数量超过家。2025年还会入驻青岛、南宁、郑州、合肥、贵阳等城市，预计实现全国省会城市、一线城市全覆盖，门店数量超1000+。', 'https://www.zhaopin.com/jobdetail/CCL1492920960J40827049008.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8972, '猎头顾问', '福州市升大培训学校', '7月12日', '5000-6000元', '福州-鼓楼区', '培训/辅导服务,咨询服务', '1000-9999人', NULL, 'CC598455320J40448746907', '★★★ 职业资格考证咨询<br>岗位职责：<br>1、负责职业资格培训考证，课程咨询，招生报名等工作；<br>2、负责中小学教师资格证、幼儿园教师资格证、教师招聘考试；<br>3、会计职称、人力资源管理师、建造师等培训考证工作；<br>4、初级、中级、高级工程师评审等相关工作<br>5、完成学校领导交办的其他工作任务。<br>岗位要求：<br>1、大专及以上学历，身体健康，年龄20-26岁（有经验优秀者35岁以下均可）；<br>2、端庄大方，普通话标准，亲和力强，善于沟通；<br>3、工作态度积极，良好的心理素质，能熟练操作各种办公软件；<br>4、有责任心和责任感，思维敏捷、较强的文字功底；<br>★★★薪资待遇：年薪5— 7万（基本工资+周末双倍工资+绩效奖+超额奖+餐补+通讯补贴），上不封顶，年终按业绩发放奖金。<br>★★★福利保障：享受养老保险、医疗保险、失业保险、生育和工伤保险。每月休息4天；节日福利、带薪培训；<br>★★★ 面试地点：福州市东街口利达大厦A座9层。福州升大学校。<br>★★★ 面试时间：合者约见。<br>如果你符合以上要求，并且对招生咨询工作充满热情，欢迎加入我们的团队！让我们一起为学生的未来努力，共创美好明天！', '福州升大学校经教育部门批准成立，办学历史悠久，为社会培养各类人才数以万计，是本市名列前茅的大规模的培训学校。师资力量雄厚，设备齐全，多媒体教室12间、电脑300多台。国家教育部自考办授予升大学校“全国示范助学组织”，福建省自考办授予升大学校“全省示范助学组织”“自考20周年先进集体”。被微软（中国）公司指定为微软MLC授权培训与考试中心、Adobe平面设计师授权培训与考试中心、Adobe授权培训与考试中心、全国计算机信息技术考试站、全国英语等级培训点、全国职业资格统一鉴定报名点。升大学校开设有：高等教育自学考试大专、本科辅导班；全国成人高考辅导班；全国英语等级考试辅导班；全国计算机等级考试辅导班；电脑系列培训；外语系列培训；会计系列培训；全国职业资格考前辅导班；会计电算化考证培训班。本校办学多年成绩显著，是人气最旺的名校。升大拥有一批国内优秀的讲师、以及在专业领域工作了十几年的优秀实战讲师；拥有系统的实战型教学体系、完善的就业推荐机制；拥有专业的硬件设备、以及培训制作一体化的优良学习环境。同时，也为学员提供了优秀的实战平台，使学员在培训期间就有接触、了解并参与大型项目实际制作的机会，而这正是“升大学校”人才培养的最重要特色。福州日报、福州晚报、海峡都市报、东南快报、福建电视台、福建教育电视台、福州电视台等多家新闻媒体前来采访并作了报道，三十多年的办学经验，教学硕果累累，如今升大已桃李满天下，从升大走出的人才遍布海内外各个行业，升大教育的办学质量也得到了国家教育部门和社会各界的赞誉。', 'https://www.zhaopin.com/jobdetail/CC598455320J40448746907.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8973, '销售工程师', '双良节能系统股份有限公司销售分公司', '7月14日', '5000-10000元', '呼和浩特-新城区', '电力/水利/热力/燃气', '10000人以上', '已上市', 'CC213538610J40710461902', '一、 职位描述：<br>1.负责公司项目信息的收集、汇总及进度跟踪；<br>2.有效开发新客户，并维护老客户的良好关系，建立客户档案；<br>3.通过面谈或者电话沟通，深入了解客户需求，协调公司内部资源，及时解决客户反馈的问题；<br>4.参与项目策划工作，制定方案，签订销售合同；<br>5.跟踪项目的完成进度及目合同款的催收工作。<br>二、任职要求：<br>1、工作地点：内蒙区域<br>2、学历：本科及以上学历：<br>3、工作经验：<br>- 理工科背景：需具备2年以上大型设备销售经验； <br>- 文科背景：需具备5年以上大型设备销售经验； <br>- 有B2B大客户销售经验或行业资源者优先；<br>4、年龄：25岁--38岁；<br>5、专业：机械类、电气类、换热类、化工类、市场营销类等相关专业；<br>6、工作能力：<br>- 热爱销售工作，具备强烈的事业心和抗压能力； <br>- 沟通表达能力强，逻辑清晰，擅长商务谈判及客户关系维护； <br>- 适应全国范围内出差及跨区域调配，服从公司工作安排； <br>- 具备团队协作精神，能高效协调内外部资源推动项目落地。。<br>三、薪资福利：<br>- 薪资结构：底薪+ 提成+ 补贴； <br>- 福利保障：五险一金、年度健康体检、节日福利； <br>- 员工关怀：生日蛋糕、团队建设、职业培训。', NULL, 'https://www.zhaopin.com/jobdetail/CC213538610J40710461902.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8974, '电话客服', '新疆乐学无忧正岳教育咨询服务有限公司', '5月26日', '7000-14000元', '乌鲁木齐-新市区', '培训/辅导服务', '20-99人', NULL, 'CCL1463417280J40567390409', '岗位职责：<br>1、通过电话与学员进行有效的沟通了解其真实需求，指导学员报考意向高校和专业。寻找招生机会并完成招生业绩。<br>2、办理学员的协议签订，报名注册等工作。<br>3、研究生考前辅导课程的推介与销售。<br>4、做好学员转介绍管理。<br>5、拓展新客户。<br>任职要求:<br>1、高中及以上学历，年龄20-40岁。<br>2、普通话标准，良好的沟通表达能力<br>3、热爱销售、执行力强、有责任心、团队合作意识强', '本公司主营：信息咨询服务行业只要你心怀感恩，只要你愿意付出，只要你能够坚持，只要你有梦想，只要你想创业，在这里，给你广阔的舞台，在这里，成就你心中的梦想。只有你真正加入它，了解它，才能真正体会到有梦想就有实现的可能。选择大于努力，不甘平庸的平凡年轻人，加入我们吧', 'https://www.zhaopin.com/jobdetail/CCL1463417280J40567390409.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8975, '咨询顾问', '济南天姣广告传媒中心', '4月28日', '4000-7000元', '济南-济阳区', '咨询服务', '20-99人', NULL, 'CC602764520J40581319912', '岗位内容：负责接待解答客户问题，接听客户电话提供相关公司服务售后售前咨询，纯接听无外呼不销售，     岗位要求：17周岁以上，会操作计算机 ，', NULL, 'https://www.zhaopin.com/jobdetail/CC602764520J40581319912.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8976, '英语翻译', '广州易库科技有限公司', '7月29日', '7000-9000元', '广州-海珠区', '汽车后市场,汽车后市场,汽车零部件', '20-99人', '不需要融资', 'CCL1484825100J40761490309', '一、岗位内容：  1.此岗位是要招聘以为出国商务谈判的随同翻译；', '广州易库科技有限公司主要涉足于车用精品、汽车礼品、汽车改装等汽车后市场相关业务。主要包括汽车改装、汽车美容、汽车装饰等方面的各种车用产品，以提升车辆性能、外观、舒适度或者安全性；采用专业设计，定制礼品方案，以关怀汽车、汽车人为出发点，承载汽车文化，为满足汽车企业及其客户的需求而服务。自2014年在广州成立，团队人员超过40人，各部门配备完善。坚持“科学管理、诚信经营、客户第一、用心服务”四个理念，为客户提供优质服务。目前合作的品牌有纳科达、金三塔等一些知名的供应商，主要服务与广汽集团。', 'https://www.zhaopin.com/jobdetail/CCL1484825100J40761490309.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8977, '总助/CEO助理/董事长助理', '邳州市东方养殖有限公司', '7月17日', '8000-13000元', '南京-建邺区', '农/林/牧/渔,生物工程', '100-299人', '未融资', 'CC211017930J40710867109', '南京天蓬生物科技有限公司招聘启事<br>职位：总经理助理（储备管理岗）<br>人数:3名<br>公司简介 <br>南京天蓬生物专注于实验动物模型研发与技术服务，是江苏省实验动物协会理事单位，与多所高校、科研机构建立战略合作。现因业务扩展需求，诚聘优秀人才加入！ <br>岗位亮点<br>- 薪资竞争力：试用期8k/月，转正13k（含社保）+ 差旅补贴 <br>- 成长加速度：高管一对一辅导，接触核心业务与行业资源 <br>- 发展通道：优秀者可晋升市场大区负责人/部门管理者 <br>- 福利保障：单休+节日礼金+年度体检+带薪培训 <br>岗位职责<br>1. 协助总经理处理日常行程、会议安排及商务接待 <br>2. 陪同参与行业论坛、客户洽谈等商务差旅（月均10天） <br>3. 撰写业务报告，跟进重点项目执行进度 <br>4. 协调跨部门协作，督办重要事项落实 <br>任职要求<br>1. 2024届硕士毕业生（生物医药/管理类相关专业优先） <br>2. 985/211院校或QS前200海外高校背景 <br>3. 具备快速学习能力，熟练使用Office办公系统 <br>4. 适应高强度工作节奏，能接受短期高频差旅 ，有驾驶证，可以少量饮酒。 <br>5. 逻辑清晰、抗压能力强，具备商务谈判基础素养', NULL, 'https://www.zhaopin.com/jobdetail/CC211017930J40710867109.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8978, '律师助理', '广东商达律师事务所', '7月25日', '4000-6000元', '湛江-霞山区', '法律服务', '300-499人', '不需要融资', 'CC542019220J40556805303', '岗位要求：<br>1、通过国家司法考试者优先、有驾驶经验者优先；<br>2、工作细致、责任心强、吃苦耐劳；<br>3、具有团队精神、思路清晰、表达能力强。<br>岗位职责：<br>1、负责客户、案件信息的收集和管理；<br>2、为客户和潜在客户提供优质高效的服务； <br>3、按照事务所的收案标准和要求协助团队律师接案，并跟进办理案件；<br>4、跟进案件办理流程，将客户交办的法律服务事宜的进展与客户进行及时有效的沟通；<br>5、为客户提供部分非诉法律服务；<br>6、准确、及时、全面地完成办案律师和团队律师交付的工作任务。<br>工作时间：单休', '广东商达律师事务所是经广东省司法厅依法批准设立的一家高起点、高标准的综合性大型律师事务所，办公地址位于深圳福田区中国凤凰大厦1栋21层，办公面积2000余平方米。深圳市大型综合性律师事务所之一。商达现有律师、实习律师、律师助理300余人。商达律所立志于打造覆盖珠三角城市群的规模化、专业化、高端化的一流品牌连锁律师事务所。目前，商达共设立了9家分所，分别为商达龙华分所、商达龙岗分所、商达前海分所、商达广州分所、商达惠州分所、商达东莞分所、商达佛山分所、商达南宁分所、商达中山分所。珠海分所、武汉分所、肇庆分所、江门分所……正在筹备设立中。本所拥有成熟的规模化、团队化的管理模式，有着独特的经营理念和成熟的专业服务领域，以公司法律服务为核心，能够为国内外客���提供企业改制、公司治理、公司并购、公司上市、投融资、破产清算、证券期货、知识产权等全方位、综合性法律服务。', 'https://www.zhaopin.com/jobdetail/CC542019220J40556805303.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8979, '销售运营', '郑州聚莱电子科技有限公司', '7月22日', '4000-8000元', '郑州-管城回族区', '互联网', '100-299人', NULL, 'CCL1323051880J40733269411', '没经验？不怕！我们看重态度和潜力，只要你敢想敢试，这里就是你的“运营实验田”！  <br>工资虽不暴富，但能让钱包“体面生存”，更重要的是——  <br>这段经历会让你的简历在秋招/春招中，比别人多一颗亮闪闪的星星！  <br>', '郑州聚莱电子科技有限公司是一家以生产，开发，营销为一体，以人才培养为核心，通过公司的人才培养理念，务实有效的人才培养系统，结合线上线下资源，打造互联网雇佣军的创客平台，针对客户产品特性，定制推广方案，其经营范围涉及到生活用品，互联网、人工智能，移动通讯等领域，满足市场智能健康生活用品消费需求，主打产品有：互联网广告、App推广、人工智能、家用办公百货、产品畅销全国各地！公司自成立以来，不断谋求新的发展思路，专注全国各地市场开发，目前合作平台有抖音，百度，高德，腾讯，移动，联通，电信等上市企业，集团在郑州，长沙，重庆，福州，厦门，贵阳，南宁，南昌等全国各地设立分公司，和全国多家互联网企业及商超达成战略合作联盟，郑州聚莱电子科技有限公司将不断对接互联网企业，人工智能领域，品质过硬的商家，为消费者提供优质健康的产品创业伙伴提供了自由发挥潜能的空间，让创业伙伴更满意，幸福指数更高，期待广大有志青年的加入，让我们携手共创美好未来！', 'https://www.zhaopin.com/jobdetail/CCL1323051880J40733269411.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8980, '猎头顾问', '北京福睿思特国际人力资源有限公司', '7月22日', '5000-8000元', '张家口-桥东区', '人力资源服务,咨询服务', '300-499人', '不需要融资', 'CC889990540J40664764506', '职位描述<br>一、工作性质及地点<br>工作性质：全职，远程居家办公，国家、省份、地区均<br>不限<br>【工作内容】<br>猎头顾问：是属于人事招聘＋业务性质的岗位<br>从事人力资源中高端岗位的招聘工作，是给客户公司招聘中高端岗位人才和专业技术型人才。<br>【猎头日常工作流程】<br>1、根据客户公司的岗位需求，做好职位分析；<br>2、通过网络渠道及公司现有人才库和转介绍方式寻访<br>到符合岗位的人才模型的简历；<br>3、通过电话跟候选人进行沟通，整理候选人简历信息<br>做成推荐报告 （算做初步面试）；<br>4、报告审核通过后邀约候选人到客户公司去面试;<br>5、候选人面试通过后，进行 offer 谈判、薪酬谈判背景<br>调查等工作;<br>6、等到候选人成功入职，客户回款，就能拿到相应的佣金提成。<br>【任职资格】<br>1有一定的招聘或销售经验，且有志向在猎头行业长期发展;<br>2、善于与人沟通，有一定的客户服务意识，思维缜密，关注细节；<br>3、良好的团队协作意识，成熟稳重，能够承受较大的工作压力，具有高度的责任感<br>4、有人事招聘工作经验、电话销售经验者优先考虑<br>5、英语或其他外语可作为工作语言优先<br>【薪资结构】<br>基本工资＋绩效工资＋项目提成 （40%-70%）＋年底红包奖励<br>职位优势<br>1.全职岗位，缴纳五险一金，高提成机制，月度发放。<br>2.远程在家远程办公，居家办公，更为灵活自由。<br>3. CEO直接管理和培养、培训，近水楼台先得月，成长迅速。<br>4.上下班不需要打卡，周未双休。<br>5. 和on-site 员工一样享有公司多种福利和活动参与。<br>(年度体检、年假、生日会、周年庆、节假日礼物、年底红包)<br>职位福利：五险一金、周末双休、弹性工作、定期体检、年底双薪、带薪年假<br>职位亮点：全职居家办公 六日双休 五险一金', 'FORESTOWN成立于中国北京，是一家具有丰富国际中高端猎头服务经验和人力资源管理咨询服务经验的全球化组织新生代企业。FORESTOWN长期致力于将客户商业战略和人才战略相结合，助力客户公司实现快速发展，行业地位快速提升。FORESTOWN在全球目前设置了三个办公室：美国圣何塞、德国汉堡、中国北京。这三家办公室业务辐射范围从所在城市到整个北美洲、欧洲、亚洲以及其他大洲，构建了强大的服务体系，服务客户遍布全球。在未来的十年内，FORESTOWN会持续在全球多个城市开设办公室，便于服务世界各地的客户。 WHAT WE DO FORESRTOWN的服务内容主要涉及：全球中高端人才寻猎服务及相关衍生服务、中高端人才职业发展咨询服务，以及面向全球企业端的的人力资源管理咨询服务。 CONSULTANT TEAM FORESTOWN的顾问团队来自于不同行业及文化背景，具有学士至博士学历，可双语甚至多语言工作。他们都是具有各行业专业工作经验的专家或在猎头行业内有多年从业经验的资深猎头顾问，经手并合作成功的客户不胜枚举，作为客户公司的商业合作伙伴和咨询顾问获得了充分的认可和信任，并长期保持友好合作关系。 INDUSTRIES FORESTOWN业务涉及到众多行业。包括但不限于：金融、IT/互联网、游戏、地产/建筑、人工智能、快消、电商、航空、制造、能源/电力、汽车、教育、传媒、医疗、农业科技、纺织、化工/检测、咨询等。', 'https://www.zhaopin.com/jobdetail/CC889990540J40664764506.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8981, '售后客服', '西安晟之恒人力资源有限公司', '7月25日', '6000-7000元', '西安-雁塔区', '人力资源服务,专业技术服务,人力资源服务,咨询服务', '20-99人', '未融资', 'CC826268740J40631408412', '【工作内容】   <br>', '深圳市成之恒人力资源有限公司，于2015年经深圳市市场监督管理局批准成立，拥有深圳市人力资源和社会保障局颁发的人力资源服务许可证和劳务派遣许可证，公司总部位于深圳市，目前在北京及广州、西安拥有分公司。成之恒致力于为客户提供精准、快捷、多元化的人力资源综合配套解决方案,依靠专业进取的业务交付团队、战略化的人员储备、以及宽广的招聘来源渠道，在结果最优的情况下为客户业务发展提供成本最低、流程和效益最佳的综合人力资源管理服务。成之恒业务涵盖劳务派遣、招聘流程外包（RPO）、猎头服务、业务流程外包（BPO）、HRBP服务、薪酬代发、社保代理、临时工（灵活用工）服务以及呼叫中心外包等。合作客户包含世界500强国企、上市公司等众多知名企业，涉及包含金融、通信、物流、餐饮快消、教育培训等多重领域。合作公司包括腾讯、58到家、京东、美联英语、阿卡索外教网、德邦物流、苏宁等大型企业。基于成熟的运营模式、出色的业务团队及合作伙伴客户的高度认可，公司发展迅速，现业务遍及华南华北众多省市。旗下CC品牌包括“CC外包”、“CC速聘”、“CCHR”、“CC呼叫中心”，依靠不断创新努力前行，成之恒目标成为人力资源行业领先企业。', 'https://www.zhaopin.com/jobdetail/CC826268740J40631408412.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8982, '档案管理', '重庆熙瑞梵企业管理咨询有限公司', '5月7日', '5000-8000元', '重庆-江北区', '互联网金融/小额贷款', '100-299人', NULL, 'CCL1493114250J40735752810', '就是前期的一个岗位，只负责处理系统上的订单查看审核通知和资料录入协助处理，你要付出的是时间和耐心，反复的做同一件事情，要接受工作的枯燥。对客户提交的数据资料进行及时筛选处理<br>不找客户、不外出、不催收。<br>年龄：18-28<br>1不外出不跑销售;<br>2.负责客户提交的订单资料进行系统录入和核实情况并整理<br>客户相关信息移交到其他部门同事接手就可以了;<br>3.主要负责评价前期附件资料:不外泄公司的任何资料数据;<br>5.该岗位为急招岗位，入职公司会提供免费培训 包住<br>上班时间:早九晚六 午休:12:00-14:00下午茶各半小时', NULL, 'https://www.zhaopin.com/jobdetail/CCL1493114250J40735752810.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8983, '律师', '广东法导律师事务所', '6月24日', '1-1.5万', '广州-天河区', '房地产中介', '20人以下', NULL, 'CC679194680J40438744010', '1、为人正派、负责，没有不良执业记录;<br>2、熟悉诸如公司法、证劵法、刑法、劳动法等某一专业法律领域;<br>3、已取得律师执业证，能独立办案;<br>4、有5年以上法务实际工作经验；<br>5、薪酬模式:面议;<br>6、律所免管理费、提成高，并提供部分案源。', '法导所办公地点位于广州市天河区越垦路611号力达广场燕岭公园山麓，地铁3、6号线燕塘站交汇处，交通便捷环境优美。“对内减轻律师执业负担、对外提供优质法律服务”是法导所的创业理念。法导所利用律师团队长期为企业法律服务而积累的丰富经验，力争为企事业单位提供更优质的法律顾问服务。', 'https://www.zhaopin.com/jobdetail/CC679194680J40438744010.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8984, '律师助理', '北京盈科(沈阳)律师事务所', '3月15日', '1000-2000元', '沈阳-和平区', '咨询服务', '500-999人', '不需要融资', 'CC474921123J00270624001', '实习律师任职资格：<br>1、通过司法考试，具有良好的法学专业功底，法律专业本科以上学历或有公司法务、政法机关一年以上工作经验，研究生以上学历优先，自身条件特优者,可适当放宽上述条件；<br>2、熟练应用办公软件，具有良好的沟通能力、人际交往能力和语言表达能力；<br>3、有志长期从事律师法律服务工作，具有较强的责任心和执行力，富有工作热情和团队意识；<br>4、认同盈科律师事务所发展理念、适应盈科所创新发展模式；<br>5、符合条件并通过面试者我们将协助办理实习律师资格。<br>联系方式：<br>公司名称：北京盈科(沈阳)律师事务所<br>公司地址：辽宁省沈阳市和平区青年大街286号华润大厦A座36层<br>招聘热线：************<br>公司主页：www.yingkelawyer.com<br>', '北京盈科（沈阳）律师事务所（简称“盈科沈阳”）位于沈城商业金廊5A级写字楼华润大厦A座，办公面积近4000平，由盈科总部直接投资、管理，截至2024年2月，员工总人数593人，注册律师人数已达481人，2010年创立至今已发展为东北地区规模最大的律师事务所之一。律所坚持“规模化、专业化、品牌化、国际化”的发展方向，并于2021年开启“国际化、专业化、数智化、碳中和”高质量发展新阶段，利用盈科全球资源平台优势，在商务法律领域不断拓展深度与广度，持续提升法律服务的综合实力，目前已正式设有31个专业法律部门及4个处于筹备期的专业法律部门，能够满足客户的全方位法律服务需求。盈科沈阳2014年被市司法局评为沈阳市“AAA诚信律师事务所”，2016年被省司法厅评为辽宁省“2014-2015年度优秀律师事务所”，2018年被沈阳市律师协会评为“2017-2018年度沈阳市优秀律师事务所”， 2020年被沈阳市工商联系统评为2019年度公益慈善先进企业，同年被中华环保联合会授予“环境权益维护志愿律师事务所”荣誉称号；2021年被沈阳市和平区司法局与沈阳市律师协会和平区代表处授予“2019-2020年度优秀律师事务所”称号；2023年被辽宁省司法厅授予“2019-2022年度辽宁省优秀律师事务所”称号。“流水之为物也，不盈科不行；君子之志于道也，不成章不达”。盈科沈阳分所将努力发挥自身商务律师事务所的优势，为客户提供优质、高效的法律服务，让客户满意。', 'https://www.zhaopin.com/jobdetail/CC474921123J00270624001.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8985, '销售工程师', '吉林省亿川智能机器人科技有限公司', '2025-07-27 00:00:02', '4000-8000元', '长春-绿园区', '工业自动化', '20人以下', NULL, 'CC886878540J40468987214', '工作职责', NULL, 'https://www.zhaopin.com/jobdetail/CC886878540J40468987214.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8986, '销售助理', '北京华威锐科化工科技有限公司', '12月20日', '4000-6000元', '佛山-南海区', '医药制造', '20-99人', '不需要融资', 'CC184054920J40202621506', '岗位职责：<br>1、负责公司销售合同等文件资料的管理、归类、整理、建档和保管；<br>2、负责各类销售指标的月度、季度、年度统计报表和报告的制作、编写，并随时汇报销售动态；<br>3、负责收集、整理、归纳市场行情，提出分析报告；<br>4、协助销售经理做好电话来访工作，在销售人员缺席时及时转告客户信息，妥善处理；<br>5、协助销售经理做好部门内务、各种内部会议的记录等工作。<br>任职资格：<br>1、专科以上学历，形象气质佳；<br>2、从事过销售助理或统计类工作者优先考虑；<br>3、做事认真、细心、负责；<br>4、熟练使用office等办公软件；<br>5、身体健康，具有服务意识，能适应较大的工作压力；<br>工作时间：8：30-17：30<br>职位福利：五险一金、绩效奖金、年终分红、全勤奖、餐补、通讯补助、不加班', '华威锐科化学是一家集研发、生产、销售于一体的高科技化学试剂专业供应商与全渠道专业化学品电子商务平台，拥有一支具有多年专业背景、极富创造力的优秀团队。目前，公司在北京、上海、广东设立有三个分公司。我公司是美国Gelest和ScienMax的中国指定合作伙伴，同时公司与国内外多家知名的化学公司建立了紧密的合作关系，产品覆盖8余万种，可立即供应的常备库存达1万种以上！此外，我们公司的全球资源优化网络系统，能够在最短时间内为你的工业化的产品筛选提供更具实力的供货商，为客户提供更全面的服务。', 'https://www.zhaopin.com/jobdetail/CC184054920J40202621506.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8987, '总助/CEO助理/董事长助理', '合肥长河科技服务有限公司', '7月9日', '5000-10000元', '合肥-蜀山区', '电子商务,在线生活服务（O2O）', '20-99人', '不需要融资', 'CC892180380J40923425504', '岗位职责：​​<br>1. ​战略执行与协调支持：​​<br>· 学习理解公司战略方向与目标，在指导下参与年度/季度目标的拆解与初步执行计划的辅助制定。<br>· 协助跟进部门简单任务的落实情况（如信息收集、初步进度核对），学习项目管理流程。<br>· 在指导下，协助进行跨部门信息的初步传递与基础沟通，了解公司业务流程。<br>2. ​决策与信息支持：​​<br>· 协助收集、整理行业新闻、市场基础数据及竞品公开信息。<br>· 学习基础的信息分析框架，在指导下制作简单的数据汇总图表或报告雏形。<br>· 协助起草日常邮件、基础通知、部分标准化的文件资料（需经理审阅），学习专业文件的撰写规范。<br>3. ​高层事务协助：​​<br>· 在指导下，协助总经理日常行程的初步整理与预约协调，学习高效的日程管理方法。<br>· 协助准备会议材料、记录会议纪要并完成初步整理；学习跟进简单决议事项的落实情况。<br>· 协助处理总经理的部分基础性沟通联络事务（如邮件转发、基础信息传达），并在实践中学习商务礼仪。<br>4. ​行政事务辅助：​​<br>· 学习并熟悉公司现有的行政管理体系与制度流程。<br>· 协助执行部分行政后勤支持工作（如办公用品申领协调、会议室管理等），保障基础办公秩序。<br>· 在指导下，协助处理流程清晰的日常事务或突发事件，学习应急响应流程。<br>​任职要求：​​<br>1. ​学历与潜力：​​<br>· 2024届应届毕业生，本科及以上学历，​工商管理、市场营销、电子商务、行政管理、经济学、语言类等相关专业优先。​​<br>· ​对互联网、本地生活服务、O2O或大型企业运营管理有浓厚兴趣与学习热情者优先。​​<br>2. ​核心能力与素质：​​<br>· ​优秀的理解能力与学习能力：​​ 能够快速学习新知识、新流程，理解复杂信息的核心要点。<br>· ​基础的逻辑思维与分析意识：​​ 能够对简单问题进行初步思考和分析；具备强烈的好奇心和求知欲。​​<br>· ​良好的沟通表达与协作意愿：​​ 能清晰地表达观点（口头和书面），具备积极的团队合作精神，愿意向不同层级的同事学习。<br>· ​扎实的文字基础：​​ 具备良好的中文写作能力，表达清晰流畅；英文基础良好（CET-4或同等水平以上）。<br>3. ​职业素养：​​<br>· ​责任心强，积极主动：​​ 有担当意识，对待工作细致认真，能尽力按时完成任务。<br>· ​高度的诚信与保密意识：​​ 理解并承诺严格遵守公司保密规定。<br>· ​踏实勤奋，吃苦耐劳：​​ 能适应快节奏工作环境，有较强的抗压能力和韧性。<br>· ​细致耐心：​​ 对细节有一定关注度。<br>4. ​技能要求：​​<br>· 熟练使用 Word, Excel, PowerPoint 等常用Office办公软件。<br>· 掌握Excel基础操作（如公式、图表制作），了解PPT设计基础。<br>· ​对数据分析感兴趣或具备基础了解者为佳（如在校学习过相关课程、接触过数据工具入门知识）。​', '合肥长河科技服务有限公司成立于2019年07月24日，是安徽长河园区运营管理有限公司全资子公司。2024年11月，长河科技开发上线了O2O生活新平台--O小盟。O小盟不只是一个平台，更是一种解决消费者、商家和创业者困难的全新商业生态。它让消费者“花钱有回报”，让商家“盈利更简单”，让创业者“低风险起航”。 O小盟基于“经营费用转化、积分补贴促复购、绿色共赢生态”，通过创新的商业模式帮助商家降低经营压力、提升盈利能力，同时为消费者提供更划算的消费体验，最终实现商家、消费者与平台的多方共赢。O小盟的使命：让实体商家经营更容易 O小盟的愿景：帮助1亿个家庭过上美好生活', 'https://www.zhaopin.com/jobdetail/CC892180380J40923425504.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8988, '网络客服', '博岳通信', '7月12日', '5000-7000元', '石家庄-裕华区', '运营商/增值服务,IT服务,通信/网络设备', '10000人以上', NULL, 'CC351377410J40642167001', '工作内容：解答用户抖音钱包存在的问题比如：自动付款、无法开通、无法使用等情况<br>工作时间：8-24点排班（22:00以后补助20元） 月休7-8天<br>食堂，娱乐休息室，宿舍 ，员工生日会、定期旅游、团队融洽，急聘，有意向联系', '河北博岳通信技术股份有限公司是一家大型的电子商务、呼叫中心运营及信息服务供应商，主要从事大数据建模/分析/应用、呼叫中心运营、运营商业务渠道、云服务、网络与信息服务业务。专注于为运营商、电子商务、金融、互联网企业和中小企业提供端到端的运营及服务解决方案。公司现有员工15000名，拥有运营坐席超过16000个，目前在北京、河北、四川、湖南、江西、辽宁、福建、宁夏、贵州、浙江、陕西等多个省市设有分公司和办事处。在大数据应用和呼叫中心运营领域，博岳股份与全国十几个省市通信运营商客户进行了全面合作,包括北京移动、中国移动咪咕公司音乐基地、咪咕动漫、四川移动、河北移动、河北铁通、宁夏移动、卓望信息、辽宁移动、江西移动、陕西移动、湖南电信、贵州联通、虚商迪信通；博岳股份与十几家互联网企业在运营和服务领域进行全方位的合作，包括小米科技、去哪网、多点生活、牛电科技、海选网运营支撑服务；博岳与互联网金融九鼎投资-借贷宝进行了全方位的战略合作，包括人人行客服、人人行催收、人人推和研发合作。博岳股份全面服务于通信运营商、金融、电商及互联网企业，服务用户超过5亿。在云服务领域，基于互联网模式建立了端到端的云客服平台，向互联网企业和各中小企业提供系统平台、数据库、数据建模及分析、物理场所、台席、人员及培训等端到端解决方案；为互联网企业和各中小企业提供快速、便捷、性价比高的优质服务。同时公司根据客户的需求，为客户设计完整的呼叫中心解决方案，并负责呼叫中心的建设、运营与维护，承接客户的对外联络、咨询、投诉、问卷调查、营销、客服等各项工作。作为河北省高科技企业，博岳股份于2016年3月份成功挂牌新三板。公司具备工信部颁发的“中华人民共和国增值电信业务经营许可证（全国呼叫中心业务许可证、河北省因特网信息服务业务许可证）”、“通信信息网络系统集成乙级”及“道路运输经营许可证”等资质，并且通过了ISO9001质量管理体系和ISO14001环境管理体系等权威认证。博岳股份立志发展成为业界一流的信息服务和网络服务提供商，博岳股份全面向世界优秀企业学习。博岳股份吸纳业界优秀人才，聚焦客户、聚焦业务，实现平台化和规模化的管理和运作，公司将秉承“以客户为中心、以贡献者为本、持续艰苦奋斗”的企业核心价值理念，我们相信通过全体员工的不懈努力和追求，一定能够为客户提供最好的解决方案和最优质的服务，并为客户实现商业成功!', 'https://www.zhaopin.com/jobdetail/CC351377410J40642167001.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8989, '网络客服', '广州市茶莫停茶业有限公司', '6月3日', '4000-6000元', '佛山-南海区', '食品/饮料', '20-99人', NULL, 'CCL1280033480J40714162801', '任职要求:  <br>1、头脑灵活，可同时与多人以上进行网上交流，负责售前、售中、售后，待人热情，有良好的服务意识，工作耐心细致!  <br>2、电脑使用熟练，打字速度快，熟悉办公软件和网络工具。  <br>3、能适应两班倒;  <br>4、熟悉线上物流配送相关流程;  <br>5、有电商客服工作经验者优先;', '①茶莫停于2000年深耕云南易武，品牌创建于2007年，并设立广州芳村全国运营中心。 2009年正式推出系列产品，全面品牌化、规模化运营②茶莫停是一个独具新起点专注易武高端普洱茶，高定位集研发、生产、销售、服务为一体的特色茶企业。③一直只做纯料易武茶，以纯料易武追求极致的茶品质、以茶同享为执着追求。以原料的基础品质为中心，追求传统工艺、纯手工压磨精制，茶叶松紧度适当，完整条索清晰，内含物质得到更好保护，注重转化，良好的工艺易于疏风透气缩短自然转化的周期，有益于茶叶口感、风味的变化，注重品质，保证收藏价值。好茶莫停茶厂占地面积十亩，建筑面积6000平方米，是一家集茶文化体验、加工生产和普洱茶仓储区于一体的现代化、规范化的标准化、园林式生产基地。茶莫停，从茶叶种植、初制、精制、生产、销售、品牌化运营、全球服务，及农、工、商一体，自主完成由茶园到茶杯全流程一体化的现代茶企。欢迎广大有志青年加入，共创共赢。', 'https://www.zhaopin.com/jobdetail/CCL1280033480J40714162801.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8990, '商务专员', '武汉赛微思财税服务有限公司', '4月10日', '6000-9000元', '武汉-江汉区', '互联网,咨询服务,计算机软件', '100-299人', '未融资', 'CC514004530J40513011604', '岗位职责： <br>1、为各行业客户提供[灵活用工]的解决方案，建立自有资源库 <br>2、电话沟通，了解企业客户实际需求，邀约拜访，深度了解公司财税情况并根据企业实际困难，为企业规划专业合理的方案;  <br>3、根据公司提供的或自有的资源开展税务筹划(包括灵活用工，工商代账、股权筹划、增值税筹划、企业所得税筹划、个税筹划等)业务  <br>任职要求： <br>1、口齿清晰，普通话流利，良好的沟通表达能力 <br>2、高度敬业，责任心强、积极上进，具备较强的团队协作意识，以及较强的资源协调能力 <br>3、统招大专及以上学历，ToB经验 <br>薪资福利： <br>1、无责4~6K+高额提成（高于同行）+各项补贴，综合年薪10W+/年 <br>2、作息时间:周一至周五:8:30--18:00(周末双休）法定节假日按国家标准休假 <br>3、5A级办公写字楼，设施设备齐全，办公环境良好  <br>4、具竞争优势的薪酬制度(在家办公期间全额发放薪资)、科学的考核体系、健全的晋升机制、广阔的发展空间。 <br>5、完善的员工培训:专业知识、产品知识、沟通技巧、管理技巧、企业文化、个人能力提升等。  <br>7、轻松的办公氛围、丰富的员工福利，如:年会、各种团队建设活动、户外拓展培训、国内外旅游奖励、亲子活动、五险、年终奖、超长带薪年假。 <br>', '武汉赛微思财税服务有限公司成立于2017年5月作为北京公瑾科技有限公司核心产品慧算账区域运营商，乘互联网之潮+综合财税服务+云计算以改善与升级本土中小微企业财税服务现状为己任已成为武汉财税服务领导品牌为中小企业提供包括代理记账、工商注册、工商变更、税务审计、税务代办、社保托管、财税咨询、商标注册及金融服务等企业服务公司现有员工规模100人左右旗下分为市场渠道管理中心商务管理中心会记运营中心人力资源管理中心坐落于武汉商业中心武商写字楼公司均来自90后员工我们团队都是年轻有活力有梦想核心团队心团队公司高度重视人才的培养及引进,我们致力于为所有员工打造一个舒适、轻松的工作环境，为大家提供一个广阔的职业发展平台我们的经营团队：履历丰厚，经验强大，颜值超高我们的管理团队：来自各行各业的销售精英+本土成长起来的一群\\\\\"神斗士”我们的员工：清一色95后、美女如云、独立自主、脑洞超大。我们的经营理念：我们不是无所不能，但我们一定竭尽所能！我们的工作理念：在工作中认识自我，在工作中展示自我，在工作中体现自我，在工作中成就自我我们的工作环境：开放式办公+科技感超强+无人货架实时购买。我们的团队构成：非主流+二次元+资深管理者。我们的用人理念：一代更比一代强！', 'https://www.zhaopin.com/jobdetail/CC514004530J40513011604.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8991, '大客户代表', '南京迅丰汽车销售服务有限公司', '7月21日', '8000-15000元', '南京-玄武区', '汽车4S店/经销商', '20-99人', NULL, 'CC882215400J40631318307', '1.岗位职责<br>（1）开发公司目标客户(全国各级政府机关、事业单位、国企和央企等行业的大客户)<br>（2）建立并维护大客户和潜在客户的档案，并及时更新现有客户情况<br>（3）推广销售丰田考斯特/COASTER、金旅海狮等车型<br>（4）交互车辆和关怀大客户<br>（5）公司是政府及旅游采购协议供货定点单位，需接受出差性质<br>2.任职要求<br>（1）有客户销售经验优先考虑<br>（2）专科及以上学历<br>（3）主动性强，工作态度积极，良好的沟通能力和表达能力<br>（4）能接受出差，会开车优先', NULL, 'https://www.zhaopin.com/jobdetail/CC882215400J40631318307.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8992, '网络客服', '成都萌小玺文化传媒有限公司', '2025-07-27 02:01:08', '300-500元/天', '全国-None', '新媒体', '10000人以上', NULL, 'CCL1486511100J40863396415', '1.入职全程不收任何费用，没有任何押金<br>2.工作地点自由，只需一部手机耳机即可', '成都萌小玺文化传媒有限公司，成立于2024年，位于四川省成都市，是一家以从事文化艺术业为主的企业。成都萌小玺文化传媒有限公司，成立于2024年，位于四川省成都市，是一家以从事文化艺术业为主的企业。', 'https://www.zhaopin.com/jobdetail/CCL1486511100J40863396415.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8993, '项目招投标', '海江环保产业集团有限公司', '6月25日', '5000-8000元', '沧州-沧县', '工程施工,建筑设备安装', '100-299人', '未融资', 'CCL1295408950J40707602716', '岗位内容：<br>1. 协助上级完成市场部门的各项工作，制作商务标书<br>2. 负责信息的整理和归纳，以便更好地制作标书。<br>3. 协调外部资源，保证项目顺利进行并按时完成。<br>4. 收集和分析市场部信息及其他工作。<br>任职要求：<br>1. 具备较好的表述和沟通能力，能够快速适应快节奏的工作环境；<br>2. 具备独立思考和问题解决能力；<br>3. 具备良好的团队意识，能够积极配合其他部门的工作。', '海江环保产业集团隶属于北京海江控股集团有限公司，是北京海江控股集团的全资子公司，专注智能拆解、固废处理、再生资源、应急救援四大主业，拥有石化和工业废弃物“分-收-储-运-处-用”全流程循环解决方案。集团始终坚持科技研发创新，拥有一大批自主知识产权和核心技术，在全国首创5G全球远程操控技术与AR实景指挥平台，有效应用于工程项目施工。是国家高新技术企业、专精特新企业、绿色工厂企业。先后荣获中华全国总工会全国五一劳动奖、河北省总工会“模范职业之家”、河北省“科技创新工作先进单位”。 2020年，集团响应国家“双碳战略”，秉承“循环科技引领、创造价值再生”的经营理念，探索全行业绿色循环经济发展新模式投建海江集团循环经济产业基地。实现再生资源的绿色回收、资源化、再制造的全生命周期管理，以新质生产力，推动资源再生行业向着高科技、高效能、高质量发展。目前，集团已覆盖全国15个省、市、自治区，初步实现了以京津冀为中心，辐射长三角、粤港澳大湾区的战略布局，全面推进城市绿色经济发展。', 'https://www.zhaopin.com/jobdetail/CCL1295408950J40707602716.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8994, '律师', '河南霁安律师事务所', '7月11日', '1-2万', '郑州-管城回族区', '咨询服务', '20-99人', NULL, 'CC305775880J40508289215', '岗位职责：<br>l、担任民事案件代理人及刑事案件辩护人、代理人参加诉讼；<br>2、办理非诉讼法律事务，参加经济项目的谈判；<br>3、能够担任机关、大中型企事业、单位团体的法律顾问；<br>4、研究、解决律师业务活动中 遇到的疑难问题；<br>任职要求：<br>1、本科及以上学历，有专职律师执业证书，可独立承办案件。有经验者优先；<br>2、无不良执业记录，未受过任何行政处罚及行业纪律处分；具有踏实细致的工作作风、良好的沟通能力和团队合作精神。<br>工作环境：<br>1、良好的办公环境、A级写字楼、免费提供独立办公室、贵宾接待室。<br>律所位于郑州市管城回族区康宁街德威广场B座20楼，随时欢迎各位律师同仁到律所面谈。', '河南霁安律师事务所秉承“协作、高效、务实、求精”的核心价值观和“客户至上、最大程度维护客户权益”的职业理念，急客户之所急，为客户提供及时的、专业的、全面的、务实的法律及商务解决方案。河南霁安律师事务所是一家经过中华人民共和国司法部核准备案，经河南省司法厅批准设立的以刑事辩护、金融证券、公司业务、房地产开发、交通事故、工伤事故、医疗纠纷、婚姻家庭、争议解决为专业方向的大型综合性法律服务机构。霁安所秉承“协作、高效、务实、求精”的核心价值观和“客户至上、最大程度维护客户权益”的职业理念，急客户之所急，为客户提供及时的、专业的、全面的、务实的法律及商务解决方案。霁安所实行“专业化分工、规范化管理”的运作模式，建立了一套行之有效的内部合作机制，形成了成熟的团队服务模式，所内资源得到有效整合，使每位律师的专长都得以充分发挥，是一家极具合作和团队精神的律师事务所。霁安所采用先进科学的管理手段，建立了内部网络工作平台，构筑了案件综合管理机制，从根本上解决了案件管理问题，实现了对案件的冲突检索、接案、办案、归档等环节情况的管理和监督，是一家管理规范的律师事务所。同时，霁安所与多家律师事务所建立了长期、紧密的合作，为异地法律业务的开展提供及时有效的帮助，是一家颇具实力的律师事务所。本所为企业提供法律服务实行多层次、多组合、分工协作的团队工作模式。团队包括律师小组和律师团。对于规模较大、法律事务较多的企业以及较为复杂的案件，指定1-2位律师、1—2位律师助理组成律师小组团队，为客户提供法律服务。对于重大、复杂且工作量大、工作时间长的法律事务，以及大型公司的法律顾问，由一名合伙人和相关领域的专业律师组成律师团，提供“项目全程式法律服务”。河南霁安律师事务所办公电话：0371-55137616邮箱G13598082400@126.com网址：www.jianlvsuo.cn地址：郑州市康宁街普济路德威广场B座20层2002室', 'https://www.zhaopin.com/jobdetail/CC305775880J40508289215.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8995, '游戏运营', '南昌西湖万达广场商业管理有限公司', '2月17日', '4000-5000元·15薪', '南昌-西湖区', '物业管理,土地与公共设施管理', '20-99人', '未融资', 'CC370816730J40391910116', '1、经营秩序、设备设施、环境卫生、陈列布展等工作检查及督办整改，商户租金、物业费等费项收缴；<br>2、帮助商户改善经营、提高销售，实现稳场；完成促销活动谈判并跟进落实；<br>3、整理、分析商户经营状况及消费动态数据，定期对相关品类、品牌进行市场调研；<br>4、新商户进场手续办理、装修管控、交接验收工作；<br>5、协助营运主管处理消费投诉，跟进相应单位落实整改。<br>1、专业不限；<br>2、有企业营运管理相关工作经验优先；<br>3、有良好的沟通协调能力、责任心强。<br>', '万达商业管理有限公司系大连万达集团的核心子公司之一，也是中国最大的全国性连锁商业经营管理企业，拥有一支近万人的商业管理团队，主要负责经营管理万达商业地产公司开发的大型商业购物中心以及住宅、公寓和写字楼等多种类型物业项目。万达商业管理公司拥有丰富的商业资源，强大的运营管理能力，物业管理面积已超过1000万平方米，创造了连续多年租金收缴率超过99%的世界行业纪录，已成为万达商业地产的核心竞争优势之一。', 'https://www.zhaopin.com/jobdetail/CC370816730J40391910116.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8996, '运营助理/专员', '成都创想卓越科技有限公司', '7月25日', '6000-11000元', '成都-双流区', '广告/营销', '100-299人', '不需要融资', 'CC241926830J40697940506', '[职位描述]<br>可以接受小白，年龄要求25岁以上，未达年龄勿扰哦，工作环境好，团队氛围好，欢迎志同道合的伙伴加入<br>[福利待遇]<br>1、无责4000+奖金+项目提成(综合薪资在6K-8K)<br>2、购买社保，团队聚餐，周末双休<br>3、工作环境好，氛围轻松友善，晋升空间大，有不定时零食下午茶<br>[工作时间]<br>上午:9:30-12:00<br>下午:14:00-18:00午休两个小时，到点下班不加班<br>周末双休!周末双休！周末双休！！！ <br>【岗位内容] <br>1、负责视频简单拍摄剪辑制作发布账号、引流; <br>2、评论区意向咨询解答 <br>3、平台上收集意向数据，交接销售部门 <br>4、完成安排的日常工作 <br>[岗位要求] <br>1、经验不限，一对一带教 <br>2、责任心强，善于沟通 <br>3、有想法，有积极性 <br>职位亮点;早九晚六，近地铁口，氛围轻松，不加班，不销售', '公司自成立以来，都保证每位员工得到发展，我们注重培养员工的积极性和创造力，为他们提供广阔的职业前景，同时也鼓励员工之间互相学习，互相帮助，共同成长，因为团队的力量永远比一个人大。公司重点招聘新媒体运营，视频剪辑，销售等岗位，为广大客户提供更优质的服务，欢迎大家的加入~！', 'https://www.zhaopin.com/jobdetail/CC241926830J40697940506.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8997, '质检员', '博岳通信', '6月14日', '9000-11000元', '石家庄-裕华区', '运营商/增值服务,IT服务,通信/网络设备', '10000人以上', NULL, 'CC351377410J40745421801', '工作内容：管控抖音后台商品出现的问题。<br>公司楼下自带餐厅，公司中央空调，接受小白，有老员工手把手带。<br>1.薪资：试用期6000-8000+，转正后 8000+ <br>2.待遇：双休+五险+节假日休息+带薪年假+提供食宿。<br>3.福利：节假日礼品+免费电影院+每月定时团建。<br>4.工作要求：18-35周岁 中专及以上学历（最好大专即以上）<br>5.工作时间：8小时工作制不加班 到点直接走~', '河北博岳通信技术股份有限公司是一家大型的电子商务、呼叫中心运营及信息服务供应商，主要从事大数据建模/分析/应用、呼叫中心运营、运营商业务渠道、云服务、网络与信息服务业务。专注于为运营商、电子商务、金融、互联网企业和中小企业提供端到端的运营及服务解决方案。公司现有员工15000名，拥有运营坐席超过16000个，目前在北京、河北、四川、湖南、江西、辽宁、福建、宁夏、贵州、浙江、陕西等多个省市设有分公司和办事处。在大数据应用和呼叫中心运营领域，博岳股份与全国十几个省市通信运营商客户进行了全面合作,包括北京移动、中国移动咪咕公司音乐基地、咪咕动漫、四川移动、河北移动、河北铁通、宁夏移动、卓望信息、辽宁移动、江西移动、陕西移动、湖南电信、贵州联通、虚商迪信通；博岳股份与十几家互联网企业在运营和服务领域进行全方位的合作，包括小米科技、去哪网、多点生活、牛电科技、海选网运营支撑服务；博岳与互联网金融九鼎投资-借贷宝进行了全方位的战略合作，包括人人行客服、人人行催收、人人推和研发合作。博岳股份全面服务于通信运营商、金融、电商及互联网企业，服务用户超过5亿。在云服务领域，基于互联网模式建立了端到端的云客服平台，向互联网企业和各中小企业提供系统平台、数据库、数据建模及分析、物理场所、台席、人员及培训等端到端解决方案；为互联网企业和各中小企业提供快速、便捷、性价比高的优质服务。同时公司根据客户的需求，为客户设计完整的呼叫中心解决方案，并负责呼叫中心的建设、运营与维护，承接客户的对外联络、咨询、投诉、问卷调查、营销、客服等各项工作。作为河北省高科技企业，博岳股份于2016年3月份成功挂牌新三板。公司具备工信部颁发的“中华人民共和国增值电信业务经营许可证（全国呼叫中心业务许可证、河北省因特网信息服务业务许可证）”、“通信信息网络系统集成乙级”及“道路运输经营许可证”等资质，并且通过了ISO9001质量管理体系和ISO14001环境管理体系等权威认证。博岳股份立志发展成为业界一流的信息服务和网络服务提供商，博岳股份全面向世界优秀企业学习。博岳股份吸纳业界优秀人才，聚焦客户、聚焦业务，实现平台化和规模化的管理和运作，公司将秉承“以客户为中心、以贡献者为本、持续艰苦奋斗”的企业核心价值理念，我们相信通过全体员工的不懈努力和追求，一定能够为客户提供最好的解决方案和最优质的服务，并为客户实现商业成功!', 'https://www.zhaopin.com/jobdetail/CC351377410J40745421801.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8998, '总助/CEO助理/董事长助理', '四川蓉城蕾茗科技有限公司', '4月16日', '8000-10000元', '上海-徐汇区', '互联网,互联网', '1000-9999人', 'B轮', 'CCL1244220070J40763576612', '岗位职责: 老板以及老板娘日常生活安排 <br>-机票、酒店预订及会务安排 <br>完成交办的其他工作 任职要求:  <br>性格开朗外向，爱运动、健身者优先  <br>-形象良好，无不良嗜好，工作细致  <br>能接受周末及节假日办公（老板和老板娘来上海需要负责安排 ）  <br>教育背景:  <br>-本科及以上学历，品行端正，无不良记录', '四川蓉城蕾茗科技有限公司，是一家综合性服务外提供商、目前公司的主要经营范围是计算机软硬件的开发与销售；信息技术领域内的技术开发、技术服务、技术咨询、技术转让；代理电信业务、增值电信业务。', 'https://www.zhaopin.com/jobdetail/CCL1244220070J40763576612.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (8999, '储备经理人', '深圳市乐有家控股集团有限公司', '6月26日', '9000-17000元', '深圳-福田区', '房地产中介,房地产中介,咨询服务', '10000人以上', '未融资', 'CC381381910J40448964305', '岗位职责<br>1、协助负责门店团队架构，能根据管辖门店情况快速搭建团队架构，优化人员配置；<br>2、协助负责门店运营管理，指导并协助经纪人开展业务，监督门店日常业务运作情况，防范业务风险；<br>3、协助店长承接公司经营目标和考核要求，制定门店经营计划，并带领团队围绕经营计划和上级指导完成业绩目标；<br>4、协助店长及时收集与整理门店所在商圈的市场动态与竞争情况，研究应对策略并推进落实；<br>5、协助店长建立及维护良好的公共关系，及时处理突发事件；<br>6、转正之前从基础业务开始扎实专业知识，日常参与门店业务开展，双线培养，业务线和管理线同步进行培养带教，重点往门店店长方向培养。<br>任职资格<br>1、有考虑往管理层发展，专业、工作经验不限；<br>2、热爱销售和房地产行业，个人职业发展规划清晰，具有较强的事业心和责任感，有奋斗拼搏精神，愿意挑战自己；<br>3、具备较强的沟通表达能力、问题解决能力、组织协调能力和风险控制能力。<br>薪资待遇<br>1、薪酬福利<br>深圳转正前薪资面议，转正后薪资9000，广州转正薪资8000，高达40%的分红奖比例；<br>五险一金、带薪假期、节日大礼包、授课奖、创新奖、仁杰奖、员工互助金政策<br>丰富多彩的员工文体活动、国内精品游、国外豪华游<br>2、完善的培训及晋升机制<br>乐学堂APP移动化学习平台、每年投入2亿培训专项经费、3000多位培训讲师。一对一导师带教，专属高阶燎原跨越式发展储备人才计划。特种兵闯关考核、1000多个培训基地、1000多门丰富课程、精选配套考题20000+！<br>明确的职级晋升标准和后备培养机制，帮助下属晋级是考核上级的重要指标；职能、营销晋升通道畅通无阻，助您纵向、横向多维度发展！<br>3、团队特色<br>集团化企业，学习型组织，创业型团队，开放型文化，年轻化团队，职业化风貌，专业化协作，扁平化管理，阳光透明，简单真诚，优秀雇主欢迎您！', '乐有家控股集团为“以房地产经纪为龙头、金融和互联网为两翼”的大型企业集团，成立于2008年，总部位于深圳市，以“立足大深圳、密布珠三角、服务全中国”为发展战略，在深圳二手房市场占有率稳居行业第一，粤港澳大湾区多个城市市占率稳居行业前列。集团旗下拥有“乐有家”、“顺联担保”、“万顺通资产”、“家家顺物联科技”等优秀品牌，业务涵盖二手房买卖、房屋租赁、项目策划、新房代理、人工智能、资产管理、金融服务等领域，获得“中国十大品牌中介机构”、“全国优秀房地产经纪机构”、“年度最佳雇主”、“最值得信任的地产经纪品牌”、“广东省诚信企业”、“最具影响力雇主”等殊荣。集团始终坚持“真诚正义，先人后己”的核心价值观，积极推行“真服务、真保障”服务战略，为客户提供及时精准、专业可信、高效超值的房产交易全价值链服务。通过运用互联网、人工智能等新技术，打造线上线下一体化的E2E智能生态系统，致力于为客户打造房产交易全过程、全网络、全家庭生命周期的极致服务体验。集团以“立足大深圳、密布珠三角、连锁全中国”为发展战略，有效整合全国各项资源，实现“有家的地方就有乐有家”的宏伟愿景！', 'https://www.zhaopin.com/jobdetail/CC381381910J40448964305.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
INSERT INTO `t_2025_multi_area_job_info` VALUES (9000, '统计员', '广州市建设工程拆迁有限公司', '7月2日', '80-100元/天', '广州-海珠区', '工程施工,工程施工', '100-299人', '未融资', 'CC840989520J40790629213', '岗位职责：<br>1.协助处理综合部门事务，如人资、行政、文秘、宣传等交办工作<br>2.辅助进行档案整理工作；<br>3.其他交办的工作。<br>任职资格：<br>1.大学本科学历或在读学生，专业不限，实习期至少连续3个月及以上；<br>2.有良好的政治素质，组织纪律性强，有较强的责任意识和服务意识；<br>3.熟悉掌握和使用办公软件，工作细致严谨，有耐心；<br>5.工作时间:周一至周五，上午8:30-12:00；下午2:00-5:30。<br>职位福利：员工食堂（工作日提供早、午餐）', '广州市建设工程拆迁有限公司（简称“广州拆迁”）成立于2001年，是广州地区征收补偿、管线迁改市政前期领域的头部企业。公司2020年5月由住建系统划转到国资系统，股权、人事、资产等全部移交至广州珠江实业集团有限公司进行统一监管。广州拆迁经营业务涉及征收补偿、管线迁改、城市更新、绿色拆卸、前期摸查、土地收储、绿化迁移、建（构）筑物拆除、建筑施工及招投标代理等，具有甲级拆迁、市政公用工程施工总承包二级、房屋建筑工程施工总承包二级等资质，通过ISO9001,ISO14001,OHSA18001质量、环境、职业健康安全管理认证体系。自成立以来，公司立足主营主业，积极承接市政征收补偿、管线迁改及工程代建、建筑拆除、施工任务。在征收补偿和管线迁改方面，承接在建白云机场三期扩建、广交会展四期扩建、广州北站至白云机场快速通道、国际金融城东区建设、如意坊放射线、棠下琶洲及海珠湿地公园高压架空线下地迁改、车陂路北延线、康王路下穿流花湖隧道、广花一级公路地下综合管廊等省市级重点项目；圆满完成洲头咀隧道、金沙洲大桥及广州大桥拓宽、新电视塔南广场、西江引水、临江大道东延线、凤凰山隧道、广州南站地下空间以及广州多条轨道交通的征收补偿管线迁改等多项重点工程。在建筑拆除方面，实施了如广州花城玻璃厂、黄金围货运站、东圃粮库金融城东区路位景观带房屋等地上建（构）筑物拆除工作。在城市更新方面，承接了环市东商圈更新改造区意愿表决咨询、京溪广智片区改造意愿征询以及五羊新城改造前期摸查等旧改项目。在绿色拆卸方面，完成沥滘污水处理厂提标改造工程绿色拆卸试点项目以及法政路湛家大街地段公共绿地工程，在车陂路隧道、金融城地块、广建人才公寓等项目大力推广使用再生石粉、机制砂等绿色拆卸产品。二十年来，广州拆迁坚持“客户至上、多方满意、专业高效、持续改进”的管理方针，秉承“为客户创造价值，实现共赢”的经营宗旨，不断开拓进取，取得了良好的经济效益与社会效益。目前已形成“市政前期＋城市更新”双轮驱动的发展格局，创建管线迁改、动迁管理、城市更新咨询服务等三大优势品牌，拥有动迁、代建、咨询、施工等四大业务板块，在土地一级开发领域基本形成完整产业链。公司将继续秉承“为客户创造价值，让城市更新更美好”的企业使命，致力于打造成为“广州城建前期与城市更新综合服务平台领军者”。', 'https://www.zhaopin.com/jobdetail/CC840989520J40790629213.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77');
